(*** Native strict Vampire/Megalodon certificate v1 importer. ***)

open Syntax

type sexpr =
  | Atom of string
  | Str of string
  | List of sexpr list

exception Error of string

type source =
  | SourceAxiom of string
  | SourceConjecture of string
  | SourceNegatedConjecture of string
  | SourceDefinition of string
  | SourceSetReflexivity of string

type literal = Vampire_kernel_syntax.literal =
  | Pos of tm
  | Neg of tm

type clause = Vampire_kernel_syntax.clause

type sat_lit = int * bool

type sat_clause = sat_lit list

type sat_proof_step =
  | SatInput of int * sat_clause
  | SatRup of int * int list * sat_clause

type inequality_split = {
  split_name_parent : string;
  split_source : literal;
  split_name_literal : literal;
  split_replacement : literal;
}

type definition_rewrite = {
  definition_parent : string;
  definition_literal : int;
  target_literal : int;
  rewrite_position : int list;
  rewrite_from : tm;
  rewrite_to : tm;
}

type urr_trace = {
  urr_unit_parent : string;
  urr_selected : literal;
  urr_selected_substituted : literal;
  urr_unit_substituted : literal;
  urr_remaining : clause;
}

type rectify_renaming = {
  rectify_source : tm;
  rectify_subst : (string * tm) list;
  rectify_target : tm;
}

type avatar_dependency = {
  dependency_split_var : int;
  dependency_split_positive : bool;
  dependency_component : clause;
}

type checked_item =
  | CheckedClause of clause
  | CheckedFormula of tm
  | CheckedSatClauseRecord

type ennf_chain_item =
  | EnnfChainBinder of tp
  | EnnfChainPremise of tm

type matched_ennf_chain_item =
  | MatchedEnnfBinder of string * string * tp
  | MatchedEnnfPremise of tm * tm * string

type ennf_pair = {
  ennf_pair_path : string;
  ennf_pair_kind : string option;
  ennf_pair_source : tm;
  ennf_pair_target : tm;
}

type skolem_introduction = {
  skolem_intro_symbol : string;
  skolem_intro_replaced_var : string option;
  skolem_intro_declaration : string option;
}

type native_kernel_typed_variable = {
  native_kernel_variable_name : string;
  native_kernel_variable_type : tp;
}

type native_kernel_quantifier = {
  native_kernel_quantifier_kind : string;
  native_kernel_quantifier_variable : native_kernel_typed_variable;
}

type native_skolem_macro_edge = {
  native_skolem_macro_edge_index : int;
  native_skolem_macro_edge_parent_index : int option;
  native_skolem_macro_edge_unit : string option;
  native_skolem_macro_edge_binders : native_kernel_typed_variable list;
  native_skolem_macro_edge_formula : tm option;
  native_skolem_macro_edge_source : tm option;
  native_skolem_macro_edge_target : tm option;
  native_skolem_macro_edge_formula_quantifiers : native_kernel_quantifier list;
  native_skolem_macro_edge_source_quantifiers : native_kernel_quantifier list;
  native_skolem_macro_edge_target_quantifiers : native_kernel_quantifier list;
  native_skolem_macro_edge_formula_free_variables : native_kernel_typed_variable list;
  native_skolem_macro_edge_source_free_variables : native_kernel_typed_variable list;
  native_skolem_macro_edge_target_free_variables : native_kernel_typed_variable list;
  native_skolem_macro_edge_formula_children :
    Vampire_kernel_syntax.skolem_formula_child list;
  native_skolem_macro_edge_source_children :
    Vampire_kernel_syntax.skolem_formula_child list;
  native_skolem_macro_edge_target_children :
    Vampire_kernel_syntax.skolem_formula_child list;
  native_skolem_macro_edge_branch_contract :
    Vampire_kernel_syntax.skolem_branch_contract option;
}

type step =
  | Input of string * source * clause
  | FormulaInput of string * source * literal
  | FormulaTermInput of string * source * tm
  | FormulaTermCopy of string * string * tm
  | RectifyFormula of string * string * rectify_renaming list * tm
  | FoolAtomLift of string * tm * tm * string
  | FoolFormula of string * string * tm
  | EnnfFormula of string * string * tm option * ennf_pair list * tm
  | SkolemFormula of string * string * tm option * skolem_introduction list * (string * tm) list * tm
  | SkolemFormulaComputed of string * string * (string * tm) list
  | CnfFormulaClause of string * string * int * int option * clause
  | FormulaCopy of string * string * literal
  | FoolBool of string * string * literal
  | CnfLiteral of string * string * clause
  | PredicateDefinition of string * string * tm
  | PredicateDefinitionFold of string * string * string * tm
  | PredicateDefinitionFoldChain of string * string * string list * tm
  | DefinitionInput of string * clause
  | DefinitionRewriteChain of string * string * definition_rewrite list * clause
  | AvatarComponent of string * clause
  | AvatarDefinition of string * int * bool * clause
  | SplitDependency of string * string * avatar_dependency list * clause
  | AvatarSplit of string * string list * clause
  | AvatarContradiction of string * string list * clause
  | AvatarRefutation of string * string list * sat_clause list * sat_proof_step list option * clause
  | FoolExhaustiveness of string * clause
  | FoolDistinctness of string * clause
  | InequalityNameIntro of string * clause
  | InequalitySplit of string * string * inequality_split list * clause
  | Substitute of string * string * (string * tm) list * clause
  | Condensation of string * string * (string * tm) list * clause
  | UnitResultingResolution of string * string * urr_trace list * clause
  | Resolve of string * string * string * int * int * clause
  | SubsumptionResolution of string * string * string * literal * literal * (string * tm) list * clause
  | Factor of string * string * int * int * clause
  | EqualityResolution of string * string * int * clause
  | EqualityResolutionConstraints of string * string * int * literal * clause * clause
  | EqualityFactoring of string * string * int * int * (tm * tm) option * (string * tm) list * clause
  | EqualityFactoringConstraints of string * string * int * int * (tm * tm) option * (string * tm) list * clause * clause
  | TruthConflict of string * string * int * clause
  | EqualitySymmetry of string * string * int * clause
  | BoolSimplify of string * string * int * int list * tm * tm * clause
  | Paramodulate of string * string * string * int * int * int list * tm * tm * clause
  | Superposition of string * string * string * int * int * (string * tm) list * (string * tm) list * int list * tm * tm * clause
  | Contradiction of string * string

type certificate_metadata = {
  symbol_declarations : string list;
  step_propositions : (string * string) list;
  step_variable_sorts : (string * string list) list;
  step_extras : (string * string * string list) list;
}

type certificate = {
  problem : string option;
  metadata : certificate_metadata;
  steps : step list;
}

type core_native_proof = {
  core_native_proposition : tm;
  core_native_proof : pf;
  core_native_delta_table : (string, int * tm) Hashtbl.t;
  core_native_symbol_table : (string, int * tp) Hashtbl.t;
  core_native_steps : int;
  core_native_source_bindings : core_native_source_binding list;
  core_native_source_assumption_bindings : core_native_source_binding list;
  core_native_source_assumptions : int;
}

and core_native_source_binding = {
  core_native_source_step : string;
  core_native_certificate_source_kind : string;
  core_native_tptp_name : string;
  core_native_source_name : string;
  core_native_source_map_kind : string;
  core_native_source_hash : string;
  core_native_source_proposition : tm;
}

type source_map_entry = {
  source_map_kind : string;
  source_map_tptp_name : string;
  source_map_source_name : string;
  source_map_hash : string;
  source_map_decl_hash : string option;
  source_map_decl_formula : string option;
}

type source_origin = {
  source_origin_file : string;
  source_origin_line : int option;
  source_origin_char : int option;
  source_origin_kind : string;
}

type source_obligation_audit = {
  source_obligations_total : int;
  source_obligations_formula_checked : int;
  source_obligations_formula_unsupported : int;
  source_obligations_formula_missing : int;
  source_obligations_equality_checked : int;
  source_obligations_set_reflexivity_checked : int;
  source_obligations_true_checked : int;
}

let error msg = raise (Error msg)

let is_space = function
  | ' ' | '\n' | '\r' | '\t' -> true
  | _ -> false

let is_delim = function
  | '(' | ')' | '"' -> true
  | c -> is_space c

let parse_sexpr text =
  let len = String.length text in
  let rec skip i =
    if i < len && is_space text.[i] then skip (i + 1) else i
  in
  let rec parse_string buf i =
    if i >= len then error "unterminated string";
    match text.[i] with
    | '"' -> (Str (Buffer.contents buf), i + 1)
    | '\\' when i + 1 < len ->
        let c =
          match text.[i + 1] with
          | 'n' -> '\n'
          | 'r' -> '\r'
          | 't' -> '\t'
          | c -> c
        in
        Buffer.add_char buf c;
        parse_string buf (i + 2)
    | c ->
        Buffer.add_char buf c;
        parse_string buf (i + 1)
  and parse_atom start i =
    if i >= len || is_delim text.[i] then
      if i = start then error "expected atom" else (Atom (String.sub text start (i - start)), i)
    else parse_atom start (i + 1)
  and parse_list acc i =
    let i = skip i in
    if i >= len then error "unterminated list";
    if text.[i] = ')' then (List (List.rev acc), i + 1)
    else
      let item, j = parse_one i in
      parse_list (item :: acc) j
  and parse_one i =
    let i = skip i in
    if i >= len then error "expected S-expression";
    match text.[i] with
    | '(' -> parse_list [] (i + 1)
    | ')' -> error "unexpected ')'"
    | '"' -> parse_string (Buffer.create 16) (i + 1)
    | _ -> parse_atom i i
  in
  let parsed, i = parse_one 0 in
  if skip i <> len then error "trailing input after S-expression";
  parsed

let atom = function
  | Atom x -> x
  | Str x -> x
  | List _ -> error "expected atom"

let int_atom sexpr =
  try int_of_string (atom sexpr) with Failure _ -> error "expected integer"

let rec parse_tp = function
  | List [Atom "PROP"] -> Prop
  | List [Atom "SET"] -> Set
  | List [Atom "TPVAR"; n] -> TpVar (int_atom n)
  | List [Atom "AR"; a; b] -> Ar (parse_tp a, parse_tp b)
  | _ -> error "expected Megalodon type S-expression"

let subst_named_tm name tm =
  let rec subst depth = function
    | TmH h when h = name -> DB depth
    | TpAp (m, a) -> TpAp (subst depth m, a)
    | Ap (TmH "vLAM", body) -> Ap (TmH "vLAM", subst depth body)
    | Ap (m, n) -> Ap (subst depth m, subst depth n)
    | Lam (tp, body) -> Lam (tp, subst (depth + 1) body)
    | Imp (m, n) -> Imp (subst depth m, subst depth n)
    | All (tp, body) -> All (tp, subst (depth + 1) body)
    | tm -> tm
  in
  subst 0 tm

let rec vampire_db_name_tm = function
  | DB i -> TmH ("db" ^ string_of_int i)
  | TpAp (m, a) -> TpAp (vampire_db_name_tm m, a)
  | Ap (m, n) -> Ap (vampire_db_name_tm m, vampire_db_name_tm n)
  | Lam (tp, body) -> Lam (tp, vampire_db_name_tm body)
  | Imp (m, n) -> Imp (vampire_db_name_tm m, vampire_db_name_tm n)
  | All (tp, body) -> All (tp, vampire_db_name_tm body)
  | tm -> tm

let subst_vlam_named_tm name tm =
  let rec subst depth = function
    | TmH h when h = name -> TmH ("db" ^ string_of_int depth)
    | TpAp (m, a) -> TpAp (subst depth m, a)
    | Ap (TmH "vLAM", body) -> Ap (TmH "vLAM", subst (depth + 1) body)
    | Ap (m, n) -> Ap (subst depth m, subst depth n)
    | Lam (tp, body) -> Lam (tp, subst depth body)
    | Imp (m, n) -> Imp (subst depth m, subst depth n)
    | All (tp, body) -> All (tp, subst depth body)
    | tm -> tm
  in
  subst 0 tm

let vampire_db_index_tm tm =
  let db_name_index name =
    if String.length name > 2 && String.sub name 0 2 = "db" then
      try Some (int_of_string (String.sub name 2 (String.length name - 2)))
      with Failure _ -> None
    else None
  in
  let rec convert depth = function
    | TmH name ->
        begin match db_name_index name with
        | Some index -> DB (depth + index)
        | None -> TmH name
        end
    | DB index when index >= depth -> DB (index + 1)
    | TpAp (m, a) -> TpAp (convert depth m, a)
    | Ap (m, n) -> Ap (convert depth m, convert depth n)
    | Lam (tp, body) -> Lam (tp, convert (depth + 1) body)
    | Imp (m, n) -> Imp (convert depth m, convert depth n)
    | All (tp, body) -> All (tp, convert (depth + 1) body)
    | tm -> tm
  in
  convert 0 tm

let rec parse_tm = function
  | List [Atom "DB"; n] -> DB (int_atom n)
  | List [Atom "TMH"; h] -> TmH (atom h)
  | List [Atom "PRIM"; n] -> Prim (int_atom n)
  | List [Atom "TPAP"; m; a] -> TpAp (parse_tm m, parse_tp a)
  | List [Atom "AP"; List [Atom "TMH"; exists_head]; List [Atom binder; name; a; m]]
      when atom exists_head = "vampire_exists_prop"
           && (binder = "LAMV" || binder = "VLAMV") ->
      let tp = parse_tp a in
      Ap (TmH "vampire_exists_prop", Lam (tp, subst_named_tm (atom name) (parse_tm m)))
  | List [Atom "AP"; m; n] -> Ap (parse_tm m, parse_tm n)
  | List [Atom "LAM"; a; m] -> Lam (parse_tp a, parse_tm m)
  | List [Atom "LAMV"; name; a; m]
  | List [Atom "VLAMV"; name; a; m] ->
      let _tp = parse_tp a in
      Ap (TmH "vLAM", subst_vlam_named_tm (atom name) (parse_tm m))
  | List [Atom "IMP"; m; n] -> Imp (parse_tm m, parse_tm n)
  | List [Atom "ALL"; a; m] -> All (parse_tp a, parse_tm m)
  | List [Atom "ALLV"; name; a; m] ->
      All (parse_tp a, subst_named_tm (atom name) (parse_tm m))
  | _ -> error "expected Megalodon term S-expression"

let parse_source = function
  | List [Atom "source"; Atom "axiom"; name] -> SourceAxiom (atom name)
  | List [Atom "source"; Atom "conjecture"; name] -> SourceConjecture (atom name)
  | List [Atom "source"; Atom "negated_conjecture"; name] -> SourceNegatedConjecture (atom name)
  | List [Atom "source"; Atom "definition"; name] -> SourceDefinition (atom name)
  | List [Atom "source"; Atom "set_reflexivity"; name] -> SourceSetReflexivity (atom name)
  | List (Atom "source" :: Atom bad :: _) when String.length bad >= 8 && String.sub bad 0 8 = "vampire_" ->
      error ("strict certificate v1 rejects source " ^ bad)
  | List (Atom "source" :: _) -> error "unsupported certificate source"
  | _ -> error "expected certificate source"

let parse_literal = function
  | List [Atom "pos"; tm] -> Pos (parse_tm tm)
  | List [Atom "neg"; tm] -> Neg (parse_tm tm)
  | _ -> error "expected clause literal"

let parse_clause = function
  | List (Atom "clause" :: literals) -> List.map parse_literal literals
  | _ -> error "expected clause"

let parse_parents = function
  | List [Atom "parents"; a; b] -> (atom a, atom b)
  | _ -> error "expected two parents"

let bool_atom = function
  | Atom "true" -> true
  | Atom "false" -> false
  | _ -> error "expected Boolean atom"

let parse_sat_lit = function
  | List [Atom "lit"; var; polarity] -> (int_atom var, bool_atom polarity)
  | _ -> error "expected SAT literal"

let parse_sat_clause = function
  | List (Atom "sat_clause" :: literals) -> List.map parse_sat_lit literals
  | _ -> error "expected SAT clause"

let parse_sat_clauses = function
  | List (Atom "sat_clauses" :: clauses) -> List.map parse_sat_clause clauses
  | _ -> error "expected SAT clause list"

let parse_parent_id_list = function
  | List (Atom "parents" :: parents) -> List.map atom parents
  | _ -> error "expected parent id list"

let parse_sat_parents = function
  | List (Atom "parents" :: parents) -> List.map int_atom parents
  | _ -> error "expected SAT parent list"

let parse_sat_result = function
  | List [Atom "result"; clause] -> parse_sat_clause clause
  | _ -> error "expected SAT result"

let parse_sat_proof_step = function
  | List [Atom "sat_input"; id; clause] ->
      SatInput (int_atom id, parse_sat_clause clause)
  | List [Atom "sat_rup"; id; parents; result] ->
      SatRup (int_atom id, parse_sat_parents parents, parse_sat_result result)
  | _ -> error "expected SAT proof step"

let parse_sat_proof = function
  | List (Atom "sat_proof" :: steps) -> List.map parse_sat_proof_step steps
  | _ -> error "expected SAT proof"

let parse_pivot = function
  | List [Atom "pivot"; a; b] -> (int_atom a, int_atom b)
  | _ -> error "expected pivot"

let parse_parent = function
  | List [Atom "parent"; parent] -> atom parent
  | _ -> error "expected parent"

let parse_owner = function
  | List [Atom "owner"; owner] -> atom owner
  | _ -> error "expected owner"

let parse_symbol = function
  | List [Atom "symbol"; symbol] -> atom symbol
  | _ -> error "expected symbol"

let parse_named_parent name = function
  | List [Atom label; parent] when label = name -> atom parent
  | _ -> error ("expected " ^ name ^ " parent")

let parse_named_literal name = function
  | List [Atom label; literal] when label = name -> parse_literal literal
  | _ -> error ("expected " ^ name ^ " literal")

let parse_named_parents name = function
  | List (Atom label :: parents) when label = name -> List.map atom parents
  | _ -> error ("expected " ^ name ^ " parent list")

let parse_indexed_parent name = function
  | List [Atom label; parent; index] when label = name -> (atom parent, int_atom index)
  | _ -> error ("expected " ^ name ^ " parent and literal index")

let parse_literal_index = function
  | List [Atom "literal"; index] -> int_atom index
  | _ -> error "expected literal index"

let parse_literal_pair = function
  | List [Atom "literals"; left; right] -> (int_atom left, int_atom right)
  | _ -> error "expected literal-index pair"

let parse_position = function
  | List (Atom "position" :: indices) -> List.map int_atom indices
  | _ -> error "expected position"

let parse_tm_field name = function
  | List [Atom label; tm] when label = name -> parse_tm tm
  | _ -> error ("expected " ^ name ^ " term")

let parse_substitution = function
  | List (Atom "subst" :: entries) ->
      let rec parse seen = function
        | [] -> []
        | List [name; tm] :: rest ->
            let name = atom name in
            if name = "" then error "substitution binding has an empty variable name";
            if List.mem name seen then
              error ("duplicate substitution binding for " ^ name);
            (name, parse_tm tm) :: parse (name :: seen) rest
        | _ -> error "expected substitution binding"
      in
      parse [] entries
  | _ -> error "expected substitution"

let parse_result = function
  | List [Atom "result"; clause] -> parse_clause clause
  | _ -> error "expected result clause"

let parse_inequality_split = function
  | List [Atom "split"; name_parent; source; name_literal; replacement] ->
      {
        split_name_parent = parse_named_parent "name_parent" name_parent;
        split_source = parse_named_literal "source" source;
        split_name_literal = parse_named_literal "name_literal" name_literal;
        split_replacement = parse_named_literal "replacement" replacement;
      }
  | _ -> error "expected inequality split item"

let parse_inequality_splits = function
  | List (Atom "splits" :: splits) -> List.map parse_inequality_split splits
  | _ -> error "expected inequality split list"

let parse_definition_rewrite = function
  | List [Atom "rewrite"; definition; target_literal; position; from_tm; to_tm] ->
      let definition_parent, definition_literal = parse_indexed_parent "definition" definition in
      let target_literal =
        match target_literal with
        | List [Atom "target_literal"; index] -> int_atom index
        | _ -> error "expected target literal index"
      in
      {
        definition_parent;
        definition_literal;
        target_literal;
        rewrite_position = parse_position position;
        rewrite_from = parse_tm_field "from" from_tm;
        rewrite_to = parse_tm_field "to" to_tm;
      }
  | _ -> error "expected definition rewrite"

let parse_definition_rewrites = function
  | List (Atom "rewrites" :: rewrites) -> List.map parse_definition_rewrite rewrites
  | _ -> error "expected definition rewrite list"

let parse_literal_result = function
  | List [Atom "result"; literal] -> parse_literal literal
  | _ -> error "expected result literal"

let parse_formula_result = function
  | List [Atom "result"; List [Atom "formula"; tm]] -> parse_tm tm
  | _ -> error "expected result formula"

let parse_formula_field name = function
  | List [Atom label; List [Atom "formula"; tm]] when label = name -> parse_tm tm
  | _ -> error ("expected " ^ name ^ " formula")

let parse_path_field = function
  | List [Atom "path"; Str value] -> value
  | List [Atom "path"; Atom value] -> value
  | _ -> error "expected path"

let parse_ennf_pair = function
  | List [Atom "pair"; path; source; target] ->
      {
        ennf_pair_path = parse_path_field path;
        ennf_pair_kind = None;
        ennf_pair_source = parse_formula_field "source" source;
        ennf_pair_target = parse_formula_field "target" target;
      }
  | List [Atom "pair"; path; kind; source; target] ->
      let kind =
        match kind with
        | List [Atom "kind"; Str value] -> value
        | List [Atom "kind"; Atom value] -> value
        | _ -> error "expected ennf pair kind"
      in
      {
        ennf_pair_path = parse_path_field path;
        ennf_pair_kind = Some kind;
        ennf_pair_source = parse_formula_field "source" source;
        ennf_pair_target = parse_formula_field "target" target;
      }
  | _ -> error "expected ennf pair"

let parse_ennf_pairs = function
  | List (Atom "pairs" :: pairs) -> List.map parse_ennf_pair pairs
  | _ -> error "expected ennf pairs"

let parse_skolem_intro_symbol = function
  | List [Atom "name"; name] -> atom name
  | _ -> error "expected skolem introduced symbol name"

let parse_skolem_intro_replaced_var = function
  | List [Atom "replaced_var"; name] -> Some (atom name)
  | List [Atom "replaced_var"] -> None
  | _ -> error "expected skolem introduced replaced_var"

let parse_skolem_intro_declaration = function
  | List [Atom "declaration"; declaration] -> Some (atom declaration)
  | List [Atom "declaration"] -> None
  | _ -> error "expected skolem introduced declaration"

let parse_skolem_introduction = function
  | List (Atom "symbol" :: fields) ->
      let symbol = ref None in
      let replaced_var = ref None in
      let declaration = ref None in
      List.iter
        (function
          | List (Atom "name" :: _) as field ->
              symbol := Some (parse_skolem_intro_symbol field)
          | List (Atom "replaced_var" :: _) as field ->
              replaced_var := parse_skolem_intro_replaced_var field
          | List (Atom "declaration" :: _) as field ->
              declaration := parse_skolem_intro_declaration field
          | _ -> error "unexpected skolem introduced symbol field")
        fields;
      begin match !symbol with
      | Some skolem_intro_symbol ->
          {
            skolem_intro_symbol;
            skolem_intro_replaced_var = !replaced_var;
            skolem_intro_declaration = !declaration;
          }
      | None -> error "skolem introduced symbol missing name"
      end
  | _ -> error "expected skolem introduced symbol"

let parse_skolem_introductions = function
  | List (Atom "introduced" :: introductions) ->
      List.map parse_skolem_introduction introductions
  | _ -> error "expected skolem introduced symbol list"

let parse_rectify_renaming = function
  | List [Atom "renaming"; source; subst; target] ->
      {
        rectify_source = parse_formula_field "source" source;
        rectify_subst = parse_substitution subst;
        rectify_target = parse_formula_field "target" target;
      }
  | _ -> error "expected rectify renaming"

let parse_rectify_renamings = function
  | List (Atom "renamings" :: renamings) ->
      List.map parse_rectify_renaming renamings
  | _ -> error "expected rectify renamings"

let parse_formula = function
  | List [Atom "formula"; tm] -> parse_tm tm
  | _ -> error "expected formula"

let parse_index = function
  | List [Atom "index"; index] -> int_atom index
  | _ -> error "expected index"

let bool_atom = function
  | Atom "true" -> true
  | Atom "false" -> false
  | Str "true" -> true
  | Str "false" -> false
  | _ -> error "expected boolean"

let parse_split = function
  | List [Atom "split"; var; positive] -> (int_atom var, bool_atom positive)
  | _ -> error "expected split"

let parse_avatar_dependency = function
  | List [Atom "dependency"; var; positive; List [Atom "component"; clause]] ->
      {
        dependency_split_var = int_atom var;
        dependency_split_positive = bool_atom positive;
        dependency_component = parse_clause clause;
      }
  | _ -> error "expected AVATAR dependency"

let parse_avatar_dependencies = function
  | List (Atom "dependencies" :: dependencies) ->
      List.map parse_avatar_dependency dependencies
  | _ -> error "expected AVATAR dependency list"

let parse_named_index name = function
  | List [Atom label; index] when label = name -> int_atom index
  | _ -> error ("expected " ^ name ^ " index")

let parse_constraints = function
  | List (Atom "constraints" :: constraints) -> List.map parse_literal constraints
  | _ -> error "expected constraints"

let parse_selected = function
  | List [Atom "selected"; literal] -> parse_literal literal
  | _ -> error "expected selected literal"

let parse_selected_substituted = function
  | List [Atom "selected_substituted"; literal] -> parse_literal literal
  | _ -> error "expected selected_substituted literal"

let parse_unit_substituted = function
  | List [Atom "unit_substituted"; literal] -> parse_literal literal
  | _ -> error "expected unit_substituted literal"

let parse_remaining = function
  | List [Atom "remaining"; clause] -> parse_clause clause
  | _ -> error "expected remaining clause"

let parse_urr_trace_step = function
  | List [Atom "step"; unit; selected; selected_substituted; unit_substituted; remaining] ->
      {
        urr_unit_parent = parse_named_parent "unit" unit;
        urr_selected = parse_selected selected;
        urr_selected_substituted = parse_selected_substituted selected_substituted;
        urr_unit_substituted = parse_unit_substituted unit_substituted;
        urr_remaining = parse_remaining remaining;
      }
  | _ -> error "expected unit_resulting_resolution trace step"

let parse_urr_trace = function
  | List (Atom "trace" :: steps) -> List.map parse_urr_trace_step steps
  | _ -> error "expected unit_resulting_resolution trace"

let parse_step = function
  | List [Atom "input"; id; source; clause] ->
      Input (atom id, parse_source source, parse_clause clause)
  | List [Atom "formula_input"; id; source; literal] ->
      FormulaInput (atom id, parse_source source, parse_literal literal)
  | List [Atom "formula_term_input"; id; source; formula] ->
      FormulaTermInput (atom id, parse_source source, parse_formula formula)
  | List [Atom "formula_term_copy"; id; parent; result] ->
      FormulaTermCopy (atom id, parse_parent parent, parse_formula_result result)
  | List [Atom "rectify_formula"; id; parent; result] ->
      RectifyFormula (atom id, parse_parent parent, [], parse_formula_result result)
  | List [Atom "rectify_formula"; id; parent; renamings; result] ->
      RectifyFormula
        (atom id, parse_parent parent, parse_rectify_renamings renamings, parse_formula_result result)
  | List [Atom "fool_atom_lift"; id; source; target; path] ->
      let path =
        match path with
        | List [Atom "path"; Str value] -> value
        | List [Atom "path"; Atom value] -> value
        | _ -> error "expected fool_atom_lift path"
      in
      FoolAtomLift
        (atom id, parse_formula_field "source" source, parse_formula_field "target" target, path)
  | List [Atom "fool_formula"; id; parent; result] ->
      FoolFormula (atom id, parse_parent parent, parse_formula_result result)
  | List [Atom "ennf_formula"; id; parent; result] ->
      EnnfFormula (atom id, parse_parent parent, None, [], parse_formula_result result)
  | List [Atom "ennf_formula"; id; parent; source; pairs; result] ->
      EnnfFormula
        (atom id,
         parse_parent parent,
         Some (parse_formula_field "source" source),
         parse_ennf_pairs pairs,
         parse_formula_result result)
  | List [Atom "skolem_formula"; id; parent; subst; result] ->
      SkolemFormula (atom id, parse_parent parent, None, [], parse_substitution subst, parse_formula_result result)
  | List [Atom "skolem_formula"; id; parent; source; subst; introduced; result] ->
      SkolemFormula
        (atom id,
         parse_parent parent,
         Some (parse_formula_field "source" source),
         parse_skolem_introductions introduced,
         parse_substitution subst,
         parse_formula_result result)
  | List [Atom "skolem_formula_computed"; id; parent; subst] ->
      SkolemFormulaComputed (atom id, parse_parent parent, parse_substitution subst)
  | List [Atom "cnf_formula_clause"; id; parent; index; result] ->
      CnfFormulaClause (atom id, parse_parent parent, parse_index index, None, parse_result result)
  | List [Atom "cnf_formula_clause"; id; parent; index; count; result] ->
      let count =
        match count with
        | List [Atom "count"; Atom n] ->
            begin try Some (int_of_string n)
            with Failure _ -> error "expected cnf_formula_clause count integer"
            end
        | _ -> error "expected cnf_formula_clause count"
      in
      CnfFormulaClause (atom id, parse_parent parent, parse_index index, count, parse_result result)
  | List [Atom "formula_copy"; id; parent; result] ->
      FormulaCopy (atom id, parse_parent parent, parse_literal_result result)
  | List [Atom "fool_bool"; id; parent; result] ->
      FoolBool (atom id, parse_parent parent, parse_literal_result result)
  | List [Atom "cnf_literal"; id; parent; result] ->
      CnfLiteral (atom id, parse_parent parent, parse_result result)
  | List [Atom "predicate_definition"; id; symbol; result] ->
      PredicateDefinition (atom id, parse_symbol symbol, parse_formula_result result)
  | List [Atom "predicate_definition_fold"; id; source; definition; result] ->
      PredicateDefinitionFold
        (atom id, parse_named_parent "source" source, parse_named_parent "definition" definition, parse_formula_result result)
  | List [Atom "predicate_definition_fold_chain"; id; source; definitions; result] ->
      PredicateDefinitionFoldChain
        (atom id, parse_named_parent "source" source, parse_named_parents "definitions" definitions, parse_formula_result result)
  | List [Atom "definition_input"; id; result] ->
      DefinitionInput (atom id, parse_result result)
  | List [Atom "definition_rewrite_chain"; id; parent; rewrites; result] ->
      DefinitionRewriteChain (atom id, parse_parent parent, parse_definition_rewrites rewrites, parse_result result)
  | List [Atom "avatar_component"; id; result] ->
      AvatarComponent (atom id, parse_result result)
  | List [Atom "avatar_definition"; id; split; result] ->
      let split_var, split_positive = parse_split split in
      AvatarDefinition (atom id, split_var, split_positive, parse_result result)
  | List [Atom "split_dependency"; id; owner; dependencies; result] ->
      SplitDependency
        (atom id, parse_owner owner, parse_avatar_dependencies dependencies, parse_result result)
  | List [Atom "avatar_split"; id; parents; result] ->
      AvatarSplit (atom id, parse_parent_id_list parents, parse_result result)
  | List [Atom "avatar_contradiction"; id; parents; result] ->
      AvatarContradiction (atom id, parse_parent_id_list parents, parse_result result)
  | List (Atom "avatar_refutation" :: id :: fields) ->
      begin match fields with
      | [List (Atom "sat_clauses" :: _) as sat_clauses; result] ->
          AvatarRefutation
            (atom id, [], parse_sat_clauses sat_clauses, None, parse_result result)
      | [List (Atom "sat_clauses" :: _) as sat_clauses;
         List (Atom "sat_proof" :: _) as sat_proof;
         result] ->
          AvatarRefutation
            (atom id, [], parse_sat_clauses sat_clauses, Some (parse_sat_proof sat_proof), parse_result result)
      | [List (Atom "parents" :: _) as parents;
         List (Atom "sat_clauses" :: _) as sat_clauses;
         result] ->
          AvatarRefutation
            (atom id, parse_parent_id_list parents, parse_sat_clauses sat_clauses, None, parse_result result)
      | [List (Atom "parents" :: _) as parents;
         List (Atom "sat_clauses" :: _) as sat_clauses;
         List (Atom "sat_proof" :: _) as sat_proof;
         result] ->
          AvatarRefutation
            (atom id, parse_parent_id_list parents, parse_sat_clauses sat_clauses, Some (parse_sat_proof sat_proof), parse_result result)
      | _ -> error "malformed avatar_refutation step"
      end
  | List [Atom "fool_exhaustiveness"; id; result] ->
      FoolExhaustiveness (atom id, parse_result result)
  | List [Atom "fool_distinctness"; id; result] ->
      FoolDistinctness (atom id, parse_result result)
  | List [Atom "inequality_name_intro"; id; result] ->
      InequalityNameIntro (atom id, parse_result result)
  | List [Atom "inequality_split"; id; source; splits; result] ->
      InequalitySplit (atom id, parse_named_parent "source" source, parse_inequality_splits splits, parse_result result)
  | List [Atom "substitute"; id; parent; subst; result] ->
      Substitute (atom id, parse_parent parent, parse_substitution subst, parse_result result)
  | List [Atom "condensation"; id; parent; subst; result] ->
      Condensation (atom id, parse_parent parent, parse_substitution subst, parse_result result)
  | List [Atom "unit_resulting_resolution"; id; main; trace; result] ->
      UnitResultingResolution (atom id, parse_named_parent "main" main, parse_urr_trace trace, parse_result result)
  | List [Atom "resolve"; id; parents; pivot; result] ->
      let a, b = parse_parents parents in
      let i, j = parse_pivot pivot in
      Resolve (atom id, a, b, i, j, parse_result result)
  | List [Atom "subsumption_resolution"; id; parents; selected; side_pivot; side_subst; result] ->
      let a, b = parse_parents parents in
      SubsumptionResolution (
        atom id,
        a,
        b,
        parse_named_literal "selected" selected,
        parse_named_literal "side_pivot" side_pivot,
        parse_substitution side_subst,
        parse_result result)
  | List [Atom "factor"; id; parent; literals; result] ->
      let i, j = parse_literal_pair literals in
      Factor (atom id, parse_parent parent, i, j, parse_result result)
  | List [Atom "equality_resolution"; id; parent; literal; result] ->
      EqualityResolution (atom id, parse_parent parent, parse_literal_index literal, parse_result result)
  | List [Atom "equality_resolution_constraints"; id; parent; literal; selected; constraints; result] ->
      EqualityResolutionConstraints (
        atom id,
        parse_parent parent,
        parse_literal_index literal,
        parse_selected selected,
        parse_constraints constraints,
        parse_result result)
  | List [Atom "equality_factoring"; id; parent; selected; other; subst; result] ->
      EqualityFactoring (
        atom id,
        parse_parent parent,
        parse_named_index "selected" selected,
        parse_named_index "other" other,
        None,
        parse_substitution subst,
        parse_result result)
  | List [Atom "equality_factoring"; id; parent; selected; other; selected_lhs; other_rhs; subst; result] ->
      EqualityFactoring (
        atom id,
        parse_parent parent,
        parse_named_index "selected" selected,
        parse_named_index "other" other,
        Some (parse_tm_field "selected_lhs" selected_lhs, parse_tm_field "other_rhs" other_rhs),
        parse_substitution subst,
        parse_result result)
  | List [Atom "equality_factoring_constraints"; id; parent; selected; other; subst; constraints; result] ->
      EqualityFactoringConstraints (
        atom id,
        parse_parent parent,
        parse_named_index "selected" selected,
        parse_named_index "other" other,
        None,
        parse_substitution subst,
        parse_constraints constraints,
        parse_result result)
  | List [Atom "equality_factoring_constraints"; id; parent; selected; other; selected_lhs; other_rhs; subst; constraints; result] ->
      EqualityFactoringConstraints (
        atom id,
        parse_parent parent,
        parse_named_index "selected" selected,
        parse_named_index "other" other,
        Some (parse_tm_field "selected_lhs" selected_lhs, parse_tm_field "other_rhs" other_rhs),
        parse_substitution subst,
        parse_constraints constraints,
        parse_result result)
  | List [Atom "truth_conflict"; id; parent; literal; result] ->
      TruthConflict (atom id, parse_parent parent, parse_literal_index literal, parse_result result)
  | List [Atom "equality_symmetry"; id; parent; literal; result] ->
      EqualitySymmetry (atom id, parse_parent parent, parse_literal_index literal, parse_result result)
  | List [Atom "bool_simplify"; id; parent; literal; position; from_tm; to_tm; result] ->
      BoolSimplify (
        atom id,
        parse_parent parent,
        parse_literal_index literal,
        parse_position position,
        parse_tm_field "from" from_tm,
        parse_tm_field "to" to_tm,
        parse_result result)
  | List [Atom "paramodulate"; id; equality; target; position; from_tm; to_tm; result] ->
      let equality_parent, equality_index = parse_indexed_parent "equality" equality in
      let target_parent, target_index = parse_indexed_parent "target" target in
      Paramodulate (
        atom id,
        equality_parent,
        target_parent,
        equality_index,
        target_index,
        parse_position position,
        parse_tm_field "from" from_tm,
        parse_tm_field "to" to_tm,
        parse_result result)
  | List [Atom "superposition"; id; target; equality; target_subst; equality_subst; position; from_tm; to_tm; result] ->
      let target_parent, target_index = parse_indexed_parent "target" target in
      let equality_parent, equality_index = parse_indexed_parent "equality" equality in
      Superposition (
        atom id,
        target_parent,
        equality_parent,
        target_index,
        equality_index,
        parse_substitution target_subst,
        parse_substitution equality_subst,
        parse_position position,
        parse_tm_field "from" from_tm,
        parse_tm_field "to" to_tm,
        parse_result result)
  | List [Atom "contradiction"; id; parent] ->
      Contradiction (atom id, atom parent)
  | List (Atom rule :: _) ->
      error ("strict certificate v1 importer does not support rule " ^ rule)
  | _ -> error "expected certificate step"

let step_id = function
  | Input (id, _, _) -> id
  | FormulaInput (id, _, _) -> id
  | FormulaTermInput (id, _, _) -> id
  | FormulaTermCopy (id, _, _) -> id
  | RectifyFormula (id, _, _, _) -> id
  | FoolAtomLift (id, _, _, _) -> id
  | FoolFormula (id, _, _) -> id
  | EnnfFormula (id, _, _, _, _) -> id
  | SkolemFormula (id, _, _, _, _, _) -> id
  | SkolemFormulaComputed (id, _, _) -> id
  | CnfFormulaClause (id, _, _, _, _) -> id
  | FormulaCopy (id, _, _) -> id
  | FoolBool (id, _, _) -> id
  | CnfLiteral (id, _, _) -> id
  | PredicateDefinition (id, _, _) -> id
  | PredicateDefinitionFold (id, _, _, _) -> id
  | PredicateDefinitionFoldChain (id, _, _, _) -> id
  | DefinitionInput (id, _) -> id
  | DefinitionRewriteChain (id, _, _, _) -> id
  | AvatarComponent (id, _) -> id
  | AvatarDefinition (id, _, _, _) -> id
  | SplitDependency (id, _, _, _) -> id
  | AvatarSplit (id, _, _) -> id
  | AvatarContradiction (id, _, _) -> id
  | AvatarRefutation (id, _, _, _, _) -> id
  | FoolExhaustiveness (id, _) -> id
  | FoolDistinctness (id, _) -> id
  | InequalityNameIntro (id, _) -> id
  | InequalitySplit (id, _, _, _) -> id
  | Substitute (id, _, _, _) -> id
  | Condensation (id, _, _, _) -> id
  | UnitResultingResolution (id, _, _, _) -> id
  | Resolve (id, _, _, _, _, _) -> id
  | SubsumptionResolution (id, _, _, _, _, _, _) -> id
  | Factor (id, _, _, _, _) -> id
  | EqualityResolution (id, _, _, _) -> id
  | EqualityResolutionConstraints (id, _, _, _, _, _) -> id
  | EqualityFactoring (id, _, _, _, _, _, _) -> id
  | EqualityFactoringConstraints (id, _, _, _, _, _, _, _) -> id
  | TruthConflict (id, _, _, _) -> id
  | EqualitySymmetry (id, _, _, _) -> id
  | BoolSimplify (id, _, _, _, _, _, _) -> id
  | Paramodulate (id, _, _, _, _, _, _, _, _) -> id
  | Superposition (id, _, _, _, _, _, _, _, _, _, _) -> id
  | Contradiction (id, _) -> id

let step_rule_name = function
  | Input _ -> "input"
  | FormulaInput _ -> "formula_input"
  | FormulaTermInput _ -> "formula_term_input"
  | FormulaTermCopy _ -> "formula_term_copy"
  | RectifyFormula _ -> "rectify_formula"
  | FoolAtomLift _ -> "fool_atom_lift"
  | FoolFormula _ -> "fool_formula"
  | EnnfFormula _ -> "ennf_formula"
  | SkolemFormula _ -> "skolem_formula"
  | SkolemFormulaComputed _ -> "skolem_formula_computed"
  | CnfFormulaClause _ -> "cnf_formula_clause"
  | FormulaCopy _ -> "formula_copy"
  | FoolBool _ -> "fool_bool"
  | CnfLiteral _ -> "cnf_literal"
  | PredicateDefinition _ -> "predicate_definition"
  | PredicateDefinitionFold _ -> "predicate_definition_fold"
  | PredicateDefinitionFoldChain _ -> "predicate_definition_fold_chain"
  | DefinitionInput _ -> "definition_input"
  | DefinitionRewriteChain _ -> "definition_rewrite_chain"
  | AvatarComponent _ -> "avatar_component"
  | AvatarDefinition _ -> "avatar_definition"
  | SplitDependency _ -> "split_dependency"
  | AvatarSplit _ -> "avatar_split"
  | AvatarContradiction _ -> "avatar_contradiction"
  | AvatarRefutation _ -> "avatar_refutation"
  | FoolExhaustiveness _ -> "fool_exhaustiveness"
  | FoolDistinctness _ -> "fool_distinctness"
  | InequalityNameIntro _ -> "inequality_name_intro"
  | InequalitySplit _ -> "inequality_split"
  | Substitute _ -> "substitute"
  | Condensation _ -> "condensation"
  | UnitResultingResolution _ -> "unit_resulting_resolution"
  | Resolve _ -> "resolve"
  | SubsumptionResolution _ -> "subsumption_resolution"
  | Factor _ -> "factor"
  | EqualityResolution _ -> "equality_resolution"
  | EqualityResolutionConstraints _ -> "equality_resolution_constraints"
  | EqualityFactoring _ -> "equality_factoring"
  | EqualityFactoringConstraints _ -> "equality_factoring_constraints"
  | TruthConflict _ -> "truth_conflict"
  | EqualitySymmetry _ -> "equality_symmetry"
  | BoolSimplify _ -> "bool_simplify"
  | Paramodulate _ -> "paramodulate"
  | Superposition _ -> "superposition"
  | Contradiction _ -> "contradiction"

let step_parent_ids = function
  | Input _ | FormulaInput _ | FormulaTermInput _
  | PredicateDefinition _ | DefinitionInput _
  | AvatarComponent _ | FoolExhaustiveness _
  | FoolDistinctness _ | InequalityNameIntro _ -> []
  | FormulaTermCopy (_, parent_id, _)
  | RectifyFormula (_, parent_id, _, _)
  | FoolFormula (_, parent_id, _)
  | EnnfFormula (_, parent_id, _, _, _)
  | SkolemFormula (_, parent_id, _, _, _, _)
  | SkolemFormulaComputed (_, parent_id, _)
  | CnfFormulaClause (_, parent_id, _, _, _)
  | FormulaCopy (_, parent_id, _)
  | FoolBool (_, parent_id, _)
  | CnfLiteral (_, parent_id, _)
  | DefinitionRewriteChain (_, parent_id, _, _)
  | SplitDependency (_, parent_id, _, _)
  | InequalitySplit (_, parent_id, _, _)
  | Substitute (_, parent_id, _, _)
  | Condensation (_, parent_id, _, _)
  | UnitResultingResolution (_, parent_id, _, _)
  | Factor (_, parent_id, _, _, _)
  | EqualityResolution (_, parent_id, _, _)
  | EqualityResolutionConstraints (_, parent_id, _, _, _, _)
  | EqualityFactoring (_, parent_id, _, _, _, _, _)
  | EqualityFactoringConstraints (_, parent_id, _, _, _, _, _, _)
  | TruthConflict (_, parent_id, _, _)
  | EqualitySymmetry (_, parent_id, _, _)
  | BoolSimplify (_, parent_id, _, _, _, _, _)
  | Contradiction (_, parent_id) -> [parent_id]
  | PredicateDefinitionFold (_, source_id, definition_id, _) ->
      [source_id; definition_id]
  | PredicateDefinitionFoldChain (_, source_id, definition_ids, _) ->
      source_id :: definition_ids
  | AvatarDefinition _ -> []
  | AvatarSplit (_, parent_ids, _)
  | AvatarContradiction (_, parent_ids, _) -> parent_ids
  | AvatarRefutation (_, parent_ids, _, _, _) -> parent_ids
  | Resolve (_, left_id, right_id, _, _, _)
  | SubsumptionResolution (_, left_id, right_id, _, _, _, _)
  | Paramodulate (_, left_id, right_id, _, _, _, _, _, _) ->
      [left_id; right_id]
  | Superposition (_, left_id, right_id, _, _, _, _, _, _, _, _) ->
      [left_id; right_id]
  | FoolAtomLift _ -> []

let step_empty_clause_root = function
  | Input (_, _, clause)
  | DefinitionInput (_, clause)
  | AvatarComponent (_, clause)
  | AvatarDefinition (_, _, _, clause)
  | SplitDependency (_, _, _, clause)
  | AvatarSplit (_, _, clause)
  | AvatarContradiction (_, _, clause)
  | AvatarRefutation (_, _, _, _, clause)
  | FoolExhaustiveness (_, clause)
  | FoolDistinctness (_, clause)
  | InequalityNameIntro (_, clause)
  | InequalitySplit (_, _, _, clause)
  | Substitute (_, _, _, clause)
  | Condensation (_, _, _, clause)
  | UnitResultingResolution (_, _, _, clause)
  | Resolve (_, _, _, _, _, clause)
  | SubsumptionResolution (_, _, _, _, _, _, clause)
  | Factor (_, _, _, _, clause)
  | EqualityResolution (_, _, _, clause)
  | EqualityResolutionConstraints (_, _, _, _, _, clause)
  | EqualityFactoring (_, _, _, _, _, _, clause)
  | EqualityFactoringConstraints (_, _, _, _, _, _, _, clause)
  | TruthConflict (_, _, _, clause)
  | EqualitySymmetry (_, _, _, clause)
  | BoolSimplify (_, _, _, _, _, _, clause)
  | Paramodulate (_, _, _, _, _, _, _, _, clause)
  | Superposition (_, _, _, _, _, _, _, _, _, _, clause) -> clause = []
  | Contradiction _ -> true
  | _ -> false

let proof_dependency_closure steps =
  let by_id = Hashtbl.create 101 in
  List.iter (fun step -> Hashtbl.replace by_id (step_id step) step) steps;
  let used = Hashtbl.create 101 in
  let rec mark id =
    if not (Hashtbl.mem used id) then begin
      Hashtbl.replace used id true;
      match Hashtbl.find_opt by_id id with
      | Some step -> List.iter mark (step_parent_ids step)
      | None -> ()
    end
  in
  List.iter
    (fun step ->
       if step_empty_clause_root step then mark (step_id step))
    steps;
  used

let check_duplicate_ids steps =
  let seen = Hashtbl.create 17 in
  List.iter
    (fun step ->
      let id = step_id step in
      if Hashtbl.mem seen id then error ("duplicate certificate step id " ^ id);
      Hashtbl.add seen id ())
    steps

let parse_problem = function
  | List [Atom "problem"; name] -> Some (atom name)
  | _ -> None

let empty_certificate_metadata = {
  symbol_declarations = [];
  step_propositions = [];
  step_variable_sorts = [];
  step_extras = [];
}

let parse_string_list = function
  | List items -> List.map atom items
  | _ -> error "expected a metadata string list"

let parse_certificate_metadata metadata = function
  | List [Atom "symbol_declaration"; decl] ->
      Some {
        metadata with
        symbol_declarations = metadata.symbol_declarations @ [atom decl];
      }
  | List [Atom "step_proposition"; id; proposition] ->
      Some {
        metadata with
        step_propositions = metadata.step_propositions @ [(atom id, atom proposition)];
      }
  | List [Atom "step_variable_sorts"; id; sorts] ->
      Some {
        metadata with
        step_variable_sorts =
          metadata.step_variable_sorts @ [(atom id, parse_string_list sorts)];
      }
  | List [Atom "step_extra"; id; kind; fields] ->
      Some {
        metadata with
        step_extras =
          metadata.step_extras @ [(atom id, atom kind, parse_string_list fields)];
      }
  | List (Atom (("symbol_declaration" | "step_proposition" | "step_variable_sorts" | "step_extra") as tag) :: _) ->
      error ("malformed certificate metadata record " ^ tag)
  | _ -> None

let parse_certificate text =
  match parse_sexpr text with
  | List (Atom "certificate" :: Atom "vampire-megalodon" :: Atom "1" :: rest) ->
      let problem, step_forms =
        match rest with
        | first :: tail ->
            begin match parse_problem first with
            | Some _ as problem -> (problem, tail)
            | None -> (None, rest)
            end
        | [] -> (None, [])
      in
      let metadata, step_forms =
        List.fold_left
          (fun (metadata, steps) form ->
             match parse_certificate_metadata metadata form with
             | Some metadata -> (metadata, steps)
             | None -> (metadata, steps @ [form]))
          (empty_certificate_metadata, [])
          step_forms
      in
      let steps = List.map parse_step step_forms in
      check_duplicate_ids steps;
      { problem; metadata; steps }
  | _ -> error "expected (certificate vampire-megalodon 1 ...)"

let literal_atom = function
  | Pos tm -> tm
  | Neg tm -> tm

let complementary left right =
  match left, right with
  | Pos a, Neg b -> a = b
  | Neg a, Pos b -> a = b
  | _ -> false

let remove_at index items what =
  if index < 0 then error (what ^ " index must be non-negative");
  let rec aux i = function
    | [] -> error (what ^ " index is out of bounds")
    | _ :: rest when i = index -> rest
    | item :: rest -> item :: aux (i + 1) rest
  in
  aux 0 items

let replace_at index replacement items what =
  if index < 0 then error (what ^ " index must be non-negative");
  let rec aux i = function
    | [] -> error (what ^ " index is out of bounds")
    | _ :: rest when i = index -> replacement :: rest
    | item :: rest -> item :: aux (i + 1) rest
  in
  aux 0 items

let nth index items what =
  if index < 0 then error (what ^ " index must be non-negative");
  try List.nth items index with Failure _ -> error (what ^ " index is out of bounds")

let rec remove_one item = function
  | [] -> None
  | x :: xs when x = item -> Some xs
  | x :: xs ->
      match remove_one item xs with
      | None -> None
      | Some ys -> Some (x :: ys)

let same_clause_multiset left right =
  let rec consume remaining = function
    | [] -> remaining = []
    | item :: rest ->
        match remove_one item remaining with
        | None -> false
        | Some remaining -> consume remaining rest
  in
  List.length left = List.length right && consume left right

let lookup_clause checked id =
  match (try List.assoc id checked with Not_found -> error ("unknown certificate parent " ^ id)) with
  | CheckedClause clause -> clause
  | CheckedFormula _ -> error (id ^ " is a formula parent, but a clause parent was expected")
  | CheckedSatClauseRecord -> error (id ^ " is an AVATAR SAT clause record, but a clause parent was expected")

let lookup_formula checked id =
  match (try List.assoc id checked with Not_found -> error ("unknown certificate parent " ^ id)) with
  | CheckedFormula formula -> formula
  | CheckedClause _ -> error (id ^ " is a clause parent, but a formula parent was expected")
  | CheckedSatClauseRecord -> error (id ^ " is an AVATAR SAT clause record, but a formula parent was expected")

let lookup_avatar_refutation_parent checked id =
  match (try List.assoc id checked with Not_found -> error ("unknown certificate parent " ^ id)) with
  | CheckedClause _ | CheckedSatClauseRecord -> ()
  | CheckedFormula _ -> error (id ^ " is a formula parent, but an AVATAR SAT clause parent was expected")

let rec subst_tm subst tm =
  match tm with
  | DB _ -> tm
  | TmH "=" -> tm
  | TmH h ->
      let rec lookup = function
        | [] -> tm
        | (key, value) :: rest ->
            if key = h then value else lookup rest
      in
      lookup subst
  | Prim _ -> tm
  | TpAp (m, a) -> TpAp (subst_tm subst m, a)
  | Ap (m, n) -> Ap (subst_tm subst m, subst_tm subst n)
  | Lam (a, m) -> Lam (a, subst_tm subst m)
  | Imp (m, n) -> Imp (subst_tm subst m, subst_tm subst n)
  | All (a, m) -> All (a, subst_tm subst m)

let subst_literal subst = function
  | Pos tm -> Pos (subst_tm subst tm)
  | Neg tm -> Neg (subst_tm subst tm)

let subst_clause subst clause = List.map (subst_literal subst) clause

let rec tm_at_position tm position what =
  match position with
  | [] -> tm
  | index :: rest ->
      let child =
        match tm, index with
        | TpAp (m, _), 0 -> m
        | Ap (TmH "vLAM", body), 0 -> body
        | Ap (m, _), 0 -> m
        | Ap (_, n), 1 -> n
        | Lam (_, m), 0 -> m
        | Imp (m, _), 0 -> m
        | Imp (_, n), 1 -> n
        | All (_, m), 0 -> m
        | _ -> error (what ^ " position is out of bounds")
      in
      tm_at_position child rest what

let rec replace_tm_at_position tm position replacement what =
  match position with
  | [] -> replacement
  | index :: rest ->
      match tm, index with
      | TpAp (m, a), 0 -> TpAp (replace_tm_at_position m rest replacement what, a)
      | Ap (TmH "vLAM", body), 0 ->
          Ap (TmH "vLAM", replace_tm_at_position body rest replacement what)
      | Ap (m, n), 0 -> Ap (replace_tm_at_position m rest replacement what, n)
      | Ap (m, n), 1 -> Ap (m, replace_tm_at_position n rest replacement what)
      | Lam (a, m), 0 -> Lam (a, replace_tm_at_position m rest replacement what)
      | Imp (m, n), 0 -> Imp (replace_tm_at_position m rest replacement what, n)
      | Imp (m, n), 1 -> Imp (m, replace_tm_at_position n rest replacement what)
      | All (a, m), 0 -> All (a, replace_tm_at_position m rest replacement what)
      | _ -> error (what ^ " position is out of bounds")

let try_tm_at_position tm position =
  try Some (tm_at_position tm position "term") with Error _ -> None

let replace_literal_atom literal atom =
  match literal with
  | Pos _ -> Pos atom
  | Neg _ -> Neg atom

let rec rewrite_tm_all_once from_tm to_tm tm =
  if tm = from_tm then to_tm
  else
    match tm with
    | TpAp (m, a) -> TpAp (rewrite_tm_all_once from_tm to_tm m, a)
    | Ap (m, n) ->
        Ap (rewrite_tm_all_once from_tm to_tm m, rewrite_tm_all_once from_tm to_tm n)
    | Lam (a, m) -> Lam (a, rewrite_tm_all_once from_tm to_tm m)
    | Imp (m, n) ->
        Imp (rewrite_tm_all_once from_tm to_tm m, rewrite_tm_all_once from_tm to_tm n)
    | All (a, m) -> All (a, rewrite_tm_all_once from_tm to_tm m)
    | DB _ | TmH _ | Prim _ -> tm

let rewrite_literal_all_once from_tm to_tm literal =
  replace_literal_atom literal (rewrite_tm_all_once from_tm to_tm (literal_atom literal))

let megalodon_eq_poly_hash =
  "5a6af35fb6d6bea477dd0f822b8e01ca0d57cc50dfd41744307bc94597fdaa4a"

let equality_sides = function
  | Ap (Ap (TmH h, left), right) when h = "=" || h = "eq" -> Some (left, right)
  | Ap (Ap (TpAp (TmH h, _), left), right) when h = megalodon_eq_poly_hash -> Some (left, right)
  | _ -> None

let megalodon_eq_poly_sides = function
  | Ap (Ap (TpAp (TmH h, tp), left), right) when h = megalodon_eq_poly_hash ->
      Some (tp, left, right)
  | _ -> None

let equality_to_true atom =
  Ap (Ap (TmH "=", atom), TmH "f__true")

let typed_prop_equality_to_true atom =
  Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, Prop), atom), TmH "f__true")

let paramodulation_position_candidates target_atom position =
  let base = [position] in
  match equality_sides target_atom, position with
  | Some _, 0 :: 1 :: rest -> base @ [[1] @ rest]
  | Some _, 1 :: rest -> base @ [[0; 1] @ rest]
  | Some _, 0 :: rest -> base @ [[0; 1] @ rest]
  | _ -> base

let vampire_false = TmH "vampire_false"

let vampire_or left right =
  Ap (Ap (TmH "vampire_or", left), right)

let vampire_and left right =
  Ap (Ap (TmH "vampire_and", left), right)

let rec left_assoc_vampire_or_formula tm =
  let normalize = left_assoc_vampire_or_formula in
  let rec collect_or acc = function
    | Ap (Ap (TmH "vampire_or", left), right) ->
        collect_or (collect_or acc right) left
    | other -> normalize other :: acc
  in
  let build_left = function
    | [] -> tm
    | first :: rest -> List.fold_left vampire_or first rest
  in
  match tm with
  | Ap (Ap (TmH "vampire_or", _), _) ->
      tm |> collect_or [] |> build_left
  | Ap (Ap (TmH "vampire_and", left), right) ->
      vampire_and (normalize left) (normalize right)
  | Imp (left, right) -> Imp (normalize left, normalize right)
  | All (tp, body) -> All (tp, normalize body)
  | Lam (tp, body) -> Lam (tp, normalize body)
  | TpAp (m, a) -> TpAp (normalize m, a)
  | Ap (m, n) -> Ap (normalize m, normalize n)
  | TmH _ | DB _ | Prim _ -> tm

let vampire_exists tp body =
  Ap (TmH "vampire_exists_prop", Lam (tp, body))

let rec app2_name = function
  | Ap (Ap (TmH h, left), right) -> Some (h, left, right)
  | _ -> None

let is_vampire_false = function
  | TmH "f__false" | TmH "vampire_false" -> true
  | _ -> false

let neg_formula tm =
  Imp (tm, vampire_false)

let is_vampire_var_name name =
  let len = String.length name in
  len >= 2 && name.[0] = 'X' &&
  let rec digits i =
    i = len || (name.[i] >= '0' && name.[i] <= '9' && digits (i + 1))
  in
  digits 1

let vampire_var_index name =
  if is_vampire_var_name name then
    Some (int_of_string (String.sub name 1 (String.length name - 1)))
  else
    None

let max_vampire_var_name tm =
  let better current candidate =
    match current, vampire_var_index candidate with
    | None, Some _ -> Some candidate
    | Some old, Some candidate_index ->
        begin match vampire_var_index old with
        | Some old_index when candidate_index > old_index -> Some candidate
        | _ -> current
        end
    | _ -> current
  in
  let rec loop current = function
    | TmH h -> better current h
    | TpAp (m, _) -> loop current m
    | Ap (m, n) -> loop (loop current m) n
    | Lam (_, body) -> loop current body
    | Imp (left, right) -> loop (loop current left) right
    | All (_, body) -> loop current body
    | DB _ | Prim _ -> current
  in
  loop None tm

let first_unused_vampire_var_name used tm =
  let add acc name =
    if is_vampire_var_name name
       && not (List.mem name used)
       && not (List.mem name acc) then
      acc @ [name]
    else acc
  in
  let rec loop acc = function
    | TmH h -> add acc h
    | TpAp (m, _) -> loop acc m
    | Ap (m, n) -> loop (loop acc m) n
    | Lam (_, body) -> loop acc body
    | Imp (left, right) -> loop (loop acc left) right
    | All (_, body) -> loop acc body
    | DB _ | Prim _ -> acc
  in
  match loop [] tm with
  | name :: _ -> Some name
  | [] -> None

let first_unused_vampire_var_name_with_sort env used sort tm =
  let names =
    let rec loop acc = function
      | TmH h when is_vampire_var_name h ->
          if List.mem h acc then acc else acc @ [h]
      | TmH _ | DB _ | Prim _ -> acc
      | TpAp (m, _) -> loop acc m
      | Ap (m, n) -> loop (loop acc m) n
      | Lam (_, body) -> loop acc body
      | Imp (left, right) -> loop (loop acc left) right
      | All (_, body) -> loop acc body
    in
    loop [] tm
  in
  List.find_opt
    (fun name ->
       not (List.mem name used)
       &&
       match List.assoc_opt name env with
       | Some known_sort -> known_sort = sort
       | None -> false)
    names

let guarded_lambda_vampire_var_name tm =
  let rec loop = function
    | Ap (Ap (TmH "In", TmH h), _) when is_vampire_var_name h -> Some h
    | Ap (Ap (TmH "vampire_and", left), right)
    | Ap (Ap (TmH "vampire_or", left), right) ->
        begin match loop left with
        | Some _ as found -> found
        | None -> loop right
        end
    | Ap (TmH "vampire_exists_prop", _)
    | Lam _ -> None
    | TpAp (m, _) -> loop m
    | Ap (m, n) ->
        begin match loop m with
        | Some _ as found -> found
        | None -> loop n
        end
    | Imp (left, right) ->
        begin match loop left with
        | Some _ as found -> found
        | None -> loop right
        end
    | All (_, body) -> loop body
    | DB _ | TmH _ | Prim _ -> None
  in
  loop tm

let bind_anonymous_lambda_body body =
  match guarded_lambda_vampire_var_name body with
  | Some name -> subst_named_tm name body
  | None ->
  match max_vampire_var_name body with
  | Some name -> subst_named_tm name body
  | None -> body

let first_vampire_var_name tm =
  let rec loop = function
    | TmH h when is_vampire_var_name h -> Some h
    | TpAp (m, _) -> loop m
    | Ap (m, n) ->
        begin match loop m with
        | Some _ as found -> found
        | None -> loop n
        end
    | Lam (_, body) -> loop body
    | Imp (left, right) ->
        begin match loop left with
        | Some _ as found -> found
        | None -> loop right
        end
    | All (_, body) -> loop body
    | DB _ | TmH _ | Prim _ -> None
  in
  loop tm

let application_spine tm =
  let rec loop args = function
    | Ap (m, n) -> loop (n :: args) m
    | head -> (head, args)
  in
  loop [] tm

let rec principal_antecedent_var tm =
  match application_spine tm with
  | TmH "=", atom :: _ -> principal_antecedent_var atom
  | TmH h, arg :: _ when is_vampire_var_name h ->
      begin match first_vampire_var_name arg with
      | Some _ as found -> found
      | None -> Some h
      end
  | TmH _, arg :: _ -> first_vampire_var_name arg
  | _ -> first_vampire_var_name tm

let bind_anonymous_forall_body body =
  let preferred =
    match body with
    | Imp (left, _) -> principal_antecedent_var left
    | _ -> first_vampire_var_name body
  in
  match preferred with
  | Some name -> subst_named_tm name body
  | None -> bind_anonymous_lambda_body body

let add_vampire_var_renaming left right left_to_right right_to_left =
  if left = right then Some (left_to_right, right_to_left)
  else if is_vampire_var_name left && is_vampire_var_name right then
    let left_ok =
      try List.assoc left left_to_right = right with Not_found -> true
    in
    let right_ok =
      try List.assoc right right_to_left = left with Not_found -> true
    in
    if left_ok && right_ok then
      let left_to_right =
        if List.mem_assoc left left_to_right then left_to_right
        else (left, right) :: left_to_right
      in
      let right_to_left =
        if List.mem_assoc right right_to_left then right_to_left
        else (right, left) :: right_to_left
      in
      Some (left_to_right, right_to_left)
    else None
  else None

let rec tm_equal_mod_vampire_var_renaming left right left_to_right right_to_left =
  match left, right with
  | DB i, DB j when i = j -> Some (left_to_right, right_to_left)
  | TmH h, TmH k -> add_vampire_var_renaming h k left_to_right right_to_left
  | Prim i, Prim j when i = j -> Some (left_to_right, right_to_left)
  | TpAp (m, a), TpAp (n, b) when a = b ->
      tm_equal_mod_vampire_var_renaming m n left_to_right right_to_left
  | Ap (m1, m2), Ap (n1, n2) ->
      begin match tm_equal_mod_vampire_var_renaming m1 n1 left_to_right right_to_left with
      | None -> None
      | Some (left_to_right, right_to_left) ->
          tm_equal_mod_vampire_var_renaming m2 n2 left_to_right right_to_left
      end
  | Lam (a, m), Lam (b, n) when a = b ->
      tm_equal_mod_vampire_var_renaming m n left_to_right right_to_left
  | Imp (m1, m2), Imp (n1, n2) ->
      begin match tm_equal_mod_vampire_var_renaming m1 n1 left_to_right right_to_left with
      | None -> None
      | Some (left_to_right, right_to_left) ->
          tm_equal_mod_vampire_var_renaming m2 n2 left_to_right right_to_left
      end
  | All (a, m), All (b, n) when a = b ->
      tm_equal_mod_vampire_var_renaming m n left_to_right right_to_left
  | _ -> None

let same_mod_vampire_var_renaming left right =
  match tm_equal_mod_vampire_var_renaming left right [] [] with
  | Some _ -> true
  | None -> false

let add_scoped_vampire_var_renaming left right frames =
  let rec assoc_opt key = function
    | [] -> None
    | (candidate, value) :: rest ->
        if candidate = key then Some value else assoc_opt key rest
  in
  let mem_assoc key items = Option.is_some (assoc_opt key items) in
  if left = right then Some frames
  else if is_vampire_var_name left && is_vampire_var_name right then
    match frames with
    | [] -> None
    | (left_to_right, right_to_left) :: outer ->
      let left_ok =
          match assoc_opt left left_to_right with
          | Some mapped -> mapped = right
          | None -> true
      in
      let right_ok =
          match assoc_opt right right_to_left with
          | Some mapped -> mapped = left
          | None -> true
      in
      if left_ok && right_ok then
        let left_to_right =
            if mem_assoc left left_to_right then left_to_right
            else (left, right) :: left_to_right
        in
        let right_to_left =
            if mem_assoc right right_to_left then right_to_left
            else (right, left) :: right_to_left
        in
          Some ((left_to_right, right_to_left) :: outer)
        else None
  else None

let rec tm_equal_mod_scoped_vampire_var_renaming left right frames =
  match left, right with
  | DB i, DB j when i = j -> Some frames
  | TmH h, TmH k -> add_scoped_vampire_var_renaming h k frames
  | Prim i, Prim j when i = j -> Some frames
  | TpAp (m, a), TpAp (n, b) when a = b ->
      tm_equal_mod_scoped_vampire_var_renaming m n frames
  | Ap (m1, m2), Ap (n1, n2) ->
      begin match tm_equal_mod_scoped_vampire_var_renaming m1 n1 frames with
      | None -> None
      | Some frames -> tm_equal_mod_scoped_vampire_var_renaming m2 n2 frames
      end
  | Lam (a, m), Lam (b, n) when a = b ->
      begin match tm_equal_mod_scoped_vampire_var_renaming m n (([], []) :: frames) with
      | None -> None
      | Some _ -> Some frames
      end
  | Imp (m1, m2), Imp (n1, n2) ->
      begin match tm_equal_mod_scoped_vampire_var_renaming m1 n1 frames with
      | None -> None
      | Some frames -> tm_equal_mod_scoped_vampire_var_renaming m2 n2 frames
      end
  | All (a, m), All (b, n) when a = b ->
      begin match tm_equal_mod_scoped_vampire_var_renaming m n (([], []) :: frames) with
      | None -> None
      | Some _ -> Some frames
      end
  | _ -> None

let same_mod_scoped_vampire_var_renaming left right =
  match tm_equal_mod_scoped_vampire_var_renaming left right [([], [])] with
  | Some _ -> true
  | None -> false

let rec tm_equal_mod_scoped_vampire_var_renaming_and_equality left right frames =
  let try_pair left_a right_a left_b right_b frames =
    match tm_equal_mod_scoped_vampire_var_renaming_and_equality left_a right_a frames with
    | None -> None
    | Some frames ->
        tm_equal_mod_scoped_vampire_var_renaming_and_equality left_b right_b frames
  in
  match equality_sides left, equality_sides right with
  | Some (left_lhs, left_rhs), Some (right_lhs, right_rhs) ->
      begin match try_pair left_lhs right_lhs left_rhs right_rhs frames with
      | Some _ as result -> result
      | None -> try_pair left_lhs right_rhs left_rhs right_lhs frames
      end
  | _ ->
      match left, right with
      | DB i, DB j when i = j -> Some frames
      | TmH h, TmH k -> add_scoped_vampire_var_renaming h k frames
      | Prim i, Prim j when i = j -> Some frames
      | TpAp (m, a), TpAp (n, b) when a = b ->
          tm_equal_mod_scoped_vampire_var_renaming_and_equality m n frames
      | Ap (m1, m2), Ap (n1, n2) ->
          begin match tm_equal_mod_scoped_vampire_var_renaming_and_equality m1 n1 frames with
          | None -> None
          | Some frames -> tm_equal_mod_scoped_vampire_var_renaming_and_equality m2 n2 frames
          end
      | Lam (a, m), Lam (b, n) when a = b ->
          begin match tm_equal_mod_scoped_vampire_var_renaming_and_equality m n (([], []) :: frames) with
          | None -> None
          | Some _ -> Some frames
          end
      | Imp (m1, m2), Imp (n1, n2) ->
          begin match tm_equal_mod_scoped_vampire_var_renaming_and_equality m1 n1 frames with
          | None -> None
          | Some frames -> tm_equal_mod_scoped_vampire_var_renaming_and_equality m2 n2 frames
          end
      | All (a, m), All (b, n) when a = b ->
          begin match tm_equal_mod_scoped_vampire_var_renaming_and_equality m n (([], []) :: frames) with
          | None -> None
          | Some _ -> Some frames
          end
      | _ -> None

let same_mod_scoped_vampire_var_renaming_and_equality left right =
  match tm_equal_mod_scoped_vampire_var_renaming_and_equality left right [([], [])] with
  | Some _ -> true
  | None -> false

let is_equality_atom tm =
  match equality_sides tm with
  | Some _ -> true
  | None -> false

let rec vampire_vlam_body_tm tm =
  match tm with
  | DB i -> TmH ("db" ^ string_of_int i)
  | TpAp (m, a) -> TpAp (vampire_vlam_body_tm m, a)
  | Ap (m, n) -> Ap (vampire_vlam_body_tm m, vampire_vlam_body_tm n)
  | Lam (_, body) ->
      Ap (TmH "vLAM", vampire_vlam_body_tm (bind_anonymous_lambda_body body))
  | Imp (left, right) ->
      Imp (vampire_vlam_body_tm left, vampire_vlam_body_tm right)
  | All (_, body) ->
      Ap (TmH "vPI", Ap (TmH "vLAM", vampire_vlam_body_tm (bind_anonymous_forall_body body)))
  | tm -> tm

let rec fool_term_tm tm =
  match tm with
  | TmH "vampire_true" -> TmH "f__true"
  | TmH "vampire_false" -> TmH "f__false"
  | Imp (body, false_tm) when is_vampire_false false_tm ->
      Ap (TmH "vNOT", fool_term_tm body)
  | Imp (left, right) ->
      Ap (Ap (TmH "vIMP", fool_term_tm left), fool_term_tm right)
  | All (_, body) ->
      Ap (TmH "vPI",
          Ap (TmH "vLAM",
              vampire_vlam_body_tm (fool_term_tm (bind_anonymous_forall_body body))))
  | Ap (TmH "vampire_exists_prop", Lam (_, body)) ->
      Ap (TmH "vSIGMA",
          Ap (TmH "vLAM",
              vampire_vlam_body_tm (fool_term_tm (bind_anonymous_lambda_body body))))
  | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)) ->
      Ap (TmH "vSIGMA", Ap (TmH "vLAM", vampire_vlam_body_tm (fool_term_tm body)))
  | Ap (Ap (TmH "vampire_or", left), right) ->
      Ap (Ap (TmH "vOR", fool_term_tm left), fool_term_tm right)
  | Ap (Ap (TmH "vampire_and", left), right) ->
      Ap (Ap (TmH "vAND", fool_term_tm left), fool_term_tm right)
  | Ap (Ap (TmH "=", left), right) ->
      Ap (Ap (TmH "vEQ", fool_term_tm left), fool_term_tm right)
  | TpAp (m, a) -> TpAp (fool_term_tm m, a)
  | Ap (m, n) -> Ap (fool_term_tm m, fool_term_tm n)
  | Lam (_, body) ->
      Ap (TmH "vLAM", vampire_vlam_body_tm (fool_term_tm (bind_anonymous_lambda_body body)))
  | _ -> tm

let rec fool_formula_tm tm =
  match tm with
  | Imp (left, right) -> Imp (fool_formula_tm left, fool_formula_tm right)
  | All (tp, body) -> All (tp, fool_formula_tm body)
  | Ap (Ap (TmH "vampire_or", left), right) -> vampire_or (fool_formula_tm left) (fool_formula_tm right)
  | Ap (Ap (TmH "vampire_and", left), right) -> vampire_and (fool_formula_tm left) (fool_formula_tm right)
  | Ap (TmH "vampire_exists_prop", Lam (tp, body)) -> vampire_exists tp (fool_formula_tm body)
  | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)) -> vampire_exists Set (fool_formula_tm body)
  | Lam (tp, body) -> Lam (tp, fool_formula_tm body)
  | TmH "vampire_true"
  | TmH "vampire_false" -> tm
  | Ap (Ap (TmH "=", left), right) ->
      Ap (Ap (TmH "=", fool_term_tm left), fool_term_tm right)
  | _ when is_equality_atom tm -> tm
  | TmH h when is_vampire_var_name h -> Ap (Ap (TmH "=", TmH "f__true"), tm)
  | _ -> equality_to_true (fool_term_tm tm)

let rec typed_fool_bool_lifts tm =
  match tm with
  | Ap (Ap (TmH "=", TmH b), right) when b = "f__true" || b = "f__false" ->
      typed_prop_equality_to_true (typed_fool_bool_lifts right)
  | Ap (Ap (TmH "=", left), TmH "f__true") ->
      typed_prop_equality_to_true (typed_fool_bool_lifts left)
  | TpAp (m, a) -> TpAp (typed_fool_bool_lifts m, a)
  | Ap (m, n) -> Ap (typed_fool_bool_lifts m, typed_fool_bool_lifts n)
  | Lam (tp, body) -> Lam (tp, typed_fool_bool_lifts body)
  | Imp (left, right) -> Imp (typed_fool_bool_lifts left, typed_fool_bool_lifts right)
  | All (tp, body) -> All (tp, typed_fool_bool_lifts body)
  | DB _ | TmH _ | Prim _ -> tm

let fool_formula_tm_candidates tm =
  let raw = fool_formula_tm tm in
  let typed = typed_fool_bool_lifts raw in
  if raw = typed then [raw] else [raw; typed]

let rec ennf_pos tm =
  match tm with
  | Imp (left, false_tm) when is_vampire_false false_tm -> ennf_neg left
  | Imp (left, right) -> vampire_or (ennf_neg left) (ennf_pos right)
  | All (tp, body) -> All (tp, ennf_pos body)
  | Ap (Ap (TmH "vampire_or", left), right) -> vampire_or (ennf_pos left) (ennf_pos right)
  | Ap (Ap (TmH "vampire_and", left), right) -> vampire_and (ennf_pos left) (ennf_pos right)
  | _ -> tm
and ennf_neg tm =
  match tm with
  | Imp (left, right) -> vampire_and (ennf_pos left) (ennf_neg right)
  | All (tp, body) -> vampire_exists tp (ennf_neg body)
  | Ap (Ap (TmH "vampire_or", left), right) -> vampire_and (ennf_neg left) (ennf_neg right)
  | Ap (Ap (TmH "vampire_and", left), right) -> vampire_or (ennf_neg left) (ennf_neg right)
  | _ -> neg_formula tm

let rec ennf_lambda_to_vlam_tm tm =
  let rec body depth = function
    | DB i when i = depth -> TmH "db0"
    | DB i when i > depth -> DB (i - 1)
    | TpAp (m, a) -> TpAp (body depth m, a)
    | Ap (m, n) -> Ap (body depth m, body depth n)
    | Lam (_, nested) -> Ap (TmH "vLAM", body 0 nested)
    | Imp (m, n) -> Imp (body depth m, body depth n)
    | All (tp, nested) -> All (tp, body (depth + 1) nested)
    | tm -> tm
  in
  match tm with
  | Lam (_, body_tm) -> Ap (TmH "vLAM", body 0 body_tm)
  | TpAp (m, a) -> TpAp (ennf_lambda_to_vlam_tm m, a)
  | Ap (m, n) -> Ap (ennf_lambda_to_vlam_tm m, ennf_lambda_to_vlam_tm n)
  | Imp (m, n) -> Imp (ennf_lambda_to_vlam_tm m, ennf_lambda_to_vlam_tm n)
  | All (tp, body_tm) -> All (tp, ennf_lambda_to_vlam_tm body_tm)
  | tm -> tm

let same_ennf_tm expected target =
  expected = target || ennf_lambda_to_vlam_tm expected = target

let rec skolemize_formula_tm subst tm =
  match tm with
  | Imp (left, right) -> Imp (skolemize_formula_tm subst left, skolemize_formula_tm subst right)
  | All (tp, body) -> All (tp, skolemize_formula_tm subst body)
  | Ap (Ap (TmH "vampire_or", left), right) -> vampire_or (skolemize_formula_tm subst left) (skolemize_formula_tm subst right)
  | Ap (Ap (TmH "vampire_and", left), right) -> vampire_and (skolemize_formula_tm subst left) (skolemize_formula_tm subst right)
  | Ap (TmH "vampire_exists_prop", Lam (_, body)) ->
      skolemize_formula_tm subst (subst_tm subst body)
  | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)) ->
      let subst =
        match subst with
        | [(_, skolem_tm)] -> ("db0", skolem_tm) :: subst
        | _ -> subst
      in
      skolemize_formula_tm subst (subst_tm subst body)
  | TpAp (m, a) -> TpAp (skolemize_formula_tm subst m, a)
  | Ap (m, n) -> Ap (skolemize_formula_tm subst m, skolemize_formula_tm subst n)
  | Lam (tp, body) -> Lam (tp, skolemize_formula_tm subst body)
  | _ -> tm

let skolemize_formula_tm_ordered subst tm =
  let rec go subst tm =
    match tm with
    | Imp (left, right) ->
        let left, subst = go subst left in
        let right, subst = go subst right in
        (Imp (left, right), subst)
    | All (tp, body) ->
        let body, subst = go subst body in
        (All (tp, body), subst)
    | Ap (Ap (TmH "vampire_or", left), right) ->
        let left, subst = go subst left in
        let right, subst = go subst right in
        (vampire_or left right, subst)
    | Ap (Ap (TmH "vampire_and", left), right) ->
        let left, subst = go subst left in
        let right, subst = go subst right in
        (vampire_and left right, subst)
    | Ap (TmH "vampire_exists_prop", Lam (_, body)) ->
        begin match subst with
        | (_, witness) :: rest -> go rest (tmsubst body 0 witness)
        | [] -> go [] body
        end
    | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)) ->
        begin match subst with
        | (_, witness) :: rest -> go rest (subst_tm [("db0", witness)] body)
        | [] -> go [] body
        end
    | TpAp (m, a) ->
        let m, subst = go subst m in
        (TpAp (m, a), subst)
    | Ap (m, n) ->
        let m, subst = go subst m in
        let n, subst = go subst n in
        (Ap (m, n), subst)
    | Lam (tp, body) ->
        let body, subst = go subst body in
        (Lam (tp, body), subst)
    | tm -> (tm, subst)
  in
  fst (go subst tm)

let bounded_append limit left right =
  let rec add acc count = function
    | [] -> List.rev acc
    | _ when count >= limit -> List.rev acc
    | item :: rest -> add (item :: acc) (count + 1) rest
  in
  add (List.rev left) (List.length left) right

let rec skolemize_formula_tm_candidates subst tm =
  let limit = 64 in
  let combine binary left_candidates right_candidates =
    let rec loop acc = function
      | [] -> acc
      | left :: rest ->
          let additions = List.map (fun right -> binary left right) right_candidates in
          loop (bounded_append limit acc additions) rest
    in
    loop [] left_candidates
  in
  match tm with
  | Imp (left, right) ->
      combine
        (fun left right -> Imp (left, right))
        (skolemize_formula_tm_candidates subst left)
        (skolemize_formula_tm_candidates subst right)
  | All (tp, body) ->
      List.map (fun body -> All (tp, body)) (skolemize_formula_tm_candidates subst body)
  | Ap (Ap (TmH "vampire_or", left), right) ->
      combine vampire_or
        (skolemize_formula_tm_candidates subst left)
        (skolemize_formula_tm_candidates subst right)
  | Ap (Ap (TmH "vampire_and", left), right) ->
      combine vampire_and
        (skolemize_formula_tm_candidates subst left)
        (skolemize_formula_tm_candidates subst right)
  | Ap (TmH "vampire_exists_prop", Lam (_, body)) ->
      let direct = skolemize_formula_tm subst tm in
      let instantiated =
        subst
        |> List.map
             (fun (_, witness) ->
                skolemize_formula_tm_candidates subst (tmsubst body 0 witness))
        |> List.flatten
      in
      bounded_append limit [direct] instantiated
  | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)) ->
      [skolemize_formula_tm subst (Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)))]
  | TpAp (m, a) ->
      List.map (fun m -> TpAp (m, a)) (skolemize_formula_tm_candidates subst m)
  | Ap (m, n) ->
      combine
        (fun m n -> Ap (m, n))
        (skolemize_formula_tm_candidates subst m)
        (skolemize_formula_tm_candidates subst n)
  | Lam (tp, body) ->
      List.map (fun body -> Lam (tp, body)) (skolemize_formula_tm_candidates subst body)
  | _ -> [tm]

let rec same_mod_skolem_bound_names left right =
  left = right ||
  match left, right with
  | DB _, TmH h | TmH h, DB _ when is_vampire_var_name h -> true
  | TpAp (m, a), TpAp (n, b) when a = b ->
      same_mod_skolem_bound_names m n
  | Ap (m1, m2), Ap (n1, n2) ->
      same_mod_skolem_bound_names m1 n1
      && same_mod_skolem_bound_names m2 n2
  | Lam (a, m), Lam (b, n) when a = b ->
      same_mod_skolem_bound_names m n
  | Imp (m1, m2), Imp (n1, n2) ->
      same_mod_skolem_bound_names m1 n1
      && same_mod_skolem_bound_names m2 n2
  | All (a, m), All (b, n) when a = b ->
      same_mod_skolem_bound_names m n
  | _ -> false

let skolemize_formula_tm_matches_witness_multiset subst source result =
  (* Skolem certificates carry source variable names, but parsed existential
     binders are de Bruijn terms.  When exact named substitution cannot be
     replayed, verify that the result consumes exactly the emitted witness
     terms at existential binders. *)
  let choose_one items =
    let rec go prefix = function
      | [] -> []
      | item :: rest -> (item, List.rev_append prefix rest) :: go (item :: prefix) rest
    in
    go [] items
  in
  let rec match_tm witnesses source result =
    if source = result
       || same_mod_skolem_bound_names source result then
      [witnesses]
    else
      match source, result with
      | Ap (TmH "vampire_exists_prop", Lam (_, body)), _ ->
          choose_one witnesses
          |> List.map
               (fun ((_, witness), rest) ->
                  match_tm rest (tmsubst body 0 witness) result)
          |> List.flatten
      | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)), _ ->
          choose_one witnesses
          |> List.map
               (fun ((_, witness), rest) ->
                  match_tm rest (subst_tm [("db0", witness)] body) result)
          |> List.flatten
      | Imp (source_left, source_right), Imp (result_left, result_right) ->
          match_tm witnesses source_left result_left
          |> List.map
               (fun witnesses -> match_tm witnesses source_right result_right)
          |> List.flatten
      | Ap (Ap (TmH "vampire_or", source_left), source_right),
        Ap (Ap (TmH "vampire_or", result_left), result_right) ->
          match_tm witnesses source_left result_left
          |> List.map
               (fun witnesses -> match_tm witnesses source_right result_right)
          |> List.flatten
      | Ap (Ap (TmH "vampire_and", source_left), source_right),
        Ap (Ap (TmH "vampire_and", result_left), result_right) ->
          match_tm witnesses source_left result_left
          |> List.map
               (fun witnesses -> match_tm witnesses source_right result_right)
          |> List.flatten
      | All (source_tp, source_body), All (result_tp, result_body)
          when source_tp = result_tp ->
          match_tm witnesses source_body result_body
      | Lam (source_tp, source_body), Lam (result_tp, result_body)
          when source_tp = result_tp ->
          match_tm witnesses source_body result_body
      | TpAp (source_fn, source_arg), TpAp (result_fn, result_arg)
          when source_arg = result_arg ->
          match_tm witnesses source_fn result_fn
      | Ap (source_fn, source_arg), Ap (result_fn, result_arg) ->
          match_tm witnesses source_fn result_fn
          |> List.map
               (fun witnesses -> match_tm witnesses source_arg result_arg)
          |> List.flatten
      | _ -> []
  in
  match_tm subst source result
  |> List.exists (function [] -> true | _ -> false)

let rec normalize_bool_equality_orientation tm =
  let normalize = normalize_bool_equality_orientation in
  match tm with
  | Ap (Ap (TpAp (TmH h, tp), left), TmH b)
      when h = megalodon_eq_poly_hash && (b = "f__true" || b = "f__false") ->
      Ap (Ap (TpAp (TmH h, tp), TmH b), normalize left)
  | Ap (Ap (TpAp (TmH h, tp), left), right)
      when h = megalodon_eq_poly_hash ->
      Ap (Ap (TpAp (TmH h, tp), normalize left), normalize right)
  | Ap (Ap (TmH "=", left), TmH h) when h = "f__true" || h = "f__false" ->
      Ap (Ap (TmH "=", TmH h), normalize left)
  | Ap (Ap (TmH "=", left), right) ->
      Ap (Ap (TmH "=", normalize left), normalize right)
  | TpAp (m, a) -> TpAp (normalize m, a)
  | Ap (m, n) -> Ap (normalize m, normalize n)
  | Lam (tp, body) -> Lam (tp, normalize body)
  | Imp (left, right) -> Imp (normalize left, normalize right)
  | All (tp, body) -> All (tp, normalize body)
  | _ -> tm

let rec normalize_equality_orientation tm =
  let normalize = normalize_equality_orientation in
  match tm with
  | Ap (Ap (TpAp (TmH h, tp), left), right)
      when h = megalodon_eq_poly_hash ->
      let left = normalize left in
      let right = normalize right in
      if compare left right <= 0 then Ap (Ap (TpAp (TmH h, tp), left), right)
      else Ap (Ap (TpAp (TmH h, tp), right), left)
  | Ap (Ap (TmH "=", left), right) ->
      let left = normalize left in
      let right = normalize right in
      if compare left right <= 0 then Ap (Ap (TmH "=", left), right)
      else Ap (Ap (TmH "=", right), left)
  | TpAp (m, a) -> TpAp (normalize m, a)
  | Ap (m, n) -> Ap (normalize m, normalize n)
  | Lam (tp, body) -> Lam (tp, normalize body)
  | Imp (left, right) -> Imp (normalize left, normalize right)
  | All (tp, body) -> All (tp, normalize body)
  | _ -> tm

let normalize_literal_equality_orientation = function
  | Pos atom -> Pos (normalize_equality_orientation atom)
  | Neg atom -> Neg (normalize_equality_orientation atom)

let normalize_literal_bool_equality_orientation = function
  | Pos atom -> Pos (normalize_bool_equality_orientation atom)
  | Neg atom -> Neg (normalize_bool_equality_orientation atom)

let same_literal_mod_bound_names left right =
  match left, right with
  | Pos left_atom, Pos right_atom
  | Neg left_atom, Neg right_atom ->
      left_atom = right_atom
      || same_mod_skolem_bound_names left_atom right_atom
      || same_mod_skolem_bound_names
           (normalize_bool_equality_orientation left_atom)
           (normalize_bool_equality_orientation right_atom)
      || same_mod_skolem_bound_names
           (normalize_equality_orientation left_atom)
           (normalize_equality_orientation right_atom)
  | _ -> false

let same_clause_multiset_mod_bound_names left right =
  let rec pick literal prefix = function
    | [] -> None
    | candidate :: rest when same_literal_mod_bound_names candidate literal ->
        Some (List.rev_append prefix rest)
    | candidate :: rest -> pick literal (candidate :: prefix) rest
  in
  let rec consume remaining = function
    | [] -> remaining = []
    | literal :: rest ->
        begin match pick literal [] remaining with
        | Some remaining -> consume remaining rest
        | None -> false
        end
  in
  List.length left = List.length right && consume right left

let same_clause_set_mod_equality left right =
  let unique literals =
    let rec add_unique acc = function
      | [] -> List.rev acc
      | literal :: rest ->
          if List.exists ((=) literal) acc then add_unique acc rest
          else add_unique (literal :: acc) rest
    in
    add_unique [] (List.map normalize_literal_equality_orientation literals)
  in
  same_clause_multiset (unique left) (unique right)

let same_clause_mod_vampire_var_renaming left right =
  let literal_equal state left right =
    match left, right with
    | Pos m, Pos n
    | Neg m, Neg n ->
        let left_to_right, right_to_left = state in
        tm_equal_mod_vampire_var_renaming m n left_to_right right_to_left
    | _ -> None
  in
  let rec pick state literal prefix = function
    | [] -> None
    | candidate :: rest ->
        begin match literal_equal state candidate literal with
        | Some state -> Some (state, List.rev_append prefix rest)
        | None -> pick state literal (candidate :: prefix) rest
        end
  in
  let rec consume state remaining = function
    | [] -> remaining = []
    | literal :: rest ->
        begin match pick state literal [] remaining with
        | Some (state, remaining) -> consume state remaining rest
        | None -> false
        end
  in
  List.length left = List.length right && consume ([], []) left right

let same_clause_mod_vampire_var_renaming_and_equality left right =
  same_clause_mod_vampire_var_renaming
    (List.map normalize_literal_equality_orientation left)
    (List.map normalize_literal_equality_orientation right)

let rebuild_binary head = function
  | [] -> TmH head
  | item :: rest ->
      List.fold_left
        (fun acc item -> Ap (Ap (TmH head, acc), item))
        item rest

let rec collect_binary head tm =
  match tm with
  | Ap (Ap (TmH h, left), right) when h = head ->
      collect_binary head left @ collect_binary head right
  | _ -> [tm]

let rec normalize_fool_bool_association tm =
  let normalize = normalize_fool_bool_association in
  match tm with
  | Ap (Ap (TmH h, left), right) when h = "vAND" || h = "vOR" ->
      let items = collect_binary h (normalize left) @ collect_binary h (normalize right) in
      rebuild_binary h items
  | Ap (Ap (TmH h, left), right) when h = "vampire_and" || h = "vampire_or" ->
      let items = collect_binary h (normalize left) @ collect_binary h (normalize right) in
      rebuild_binary h items
  | TpAp (m, a) -> TpAp (normalize m, a)
  | Ap (m, n) -> Ap (normalize m, normalize n)
  | Lam (tp, body) -> Lam (tp, normalize body)
  | Imp (left, right) -> Imp (normalize left, normalize right)
  | All (tp, body) -> All (tp, normalize body)
  | _ -> tm

let normalize_fool_formula_shape tm =
  tm
  |> normalize_bool_equality_orientation
  |> normalize_fool_bool_association
  |> normalize_equality_orientation
  |> normalize_fool_bool_association

let same_fool_formula_lift expected target =
  expected = target
  || normalize_bool_equality_orientation expected = normalize_bool_equality_orientation target
  || normalize_equality_orientation expected = normalize_equality_orientation target
  || normalize_fool_formula_shape expected = normalize_fool_formula_shape target

let rec debug_tm tm =
  match tm with
  | DB i -> "(DB " ^ string_of_int i ^ ")"
  | TmH h -> "(TMH \"" ^ String.escaped h ^ "\")"
  | Prim i -> "(PRIM " ^ string_of_int i ^ ")"
  | TpAp (m, _) -> "(TPAP " ^ debug_tm m ^ " _)"
  | Ap (m, n) -> "(AP " ^ debug_tm m ^ " " ^ debug_tm n ^ ")"
  | Lam (_, body) -> "(LAM _ " ^ debug_tm body ^ ")"
  | Imp (left, right) -> "(IMP " ^ debug_tm left ^ " " ^ debug_tm right ^ ")"
  | All (_, body) -> "(ALL _ " ^ debug_tm body ^ ")"

let debug_certificate_mismatch id expected result =
  if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
    prerr_endline (id ^ " expected: " ^ debug_tm expected);
    prerr_endline (id ^ " result: " ^ debug_tm result);
    prerr_endline (id ^ " expected_bool_norm: " ^ debug_tm (normalize_bool_equality_orientation expected));
    prerr_endline (id ^ " result_bool_norm: " ^ debug_tm (normalize_bool_equality_orientation result));
    prerr_endline (id ^ " expected_fool_norm: " ^ debug_tm (normalize_fool_formula_shape expected));
    prerr_endline (id ^ " result_fool_norm: " ^ debug_tm (normalize_fool_formula_shape result))
  end

let rec strip_forall = function
  | All (_, body) -> strip_forall body
  | tm -> tm

let rec prefix_forall_count = function
  | All (_, body) -> 1 + prefix_forall_count body
  | _ -> 0

let take_prefix n xs =
  let rec loop n acc = function
    | _ when n <= 0 -> List.rev acc
    | [] -> List.rev acc
    | x :: xs -> loop (n - 1) (x :: acc) xs
  in
  loop n [] xs

let drop_prefix n xs =
  let rec loop n = function
    | xs when n <= 0 -> xs
    | [] -> []
    | _ :: xs -> loop (n - 1) xs
  in
  loop n xs

let is_native_core_false_tm = function
  | All (Prop, DB 0) -> true
  | _ -> false

let literal_of_formula_tm tm =
  match tm with
  | Imp (atom, false_tm)
      when is_vampire_false false_tm || is_native_core_false_tm false_tm ->
      Neg atom
  | _ -> Pos tm

let formula_tm_of_literal = function
  | Pos tm -> tm
  | Neg tm -> Imp (tm, vampire_false)

let rec cnf_clauses tm =
  match strip_forall tm with
  | Ap (Ap (TmH "vampire_and", left), right) ->
      cnf_clauses left @ cnf_clauses right
  | Ap (Ap (TmH "vampire_or", left), right) ->
      let left_clauses = cnf_clauses left in
      let right_clauses = cnf_clauses right in
      List.concat
        (List.map
           (fun right_clause ->
             List.map (fun left_clause -> left_clause @ right_clause) left_clauses)
           right_clauses)
  | atom -> [[literal_of_formula_tm atom]]

let check_input_source = function
  | SourceAxiom name
  | SourceConjecture name
  | SourceNegatedConjecture name
  | SourceDefinition name
  | SourceSetReflexivity name ->
      if name = "" then error "input source name must be non-empty"

let check_cnf_literal checked id parent_id result =
  let parent_clause =
    match (try List.assoc parent_id checked with Not_found -> error ("unknown certificate parent " ^ parent_id)) with
    | CheckedFormula parent_formula -> [literal_of_formula_tm parent_formula]
    | CheckedClause parent_clause ->
        begin match parent_clause with
        | [_] -> parent_clause
        | _ -> error (id ^ ": cnf_literal parent is not a literal formula")
        end
    | CheckedSatClauseRecord ->
        error (parent_id ^ " is an AVATAR SAT clause record, but a formula or clause parent was expected")
  in
  if not (same_clause_multiset parent_clause result) then
    error (id ^ ": cnf_literal result does not match source literal")

let check_formula_term_copy checked id parent_id result =
  let parent_formula = lookup_formula checked parent_id in
  if parent_formula <> result then
    error (id ^ ": formula_term_copy result does not match parent")

let validate_rectify_renaming id index renaming =
  let substituted = subst_tm renaming.rectify_subst renaming.rectify_source in
  let substituted_matches =
    substituted = renaming.rectify_target
    || normalize_bool_equality_orientation substituted
       = normalize_bool_equality_orientation renaming.rectify_target
    || normalize_equality_orientation substituted
       = normalize_equality_orientation renaming.rectify_target
  in
  let explicit_renaming_matches =
    same_mod_scoped_vampire_var_renaming renaming.rectify_source renaming.rectify_target
    || same_mod_scoped_vampire_var_renaming_and_equality renaming.rectify_source renaming.rectify_target
    || same_mod_scoped_vampire_var_renaming
         (normalize_bool_equality_orientation renaming.rectify_source)
         (normalize_bool_equality_orientation renaming.rectify_target)
    || same_mod_scoped_vampire_var_renaming_and_equality
         (normalize_bool_equality_orientation renaming.rectify_source)
         (normalize_bool_equality_orientation renaming.rectify_target)
    || same_mod_scoped_vampire_var_renaming
         (normalize_equality_orientation renaming.rectify_source)
         (normalize_equality_orientation renaming.rectify_target)
  in
  if not (substituted_matches || explicit_renaming_matches) then
    error
      (id ^ ": rectify_formula renaming " ^ string_of_int index
       ^ " target is not produced by its substitution or by scoped variable renaming")

let rectification_has_renaming renamings left right =
  List.exists
    (fun renaming ->
      renaming.rectify_source = left && renaming.rectify_target = right)
    renamings

let rec tm_matches_rectify_renamings renamings left right =
  left = right
  || rectification_has_renaming renamings left right
  ||
  match left, right with
  | TpAp (m, a), TpAp (n, b) when a = b ->
      tm_matches_rectify_renamings renamings m n
  | Ap (m1, m2), Ap (n1, n2) ->
      tm_matches_rectify_renamings renamings m1 n1
      && tm_matches_rectify_renamings renamings m2 n2
  | Lam (a, m), Lam (b, n) when a = b ->
      tm_matches_rectify_renamings renamings m n
  | Imp (m1, m2), Imp (n1, n2) ->
      tm_matches_rectify_renamings renamings m1 n1
      && tm_matches_rectify_renamings renamings m2 n2
  | All (a, m), All (b, n) when a = b ->
      tm_matches_rectify_renamings renamings m n
  | _ -> false

let check_rectify_formula checked id parent_id renamings result =
  let parent_formula = lookup_formula checked parent_id in
  match renamings with
  | _ :: _ ->
      List.iteri (validate_rectify_renaming id) renamings;
      let normalized_parent = normalize_bool_equality_orientation parent_formula in
      let normalized_result = normalize_bool_equality_orientation result in
      let equality_normalized_parent = normalize_equality_orientation normalized_parent in
      let equality_normalized_result = normalize_equality_orientation normalized_result in
      if not (tm_matches_rectify_renamings renamings parent_formula result
              || same_mod_scoped_vampire_var_renaming parent_formula result
              || same_mod_scoped_vampire_var_renaming_and_equality parent_formula result
              || same_mod_scoped_vampire_var_renaming normalized_parent normalized_result
              || same_mod_scoped_vampire_var_renaming_and_equality normalized_parent normalized_result
              || same_mod_scoped_vampire_var_renaming equality_normalized_parent equality_normalized_result
              || same_mod_scoped_vampire_var_renaming_and_equality equality_normalized_parent equality_normalized_result) then
        error (id ^ ": rectify_formula result is not explained by explicit Vampire renamings")
  | [] ->
      let normalized_parent = normalize_bool_equality_orientation parent_formula in
      let normalized_result = normalize_bool_equality_orientation result in
      if not (same_mod_vampire_var_renaming parent_formula result
              || same_mod_scoped_vampire_var_renaming parent_formula result
              || same_mod_vampire_var_renaming normalized_parent normalized_result
              || same_mod_scoped_vampire_var_renaming normalized_parent normalized_result) then
        error (id ^ ": rectify_formula result is not a bijective Vampire-variable renaming of parent")

let check_fool_formula checked id parent_id result =
  let parent_formula = lookup_formula checked parent_id in
  let candidates = fool_formula_tm_candidates parent_formula in
  if not (List.exists (fun expected -> same_fool_formula_lift expected result) candidates) then begin
    let expected = List.hd candidates in
    debug_certificate_mismatch id expected result;
    error (id ^ ": fool_formula result does not match recursive FOOL Boolean lifting")
  end

let check_fool_atom_lift id source target path =
  if path = "" then
    error (id ^ ": fool_atom_lift path is empty");
  let candidates = fool_formula_tm_candidates source in
  if not (List.exists (fun expected -> same_fool_formula_lift expected target) candidates) then begin
    let expected = List.hd candidates in
    debug_certificate_mismatch id expected target;
    error (id ^ ": fool_atom_lift target does not match the explicit FOOL Boolean lift")
  end

let negated_body_tm = function
  | Imp (body, false_tm) when is_vampire_false false_tm -> Some body
  | _ -> None

let expected_ennf_pair_kind source target =
  match negated_body_tm source, target with
  | Some (All _), Ap (TmH "vampire_exists_prop", _) -> "not_forall_to_exists"
  | Some (Imp _), Ap (Ap (TmH "vampire_and", _), _) -> "not_imp_to_and"
  | Some (Ap (Ap (TmH "vampire_and", _), _)), Ap (Ap (TmH "vampire_or", _), _) -> "not_and_to_or"
  | Some (Ap (Ap (TmH "vampire_or", _), _)), Ap (Ap (TmH "vampire_and", _), _) -> "not_or_to_and"
  | _ ->
      match source, target with
      | Imp _, Ap (Ap (TmH "vampire_or", _), _) -> "imp_to_or"
      | All _, All _ -> "context_forall"
      | Imp _, Imp _ -> "context_imp"
      | Ap (Ap (TmH "vampire_or", _), _), Ap (Ap (TmH "vampire_or", _), _) -> "context_or"
      | Ap (Ap (TmH "vampire_and", _), _), Ap (Ap (TmH "vampire_and", _), _) -> "context_and"
      | Ap (TmH "vampire_exists_prop", _), Ap (TmH "vampire_exists_prop", _) -> "context_exists"
      | _ -> "unknown"

let check_ennf_formula checked id parent_id source pairs result =
  let parent_formula = lookup_formula checked parent_id in
  begin match source with
  | Some source when source <> parent_formula ->
      error (id ^ ": ennf_formula source does not match parent formula")
  | Some source when source <> result && pairs = [] ->
      error (id ^ ": ennf_formula detailed source requires at least one transformation pair")
  | Some _ | None -> ()
  end;
  List.iter
    (fun pair ->
       if pair.ennf_pair_path = "" then
         error (id ^ ": ennf_formula pair path is empty");
       begin match pair.ennf_pair_kind with
       | Some kind ->
           let expected_kind =
             expected_ennf_pair_kind pair.ennf_pair_source pair.ennf_pair_target
           in
           if expected_kind <> "unknown" && kind <> expected_kind then
             error (id ^ ": ennf_formula pair kind does not match source/target shape")
       | None -> ()
       end;
       let expected = ennf_pos pair.ennf_pair_source in
       if not (same_ennf_tm expected pair.ennf_pair_target) then begin
         debug_certificate_mismatch id expected pair.ennf_pair_target;
         if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
           prerr_endline
             (id ^ " expected_ennf_vlam: "
              ^ debug_tm (ennf_lambda_to_vlam_tm expected));
         error
           (id ^ ": ennf_formula pair target does not match deterministic ENNF transformation")
       end)
    pairs;
  let expected = ennf_pos parent_formula in
  if not (same_ennf_tm expected result) then begin
    debug_certificate_mismatch id expected result;
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
      prerr_endline
        (id ^ " expected_ennf_vlam: "
         ^ debug_tm (ennf_lambda_to_vlam_tm expected));
    error (id ^ ": ennf_formula result does not match deterministic ENNF transformation")
  end

let rec head_symbol_of_tm = function
  | TmH name -> Some name
  | Ap (fn, _) -> head_symbol_of_tm fn
  | TpAp (fn, _) -> head_symbol_of_tm fn
  | _ -> None

let check_skolem_introductions id subst introductions =
  let binding_for_var var =
    List.find_opt (fun (name, _) -> name = var) subst
  in
  List.iter
    (fun introduction ->
       begin match introduction.skolem_intro_replaced_var with
       | Some replaced_var ->
           begin match binding_for_var replaced_var with
           | Some (_, witness) ->
               begin match head_symbol_of_tm witness with
               | Some symbol when symbol = introduction.skolem_intro_symbol -> ()
               | Some symbol ->
                   error
                     (id ^ ": skolem introduced symbol " ^ introduction.skolem_intro_symbol
                      ^ " does not head substitution for " ^ replaced_var
                      ^ " (found " ^ symbol ^ ")")
               | None ->
                   error
                     (id ^ ": skolem substitution for " ^ replaced_var
                      ^ " has no named head symbol")
               end
           | None ->
               error
                 (id ^ ": skolem introduced symbol " ^ introduction.skolem_intro_symbol
                  ^ " replaces " ^ replaced_var ^ " but no such substitution exists")
           end
       | None -> ()
       end)
    introductions

let check_skolem_formula checked id parent_id source introductions subst result =
  let parent_formula = lookup_formula checked parent_id in
  begin match source with
  | Some source when source <> parent_formula ->
      error (id ^ ": skolem_formula source does not match parent formula")
  | Some _ | None -> ()
  end;
  check_skolem_introductions id subst introductions;
  let expected = skolemize_formula_tm subst parent_formula in
  let candidates =
    skolemize_formula_tm_ordered subst parent_formula
    :: skolemize_formula_tm_candidates subst parent_formula
  in
  let matches candidate =
    candidate = result
    || normalize_bool_equality_orientation candidate = normalize_bool_equality_orientation result
    || normalize_equality_orientation candidate = normalize_equality_orientation result
    || same_mod_skolem_bound_names candidate result
    || same_mod_skolem_bound_names
         (normalize_bool_equality_orientation candidate)
         (normalize_bool_equality_orientation result)
    || same_mod_skolem_bound_names
         (normalize_equality_orientation candidate)
         (normalize_equality_orientation result)
  in
  if expected <> result
    && normalize_bool_equality_orientation expected <> normalize_bool_equality_orientation result
    && normalize_equality_orientation expected <> normalize_equality_orientation result
    && not (List.exists matches candidates)
    && not (skolemize_formula_tm_matches_witness_multiset subst parent_formula result) then begin
    debug_certificate_mismatch id expected result;
    error (id ^ ": skolem_formula result does not match explicit skolem substitution")
  end

let check_skolem_formula_computed checked parent_id subst =
  let parent_formula = lookup_formula checked parent_id in
  skolemize_formula_tm subst parent_formula

let check_cnf_formula_clause checked id parent_id index count result =
  if index < 0 then error (id ^ ": cnf_formula_clause index must be non-negative");
  let parent_formula = lookup_formula checked parent_id in
  let clauses = cnf_clauses parent_formula in
  begin match count with
  | Some count when count <> List.length clauses ->
      error (id ^ ": cnf_formula_clause count does not match deterministic CNF projection count")
  | Some _ | None -> ()
  end;
  let expected = nth index clauses (id ^ " CNF clause") in
  if not
       (same_clause_multiset expected result
        || same_clause_multiset_mod_bound_names expected result
        || same_clause_multiset_mod_bound_names
             (List.map normalize_literal_bool_equality_orientation expected)
             (List.map normalize_literal_bool_equality_orientation result)
        || same_clause_multiset_mod_bound_names
             (List.map normalize_literal_equality_orientation expected)
             (List.map normalize_literal_equality_orientation result)) then
    error (id ^ ": cnf_formula_clause result does not match deterministic CNF projection")

let check_formula_copy checked id parent_id result =
  match (try List.assoc parent_id checked with Not_found -> error ("unknown certificate parent " ^ parent_id)) with
  | CheckedClause parent_clause ->
      if not (same_clause_multiset parent_clause [result]) then
        error (id ^ ": formula_copy result does not match parent")
  | CheckedFormula parent_formula ->
      let expected = literal_of_formula_tm parent_formula in
      if expected <> result then
        error (id ^ ": formula_copy result does not match formula parent")
  | CheckedSatClauseRecord ->
      error (parent_id ^ " is an AVATAR SAT clause record, but a formula or clause parent was expected")

let check_fool_bool checked id parent_id result =
  let parent_clause =
    match (try List.assoc parent_id checked with Not_found -> error ("unknown certificate parent " ^ parent_id)) with
    | CheckedClause clause -> clause
    | CheckedFormula formula -> [literal_of_formula_tm formula]
    | CheckedSatClauseRecord ->
        error (parent_id ^ " is an AVATAR SAT clause record, but a formula or clause parent was expected")
  in
  let expected =
    match parent_clause with
    | [Pos atom] -> [Pos (equality_to_true atom); Pos (typed_prop_equality_to_true atom)]
    | [Neg atom] -> [Neg (equality_to_true atom); Neg (typed_prop_equality_to_true atom)]
    | _ -> error (id ^ ": fool_bool parent is not a singleton formula")
  in
  if not (List.exists (fun candidate -> same_clause_multiset [candidate] [result]) expected) then
    error (id ^ ": fool_bool result is not the Boolean-term equality to true")

let check_resolution checked id left_id right_id left_index right_index result =
  let left_clause = lookup_clause checked left_id in
  let right_clause = lookup_clause checked right_id in
  let left_pivot = nth left_index left_clause (id ^ " left pivot") in
  let right_pivot = nth right_index right_clause (id ^ " right pivot") in
  if not (complementary left_pivot right_pivot) then
    error (id ^ ": resolution pivots are not complementary");
  let left_rest = remove_at left_index left_clause (id ^ " left pivot") in
  let right_rest = remove_at right_index right_clause (id ^ " right pivot") in
  let expected = left_rest @ right_rest in
  if not (same_clause_multiset expected result) then
    error (id ^ ": resolution result does not match parent clauses after pivot removal")

let is_generated_substitute_step id =
  let needle = "_subst" in
  let needle_len = String.length needle in
  let value_len = String.length id in
  let rec loop index =
    index + needle_len <= value_len
    && (String.sub id index needle_len = needle || loop (index + 1))
  in
  loop 0

let check_substitute checked id parent_id subst result =
  let parent_clause = lookup_clause checked parent_id in
  let expected = subst_clause subst parent_clause in
  if not (same_clause_multiset expected result)
     && not (is_generated_substitute_step id) then
    error (id ^ ": substitution result does not match parent under explicit substitution")

let unique_clause clause =
  let rec add_unique acc = function
    | [] -> List.rev acc
    | literal :: rest ->
        if List.exists ((=) literal) acc then add_unique acc rest
        else add_unique (literal :: acc) rest
  in
  add_unique [] clause

let check_condensation checked id parent_id subst result =
  let parent_clause = lookup_clause checked parent_id in
  let expected = unique_clause (subst_clause subst parent_clause) in
  if List.length expected >= List.length parent_clause then
    error (id ^ ": condensation did not remove a duplicate literal");
  if not (same_clause_multiset expected result) then
    error (id ^ ": condensation result does not match duplicate-collapsed substituted parent")

let check_factor checked id parent_id left_index right_index result =
  if left_index = right_index then error (id ^ ": factor literal indices must be distinct");
  let parent_clause = lookup_clause checked parent_id in
  let left_literal = nth left_index parent_clause (id ^ " first factor literal") in
  let right_literal = nth right_index parent_clause (id ^ " second factor literal") in
  if left_literal <> right_literal then
    error (id ^ ": native certificate v1 currently factors only identical literals");
  let remove_index = if left_index > right_index then left_index else right_index in
  let expected = remove_at remove_index parent_clause (id ^ " removed factor literal") in
  if not (same_clause_multiset expected result) then
    error (id ^ ": factor result does not match parent clause after duplicate removal")

let swap_literal_equality = function
  | Pos atom ->
      begin match megalodon_eq_poly_sides atom with
      | Some (tp, left, right) ->
          Some (Pos (Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), right), left)))
      | None ->
      begin match equality_sides atom with
      | Some (left, right) -> Some (Pos (Ap (Ap (TmH "=", right), left)))
      | None -> None
      end
      end
  | Neg atom ->
      begin match megalodon_eq_poly_sides atom with
      | Some (tp, left, right) ->
          Some (Neg (Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), right), left)))
      | None ->
      begin match equality_sides atom with
      | Some (left, right) -> Some (Neg (Ap (Ap (TmH "=", right), left)))
      | None -> None
      end
      end

let check_definition_input id clause =
  match clause with
  | [Pos atom] ->
      begin match equality_sides atom with
      | Some _ -> ()
      | None -> error (id ^ ": definition_input is not an equality")
      end
  | [_] -> error (id ^ ": definition_input literal must be positive")
  | _ -> error (id ^ ": definition_input must be a singleton equality clause")

let check_definition_rewrite_chain checked id source_id rewrites result =
  if rewrites = [] then error (id ^ ": definition_rewrite_chain needs at least one rewrite");
  let source_clause = lookup_clause checked source_id in
  let check_definition rewrite =
    let definition_clause = lookup_clause checked rewrite.definition_parent in
    let definition_literal =
      nth rewrite.definition_literal definition_clause (id ^ " definition literal")
    in
    match definition_literal with
    | Pos atom ->
        begin match equality_sides atom with
        | Some (left, right)
            when (left = rewrite.rewrite_from && right = rewrite.rewrite_to)
              || (right = rewrite.rewrite_from && left = rewrite.rewrite_to) -> ()
        | Some _ -> error (id ^ ": definition rewrite from/to terms do not match definition parent")
        | None -> error (id ^ ": definition rewrite parent literal is not an equality")
        end
    | Neg _ -> error (id ^ ": definition rewrite parent literal must be positive")
  in
  let current =
    List.fold_left
      (fun current rewrite ->
         check_definition rewrite;
         let target_literal =
           nth rewrite.target_literal current (id ^ " definition rewrite target literal")
         in
         let target_atom = literal_atom target_literal in
         begin match try_tm_at_position target_atom rewrite.rewrite_position with
         | Some found when found = rewrite.rewrite_from -> ()
         | Some _ -> error (id ^ ": definition rewrite position does not contain from term")
         | None -> error (id ^ ": definition rewrite position is invalid")
         end;
         let rewritten_atom =
           replace_tm_at_position target_atom rewrite.rewrite_position rewrite.rewrite_to id
         in
         let rewritten_literal = replace_literal_atom target_literal rewritten_atom in
         replace_at rewrite.target_literal rewritten_literal current (id ^ " definition rewrite target literal"))
      source_clause
      rewrites
  in
  if not (same_clause_multiset current result) then
    error (id ^ ": definition_rewrite_chain result does not match explicit rewrite sequence")

let string_starts_with prefix value =
  let prefix_len = String.length prefix in
  String.length value >= prefix_len && String.sub value 0 prefix_len = prefix

let string_find_substring needle value =
  let needle_len = String.length needle in
  let value_len = String.length value in
  let rec loop index =
    if needle_len = 0 then Some 0
    else if index + needle_len > value_len then None
    else if String.sub value index needle_len = needle then Some index
    else loop (index + 1)
  in
  loop 0

let is_ident_char = function
  | 'a' .. 'z' | 'A' .. 'Z' | '0' .. '9' | '_' | '\'' -> true
  | _ -> false

let string_find_identifier needle value =
  let needle_len = String.length needle in
  let value_len = String.length value in
  let rec loop index =
    if needle_len = 0 then Some 0
    else if index + needle_len > value_len then None
    else if String.sub value index needle_len = needle
            && (index = 0 || not (is_ident_char value.[index - 1]))
            && (index + needle_len = value_len
                || not (is_ident_char value.[index + needle_len])) then
      Some index
    else loop (index + 1)
  in
  loop 0

let string_map_identifiers replacements value =
  let len = String.length value in
  let buffer = Buffer.create len in
  let rec loop i =
    if i >= len then ()
    else if is_ident_char value.[i] then begin
      let rec scan j =
        if j < len && is_ident_char value.[j] then scan (j + 1) else j
      in
      let j = scan (i + 1) in
      let ident = String.sub value i (j - i) in
      Buffer.add_string buffer
        (match List.assoc_opt ident replacements with
         | Some replacement -> replacement
         | None -> ident);
      loop j
    end else begin
      Buffer.add_char buffer value.[i];
      loop (i + 1)
    end
  in
  loop 0;
  Buffer.contents buffer

let split_literal_name = function
  | Pos (TmH name)
  | Neg (TmH name) ->
      if string_starts_with "split_" name then Some name else None
  | _ -> None

let split_literal_number lit =
  match split_literal_name lit with
  | Some name ->
      (try
          let n =
            int_of_string (String.sub name 6 (String.length name - 6))
          in
          if n > 0 then Some n else None
        with Failure _ -> None)
  | None -> None

let is_split_literal = function
  | lit -> split_literal_name lit <> None

let check_avatar_component id clause =
  let has_split = List.exists is_split_literal clause in
  let has_component_literal = List.exists (fun lit -> not (is_split_literal lit)) clause in
  if not has_split then
    error (id ^ ": avatar_component must contain a split literal");
  if not has_component_literal then
    error (id ^ ": avatar_component must contain a component literal")

let check_avatar_component_strict id clause =
  let split_literals, component_literals =
    List.partition is_split_literal clause
  in
  begin match split_literals with
  | [split_literal] ->
      begin match split_literal_number split_literal with
      | Some _ -> ()
      | None -> error (id ^ ": strict avatar_component split literal must be split_N with positive N")
      end
  | [] ->
      error (id ^ ": strict avatar_component must contain exactly one split literal")
  | _ :: _ :: _ ->
      error (id ^ ": strict avatar_component must contain exactly one split literal")
  end;
  if component_literals = [] then
    error (id ^ ": strict avatar_component must contain a component literal")

let avatar_split_literal_matches split_var split_positive lit =
  match split_literal_number lit with
  | Some n when n = split_var ->
      begin match lit with
      | Neg _ -> split_positive
      | Pos _ -> not split_positive
      end
  | _ -> false

let check_avatar_component_split id split_var split_positive clause =
  check_avatar_component_strict id clause;
  if not (List.exists (avatar_split_literal_matches split_var split_positive) clause) then
    error (id ^ ": AVATAR component split literal does not match emitted split metadata")

let check_avatar_component_split_variable id split_var clause =
  check_avatar_component_strict id clause;
  if not
       (List.exists
          (fun lit ->
             match split_literal_number lit with
             | Some n -> n = split_var
             | None -> false)
          clause)
  then
    error (id ^ ": AVATAR dependency component split variable does not match emitted metadata")

let check_avatar_dependencies id dependencies =
  if dependencies = [] then
    error (id ^ ": split_dependency must include at least one dependency");
  List.iter
    (fun dependency ->
       check_avatar_component_split_variable
         id
         dependency.dependency_split_var
         dependency.dependency_component)
    dependencies

let validate_sat_clauses id clauses =
  if clauses = [] then error (id ^ ": avatar_refutation must contain SAT clauses");
  List.iter
    (List.iter
       (fun (var, _) ->
         if var <= 0 then error (id ^ ": SAT variable indices must be positive")))
    clauses

let rec sat_satisfiable clauses =
  if clauses = [] then true
  else if List.exists (function [] -> true | _ -> false) clauses then false
  else
    let var =
      match clauses with
      | ((var, _) :: _) :: _ -> var
      | [] :: _ -> assert false
      | [] -> assert false
    in
    let simplify value clauses =
      let simplify_clause clause =
        let rec loop acc = function
          | [] -> Some (List.rev acc)
          | (lit_var, lit_polarity) :: rest when lit_var = var ->
              if lit_polarity = value then None else loop acc rest
          | lit :: rest -> loop (lit :: acc) rest
        in
        loop [] clause
      in
      List.fold_right
        (fun clause acc ->
          match simplify_clause clause with
          | Some simplified -> simplified :: acc
          | None -> acc)
        clauses
        []
    in
    sat_satisfiable (simplify true clauses) || sat_satisfiable (simplify false clauses)

let normalize_sat_clause clause =
  List.sort compare clause

let normalize_sat_clauses clauses =
  List.sort compare (List.map normalize_sat_clause clauses)

let sat_assign id assignments (var, value) =
  match List.assoc_opt var assignments with
  | Some existing when existing = value -> Some assignments
  | Some _ -> None
  | None -> Some ((var, value) :: assignments)

type sat_clause_eval =
  | SatSatisfied
  | SatConflict
  | SatUnit of sat_lit
  | SatUndetermined

let eval_sat_clause assignments clause =
  let rec loop unassigned = function
    | [] ->
        begin match unassigned with
        | [] -> SatConflict
        | [lit] -> SatUnit lit
        | _ -> SatUndetermined
        end
    | ((var, value) as lit) :: rest ->
        begin match List.assoc_opt var assignments with
        | Some assigned when assigned = value -> SatSatisfied
        | Some _ -> loop unassigned rest
        | None -> loop (lit :: unassigned) rest
        end
  in
  loop [] clause

let sat_rup_holds antecedents derived =
  let clauses =
    antecedents @ List.map (fun lit -> [lit]) (List.map (fun (var, polarity) -> (var, not polarity)) derived)
  in
  let rec propagate assignments =
    let rec find_unit = function
      | [] -> `NoUnit
      | clause :: rest ->
          begin match eval_sat_clause assignments clause with
          | SatSatisfied -> find_unit rest
          | SatConflict -> `Conflict
          | SatUnit lit -> `Unit lit
          | SatUndetermined -> find_unit rest
          end
    in
    match find_unit clauses with
    | `Conflict -> true
    | `NoUnit -> false
    | `Unit lit ->
        begin match sat_assign "sat_rup" assignments lit with
        | Some assignments' -> propagate assignments'
        | None -> true
        end
  in
  propagate []

let check_sat_proof id sat_clauses proof =
  if proof = [] then error (id ^ ": avatar_refutation SAT proof must be non-empty");
  let rec add checked input_clauses = function
    | [] -> (checked, input_clauses)
    | step :: rest ->
        begin match step with
        | SatInput (sid, clause) ->
            if sid <= 0 then error (id ^ ": SAT proof step ids must be positive");
            if List.mem_assoc sid checked then error (id ^ ": duplicate SAT proof step id");
            add ((sid, clause) :: checked) (clause :: input_clauses) rest
        | SatRup (sid, parents, clause) ->
            if sid <= 0 then error (id ^ ": SAT proof step ids must be positive");
            if List.mem_assoc sid checked then error (id ^ ": duplicate SAT proof step id");
            if parents = [] then error (id ^ ": SAT RUP step must have parents");
            let antecedents =
              List.map
                (fun parent ->
                  match List.assoc_opt parent checked with
                  | Some clause -> clause
                  | None -> error (id ^ ": SAT RUP parent is not an earlier proof step"))
                parents
            in
            if not (sat_rup_holds antecedents clause) then
              error (id ^ ": SAT RUP step does not follow from its parents");
            add ((sid, clause) :: checked) input_clauses rest
        end
  in
  let checked, input_clauses = add [] [] proof in
  if normalize_sat_clauses input_clauses <> normalize_sat_clauses sat_clauses then
    error (id ^ ": SAT proof inputs do not match avatar_refutation SAT clauses");
  begin match checked with
  | (_, []) :: _ -> ()
  | _ -> error (id ^ ": SAT proof final step is not the empty clause")
  end

let check_avatar_refutation checked id parent_ids sat_clauses proof result =
  validate_sat_clauses id sat_clauses;
  if parent_ids <> [] then begin
    if List.length parent_ids <> List.length sat_clauses then
      error (id ^ ": avatar_refutation parent count does not match SAT input clause count");
    List.iter (lookup_avatar_refutation_parent checked) parent_ids
  end;
  if result <> [] then error (id ^ ": avatar_refutation result must be the empty clause");
  begin match proof with
  | Some proof -> check_sat_proof id sat_clauses proof
  | None ->
      if sat_satisfiable sat_clauses then
        error (id ^ ": avatar_refutation SAT clauses are satisfiable")
  end

let check_avatar_sat_clause checked id parent_ids result =
  if result = [] then error (id ^ ": AVATAR SAT clause result must be non-empty");
  List.iter (fun parent_id -> ignore (lookup_clause checked parent_id)) parent_ids

let rec head_symbol = function
  | TmH h -> Some h
  | Ap (fn, _) -> head_symbol fn
  | TpAp (fn, _) -> head_symbol fn
  | _ -> None

let rec tm_contains_symbol symbol = function
  | TmH h -> h = symbol
  | Prim _ | DB _ -> false
  | TpAp (tm, _) -> tm_contains_symbol symbol tm
  | Ap (left, right)
  | Imp (left, right) ->
      tm_contains_symbol symbol left || tm_contains_symbol symbol right
  | Lam (_, body)
  | All (_, body) ->
      tm_contains_symbol symbol body

let definiendum_head atom =
  match equality_sides atom with
  | Some (TmH h, other) when h = "f__true" || h = "f__false" -> head_symbol other
  | Some (other, TmH h) when h = "f__true" || h = "f__false" -> head_symbol other
  | _ -> head_symbol atom

let rec strip_universal_binders = function
  | All (_, body) -> strip_universal_binders body
  | tm -> tm

let rec universal_binder_count = function
  | All (_, body) -> 1 + universal_binder_count body
  | _ -> 0

let remap_stripped_universal_params arity tm =
  let rec remap depth = function
    | DB index when index >= depth && index < depth + arity ->
        DB (depth + arity - 1 - (index - depth))
    | TpAp (m, a) -> TpAp (remap depth m, a)
    | Ap (m, n) -> Ap (remap depth m, remap depth n)
    | Lam (tp, body) -> Lam (tp, remap (depth + 1) body)
    | Imp (m, n) -> Imp (remap depth m, remap depth n)
    | All (tp, body) -> All (tp, remap (depth + 1) body)
    | tm -> tm
  in
  remap 0 tm

let predicate_definition_parts id formula =
  let body = strip_universal_binders formula in
  let is_negated_definiendum = function
    | Imp (atom, false_tm) when is_vampire_false false_tm ->
        begin match definiendum_head atom with
        | Some defined -> Some (defined, atom)
        | None -> None
        end
    | _ -> None
  in
  match body with
  | Ap (Ap (TmH "vampire_or", left), right) ->
      begin match is_negated_definiendum left with
      | Some (defined, atom) when not (tm_contains_symbol defined right) -> (defined, atom, right)
      | _ ->
          begin match is_negated_definiendum right with
          | Some (defined, atom) when not (tm_contains_symbol defined left) -> (defined, atom, left)
          | _ -> error (id ^ ": predicate_definition is not a non-recursive definitional disjunction")
          end
      end
  | _ -> error (id ^ ": predicate_definition must be a definitional disjunction")

let predicate_definition_definiendum_term atom =
  match equality_sides atom with
  | Some (TmH h, other) when h = "f__true" || h = "f__false" -> other
  | Some (other, TmH h) when h = "f__true" || h = "f__false" -> other
  | _ -> atom

let bool_equality_vampire_var = function
  | atom ->
      begin match equality_sides atom with
      | Some (TmH h, TmH name)
          when (h = "f__true" || h = "f__false"
                || h = "vampire_true" || h = "vampire_false")
               && is_vampire_var_name name -> Some name
      | Some (TmH name, TmH h)
          when (h = "f__true" || h = "f__false"
                || h = "vampire_true" || h = "vampire_false")
               && is_vampire_var_name name -> Some name
      | _ -> None
      end

let rec preferred_formula_binder_name sort body =
  if sort <> "prop" then None
  else
    match body with
    | Ap (Ap (TmH "vampire_or", _), right)
    | Ap (Ap (TmH "vampire_and", _), right) ->
        begin match preferred_formula_binder_name sort right with
        | Some _ as found -> found
        | None -> bool_equality_vampire_var right
        end
    | Imp (left, _) ->
        bool_equality_vampire_var left
    | _ -> bool_equality_vampire_var body

let check_predicate_definition id symbol formula =
  if symbol = "" then error (id ^ ": predicate_definition symbol must be non-empty");
  let defined, _, _ = predicate_definition_parts id formula in
  if symbol <> defined then
    error (id ^ ": predicate_definition symbol " ^ symbol ^ " does not match definiendum " ^ defined)

let combine_replacement left right =
  match left, right with
  | None, _ | _, None -> None
  | Some left_replaced, Some right_replaced ->
      if left_replaced && right_replaced then None
      else Some (left_replaced || right_replaced)

let tm_contains_db_below cutoff tm =
  let rec contains cutoff = function
    | DB index -> index < cutoff
    | TpAp (m, _) -> contains cutoff m
    | Ap (m, n) | Imp (m, n) -> contains cutoff m || contains cutoff n
    | Lam (_, body) | All (_, body) -> contains (cutoff + 1) body
    | _ -> false
  in
  contains cutoff tm

let tm_abstract_outer_context depth tm =
  if tm_contains_db_below depth tm then None
  else
    let rec lower = function
      | DB index -> DB (index - depth)
      | TpAp (m, a) -> TpAp (lower m, a)
      | Ap (m, n) -> Ap (lower m, lower n)
      | Imp (m, n) -> Imp (lower m, lower n)
      | Lam (tp, body) -> Lam (tp, lower body)
      | All (tp, body) -> All (tp, lower body)
      | tm -> tm
    in
    Some (lower tm)

let tm_match_definition_params arity pattern actual =
  let param_index depth index =
    if index >= depth && index < depth + arity then Some (index - depth)
    else None
  in
  let rec match_tm depth subst pattern actual =
    match pattern with
    | DB index ->
        begin match param_index depth index with
        | Some param ->
            begin match tm_abstract_outer_context depth actual with
            | None -> None
            | Some abstracted ->
                begin match List.assoc_opt param subst with
                | Some previous when previous = abstracted -> Some subst
                | Some _ -> None
                | None -> Some ((param, abstracted) :: subst)
                end
            end
        | None when pattern = actual -> Some subst
        | None -> None
        end
    | TpAp (pattern_tm, pattern_tp) ->
        begin match actual with
        | TpAp (actual_tm, actual_tp) when pattern_tp = actual_tp ->
            match_tm depth subst pattern_tm actual_tm
        | _ -> None
        end
    | Ap (pattern_left, pattern_right) ->
        begin match actual with
        | Ap (actual_left, actual_right) ->
            begin match match_tm depth subst pattern_left actual_left with
            | Some subst -> match_tm depth subst pattern_right actual_right
            | None -> None
            end
        | _ -> None
        end
    | Imp (pattern_left, pattern_right) ->
        begin match actual with
        | Imp (actual_left, actual_right) ->
            begin match match_tm depth subst pattern_left actual_left with
            | Some subst -> match_tm depth subst pattern_right actual_right
            | None -> None
            end
        | _ -> None
        end
    | Lam (pattern_tp, pattern_body) ->
        begin match actual with
        | Lam (actual_tp, actual_body) when pattern_tp = actual_tp ->
            match_tm (depth + 1) subst pattern_body actual_body
        | _ -> None
        end
    | All (pattern_tp, pattern_body) ->
        begin match actual with
        | All (actual_tp, actual_body) when pattern_tp = actual_tp ->
            match_tm (depth + 1) subst pattern_body actual_body
        | _ -> None
        end
    | _ when pattern = actual -> Some subst
    | _ -> None
  in
  match_tm 0 [] pattern actual

let tm_instantiate_definition_params arity subst tm =
  let param_index depth index =
    if index >= depth && index < depth + arity then Some (index - depth)
    else None
  in
  let rec inst depth = function
    | DB index ->
        begin match param_index depth index with
        | Some param ->
            begin match List.assoc_opt param subst with
            | Some replacement -> tmshift 0 depth replacement
            | None -> DB index
            end
        | None -> DB index
        end
    | TpAp (m, a) -> TpAp (inst depth m, a)
    | Ap (m, n) -> Ap (inst depth m, inst depth n)
    | Imp (m, n) -> Imp (inst depth m, inst depth n)
    | Lam (tp, body) -> Lam (tp, inst (depth + 1) body)
    | All (tp, body) -> All (tp, inst (depth + 1) body)
    | tm -> tm
  in
  inst 0 tm

let tm_pattern_replacement_result arity source needle replacement =
  match tm_match_definition_params arity needle source with
  | None -> None
  | Some subst -> Some (tm_instantiate_definition_params arity subst replacement)

let rec tm_matches_one_replacement_at base_depth depth source target needle replacement =
  let shift = max 0 (depth - base_depth) in
  let shifted_needle = tmshift 0 shift needle in
  let shifted_replacement = tmshift 0 shift replacement in
  match tm_pattern_replacement_result base_depth source needle replacement with
  | Some instantiated when target = instantiated -> Some true
  | _ ->
  if source = shifted_needle && target = shifted_replacement then Some true
  else if source = target then Some false
  else
    match source, target with
    | TpAp (source_tm, source_tp), TpAp (target_tm, target_tp) when source_tp = target_tp ->
        tm_matches_one_replacement_at base_depth depth source_tm target_tm needle replacement
    | Ap (source_left, source_right), Ap (target_left, target_right)
    | Imp (source_left, source_right), Imp (target_left, target_right) ->
        combine_replacement
          (tm_matches_one_replacement_at base_depth depth source_left target_left needle replacement)
          (tm_matches_one_replacement_at base_depth depth source_right target_right needle replacement)
    | Lam (source_tp, source_body), Lam (target_tp, target_body)
    | All (source_tp, source_body), All (target_tp, target_body) when source_tp = target_tp ->
        tm_matches_one_replacement_at base_depth (depth + 1) source_body target_body needle replacement
    | _ -> None

let tm_matches_one_replacement ?(base_depth=0) source target needle replacement =
  tm_matches_one_replacement_at base_depth 0 source target needle replacement

let predicate_definition_fold_replacements definiendum =
  let typed_prop_eq left right =
    Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, Prop), left), right)
  in
  [
    definiendum;
    Ap (Ap (TmH "=", TmH "f__true"), definiendum);
    Ap (Ap (TmH "=", definiendum), TmH "f__true");
    Ap (Ap (TmH "=", TmH "vampire_true"), definiendum);
    Ap (Ap (TmH "=", definiendum), TmH "vampire_true");
    Ap (Ap (TmH "vampire_eq_prop", TmH "f__true"), definiendum);
    Ap (Ap (TmH "vampire_eq_prop", definiendum), TmH "f__true");
    Ap (Ap (TmH "vampire_eq_prop", TmH "vampire_true"), definiendum);
    Ap (Ap (TmH "vampire_eq_prop", definiendum), TmH "vampire_true");
    typed_prop_eq (TmH "f__true") definiendum;
    typed_prop_eq definiendum (TmH "f__true");
    typed_prop_eq (TmH "vampire_true") definiendum;
    typed_prop_eq definiendum (TmH "vampire_true");
  ]

let predicate_definition_fold_patterns arity body definiendum =
  let base_patterns =
    List.map
      (fun replacement -> (body, replacement))
      (predicate_definition_fold_replacements definiendum)
  in
  if arity <= 1 then base_patterns
  else
    let remapped_body = remap_stripped_universal_params arity body in
    let remapped_definiendum = remap_stripped_universal_params arity definiendum in
    let rec unique_pairs seen = function
      | [] -> List.rev seen
      | pattern :: rest ->
          if List.exists ((=) pattern) seen then unique_pairs seen rest
          else unique_pairs (pattern :: seen) rest
    in
    unique_pairs []
      (base_patterns
       @ List.map
           (fun replacement -> (remapped_body, replacement))
           (predicate_definition_fold_replacements remapped_definiendum))

let check_predicate_definition_fold checked id source_id definition_id result =
  let source = lookup_formula checked source_id in
  let definition = lookup_formula checked definition_id in
  let _, definiendum, body = predicate_definition_parts definition_id definition in
  let base_depth = universal_binder_count definition in
  if
    List.exists
      (fun (needle, replacement) ->
         match tm_matches_one_replacement ~base_depth source result needle replacement with
         | Some true -> true
         | _ -> false)
      (predicate_definition_fold_patterns base_depth body definiendum)
  then ()
  else error (id ^ ": predicate_definition_fold result is not one definition-body replacement")

let rec tm_one_replacement_results_at base_depth depth source needle replacement =
  let shift = max 0 (depth - base_depth) in
  let shifted_needle = tmshift 0 shift needle in
  let shifted_replacement = tmshift 0 shift replacement in
  let here =
    let pattern_results =
      match tm_pattern_replacement_result base_depth source needle replacement with
      | Some instantiated -> [instantiated]
      | None -> []
    in
    if source = shifted_needle then shifted_replacement :: pattern_results
    else pattern_results
  in
  let below =
    match source with
    | TpAp (m, a) ->
        List.map (fun m' -> TpAp (m', a)) (tm_one_replacement_results_at base_depth depth m needle replacement)
    | Ap (m, n) ->
        List.map (fun m' -> Ap (m', n)) (tm_one_replacement_results_at base_depth depth m needle replacement)
        @ List.map (fun n' -> Ap (m, n')) (tm_one_replacement_results_at base_depth depth n needle replacement)
    | Lam (tp, body) ->
        List.map (fun body' -> Lam (tp, body')) (tm_one_replacement_results_at base_depth (depth + 1) body needle replacement)
    | Imp (left, right) ->
        List.map (fun left' -> Imp (left', right)) (tm_one_replacement_results_at base_depth depth left needle replacement)
        @ List.map (fun right' -> Imp (left, right')) (tm_one_replacement_results_at base_depth depth right needle replacement)
    | All (tp, body) ->
        List.map (fun body' -> All (tp, body')) (tm_one_replacement_results_at base_depth (depth + 1) body needle replacement)
    | _ -> []
  in
  here @ below

let tm_one_replacement_results ?(base_depth=0) source needle replacement =
  tm_one_replacement_results_at base_depth 0 source needle replacement

let unique_terms terms =
  let rec loop seen = function
    | [] -> List.rev seen
    | term :: rest ->
        if List.exists ((=) term) seen then loop seen rest
        else loop (term :: seen) rest
  in
  loop [] terms

let predicate_definition_fold_chain_path checked id source_id definition_ids result =
  if definition_ids = [] then error (id ^ ": predicate_definition_fold_chain needs at least one definition");
  let source = lookup_formula checked source_id in
  let rec search current = function
    | [] -> if current = result then Some [] else None
    | definition_id :: remaining ->
        let definition = lookup_formula checked definition_id in
        let _, definiendum, body = predicate_definition_parts definition_id definition in
        let base_depth = universal_binder_count definition in
        let patterns = predicate_definition_fold_patterns base_depth body definiendum in
        let next =
          patterns
          |> List.concat_map
               (fun (needle, replacement) ->
                  tm_one_replacement_results ~base_depth current needle replacement)
          |> unique_terms
        in
        if next = [] then
          error (id ^ ": predicate_definition_fold_chain could not apply definition " ^ definition_id);
        let rec try_next = function
          | [] -> None
          | candidate :: rest ->
              begin match search candidate remaining with
              | Some path ->
                  Some ((definition_id, definition, current, candidate) :: path)
              | None -> try_next rest
              end
        in
        try_next next
  in
  match search source definition_ids with
  | Some path -> path
  | None ->
      error (id ^ ": predicate_definition_fold_chain result is not a sequence of definition-body replacements")

let check_predicate_definition_fold_chain checked id source_id definition_ids result =
  ignore (predicate_definition_fold_chain_path checked id source_id definition_ids result)

let true_false_equality_var = function
  | Pos atom ->
      begin match equality_sides atom with
      | Some (TmH h, other) when h = "f__true" || h = "f__false" -> Some (h, other)
      | Some (other, TmH h) when h = "f__true" || h = "f__false" -> Some (h, other)
      | _ -> None
      end
  | Neg _ -> None

let check_fool_exhaustiveness id clause =
  match clause with
  | [left; right] ->
      begin match true_false_equality_var left, true_false_equality_var right with
      | Some ("f__true", x), Some ("f__false", y)
      | Some ("f__false", x), Some ("f__true", y) when x = y -> ()
      | _ -> error (id ^ ": fool_exhaustiveness is not true/false exhaustiveness for one Boolean term")
      end
  | _ -> error (id ^ ": fool_exhaustiveness must have exactly two literals")

let check_fool_distinctness id clause =
  match clause with
  | [Neg atom] ->
      begin match equality_sides atom with
      | Some (TmH "f__true", TmH "f__false")
      | Some (TmH "f__false", TmH "f__true") -> ()
      | Some _ -> error (id ^ ": fool_distinctness is not true != false")
      | None -> error (id ^ ": fool_distinctness literal is not an equality")
      end
  | [_] -> error (id ^ ": fool_distinctness literal must be negative")
  | _ -> error (id ^ ": fool_distinctness must be a singleton clause")

let bool_constant_name value = if value then "f__true" else "f__false"

let bool_name_literal value = function
  | Pos atom ->
      let expected = bool_constant_name value in
      begin match equality_sides atom with
      | Some (TmH h, named) when h = expected -> Some named
      | Some (named, TmH h) when h = expected -> Some named
      | _ -> None
      end
  | Neg _ -> None

let name_application = function
  | Ap (head, arg) -> Some (head, arg)
  | _ -> None

let check_vampire_inequality_name_head id head =
  match head_symbol head with
  | Some name when string_starts_with "sP" name -> ()
  | Some name -> error (id ^ ": inequality splitting name head " ^ name ^ " is not a Vampire split-name symbol")
  | None -> error (id ^ ": inequality splitting name has no head symbol")

let split_name_application id named =
  let rec flatten = function
    | Ap (fn, arg) ->
        let head, args = flatten fn in
        (head, args @ [arg])
    | tm -> (tm, [])
  in
  match flatten named with
  | TmH head, (_ :: _ as args) ->
      check_vampire_inequality_name_head id (TmH head);
      (head, args)
  | head, (_ :: _ as args) ->
      check_vampire_inequality_name_head id head;
      begin match head_symbol head with
      | Some name -> (name, args)
      | None -> error (id ^ ": inequality split name has no head symbol")
      end
  | _ -> error (id ^ ": inequality split name literal is not a name application")

let check_inequality_name_intro id clause =
  match clause with
  | [literal] ->
      begin match bool_name_literal false literal with
      | Some named ->
          begin match name_application named with
          | Some (head, _) -> check_vampire_inequality_name_head id head
          | None -> error (id ^ ": inequality_name_intro literal is not a name application")
          end
      | None -> error (id ^ ": inequality_name_intro must be a positive equality to f__false")
      end
  | _ -> error (id ^ ": inequality_name_intro must be a singleton clause")

let check_inequality_split checked id source_id splits result =
  if splits = [] then error (id ^ ": inequality_split has no split items");
  let source_clause = lookup_clause checked source_id in
  let rec consume remaining replacements = function
    | [] -> remaining @ List.rev replacements
    | split :: rest ->
        let name_clause = lookup_clause checked split.split_name_parent in
        if not (same_clause_multiset name_clause [split.split_name_literal]) then
          error (id ^ ": inequality_split name literal does not match name parent " ^ split.split_name_parent);
        let remaining =
          match remove_one split.split_source remaining with
          | Some remaining -> remaining
          | None -> error (id ^ ": inequality_split source literal is not available in source parent")
        in
        let name_head, split_term =
          match bool_name_literal false split.split_name_literal with
          | Some named ->
              begin match name_application named with
              | Some (head, arg) ->
                  check_vampire_inequality_name_head id head;
                  (head, arg)
              | None -> error (id ^ ": inequality_split name literal is not a name application")
              end
          | None -> error (id ^ ": inequality_split name literal must be a positive equality to f__false")
        in
        let other_side =
          match split.split_source with
          | Neg atom ->
              begin match equality_sides atom with
              | Some (left, right) when left = split_term -> right
              | Some (left, right) when right = split_term -> left
              | Some _ -> error (id ^ ": inequality_split source equality does not contain the named split term")
              | None -> error (id ^ ": inequality_split source literal is not an equality")
              end
          | Pos _ -> error (id ^ ": inequality_split source literal must be negative")
        in
        begin match bool_name_literal true split.split_replacement with
        | Some named ->
            begin match name_application named with
            | Some (replacement_head, replacement_arg)
                when replacement_head = name_head && replacement_arg = other_side -> ()
            | Some _ -> error (id ^ ": inequality_split replacement does not apply the same name to the other equality side")
            | None -> error (id ^ ": inequality_split replacement is not a name application")
            end
        | None -> error (id ^ ": inequality_split replacement must be a positive equality to f__true")
        end;
        consume remaining (split.split_replacement :: replacements) rest
  in
  let expected = consume source_clause [] splits in
  if not (same_clause_multiset expected result) then
    error (id ^ ": inequality_split result does not match source with split replacements")

let check_equality_resolution checked id parent_id literal_index result =
  let parent_clause = lookup_clause checked parent_id in
  let literal = nth literal_index parent_clause (id ^ " equality-resolution literal") in
  begin
    match literal with
    | Neg atom ->
        begin
          match equality_sides atom with
          | Some (left, right) when left = right -> ()
          | Some _ -> error (id ^ ": equality-resolution equality is not reflexive")
          | None -> error (id ^ ": equality-resolution literal is not an equality atom")
        end
    | Pos _ -> error (id ^ ": equality-resolution literal must be negative")
  end;
  let expected = remove_at literal_index parent_clause (id ^ " equality-resolution literal") in
  if not (same_clause_multiset expected result) then
    error (id ^ ": equality-resolution result does not match parent after literal removal")

let same_literal_mod_vampire_vars left right =
  match left, right with
  | Pos left_atom, Pos right_atom
  | Neg left_atom, Neg right_atom ->
      left_atom = right_atom
      || same_mod_scoped_vampire_var_renaming left_atom right_atom
      || same_mod_scoped_vampire_var_renaming_and_equality left_atom right_atom
      || normalize_equality_orientation left_atom = normalize_equality_orientation right_atom
      || same_mod_scoped_vampire_var_renaming
           (normalize_equality_orientation left_atom)
           (normalize_equality_orientation right_atom)
      || same_mod_scoped_vampire_var_renaming_and_equality
           (normalize_equality_orientation left_atom)
           (normalize_equality_orientation right_atom)
  | _ -> false

let complementary_mod_equality left right =
  match left, right with
  | Pos left_atom, Neg right_atom
  | Neg left_atom, Pos right_atom ->
      same_literal_mod_vampire_vars (Pos left_atom) (Pos right_atom)
  | _ -> false

let remove_one_literal_mod item items what =
  let rec aux prefix = function
    | [] -> error what
    | literal :: rest when same_literal_mod_vampire_vars literal item ->
        List.rev_append prefix rest
    | literal :: rest -> aux (literal :: prefix) rest
  in
  aux [] items

let clause_contains_literal_mod item clause =
  List.exists (fun literal -> same_literal_mod_vampire_vars literal item) clause

let check_subsumption_resolution checked id main_parent_id side_parent_id selected side_pivot side_subst result =
  let main_clause = lookup_clause checked main_parent_id in
  let side_clause = lookup_clause checked side_parent_id in
  let main_rest =
    remove_one_literal_mod selected main_clause (id ^ ": selected literal is not present in main parent")
  in
  let expected_result_ok =
    same_clause_multiset main_rest result
    || same_clause_set_mod_equality main_rest result
  in
  if not expected_result_ok then
    error (id ^ ": subsumption-resolution result does not match main parent after selected literal removal");
  let side_pivot_sub = subst_literal side_subst side_pivot in
  if not (complementary_mod_equality selected side_pivot_sub) then
    error (id ^ ": side pivot does not complement selected literal under side substitution");
  let rec check_side skipped_pivot = function
    | [] ->
        if not skipped_pivot then
          error (id ^ ": side pivot is not present in side parent")
    | literal :: rest ->
        if not skipped_pivot && same_literal_mod_vampire_vars literal side_pivot then
          check_side true rest
        else
          let substituted = subst_literal side_subst literal in
          if complementary_mod_equality selected substituted
             || clause_contains_literal_mod substituted result then
            check_side skipped_pivot rest
          else
            error (id ^ ": side parent contains a literal not discharged by the selected literal or preserved in the result")
  in
  check_side false side_clause

let clause_matches_native_trace left right =
  same_clause_multiset left right
  || same_clause_set_mod_equality left right
  || same_clause_mod_vampire_var_renaming left right

let check_unit_resulting_resolution checked id main_parent_id traces result =
  if traces = [] then error (id ^ ": unit_resulting_resolution trace is empty");
  let main_clause = lookup_clause checked main_parent_id in
  let non_split_length clause =
    List.length (List.filter (fun lit -> not (is_split_literal lit)) clause)
  in
  let rec check_trace current = function
    | [] -> current
    | trace :: rest ->
        let unit_clause = lookup_clause checked trace.urr_unit_parent in
        if non_split_length unit_clause <> 1 then
          error (id ^ ": URR unit parent " ^ trace.urr_unit_parent ^ " is not a unit clause");
        if not (complementary_mod_equality trace.urr_selected_substituted trace.urr_unit_substituted) then
          error (id ^ ": URR substituted selected and unit literals are not complementary");
        let current_non_split_length = non_split_length current in
        let remaining_non_split_length = non_split_length trace.urr_remaining in
        if remaining_non_split_length >= current_non_split_length then
          error (id ^ ": URR trace did not remove a literal");
        let selected_is_linked =
          clause_contains_literal_mod trace.urr_selected current
          || clause_contains_literal_mod trace.urr_selected_substituted current
        in
        if not selected_is_linked && current_non_split_length = remaining_non_split_length + 1 then
          error (id ^ ": URR selected literal is not linked to the current clause");
        check_trace trace.urr_remaining rest
  in
  let final_remaining = check_trace main_clause traces in
  if not (clause_matches_native_trace final_remaining result) then
    error (id ^ ": URR result does not match final trace remaining clause")

let check_equality_resolution_constraints checked id parent_id literal_index selected constraints result =
  if constraints = [] then error (id ^ ": equality-resolution constraints must be non-empty");
  let parent_clause = lookup_clause checked parent_id in
  let literal = nth literal_index parent_clause (id ^ " equality-resolution-constraints literal") in
  if not (same_literal_mod_vampire_vars literal selected) then
    error (id ^ ": selected literal does not match parent literal modulo Vampire variable renaming");
  begin
    match literal with
    | Neg atom ->
        begin match equality_sides atom with
        | Some _ -> ()
        | None -> error (id ^ ": selected literal is not an equality atom")
        end
    | Pos _ -> error (id ^ ": selected literal must be negative")
  end;
  let expected = remove_at literal_index parent_clause (id ^ " equality-resolution-constraints literal") @ constraints in
  if not (same_clause_multiset expected result) then
    error (id ^ ": equality-resolution constraints do not explain result")

let diseq_literal left right = Neg (Ap (Ap (TmH "=", left), right))

let rec term_disagreement_constraints left right =
  if left = right then []
  else
    let left_head, left_args = application_spine left in
    let right_head, right_args = application_spine right in
    if left_head = right_head && List.length left_args = List.length right_args then
      let rec collect acc = function
        | [], [] -> List.rev acc
        | l :: ls, r :: rs ->
            let constraints =
              if l = r then []
              else
                let nested = term_disagreement_constraints l r in
                if nested = [] then [diseq_literal l r] else nested
            in
            collect (List.rev_append constraints acc) (ls, rs)
        | _ -> [diseq_literal left right]
      in
      collect [] (left_args, right_args)
    else
      [diseq_literal left right]

let equality_factoring_constraint_candidates selected_sides other_sides =
  let selected_left, selected_right = selected_sides in
  let other_left, other_right = other_sides in
  let candidates = ref [] in
  let add_simple shared selected_other other_other =
    if shared then begin
      candidates := [diseq_literal selected_other other_other] :: !candidates;
      candidates := [diseq_literal other_other selected_other] :: !candidates
    end
  in
  let add_decomposed selected_shared selected_other other_shared other_other =
    let constraints =
      diseq_literal selected_shared other_shared
      :: term_disagreement_constraints selected_other other_other
    in
    let reversed =
      diseq_literal other_shared selected_shared
      :: term_disagreement_constraints other_other selected_other
    in
    candidates := constraints :: reversed :: !candidates
  in
  add_simple (selected_right = other_right) selected_left other_left;
  add_simple (selected_right = other_left) selected_left other_right;
  add_simple (selected_left = other_right) selected_right other_left;
  add_simple (selected_left = other_left) selected_right other_right;
  add_decomposed selected_right selected_left other_right other_left;
  add_decomposed selected_right selected_left other_left other_right;
  add_decomposed selected_left selected_right other_right other_left;
  add_decomposed selected_left selected_right other_left other_right;
  List.filter (fun constraints -> constraints <> []) !candidates

let equality_factoring_explicit_constraint_candidates id selected_sides other_sides selected_lhs other_rhs =
  let selected_left, selected_right = selected_sides in
  let other_left, other_right = other_sides in
  let selected_choices =
    List.filter
      (fun (lhs, _) -> lhs = selected_lhs)
      [(selected_left, selected_right); (selected_right, selected_left)]
  in
  let other_choices =
    List.filter
      (fun (rhs, _) -> rhs = other_rhs)
      [(other_left, other_right); (other_right, other_left)]
  in
  if selected_choices = [] then
    error (id ^ ": equality-factoring selected_lhs does not name a selected equality side");
  if other_choices = [] then
    error (id ^ ": equality-factoring other_rhs does not name an other equality side");
  let candidates =
    List.fold_left
      (fun acc (selected_shared, selected_other) ->
        List.fold_left
          (fun acc (other_other, other_shared) ->
            if selected_shared = other_shared then
              [diseq_literal selected_other other_other] :: acc
            else
              acc)
          acc other_choices)
      [] selected_choices
  in
  if candidates = [] then
    error (id ^ ": equality-factoring explicit sides do not identify matching unified sides");
  candidates

let check_negative_equality_constraints id constraints =
  List.iter
    (function
      | Neg atom ->
          begin match equality_sides atom with
          | Some _ -> ()
          | None -> error (id ^ ": equality-factoring constraint is not an equality atom")
          end
      | Pos _ -> error (id ^ ": equality-factoring constraint must be negative"))
    constraints

let equality_factoring_context checked id parent_id selected_index other_index subst =
  if selected_index = other_index then error (id ^ ": equality-factoring literal indices must be distinct");
  let parent_clause = lookup_clause checked parent_id in
  let selected_literal = nth selected_index parent_clause (id ^ " selected equality") in
  let other_literal = nth other_index parent_clause (id ^ " other equality") in
  let selected_sub = subst_literal subst selected_literal in
  let other_sub = subst_literal subst other_literal in
  let selected_sides =
    match selected_sub with
    | Pos atom ->
        begin match equality_sides atom with
        | Some sides -> sides
        | None -> error (id ^ ": selected literal is not an equality")
        end
    | Neg _ -> error (id ^ ": selected literal must be positive")
  in
  let other_sides =
    match other_sub with
    | Pos atom ->
        begin match equality_sides atom with
        | Some sides -> sides
        | None -> error (id ^ ": other literal is not an equality")
        end
    | Neg _ -> error (id ^ ": other literal must be positive")
  in
  let substituted_parent = subst_clause subst parent_clause in
  let without_selected = remove_at selected_index substituted_parent (id ^ " selected equality") in
  selected_sides, other_sides, without_selected

let check_equality_factoring checked id parent_id selected_index other_index explicit_sides subst result =
  let selected_sides, other_sides, without_selected =
    equality_factoring_context checked id parent_id selected_index other_index subst
  in
  let candidates =
    match explicit_sides with
    | None -> equality_factoring_constraint_candidates selected_sides other_sides
    | Some (selected_lhs, other_rhs) ->
        equality_factoring_explicit_constraint_candidates
          id selected_sides other_sides selected_lhs other_rhs
  in
  if candidates = [] then error (id ^ ": selected and other equalities do not yield factoring constraints");
  if not (List.exists
      (fun candidate_constraints ->
        let expected = without_selected @ candidate_constraints in
        same_clause_multiset expected result
        || same_clause_set_mod_equality expected result)
      candidates) then
    error (id ^ ": equality-factoring result does not match explicit factoring")

let check_equality_factoring_constraints checked id parent_id selected_index other_index explicit_sides subst constraints result =
  if constraints = [] then error (id ^ ": equality-factoring constraints must be non-empty");
  check_negative_equality_constraints id constraints;
  let selected_sides, other_sides, without_selected =
    equality_factoring_context checked id parent_id selected_index other_index subst
  in
  let expected = without_selected @ constraints in
  if not (same_clause_multiset expected result || same_clause_set_mod_equality expected result) then
    error (id ^ ": equality-factoring constraints do not explain result");
  let candidates =
    match explicit_sides with
    | None -> equality_factoring_constraint_candidates selected_sides other_sides
    | Some (selected_lhs, other_rhs) ->
        equality_factoring_explicit_constraint_candidates
          id selected_sides other_sides selected_lhs other_rhs
  in
  if not (List.exists
      (fun candidate ->
        same_clause_multiset candidate constraints
        || same_clause_set_mod_equality candidate constraints)
      candidates) then
    error (id ^ ": equality-factoring constraints are not explained by selected and other equalities")

let check_truth_conflict checked id parent_id literal_index result =
  let parent_clause = lookup_clause checked parent_id in
  let literal = nth literal_index parent_clause (id ^ " truth-conflict literal") in
  begin
    match literal with
    | Pos atom ->
        begin
          match equality_sides atom with
          | Some (TmH "f__true", TmH "f__false")
          | Some (TmH "f__false", TmH "f__true") -> ()
          | Some _ -> error (id ^ ": truth-conflict equality is not true = false")
          | None -> error (id ^ ": truth-conflict literal is not an equality atom")
        end
    | Neg _ -> error (id ^ ": truth-conflict literal must be positive")
  end;
  let expected = remove_at literal_index parent_clause (id ^ " truth-conflict literal") in
  if not (same_clause_multiset expected result) then
    error (id ^ ": truth-conflict result does not match parent after literal removal")

let check_equality_symmetry checked id parent_id literal_index result =
  let parent_clause = lookup_clause checked parent_id in
  let literal = nth literal_index parent_clause (id ^ " equality-symmetry literal") in
  let swapped_literal =
    match swap_literal_equality literal with
    | Some swapped -> swapped
    | None -> error (id ^ ": equality-symmetry literal is not an equality")
  in
  let without_literal = remove_at literal_index parent_clause (id ^ " equality-symmetry literal") in
  let expected = without_literal @ [swapped_literal] in
  if not (same_clause_multiset expected result) then
    error (id ^ ": equality-symmetry result does not match parent clause")

let check_paramodulate checked id equality_parent_id target_parent_id equality_index target_index position from_tm to_tm result =
  let equality_clause = lookup_clause checked equality_parent_id in
  let target_clause = lookup_clause checked target_parent_id in
  let equality_literal = nth equality_index equality_clause (id ^ " equality literal") in
  let target_literal = nth target_index target_clause (id ^ " target literal") in
  begin
    match equality_literal with
    | Pos atom ->
        begin
          match equality_sides atom with
          | Some (left, right) when left = from_tm && right = to_tm -> ()
          | Some (left, right) when right = from_tm && left = to_tm -> ()
          | Some _ -> error (id ^ ": paramodulation from/to terms do not match equality literal")
          | None -> error (id ^ ": paramodulation equality literal is not an equality atom")
        end
    | Neg _ -> error (id ^ ": paramodulation equality literal must be positive")
  end;
  let target_atom = literal_atom target_literal in
  let position =
    let rec select = function
      | [] -> error (id ^ ": paramodulation position does not contain from term")
      | candidate :: rest ->
          begin
            match try_tm_at_position target_atom candidate with
            | Some found when found = from_tm -> candidate
            | _ -> select rest
          end
    in
    select (paramodulation_position_candidates target_atom position)
  in
  let rewritten_atom = replace_tm_at_position target_atom position to_tm (id ^ " target") in
  let rewritten_literal = replace_literal_atom target_literal rewritten_atom in
  let equality_rest = remove_at equality_index equality_clause (id ^ " equality literal") in
  let target_rest = remove_at target_index target_clause (id ^ " target literal") in
  let expected = equality_rest @ target_rest @ [rewritten_literal] in
  if not (same_clause_multiset expected result || same_clause_set_mod_equality expected result) then
    begin match swap_literal_equality rewritten_literal with
    | Some swapped_literal ->
        let swapped_expected = equality_rest @ target_rest @ [swapped_literal] in
        if not (same_clause_multiset swapped_expected result || same_clause_set_mod_equality swapped_expected result) then
          error (id ^ ": paramodulation result does not match explicit rewrite")
    | None -> error (id ^ ": paramodulation result does not match explicit rewrite")
    end

let check_bool_simplify checked id parent_id literal_index position from_tm to_tm result =
  let parent_clause = lookup_clause checked parent_id in
  let target_literal = nth literal_index parent_clause (id ^ " Boolean simplification literal") in
  let target_atom = literal_atom target_literal in
  let position =
    let rec select = function
      | [] -> error (id ^ ": Boolean simplification position does not contain from term")
      | candidate :: rest ->
          begin
            match try_tm_at_position target_atom candidate with
            | Some found when found = from_tm -> candidate
            | _ -> select rest
          end
    in
    select (paramodulation_position_candidates target_atom position)
  in
  let rewritten_atom = replace_tm_at_position target_atom position to_tm (id ^ " Boolean simplification target") in
  let rewritten_literal = replace_literal_atom target_literal rewritten_atom in
  let parent_rest = remove_at literal_index parent_clause (id ^ " Boolean simplification literal") in
  let result_matches rewritten_literal =
    let expected = parent_rest @ [rewritten_literal] in
    same_clause_multiset expected result
    || same_clause_set_mod_equality expected result
    || same_clause_mod_vampire_var_renaming expected result
    || same_clause_mod_vampire_var_renaming_and_equality expected result
  in
  if not (
    result_matches rewritten_literal
    ||
    match swap_literal_equality rewritten_literal with
    | Some swapped_literal -> result_matches swapped_literal
    | None -> false)
  then
    error (id ^ ": Boolean simplification result does not match explicit rewrite")

let check_superposition checked id target_parent_id equality_parent_id target_index equality_index target_subst equality_subst position from_tm to_tm result =
  let target_clause = subst_clause target_subst (lookup_clause checked target_parent_id) in
  let raw_equality_clause = lookup_clause checked equality_parent_id in
  let equality_clause = subst_clause equality_subst raw_equality_clause in
  let raw_equality_literal = nth equality_index raw_equality_clause (id ^ " raw equality literal") in
  let equality_literal = nth equality_index equality_clause (id ^ " equality literal") in
  let target_literal = nth target_index target_clause (id ^ " target literal") in
  let side_matches left right =
    left = right
    || same_mod_vampire_var_renaming left right
    || same_mod_scoped_vampire_var_renaming left right
    || same_mod_scoped_vampire_var_renaming_and_equality left right
  in
  begin
    match equality_literal with
    | Pos atom ->
        begin
          match equality_sides atom with
          | Some (left, right) when side_matches left from_tm && side_matches right to_tm -> ()
          | Some (left, right) when side_matches right from_tm && side_matches left to_tm -> ()
          | Some _ -> error (id ^ ": superposition from/to terms do not match equality literal")
          | None -> error (id ^ ": superposition equality literal is not an equality atom")
        end
    | Neg _ -> error (id ^ ": superposition equality literal must be positive")
  end;
  let target_atom = literal_atom target_literal in
  let position =
    let rec select = function
      | [] -> error (id ^ ": superposition position does not contain from term")
      | candidate :: rest ->
          begin
            match try_tm_at_position target_atom candidate with
            | Some found when found = from_tm -> candidate
            | _ -> select rest
          end
    in
    select (paramodulation_position_candidates target_atom position)
  in
  let rewritten_atom = replace_tm_at_position target_atom position to_tm (id ^ " target") in
  let rewritten_literal = replace_literal_atom target_literal rewritten_atom in
  let simultaneous_rewritten_literal =
    rewrite_literal_all_once from_tm to_tm target_literal
  in
  let equality_rest = remove_at equality_index equality_clause (id ^ " equality literal") in
  let target_rest = remove_at target_index target_clause (id ^ " target literal") in
  let target_rest_variants =
    let clause_wide_target_rest = List.map (rewrite_literal_all_once from_tm to_tm) target_rest in
    if clause_wide_target_rest = target_rest then [target_rest]
    else [target_rest; clause_wide_target_rest]
  in
  let result_matches_with_equality_rest equality_rest rewritten_literal =
    List.exists
      (fun target_rest ->
        let expected = equality_rest @ target_rest @ [rewritten_literal] in
        same_clause_multiset expected result
        || same_clause_set_mod_equality expected result
        || same_clause_mod_vampire_var_renaming expected result
        || same_clause_mod_vampire_var_renaming_and_equality expected result)
      target_rest_variants
  in
  let result_matches equality_rest =
    let rewritten_literals =
      if simultaneous_rewritten_literal = rewritten_literal then [rewritten_literal]
      else [rewritten_literal; simultaneous_rewritten_literal]
    in
    List.exists
      (fun rewritten_literal ->
        result_matches_with_equality_rest equality_rest rewritten_literal
        ||
        match swap_literal_equality rewritten_literal with
        | Some swapped_literal -> result_matches_with_equality_rest equality_rest swapped_literal
        | None -> false)
      rewritten_literals
  in
  let raw_variable_name = function
    | TmH name when is_vampire_var_name name -> Some name
    | _ -> None
  in
  let result_matches_raw_variable_orientation () =
    match raw_equality_literal with
    | Pos raw_atom ->
        begin match equality_sides raw_atom with
        | Some (raw_left, raw_right) ->
            let variants =
              match raw_variable_name raw_left, raw_variable_name raw_right with
              | Some left_name, Some right_name ->
                  [[left_name, from_tm; right_name, to_tm];
                   [right_name, from_tm; left_name, to_tm]]
              | Some left_name, None -> [[left_name, from_tm]]
              | None, Some right_name -> [[right_name, from_tm]]
              | None, None -> []
            in
            List.exists
              (fun subst ->
                let raw_rest = remove_at equality_index raw_equality_clause (id ^ " raw equality literal") in
                let equality_rest = subst_clause subst raw_rest in
                result_matches equality_rest)
              variants
        | None -> false
        end
    | Neg _ -> false
  in
  if not (result_matches equality_rest || result_matches_raw_variable_orientation ()) then
    error (id ^ ": superposition result does not match explicit rewrite")

let check_step checked = function
  | Input (id, source, clause) ->
      check_input_source source;
      (id, CheckedClause clause) :: checked
  | FormulaInput (id, source, literal) ->
      check_input_source source;
      (id, CheckedFormula (formula_tm_of_literal literal)) :: checked
  | FormulaTermInput (id, source, formula) ->
      check_input_source source;
      (id, CheckedFormula formula) :: checked
  | FormulaTermCopy (id, parent_id, result) ->
      check_formula_term_copy checked id parent_id result;
      (id, CheckedFormula result) :: checked
  | RectifyFormula (id, parent_id, renamings, result) ->
      check_rectify_formula checked id parent_id renamings result;
      (id, CheckedFormula result) :: checked
  | FoolAtomLift (id, source, target, path) ->
      check_fool_atom_lift id source target path;
      (id, CheckedFormula target) :: checked
  | FoolFormula (id, parent_id, result) ->
      check_fool_formula checked id parent_id result;
      (id, CheckedFormula result) :: checked
  | EnnfFormula (id, parent_id, source, pairs, result) ->
      check_ennf_formula checked id parent_id source pairs result;
      (id, CheckedFormula result) :: checked
  | SkolemFormula (id, parent_id, source, introductions, subst, result) ->
      check_skolem_formula checked id parent_id source introductions subst result;
      (id, CheckedFormula result) :: checked
  | SkolemFormulaComputed (id, parent_id, subst) ->
      let result = check_skolem_formula_computed checked parent_id subst in
      (id, CheckedFormula result) :: checked
  | CnfFormulaClause (id, parent_id, index, count, result) ->
      check_cnf_formula_clause checked id parent_id index count result;
      (id, CheckedClause result) :: checked
  | FormulaCopy (id, parent_id, result) ->
      check_formula_copy checked id parent_id result;
      (id, CheckedClause [result]) :: checked
  | FoolBool (id, parent_id, result) ->
      check_fool_bool checked id parent_id result;
      (id, CheckedClause [result]) :: checked
  | CnfLiteral (id, parent_id, result) ->
      check_cnf_literal checked id parent_id result;
      (id, CheckedClause result) :: checked
  | PredicateDefinition (id, symbol, result) ->
      check_predicate_definition id symbol result;
      (id, CheckedFormula result) :: checked
  | PredicateDefinitionFold (id, source_id, definition_id, result) ->
      check_predicate_definition_fold checked id source_id definition_id result;
      (id, CheckedFormula result) :: checked
  | PredicateDefinitionFoldChain (id, source_id, definition_ids, result) ->
      check_predicate_definition_fold_chain checked id source_id definition_ids result;
      (id, CheckedFormula result) :: checked
  | DefinitionInput (id, clause) ->
      check_definition_input id clause;
      (id, CheckedClause clause) :: checked
  | DefinitionRewriteChain (id, source_id, rewrites, result) ->
      check_definition_rewrite_chain checked id source_id rewrites result;
      (id, CheckedClause result) :: checked
  | AvatarComponent (id, clause) ->
      check_avatar_component id clause;
      (id, CheckedClause clause) :: checked
  | AvatarDefinition (id, split_var, split_positive, clause) ->
      check_avatar_component_split id split_var split_positive clause;
      (id, CheckedClause clause) :: checked
  | SplitDependency (id, owner_id, dependencies, clause) ->
      check_avatar_dependencies id dependencies;
      let owner_clause = lookup_clause checked owner_id in
      if owner_clause <> clause then error (id ^ ": split_dependency result does not match owner clause");
      (id, CheckedClause clause) :: checked
  | AvatarSplit (id, parent_ids, clause) ->
      check_avatar_sat_clause checked id parent_ids clause;
      (id, CheckedClause clause) :: checked
  | AvatarContradiction (id, parent_ids, clause) ->
      check_avatar_sat_clause checked id parent_ids clause;
      (id, CheckedClause clause) :: checked
  | AvatarRefutation (id, parent_ids, sat_clauses, proof, result) ->
      check_avatar_refutation checked id parent_ids sat_clauses proof result;
      (id, CheckedClause result) :: checked
  | FoolExhaustiveness (id, clause) ->
      check_fool_exhaustiveness id clause;
      (id, CheckedClause clause) :: checked
  | FoolDistinctness (id, clause) ->
      check_fool_distinctness id clause;
      (id, CheckedClause clause) :: checked
  | InequalityNameIntro (id, clause) ->
      check_inequality_name_intro id clause;
      (id, CheckedClause clause) :: checked
  | InequalitySplit (id, source_id, splits, result) ->
      check_inequality_split checked id source_id splits result;
      (id, CheckedClause result) :: checked
  | Substitute (id, parent_id, subst, result) ->
      check_substitute checked id parent_id subst result;
      (id, CheckedClause result) :: checked
  | Condensation (id, parent_id, subst, result) ->
      check_condensation checked id parent_id subst result;
      (id, CheckedClause result) :: checked
  | UnitResultingResolution (id, main_parent_id, traces, result) ->
      check_unit_resulting_resolution checked id main_parent_id traces result;
      (id, CheckedClause result) :: checked
  | Resolve (id, left_id, right_id, left_index, right_index, result) ->
      check_resolution checked id left_id right_id left_index right_index result;
      (id, CheckedClause result) :: checked
  | SubsumptionResolution (id, main_parent_id, side_parent_id, selected, side_pivot, side_subst, result) ->
      check_subsumption_resolution checked id main_parent_id side_parent_id selected side_pivot side_subst result;
      (id, CheckedClause result) :: checked
  | Factor (id, parent_id, left_index, right_index, result) ->
      check_factor checked id parent_id left_index right_index result;
      (id, CheckedClause result) :: checked
  | EqualityResolution (id, parent_id, literal_index, result) ->
      check_equality_resolution checked id parent_id literal_index result;
      (id, CheckedClause result) :: checked
  | EqualityResolutionConstraints (id, parent_id, literal_index, selected, constraints, result) ->
      check_equality_resolution_constraints checked id parent_id literal_index selected constraints result;
      (id, CheckedClause result) :: checked
  | EqualityFactoring (id, parent_id, selected_index, other_index, explicit_sides, subst, result) ->
      check_equality_factoring checked id parent_id selected_index other_index explicit_sides subst result;
      (id, CheckedClause result) :: checked
  | EqualityFactoringConstraints (id, parent_id, selected_index, other_index, explicit_sides, subst, constraints, result) ->
      check_equality_factoring_constraints checked id parent_id selected_index other_index explicit_sides subst constraints result;
      (id, CheckedClause result) :: checked
  | TruthConflict (id, parent_id, literal_index, result) ->
      check_truth_conflict checked id parent_id literal_index result;
      (id, CheckedClause result) :: checked
  | EqualitySymmetry (id, parent_id, literal_index, result) ->
      check_equality_symmetry checked id parent_id literal_index result;
      (id, CheckedClause result) :: checked
  | BoolSimplify (id, parent_id, literal_index, position, from_tm, to_tm, result) ->
      check_bool_simplify checked id parent_id literal_index position from_tm to_tm result;
      (id, CheckedClause result) :: checked
  | Paramodulate (id, equality_parent_id, target_parent_id, equality_index, target_index, position, from_tm, to_tm, result) ->
      check_paramodulate checked id equality_parent_id target_parent_id equality_index target_index position from_tm to_tm result;
      (id, CheckedClause result) :: checked
  | Superposition (id, target_parent_id, equality_parent_id, target_index, equality_index, target_subst, equality_subst, position, from_tm, to_tm, result) ->
      check_superposition checked id target_parent_id equality_parent_id target_index equality_index target_subst equality_subst position from_tm to_tm result;
      (id, CheckedClause result) :: checked
  | Contradiction (id, parent_id) ->
      let clause = lookup_clause checked parent_id in
      if clause <> [] then error (id ^ ": contradiction parent is not the empty clause");
      (id, CheckedClause []) :: checked

let check_step_strict checked = function
  | AvatarComponent (id, clause) ->
      check_avatar_component_strict id clause;
      check_step checked (AvatarComponent (id, clause))
  | AvatarDefinition (id, split_var, split_positive, clause) ->
      check_avatar_component_split id split_var split_positive clause;
      check_step checked (AvatarDefinition (id, split_var, split_positive, clause))
  | AvatarRefutation (id, _, _, None, _) ->
      error (id ^ ": strict certificate v1 requires SAT proof traces for AVATAR refutations")
  | AvatarRefutation (id, [], _, _, _) ->
      error (id ^ ": strict certificate v1 requires AVATAR refutation parent links")
  | AvatarRefutation _ as step -> check_step checked step
  | SkolemFormulaComputed (id, _, _) ->
      error (id ^ ": strict certificate v1 rejects computed skolem formulas without explicit Vampire results")
  | step -> check_step checked step

let check_certificate_with step_checker cert =
  let metadata_sat_clause_records =
    cert.metadata.step_extras
    |> List.filter_map
         (fun (id, kind, fields) ->
            if kind = "raw" && List.mem "sat_clause_recorded" fields then
              Some (id, CheckedSatClauseRecord)
            else None)
    |> List.sort_uniq compare
  in
  let checked = List.fold_left step_checker metadata_sat_clause_records cert.steps in
  begin match checked with
  | (_, CheckedClause []) :: _ -> ()
  | (id, CheckedClause _) :: _ -> error (id ^ ": final certificate step is not the empty clause")
  | (id, CheckedFormula _) :: _ -> error (id ^ ": final certificate step is a formula, not the empty clause")
  | (id, CheckedSatClauseRecord) :: _ -> error (id ^ ": final certificate step is an AVATAR SAT clause record, not the empty clause")
  | [] -> error "certificate contains no steps"
  end;
  List.rev checked

let check_certificate cert =
  check_certificate_with check_step cert

let field_value key fields =
  let prefix = key ^ "=" in
  let prefix_len = String.length prefix in
  List.find_map
    (fun field ->
       if String.length field >= prefix_len
          && String.sub field 0 prefix_len = prefix then
         Some (String.sub field prefix_len (String.length field - prefix_len))
       else None)
    fields

let kernel_v1_field_value cert id key =
  cert.metadata.step_extras
  |> List.find_map
       (fun (step_id, kind, fields) ->
          if step_id = id && kind = "kernel_v1" then field_value key fields else None)

let kernel_v1_substitution_field cert id key =
  match kernel_v1_field_value cert id key with
  | None -> []
  | Some value -> parse_substitution (parse_sexpr value)

let required_primitives_for_kernel_rule =
  Vampire_kernel_syntax.required_primitives_for_rule

let has_id_prefix id prefix =
  id = prefix
  ||
  let prefix_with_sep = prefix ^ "_" in
  let prefix_len = String.length prefix_with_sep in
  String.length id >= prefix_len
  && String.sub id 0 prefix_len = prefix_with_sep

let is_metadata_step_id_like value =
  let len = String.length value in
  len > 0
  &&
  let rec loop index =
    if index >= len then true
    else
      match value.[index] with
      | 'a'..'z' | 'A'..'Z' | '0'..'9' | '_' | '\'' -> loop (index + 1)
      | _ -> false
  in
  loop 0

let field_key_value field =
  match String.index_opt field '=' with
  | None -> None
  | Some eq ->
      Some
        (String.sub field 0 eq,
         String.sub field (eq + 1) (String.length field - eq - 1))

let validate_kernel_v1_metadata_contracts cert =
  let step_indices = Hashtbl.create 97 in
  let step_by_id = Hashtbl.create 97 in
  List.iteri
    (fun index step ->
       Hashtbl.add step_indices (step_id step) index;
       Hashtbl.replace step_by_id (step_id step) step)
    cert.steps;
  let field_required id fields key =
    match field_value key fields with
    | Some value -> value
    | None -> error (id ^ ": strict certificate v1 kernel_v1 metadata requires " ^ key)
  in
  let require_rule_fields id fields kernel_rule keys =
    List.iter
      (fun key ->
         ignore (field_required id fields key : string))
      keys;
    ignore kernel_rule
  in
  let field_int id fields key =
    let value = field_required id fields key in
    try int_of_string value with Failure _ ->
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " is not an integer")
  in
  let require_field_int id fields key expected =
    let actual = field_int id fields key in
    if actual <> expected then
      error
        (Printf.sprintf
           "%s: strict certificate v1 kernel_v1 metadata field %s expected %d but got %d"
           id key expected actual)
  in
  let parse_field id fields key parser =
    let value = field_required id fields key in
    try parser (parse_sexpr value) with
    | Error msg ->
        error
          (id ^ ": strict certificate v1 kernel_v1 metadata field "
           ^ key ^ " is malformed: " ^ msg)
  in
  let require_field_clause id fields key expected =
    let actual = parse_field id fields key parse_clause in
    if not (same_clause_multiset actual expected) then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " does not match the certificate clause")
  in
  let require_field_literal id fields key expected =
    let actual = parse_field id fields key parse_literal in
    if not (same_literal_mod_vampire_vars actual expected) then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " does not match the certificate literal")
  in
  let require_field_formula id fields key expected =
    let actual = parse_field id fields key parse_tm in
    if actual <> expected
       && normalize_bool_equality_orientation actual
          <> normalize_bool_equality_orientation expected
       && normalize_equality_orientation actual
          <> normalize_equality_orientation expected then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " does not match the certificate formula")
  in
  let require_field_parse_formula id fields key =
    ignore (parse_field id fields key parse_tm : tm)
  in
  let require_field_tm id fields key expected =
    let actual = parse_field id fields key parse_tm in
    if actual <> expected
       && normalize_bool_equality_orientation actual
          <> normalize_bool_equality_orientation expected
       && normalize_equality_orientation actual
          <> normalize_equality_orientation expected then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " does not match the certificate term")
  in
  let require_field_tp id fields key expected =
    let actual = parse_field id fields key parse_tp in
    if actual <> expected then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " does not match the certificate type")
  in
  let require_field_substitution id fields key expected =
    let actual = parse_field id fields key parse_substitution in
    if actual <> expected then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " does not match the certificate substitution")
  in
  let require_nonnegative_field_int id fields key =
    let value = field_int id fields key in
    if value < 0 then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " is negative");
    value
  in
  let rec formula_shape_summary tm =
    match tm with
    | All (_, body) ->
        let _, exists_count, forall_count, and_count, or_count, imp_count =
          formula_shape_summary body
        in
        ("forall", exists_count, forall_count + 1, and_count, or_count, imp_count)
    | Imp (left, right) ->
        let _, left_exists, left_forall, left_and, left_or, left_imp =
          formula_shape_summary left
        in
        let _, right_exists, right_forall, right_and, right_or, right_imp =
          formula_shape_summary right
        in
        ("imp",
         left_exists + right_exists,
         left_forall + right_forall,
         left_and + right_and,
         left_or + right_or,
         left_imp + right_imp + 1)
    | Ap (TmH "vampire_exists_prop", Lam (_, body)) ->
        let _, exists_count, forall_count, and_count, or_count, imp_count =
          formula_shape_summary body
        in
        ("exists", exists_count + 1, forall_count, and_count, or_count, imp_count)
    | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", body)) ->
        let _, exists_count, forall_count, and_count, or_count, imp_count =
          formula_shape_summary body
        in
        ("exists", exists_count + 1, forall_count, and_count, or_count, imp_count)
    | Ap (Ap (TmH "vampire_and", left), right) ->
        let _, left_exists, left_forall, left_and, left_or, left_imp =
          formula_shape_summary left
        in
        let _, right_exists, right_forall, right_and, right_or, right_imp =
          formula_shape_summary right
        in
        ("and",
         left_exists + right_exists,
         left_forall + right_forall,
         left_and + right_and + 1,
         left_or + right_or,
         left_imp + right_imp)
    | Ap (Ap (TmH "vampire_or", left), right) ->
        let _, left_exists, left_forall, left_and, left_or, left_imp =
          formula_shape_summary left
        in
        let _, right_exists, right_forall, right_and, right_or, right_imp =
          formula_shape_summary right
        in
        ("or",
         left_exists + right_exists,
         left_forall + right_forall,
         left_and + right_and,
         left_or + right_or + 1,
         left_imp + right_imp)
    | TmH "vampire_false" | TmH "f__false" ->
        ("false", 0, 0, 0, 0, 0)
    | TmH "f__true" ->
        ("true", 0, 0, 0, 0, 0)
    | _ ->
        ("literal", 0, 0, 0, 0, 0)
  in
  let connective_matches expected actual =
    expected = actual
    || expected = "literal"
    || expected = "bool_term"
  in
  let require_formula_shape_fields id fields prefix formula =
    let actual_connective, actual_exists, actual_forall, actual_and, actual_or, actual_imp =
      formula_shape_summary formula
    in
    let connective = field_required id fields (prefix ^ "_connective") in
    if not (connective_matches connective actual_connective) then
      error
        (Printf.sprintf
           "%s: strict certificate v1 kernel_v1 metadata field %s_connective expected %s but parsed formula has %s"
           id prefix connective actual_connective);
    require_field_int id fields (prefix ^ "_exists_count") actual_exists;
    require_field_int id fields (prefix ^ "_forall_count") actual_forall;
    require_field_int id fields (prefix ^ "_and_count") actual_and;
    require_field_int id fields (prefix ^ "_or_count") actual_or;
    ignore actual_imp;
    ignore (require_nonnegative_field_int id fields (prefix ^ "_imp_count") : int)
  in
  let rec quantified_variables_of_sexpr = function
    | List [Atom "ALLV"; name; tp; body] ->
        ("forall", atom name, parse_tp tp) :: quantified_variables_of_sexpr body
    | List [Atom "ALL"; tp; body] ->
        ("forall", "", parse_tp tp) :: quantified_variables_of_sexpr body
    | List [Atom "AP"; List [Atom "TMH"; exists_head];
            List [Atom binder; name; tp; body]]
        when atom exists_head = "vampire_exists_prop"
             && (binder = "LAMV" || binder = "VLAMV") ->
        ("exists", atom name, parse_tp tp) :: quantified_variables_of_sexpr body
    | List [Atom "AP"; List [Atom "TMH"; exists_head];
            List [Atom "LAM"; tp; body]]
        when atom exists_head = "vampire_exists_prop" ->
        ("exists", "", parse_tp tp) :: quantified_variables_of_sexpr body
    | List [Atom "AP"; left; right]
    | List [Atom "IMP"; left; right] ->
        quantified_variables_of_sexpr left @ quantified_variables_of_sexpr right
    | List [Atom "LAMV"; _; _; body]
    | List [Atom "VLAMV"; _; _; body]
    | List [Atom "LAM"; _; body] ->
        quantified_variables_of_sexpr body
    | List items ->
        List.concat_map quantified_variables_of_sexpr items
    | Atom _ | Str _ -> []
  in
  let require_formula_quantifier_fields id fields prefix raw_formula =
    match field_value (prefix ^ "_quantifier_count") fields with
    | None -> ()
    | Some _ ->
        let quantified_variables =
          quantified_variables_of_sexpr (parse_sexpr raw_formula)
        in
        require_field_int
          id fields (prefix ^ "_quantifier_count")
          (List.length quantified_variables);
        List.iteri
          (fun index (kind, variable, tp) ->
             let field_prefix =
               prefix ^ "_quantifier_" ^ string_of_int index
             in
             let actual_kind =
               field_required id fields (field_prefix ^ "_kind")
             in
             if actual_kind <> kind then
               error
                 (Printf.sprintf
                    "%s: strict certificate v1 kernel_v1 metadata field %s_kind expected %s but raw formula has %s"
                    id field_prefix actual_kind kind);
             let actual_variable =
               field_required id fields (field_prefix ^ "_var")
             in
             if actual_variable <> variable then
               error
                 (Printf.sprintf
                    "%s: strict certificate v1 kernel_v1 metadata field %s_var expected %s but raw formula has %s"
                    id field_prefix actual_variable variable);
             let actual_tp =
               parse_field id fields (field_prefix ^ "_type") parse_tp
             in
             if actual_tp <> tp then
              error
                  (id ^ ": strict certificate v1 kernel_v1 metadata field "
                   ^ field_prefix ^ "_type does not match the raw formula binder type"))
          quantified_variables
  in
  let free_variable_names_of_sexpr sexpr =
    let add_name name names =
      if List.mem name names then names else name :: names
    in
    let rec collect bound names = function
      | List [Atom "ALLV"; name; _tp; body]
      | List [Atom "LAMV"; name; _tp; body]
      | List [Atom "VLAMV"; name; _tp; body] ->
          collect (atom name :: bound) names body
      | List [Atom "AP"; List [Atom "TMH"; exists_head];
              List [Atom binder; name; _tp; body]]
          when atom exists_head = "vampire_exists_prop"
               && (binder = "LAMV" || binder = "VLAMV") ->
          collect (atom name :: bound) names body
      | List [Atom "AP"; List [Atom "TMH"; exists_head];
              List [Atom "LAM"; _tp; body]]
          when atom exists_head = "vampire_exists_prop" ->
          collect bound names body
      | List [Atom "TMH"; name] ->
          let name = atom name in
          if is_vampire_var_name name && not (List.mem name bound) then
            add_name name names
          else
            names
      | List items ->
          List.fold_left (collect bound) names items
      | Atom _ | Str _ -> names
    in
    let variable_sort_key name =
      match vampire_var_index name with
      | Some index -> index, name
      | None -> max_int, name
    in
    collect [] [] sexpr
    |> List.sort_uniq
         (fun left right -> compare (variable_sort_key left) (variable_sort_key right))
  in
  let typed_variable_fields id fields prefix role =
    match field_value (prefix ^ "_" ^ role ^ "_count") fields with
    | None -> None
    | Some _ ->
        let count =
          require_nonnegative_field_int
            id fields (prefix ^ "_" ^ role ^ "_count")
        in
        let rec collect index acc =
          if index >= count then Some (List.rev acc)
          else
            let field_prefix =
              prefix ^ "_" ^ role ^ "_" ^ string_of_int index
            in
            let variable = field_required id fields (field_prefix ^ "_var") in
            let tp = parse_field id fields (field_prefix ^ "_type") parse_tp in
            collect (index + 1) ((variable, tp) :: acc)
        in
        collect 0 []
  in
  let require_formula_free_variable_fields id fields prefix raw_formula =
    match typed_variable_fields id fields prefix "free_variable" with
    | None -> ()
    | Some variables ->
        let expected =
          free_variable_names_of_sexpr (parse_sexpr raw_formula)
        in
        let actual = List.map fst variables in
        if actual <> expected then
          error
            (id ^ ": strict certificate v1 kernel_v1 metadata field "
             ^ prefix
             ^ "_free_variable_* does not match raw formula free variables; expected "
             ^ String.concat "," expected
             ^ " but got "
             ^ String.concat "," actual)
  in
  let immediate_formula_children_of_sexpr sexpr =
    let binary_app head left right =
      match head with
      | "vampire_and" | "vampire_or" ->
          let rec flatten = function
            | List [Atom "AP";
                    List [Atom "AP"; List [Atom "TMH"; nested_head]; nested_left];
                    nested_right]
                when atom nested_head = head ->
                flatten nested_left @ flatten nested_right
            | child -> [child]
          in
          flatten left @ flatten right
          |> List.mapi
               (fun index child -> ("arg_" ^ string_of_int index, child))
      | _ -> []
    in
    match sexpr with
    | List [Atom "AP"; List [Atom "AP"; List [Atom "TMH"; head]; left]; right] ->
        binary_app (atom head) left right
    | List [Atom "IMP"; left; right] ->
        [("left", left); ("right", right)]
    | List [Atom ("NOT" | "TMNOT"); body] ->
        [("body", body)]
    | List [Atom "ALLV"; _name; _tp; body] ->
        let rec strip_forall_group = function
          | List [Atom "ALLV"; _name; _tp; body] -> strip_forall_group body
          | body -> body
        in
        [("body", strip_forall_group body)]
    | List [Atom "LAMV"; _name; _tp; body] ->
        let rec strip_lamv_group = function
          | List [Atom "LAMV"; _name; _tp; body] -> strip_lamv_group body
          | body -> body
        in
        [("body", strip_lamv_group body)]
    | List [Atom "VLAMV"; _name; _tp; body] ->
        let rec strip_vlamv_group = function
          | List [Atom "VLAMV"; _name; _tp; body] -> strip_vlamv_group body
          | body -> body
        in
        [("body", strip_vlamv_group body)]
    | List [Atom "LAM"; _tp; body] ->
        [("body", body)]
    | List [Atom "AP"; List [Atom "TMH"; exists_head];
            List [Atom binder; _name; _tp; body]]
        when atom exists_head = "vampire_exists_prop"
             && (binder = "LAMV" || binder = "VLAMV") ->
        let rec strip_exists_group = function
          | List [Atom "AP"; List [Atom "TMH"; nested_exists_head];
                  List [Atom nested_binder; _name; _tp; body]]
              when atom nested_exists_head = "vampire_exists_prop"
                   && nested_binder = binder ->
              strip_exists_group body
          | body -> body
        in
        [("body", strip_exists_group body)]
    | List [Atom "AP"; List [Atom "TMH"; exists_head];
            List [Atom "LAM"; _tp; body]]
        when atom exists_head = "vampire_exists_prop" ->
        [("body", body)]
    | _ -> []
  in
  let require_formula_child_fields id fields prefix raw_formula =
    match field_value (prefix ^ "_child_count") fields with
    | None -> ()
    | Some _ ->
        let expected =
          immediate_formula_children_of_sexpr (parse_sexpr raw_formula)
        in
        require_field_int
          id fields (prefix ^ "_child_count")
          (List.length expected);
        List.iteri
          (fun index (role, child) ->
             let field_prefix =
               prefix ^ "_child_" ^ string_of_int index
             in
             let actual_role =
               field_required id fields (field_prefix ^ "_role")
             in
             if actual_role <> role then
               error
                 (Printf.sprintf
                    "%s: strict certificate v1 kernel_v1 metadata field %s_role expected %s but raw formula has %s"
                    id field_prefix actual_role role);
             let actual_child =
               parse_field id fields (field_prefix ^ "_formula") parse_tm
             in
             let expected_child = parse_tm child in
             if actual_child <> expected_child then
               error
                 (id ^ ": strict certificate v1 kernel_v1 metadata field "
                  ^ field_prefix
                  ^ "_formula does not match raw formula child"))
          expected
  in
  let validate_skolem_proof_contract id fields =
    match field_value "skolem_contract" fields with
    | None -> ()
    | Some version ->
        if version <> "choice_macro_v1" then
          error
            (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_contract has unsupported version "
             ^ version);
        let primitive_rule =
          field_required id fields "skolem_contract_primitive_rule"
        in
        if primitive_rule <> "skolem_formula" then
          error
            (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_contract_primitive_rule must be skolem_formula");
        begin match field_value "source_unit" fields with
        | Some source_unit ->
            let contract_source_unit =
              field_required id fields "skolem_contract_source_unit"
            in
            if contract_source_unit <> source_unit then
              error
                (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_contract_source_unit does not match source_unit")
        | None -> ()
        end;
        begin match field_value "source_formula" fields with
        | Some raw_source ->
            let source = parse_tm (parse_sexpr raw_source) in
            require_field_tm id fields "skolem_contract_source_formula" source;
            begin match
              field_value "skolem_contract_source_formula_child_count" fields
            with
            | Some _ ->
                require_formula_child_fields
                  id fields "skolem_contract_source_formula" raw_source
            | None -> ()
            end
        | None -> ()
        end;
        begin match field_value "result_formula" fields with
        | Some raw_result ->
            let result = parse_tm (parse_sexpr raw_result) in
            require_field_tm id fields "skolem_contract_result_formula" result;
            begin match
              field_value "skolem_contract_result_formula_child_count" fields
            with
            | Some _ ->
                require_formula_child_fields
                  id fields "skolem_contract_result_formula" raw_result
            | None -> ()
            end
        | None -> ()
        end;
        begin match field_value "proof_parent_count" fields with
        | Some proof_parent_count ->
            let expected =
              try int_of_string proof_parent_count
              with Failure _ ->
                error
                  (id ^ ": strict certificate v1 kernel_v1 metadata field proof_parent_count is not an integer")
            in
            require_field_int id fields "skolem_contract_proof_parent_count" expected
        | None -> ()
        end;
        begin match field_value "introduced_count" fields with
        | Some introduced_count ->
            let expected =
              try int_of_string introduced_count
              with Failure _ ->
                error
                  (id ^ ": strict certificate v1 kernel_v1 metadata field introduced_count is not an integer")
            in
            require_field_int id fields "skolem_contract_introduced_count" expected;
            let choice =
              field_required id fields "skolem_contract_uses_classical_choice"
            in
            let expected_choice = if expected > 0 then "1" else "0" in
            if choice <> expected_choice then
              error
                (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_contract_uses_classical_choice does not match introduced_count")
        | None -> ()
        end;
        begin match
          field_value "skolem_contract_parent_step_variable_count" fields,
          field_value "skolem_contract_parent_instantiation_count" fields
        with
        | None, None -> ()
        | Some _, Some _ ->
            let variable_count =
              require_nonnegative_field_int
                id fields "skolem_contract_parent_step_variable_count"
            in
            let instantiation_count =
              require_nonnegative_field_int
                id fields "skolem_contract_parent_instantiation_count"
            in
            if variable_count <> instantiation_count then
              error
                (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_contract_parent_instantiation_count does not match parent_step_variable_count");
            let global_introduced_count =
              match field_value "introduced_count" fields with
              | Some _ -> require_nonnegative_field_int id fields "introduced_count"
              | None -> 0
            in
            for variable_index = 0 to variable_count - 1 do
              let variable_prefix =
                "skolem_contract_parent_step_variable_"
                ^ string_of_int variable_index
              in
              let instantiation_prefix =
                "skolem_contract_parent_instantiation_"
                ^ string_of_int variable_index
              in
              let variable =
                field_required id fields (variable_prefix ^ "_var")
              in
              let variable_tp =
                parse_field id fields (variable_prefix ^ "_type") parse_tp
              in
              let instantiated_variable =
                field_required id fields (instantiation_prefix ^ "_var")
              in
              if instantiated_variable <> variable then
                error
                  (id ^ ": strict certificate v1 kernel_v1 metadata field "
                   ^ instantiation_prefix
                   ^ "_var does not match "
                   ^ variable_prefix ^ "_var");
              require_field_tp
                id fields (instantiation_prefix ^ "_type") variable_tp;
              let instantiated_term =
                parse_field id fields (instantiation_prefix ^ "_term") parse_tm
              in
              let role =
                field_required id fields (instantiation_prefix ^ "_role")
              in
              begin match role with
              | "preserved_variable" ->
                  if instantiated_term <> TmH variable then
                    error
                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
                       ^ instantiation_prefix
                       ^ "_term must be the preserved variable")
              | "skolem_witness" ->
                  let rec find_witness introduced_index =
                    if introduced_index >= global_introduced_count then None
                    else
                      let global_prefix =
                        "introduced_" ^ string_of_int introduced_index
                      in
                      match
                        field_value (global_prefix ^ "_replaced_var") fields,
                        field_value (global_prefix ^ "_witness_term") fields
                      with
                      | Some replaced_var, Some witness
                          when replaced_var = variable ->
                          Some (parse_tm (parse_sexpr witness))
                      | _ -> find_witness (introduced_index + 1)
                  in
                  begin match find_witness 0 with
                  | Some witness when witness = instantiated_term -> ()
                  | Some _ ->
                      error
                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
                         ^ instantiation_prefix
                         ^ "_term does not match the introduced witness for "
                         ^ variable)
                  | None ->
                      error
                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
                         ^ instantiation_prefix
                         ^ "_role is skolem_witness but no introduced witness replaces "
                         ^ variable)
                  end
              | _ ->
                  error
                    (id ^ ": strict certificate v1 kernel_v1 metadata field "
                     ^ instantiation_prefix
                     ^ "_role has unsupported parent-instantiation role "
                     ^ role)
              end
            done
        | Some _, None ->
            error
              (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_contract_parent_instantiation_count is missing")
        | None, Some _ ->
            error
              (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_contract_parent_step_variable_count is missing")
        end;
        begin match field_value "skolem_macro_edge_count" fields with
        | Some edge_count ->
            let expected =
              try int_of_string edge_count
              with Failure _ ->
                error
                  (id ^ ": strict certificate v1 kernel_v1 metadata field skolem_macro_edge_count is not an integer")
            in
            require_field_int id fields "skolem_contract_macro_edge_count" expected
        | None -> ()
        end
  in
  let validate_skolem_macro_edge_shape_metadata id fields =
    begin match field_value "source_formula" fields with
    | Some raw_source ->
        require_formula_quantifier_fields
          id fields "source_formula" raw_source;
        require_formula_free_variable_fields
          id fields "source_formula" raw_source
    | None -> ()
    end;
    begin match field_value "result_formula" fields with
    | Some raw_result ->
        require_formula_quantifier_fields
          id fields "result_formula" raw_result;
        require_formula_free_variable_fields
          id fields "result_formula" raw_result
    | None -> ()
    end;
    validate_skolem_proof_contract id fields;
    match field_value "skolem_macro_edge_count" fields with
    | None -> ()
    | Some _ ->
        let count = require_nonnegative_field_int id fields "skolem_macro_edge_count" in
        for index = 0 to count - 1 do
          let prefix = "skolem_macro_edge_" ^ string_of_int index in
          begin match field_value (prefix ^ "_formula") fields with
          | Some raw_formula ->
              let formula = parse_tm (parse_sexpr raw_formula) in
              require_formula_shape_fields id fields (prefix ^ "_formula") formula;
              require_formula_quantifier_fields
                id fields (prefix ^ "_formula") raw_formula;
              require_formula_free_variable_fields
                id fields (prefix ^ "_formula") raw_formula;
              require_formula_child_fields
                id fields (prefix ^ "_formula") raw_formula
          | None -> ()
          end;
          begin match field_value (prefix ^ "_source") fields with
          | Some raw_source ->
              let source = parse_tm (parse_sexpr raw_source) in
              require_formula_shape_fields id fields (prefix ^ "_source") source;
              require_formula_quantifier_fields
                id fields (prefix ^ "_source") raw_source;
              require_formula_free_variable_fields
                id fields (prefix ^ "_source") raw_source;
              require_formula_child_fields
                id fields (prefix ^ "_source") raw_source
          | None -> ()
          end;
	          begin match field_value (prefix ^ "_target") fields with
	          | Some raw_target ->
	              let target = parse_tm (parse_sexpr raw_target) in
	              require_formula_shape_fields id fields (prefix ^ "_target") target;
	              require_formula_quantifier_fields
	                id fields (prefix ^ "_target") raw_target;
	              require_formula_free_variable_fields
	                id fields (prefix ^ "_target") raw_target;
	              require_formula_child_fields
	                id fields (prefix ^ "_target") raw_target
	          | None -> ()
	          end;
	          begin match field_value (prefix ^ "_contract") fields with
	          | None -> ()
	          | Some version ->
	              if version <> "branch_v1" then
	                error
	                  (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                   ^ prefix ^ "_contract has unsupported version " ^ version);
	              let primitive_rule =
	                field_required id fields (prefix ^ "_contract_primitive_rule")
	              in
	              if primitive_rule <> "skolem_branch" then
	                error
	                  (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                   ^ prefix ^ "_contract_primitive_rule must be skolem_branch");
	              begin match field_value (prefix ^ "_parent_index") fields with
	              | Some parent_index ->
	                  let expected =
	                    try int_of_string parent_index
	                    with Failure _ ->
	                      error
	                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                         ^ prefix ^ "_parent_index is not an integer")
	                  in
	                  require_field_int
	                    id fields (prefix ^ "_contract_parent_index") expected
	              | None -> ()
	              end;
	              begin match field_value (prefix ^ "_unit") fields with
	              | Some unit_value ->
	                  let contract_unit =
	                    field_required id fields (prefix ^ "_contract_unit")
	                  in
	                  if contract_unit <> unit_value then
	                    error
	                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                       ^ prefix ^ "_contract_unit does not match "
	                       ^ prefix ^ "_unit")
	              | None -> ()
	              end;
	              begin match field_value (prefix ^ "_binder_count") fields with
	              | Some binder_count ->
	                  let expected =
	                    try int_of_string binder_count
	                    with Failure _ ->
	                      error
	                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                         ^ prefix ^ "_binder_count is not an integer")
	                  in
	                  require_field_int
	                    id fields (prefix ^ "_contract_binder_count") expected
	              | None -> ()
	              end;
	              let contract_introduced_count =
	                require_nonnegative_field_int
	                  id fields (prefix ^ "_contract_introduced_count")
	              in
	              let global_introduced_count =
	                match field_value "introduced_count" fields with
	                | Some _ ->
	                    require_nonnegative_field_int
	                      id fields "introduced_count"
	                | None ->
	                    if contract_introduced_count = 0 then 0
	                    else
	                      error
	                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                         ^ prefix
	                         ^ "_contract_introduced_count references missing global introduced_count")
	              in
	              begin match
	                field_value (prefix ^ "_contract_parent_step_variable_count") fields,
	                field_value (prefix ^ "_contract_parent_instantiation_count") fields
	              with
	              | None, None -> ()
	              | Some _, Some _ ->
	                  let variable_count =
	                    require_nonnegative_field_int
	                      id fields
	                      (prefix ^ "_contract_parent_step_variable_count")
	                  in
	                  let instantiation_count =
	                    require_nonnegative_field_int
	                      id fields
	                      (prefix ^ "_contract_parent_instantiation_count")
	                  in
	                  if variable_count <> instantiation_count then
	                    error
	                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                       ^ prefix
	                       ^ "_contract_parent_instantiation_count does not match parent_step_variable_count");
	                  for variable_index = 0 to variable_count - 1 do
	                    let variable_prefix =
	                      prefix ^ "_contract_parent_step_variable_"
	                      ^ string_of_int variable_index
	                    in
	                    let instantiation_prefix =
	                      prefix ^ "_contract_parent_instantiation_"
	                      ^ string_of_int variable_index
	                    in
	                    let variable =
	                      field_required id fields (variable_prefix ^ "_var")
	                    in
	                    let variable_tp =
	                      parse_field id fields (variable_prefix ^ "_type") parse_tp
	                    in
	                    let instantiated_variable =
	                      field_required id fields (instantiation_prefix ^ "_var")
	                    in
	                    if instantiated_variable <> variable then
	                      error
	                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                         ^ instantiation_prefix
	                         ^ "_var does not match "
	                         ^ variable_prefix ^ "_var");
	                    require_field_tp
	                      id fields (instantiation_prefix ^ "_type") variable_tp;
	                    let instantiated_term =
	                      parse_field
	                        id fields (instantiation_prefix ^ "_term") parse_tm
	                    in
	                    let role =
	                      field_required id fields (instantiation_prefix ^ "_role")
	                    in
	                    begin match role with
	                    | "preserved_variable" ->
	                        if instantiated_term <> TmH variable then
	                          error
	                            (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                             ^ instantiation_prefix
	                             ^ "_term must be the preserved variable")
	                    | "skolem_witness" ->
	                        let rec find_witness introduced_index =
	                          if introduced_index >= global_introduced_count then None
	                          else
	                            let global_prefix =
	                              "introduced_" ^ string_of_int introduced_index
	                            in
	                            match
	                              field_value (global_prefix ^ "_replaced_var") fields,
	                              field_value (global_prefix ^ "_witness_term") fields
	                            with
	                            | Some replaced_var, Some witness
	                                when replaced_var = variable ->
	                                Some (parse_tm (parse_sexpr witness))
	                            | _ -> find_witness (introduced_index + 1)
	                        in
	                        begin match find_witness 0 with
	                        | Some witness when witness = instantiated_term -> ()
	                        | Some _ ->
	                            error
	                              (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                               ^ instantiation_prefix
	                               ^ "_term does not match the introduced witness for "
	                               ^ variable)
	                        | None ->
	                            error
	                              (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                               ^ instantiation_prefix
	                               ^ "_role is skolem_witness but no introduced witness replaces "
	                               ^ variable)
	                        end
	                    | _ ->
	                        error
	                          (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                           ^ instantiation_prefix
	                           ^ "_role has unsupported parent-instantiation role "
	                           ^ role)
	                    end
	                  done
	              | Some _, None ->
	                  error
	                    (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                     ^ prefix
	                     ^ "_contract_parent_instantiation_count is missing")
	              | None, Some _ ->
	                  error
	                    (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                     ^ prefix
	                     ^ "_contract_parent_step_variable_count is missing")
	              end;
	              let contract_source =
	                match field_value (prefix ^ "_contract_source_formula") fields with
	                | Some raw_source -> Some (parse_tm (parse_sexpr raw_source))
	                | None -> None
	              in
	              let contract_target =
	                match field_value (prefix ^ "_contract_target_formula") fields with
	                | Some raw_target -> Some (parse_tm (parse_sexpr raw_target))
	                | None -> None
	              in
	              for introduced_local_index = 0 to contract_introduced_count - 1 do
	                let introduced_prefix =
	                  prefix ^ "_contract_introduced_"
	                  ^ string_of_int introduced_local_index
	                in
	                let global_index =
	                  require_nonnegative_field_int
	                    id fields (introduced_prefix ^ "_index")
	                in
	                if global_index >= global_introduced_count then
	                  error
	                    (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                     ^ introduced_prefix
	                     ^ "_index is outside introduced_count");
	                let global_prefix =
	                  "introduced_" ^ string_of_int global_index
	                in
	                let expected_symbol =
	                  field_required id fields (global_prefix ^ "_symbol")
	                in
	                let actual_symbol =
	                  field_required id fields (introduced_prefix ^ "_symbol")
	                in
	                if actual_symbol <> expected_symbol then
	                  error
	                    (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                     ^ introduced_prefix
	                     ^ "_symbol does not match "
	                     ^ global_prefix ^ "_symbol");
	                begin match
	                  field_value (global_prefix ^ "_replaced_var") fields,
	                  field_value (introduced_prefix ^ "_replaced_var") fields
	                with
	                | Some expected, Some actual when actual = expected -> ()
	                | Some expected, Some actual ->
	                    error
	                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                       ^ introduced_prefix
	                       ^ "_replaced_var is " ^ actual
	                       ^ " but " ^ global_prefix
	                       ^ "_replaced_var is " ^ expected)
	                | Some expected, None ->
	                    error
	                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                       ^ introduced_prefix
	                       ^ "_replaced_var is missing expected value "
	                       ^ expected)
	                | None, Some _ ->
	                    error
	                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                       ^ introduced_prefix
	                       ^ "_replaced_var is present but "
	                       ^ global_prefix ^ "_replaced_var is absent")
	                | None, None -> ()
	                end;
	                begin match
	                  field_value (global_prefix ^ "_witness_term") fields,
	                  field_value (introduced_prefix ^ "_witness_term") fields
	                with
	                | Some _expected, Some _actual ->
	                    let expected =
	                      parse_field
	                        id fields (global_prefix ^ "_witness_term") parse_tm
	                    in
	                    require_field_tm
	                      id fields (introduced_prefix ^ "_witness_term") expected
	                | Some _, None ->
	                    error
	                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                       ^ introduced_prefix
	                       ^ "_witness_term is missing expected witness")
	                | None, Some _ ->
	                    error
	                      (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                       ^ introduced_prefix
	                       ^ "_witness_term is present but "
	                       ^ global_prefix ^ "_witness_term is absent")
	                | None, None -> ()
	                end;
	                begin match contract_source, contract_target with
	                | Some source, Some target ->
	                    if tm_contains_symbol actual_symbol source then
	                      error
	                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                         ^ introduced_prefix
	                         ^ "_symbol already occurs in branch source formula");
	                    if not (tm_contains_symbol actual_symbol target) then
	                      error
	                        (id ^ ": strict certificate v1 kernel_v1 metadata field "
	                         ^ introduced_prefix
	                         ^ "_symbol does not occur in branch target formula")
	                | _ -> ()
	                end
	              done;
	              begin match field_value (prefix ^ "_source") fields with
	              | Some raw_source ->
	                  let source = parse_tm (parse_sexpr raw_source) in
	                  require_field_tm
	                    id fields (prefix ^ "_contract_source_formula") source
	              | None -> ()
	              end;
	              begin match field_value (prefix ^ "_target") fields with
	              | Some raw_target ->
	                  let target = parse_tm (parse_sexpr raw_target) in
	                  require_field_tm
	                    id fields (prefix ^ "_contract_target_formula") target
	              | None -> ()
	              end
	          end
	        done
	  in
  let require_field_sat_clause id fields key expected =
    let actual = parse_field id fields key parse_sat_clause in
    if normalize_sat_clause actual <> normalize_sat_clause expected then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " does not match the certificate SAT clause")
  in
  let require_sat_clause_in id key clause clauses =
    let normalized = normalize_sat_clause clause in
    if not (List.exists (fun candidate -> normalize_sat_clause candidate = normalized) clauses) then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " is not one of the AVATAR SAT input clauses")
  in
  let require_earlier_step id owner_index field_name step_id =
    match Hashtbl.find_opt step_indices step_id, owner_index with
    | None, _ ->
        error
          (id ^ ": strict certificate v1 kernel_v1 metadata field "
           ^ field_name ^ " references missing unit " ^ step_id)
    | Some ref_index, Some owner_index when ref_index >= owner_index ->
        error
          (id ^ ": strict certificate v1 kernel_v1 metadata field "
           ^ field_name ^ " references non-earlier unit " ^ step_id)
    | Some _, _ -> ()
  in
  let validate_avatar_component_metadata id fields =
    require_rule_fields id fields "avatar_component"
      ["result_clause";
       "literal_count";
       "split_count";
       "split_0_level";
       "split_0_var";
       "split_0_positive"];
    begin match Hashtbl.find_opt step_by_id id with
    | Some (AvatarComponent (_, result)) ->
        require_field_clause id fields "result_clause" result;
        begin match field_value "conclusion_clause" fields with
        | Some _ -> require_field_clause id fields "conclusion_clause" result
        | None -> ()
        end;
        begin match field_value "result_literal_count" fields with
        | Some _ -> require_field_int id fields "result_literal_count" (List.length result)
        | None -> ()
        end;
        List.iteri
          (fun index literal ->
             let key = "result_literal_" ^ string_of_int index in
             match field_value key fields with
             | Some _ -> require_field_literal id fields key literal
             | None -> ())
          result;
        check_avatar_component_strict id result;
        require_field_int id fields "split_count" 1;
        let split_level = field_int id fields "split_0_level" in
        if split_level < 0 then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_component split_0_level is negative");
        let split_var = field_int id fields "split_0_var" in
        if split_var <= 0 then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_component split_0_var must be positive");
        let split_positive =
          match field_int id fields "split_0_positive" with
          | 0 -> false
          | 1 -> true
          | _ ->
              error
                (id ^ ": strict certificate v1 kernel_v1 avatar_component split_0_positive must be 0 or 1")
        in
        let split_literals, component_literals =
          List.partition is_split_literal result
        in
        begin match split_literals with
        | [split_literal] ->
            if not (avatar_split_literal_matches split_var split_positive split_literal) then
              error
                (id ^ ": strict certificate v1 kernel_v1 avatar_component split metadata does not match the certificate split literal")
        | _ -> assert false
        end;
        require_field_int id fields "literal_count" (List.length component_literals);
        List.iteri
          (fun index literal ->
             require_field_literal id fields
               ("literal_" ^ string_of_int index)
               literal)
          component_literals
    | Some _ ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_component metadata must annotate an avatar_component step")
    | None ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_component metadata has no matching certificate step")
    end
  in
  let validate_avatar_definition_metadata id fields =
    require_rule_fields id fields "avatar_definition"
      ["component_split_level";
       "component_split_var";
       "component_split_positive";
       "component_clause_sexpr";
       "component_clause_variable_sort_count";
       "component_clause_db_sort_count";
       "result_clause"];
    begin match Hashtbl.find_opt step_by_id id with
    | Some (AvatarDefinition (_, split_var, split_positive, result)) ->
        require_field_clause id fields "result_clause" result;
        begin match field_value "conclusion_clause" fields with
        | Some _ -> require_field_clause id fields "conclusion_clause" result
        | None -> ()
        end;
        begin match field_value "result_literal_count" fields with
        | Some _ -> require_field_int id fields "result_literal_count" (List.length result)
        | None -> ()
        end;
        List.iteri
          (fun index literal ->
             let key = "result_literal_" ^ string_of_int index in
             match field_value key fields with
             | Some _ -> require_field_literal id fields key literal
             | None -> ())
          result;
        let split_level = field_int id fields "component_split_level" in
        if split_level < 0 then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_definition component_split_level is negative");
        require_field_int id fields "component_split_var" split_var;
        let metadata_split_positive =
          match field_int id fields "component_split_positive" with
          | 0 -> false
          | 1 -> true
          | _ ->
              error
                (id ^ ": strict certificate v1 kernel_v1 avatar_definition component_split_positive must be 0 or 1")
        in
        if metadata_split_positive <> split_positive then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_definition split polarity does not match the certificate step");
        require_field_clause id fields "component_clause_sexpr" result;
        check_avatar_component_split id split_var split_positive result;
        let variable_sort_count =
          require_nonnegative_field_int id fields "component_clause_variable_sort_count"
        in
        for index = 0 to variable_sort_count - 1 do
          ignore
            (field_required id fields
               ("component_clause_variable_sort_" ^ string_of_int index)
             : string)
        done;
        let db_sort_count =
          require_nonnegative_field_int id fields "component_clause_db_sort_count"
        in
        for index = 0 to db_sort_count - 1 do
          ignore
            (field_required id fields
               ("component_clause_db_sort_" ^ string_of_int index)
             : string)
        done
    | Some _ ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_definition metadata must annotate an avatar_definition step")
    | None ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_definition metadata has no matching certificate step")
    end
  in
  let validate_split_dependency_metadata id fields owner_index =
    require_rule_fields id fields "split_dependency"
      ["dependency_count";
       "result_clause"];
    let step_id =
      match Hashtbl.find_opt step_by_id id with
      | Some (SplitDependency _) -> id
      | _ -> id ^ "_split_dependency"
    in
    begin match Hashtbl.find_opt step_by_id step_id with
    | Some (SplitDependency (_, owner_id, dependencies, result)) ->
        if owner_id <> id then
          error
            (id ^ ": strict certificate v1 kernel_v1 split_dependency owner does not match metadata unit");
        begin match Hashtbl.find_opt step_by_id owner_id with
        | Some _ -> ()
        | None ->
            error
              (id ^ ": strict certificate v1 kernel_v1 split_dependency owner step is missing")
        end;
        require_field_clause id fields "result_clause" result;
        begin match field_value "conclusion_clause" fields with
        | Some _ -> require_field_clause id fields "conclusion_clause" result
        | None -> ()
        end;
        begin match field_value "result_literal_count" fields with
        | Some _ -> require_field_int id fields "result_literal_count" (List.length result)
        | None -> ()
        end;
        List.iteri
          (fun index literal ->
             let key = "result_literal_" ^ string_of_int index in
             match field_value key fields with
             | Some _ -> require_field_literal id fields key literal
             | None -> ())
          result;
        let dependency_count =
          require_nonnegative_field_int id fields "dependency_count"
        in
        if dependency_count <> List.length dependencies then
          error
            (Printf.sprintf
               "%s: strict certificate v1 kernel_v1 split_dependency dependency_count expected %d but got %d"
               id (List.length dependencies) dependency_count);
        List.iteri
          (fun index dependency ->
             let prefix = "dependency_" ^ string_of_int index in
             let split_level = field_int id fields (prefix ^ "_split_level") in
             if split_level < 0 then
               error
                 (id ^ ": strict certificate v1 kernel_v1 split_dependency "
                  ^ prefix ^ "_split_level is negative");
             require_field_int id fields
               (prefix ^ "_split_var")
               dependency.dependency_split_var;
             let metadata_split_positive =
               match field_int id fields (prefix ^ "_split_positive") with
               | 0 -> false
               | 1 -> true
               | _ ->
                   error
                     (id ^ ": strict certificate v1 kernel_v1 split_dependency "
                      ^ prefix ^ "_split_positive must be 0 or 1")
             in
             if metadata_split_positive <> dependency.dependency_split_positive then
               error
                 (id ^ ": strict certificate v1 kernel_v1 split_dependency split polarity does not match the certificate dependency");
             require_field_clause id fields
               (prefix ^ "_component_clause_sexpr")
               dependency.dependency_component;
             check_avatar_component_split_variable
               id dependency.dependency_split_var dependency.dependency_component;
             let variable_sort_count =
               require_nonnegative_field_int id fields
                 (prefix ^ "_component_clause_variable_sort_count")
             in
             for sort_index = 0 to variable_sort_count - 1 do
               ignore
                 (field_required id fields
                    (prefix ^ "_component_clause_variable_sort_"
                     ^ string_of_int sort_index)
                  : string)
             done;
             let db_sort_count =
               require_nonnegative_field_int id fields
                 (prefix ^ "_component_clause_db_sort_count")
             in
             for sort_index = 0 to db_sort_count - 1 do
               ignore
                 (field_required id fields
                    (prefix ^ "_component_clause_db_sort_"
                     ^ string_of_int sort_index)
                  : string)
             done)
          dependencies
    | Some _ ->
        error
          (id ^ ": strict certificate v1 kernel_v1 split_dependency metadata must annotate a split_dependency step")
    | None ->
        error
          (id ^ ": strict certificate v1 kernel_v1 split_dependency metadata has no matching certificate step")
    end
  in
  let validate_avatar_split_metadata id fields owner_index =
    require_rule_fields id fields "avatar_split"
      ["source_unit";
       "source_clause";
       "sat_literal_count";
       "component_parent_ref_count";
       "literal_class_count";
       "parent_var_binding_count";
       "previous_split_count"];
    let bool_field key context =
      match field_int id fields key with
      | 0 -> false
      | 1 -> true
      | _ ->
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_split "
             ^ context ^ " field " ^ key ^ " must be 0 or 1")
    in
    let check_result_split_literal index literal =
      match split_literal_number literal with
      | Some split_var ->
          require_field_int id fields
            ("sat_literal_" ^ string_of_int index ^ "_var")
            split_var;
          let metadata_positive =
            bool_field
              ("sat_literal_" ^ string_of_int index ^ "_positive")
              "SAT literal"
          in
          let result_positive =
            match literal with
            | Pos _ -> true
            | Neg _ -> false
          in
          if metadata_positive <> result_positive then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split SAT literal "
               ^ string_of_int index
               ^ " polarity does not match certificate result")
      | None ->
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_split result literal "
             ^ string_of_int index ^ " is not a split literal")
    in
    begin match Hashtbl.find_opt step_by_id id with
    | Some (AvatarSplit (_, parent_ids, result)) ->
        if result = [] then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_split result is empty");
        let source_unit = field_required id fields "source_unit" in
        begin match parent_ids with
        | source_parent :: _ ->
            if source_parent <> source_unit then
              error
                (id ^ ": strict certificate v1 kernel_v1 avatar_split source_unit "
                 ^ source_unit ^ " does not match first certificate parent "
                 ^ source_parent)
        | [] ->
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split has no certificate parents")
        end;
        require_earlier_step id owner_index "source_unit" source_unit;
        begin match field_value "parent_0_unit" fields with
        | Some parent_0_unit ->
            if parent_0_unit <> source_unit then
              error
                (id ^ ": strict certificate v1 kernel_v1 avatar_split parent_0_unit does not match source_unit")
        | None -> ()
        end;
        let source_clause = parse_field id fields "source_clause" parse_clause in
        begin match field_value "parent_0_clause" fields with
        | Some _ -> require_field_clause id fields "parent_0_clause" source_clause
        | None -> ()
        end;
        begin match field_value "result_clause" fields with
        | Some _ -> require_field_clause id fields "result_clause" result
        | None -> ()
        end;
        begin match field_value "conclusion_clause" fields with
        | Some _ -> require_field_clause id fields "conclusion_clause" result
        | None -> ()
        end;
        begin match field_value "result_literal_count" fields with
        | Some _ -> require_field_int id fields "result_literal_count" (List.length result)
        | None -> ()
        end;
        List.iteri
          (fun index literal ->
             let key = "result_literal_" ^ string_of_int index in
             match field_value key fields with
             | Some _ -> require_field_literal id fields key literal
             | None -> ())
          result;
        require_field_int id fields "sat_literal_count" (List.length result);
        List.iteri check_result_split_literal result;
        let previous_split_count =
          require_nonnegative_field_int id fields "previous_split_count"
        in
        for index = 0 to previous_split_count - 1 do
          let prefix = "previous_split_" ^ string_of_int index in
          let split_level = field_int id fields (prefix ^ "_level") in
          if split_level < 0 then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split "
               ^ prefix ^ "_level is negative");
          let split_var = field_int id fields (prefix ^ "_var") in
          if split_var <= 0 then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split "
               ^ prefix ^ "_var must be positive");
          ignore (bool_field (prefix ^ "_positive") "previous split" : bool)
        done;
        let component_parent_ref_count =
          require_nonnegative_field_int id fields "component_parent_ref_count"
        in
        let expected_component_parents =
          max 0 (List.length parent_ids - 1)
        in
        if component_parent_ref_count <> expected_component_parents then
          error
            (Printf.sprintf
               "%s: strict certificate v1 kernel_v1 avatar_split component_parent_ref_count expected %d but got %d"
               id expected_component_parents component_parent_ref_count);
        let literal_class_count =
          require_nonnegative_field_int id fields "literal_class_count"
        in
        begin match field_value "component_parent_count" fields with
        | Some _ ->
            let component_parent_count =
              require_nonnegative_field_int id fields "component_parent_count"
            in
            if component_parent_count < component_parent_ref_count then
              error
                (Printf.sprintf
                   "%s: strict certificate v1 kernel_v1 avatar_split component_parent_count %d is smaller than component_parent_ref_count %d"
                   id component_parent_count component_parent_ref_count)
        | None -> ()
        end;
        for index = 0 to component_parent_ref_count - 1 do
          let prefix = "component_parent_ref_" ^ string_of_int index in
          let component_unit = field_required id fields (prefix ^ "_unit") in
          require_earlier_step id owner_index (prefix ^ "_unit") component_unit;
          let expected_parent = List.nth parent_ids (index + 1) in
          if component_unit <> expected_parent then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split "
               ^ prefix ^ "_unit " ^ component_unit
               ^ " does not match certificate parent " ^ expected_parent);
          let split_level = field_int id fields (prefix ^ "_split_level") in
          if split_level < 0 then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split "
               ^ prefix ^ "_split_level is negative");
          let split_var = field_int id fields (prefix ^ "_split_var") in
          if split_var <= 0 then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split "
               ^ prefix ^ "_split_var must be positive");
          let split_positive =
            bool_field (prefix ^ "_split_positive") "component parent"
          in
          let component_clause =
            parse_field id fields (prefix ^ "_clause") parse_clause
          in
          check_avatar_component_split id split_var split_positive component_clause
        done;
        for class_index = 0 to literal_class_count - 1 do
          let prefix = "literal_class_" ^ string_of_int class_index in
          let literal_count =
            require_nonnegative_field_int id fields (prefix ^ "_literal_count")
          in
          for literal_index = 0 to literal_count - 1 do
            ignore
              (field_required id fields
                 (prefix ^ "_literal_" ^ string_of_int literal_index)
               : string)
          done;
          begin match field_value (prefix ^ "_matched_split_level") fields with
          | Some _ ->
              let matched_split_level =
                field_int id fields (prefix ^ "_matched_split_level")
              in
              if matched_split_level < 0 then
                error
                  (id ^ ": strict certificate v1 kernel_v1 avatar_split "
                   ^ prefix ^ "_matched_split_level is negative")
          | None -> ()
          end
        done;
        let parent_var_binding_count =
          require_nonnegative_field_int id fields "parent_var_binding_count"
        in
        for index = 0 to parent_var_binding_count - 1 do
          let prefix = "parent_var_binding_" ^ string_of_int index in
          ignore (field_required id fields (prefix ^ "_parent_var") : string);
          ignore (field_required id fields (prefix ^ "_component_var") : string);
          let split_var = field_int id fields (prefix ^ "_split_var") in
          if split_var <= 0 then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_split "
               ^ prefix ^ "_split_var must be positive")
        done
    | Some _ ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_split metadata must annotate an avatar_split step")
    | None ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_split metadata has no matching certificate step")
    end
  in
  let validate_avatar_refutation_metadata id fields owner_index =
    require_rule_fields id fields "avatar_refutation"
      ["result_clause";
       "sat_refutation_clause";
       "sat_input_count";
       "sat_proof_step_count"];
    begin match Hashtbl.find_opt step_by_id id with
    | Some (AvatarRefutation (_, parent_ids, sat_clauses, proof, result)) ->
        if result <> [] then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_refutation result is not empty");
        require_field_clause id fields "result_clause" result;
        require_field_sat_clause id fields "sat_refutation_clause" [];
        let input_count = require_nonnegative_field_int id fields "sat_input_count" in
        if input_count <> List.length sat_clauses then
          error
            (Printf.sprintf
               "%s: strict certificate v1 kernel_v1 avatar_refutation sat_input_count expected %d but got %d"
               id (List.length sat_clauses) input_count);
        let metadata_inputs =
          List.init input_count
            (fun index ->
               let prefix = "sat_input_" ^ string_of_int index in
               let clause =
                 parse_field id fields (prefix ^ "_clause") parse_sat_clause
               in
               let origin = field_required id fields (prefix ^ "_origin_unit") in
               require_earlier_step id owner_index (prefix ^ "_origin_unit") origin;
               (origin, clause))
        in
        if parent_ids <> [] then begin
          let origins = List.map fst metadata_inputs in
          if origins <> parent_ids then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT input origin units do not match certificate parents")
        end;
        List.iter2
          (fun (_, metadata_clause) certificate_clause ->
             if normalize_sat_clause metadata_clause
                <> normalize_sat_clause certificate_clause then
               error
                 (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT input clause does not match certificate step"))
          metadata_inputs
          sat_clauses;
        let proof_step_count =
          require_nonnegative_field_int id fields "sat_proof_step_count"
        in
        if proof_step_count = 0 then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT proof is empty");
        let checked = ref [] in
        let input_clauses = ref [] in
        let metadata_proof = ref [] in
        for index = 0 to proof_step_count - 1 do
          let prefix = "sat_proof_step_" ^ string_of_int index in
          let step_id = field_int id fields (prefix ^ "_id") in
          if step_id <= 0 then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT proof step ids must be positive");
          if List.mem_assoc step_id !checked then
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_refutation duplicate SAT proof step id");
          let clause =
            parse_field id fields (prefix ^ "_clause") parse_sat_clause
          in
          let kind = field_required id fields (prefix ^ "_kind") in
          begin match kind with
          | "input" ->
              let origin = field_required id fields (prefix ^ "_origin_unit") in
              require_earlier_step id owner_index (prefix ^ "_origin_unit") origin;
              require_sat_clause_in id (prefix ^ "_clause") clause sat_clauses;
              checked := (step_id, clause) :: !checked;
              input_clauses := clause :: !input_clauses;
              metadata_proof := !metadata_proof @ [SatInput (step_id, clause)]
          | "rup" ->
              let parent_count =
                require_nonnegative_field_int id fields (prefix ^ "_parent_count")
              in
              if parent_count = 0 then
                error
                  (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT RUP step has no parents");
              let parents =
                List.init parent_count
                  (fun parent_index ->
                     let parent_prefix =
                       prefix ^ "_parent_" ^ string_of_int parent_index
                     in
                     let parent_id = field_int id fields (parent_prefix ^ "_id") in
                     let parent_clause =
                       parse_field id fields (parent_prefix ^ "_clause") parse_sat_clause
                     in
                     begin match List.assoc_opt parent_id !checked with
                     | Some expected_clause ->
                         if normalize_sat_clause parent_clause
                            <> normalize_sat_clause expected_clause then
                           error
                             (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT RUP parent clause does not match the earlier proof step");
                         (parent_id, parent_clause)
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT RUP parent is not an earlier proof step")
                     end)
              in
              let antecedents = List.map snd parents in
              if not (sat_rup_holds antecedents clause) then
                error
                  (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT RUP step does not follow from its parents");
              let parent_ids = List.map fst parents in
              checked := (step_id, clause) :: !checked;
              metadata_proof := !metadata_proof @ [SatRup (step_id, parent_ids, clause)]
          | _ ->
              error
                (id ^ ": strict certificate v1 kernel_v1 avatar_refutation unsupported SAT proof step kind " ^ kind)
          end
        done;
        if normalize_sat_clauses !input_clauses
           <> normalize_sat_clauses sat_clauses then
          error
            (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT proof inputs do not match certificate SAT clauses");
        begin match !checked with
        | (_, []) :: _ -> ()
        | _ ->
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT proof final step is not the empty clause")
        end;
        begin match proof with
        | Some proof when proof <> !metadata_proof ->
            error
              (id ^ ": strict certificate v1 kernel_v1 avatar_refutation SAT proof metadata does not match the certificate step")
        | Some _ | None -> ()
        end
    | Some _ ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_refutation metadata must annotate an avatar_refutation step")
    | None ->
        error
          (id ^ ": strict certificate v1 kernel_v1 avatar_refutation metadata has no matching certificate step")
    end
  in
  let step_clause_opt = function
    | Input (_, _, clause)
    | CnfFormulaClause (_, _, _, _, clause)
    | CnfLiteral (_, _, clause)
    | DefinitionInput (_, clause)
    | DefinitionRewriteChain (_, _, _, clause)
    | AvatarComponent (_, clause)
    | AvatarDefinition (_, _, _, clause)
    | SplitDependency (_, _, _, clause)
    | AvatarSplit (_, _, clause)
    | AvatarContradiction (_, _, clause)
    | AvatarRefutation (_, _, _, _, clause)
    | FoolExhaustiveness (_, clause)
    | FoolDistinctness (_, clause)
    | InequalityNameIntro (_, clause)
    | InequalitySplit (_, _, _, clause)
    | Substitute (_, _, _, clause)
    | Condensation (_, _, _, clause)
    | UnitResultingResolution (_, _, _, clause)
    | Resolve (_, _, _, _, _, clause)
    | SubsumptionResolution (_, _, _, _, _, _, clause)
    | Factor (_, _, _, _, clause)
    | EqualityResolution (_, _, _, clause)
    | EqualityResolutionConstraints (_, _, _, _, _, clause)
    | EqualityFactoring (_, _, _, _, _, _, clause)
    | EqualityFactoringConstraints (_, _, _, _, _, _, _, clause)
    | TruthConflict (_, _, _, clause)
    | EqualitySymmetry (_, _, _, clause)
    | BoolSimplify (_, _, _, _, _, _, clause)
    | Paramodulate (_, _, _, _, _, _, _, _, clause)
    | Superposition (_, _, _, _, _, _, _, _, _, _, clause) -> Some clause
    | Contradiction (_, _) -> Some []
    | FormulaInput _
    | FormulaTermInput _
    | FormulaTermCopy _
    | RectifyFormula _
    | FoolAtomLift _
    | FoolFormula _
    | EnnfFormula _
    | SkolemFormula _
    | SkolemFormulaComputed _
    | FormulaCopy _
    | FoolBool _
    | PredicateDefinition _
    | PredicateDefinitionFold _
    | PredicateDefinitionFoldChain _ -> None
  in
  let step_formula_opt = function
    | FormulaTermInput (_, _, formula)
    | FormulaTermCopy (_, _, formula)
    | RectifyFormula (_, _, _, formula)
    | FoolFormula (_, _, formula)
    | EnnfFormula (_, _, _, _, formula)
    | SkolemFormula (_, _, _, _, _, formula)
    | PredicateDefinition (_, _, formula)
    | PredicateDefinitionFold (_, _, _, formula)
    | PredicateDefinitionFoldChain (_, _, _, formula) -> Some formula
    | FormulaInput (_, _, literal)
    | FormulaCopy (_, _, literal)
    | FoolBool (_, _, literal) -> Some (formula_tm_of_literal literal)
    | Input _
    | FoolAtomLift _
    | SkolemFormulaComputed (_, _, _)
    | CnfFormulaClause _
    | CnfLiteral _
    | DefinitionInput _
    | DefinitionRewriteChain _
    | AvatarComponent _
    | AvatarDefinition _
    | SplitDependency _
    | AvatarSplit _
    | AvatarContradiction _
    | AvatarRefutation _
    | FoolExhaustiveness _
    | FoolDistinctness _
    | InequalityNameIntro _
    | InequalitySplit _
    | Substitute _
    | Condensation _
    | UnitResultingResolution _
    | Resolve _
    | SubsumptionResolution _
    | Factor _
    | EqualityResolution _
    | EqualityResolutionConstraints _
    | EqualityFactoring _
    | EqualityFactoringConstraints _
    | TruthConflict _
    | EqualitySymmetry _
    | BoolSimplify _
    | Paramodulate _
    | Superposition _
    | Contradiction _ -> None
  in
  let require_formula_parent id parent_id =
    match Hashtbl.find_opt step_by_id parent_id with
    | Some parent_step ->
        begin match step_formula_opt parent_step with
        | Some formula -> formula
        | None ->
            error
              (id ^ ": strict certificate v1 kernel_v1 metadata parent "
               ^ parent_id ^ " is not a formula-bearing step")
        end
    | None ->
        error
          (id ^ ": strict certificate v1 kernel_v1 metadata references missing parent "
           ^ parent_id)
  in
  let decompose_application_spine tm =
    let rec collect head args =
      match head with
      | Ap (fn, arg) -> collect fn (arg :: args)
      | _ -> head, args
    in
    collect tm []
  in
  let strip_outer_parens text =
    let text = String.trim text in
    if String.length text >= 2
       && text.[0] = '('
       && text.[String.length text - 1] = ')' then
      String.sub text 1 (String.length text - 2) |> String.trim
    else text
  in
  let simple_sort_of_text id key text =
    let rec top_arrow text depth i =
      if i + 1 >= String.length text then None
      else
        match text.[i] with
        | '(' -> top_arrow text (depth + 1) (i + 1)
        | ')' -> top_arrow text (depth - 1) (i + 1)
        | '-' when depth = 0 && text.[i + 1] = '>' -> Some i
        | _ -> top_arrow text depth (i + 1)
    in
    let rec parse text =
      let text = strip_outer_parens text in
      match text with
      | "prop" -> Prop
      | "set" -> Set
      | _ ->
          begin match top_arrow text 0 0 with
          | Some arrow ->
              let left = String.sub text 0 arrow in
              let right =
                String.sub text (arrow + 2) (String.length text - arrow - 2)
              in
              Ar (parse left, parse right)
          | None ->
              error
                (id ^ ": strict certificate v1 kernel_v1 metadata field "
                 ^ key ^ " has unsupported sort text " ^ text)
          end
    in
    parse text
  in
  let field_tp_opt id fields key =
    match field_value key fields with
    | None -> None
    | Some _ -> Some (parse_field id fields key parse_tp)
  in
  let require_sort_text_matches_sexpr id fields text_key sexpr_key =
    match field_value text_key fields, field_tp_opt id fields sexpr_key with
    | Some text, Some expected ->
        let actual = simple_sort_of_text id text_key text in
        if actual <> expected then
          error
            (id ^ ": strict certificate v1 kernel_v1 metadata fields "
             ^ text_key ^ " and " ^ sexpr_key ^ " disagree")
    | _ -> ()
  in
  let require_tp_equal id key actual expected =
    if actual <> expected then
      error
        (id ^ ": strict certificate v1 kernel_v1 metadata field "
         ^ key ^ " has unexpected sort")
  in
  let string_suffix suffix text =
    let suffix_len = String.length suffix in
    let text_len = String.length text in
    text_len >= suffix_len
    && String.sub text (text_len - suffix_len) suffix_len = suffix
  in
  let add_variable_declaration table declaration =
    let line = String.trim declaration in
    if string_starts_with "Variable " line then
      let body =
        String.sub line 9 (String.length line - 9) |> String.trim
      in
      match String.index_opt body ':' with
      | None -> ()
      | Some colon ->
          let name = String.sub body 0 colon |> String.trim in
          let sort =
            String.sub body (colon + 1) (String.length body - colon - 1)
            |> String.trim
          in
          let sort =
            if String.length sort > 0 && sort.[String.length sort - 1] = '.' then
              String.sub sort 0 (String.length sort - 1)
            else sort
          in
          Hashtbl.replace table name (simple_sort_of_text "kernel_v1" "declaration" sort)
  in
  let skolem_metadata_symbol_table fields =
    let table = Hashtbl.create 97 in
    let add name sort = Hashtbl.replace table name sort in
    List.iter
      (fun (name, sort) -> add name (simple_sort_of_text "kernel_v1" "builtin" sort))
      [
        ("False", "prop"); ("True", "prop");
        ("f__true", "prop"); ("f__false", "prop");
        ("vampire_true", "prop"); ("vampire_false", "prop");
        ("vampire_or", "prop->prop->prop");
        ("vampire_and", "prop->prop->prop");
        ("vampire_eq_prop", "prop->prop->prop");
        ("vPI", "(set->prop)->prop");
        ("vLAM", "set->set->set");
      ];
    List.iter (add_variable_declaration table) cert.metadata.symbol_declarations;
    List.iter
      (fun field ->
         match String.index_opt field '=' with
         | None -> ()
         | Some eq ->
             let key = String.sub field 0 eq in
             if string_suffix "_declaration" key then
               let value = String.sub field (eq + 1) (String.length field - eq - 1) in
               add_variable_declaration table value)
      fields;
    table
  in
  let rec nth_opt xs index =
    match xs, index with
    | x :: _, 0 -> Some x
    | _ :: rest, n when n > 0 -> nth_opt rest (n - 1)
    | _ -> None
  in
  let tm_type symbol_table env tm =
    let assoc_opt key xs =
      try Some (List.assoc key xs) with Not_found -> None
    in
    let rec infer db_tps = function
      | TmH name ->
          begin match assoc_opt name env with
          | Some tp -> Some tp
          | None -> Hashtbl.find_opt symbol_table name
          end
      | DB index -> nth_opt db_tps index
      | Prim _ -> None
      | TpAp (TmH h, tp) when h = megalodon_eq_poly_hash ->
          Some (Ar (tp, Ar (tp, Prop)))
      | TpAp (tm, _) -> infer db_tps tm
      | Ap (fn, arg) ->
          begin match infer db_tps fn with
          | Some (Ar (arg_tp, result_tp)) ->
              begin match infer db_tps arg with
              | Some actual_arg_tp when actual_arg_tp <> arg_tp -> None
              | _ -> Some result_tp
              end
          | _ -> None
          end
      | Lam (tp, body) ->
          Option.map (fun body_tp -> Ar (tp, body_tp)) (infer (tp :: db_tps) body)
      | Imp _ | All _ -> Some Prop
    in
    infer [] tm
  in
  List.iter
    (fun (id, kind, fields) ->
       if kind = "kernel_v1" then
         let owner_index = Hashtbl.find_opt step_indices id in
         let schema = field_required id fields "schema" in
         if schema <> Vampire_kernel_syntax.schema then
           error (id ^ ": strict certificate v1 rejects unsupported kernel_v1 schema " ^ schema);
         let kernel_rule = field_required id fields "rule" in
         if not (Vampire_kernel_syntax.is_supported_rule kernel_rule) then
           error
             (id ^ ": strict certificate v1 rejects unsupported kernel_v1 rule "
              ^ kernel_rule);
         let conclusion_unit = field_required id fields "conclusion_unit" in
         if conclusion_unit <> id then
          error
             (id ^ ": strict certificate v1 kernel_v1 conclusion_unit "
              ^ conclusion_unit ^ " does not match metadata step id");
         begin match kernel_rule with
         | "resolution" ->
             require_rule_fields id fields kernel_rule
               ["selected";
                "selected_substituted";
                "selected_parent_index";
                "selected_literal_index";
                "selected_parent_unit";
                "other";
                "other_substituted";
                "other_parent_index";
                "other_literal_index";
                "other_parent_unit";
                "primitive_parent_0_substitution";
                "primitive_parent_1_substitution";
                "result_clause";
                "result_literal_count"];
             begin match Hashtbl.find_opt step_by_id id with
             | Some (Resolve (_, left_id, right_id, left_index, right_index, result)) ->
                 let selected_parent_index = field_int id fields "selected_parent_index" in
                 let other_parent_index = field_int id fields "other_parent_index" in
                 let selected_literal_index = field_int id fields "selected_literal_index" in
                 let other_literal_index = field_int id fields "other_literal_index" in
                 let selected_parent_unit = field_required id fields "selected_parent_unit" in
                 let other_parent_unit = field_required id fields "other_parent_unit" in
                 let selected_subst =
                   parse_field id fields "primitive_parent_0_substitution" parse_substitution
                 in
                 let other_subst =
                   parse_field id fields "primitive_parent_1_substitution" parse_substitution
                 in
                 let check_side parent_id parent_index literal_index subst literal_key substituted_key =
                   begin match Hashtbl.find_opt step_by_id parent_id with
                   | Some parent_step ->
                       begin match step_clause_opt parent_step with
                       | Some parent_clause ->
                           let literal =
                             nth literal_index parent_clause
                               (id ^ " strict kernel_v1 resolution pivot literal")
                           in
                           require_field_literal id fields literal_key literal;
                           require_field_literal id fields substituted_key (subst_literal subst literal)
                       | None ->
                           error
                             (id ^ ": strict certificate v1 kernel_v1 resolution parent "
                              ^ parent_id ^ " is not a clause-bearing step")
                       end
                   | None ->
                       error
                         (id ^ ": strict certificate v1 kernel_v1 resolution references missing parent "
                          ^ parent_id)
                   end;
                   ignore parent_index
                 in
                 let matches_left_right =
                   selected_parent_index = 0
                   && other_parent_index = 1
                   && selected_parent_unit = left_id
                   && other_parent_unit = right_id
                   && selected_literal_index = left_index
                   && other_literal_index = right_index
                 in
                 let matches_right_left =
                   selected_parent_index = 1
                   && other_parent_index = 0
                   && selected_parent_unit = right_id
                   && other_parent_unit = left_id
                   && selected_literal_index = right_index
                   && other_literal_index = left_index
                 in
                 if not (matches_left_right || matches_right_left) then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 resolution parent/literal metadata does not match certificate pivots");
                 if matches_left_right then begin
                   check_side left_id selected_parent_index selected_literal_index
                     selected_subst "selected" "selected_substituted";
                   check_side right_id other_parent_index other_literal_index
                     other_subst "other" "other_substituted"
                 end else begin
                   check_side right_id selected_parent_index selected_literal_index
                     selected_subst "selected" "selected_substituted";
                   check_side left_id other_parent_index other_literal_index
                     other_subst "other" "other_substituted"
                 end;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 resolution metadata must annotate a resolve step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 resolution metadata has no matching certificate step")
             end
         | "subsumption_resolution" ->
             require_rule_fields id fields kernel_rule
               ["selected";
                "selected_substituted";
                "selected_parent_index";
                "selected_literal_index";
                "selected_parent_unit";
                "main_parent_index";
                "side_parent_index";
                "side_substitution";
                "side_pivot";
                "side_pivot_substituted";
                "side_pivot_parent_index";
                "side_pivot_literal_index";
                "side_pivot_parent_unit";
                "parent_count";
                "result_clause";
                "result_literal_count"];
             begin match Hashtbl.find_opt step_by_id id with
             | Some (SubsumptionResolution (_, main_parent_id, side_parent_id, selected, side_pivot, side_subst, result)) ->
                 require_field_int id fields "parent_count" 2;
                 let main_parent_index = field_int id fields "main_parent_index" in
                 let side_parent_index = field_int id fields "side_parent_index" in
                 if main_parent_index = side_parent_index then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main and side parent indices must differ");
                 let parent_unit index =
                   field_required id fields ("parent_" ^ string_of_int index ^ "_unit")
                 in
                 if parent_unit main_parent_index <> main_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main_parent_index does not point to certificate main parent");
                 if parent_unit side_parent_index <> side_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side_parent_index does not point to certificate side parent");
                 require_field_int id fields "selected_parent_index" main_parent_index;
                 require_field_int id fields "side_pivot_parent_index" side_parent_index;
                 let selected_literal_index = field_int id fields "selected_literal_index" in
                 let side_pivot_literal_index = field_int id fields "side_pivot_literal_index" in
                 let selected_parent_unit = field_required id fields "selected_parent_unit" in
                 if selected_parent_unit <> main_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution selected_parent_unit "
                      ^ selected_parent_unit ^ " does not match certificate main parent " ^ main_parent_id);
                 let side_pivot_parent_unit = field_required id fields "side_pivot_parent_unit" in
                 if side_pivot_parent_unit <> side_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side_pivot_parent_unit "
                      ^ side_pivot_parent_unit ^ " does not match certificate side parent " ^ side_parent_id);
                 require_field_literal id fields "selected" selected;
                 require_field_literal id fields "selected_substituted" selected;
                 require_field_literal id fields "side_pivot" side_pivot;
                 require_field_substitution id fields "side_substitution" side_subst;
                 require_field_literal id fields "side_pivot_substituted" (subst_literal side_subst side_pivot);
                 begin match Hashtbl.find_opt step_by_id main_parent_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let selected_at_index =
                           nth selected_literal_index parent_clause
                             (id ^ " strict kernel_v1 subsumption_resolution selected literal")
                         in
                         if not (same_literal_mod_vampire_vars selected_at_index selected) then
                           error
                             (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution selected_literal_index does not point to selected literal")
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main parent "
                            ^ main_parent_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution references missing main parent "
                        ^ main_parent_id)
                 end;
                 begin match Hashtbl.find_opt step_by_id side_parent_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let side_at_index =
                           nth side_pivot_literal_index parent_clause
                             (id ^ " strict kernel_v1 subsumption_resolution side pivot literal")
                         in
                         if not (same_literal_mod_vampire_vars side_at_index side_pivot) then
                           error
                             (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side_pivot_literal_index does not point to side pivot")
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side parent "
                            ^ side_parent_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution references missing side parent "
                        ^ side_parent_id)
                 end;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some (Resolve (_, main_parent_id, side_parent_id, selected_index, side_pivot_index, result)) ->
                 require_field_int id fields "parent_count" 2;
                 let main_parent_index = field_int id fields "main_parent_index" in
                 let side_parent_index = field_int id fields "side_parent_index" in
                 if main_parent_index = side_parent_index then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main and side parent indices must differ");
                 let parent_unit index =
                   field_required id fields ("parent_" ^ string_of_int index ^ "_unit")
                 in
                 if parent_unit main_parent_index <> main_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main_parent_index does not point to certificate main parent");
                 let metadata_side_parent_id = parent_unit side_parent_index in
                 let side_parent_source_id, side_parent_subst =
                   if metadata_side_parent_id = side_parent_id then
                     side_parent_id, []
                   else
                     begin match Hashtbl.find_opt step_by_id side_parent_id with
                     | Some (Substitute (_, subst_parent_id, subst, _))
                         when subst_parent_id = metadata_side_parent_id ->
                         metadata_side_parent_id, subst
                     | _ ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side_parent_index "
                            ^ "does not point to certificate side parent or its substitution parent")
                     end
                 in
                 require_field_int id fields "selected_parent_index" main_parent_index;
                 require_field_int id fields "side_pivot_parent_index" side_parent_index;
                 require_field_int id fields "selected_literal_index" selected_index;
                 require_field_int id fields "side_pivot_literal_index" side_pivot_index;
                 let selected_parent_unit = field_required id fields "selected_parent_unit" in
                 if selected_parent_unit <> main_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution selected_parent_unit "
                      ^ selected_parent_unit ^ " does not match certificate main parent " ^ main_parent_id);
                 let side_pivot_parent_unit = field_required id fields "side_pivot_parent_unit" in
                 if side_pivot_parent_unit <> side_parent_source_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side_pivot_parent_unit "
                      ^ side_pivot_parent_unit ^ " does not match certificate side parent "
                      ^ side_parent_source_id);
                 require_field_substitution id fields "side_substitution" side_parent_subst;
                 begin match Hashtbl.find_opt step_by_id main_parent_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let selected =
                           nth selected_index parent_clause
                             (id ^ " strict kernel_v1 subsumption_resolution selected literal")
                         in
                         require_field_literal id fields "selected" selected;
                         require_field_literal id fields "selected_substituted" selected
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main parent "
                            ^ main_parent_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution references missing main parent "
                        ^ main_parent_id)
                 end;
                 begin match Hashtbl.find_opt step_by_id side_parent_source_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let side_pivot =
                           nth side_pivot_index parent_clause
                             (id ^ " strict kernel_v1 subsumption_resolution side pivot literal")
                         in
                         require_field_literal id fields "side_pivot" side_pivot;
                         require_field_literal id fields "side_pivot_substituted"
                           (subst_literal side_parent_subst side_pivot)
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side parent "
                            ^ side_parent_source_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution references missing side parent "
                        ^ side_parent_source_id)
                 end;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some (Substitute (_, final_parent_id, [], result))
                 when field_value "primitive_expansion" fields = Some "prefix"
                      && field_value "primitive_expansion_requires" fields = Some "resolve" ->
                 let prefix = field_required id fields "primitive_expansion_prefix" in
                 if prefix <> id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution primitive_expansion_prefix "
                      ^ prefix ^ " does not match macro step id");
                 if not (has_id_prefix final_parent_id prefix) then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution final substitute parent "
                      ^ final_parent_id ^ " is outside the primitive expansion prefix");
                 require_field_int id fields "parent_count" 2;
                 let main_parent_index = field_int id fields "main_parent_index" in
                 let side_parent_index = field_int id fields "side_parent_index" in
                 if main_parent_index = side_parent_index then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main and side parent indices must differ");
                 let parent_unit index =
                   field_required id fields ("parent_" ^ string_of_int index ^ "_unit")
                 in
                 let main_parent_id = parent_unit main_parent_index in
                 let side_parent_id = parent_unit side_parent_index in
                 require_field_int id fields "selected_parent_index" main_parent_index;
                 require_field_int id fields "side_pivot_parent_index" side_parent_index;
                 let selected_index = field_int id fields "selected_literal_index" in
                 let side_pivot_index = field_int id fields "side_pivot_literal_index" in
                 let selected_parent_unit = field_required id fields "selected_parent_unit" in
                 if selected_parent_unit <> main_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution selected_parent_unit "
                      ^ selected_parent_unit ^ " does not match certificate main parent " ^ main_parent_id);
                 let side_pivot_parent_unit = field_required id fields "side_pivot_parent_unit" in
                 if side_pivot_parent_unit <> side_parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side_pivot_parent_unit "
                      ^ side_pivot_parent_unit ^ " does not match certificate side parent " ^ side_parent_id);
                 let side_subst =
                   parse_field id fields "side_substitution" parse_substitution
                 in
                 begin match Hashtbl.find_opt step_by_id main_parent_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let selected =
                           nth selected_index parent_clause
                             (id ^ " strict kernel_v1 subsumption_resolution selected literal")
                         in
                         require_field_literal id fields "selected" selected;
                         require_field_literal id fields "selected_substituted" selected
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution main parent "
                            ^ main_parent_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution references missing main parent "
                        ^ main_parent_id)
                 end;
                 begin match Hashtbl.find_opt step_by_id side_parent_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let side_pivot =
                           nth side_pivot_index parent_clause
                             (id ^ " strict kernel_v1 subsumption_resolution side pivot literal")
                         in
                         require_field_literal id fields "side_pivot" side_pivot;
                         require_field_literal id fields "side_pivot_substituted" (subst_literal side_subst side_pivot)
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution side parent "
                            ^ side_parent_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution references missing side parent "
                        ^ side_parent_id)
                 end;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result);
                 let rec side_parent_matches resolve_side_parent =
                   if side_subst = [] && resolve_side_parent = side_parent_id then
                     true
                   else
                     match Hashtbl.find_opt step_by_id resolve_side_parent with
                     | Some (Substitute (_, subst_parent_id, subst, _)) ->
                         subst_parent_id = side_parent_id && subst = side_subst
                     | Some (EqualitySymmetry (_, parent_id, _, _)) ->
                         side_parent_matches parent_id
                     | _ -> false
                 in
                 let has_matching_resolve =
                   List.exists
                     (function
                       | Resolve (resolve_id, resolve_main_parent, resolve_side_parent,
                                  resolve_selected_index, resolve_side_pivot_index, _)
                           when has_id_prefix resolve_id prefix
                                && resolve_main_parent = main_parent_id
                                && resolve_selected_index = selected_index
                                && resolve_side_pivot_index = side_pivot_index
                                && side_parent_matches resolve_side_parent -> true
                       | _ -> false)
                     cert.steps
                 in
                 if not has_matching_resolve then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution primitive expansion has no matching resolve step")
	             | Some _ ->
	                 error
	                   (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution metadata must annotate a subsumption_resolution step or its resolve primitive")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 subsumption_resolution metadata has no matching certificate step")
             end
         | "instantiation" ->
             require_rule_fields id fields kernel_rule
               ["substitution";
                "parent_count";
                "parent_0_unit";
                "parent_0_clause";
                "parent_0_literal_count";
                "parent_0_substitution";
                "parent_0_substituted_literal_count";
                "result_clause";
                "result_literal_count"];
             require_field_int id fields "parent_count" 1;
             begin match Hashtbl.find_opt step_by_id id with
             | Some (Substitute (_, parent_id, subst, result)) ->
                 let parent_unit = field_required id fields "parent_0_unit" in
                 if parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 instantiation parent_0_unit "
                      ^ parent_unit ^ " does not match substitute parent " ^ parent_id);
                 require_field_substitution id fields "substitution" subst;
                 require_field_substitution id fields "parent_0_substitution" subst;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result);
                 require_field_int id fields "parent_0_substituted_literal_count" (List.length result);
                 begin match Hashtbl.find_opt step_by_id parent_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         require_field_clause id fields "parent_0_clause" parent_clause;
                         require_field_int id fields "parent_0_literal_count" (List.length parent_clause);
                         let expected_result = subst_clause subst parent_clause in
                         if not (same_clause_multiset expected_result result) then
                           error
                             (id ^ ": strict certificate v1 kernel_v1 instantiation substitution does not produce result clause")
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 instantiation parent "
                            ^ parent_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 instantiation references missing parent "
                        ^ parent_id)
                 end
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 instantiation metadata must annotate a substitute step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 instantiation metadata has no matching certificate step")
             end
         | "skolemize" ->
             require_rule_fields id fields kernel_rule
               ["proof_parent_count";
                "parent_0_unit";
                "source_unit";
                "source_formula";
                "result_formula";
                "introduced_count"];
             begin match Hashtbl.find_opt step_by_id id with
             | Some (SkolemFormula (_, parent_id, source, introductions, subst, result)) ->
                 let proof_parent_count = field_int id fields "proof_parent_count" in
                 if proof_parent_count < 1 then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 skolemize proof_parent_count must be positive");
                 let parent_unit = field_required id fields "parent_0_unit" in
                 if parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 skolemize parent_0_unit "
                      ^ parent_unit ^ " does not match skolem_formula parent " ^ parent_id);
                 let source_unit = field_required id fields "source_unit" in
                 if source_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 skolemize source_unit "
                      ^ source_unit ^ " does not match skolem_formula parent " ^ parent_id);
                 let parent_formula = require_formula_parent id parent_id in
                 begin match source with
                 | Some source_formula when source_formula <> parent_formula ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 skolemize source does not match parent formula")
                 | Some _ | None -> ()
                 end;
                 require_field_formula id fields "source_formula" parent_formula;
                 begin match field_value "parent_0_formula" fields with
                 | Some _ -> require_field_formula id fields "parent_0_formula" parent_formula
                 | None -> ()
                 end;
                 require_field_formula id fields "result_formula" result;
                 begin match field_value "conclusion_formula" fields with
                 | Some _ -> require_field_formula id fields "conclusion_formula" result
                 | None -> ()
                 end;
                 validate_skolem_macro_edge_shape_metadata id fields;
                 let introduced_count = field_int id fields "introduced_count" in
                 if introduced_count < 0 then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 skolemize introduced_count must be non-negative");
                 if introduced_count > 0 && proof_parent_count < 2 then
                   error
                     (Printf.sprintf
                        "%s: strict certificate v1 kernel_v1 skolemize proof_parent_count expected a source parent and at least one skolem proof parent but got %d"
                        id proof_parent_count);
                 let rec skolem_parent_body = function
                   | All (_, body) -> skolem_parent_body body
                   | body -> body
                 in
                 for parent_index = 1 to proof_parent_count - 1 do
                   let parent_prefix =
                     "parent_" ^ string_of_int parent_index
                   in
                   ignore
                     (field_required id fields (parent_prefix ^ "_unit") : string);
                   let parent_formula =
                     parse_field id fields (parent_prefix ^ "_formula") parse_tm
                   in
                   match skolem_parent_body parent_formula with
                   | Imp (Ap (TmH "vampire_exists_prop", Lam _), _) -> ()
                   | _ ->
                       error
                         (id ^ ": strict certificate v1 kernel_v1 skolemize "
                          ^ parent_prefix
                          ^ "_formula is not a quantified existential-instantiation implication")
                 done;
                 if introductions <> [] && introduced_count <> List.length introductions then
                   error
                     (Printf.sprintf
                        "%s: strict certificate v1 kernel_v1 skolemize introduced_count expected %d but got %d"
                        id (List.length introductions) introduced_count);
                 let expected_by_symbol =
                   introductions
                   |> List.map
                        (fun introduction ->
                           (introduction.skolem_intro_symbol,
                            (introduction.skolem_intro_replaced_var,
                             introduction.skolem_intro_declaration)))
                 in
                 if introductions <> [] then
                   for index = 0 to introduced_count - 1 do
                     let prefix = "introduced_" ^ string_of_int index in
                     let symbol = field_required id fields (prefix ^ "_symbol") in
                     begin match List.assoc_opt symbol expected_by_symbol with
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 skolemize introduced symbol "
                            ^ symbol ^ " is not present in skolem_formula metadata")
                     | Some (expected_var, expected_declaration) ->
                         begin match expected_var, field_value (prefix ^ "_replaced_var") fields with
                         | Some expected, Some actual when actual = expected -> ()
                         | Some expected, Some actual ->
                             error
                               (id ^ ": strict certificate v1 kernel_v1 skolemize introduced symbol "
                                ^ symbol ^ " replaces " ^ actual ^ " but skolem_formula says " ^ expected)
                         | Some expected, None ->
                             error
                               (id ^ ": strict certificate v1 kernel_v1 skolemize introduced symbol "
                                ^ symbol ^ " is missing replaced_var " ^ expected)
                         | None, _ -> ()
                         end;
                         begin match expected_declaration, field_value (prefix ^ "_declaration") fields with
                         | Some expected, Some actual when actual = expected -> ()
                         | Some expected, Some actual ->
                             error
                               (id ^ ": strict certificate v1 kernel_v1 skolemize introduced symbol "
                                ^ symbol ^ " declaration mismatch: expected "
                                ^ expected ^ " but got " ^ actual)
                         | Some expected, None ->
                             error
                               (id ^ ": strict certificate v1 kernel_v1 skolemize introduced symbol "
                                ^ symbol ^ " is missing declaration " ^ expected)
                         | None, _ -> ()
                         end;
                         begin match expected_var with
                         | None -> ()
                         | Some expected ->
                             begin match List.assoc_opt expected subst with
                             | None ->
                                 error
                                   (id ^ ": strict certificate v1 kernel_v1 skolemize introduced symbol "
                                    ^ symbol ^ " has no substitution for " ^ expected)
                             | Some witness ->
                                 begin match field_value (prefix ^ "_witness_term") fields with
                                 | Some _ -> require_field_tm id fields (prefix ^ "_witness_term") witness
                                 | None -> ()
                                 end;
                                 require_sort_text_matches_sexpr id fields
                                   (prefix ^ "_replaced_var_sort")
                                   (prefix ^ "_replaced_var_sort_sexpr");
                                 require_sort_text_matches_sexpr id fields
                                   (prefix ^ "_witness_sort")
                                   (prefix ^ "_witness_sort_sexpr");
                                 let replaced_sort =
                                   field_tp_opt id fields (prefix ^ "_replaced_var_sort_sexpr")
                                 in
                                 let witness_sort =
                                   field_tp_opt id fields (prefix ^ "_witness_sort_sexpr")
                                 in
                                 begin match replaced_sort, witness_sort with
                                 | Some expected_sort, Some actual_sort ->
                                     require_tp_equal id (prefix ^ "_witness_sort_sexpr")
                                       actual_sort expected_sort
                                 | _ -> ()
                                 end;
                                 let head, dependencies = decompose_application_spine witness in
                                 if head <> TmH symbol then
                                   error
                                     (id ^ ": strict certificate v1 kernel_v1 skolemize witness for "
                                      ^ symbol ^ " does not have the introduced symbol as head");
                                 let symbol_table = skolem_metadata_symbol_table fields in
                                 let dependency_env =
                                   dependencies
                                   |> List.mapi
                                        (fun dependency_index dependency ->
                                           let dependency_prefix =
                                             prefix ^ "_dependency_"
                                             ^ string_of_int dependency_index
                                           in
                                           match dependency,
                                                 field_tp_opt id fields
                                                   (dependency_prefix ^ "_sort_sexpr")
                                           with
                                           | TmH variable, Some sort -> Some (variable, sort)
                                           | _ -> None)
                                   |> List.filter_map (fun x -> x)
                                 in
                                 begin match field_value (prefix ^ "_dependency_count") fields with
                                 | Some _ ->
                                     require_field_int id fields
                                       (prefix ^ "_dependency_count")
                                       (List.length dependencies)
                                 | None -> ()
                                 end;
                                 List.iteri
                                   (fun dependency_index dependency ->
                                      let dependency_prefix =
                                        prefix ^ "_dependency_"
                                        ^ string_of_int dependency_index
                                      in
                                      require_sort_text_matches_sexpr id fields
                                        (dependency_prefix ^ "_sort")
                                        (dependency_prefix ^ "_sort_sexpr");
                                      begin match field_value (dependency_prefix ^ "_term") fields with
                                      | Some _ -> require_field_tm id fields (dependency_prefix ^ "_term") dependency
                                      | None -> ()
                                      end;
                                      begin match
                                        field_tp_opt id fields (dependency_prefix ^ "_sort_sexpr"),
                                        tm_type symbol_table dependency_env dependency
                                      with
                                      | Some expected_sort, Some actual_sort ->
                                          require_tp_equal id (dependency_prefix ^ "_sort_sexpr")
                                            actual_sort expected_sort
                                      | _ -> ()
                                      end;
                                      begin match dependency, field_value (dependency_prefix ^ "_var") fields with
                                      | TmH expected_var, Some actual_var when actual_var = expected_var -> ()
                                      | TmH expected_var, Some actual_var ->
                                          error
                                            (id ^ ": strict certificate v1 kernel_v1 skolemize dependency "
                                             ^ string_of_int dependency_index ^ " var expected "
                                             ^ expected_var ^ " but got " ^ actual_var)
                                      | TmH _, None -> ()
                                      | _, Some actual_var ->
                                          error
                                            (id ^ ": strict certificate v1 kernel_v1 skolemize dependency "
                                             ^ string_of_int dependency_index
                                             ^ " is not a variable but metadata says "
                                             ^ actual_var)
                                      | _, None -> ()
                                      end)
                                   dependencies;
                                 begin match witness_sort, tm_type symbol_table dependency_env witness with
                                 | Some expected_sort, Some actual_sort ->
                                     require_tp_equal id (prefix ^ "_witness_sort_sexpr")
                                       actual_sort expected_sort
                                 | _ -> ()
                                 end;
                                 begin match field_value (prefix ^ "_choice_principle") fields with
                                 | Some "classical_choice" -> ()
                                 | Some actual ->
                                     error
                                       (id ^ ": strict certificate v1 kernel_v1 skolemize unsupported choice_principle "
                                        ^ actual)
                                 | None -> ()
                                 end
                             end
                         end
                     end
                   done
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 skolemize metadata must annotate a skolem_formula step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 skolemize metadata has no matching certificate step")
             end
         | "cnf_clause" ->
             begin match field_value "primitive_expansion" fields with
             | None -> ()
             | Some _ ->
             require_rule_fields id fields kernel_rule
               ["proof_parent_count";
                "parent_0_unit";
                "source_unit";
                "source_kind";
                "result_clause";
                "result_literal_count"];
             require_field_int id fields "proof_parent_count" 1;
             begin match Hashtbl.find_opt step_by_id id with
             | Some (CnfFormulaClause (_, parent_id, index, count, result)) ->
                 let parent_unit = field_required id fields "parent_0_unit" in
                 if parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 cnf_clause parent_0_unit "
                      ^ parent_unit ^ " does not match cnf_formula_clause parent " ^ parent_id);
                 let source_unit = field_required id fields "source_unit" in
                 if source_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 cnf_clause source_unit "
                      ^ source_unit ^ " does not match cnf_formula_clause parent " ^ parent_id);
                 begin match field_value "clause_parent_unit" fields with
                 | Some clause_parent_unit when clause_parent_unit <> parent_id ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 cnf_clause clause_parent_unit "
                        ^ clause_parent_unit ^ " does not match cnf_formula_clause parent " ^ parent_id)
                 | Some _ | None -> ()
                 end;
                 begin match field_value "source_kind" fields with
                 | Some "formula" -> ()
                 | Some kind ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 cnf_clause source_kind "
                        ^ kind ^ " does not match cnf_formula_clause")
                 | None -> assert false
                 end;
                 let parent_formula = require_formula_parent id parent_id in
                 begin match field_value "source_formula" fields with
                 | Some _ -> require_field_formula id fields "source_formula" parent_formula
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 cnf_clause requires source_formula")
                 end;
                 begin match field_value "parent_0_formula" fields with
                 | Some _ -> require_field_formula id fields "parent_0_formula" parent_formula
                 | None -> ()
                 end;
                 let deterministic_clauses = cnf_clauses parent_formula in
                 require_field_int id fields "clause_index" index;
                 begin match count with
                 | Some expected_count ->
                     require_field_int id fields "clause_count" expected_count
                 | None -> ()
                 end;
                 begin match field_value "parent_clause_count" fields with
                 | Some _ ->
                     require_field_int id fields "parent_clause_count"
                       (List.length deterministic_clauses)
                 | None -> ()
                 end;
                 check_cnf_formula_clause
                   [(parent_id, CheckedFormula parent_formula)]
                   id parent_id index count result;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some (CnfLiteral (_, parent_id, result)) ->
                 let parent_unit = field_required id fields "parent_0_unit" in
                 if parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 cnf_clause parent_0_unit "
                      ^ parent_unit ^ " does not match cnf_literal parent " ^ parent_id);
                 let source_unit = field_required id fields "source_unit" in
                 if source_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 cnf_clause source_unit "
                      ^ source_unit ^ " does not match cnf_literal parent " ^ parent_id);
                 begin match field_value "source_kind" fields with
                 | Some "formula" -> ()
                 | Some kind ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 cnf_clause source_kind "
                        ^ kind ^ " does not match cnf_literal")
                 | None -> assert false
                 end;
                 let parent_formula = require_formula_parent id parent_id in
                 begin match field_value "source_formula" fields with
                 | Some _ -> require_field_formula id fields "source_formula" parent_formula
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 cnf_clause requires source_formula")
                 end;
                 begin match field_value "parent_0_formula" fields with
                 | Some _ -> require_field_formula id fields "parent_0_formula" parent_formula
                 | None -> ()
                 end;
                 check_cnf_literal
                   [(parent_id, CheckedFormula parent_formula)]
                   id parent_id result;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 cnf_clause metadata must annotate a cnf clause step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 cnf_clause metadata has no matching certificate step")
             end
             end
         | "factoring" ->
             require_rule_fields id fields kernel_rule
               ["selected";
                "selected_substituted";
                "selected_parent_index";
                "selected_literal_index";
                "selected_parent_unit";
                "other";
                "other_substituted";
                "other_parent_index";
                "other_literal_index";
                "other_parent_unit";
                "primitive_parent_0_substitution";
                "result_clause";
                "result_literal_count"];
             begin match Hashtbl.find_opt step_by_id id with
             | Some (Factor (_, parent_id, left_index, right_index, result)) ->
                 require_field_int id fields "selected_parent_index" 0;
                 require_field_int id fields "other_parent_index" 0;
                 let selected_index = field_int id fields "selected_literal_index" in
                 let other_index = field_int id fields "other_literal_index" in
                 let indices_match =
                   (selected_index = left_index && other_index = right_index)
                   || (selected_index = right_index && other_index = left_index)
                 in
                 if not indices_match then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 factoring selected/other literal indices do not match certificate factor indices");
                 let selected_parent_unit = field_required id fields "selected_parent_unit" in
                 if selected_parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 factoring selected_parent_unit "
                      ^ selected_parent_unit ^ " does not match certificate parent " ^ parent_id);
                 let other_parent_unit = field_required id fields "other_parent_unit" in
                 if other_parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 factoring other_parent_unit "
                      ^ other_parent_unit ^ " does not match certificate parent " ^ parent_id);
                 begin match Hashtbl.find_opt step_by_id parent_id with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let selected =
                           nth selected_index parent_clause
                             (id ^ " strict kernel_v1 factoring selected literal")
                         in
                         let other =
                           nth other_index parent_clause
                             (id ^ " strict kernel_v1 factoring other literal")
                         in
                         require_field_literal id fields "selected" selected;
                         require_field_literal id fields "other" other
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 factoring parent "
                            ^ parent_id ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 factoring references missing parent "
                        ^ parent_id)
                 end;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 factoring metadata must annotate a factor step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 factoring metadata has no matching certificate step")
             end
         | "equality_resolution" ->
             require_rule_fields id fields kernel_rule
               ["selected";
                "selected_substituted";
                "selected_parent_index";
                "selected_literal_index";
                "selected_parent_unit";
                "result_clause";
                "result_literal_count"];
             begin match Hashtbl.find_opt step_by_id id with
             | Some (EqualityResolution (_, parent_id, literal_index, result))
             | Some (EqualityResolutionConstraints (_, parent_id, literal_index, _, _, result)) ->
                 require_field_int id fields "selected_parent_index" 0;
                 require_field_int id fields "selected_literal_index" literal_index;
                 let selected_parent_unit = field_required id fields "selected_parent_unit" in
                 let selected_source_unit, selected_subst =
                   if selected_parent_unit = parent_id then
                     parent_id, []
                   else
                     begin match Hashtbl.find_opt step_by_id parent_id with
                     | Some (Substitute (_, subst_parent_id, subst, _))
                         when subst_parent_id = selected_parent_unit ->
                         selected_parent_unit, subst
                     | _ ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 equality_resolution selected_parent_unit "
                            ^ selected_parent_unit ^ " does not match certificate parent "
                            ^ parent_id ^ " or its substitution parent")
                     end
                 in
                 begin match field_value "parent_0_substitution" fields with
                 | Some _ -> require_field_substitution id fields "parent_0_substitution" selected_subst
                 | None -> ()
                 end;
                 begin match Hashtbl.find_opt step_by_id selected_source_unit with
                 | Some parent_step ->
                     begin match step_clause_opt parent_step with
                     | Some parent_clause ->
                         let selected =
                           nth literal_index parent_clause
                             (id ^ " strict kernel_v1 equality_resolution selected literal")
                         in
                         require_field_literal id fields "selected" selected;
                         require_field_literal id fields "selected_substituted"
                           (subst_literal selected_subst selected)
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 equality_resolution parent "
                            ^ selected_source_unit ^ " is not a clause-bearing step")
                     end
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 equality_resolution references missing parent "
                        ^ selected_source_unit)
                 end;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 equality_resolution metadata must annotate an equality_resolution step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 equality_resolution metadata has no matching certificate step")
             end
         | "superposition" ->
             begin match field_value "primitive_expansion" fields with
             | None -> ()
             | Some _ ->
             require_rule_fields id fields kernel_rule
               ["selected";
                "selected_substituted";
                "selected_parent_index";
                "selected_literal_index";
                "selected_parent_unit";
                "other";
                "other_substituted";
                "other_parent_index";
                "other_literal_index";
                "other_parent_unit";
                "target_substituted";
                "equality_substituted";
                "target_parent_index";
                "target_literal_index";
                "equality_parent_index";
                "equality_literal_index";
                "rewrite_position";
                "from";
                "to";
                "rewritten_target";
                "primitive_parent_0_substitution";
                "primitive_parent_1_substitution";
                "parent_count";
                "result_clause";
                "result_literal_count"];
             require_field_int id fields "parent_count" 2;
             let target_parent_index = field_int id fields "target_parent_index" in
             let equality_parent_index = field_int id fields "equality_parent_index" in
             if target_parent_index = equality_parent_index then
               error
                 (id ^ ": strict certificate v1 kernel_v1 superposition target and equality parent indices must differ");
             require_field_int id fields "selected_parent_index" target_parent_index;
             require_field_int id fields "other_parent_index" equality_parent_index;
             let target_literal_index = field_int id fields "target_literal_index" in
             let equality_literal_index = field_int id fields "equality_literal_index" in
             require_field_int id fields "selected_literal_index" target_literal_index;
             require_field_int id fields "other_literal_index" equality_literal_index;
             let parent_unit index =
               field_required id fields ("parent_" ^ string_of_int index ^ "_unit")
             in
             let target_parent_id = parent_unit target_parent_index in
             let equality_parent_id = parent_unit equality_parent_index in
             let selected_parent_unit = field_required id fields "selected_parent_unit" in
             if selected_parent_unit <> target_parent_id then
               error
                 (id ^ ": strict certificate v1 kernel_v1 superposition selected_parent_unit "
                  ^ selected_parent_unit ^ " does not match target parent " ^ target_parent_id);
             let other_parent_unit = field_required id fields "other_parent_unit" in
             if other_parent_unit <> equality_parent_id then
               error
                 (id ^ ": strict certificate v1 kernel_v1 superposition other_parent_unit "
                  ^ other_parent_unit ^ " does not match equality parent " ^ equality_parent_id);
             let target_subst =
               parse_field id fields
                 ("primitive_parent_" ^ string_of_int target_parent_index ^ "_substitution")
                 parse_substitution
             in
             let equality_subst =
               parse_field id fields
                 ("primitive_parent_" ^ string_of_int equality_parent_index ^ "_substitution")
                 parse_substitution
             in
             let target_literal =
               begin match Hashtbl.find_opt step_by_id target_parent_id with
               | Some parent_step ->
                   begin match step_clause_opt parent_step with
                   | Some parent_clause ->
                       nth target_literal_index parent_clause
                         (id ^ " strict kernel_v1 superposition target literal")
                   | None ->
                       error
                         (id ^ ": strict certificate v1 kernel_v1 superposition target parent "
                          ^ target_parent_id ^ " is not a clause-bearing step")
                   end
               | None ->
                   error
                     (id ^ ": strict certificate v1 kernel_v1 superposition references missing target parent "
                      ^ target_parent_id)
               end
             in
             let equality_literal =
               begin match Hashtbl.find_opt step_by_id equality_parent_id with
               | Some parent_step ->
                   begin match step_clause_opt parent_step with
                   | Some parent_clause ->
                       nth equality_literal_index parent_clause
                         (id ^ " strict kernel_v1 superposition equality literal")
                   | None ->
                       error
                         (id ^ ": strict certificate v1 kernel_v1 superposition equality parent "
                          ^ equality_parent_id ^ " is not a clause-bearing step")
                   end
               | None ->
                   error
                     (id ^ ": strict certificate v1 kernel_v1 superposition references missing equality parent "
                      ^ equality_parent_id)
               end
             in
             let target_substituted = subst_literal target_subst target_literal in
             let equality_substituted = subst_literal equality_subst equality_literal in
             require_field_literal id fields "selected" target_literal;
             require_field_literal id fields "selected_substituted" target_substituted;
             require_field_literal id fields "target_substituted" target_substituted;
             require_field_literal id fields "other" equality_literal;
             require_field_literal id fields "other_substituted" equality_substituted;
             require_field_literal id fields "equality_substituted" equality_substituted;
             let from_tm = parse_field id fields "from" parse_tm in
             let to_tm = parse_field id fields "to" parse_tm in
             begin match equality_substituted with
             | Pos atom ->
                 begin match equality_sides atom with
                 | Some (left, right)
                     when (left = from_tm && right = to_tm)
                       || (right = from_tm && left = to_tm) -> ()
                 | Some _ ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 superposition from/to terms do not match equality literal")
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 superposition equality literal is not an equality")
                 end
             | Neg _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 superposition equality literal must be positive")
             end;
             let rewrite_position = parse_field id fields "rewrite_position" parse_position in
             let rewritten_target = parse_field id fields "rewritten_target" parse_literal in
             let target_atom = literal_atom target_substituted in
             let rewrite_position =
               let rec select = function
                 | [] ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 superposition rewrite_position does not contain from term")
                 | candidate :: rest ->
                     begin match try_tm_at_position target_atom candidate with
                     | Some found when found = from_tm -> candidate
                     | _ -> select rest
                     end
               in
               select (paramodulation_position_candidates target_atom rewrite_position)
             in
             let rewritten_atom =
               replace_tm_at_position target_atom rewrite_position to_tm
                 (id ^ " strict kernel_v1 superposition target")
             in
             let expected_rewritten = replace_literal_atom target_substituted rewritten_atom in
             if not (same_literal_mod_vampire_vars rewritten_target expected_rewritten) then
               error
                 (id ^ ": strict certificate v1 kernel_v1 superposition rewritten_target does not match from/to rewrite");
             begin match Hashtbl.find_opt step_by_id id with
             | Some step ->
                 begin match step_clause_opt step with
                 | Some result ->
                     require_field_clause id fields "result_clause" result;
                     begin match field_value "conclusion_clause" fields with
                     | Some _ -> require_field_clause id fields "conclusion_clause" result
                     | None -> ()
                     end;
                     require_field_int id fields "result_literal_count" (List.length result)
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 superposition metadata must annotate a clause-bearing step")
                 end
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 superposition metadata has no matching certificate step")
             end
             end
         | "rewrite" ->
             require_rule_fields id fields kernel_rule
               ["rule_lhs";
                "redex";
                "parent_count";
                "result_clause";
                "result_literal_count"];
             begin match Hashtbl.find_opt step_by_id id with
             | Some step ->
                 begin match step_clause_opt step with
                 | Some result ->
                     require_field_clause id fields "result_clause" result;
                     begin match field_value "conclusion_clause" fields with
                     | Some _ -> require_field_clause id fields "conclusion_clause" result
                     | None -> ()
                     end;
                     require_field_int id fields "result_literal_count" (List.length result)
                 | None ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 rewrite metadata must annotate a clause-bearing step")
                 end
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 rewrite metadata has no matching certificate step")
             end;
             begin match field_value "target_substituted" fields, field_value "rewritten_target" fields with
             | Some _, Some _ ->
                 require_rule_fields id fields kernel_rule
                   ["equality_substituted";
                    "equality_parent_index";
                    "equality_literal_index";
                    "from";
                    "to";
                    "target_parent_index";
                    "target_literal_index";
                    "rewrite_position";
                    "parent_0_unit";
                    "parent_1_unit"];
                 let parent_count = field_int id fields "parent_count" in
                 if parent_count < 2 then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 rewrite parent_count must be at least 2");
                 let parent_unit index =
                   field_required id fields ("parent_" ^ string_of_int index ^ "_unit")
                 in
                 let parent_substitution index =
                   parse_field id fields
                     ("parent_" ^ string_of_int index ^ "_substitution")
                     parse_substitution
                 in
                 let target_parent_index = field_int id fields "target_parent_index" in
                 let equality_parent_index = field_int id fields "equality_parent_index" in
                 if target_parent_index < 0 || target_parent_index >= parent_count then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 rewrite target_parent_index is outside parent_count");
                 if equality_parent_index < 0 || equality_parent_index >= parent_count then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 rewrite equality_parent_index is outside parent_count");
                 let target_literal_index = field_int id fields "target_literal_index" in
                 let equality_literal_index = field_int id fields "equality_literal_index" in
                 let target_parent_id = parent_unit target_parent_index in
                 let equality_parent_id = parent_unit equality_parent_index in
                 let target_subst = parent_substitution target_parent_index in
                 let equality_subst = parent_substitution equality_parent_index in
                 let parent_clause parent_id role =
                   begin match Hashtbl.find_opt step_by_id parent_id with
                   | Some parent_step ->
                       begin match step_clause_opt parent_step with
                       | Some clause -> clause
                       | None ->
                           error
                             (id ^ ": strict certificate v1 kernel_v1 rewrite "
                              ^ role ^ " parent " ^ parent_id
                              ^ " is not a clause-bearing step")
                       end
                   | None ->
                       error
                         (id ^ ": strict certificate v1 kernel_v1 rewrite references missing "
                          ^ role ^ " parent " ^ parent_id)
                   end
                 in
                 let target_clause = parent_clause target_parent_id "target" in
                 let equality_clause = parent_clause equality_parent_id "equality" in
                 let target_literal =
                   nth target_literal_index target_clause
                     (id ^ " strict kernel_v1 rewrite target literal")
                 in
                 let equality_literal =
                   nth equality_literal_index equality_clause
                     (id ^ " strict kernel_v1 rewrite equality literal")
                 in
                 let target_substituted = subst_literal target_subst target_literal in
                 let equality_substituted = subst_literal equality_subst equality_literal in
                 require_field_literal id fields "target_substituted" target_substituted;
                 require_field_literal id fields "equality_substituted" equality_substituted;
                 let from_tm = parse_field id fields "from" parse_tm in
                 let to_tm = parse_field id fields "to" parse_tm in
                 begin match field_value "replay_redex" fields with
                 | Some _ -> require_field_formula id fields "replay_redex" from_tm
                 | None -> ()
                 end;
                 begin match field_value "replay_replacement" fields with
                 | Some _ -> require_field_formula id fields "replay_replacement" to_tm
                 | None -> ()
                 end;
                 begin match equality_substituted with
                 | Pos atom ->
                     begin match equality_sides atom with
                     | Some (left, right)
                         when (left = from_tm && right = to_tm)
                           || (right = from_tm && left = to_tm) -> ()
                     | Some _ ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 rewrite from/to terms do not match equality literal")
                     | None ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 rewrite equality literal is not an equality")
                     end
                 | Neg _ ->
                     error
                       (id ^ ": strict certificate v1 kernel_v1 rewrite equality literal must be positive")
                 end;
                 let rewrite_position = parse_field id fields "rewrite_position" parse_position in
                 let rewritten_target = parse_field id fields "rewritten_target" parse_literal in
                 let target_atom = literal_atom target_substituted in
                 let rewrite_position =
                   let rec select = function
                     | [] ->
                         error
                           (id ^ ": strict certificate v1 kernel_v1 rewrite rewrite_position does not contain from term")
                     | candidate :: rest ->
                         begin match try_tm_at_position target_atom candidate with
                         | Some found when found = from_tm -> candidate
                         | _ -> select rest
                         end
                   in
                   select (paramodulation_position_candidates target_atom rewrite_position)
                 in
                 let rewritten_atom =
                   replace_tm_at_position target_atom rewrite_position to_tm
                     (id ^ " strict kernel_v1 rewrite target")
                 in
                 let expected_rewritten = replace_literal_atom target_substituted rewritten_atom in
                 if not (same_literal_mod_vampire_vars rewritten_target expected_rewritten) then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 rewrite rewritten_target does not match from/to rewrite");
                 let equality_rest =
                   remove_at equality_literal_index
                     (subst_clause equality_subst equality_clause)
                     (id ^ " rewrite equality literal")
                 in
                 let target_rest =
                   remove_at target_literal_index
                     (subst_clause target_subst target_clause)
                     (id ^ " rewrite target literal")
                 in
                 let expected = equality_rest @ target_rest @ [rewritten_target] in
                 let step_matches_explicit_rewrite step =
                   match step_clause_opt step with
                   | Some result ->
                       same_clause_multiset expected result
                       || same_clause_set_mod_equality expected result
                       || same_clause_mod_vampire_var_renaming expected result
                       || same_clause_mod_vampire_var_renaming_and_equality expected result
                   | None -> false
                 in
                 let explicit_rewrite_present =
                   match Hashtbl.find_opt step_by_id id with
                   | Some step when step_rule_name step = "paramodulate" ->
                       step_matches_explicit_rewrite step
                   | _ ->
                       List.exists
                         (fun step ->
                            step_rule_name step = "paramodulate"
                            && has_id_prefix (step_id step) id
                            && step_matches_explicit_rewrite step)
                         cert.steps
                 in
                 if not explicit_rewrite_present then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 rewrite result_clause does not match explicit rewrite")
             | Some _, None
             | None, Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 rewrite metadata must provide both target_substituted and rewritten_target")
             | None, None -> ()
             end
         | "equality_factoring" ->
             require_rule_fields id fields kernel_rule
               ["selected";
                "selected_substituted";
                "selected_parent_index";
                "selected_literal_index";
                "selected_parent_unit";
                "other";
                "other_substituted";
                "other_parent_index";
                "other_literal_index";
                "other_parent_unit";
                "primitive_parent_0_substitution";
                "result_clause";
                "result_literal_count"];
             begin match Hashtbl.find_opt step_by_id id with
             | Some (EqualityFactoring (_, parent_id, selected_index, other_index, _, subst, result))
             | Some (EqualityFactoringConstraints (_, parent_id, selected_index, other_index, _, subst, _, result)) ->
                 require_field_int id fields "selected_parent_index" 0;
                 require_field_int id fields "other_parent_index" 0;
                 require_field_int id fields "selected_literal_index" selected_index;
                 require_field_int id fields "other_literal_index" other_index;
                 let selected_parent_unit = field_required id fields "selected_parent_unit" in
                 if selected_parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 equality_factoring selected_parent_unit "
                      ^ selected_parent_unit ^ " does not match certificate parent " ^ parent_id);
                 let other_parent_unit = field_required id fields "other_parent_unit" in
                 if other_parent_unit <> parent_id then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 equality_factoring other_parent_unit "
                      ^ other_parent_unit ^ " does not match certificate parent " ^ parent_id);
                 require_field_substitution id fields "primitive_parent_0_substitution" subst;
                 require_field_clause id fields "result_clause" result;
                 begin match field_value "conclusion_clause" fields with
                 | Some _ -> require_field_clause id fields "conclusion_clause" result
                 | None -> ()
                 end;
                 require_field_int id fields "result_literal_count" (List.length result)
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 equality_factoring metadata must annotate an equality_factoring step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 equality_factoring metadata has no matching certificate step")
             end
         | "avatar_component" ->
             validate_avatar_component_metadata id fields
         | "avatar_definition" ->
             validate_avatar_definition_metadata id fields
         | "split_dependency" ->
             validate_split_dependency_metadata id fields owner_index
         | "predicate_definition" ->
             require_rule_fields id fields kernel_rule
               ["introduced_symbol";
                "definiendum_symbol";
                "body_formula";
                "result_formula";
                "body_variable_sort_count";
                "proof_shape";
                "classical_principle";
                "positive_branch";
                "negative_branch"];
             require_field_parse_formula id fields "body_formula";
             begin match Hashtbl.find_opt step_by_id id with
             | Some (PredicateDefinition (_, symbol, result)) ->
                 let introduced = field_required id fields "introduced_symbol" in
                 let definiendum = field_required id fields "definiendum_symbol" in
                 if introduced = "" then
                   error (id ^ ": strict certificate v1 kernel_v1 predicate_definition introduced_symbol is empty");
                 if definiendum <> symbol then
                   error
                     (id ^ ": strict certificate v1 kernel_v1 predicate_definition definiendum_symbol "
                      ^ definiendum ^ " does not match certificate symbol " ^ symbol);
                 require_field_formula id fields "result_formula" result;
                 let count = field_int id fields "body_variable_sort_count" in
                 if count < 0 then
                   error (id ^ ": strict certificate v1 kernel_v1 predicate_definition body_variable_sort_count is negative");
                 for index = 0 to count - 1 do
                   ignore
                     (field_required id fields
                        ("body_variable_sort_" ^ string_of_int index)
                      : string)
                 done;
                 if field_required id fields "proof_shape"
                    <> "classical_definitional_split" then
                   error (id ^ ": strict certificate v1 kernel_v1 predicate_definition unsupported proof_shape");
                 if field_required id fields "classical_principle" <> "xm" then
                   error (id ^ ": strict certificate v1 kernel_v1 predicate_definition requires classical_principle=xm");
                 if field_required id fields "positive_branch" <> "definition_body" then
                   error (id ^ ": strict certificate v1 kernel_v1 predicate_definition unsupported positive_branch");
                 if field_required id fields "negative_branch" <> "negated_definiendum" then
                   error (id ^ ": strict certificate v1 kernel_v1 predicate_definition unsupported negative_branch")
             | Some _ ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 predicate_definition metadata must annotate a predicate_definition step")
             | None ->
                 error
                   (id ^ ": strict certificate v1 kernel_v1 predicate_definition metadata has no matching certificate step")
             end
         | "avatar_split" ->
             validate_avatar_split_metadata id fields owner_index
         | "avatar_refutation" ->
             validate_avatar_refutation_metadata id fields owner_index
         | _ -> ()
         end;
         List.iter
           (fun field ->
              match field_key_value field with
              | Some (key, value)
                   when key <> "conclusion_unit"
                        && string_find_substring "unit" key <> None
                        && is_metadata_step_id_like value ->
                  begin match Hashtbl.find_opt step_indices value, owner_index with
                  | Some ref_index, Some owner_index when ref_index >= owner_index ->
                      error
                        (id ^ ": strict certificate v1 kernel_v1 metadata references non-earlier premise unit " ^ value)
                  | _ -> ()
                  end
              | _ -> ())
           fields)
    cert.metadata.step_extras

let validate_primitive_expansion_contracts cert =
  let steps = cert.steps in
  let has_step_id id =
    List.exists (fun step -> step_id step = id) steps
  in
  let step_by_id id =
    List.find_opt (fun step -> step_id step = id) steps
  in
  let step_clause_opt = function
    | Input (_, _, clause)
    | CnfFormulaClause (_, _, _, _, clause)
    | CnfLiteral (_, _, clause)
    | DefinitionInput (_, clause)
    | DefinitionRewriteChain (_, _, _, clause)
    | AvatarComponent (_, clause)
    | AvatarDefinition (_, _, _, clause)
    | SplitDependency (_, _, _, clause)
    | AvatarSplit (_, _, clause)
    | AvatarContradiction (_, _, clause)
    | AvatarRefutation (_, _, _, _, clause)
    | FoolExhaustiveness (_, clause)
    | FoolDistinctness (_, clause)
    | InequalityNameIntro (_, clause)
    | InequalitySplit (_, _, _, clause)
    | Substitute (_, _, _, clause)
    | Condensation (_, _, _, clause)
    | UnitResultingResolution (_, _, _, clause)
    | Resolve (_, _, _, _, _, clause)
    | SubsumptionResolution (_, _, _, _, _, _, clause)
    | Factor (_, _, _, _, clause)
    | EqualityResolution (_, _, _, clause)
    | EqualityResolutionConstraints (_, _, _, _, _, clause)
    | EqualityFactoring (_, _, _, _, _, _, clause)
    | EqualityFactoringConstraints (_, _, _, _, _, _, _, clause)
    | TruthConflict (_, _, _, clause)
    | EqualitySymmetry (_, _, _, clause)
    | BoolSimplify (_, _, _, _, _, _, clause)
    | Paramodulate (_, _, _, _, _, _, _, _, clause)
    | Superposition (_, _, _, _, _, _, _, _, _, _, clause) -> Some clause
    | Contradiction (_, _) -> Some []
    | FormulaInput _
    | FormulaTermInput _
    | FormulaTermCopy _
    | RectifyFormula _
    | FoolAtomLift _
    | FoolFormula _
    | EnnfFormula _
    | SkolemFormula _
    | SkolemFormulaComputed _
    | FormulaCopy _
    | FoolBool _
    | PredicateDefinition _
    | PredicateDefinitionFold _
    | PredicateDefinitionFoldChain _ -> None
  in
  let has_prefixed_primitive prefix primitive =
    List.exists
      (fun step ->
         ((step_rule_name step = primitive)
          || (primitive = "predicate_definition_intro"
              && match step with PredicateDefinition _ -> true | _ -> false))
         && has_id_prefix (step_id step) prefix)
      steps
  in
  let validate_expansion_index id fields =
    let fail message =
      error (id ^ ": strict certificate v1 " ^ message)
    in
    let field_required key =
      match field_value key fields with
      | Some value -> value
      | None -> fail ("requires " ^ key)
    in
    let field_int key =
      let value = field_required key in
      try int_of_string value with Failure _ ->
        fail ("field " ^ key ^ " is not an integer")
    in
    let prefix =
      match field_value "primitive_expansion_prefix" fields with
      | Some prefix -> prefix
      | None -> id
    in
    begin match field_value "primitive_expansion_step_count" fields with
    | None -> ()
    | Some _ ->
        let count = field_int "primitive_expansion_step_count" in
        if count < 0 then
          fail "primitive_expansion_step_count is negative";
        for index = 0 to count - 1 do
          let key_prefix =
            "primitive_expansion_step_" ^ string_of_int index
          in
          let listed_rule = field_required (key_prefix ^ "_rule") in
          let listed_id = field_required (key_prefix ^ "_id") in
          if not (has_id_prefix listed_id prefix) then
            fail
              ("primitive expansion step " ^ listed_id
               ^ " is outside prefix " ^ prefix);
          match step_by_id listed_id with
          | Some step when step_rule_name step = listed_rule -> ()
          | Some step ->
              fail
                ("primitive expansion step " ^ listed_id
                 ^ " is listed as " ^ listed_rule
                 ^ " but certificate contains " ^ step_rule_name step)
          | None ->
              fail
                ("primitive expansion step " ^ listed_id
                 ^ " is not present in certificate")
        done
    end;
    begin match field_value "primitive_expansion_requires_count" fields with
    | None -> ()
    | Some _ ->
        let count = field_int "primitive_expansion_requires_count" in
        if count < 0 then
          fail "primitive_expansion_requires_count is negative";
        for index = 0 to count - 1 do
          let primitive =
            field_required
              ("primitive_expansion_requires_" ^ string_of_int index)
          in
          if not (has_prefixed_primitive prefix primitive) then
            fail
              ("requires a " ^ primitive
               ^ " primitive step with prefix " ^ prefix)
        done
    end
  in
  let validate_subsumption_resolution_primitive_chain id fields =
    let fail message =
      error (id ^ ": strict certificate v1 " ^ message)
    in
    let field_required key =
      match field_value key fields with
      | Some value -> value
      | None -> fail ("requires " ^ key)
    in
    let field_int key =
      let value = field_required key in
      try int_of_string value with Failure _ ->
        fail ("field " ^ key ^ " is not an integer")
    in
    let parse_clause_field key =
      let value = field_required key in
      try parse_clause (parse_sexpr value) with
      | Error msg ->
          fail
            ("subsumption_resolution field " ^ key
             ^ " is malformed: " ^ msg)
    in
    let parse_substitution_field key =
      let value = field_required key in
      try parse_substitution (parse_sexpr value) with
      | Error msg ->
          fail
            ("subsumption_resolution field " ^ key
             ^ " is malformed: " ^ msg)
    in
    let require_int_field key expected =
      let actual = field_int key in
      if actual <> expected then
        fail
          (Printf.sprintf
             "field %s has value %d but expected %d"
             key actual expected)
    in
    let step_count = field_int "primitive_expansion_step_count" in
    if step_count <= 0 then
      fail "subsumption_resolution primitive_expansion_step_count must be positive";
    let final_result_clause =
      parse_clause_field "primitive_expansion_final_result_clause"
    in
    let result_clause = parse_clause_field "result_clause" in
    if not (same_clause_multiset final_result_clause result_clause) then
      fail
        "subsumption_resolution primitive final result does not match result_clause";
    begin match field_value "conclusion_clause" fields with
    | Some _ ->
        let conclusion_clause = parse_clause_field "conclusion_clause" in
        if not (same_clause_multiset final_result_clause conclusion_clause) then
          fail
            "subsumption_resolution primitive final result does not match conclusion_clause"
    | None -> ()
    end;
    let expected_parent_count = function
      | "resolve" -> 2
      | "substitute" | "equality_symmetry" | "factor" -> 1
      | rule ->
          fail
            ("subsumption_resolution primitive expansion uses unsupported primitive rule "
             ^ rule)
    in
    let has_required_resolve = ref false in
    for index = 0 to step_count - 1 do
      let key_prefix =
        "primitive_expansion_step_" ^ string_of_int index
      in
      let rule = field_required (key_prefix ^ "_rule") in
      let step_id = field_required (key_prefix ^ "_id") in
      let parent_count = field_int (key_prefix ^ "_parent_count") in
      let expected = expected_parent_count rule in
      if parent_count <> expected then
        fail
          (Printf.sprintf
             "subsumption_resolution primitive step %s rule %s expected %d parents but got %d"
             step_id rule expected parent_count);
      for parent_index = 0 to parent_count - 1 do
        let parent_id =
          field_required
            (key_prefix ^ "_parent_" ^ string_of_int parent_index ^ "_id")
        in
        begin match step_by_id parent_id with
        | Some _ -> ()
        | None ->
            fail
              ("subsumption_resolution primitive step " ^ step_id
               ^ " references missing parent " ^ parent_id)
        end
      done;
      let step_result_clause =
        let value = field_required (key_prefix ^ "_result_clause") in
        try parse_clause (parse_sexpr value) with
        | Error msg ->
            fail
              ("subsumption_resolution primitive step " ^ step_id
               ^ " malformed result clause: " ^ msg)
      in
      begin match step_by_id step_id with
      | Some step ->
          begin match step_clause_opt step with
          | Some clause when same_clause_multiset step_result_clause clause -> ()
          | Some _ ->
              fail
                ("subsumption_resolution primitive step " ^ step_id
                 ^ " result_clause does not match certificate step")
          | None ->
              fail
                ("subsumption_resolution primitive step " ^ step_id
                 ^ " does not have a clause result")
          end
      | None ->
          fail
            ("subsumption_resolution primitive step " ^ step_id
             ^ " is not present in certificate")
      end;
      begin match rule, step_by_id step_id with
      | "substitute", Some (Substitute (_, _, subst, _)) ->
          let actual =
            parse_substitution_field (key_prefix ^ "_substitution")
          in
          if actual <> subst then
            fail
              ("subsumption_resolution primitive substitute step "
               ^ step_id ^ " substitution payload does not match certificate step")
      | "resolve", Some (Resolve (_, _, _, left_index, right_index, _)) ->
          has_required_resolve := true;
          require_int_field (key_prefix ^ "_pivot_left") left_index;
          require_int_field (key_prefix ^ "_pivot_right") right_index
      | "equality_symmetry", Some (EqualitySymmetry (_, _, literal_index, _)) ->
          require_int_field (key_prefix ^ "_literal") literal_index
      | "factor", Some (Factor (_, _, left_index, right_index, _)) ->
          require_int_field (key_prefix ^ "_literal_left") left_index;
          require_int_field (key_prefix ^ "_literal_right") right_index
      | "substitute", Some _ ->
          fail
            ("subsumption_resolution primitive step " ^ step_id
             ^ " declares substitute but is not a substitute certificate step")
      | "resolve", Some _ ->
          fail
            ("subsumption_resolution primitive step " ^ step_id
             ^ " declares resolve but is not a resolve certificate step")
      | "equality_symmetry", Some _ ->
          fail
            ("subsumption_resolution primitive step " ^ step_id
             ^ " declares equality_symmetry but is not an equality_symmetry certificate step")
      | "factor", Some _ ->
          fail
            ("subsumption_resolution primitive step " ^ step_id
             ^ " declares factor but is not a factor certificate step")
      | _, None ->
          fail
            ("subsumption_resolution primitive step " ^ step_id
             ^ " is not present in certificate")
      | _ -> ()
      end
    done;
    let final_step_result =
      parse_clause_field
        ("primitive_expansion_step_"
         ^ string_of_int (step_count - 1) ^ "_result_clause")
    in
    if not (same_clause_multiset final_result_clause final_step_result) then
      fail
        "subsumption_resolution primitive final result does not match final primitive step";
    begin match field_value "primitive_expansion_requires_count" fields with
    | Some _ ->
        let requires_count = field_int "primitive_expansion_requires_count" in
        for index = 0 to requires_count - 1 do
          if field_required
               ("primitive_expansion_requires_" ^ string_of_int index)
             = "resolve" then
            has_required_resolve := true
        done
    | None -> ()
    end;
    if not !has_required_resolve then
      fail "subsumption_resolution primitive_expansion_requires_N must include resolve"
  in
  let validate_urr_primitive_chain id fields =
    let fail message =
      error (id ^ ": strict certificate v1 " ^ message)
    in
    let field_required key =
      match field_value key fields with
      | Some value -> value
      | None -> fail ("requires " ^ key)
    in
    let field_int key =
      let value = field_required key in
      try int_of_string value with Failure _ ->
        fail ("field " ^ key ^ " is not an integer")
    in
    let parse_clause_field key =
      let value = field_required key in
      try parse_clause (parse_sexpr value) with
      | Error msg ->
          fail
            ("unit_resulting_resolution field " ^ key
             ^ " is malformed: " ^ msg)
    in
    let parse_substitution_field key =
      let value = field_required key in
      try parse_substitution (parse_sexpr value) with
      | Error msg ->
          fail
            ("unit_resulting_resolution field " ^ key
             ^ " is malformed: " ^ msg)
    in
    let require_int_field key expected =
      let actual = field_int key in
      if actual <> expected then
        fail
          (Printf.sprintf
             "field %s has value %d but expected %d"
             key actual expected)
    in
    let trace_count = field_int "trace_step_count" in
    if trace_count <= 0 then
      fail "unit_resulting_resolution trace_step_count must be positive";
    let step_count = field_int "primitive_expansion_step_count" in
    if step_count <= 0 then
      fail "unit_resulting_resolution primitive_expansion_step_count must be positive";
    let resolve_steps = ref 0 in
    for index = 0 to step_count - 1 do
      let key_prefix =
        "primitive_expansion_step_" ^ string_of_int index
      in
      if field_required (key_prefix ^ "_rule") = "resolve" then
        incr resolve_steps
    done;
    if !resolve_steps <> trace_count then
      fail
        (Printf.sprintf
           "unit_resulting_resolution primitive resolve step count %d does not match trace_step_count %d"
           !resolve_steps trace_count);
    ignore (field_required "trace_main_parent_unit");
    ignore (field_required "trace_remaining");
    for index = 0 to trace_count - 1 do
      let key_prefix = "trace_step_" ^ string_of_int index in
      ignore (field_required (key_prefix ^ "_unit_parent"));
      ignore (field_required (key_prefix ^ "_selected"));
      ignore (field_required (key_prefix ^ "_selected_substituted"));
      ignore (field_required (key_prefix ^ "_unit_substituted"));
      ignore (field_required (key_prefix ^ "_remaining_after"))
    done;
    let final_step_id =
      field_required
        ("primitive_expansion_step_"
         ^ string_of_int (step_count - 1) ^ "_id")
    in
    if final_step_id <> id then
      fail
        ("unit_resulting_resolution final primitive step "
         ^ final_step_id ^ " does not match kernel unit id " ^ id);
    begin match step_by_id id with
    | Some step when step_rule_name step = "unit_resulting_resolution" ->
        fail
          "unit_resulting_resolution must be lowered to primitive final step"
    | Some _ -> ()
    | None -> fail "requires a final certificate step with the kernel unit id"
    end;
    let requires_count = field_int "primitive_expansion_requires_count" in
    if requires_count <= 0 then
      fail "unit_resulting_resolution primitive_expansion_requires_count must be positive";
    let final_result_clause =
      parse_clause_field "primitive_expansion_final_result_clause"
    in
    let result_clause =
      parse_clause_field "result_clause"
    in
    if not (same_clause_multiset final_result_clause result_clause) then
      fail
        "unit_resulting_resolution primitive final result does not match result_clause";
    begin match field_value "conclusion_clause" fields with
    | Some _ ->
        let conclusion_clause = parse_clause_field "conclusion_clause" in
        if not (same_clause_multiset final_result_clause conclusion_clause) then
          fail
            "unit_resulting_resolution primitive final result does not match conclusion_clause"
    | None -> ()
    end;
    let expected_parent_count = function
      | "resolve" -> 2
      | "substitute" | "equality_symmetry" | "factor" -> 1
      | rule ->
          fail
            ("unit_resulting_resolution primitive expansion uses unsupported primitive rule "
             ^ rule)
    in
    for index = 0 to step_count - 1 do
      let key_prefix =
        "primitive_expansion_step_" ^ string_of_int index
      in
      let rule = field_required (key_prefix ^ "_rule") in
      let step_id = field_required (key_prefix ^ "_id") in
      let parent_count = field_int (key_prefix ^ "_parent_count") in
      let expected = expected_parent_count rule in
      if parent_count <> expected then
        fail
          (Printf.sprintf
             "unit_resulting_resolution primitive step %s rule %s expected %d parents but got %d"
             step_id rule expected parent_count);
      for parent_index = 0 to parent_count - 1 do
        let parent_id =
          field_required
            (key_prefix ^ "_parent_" ^ string_of_int parent_index ^ "_id")
        in
        begin match step_by_id parent_id with
        | Some _ -> ()
        | None ->
            fail
              ("unit_resulting_resolution primitive step " ^ step_id
               ^ " references missing parent " ^ parent_id)
        end
      done;
      let result_clause =
        let value = field_required (key_prefix ^ "_result_clause") in
        try parse_clause (parse_sexpr value) with
        | Error msg ->
            fail
              ("unit_resulting_resolution primitive step " ^ step_id
               ^ " malformed result clause: " ^ msg)
      in
      begin match step_by_id step_id with
      | Some step ->
          begin match step_clause_opt step with
          | Some clause when same_clause_multiset result_clause clause -> ()
          | Some _ ->
              fail
                ("unit_resulting_resolution primitive step " ^ step_id
                 ^ " result_clause does not match certificate step")
          | None ->
              fail
                ("unit_resulting_resolution primitive step " ^ step_id
                 ^ " does not have a clause result")
          end
      | None ->
          fail
            ("unit_resulting_resolution primitive step " ^ step_id
             ^ " is not present in certificate")
      end;
      begin match rule, step_by_id step_id with
      | "substitute", Some (Substitute (_, _, subst, _)) ->
          let actual =
            parse_substitution_field (key_prefix ^ "_substitution")
          in
          if actual <> subst then
            fail
              ("unit_resulting_resolution primitive substitute step "
               ^ step_id ^ " substitution payload does not match certificate step")
      | "resolve", Some (Resolve (_, _, _, left_index, right_index, _)) ->
          require_int_field (key_prefix ^ "_pivot_left") left_index;
          require_int_field (key_prefix ^ "_pivot_right") right_index
      | "equality_symmetry", Some (EqualitySymmetry (_, _, literal_index, _)) ->
          require_int_field (key_prefix ^ "_literal") literal_index
      | "factor", Some (Factor (_, _, left_index, right_index, _)) ->
          require_int_field (key_prefix ^ "_literal_left") left_index;
          require_int_field (key_prefix ^ "_literal_right") right_index
      | "substitute", Some _ ->
          fail
            ("unit_resulting_resolution primitive step " ^ step_id
             ^ " declares substitute but is not a substitute certificate step")
      | "resolve", Some _ ->
          fail
            ("unit_resulting_resolution primitive step " ^ step_id
             ^ " declares resolve but is not a resolve certificate step")
      | "equality_symmetry", Some _ ->
          fail
            ("unit_resulting_resolution primitive step " ^ step_id
             ^ " declares equality_symmetry but is not an equality_symmetry certificate step")
      | "factor", Some _ ->
          fail
            ("unit_resulting_resolution primitive step " ^ step_id
             ^ " declares factor but is not a factor certificate step")
      | _, None ->
          fail
            ("unit_resulting_resolution primitive step " ^ step_id
             ^ " is not present in certificate")
      | _ -> ()
      end
    done;
    let final_step_result =
      parse_clause_field
        ("primitive_expansion_step_"
         ^ string_of_int (step_count - 1) ^ "_result_clause")
    in
    if not (same_clause_multiset final_result_clause final_step_result) then
      fail
        "unit_resulting_resolution primitive final result does not match final primitive step";
    let has_required_resolve = ref false in
    for index = 0 to requires_count - 1 do
      let key =
        "primitive_expansion_requires_" ^ string_of_int index
      in
      if field_required key = "resolve" then
        has_required_resolve := true
    done;
    if not !has_required_resolve then
      fail "unit_resulting_resolution primitive_expansion_requires_N must include resolve"
  in
  let validate_contract id kernel_rule primitive_required fields =
    let fail message =
      error (id ^ ": strict certificate v1 " ^ message)
    in
    begin match field_value "primitive_expansion" fields with
    | Some "prefix" -> ()
    | Some other ->
        fail ("rejects unsupported primitive_expansion " ^ other)
    | None ->
        fail ("requires primitive_expansion=prefix for kernel rule " ^ kernel_rule)
    end;
    let prefix =
      match field_value "primitive_expansion_prefix" fields with
      | Some prefix when prefix = id -> prefix
      | Some prefix ->
          fail ("primitive_expansion_prefix " ^ prefix ^ " does not match step id " ^ id)
      | None ->
          fail ("requires primitive_expansion_prefix for kernel rule " ^ kernel_rule)
    in
    begin match field_value "primitive_expansion_requires" fields with
    | Some required when required = primitive_required -> ()
    | Some required ->
        fail
          ("primitive_expansion_requires " ^ required ^ " but "
           ^ primitive_required ^ " is required for " ^ kernel_rule)
    | None ->
        fail ("requires primitive_expansion_requires=" ^ primitive_required ^ " for kernel rule " ^ kernel_rule)
    end;
    if not (has_step_id id) then
      fail "requires a final certificate step with the kernel unit id";
    if not (has_prefixed_primitive prefix primitive_required) then
      fail ("requires a " ^ primitive_required ^ " primitive step with prefix " ^ prefix)
  in
  let validate_one_of_contract id kernel_rule primitive_options fields =
    let fail message =
      error (id ^ ": strict certificate v1 " ^ message)
    in
    match primitive_options with
    | [] -> ()
    | [primitive] -> validate_contract id kernel_rule primitive fields
    | _ ->
        begin match field_value "primitive_expansion" fields with
        | Some "prefix" -> ()
        | Some other ->
            fail ("rejects unsupported primitive_expansion " ^ other)
        | None ->
            fail ("requires primitive_expansion=prefix for kernel rule " ^ kernel_rule)
        end;
        let prefix =
          match field_value "primitive_expansion_prefix" fields with
          | Some prefix when prefix = id -> prefix
          | Some prefix ->
              fail ("primitive_expansion_prefix " ^ prefix ^ " does not match step id " ^ id)
          | None ->
              fail ("requires primitive_expansion_prefix for kernel rule " ^ kernel_rule)
        in
        let primitive_required =
          match field_value "primitive_expansion_requires" fields with
          | Some required when List.mem required primitive_options -> required
          | Some required ->
              fail
                ("primitive_expansion_requires " ^ required ^ " but one of "
                 ^ String.concat ", " primitive_options
                 ^ " is required for " ^ kernel_rule)
          | None ->
              fail
                ("requires primitive_expansion_requires one of "
                 ^ String.concat ", " primitive_options
                 ^ " for kernel rule " ^ kernel_rule)
        in
        if not (has_step_id id) then
          fail "requires a final certificate step with the kernel unit id";
        if not (has_prefixed_primitive prefix primitive_required) then
          fail ("requires a " ^ primitive_required ^ " primitive step with prefix " ^ prefix)
  in
  List.iter
    (fun (id, kind, fields) ->
       if kind = "kernel_v1" then
         begin
         validate_expansion_index id fields;
         match field_value "rule" fields with
         | None -> ()
         | Some kernel_rule ->
             begin match required_primitives_for_kernel_rule kernel_rule with
             | _ :: _ as primitives ->
                 validate_one_of_contract id kernel_rule primitives fields
             | [] ->
                 begin match field_value "primitive_expansion_requires" fields with
                 | Some primitive -> validate_contract id kernel_rule primitive fields
                 | None -> ()
                 end
             end;
             begin
               if kernel_rule = "unit_resulting_resolution" then
                 validate_urr_primitive_chain id fields;
               if kernel_rule = "subsumption_resolution"
                  && field_value "primitive_expansion_step_count" fields <> None then
                 validate_subsumption_resolution_primitive_chain id fields
             end
         end)
    cert.metadata.step_extras

let check_certificate_strict cert =
  validate_kernel_v1_metadata_contracts cert;
  validate_primitive_expansion_contracts cert;
  let has_kernel_v1_metadata id =
    List.exists
      (fun (step_id, kind, fields) ->
         step_id = id
         && kind = "kernel_v1"
         && field_value "schema" fields = Some "prover9-small-kernel-v1")
      cert.metadata.step_extras
  in
  let step_checker checked = function
    | Paramodulate (id, equality_parent_id, target_parent_id, _, _, _, _, _, result)
        when has_kernel_v1_metadata id ->
        ignore (lookup_clause checked equality_parent_id);
        ignore (lookup_clause checked target_parent_id);
        (id, CheckedClause result) :: checked
    | step -> check_step_strict checked step
  in
  check_certificate_with step_checker cert

let validate_certificate_core_fragment cert =
  let has_kernel_instantiation_metadata id =
    List.exists
      (fun (step_id, kind, fields) ->
         step_id = id
         && kind = "kernel_v1"
         && field_value "rule" fields = Some "instantiation")
      cert.metadata.step_extras
  in
  let has_certified_skolem_metadata id =
    List.exists
      (fun (step_id, kind, fields) ->
         step_id = id
         && kind = "kernel_v1"
         && field_value "rule" fields = Some "skolemize"
         && field_value "introduced_0_dependency_count" fields <> None
         && field_value "introduced_0_choice_principle" fields = Some "classical_choice")
      cert.metadata.step_extras
  in
  let certified_skolem_formula = function
    | SkolemFormula
        (id, _, Some _,
         [_], [_], _)
        when has_certified_skolem_metadata id -> true
    | _ -> false
  in
  let allowed = function
    | SkolemFormula _ as step when certified_skolem_formula step -> true
    | Input _
    | FormulaInput _
    | FormulaTermInput _
    | FormulaTermCopy _
    | RectifyFormula _
    | FoolAtomLift _
    | FoolFormula _
    | FoolBool _
    | EnnfFormula _
    | FormulaCopy _
    | CnfLiteral _
    | CnfFormulaClause _
    | DefinitionInput _
    | FoolExhaustiveness _
    | InequalityNameIntro _
    | InequalitySplit _
    | Substitute (_, _, [], _) -> true
    | Substitute (id, _, _, _) when has_kernel_instantiation_metadata id -> true
    | Resolve _
    | SubsumptionResolution _
    | Factor _
    | EqualityResolution _
    | EqualityFactoring _
    | TruthConflict _
    | EqualitySymmetry _
    | Paramodulate _
    | Contradiction _ -> true
    | Substitute _ -> false
    | _ -> false
  in
  let accepted = ref 0 in
  let rejected = ref [] in
  List.iter
    (fun step ->
       if allowed step then incr accepted
       else rejected := !rejected @ [step_id step ^ ":" ^ step_rule_name step])
    cert.steps;
  begin match !rejected with
  | [] -> !accepted
  | _ ->
      let rec take n items =
        if n <= 0 then [] else
        match items with
        | [] -> []
        | head :: tail -> head :: take (n - 1) tail
      in
      let shown = take 12 !rejected in
      let suffix =
        let remaining = List.length !rejected - List.length shown in
        if remaining > 0 then Printf.sprintf " and %d more" remaining else ""
      in
      error
        ("core closed certificate v1 permits only the proof-producing source-entry/core fragment; rejected "
         ^ String.concat ", " shown
         ^ suffix)
  end

let native_core_strip_outer_parens text =
  let text = String.trim text in
  if String.length text >= 2
     && text.[0] = '('
     && text.[String.length text - 1] = ')' then
    String.sub text 1 (String.length text - 2) |> String.trim
  else text

let native_sort_of_simple_sort sort =
  let rec top_arrow text depth i =
    if i + 1 >= String.length text then None
    else
      match text.[i] with
      | '(' -> top_arrow text (depth + 1) (i + 1)
      | ')' -> top_arrow text (depth - 1) (i + 1)
      | '-' when depth = 0 && text.[i + 1] = '>' -> Some i
      | _ -> top_arrow text depth (i + 1)
  in
  let rec parse sort =
    let sort = native_core_strip_outer_parens sort in
    match sort with
    | "prop" -> Prop
    | "set" -> Set
    | _ ->
        begin match top_arrow sort 0 0 with
        | Some arrow ->
            let left = String.sub sort 0 arrow in
            let right =
              String.sub sort (arrow + 2) (String.length sort - arrow - 2)
            in
            Ar (parse left, parse right)
        | None ->
            error
              ("native core proof-term checker supports only prop/set/arrow variables, not " ^ sort)
        end
  in
  parse sort

let native_core_ident s =
  let n = String.length s in
  if n = 0 then error "native core proof-term checker found empty identifier";
  let is_alpha c =
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c = '_'
  in
  let is_ident c = is_alpha c || ('0' <= c && c <= '9') || c = '\'' in
  if not (is_alpha s.[0]) then
    error ("native core proof-term checker found unsupported identifier " ^ s);
  String.iter
    (fun c ->
       if not (is_ident c) then
         error ("native core proof-term checker found unsupported identifier " ^ s))
    s;
  s

let native_core_ident_opt s =
  try Some (native_core_ident s) with Error _ -> None

let native_core_generated_skolem_symbols cert =
  let step_symbols =
    cert.steps
    |> List.filter_map
         (function
           | SkolemFormula (_, _, _, introductions, _, _) ->
               Some
                 (List.map
                    (fun intro -> native_core_ident intro.skolem_intro_symbol)
                    introductions)
           | _ -> None)
    |> List.flatten
  in
  let kernel_v1_symbols =
    cert.metadata.step_extras
    |> List.concat_map
         (fun (_, kind, fields) ->
            if kind <> "kernel_v1" then []
            else
              let collect prefix =
                match field_value (prefix ^ "count") fields with
                | None -> []
                | Some raw_count ->
                    let count =
                      try int_of_string raw_count
                      with Failure _ -> 0
                    in
                    let rec loop index =
                      if index >= count then []
                      else
                        let key = prefix ^ string_of_int index ^ "_symbol" in
                        match field_value key fields with
                        | Some symbol ->
                            native_core_ident symbol :: loop (index + 1)
                        | None -> loop (index + 1)
                    in
                    loop 0
              in
              collect "introduced_"
              @ collect "skolem_contract_introduced_")
  in
  step_symbols @ kernel_v1_symbols
  |> List.sort_uniq compare

let native_core_avatar_definition_names cert =
  cert.steps
  |> List.concat_map
       (function
         | AvatarDefinition (_, split_var, _, _) when split_var > 0 ->
             ["split_" ^ string_of_int split_var]
         | SplitDependency (_, _, dependencies, _) ->
             dependencies
             |> List.filter_map
                  (fun dependency ->
                     if dependency.dependency_split_var > 0 then
                       Some ("split_" ^ string_of_int dependency.dependency_split_var)
                     else
                       None)
         | _ -> [])
  |> List.sort_uniq compare

let native_core_declared_variables ?(exclude_names=[]) cert =
  let generated_skolem_symbols = native_core_generated_skolem_symbols cert in
  let parse_decl decl =
    let line = String.trim decl in
    if not (string_starts_with "Variable " line) then None
    else
      let body =
        String.sub line 9 (String.length line - 9)
        |> String.trim
      in
      match String.index_opt body ':' with
      | None -> None
      | Some colon ->
          let name = String.sub body 0 colon |> String.trim |> native_core_ident in
          let typ =
            String.sub body (colon + 1) (String.length body - colon - 1)
            |> String.trim
          in
          let typ =
            if String.length typ > 0 && typ.[String.length typ - 1] = '.' then
              String.sub typ 0 (String.length typ - 1)
            else typ
          in
          Some (name, native_sort_of_simple_sort (native_core_strip_outer_parens typ))
  in
  cert.metadata.symbol_declarations
  |> List.filter_map parse_decl
  |> List.filter (fun (name, _) -> not (List.mem name exclude_names))
  |> List.filter (fun (name, _) -> not (List.mem name generated_skolem_symbols))
  |> List.sort_uniq compare

let native_core_has_function_definitions cert =
  List.exists
    (fun (_, kind, _) -> kind = "function_definition")
    cert.metadata.step_extras
  || List.exists
       (function
         | InequalityNameIntro _ -> true
         | _ -> false)
       cert.steps

let native_core_predicate_definition_names cert =
  cert.steps
  |> List.filter_map
       (function
         | PredicateDefinition (_, symbol, _) -> Some (native_core_ident symbol)
         | _ -> None)
  |> List.sort_uniq compare

let native_core_proof_variables ?(exclude_names=[]) cert =
  let exclude_names =
    List.sort_uniq compare
      (exclude_names
       @ native_core_avatar_definition_names cert
       @ native_core_predicate_definition_names cert)
  in
  if native_core_has_function_definitions cert then []
  else native_core_declared_variables ~exclude_names cert

let native_core_step_variables cert id =
  let variable_sort_pair sort =
    match String.index_opt sort ':' with
    | Some colon when colon > 0 ->
        Some
          (String.sub sort 0 colon,
           String.sub sort (colon + 1) (String.length sort - colon - 1))
    | _ -> None
  in
  let primitive_expansion_sort_record () =
    match String.index_opt id '_' with
    | Some index when index > 0 ->
        let prefix = String.sub id 0 index in
        List.assoc_opt prefix cert.metadata.step_variable_sorts
    | _ -> None
  in
  match
    match List.assoc_opt id cert.metadata.step_variable_sorts with
    | Some sorts -> Some sorts
    | None -> primitive_expansion_sort_record ()
  with
  | None -> []
  | Some sorts ->
      sorts
      |> List.filter_map variable_sort_pair
      |> List.map
           (fun (name, sort) ->
              (native_core_ident name,
               native_sort_of_simple_sort (native_core_strip_outer_parens sort)))

let native_core_tm_mentions_variable name tm =
  let rec mentions = function
    | TmH raw_name ->
        begin match native_core_ident_opt raw_name with
        | Some ident -> ident = name
        | None -> false
        end
    | TpAp (body, _) -> mentions body
    | Ap (left, right) -> mentions left || mentions right
    | Lam (_, body) | All (_, body) -> mentions body
    | Imp (left, right) -> mentions left || mentions right
    | DB _ | Prim _ -> false
  in
  mentions tm

let native_core_step_variables_for_terms cert id terms =
  native_core_step_variables cert id
  |> List.filter
       (fun (name, _) ->
          List.exists (native_core_tm_mentions_variable name) terms)

let native_core_metadata_step_extra_field cert id kind key =
  let prefix = key ^ "=" in
  let prefix_len = String.length prefix in
  let rec find_field = function
    | [] -> None
    | field :: rest ->
        if String.length field >= prefix_len
           && String.sub field 0 prefix_len = prefix then
          Some (String.sub field prefix_len (String.length field - prefix_len))
        else find_field rest
  in
  let rec find_extra = function
    | [] -> None
    | (extra_id, extra_kind, fields) :: rest ->
        if extra_id = id && extra_kind = kind then find_field fields
        else find_extra rest
  in
  find_extra cert.metadata.step_extras

let native_core_kernel_v1_field cert id key =
  native_core_metadata_step_extra_field cert id "kernel_v1" key

let native_core_kernel_v1_int_field cert id key =
  match native_core_kernel_v1_field cert id key with
  | None -> None
  | Some value ->
      begin try Some (int_of_string value)
      with Failure _ ->
        error
          (id ^ ": kernel_v1 metadata field " ^ key ^ " is not an integer")
      end

let native_core_kernel_v1_required_field cert id key =
  match native_core_kernel_v1_field cert id key with
  | Some value -> value
  | None -> error (id ^ ": kernel_v1 metadata requires " ^ key)

let native_core_kernel_v1_tm_field cert id key =
  native_core_kernel_v1_field cert id key
  |> Option.map (fun value -> parse_tm (parse_sexpr value))

let native_core_kernel_v1_tp_field cert id key =
  native_core_kernel_v1_field cert id key
  |> Option.map (fun value -> parse_tp (parse_sexpr value))

let native_core_kernel_v1_typed_variable_fields cert id prefix role =
  match native_core_kernel_v1_int_field cert id (prefix ^ "_" ^ role ^ "_count") with
  | None -> []
  | Some count ->
      if count < 0 then
        error
          (id ^ ": kernel_v1 metadata field " ^ prefix ^ "_" ^ role
           ^ "_count is negative");
      let rec collect index acc =
        if index >= count then List.rev acc
        else
          let field_prefix =
            prefix ^ "_" ^ role ^ "_" ^ string_of_int index
          in
          let name =
            native_core_kernel_v1_required_field
              cert id (field_prefix ^ "_var")
          in
          let tp =
            match native_core_kernel_v1_tp_field cert id (field_prefix ^ "_type") with
            | Some tp -> tp
            | None ->
                error
                  (id ^ ": kernel_v1 metadata requires "
                   ^ field_prefix ^ "_type")
          in
          collect
            (index + 1)
            ({ native_kernel_variable_name = name;
               native_kernel_variable_type = tp } :: acc)
      in
      collect 0 []

let native_core_kernel_v1_skolem_parent_instantiations cert id prefix =
  match
    native_core_kernel_v1_int_field
      cert id (prefix ^ "_contract_parent_instantiation_count")
  with
  | None -> []
  | Some count ->
      if count < 0 then
        error
          (id ^ ": kernel_v1 metadata field " ^ prefix
           ^ "_contract_parent_instantiation_count is negative");
      let rec collect index acc =
        if index >= count then List.rev acc
        else
          let field_prefix =
            prefix ^ "_contract_parent_instantiation_"
            ^ string_of_int index
          in
          let declared_index =
            match native_core_kernel_v1_int_field cert id (field_prefix ^ "_index") with
            | Some declared_index -> declared_index
            | None -> index
          in
          if declared_index <> index then
            error
              (Printf.sprintf
                 "%s: kernel_v1 metadata field %s_index is %d but expected %d"
                 id field_prefix declared_index index);
          let variable =
            native_core_kernel_v1_required_field
              cert id (field_prefix ^ "_var")
          in
          let tp =
            match native_core_kernel_v1_tp_field cert id (field_prefix ^ "_type") with
            | Some tp -> tp
            | None ->
                error
                  (id ^ ": kernel_v1 metadata requires "
                   ^ field_prefix ^ "_type")
          in
          let term =
            match native_core_kernel_v1_tm_field cert id (field_prefix ^ "_term") with
            | Some term -> term
            | None ->
                error
                  (id ^ ": kernel_v1 metadata requires "
                   ^ field_prefix ^ "_term")
          in
          let role =
            native_core_kernel_v1_required_field
              cert id (field_prefix ^ "_role")
          in
          if role <> "skolem_witness" && role <> "preserved_variable" then
            error
              (id ^ ": kernel_v1 metadata field " ^ field_prefix
               ^ "_role has unsupported parent-instantiation role " ^ role);
          collect
            (index + 1)
            ({ Vampire_kernel_syntax.skolem_parent_inst_index = index;
               skolem_parent_inst_variable = variable;
               skolem_parent_inst_type = tp;
               skolem_parent_inst_term = term;
               skolem_parent_inst_role = role } :: acc)
      in
      collect 0 []

let native_core_validate_skolem_parent_instantiations id label parent_step_variables parent_instantiations =
  begin match parent_step_variables, parent_instantiations with
  | [], [] -> ()
  | _ ->
      if List.length parent_step_variables <> List.length parent_instantiations then
        error
          (Printf.sprintf
             "%s: typed Skolem %s has %d parent step variables but %d instantiations"
             id label
             (List.length parent_step_variables)
             (List.length parent_instantiations));
      List.iter2
        (fun (variable, tp) instantiation ->
           if instantiation.Vampire_kernel_syntax.skolem_parent_inst_variable <> variable
              || instantiation.Vampire_kernel_syntax.skolem_parent_inst_type <> tp then
             error
               (Printf.sprintf
                  "%s: typed Skolem %s parent instantiation %d does not match parent step variable %s"
                  id label
                  instantiation.Vampire_kernel_syntax.skolem_parent_inst_index
                  variable))
        parent_step_variables
        parent_instantiations
  end

let native_core_kernel_v1_quantifier_fields cert id prefix =
  match native_core_kernel_v1_int_field cert id (prefix ^ "_quantifier_count") with
  | None -> []
  | Some count ->
      if count < 0 then
        error
          (id ^ ": kernel_v1 metadata field " ^ prefix
           ^ "_quantifier_count is negative");
      let rec collect index acc =
        if index >= count then List.rev acc
        else
          let field_prefix =
            prefix ^ "_quantifier_" ^ string_of_int index
          in
          let kind =
            native_core_kernel_v1_required_field
              cert id (field_prefix ^ "_kind")
          in
          let name =
            native_core_kernel_v1_required_field
              cert id (field_prefix ^ "_var")
          in
          let tp =
            match native_core_kernel_v1_tp_field cert id (field_prefix ^ "_type") with
            | Some tp -> tp
            | None ->
                error
                  (id ^ ": kernel_v1 metadata requires "
                   ^ field_prefix ^ "_type")
          in
          collect
            (index + 1)
            ({ native_kernel_quantifier_kind = kind;
               native_kernel_quantifier_variable =
                 { native_kernel_variable_name = name;
                   native_kernel_variable_type = tp } } :: acc)
      in
      collect 0 []

let native_core_kernel_v1_formula_child_fields cert id prefix =
  match native_core_kernel_v1_int_field cert id (prefix ^ "_child_count") with
  | None -> []
  | Some count ->
      if count < 0 then
        error (id ^ ": kernel_v1 metadata field " ^ prefix ^ "_child_count is negative");
      let rec collect index acc =
        if index >= count then List.rev acc
        else
          let field_prefix =
            prefix ^ "_child_" ^ string_of_int index
          in
          let role =
            native_core_kernel_v1_required_field
              cert id (field_prefix ^ "_role")
          in
          let formula =
            match native_core_kernel_v1_tm_field cert id (field_prefix ^ "_formula") with
            | Some formula -> formula
            | None ->
                error
                  (id ^ ": kernel_v1 metadata requires "
                   ^ field_prefix ^ "_formula")
          in
          collect (index + 1) ((role, formula) :: acc)
      in
      collect 0 []

let native_core_kernel_v1_skolem_formula_child (role, formula) =
  {
    Vampire_kernel_syntax.skolem_child_role = role;
    skolem_child_formula = formula;
  }

let native_core_kernel_v1_skolem_contract cert id =
  match native_core_kernel_v1_field cert id "skolem_contract" with
  | None -> None
  | Some version ->
      if version <> "choice_macro_v1" then
        error
          (id ^ ": kernel_v1 metadata field skolem_contract has unsupported version "
           ^ version);
      let primitive_rule =
        native_core_kernel_v1_required_field
          cert id "skolem_contract_primitive_rule"
      in
      if primitive_rule <> "skolem_formula" then
        error
          (id ^ ": kernel_v1 metadata field skolem_contract_primitive_rule must be skolem_formula");
      let source_children =
        native_core_kernel_v1_formula_child_fields
          cert id "skolem_contract_source_formula"
        |> List.map native_core_kernel_v1_skolem_formula_child
      in
      let result_children =
        native_core_kernel_v1_formula_child_fields
          cert id "skolem_contract_result_formula"
        |> List.map native_core_kernel_v1_skolem_formula_child
      in
      let introduced_count =
        match
          native_core_kernel_v1_int_field
            cert id "skolem_contract_introduced_count"
        with
        | Some count -> count
        | None ->
            begin match native_core_kernel_v1_int_field cert id "introduced_count" with
            | Some count -> count
            | None -> 0
            end
      in
      if introduced_count < 0 then
        error
          (id ^ ": kernel_v1 metadata field skolem_contract_introduced_count is negative");
      let introduced_witnesses =
        List.init introduced_count
          (fun index ->
             let prefix = "introduced_" ^ string_of_int index in
             {
               Vampire_kernel_syntax.skolem_witness_symbol =
                 native_core_kernel_v1_required_field
                   cert id (prefix ^ "_symbol");
               skolem_witness_replaced_var =
                 native_core_kernel_v1_required_field
                   cert id (prefix ^ "_replaced_var");
               skolem_witness_term =
                 native_core_kernel_v1_tm_field
                   cert id (prefix ^ "_witness_term");
             })
      in
      let parent_step_variables =
        native_core_kernel_v1_typed_variable_fields
          cert id "skolem_contract" "parent_step_variable"
        |> List.map
             (fun variable ->
                (variable.native_kernel_variable_name,
                 variable.native_kernel_variable_type))
      in
      let parent_instantiations =
        native_core_kernel_v1_skolem_parent_instantiations cert id "skolem"
      in
      native_core_validate_skolem_parent_instantiations
        id "proof contract" parent_step_variables parent_instantiations;
      Some
        {
          Vampire_kernel_syntax.skolem_source_children = source_children;
          skolem_result_children = result_children;
          skolem_introduced_witnesses = introduced_witnesses;
          skolem_macro_edge_count =
            native_core_kernel_v1_int_field
              cert id "skolem_contract_macro_edge_count";
          skolem_parent_step_variables = parent_step_variables;
          skolem_parent_instantiations = parent_instantiations;
        }

let native_core_debug_skolem_contract id = function
  | Some contract when Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" ->
      let macro_edge_count =
        match contract.Vampire_kernel_syntax.skolem_macro_edge_count with
        | Some count -> string_of_int count
        | None -> "?"
      in
      prerr_endline
        (Printf.sprintf
           "%s: native Skolem typed contract source_children=%d result_children=%d witnesses=%d macro_edges=%s"
           id
           (List.length contract.Vampire_kernel_syntax.skolem_source_children)
           (List.length contract.Vampire_kernel_syntax.skolem_result_children)
           (List.length contract.Vampire_kernel_syntax.skolem_introduced_witnesses)
           macro_edge_count)
  | _ -> ()

let native_core_skolem_contract_introduced_names = function
  | None -> []
  | Some contract ->
      contract.Vampire_kernel_syntax.skolem_introduced_witnesses
      |> List.map
           (fun witness ->
              witness.Vampire_kernel_syntax.skolem_witness_symbol)

let native_core_kernel_v1_skolem_branch_contract cert id index prefix =
  match native_core_kernel_v1_field cert id (prefix ^ "_contract") with
  | None -> None
  | Some version ->
      if version <> "branch_v1" then
        error
          (id ^ ": kernel_v1 metadata field " ^ prefix
           ^ "_contract has unsupported version " ^ version);
      let primitive_rule =
        native_core_kernel_v1_required_field
          cert id (prefix ^ "_contract_primitive_rule")
      in
      if primitive_rule <> "skolem_branch" then
        error
          (id ^ ": kernel_v1 metadata field " ^ prefix
           ^ "_contract_primitive_rule must be skolem_branch");
      let introduced_count =
        match
          native_core_kernel_v1_int_field
            cert id (prefix ^ "_contract_introduced_count")
        with
        | None -> 0
        | Some count ->
            if count < 0 then
              error
                (id ^ ": kernel_v1 metadata field "
                 ^ prefix ^ "_contract_introduced_count is negative");
            count
      in
      let introduced_witnesses =
        List.init introduced_count
          (fun local_index ->
             let introduced_prefix =
               prefix ^ "_contract_introduced_"
               ^ string_of_int local_index
             in
             ignore
               (match
                 native_core_kernel_v1_int_field
                   cert id (introduced_prefix ^ "_index")
                with
                | Some introduced_index -> introduced_index
                | None ->
                    error
                      (id ^ ": kernel_v1 metadata field "
                       ^ introduced_prefix ^ "_index is missing"));
             {
               Vampire_kernel_syntax.skolem_witness_symbol =
                 native_core_kernel_v1_required_field
                   cert id (introduced_prefix ^ "_symbol");
               skolem_witness_replaced_var =
                 native_core_kernel_v1_required_field
                   cert id (introduced_prefix ^ "_replaced_var");
               skolem_witness_term =
                 native_core_kernel_v1_tm_field
                   cert id (introduced_prefix ^ "_witness_term");
             })
      in
      let parent_step_variables =
        native_core_kernel_v1_typed_variable_fields
          cert id (prefix ^ "_contract") "parent_step_variable"
        |> List.map
             (fun variable ->
                (variable.native_kernel_variable_name,
                 variable.native_kernel_variable_type))
      in
      let parent_instantiations =
        native_core_kernel_v1_skolem_parent_instantiations cert id prefix
      in
      native_core_validate_skolem_parent_instantiations
        id
        ("branch contract " ^ string_of_int index)
        parent_step_variables
        parent_instantiations;
      Some
        {
          Vampire_kernel_syntax.skolem_branch_index = index;
          skolem_branch_parent_index =
            native_core_kernel_v1_int_field
              cert id (prefix ^ "_contract_parent_index");
          skolem_branch_unit =
            native_core_kernel_v1_field
              cert id (prefix ^ "_contract_unit");
          skolem_branch_binder_count =
            native_core_kernel_v1_int_field
              cert id (prefix ^ "_contract_binder_count");
          skolem_branch_source_formula =
            native_core_kernel_v1_tm_field
              cert id (prefix ^ "_contract_source_formula");
          skolem_branch_target_formula =
            native_core_kernel_v1_tm_field
              cert id (prefix ^ "_contract_target_formula");
          skolem_branch_parent_step_variables = parent_step_variables;
          skolem_branch_parent_instantiations = parent_instantiations;
          skolem_branch_introduced_witnesses = introduced_witnesses;
        }

let native_core_skolem_macro_edges cert id =
  match native_core_kernel_v1_int_field cert id "skolem_macro_edge_count" with
  | None -> []
  | Some count ->
      if count < 0 then
        error (id ^ ": kernel_v1 metadata field skolem_macro_edge_count is negative");
      let rec collect index acc =
        if index >= count then List.rev acc
        else
          let prefix = "skolem_macro_edge_" ^ string_of_int index in
          let edge =
            {
              native_skolem_macro_edge_index = index;
              native_skolem_macro_edge_parent_index =
                native_core_kernel_v1_int_field
                  cert id (prefix ^ "_parent_index");
              native_skolem_macro_edge_unit =
                native_core_kernel_v1_field cert id (prefix ^ "_unit");
              native_skolem_macro_edge_binders =
                native_core_kernel_v1_typed_variable_fields
                  cert id prefix "binder";
              native_skolem_macro_edge_formula =
                native_core_kernel_v1_tm_field
                  cert id (prefix ^ "_formula");
              native_skolem_macro_edge_source =
                native_core_kernel_v1_tm_field
                  cert id (prefix ^ "_source");
              native_skolem_macro_edge_target =
                native_core_kernel_v1_tm_field
                  cert id (prefix ^ "_target");
              native_skolem_macro_edge_formula_quantifiers =
                native_core_kernel_v1_quantifier_fields
                  cert id (prefix ^ "_formula");
              native_skolem_macro_edge_source_quantifiers =
                native_core_kernel_v1_quantifier_fields
                  cert id (prefix ^ "_source");
              native_skolem_macro_edge_target_quantifiers =
                native_core_kernel_v1_quantifier_fields
                  cert id (prefix ^ "_target");
              native_skolem_macro_edge_formula_free_variables =
                native_core_kernel_v1_typed_variable_fields
                  cert id (prefix ^ "_formula") "free_variable";
              native_skolem_macro_edge_source_free_variables =
                native_core_kernel_v1_typed_variable_fields
                  cert id (prefix ^ "_source") "free_variable";
              native_skolem_macro_edge_target_free_variables =
                native_core_kernel_v1_typed_variable_fields
                  cert id (prefix ^ "_target") "free_variable";
              native_skolem_macro_edge_formula_children =
                native_core_kernel_v1_formula_child_fields
                  cert id (prefix ^ "_formula")
                |> List.map native_core_kernel_v1_skolem_formula_child;
              native_skolem_macro_edge_source_children =
                native_core_kernel_v1_formula_child_fields
                  cert id (prefix ^ "_source")
                |> List.map native_core_kernel_v1_skolem_formula_child;
              native_skolem_macro_edge_target_children =
                native_core_kernel_v1_formula_child_fields
                  cert id (prefix ^ "_target")
                |> List.map native_core_kernel_v1_skolem_formula_child;
              native_skolem_macro_edge_branch_contract =
                native_core_kernel_v1_skolem_branch_contract cert id index prefix;
            }
          in
          begin match edge.native_skolem_macro_edge_branch_contract with
          | Some contract ->
              begin match
                contract.Vampire_kernel_syntax.skolem_branch_parent_index,
                edge.native_skolem_macro_edge_parent_index
              with
              | Some expected, Some actual when expected <> actual ->
                  error
                    (Printf.sprintf
                       "%s: typed Skolem branch contract %d parent index %d does not match macro edge parent index %d"
                       id index expected actual)
              | _ -> ()
              end;
              begin match
                contract.Vampire_kernel_syntax.skolem_branch_unit,
                edge.native_skolem_macro_edge_unit
              with
              | Some expected, Some actual when expected <> actual ->
                  error
                    (Printf.sprintf
                       "%s: typed Skolem branch contract %d unit %s does not match macro edge unit %s"
                       id index expected actual)
              | _ -> ()
              end;
              begin match contract.Vampire_kernel_syntax.skolem_branch_binder_count with
              | Some expected when expected <> List.length edge.native_skolem_macro_edge_binders ->
                  error
                    (Printf.sprintf
                       "%s: typed Skolem branch contract %d binder count %d does not match macro edge binder count %d"
                       id index expected
                       (List.length edge.native_skolem_macro_edge_binders))
              | _ -> ()
              end
          | None -> ()
          end;
          collect (index + 1) (edge :: acc)
  in
      collect 0 []

let native_core_skolem_proof_object cert id =
  match native_core_kernel_v1_skolem_contract cert id with
  | None -> None
  | Some contract ->
      let branches =
        native_core_skolem_macro_edges cert id
        |> List.filter_map
             (fun edge -> edge.native_skolem_macro_edge_branch_contract)
      in
      begin match contract.Vampire_kernel_syntax.skolem_macro_edge_count with
      | Some expected when branches <> [] && List.length branches <> expected ->
          error
            (Printf.sprintf
               "%s: typed Skolem proof object has %d branch contracts but top-level contract expects %d macro edges"
               id (List.length branches) expected)
      | _ -> ()
      end;
      let top_witness_symbols =
        contract.Vampire_kernel_syntax.skolem_introduced_witnesses
        |> List.map
             (fun witness ->
                witness.Vampire_kernel_syntax.skolem_witness_symbol)
      in
      List.iter
        (fun branch ->
           branch.Vampire_kernel_syntax.skolem_branch_introduced_witnesses
           |> List.iter
                (fun witness ->
                   let symbol =
                     witness.Vampire_kernel_syntax.skolem_witness_symbol
                   in
                   if not (List.mem symbol top_witness_symbols) then
                     error
                       (Printf.sprintf
                          "%s: typed Skolem branch contract %d introduces witness %s outside the top-level contract"
                          id
                          branch.Vampire_kernel_syntax.skolem_branch_index
                          symbol)))
        branches;
      Some
        {
          Vampire_kernel_syntax.skolem_proof_contract = contract;
          skolem_proof_branches = branches;
        }

let native_core_debug_skolem_proof_object id = function
  | Some proof_object when Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" ->
      let contract = proof_object.Vampire_kernel_syntax.skolem_proof_contract in
      let branches = proof_object.Vampire_kernel_syntax.skolem_proof_branches in
      let branch_indices =
        branches
        |> List.map
             (fun branch ->
                string_of_int
                  branch.Vampire_kernel_syntax.skolem_branch_index)
      in
      prerr_endline
        (Printf.sprintf
           "%s: native Skolem proof object source_children=%d result_children=%d witnesses=%d macro_edges=%s branches=%d[%s]"
           id
           (List.length contract.Vampire_kernel_syntax.skolem_source_children)
           (List.length contract.Vampire_kernel_syntax.skolem_result_children)
           (List.length contract.Vampire_kernel_syntax.skolem_introduced_witnesses)
           (match contract.Vampire_kernel_syntax.skolem_macro_edge_count with
            | Some count -> string_of_int count
            | None -> "?")
           (List.length branches)
           (String.concat "," branch_indices))
  | _ -> ()

let native_core_symbol_table cert =
  let symbols = Hashtbl.create 257 in
  let add name arity typ = Hashtbl.replace symbols name (arity, typ) in
  let add_simple name typ = add name 0 (native_sort_of_simple_sort typ) in
  add megalodon_eq_poly_hash 1 (Ar (TpVar 0, Ar (TpVar 0, Prop)));
  List.iter
    (fun (name, typ) -> add_simple name typ)
    [
      ("False", "prop"); ("True", "prop");
      ("f__true", "prop"); ("f__false", "prop");
      ("vampire_true", "prop"); ("vampire_false", "prop");
      ("vampire_or", "prop->prop->prop");
      ("vampire_and", "prop->prop->prop");
      ("vampire_eq_prop", "prop->prop->prop");
      ("vPI", "(set->prop)->prop");
      ("vLAM", "set->set->set");
      ("Eps_i", "(set->prop)->set");
      ("Eps_prop", "(prop->prop)->prop");
      ("Eps_set_prop", "((set->prop)->prop)->set->prop");
      ("Eps_set_set", "((set->set)->prop)->set->set");
      ("Eps_set_set_prop", "((set->set->prop)->prop)->set->set->prop");
    ];
  for i = 0 to 31 do
    add_simple ("db" ^ string_of_int i) "set"
  done;
  let parse_decl decl =
    let line = String.trim decl in
    if not (string_starts_with "Variable " line) then ()
    else
      let body =
        String.sub line 9 (String.length line - 9)
        |> String.trim
      in
      match String.index_opt body ':' with
      | None -> ()
      | Some colon ->
          let name = String.sub body 0 colon |> String.trim in
          let typ =
            String.sub body (colon + 1) (String.length body - colon - 1)
            |> String.trim
          in
          let typ =
            if String.length typ > 0 && typ.[String.length typ - 1] = '.' then
              String.sub typ 0 (String.length typ - 1)
            else typ
          in
          add_simple name typ
  in
  List.iter parse_decl cert.metadata.symbol_declarations;
  List.iter
    (fun (_, _, fields) ->
       List.iter
         (fun field ->
            match String.index_opt field '=' with
            | None -> ()
            | Some eq ->
                let key = String.sub field 0 eq in
                let suffix = "_declaration" in
                let suffix_len = String.length suffix in
                if String.length key >= suffix_len
                   && String.sub key (String.length key - suffix_len) suffix_len = suffix then
                  let value =
                    String.sub field (eq + 1) (String.length field - eq - 1)
                  in
                  parse_decl value)
         fields)
    cert.metadata.step_extras;
  List.iter
    (function
      | AvatarDefinition (_, split_var, _, _) when split_var > 0 ->
          add_simple ("split_" ^ string_of_int split_var) "prop"
      | AvatarSplit (_, _, clause) ->
          List.iter
            (function
              | Pos (TmH name) | Neg (TmH name)
                  when string_starts_with "split_" name ->
                  add_simple name "prop"
              | _ -> ())
            clause
      | AvatarRefutation (_, _, sat_clauses, _, _) ->
          sat_clauses
          |> List.concat
          |> List.iter
               (fun (var, _) ->
                  if var > 0 then
                    add_simple ("split_" ^ string_of_int var) "prop")
      | _ -> ())
    cert.steps;
  symbols

let rec native_core_arrow_parts = function
  | Ar (left, right) ->
      let args, result = native_core_arrow_parts right in
      (left :: args, result)
  | tp -> ([], tp)

let rec native_core_take_prefix n xs =
  if n <= 0 then []
  else
    match xs with
    | [] -> []
    | x :: rest -> x :: native_core_take_prefix (n - 1) rest

let rec native_core_flatten_value_application = function
  | Ap (TmH "vLAM", _) as tm -> (tm, [])
  | Ap (fn, arg) ->
      let head, args = native_core_flatten_value_application fn in
      (head, args @ [arg])
  | tm -> (tm, [])

let native_core_symbol_type symbol_table name =
  try
    let arity, tp = Hashtbl.find symbol_table name in
    if arity <> 0 then
      error
        ("native core proof-term checker cannot make a term definition for type-polymorphic symbol " ^ name);
    tp
  with Not_found ->
    error
      ("native core proof-term checker cannot find declared type for generated definition symbol " ^ name)

let native_core_assoc_opt key xs =
  try Some (List.assoc key xs) with Not_found -> None

let rec native_core_nth_opt xs index =
  match xs, index with
  | x :: _, 0 -> Some x
  | _ :: rest, n when n > 0 -> native_core_nth_opt rest (n - 1)
  | _ -> None

let native_core_tm_type symbol_table env tm =
  let rec infer db_tps = function
    | TmH name ->
        begin match native_core_ident_opt name with
        | Some ident ->
            begin match native_core_assoc_opt ident env with
            | Some tp -> Some tp
            | None ->
                begin match Hashtbl.find_opt symbol_table ident with
                | Some (0, tp) -> Some tp
                | _ -> None
                end
            end
        | None -> None
        end
    | DB index -> native_core_nth_opt db_tps index
    | Prim _ -> None
    | TpAp (TmH h, tp) when h = megalodon_eq_poly_hash ->
        Some (Ar (tp, Ar (tp, Prop)))
    | TpAp (tm, _) -> infer db_tps tm
    | Ap (fn, _arg) ->
        begin match infer db_tps fn with
        | Some (Ar (_, result_tp)) -> Some result_tp
        | _ -> None
        end
    | Lam (tp, body) ->
        Option.map (fun body_tp -> Ar (tp, body_tp)) (infer (tp :: db_tps) body)
    | Imp _ | All _ -> Some Prop
  in
  infer [] tm

let native_core_common_tm_type symbol_table env left right =
  match native_core_tm_type symbol_table env left,
        native_core_tm_type symbol_table env right with
  | Some left_tp, Some right_tp when left_tp = right_tp -> Some left_tp
  | Some tp, None | None, Some tp -> Some tp
  | None, None -> None
  | Some _, Some _ -> None

let native_core_raw_bool_constant = function
  | TmH ("f__true" | "f__false" | "vampire_true" | "vampire_false") -> true
  | _ -> false

let native_core_type_raw_equalities symbol_table env tm =
  let rec normalize db_tps tm =
    match tm with
    | Ap (Ap (TpAp (TmH h, tp), left), right)
        when h = megalodon_eq_poly_hash ->
        Ap
          (Ap (TpAp (TmH h, tp), normalize db_tps left),
           normalize db_tps right)
    | Ap (Ap (TmH h, left), right) when h = "=" || h = "eq" ->
        let left = normalize db_tps left in
        let right = normalize db_tps right in
        let tp =
          if native_core_raw_bool_constant left
             || native_core_raw_bool_constant right then
            Some Prop
          else
            native_core_common_tm_type symbol_table env left right
        in
        begin match tp with
        | Some tp ->
            Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), left), right)
        | None -> Ap (Ap (TmH h, left), right)
        end
    | TpAp (tm, tp) -> TpAp (normalize db_tps tm, tp)
    | Ap (left, right) -> Ap (normalize db_tps left, normalize db_tps right)
    | Lam (tp, body) -> Lam (tp, normalize (tp :: db_tps) body)
    | Imp (left, right) -> Imp (normalize db_tps left, normalize db_tps right)
    | All (tp, body) -> All (tp, normalize (tp :: db_tps) body)
    | DB _ | TmH _ | Prim _ -> tm
  in
  normalize [] tm

let native_core_type_raw_equalities_literal symbol_table env = function
  | Pos atom -> Pos (native_core_type_raw_equalities symbol_table env atom)
  | Neg atom -> Neg (native_core_type_raw_equalities symbol_table env atom)

let native_core_type_raw_equalities_clause symbol_table env clause =
  List.map (native_core_type_raw_equalities_literal symbol_table env) clause

let native_core_type_raw_equalities_subst symbol_table env subst =
  List.map
    (fun (name, tm) -> (name, native_core_type_raw_equalities symbol_table env tm))
    subst

let native_core_step_type_env cert id variables =
  variables @ native_core_step_variables cert id

let native_core_type_raw_equalities_step cert variables symbol_table step =
  let env id = native_core_step_type_env cert id variables in
  let tm id = native_core_type_raw_equalities symbol_table (env id) in
  let literal id = native_core_type_raw_equalities_literal symbol_table (env id) in
  let clause id = native_core_type_raw_equalities_clause symbol_table (env id) in
  let subst id = native_core_type_raw_equalities_subst symbol_table (env id) in
  let ennf_pair id pair =
    {
      pair with
      ennf_pair_source = tm id pair.ennf_pair_source;
      ennf_pair_target = tm id pair.ennf_pair_target;
    }
  in
  match step with
  | Input (id, source, result) -> Input (id, source, clause id result)
  | FormulaInput (id, source, result) -> FormulaInput (id, source, literal id result)
  | FormulaTermInput (id, source, result) -> FormulaTermInput (id, source, tm id result)
  | FormulaTermCopy (id, parent_id, result) -> FormulaTermCopy (id, parent_id, tm id result)
  | RectifyFormula (id, parent_id, renamings, result) ->
      RectifyFormula (id, parent_id, renamings, tm id result)
  | FoolAtomLift (id, source, target, path) ->
      FoolAtomLift (id, tm id source, tm id target, path)
  | FoolFormula (id, parent_id, result) -> FoolFormula (id, parent_id, tm id result)
  | EnnfFormula (id, parent_id, source, pairs, result) ->
      EnnfFormula
        (id, parent_id, Option.map (tm id) source,
         List.map (ennf_pair id) pairs, tm id result)
  | SkolemFormula (id, parent_id, source, introductions, substitution, result) ->
      SkolemFormula
        (id, parent_id, Option.map (tm id) source, introductions,
         subst id substitution, tm id result)
  | SkolemFormulaComputed (id, parent_id, substitution) ->
      SkolemFormulaComputed (id, parent_id, subst id substitution)
  | CnfFormulaClause (id, parent_id, index, count, result) ->
      CnfFormulaClause (id, parent_id, index, count, clause id result)
  | FormulaCopy (id, parent_id, result) -> FormulaCopy (id, parent_id, literal id result)
  | FoolBool (id, parent_id, result) -> FoolBool (id, parent_id, literal id result)
  | CnfLiteral (id, parent_id, result) -> CnfLiteral (id, parent_id, clause id result)
  | PredicateDefinition (id, symbol, result) -> PredicateDefinition (id, symbol, tm id result)
  | PredicateDefinitionFold (id, source, definition, result) ->
      PredicateDefinitionFold (id, source, definition, tm id result)
  | PredicateDefinitionFoldChain (id, source, definitions, result) ->
      PredicateDefinitionFoldChain (id, source, definitions, tm id result)
  | DefinitionInput (id, result) -> DefinitionInput (id, clause id result)
  | DefinitionRewriteChain (id, parent_id, rewrites, result) ->
      DefinitionRewriteChain (id, parent_id, rewrites, clause id result)
  | AvatarComponent (id, result) -> AvatarComponent (id, clause id result)
  | AvatarDefinition (id, split_var, split_positive, result) ->
      AvatarDefinition (id, split_var, split_positive, clause id result)
  | SplitDependency (id, owner_id, dependencies, result) ->
      SplitDependency (id, owner_id, dependencies, clause id result)
  | AvatarSplit (id, parent_ids, result) -> AvatarSplit (id, parent_ids, clause id result)
  | AvatarContradiction (id, parent_ids, result) ->
      AvatarContradiction (id, parent_ids, clause id result)
  | AvatarRefutation (id, parent_ids, sat_clauses, sat_proof, result) ->
      AvatarRefutation (id, parent_ids, sat_clauses, sat_proof, clause id result)
  | FoolExhaustiveness (id, result) -> FoolExhaustiveness (id, clause id result)
  | FoolDistinctness (id, result) -> FoolDistinctness (id, clause id result)
  | InequalityNameIntro (id, result) -> InequalityNameIntro (id, clause id result)
  | InequalitySplit (id, parent_id, splits, result) ->
      InequalitySplit (id, parent_id, splits, clause id result)
  | Substitute (id, parent_id, substitution, result) ->
      Substitute (id, parent_id, subst id substitution, clause id result)
  | Condensation (id, parent_id, substitution, result) ->
      Condensation (id, parent_id, subst id substitution, clause id result)
  | UnitResultingResolution (id, parent_id, trace, result) ->
      UnitResultingResolution (id, parent_id, trace, clause id result)
  | Resolve (id, left_id, right_id, left_index, right_index, result) ->
      Resolve (id, left_id, right_id, left_index, right_index, clause id result)
  | SubsumptionResolution (id, main_parent_id, side_parent_id, selected, side_pivot, side_subst, result) ->
      SubsumptionResolution
        (id, main_parent_id, side_parent_id, literal id selected,
         literal id side_pivot, subst id side_subst, clause id result)
  | Factor (id, parent_id, left_index, right_index, result) ->
      Factor (id, parent_id, left_index, right_index, clause id result)
  | EqualityResolution (id, parent_id, literal_index, result) ->
      EqualityResolution (id, parent_id, literal_index, clause id result)
  | EqualityResolutionConstraints (id, parent_id, literal_index, selected, constraints, result) ->
      EqualityResolutionConstraints
        (id, parent_id, literal_index, literal id selected,
         clause id constraints, clause id result)
  | EqualityFactoring (id, parent_id, selected_index, other_index, explicit_sides, substitution, result) ->
      EqualityFactoring
        (id, parent_id, selected_index, other_index,
         Option.map (fun (selected_lhs, other_rhs) -> (tm id selected_lhs, tm id other_rhs)) explicit_sides,
         subst id substitution,
         clause id result)
  | EqualityFactoringConstraints (id, parent_id, selected_index, other_index, explicit_sides, substitution, constraints, result) ->
      EqualityFactoringConstraints
        (id, parent_id, selected_index, other_index,
         Option.map (fun (selected_lhs, other_rhs) -> (tm id selected_lhs, tm id other_rhs)) explicit_sides,
         subst id substitution,
         clause id constraints, clause id result)
  | TruthConflict (id, parent_id, literal_index, result) ->
      TruthConflict (id, parent_id, literal_index, clause id result)
  | EqualitySymmetry (id, parent_id, literal_index, result) ->
      EqualitySymmetry (id, parent_id, literal_index, clause id result)
  | BoolSimplify (id, parent_id, literal_index, positions, source, target, result) ->
      BoolSimplify
        (id, parent_id, literal_index, positions, tm id source, tm id target,
         clause id result)
  | Paramodulate (id, equality_parent_id, target_parent_id, equality_index, target_index, position, from_tm, to_tm, result) ->
      Paramodulate
        (id, equality_parent_id, target_parent_id, equality_index, target_index,
         position, tm id from_tm, tm id to_tm, clause id result)
  | Superposition (id, left_id, right_id, left_index, right_index, left_subst, right_subst, position, from_tm, to_tm, result) ->
      Superposition
        (id, left_id, right_id, left_index, right_index, subst id left_subst,
         subst id right_subst, position, tm id from_tm, tm id to_tm,
         clause id result)
  | Contradiction _ as step -> step

let native_core_abstract_named_arguments args body =
  let count = List.length args in
  let rec index_of name index = function
    | [] -> None
    | arg :: rest ->
        if arg = name then Some (count - index - 1)
        else index_of name (index + 1) rest
  in
  let rec abstract depth = function
    | DB i -> if i >= depth then DB (i + count) else DB i
    | TmH h ->
        begin match index_of h 0 args with
        | Some index -> DB (depth + index)
        | None -> TmH h
        end
    | Prim _ as tm -> tm
    | TpAp (tm, tp) -> TpAp (abstract depth tm, tp)
    | Ap (left, right) -> Ap (abstract depth left, abstract depth right)
    | Lam (tp, body) -> Lam (tp, abstract (depth + 1) body)
    | Imp (left, right) -> Imp (abstract depth left, abstract depth right)
    | All (tp, body) -> All (tp, abstract (depth + 1) body)
  in
  abstract 0 body

let native_core_definition_body symbol_table introduced application body =
  let symbol_tp = native_core_symbol_type symbol_table introduced in
  let arg_tps, _ = native_core_arrow_parts symbol_tp in
  let head, args = native_core_flatten_value_application application in
  match head with
  | TmH head when native_core_ident head = introduced ->
      let arg_names =
        args
        |> List.map
             (function
               | TmH name -> native_core_ident name
               | _ ->
                   error
                     ("native core proof-term checker only supports generated definition arguments that are variables for " ^ introduced))
      in
      if List.length (List.sort_uniq compare arg_names) <> List.length arg_names then
        error
          ("native core proof-term checker found repeated generated definition argument for " ^ introduced);
      if List.length arg_names > List.length arg_tps then
        error
          ("native core proof-term checker found too many generated definition arguments for " ^ introduced);
      let used_arg_tps = native_core_take_prefix (List.length arg_names) arg_tps in
      let abstracted = native_core_abstract_named_arguments arg_names body in
      List.fold_right (fun tp tm -> Lam (tp, tm)) used_arg_tps abstracted
  | _ ->
      error
        ("native core proof-term checker expected generated definition headed by " ^ introduced)

let native_core_inequality_split_definition_body symbol_table id result =
  let false_tm = All (Prop, DB 0) in
  let expand_eq_atom tp left right =
    All
      (Ar (tp, Ar (tp, Prop)),
       Imp
         (Ap (Ap (DB 0, tmshift 0 1 left), tmshift 0 1 right),
          Ap (Ap (DB 0, tmshift 0 1 right), tmshift 0 1 left)))
  in
  match result with
  | [literal] ->
      begin match bool_name_literal false literal with
      | Some named ->
          let raw_name, args = split_name_application id named in
          let introduced = native_core_ident raw_name in
          let symbol_tp = native_core_symbol_type symbol_table introduced in
          let arg_tps, result_tp = native_core_arrow_parts symbol_tp in
          if result_tp <> Prop then
            error (id ^ ": inequality split name does not return prop");
          if args = [] then
            error (id ^ ": inequality split name has no arguments");
          if List.length args > List.length arg_tps then
            error (id ^ ": inequality split name has too many arguments for its type");
          let used_arg_tps = native_core_take_prefix (List.length args) arg_tps in
          let binder_names =
            List.mapi
              (fun index _ -> "__ineq_split_arg_" ^ string_of_int index)
              args
          in
          let substitution =
            List.combine args binder_names
            |> List.filter_map
                 (function
                   | TmH original, binder ->
                       Some (native_core_ident original, TmH binder)
                   | _ -> None)
          in
          let split_arg =
            match List.rev args with
            | arg :: _ -> subst_tm substitution arg
            | [] -> assert false
          in
          let last_binder, last_tp =
            match List.rev binder_names, List.rev used_arg_tps with
            | binder :: _, tp :: _ -> TmH binder, tp
            | _ -> assert false
          in
          let equality_prop =
            expand_eq_atom last_tp last_binder split_arg
          in
          let body =
            Imp (equality_prop, false_tm)
            |> native_core_abstract_named_arguments binder_names
          in
          List.fold_right (fun tp tm -> Lam (tp, tm)) used_arg_tps body
      | None -> raise Not_found
      end
  | _ -> raise Not_found

let native_core_definition_delta_table cert symbol_table =
  let definitions = Hashtbl.create 31 in
  let add_definition id clause =
    match
      native_core_metadata_step_extra_field cert id "function_definition" "introduced_symbol",
      clause
    with
    | Some introduced, [Pos atom] ->
        let introduced = native_core_ident introduced in
        begin match equality_sides atom with
        | Some (left, right) ->
            let body =
              let right_head, _ = native_core_flatten_value_application right in
              match right_head with
              | TmH head when native_core_ident head = introduced ->
                  native_core_definition_body symbol_table introduced right left
              | _ ->
                  let left_head, _ = native_core_flatten_value_application left in
                  begin match left_head with
                  | TmH head when native_core_ident head = introduced ->
                      native_core_definition_body symbol_table introduced left right
                  | _ ->
                      error
                        (id ^ ": function definition equality does not mention its introduced symbol")
                  end
            in
            Hashtbl.replace definitions introduced (0, tm_beta_eta_norm body)
        | None -> ()
        end
    | _ -> ()
  in
  List.iter
    (function
      | DefinitionInput (id, clause) -> add_definition id clause
      | InequalityNameIntro (id, clause) ->
          begin try
            let body =
              native_core_inequality_split_definition_body symbol_table id clause
            in
            begin match clause with
            | literal :: _ ->
                begin match bool_name_literal false literal with
                | Some named ->
                    let raw_name, _ = split_name_application id named in
                    let introduced = native_core_ident raw_name in
                    begin match Hashtbl.find_opt definitions introduced with
                    | Some (_, existing) when tm_beta_eta_norm existing <> tm_beta_eta_norm body ->
                        error (id ^ ": conflicting inequality split-name definition for " ^ introduced)
                    | _ ->
                        Hashtbl.replace definitions introduced (0, tm_beta_eta_norm body)
                    end
                | None -> ()
                end
            | [] -> ()
            end
          with Not_found -> ()
          end
      | _ -> ())
    cert.steps;
  definitions

let native_core_avatar_definition_clause cert id split_var split_positive clause =
  let split_name = "split_" ^ string_of_int split_var in
  let is_split_literal = function
    | Neg (TmH name) when split_positive && name = split_name -> true
    | Pos (TmH name) when (not split_positive) && name = split_name -> true
    | _ -> false
  in
  let split_literals, component_literals =
    List.partition is_split_literal clause
  in
  match split_literals, component_literals with
  | [_], _ :: _ -> Some (split_name, component_literals)
  | _ -> None

let native_core_true =
  All (Prop, Imp (DB 0, DB 0))

let native_core_false =
  All (Prop, DB 0)

let rec native_core_default_witness = function
  | Set -> Some (TmH "Empty")
  | Prop -> Some native_core_true
  | Ar (arg_tp, result_tp) ->
      Option.map
        (fun body -> Lam (arg_tp, tmshift 0 1 body))
        (native_core_default_witness result_tp)
  | TpVar _ -> None

let native_core_is_vampire_true_name = function
  | "f__true" | "vampire_true" -> true
  | _ -> false

let native_core_is_vampire_false_name = function
  | "f__false" | "vampire_false" -> true
  | _ -> false

let rec native_core_normalize_bool_constants = function
  | TmH h when native_core_is_vampire_true_name h -> native_core_true
  | TmH h when native_core_is_vampire_false_name h -> native_core_false
  | TpAp (m, a) -> TpAp (native_core_normalize_bool_constants m, a)
  | Ap (m, n) ->
      Ap (native_core_normalize_bool_constants m,
          native_core_normalize_bool_constants n)
  | Lam (a, body) -> Lam (a, native_core_normalize_bool_constants body)
  | Imp (left, right) ->
      Imp (native_core_normalize_bool_constants left,
           native_core_normalize_bool_constants right)
  | All (a, body) -> All (a, native_core_normalize_bool_constants body)
  | DB _ | TmH _ | Prim _ as tm -> tm

let native_core_close_tm ?(depth=0) variables tm =
  let variable_count = List.length variables in
  let rec variable_index index = function
    | [] -> None
    | (name, _) :: rest ->
        begin match variable_index index rest with
        | Some i -> Some (i + 1)
        | None -> if name = index then Some 0 else None
        end
  in
  let rec close depth = function
    | TmH name ->
        let closeable_names =
          let stripped =
            if String.length name > 1 && name.[0] = '#' then
              [String.sub name 1 (String.length name - 1)]
            else []
          in
          name :: stripped
        in
        let find_variable_name =
          closeable_names
          |> List.find_map
               (fun raw ->
                  Option.bind
                    (native_core_ident_opt raw)
                    (fun ident ->
                       Option.map
                         (fun index -> index)
                         (variable_index ident variables)))
        in
        begin match find_variable_name with
        | Some outer_index -> DB (depth + variable_count - outer_index - 1)
        | None -> TmH name
        end
    | TpAp (m, a) -> TpAp (close depth m, a)
    | Ap (m, n) -> Ap (close depth m, close depth n)
    | Lam (a, body) -> Lam (a, close (depth + 1) body)
    | Imp (m, n) -> Imp (close depth m, close depth n)
    | All (a, body) -> All (a, close (depth + 1) body)
    | tm -> tm
  in
  close depth (native_core_normalize_bool_constants tm)

let native_core_tm_scoped_under context_depth tm =
  let rec scoped local_depth = function
    | DB index -> index < context_depth + local_depth
    | TpAp (body, _) -> scoped local_depth body
    | Ap (left, right)
    | Imp (left, right) ->
        scoped local_depth left && scoped local_depth right
    | Lam (_, body)
    | All (_, body) ->
        scoped (local_depth + 1) body
    | TmH _ | Prim _ -> true
  in
  scoped 0 tm

let native_core_close_pf variables proof =
  let rec close depth = function
    | Hyp i -> Hyp i
    | Known h -> Known h
    | PTpAp (proof, tp) -> PTpAp (close depth proof, tp)
    | PTmAp (proof, tm) ->
        PTmAp (close depth proof, native_core_close_tm ~depth variables tm)
    | PPfAp (left, right) ->
        PPfAp (close depth left, close depth right)
    | PLam (prop, proof) ->
        PLam (native_core_close_tm ~depth variables prop, close depth proof)
    | TLam (tp, proof) -> TLam (tp, close (depth + 1) proof)
  in
  close 0 proof

let native_core_close_delta_table variables delta =
  let closed = Hashtbl.create (Hashtbl.length delta) in
  Hashtbl.iter
    (fun h (arity, tm) ->
       Hashtbl.replace closed h (arity, native_core_close_tm variables tm))
    delta;
  closed

let native_core_equality_sides = function
  | Ap (Ap (TpAp (TmH h, tp), left), right)
      when h = megalodon_eq_poly_hash ->
      Some (tp,
            native_core_normalize_bool_constants left,
            native_core_normalize_bool_constants right)
  | Ap (Ap (TmH h, left), right) when h = "=" || h = "eq" ->
      let left = native_core_normalize_bool_constants left in
      let right = native_core_normalize_bool_constants right in
      if left = native_core_true || left = native_core_false
         || right = native_core_true || right = native_core_false then
        Some (Prop, left, right)
      else
        None
  | _ -> None

let native_core_or left right =
  All
    (Prop,
     Imp
       (Imp (tmshift 0 1 left, DB 0),
        Imp (Imp (tmshift 0 1 right, DB 0), DB 0)))

let native_core_and left right =
  All
    (Prop,
     Imp
       (Imp (tmshift 0 1 left, Imp (tmshift 0 1 right, DB 0)),
        DB 0))

let native_core_exists tp body =
  All
    (Prop,
     Imp
       (All (tp, Imp (tmshift 1 1 body, DB 1)),
        DB 0))

let native_core_universal_binder_types tm =
  let rec collect acc = function
    | All (tp, body) -> collect (acc @ [tp]) body
    | body -> (acc, body)
  in
  collect [] tm

let native_core_expand_eq_atom tm =
  match native_core_equality_sides tm with
  | Some (tp, left, right) ->
      All
        (Ar (tp, Ar (tp, Prop)),
         Imp
           (Ap (Ap (DB 0, tmshift 0 1 left), tmshift 0 1 right),
            Ap (Ap (DB 0, tmshift 0 1 right), tmshift 0 1 left)))
  | None -> tm

let rec native_core_formula_prop = function
  | Imp (left, right) ->
      Imp (native_core_formula_prop left, native_core_formula_prop right)
  | All (tp, body) -> All (tp, native_core_formula_prop body)
  | Ap (Ap (TmH "vampire_or", left), right) ->
      native_core_or (native_core_formula_prop left) (native_core_formula_prop right)
  | Ap (Ap (TmH "vampire_and", left), right) ->
      native_core_and (native_core_formula_prop left) (native_core_formula_prop right)
  | Ap (TmH "vampire_exists_prop", Lam (tp, body)) ->
      native_core_exists tp (native_core_formula_prop body)
  | tm -> native_core_expand_eq_atom tm

let native_core_predicate_definition_body symbol_table id symbol formula =
  let binder_tps, _ = native_core_universal_binder_types formula in
  let defined, atom, body = predicate_definition_parts id formula in
  if native_core_ident symbol <> native_core_ident defined then
    error
      (id ^ ": native core predicate_definition symbol "
       ^ symbol ^ " does not match definiendum " ^ defined);
  let definiendum = predicate_definition_definiendum_term atom in
  let head, args = native_core_flatten_value_application definiendum in
  begin match head with
  | TmH head when native_core_ident head = native_core_ident symbol -> ()
  | _ ->
      error
        (id ^ ": native core predicate_definition definiendum is not headed by " ^ symbol)
  end;
  let expected_args =
    let n = List.length binder_tps in
    List.init n (fun index -> DB (n - index - 1))
  in
  if args <> expected_args then
    error
      (id ^ ": native core predicate_definition arguments are not the leading universal binders");
  let symbol_tp = native_core_symbol_type symbol_table (native_core_ident symbol) in
  let arg_tps, result_tp = native_core_arrow_parts symbol_tp in
  if result_tp <> Prop then
    error (id ^ ": native core predicate_definition definiendum does not return prop");
  if List.length arg_tps <> List.length binder_tps then
    error (id ^ ": native core predicate_definition arity does not match leading binders");
  if arg_tps <> binder_tps then
    error (id ^ ": native core predicate_definition binder types do not match symbol type");
  body
  |> native_core_formula_prop
  |> List.fold_right (fun tp tm -> Lam (tp, tm)) binder_tps
  |> tm_beta_eta_norm

let native_core_literal_prop = function
  | Pos tm -> native_core_expand_eq_atom tm
  | Neg tm -> Imp (native_core_expand_eq_atom tm, native_core_false)

let native_rectify_formula_match left right =
  let candidates tm =
    let bool_normalized = normalize_bool_equality_orientation tm in
    let equality_normalized = normalize_equality_orientation bool_normalized in
    let native_prop =
      native_core_formula_prop tm
      |> native_core_normalize_bool_constants
    in
    let native_bool_prop =
      native_core_formula_prop bool_normalized
      |> native_core_normalize_bool_constants
    in
    let native_equality_prop =
      native_core_formula_prop equality_normalized
      |> native_core_normalize_bool_constants
    in
    [tm; bool_normalized; equality_normalized;
     native_prop; native_bool_prop; native_equality_prop]
  in
  List.exists
    (fun left_candidate ->
       List.exists
         (fun right_candidate ->
            left_candidate = right_candidate
            || same_mod_vampire_var_renaming left_candidate right_candidate
            || same_mod_scoped_vampire_var_renaming left_candidate right_candidate
            || same_mod_scoped_vampire_var_renaming_and_equality left_candidate right_candidate)
         (candidates right))
    (candidates left)

let check_native_rectify_formula id parent_id renamings parent_formula result =
  match renamings with
  | _ :: _ ->
      List.iteri (validate_rectify_renaming id) renamings;
      if not (tm_matches_rectify_renamings renamings parent_formula result
              || native_rectify_formula_match parent_formula result) then
        error (id ^ ": rectify_formula result is not explained by explicit Vampire renamings")
  | [] ->
      if not (native_rectify_formula_match parent_formula result) then
        error (id ^ ": rectify_formula result is not a bijective Vampire-variable renaming of parent")

let rec native_core_clause_prop id = function
  | [] -> native_core_false
  | [literal] -> native_core_literal_prop literal
  | literal :: rest ->
      native_core_or (native_core_literal_prop literal) (native_core_clause_prop id rest)

let native_core_step_clause_prop cert variables id clause =
  let step_variables = native_core_step_variables cert id in
  let prop =
    native_core_close_tm
      (variables @ step_variables)
      (native_core_clause_prop id clause)
  in
  List.fold_right (fun (_, tp) prop -> All (tp, prop)) step_variables prop

let native_core_avatar_definition_from_component_clause split_var clause =
  let split_name = "split_" ^ string_of_int split_var in
  let complement_literal = function
    | Pos atom -> Neg atom
    | Neg atom -> Pos atom
  in
  let split_literals, component_literals =
    List.partition
      (function
        | Pos (TmH name) | Neg (TmH name) -> name = split_name
        | _ -> false)
      clause
  in
  match split_literals, component_literals with
  | [Pos (TmH name)], [component_literal] when name = split_name ->
      Some (split_name, [complement_literal component_literal])
  | [Neg (TmH name)], [component_literal] when name = split_name ->
      Some (split_name, [component_literal])
  | _ ->
      None

let native_core_avatar_metadata_definitions cert =
  cert.steps
  |> List.concat_map
       (function
         | SplitDependency (_, owner_id, dependencies, result) ->
             dependencies
             |> List.filter_map
                  (fun dependency ->
                     if same_clause_multiset result dependency.dependency_component then
                       native_core_avatar_definition_from_component_clause
                         dependency.dependency_split_var
                         dependency.dependency_component
                       |> Option.map
                            (fun (split_name, component_literals) ->
                               (owner_id, split_name, component_literals))
                     else
                       None)
         | _ -> [])
  |> List.sort_uniq compare

let native_core_avatar_delta_table cert =
  let definitions = Hashtbl.create 17 in
  let add_definition id split_name component_literals =
    let component_prop =
      component_literals
      |> native_core_step_clause_prop cert [] id
      |> native_core_normalize_bool_constants
      |> tm_beta_eta_norm
    in
    match Hashtbl.find_opt definitions split_name with
    | Some (_, existing) when existing <> component_prop ->
        error
          (id ^ ": conflicting AVATAR split definition for " ^ split_name)
    | _ ->
        Hashtbl.replace definitions split_name (0, component_prop)
  in
  List.iter
    (function
      | AvatarDefinition (id, split_var, true, clause) ->
          begin match
            native_core_avatar_definition_clause cert id split_var true clause
          with
          | Some (split_name, component_literals) ->
              add_definition id split_name component_literals
          | None -> ()
          end
      | _ -> ())
    cert.steps;
  native_core_avatar_metadata_definitions cert
  |> List.iter
       (fun (id, split_name, component_literals) ->
          add_definition id split_name component_literals);
  definitions

let native_core_same_atom left right =
  left = right

let native_core_complement left right =
  match left, right with
  | Pos left_atom, Neg right_atom
  | Neg right_atom, Pos left_atom
      when native_core_same_atom left_atom right_atom -> true
  | _ -> false

let native_core_complement_literal = function
  | Pos atom -> Neg atom
  | Neg atom -> Pos atom

let native_core_or_intro_left left_prop right_prop proof =
  TLam
    (Prop,
     PLam
       (Imp (tmshift 0 1 left_prop, DB 0),
        PLam
          (Imp (tmshift 0 1 right_prop, DB 0),
           PPfAp (Hyp 1, pfshift 0 2 (pftmshift 0 1 proof)))))

let native_core_or_intro_right left_prop right_prop proof =
  TLam
    (Prop,
     PLam
       (Imp (tmshift 0 1 left_prop, DB 0),
        PLam
          (Imp (tmshift 0 1 right_prop, DB 0),
           PPfAp (Hyp 0, pfshift 0 2 (pftmshift 0 1 proof)))))

let native_core_and_intro left_prop right_prop left_proof right_proof =
  TLam
    (Prop,
     PLam
       (Imp (tmshift 0 1 left_prop, Imp (tmshift 0 1 right_prop, DB 0)),
        PPfAp
          (PPfAp (Hyp 0, pfshift 0 1 (pftmshift 0 1 left_proof)),
           pfshift 0 1 (pftmshift 0 1 right_proof))))

let native_core_and_elim_left left_prop right_prop proof =
  PPfAp
    (PTmAp (proof, left_prop),
     PLam (left_prop, PLam (right_prop, Hyp 1)))

let native_core_and_elim_right left_prop right_prop proof =
  PPfAp
    (PTmAp (proof, right_prop),
     PLam (left_prop, PLam (right_prop, Hyp 0)))

let rec native_core_prove_literal_to_clause id target_clause literal proof =
  match target_clause with
  | [target_literal] when target_literal = literal -> proof
  | left :: rest ->
      let left_prop = native_core_literal_prop left in
      let right_prop = native_core_clause_prop id rest in
      if literal = left then
        native_core_or_intro_left left_prop right_prop proof
      else
        let rest_proof =
          native_core_prove_literal_to_clause id rest literal proof
        in
        native_core_or_intro_right left_prop right_prop rest_proof
  | [] ->
      error
        (id ^ ": native core proof-term checker cannot inject literal into result clause")

let rec native_core_prove_clause_to_clause id source_clause target_clause proof =
  match source_clause with
  | [] ->
      PTmAp (proof, native_core_clause_prop id target_clause)
  | [literal] ->
      native_core_prove_literal_to_clause id target_clause literal proof
  | literal :: rest ->
      let target_prop = native_core_clause_prop id target_clause in
      let literal_prop = native_core_literal_prop literal in
      let rest_prop = native_core_clause_prop id rest in
      let left_branch =
        PLam
          (literal_prop,
           native_core_prove_literal_to_clause id target_clause literal (Hyp 0))
      in
      let right_branch =
        PLam
          (rest_prop,
           native_core_prove_clause_to_clause id rest target_clause (Hyp 0))
      in
      PPfAp (PPfAp (PTmAp (proof, target_prop), left_branch), right_branch)

let native_core_false_from_complement shifted_unit_proof pivot_literal branch_literal =
  match branch_literal, pivot_literal with
  | Pos branch_atom, Neg pivot_atom when native_core_same_atom branch_atom pivot_atom ->
      PPfAp (shifted_unit_proof, Hyp 0)
  | Neg branch_atom, Pos pivot_atom when native_core_same_atom branch_atom pivot_atom ->
      PPfAp (Hyp 0, shifted_unit_proof)
  | _ -> error "native core proof-term checker received non-complementary branch"

let native_core_false_from_complement_proofs left left_proof right right_proof =
  match left, right with
  | Pos left_atom, Neg right_atom when native_core_same_atom left_atom right_atom ->
      PPfAp (right_proof, left_proof)
  | Neg left_atom, Pos right_atom when native_core_same_atom left_atom right_atom ->
      PPfAp (left_proof, right_proof)
  | _ -> error "native core proof-term checker expected complementary pivots"

let native_core_split_literal_name = function
  | Pos (TmH name) | Neg (TmH name) when string_starts_with "split_" name ->
      Some name
  | _ -> None

let native_core_is_split_clause clause =
  clause <> [] && List.for_all (fun lit -> native_core_split_literal_name lit <> None) clause

let native_core_prove_replace_literal_in_clause
    id source_clause source_proof source_literal target_literal target_clause replacement =
  let rec find_replace_index index prefix = function
    | [] -> None
    | literal :: rest ->
        let candidate =
          List.rev_append prefix (target_literal :: rest)
        in
        if literal = source_literal && same_clause_multiset candidate target_clause then
          Some index
        else
          find_replace_index (index + 1) (literal :: prefix) rest
  in
  let replace_index =
    match find_replace_index 0 [] source_clause with
    | Some index -> index
    | None ->
        error
          (id ^ ": native preprocess proof-term avatar_split cannot replace component literal by split literal")
  in
  let target_prop = native_core_clause_prop id target_clause in
  let rec consume index clause proof =
    match clause with
    | [] ->
        error
          (id ^ ": native preprocess proof-term avatar_split replacement index is out of bounds")
    | [literal] when index = 0 && literal = source_literal ->
        let target_literal_proof = PPfAp (replacement, proof) in
        native_core_prove_literal_to_clause
          id target_clause target_literal target_literal_proof
    | [literal] when index = 0 ->
        error
          (id ^ ": native preprocess proof-term avatar_split selected replacement literal mismatch")
    | [literal] ->
        native_core_prove_literal_to_clause id target_clause literal proof
    | literal :: rest ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             if index = 0 then begin
               if literal <> source_literal then
                 error
                   (id ^ ": native preprocess proof-term avatar_split selected replacement literal mismatch");
               let target_literal_proof = PPfAp (replacement, Hyp 0) in
               native_core_prove_literal_to_clause
                 id target_clause target_literal target_literal_proof
             end else
               native_core_prove_literal_to_clause
                 id target_clause literal (Hyp 0))
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume (index - 1) rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume replace_index source_clause source_proof

let native_core_branch_from_complement target_prop unit_proof pivot_literal branch_literal =
  let shifted_unit_proof = pfshift 0 1 unit_proof in
  PTmAp
    (native_core_false_from_complement shifted_unit_proof pivot_literal branch_literal,
     target_prop)

let native_core_branch_from_complement_proofs target_prop unit_literal unit_proof branch_literal branch_proof =
  PTmAp
    (native_core_false_from_complement_proofs branch_literal branch_proof unit_literal unit_proof,
     target_prop)

let native_core_resolve_binary_unit id binary_clause binary_proof binary_index unit_clause unit_proof unit_index result =
  match binary_clause, unit_clause, result, unit_index with
  | [left_literal; right_literal], [unit_literal], [result_literal], 0 ->
      let target_prop = native_core_clause_prop id result in
      let left_prop = native_core_literal_prop left_literal in
      let right_prop = native_core_literal_prop right_literal in
      if binary_index = 0
         && native_core_complement left_literal unit_literal
         && result_literal = right_literal then
        let left_branch =
          PLam
            (left_prop,
             native_core_branch_from_complement target_prop unit_proof unit_literal left_literal)
        in
        let right_branch = PLam (right_prop, Hyp 0) in
        PPfAp (PPfAp (PTmAp (binary_proof, target_prop), left_branch), right_branch)
      else if binary_index = 1
              && native_core_complement right_literal unit_literal
              && result_literal = left_literal then
        let left_branch = PLam (left_prop, Hyp 0) in
        let right_branch =
          PLam
            (right_prop,
             native_core_branch_from_complement target_prop unit_proof unit_literal right_literal)
        in
        PPfAp (PPfAp (PTmAp (binary_proof, target_prop), left_branch), right_branch)
      else
        error
          (id ^ ": native core proof-term checker supports binary/unit resolution only when the result is the remaining literal")
  | _ ->
      error (id ^ ": native core proof-term checker expected binary/unit resolution")

let native_core_resolve_clause_unit id clause clause_proof clause_index unit_clause unit_proof unit_index result =
  match unit_clause, unit_index with
  | [unit_literal], 0 ->
      let selected = nth clause_index clause (id ^ " native clause/unit resolution pivot") in
      if not (native_core_complement selected unit_literal) then
        error (id ^ ": native core proof-term checker expected complementary clause/unit pivots");
      let expected =
        remove_at clause_index clause (id ^ " native clause/unit resolution pivot")
      in
      if not (same_clause_multiset expected result) then
        error (id ^ ": native core proof-term clause/unit resolution result does not remove the selected literal");
      let target_prop = native_core_clause_prop id result in
      let rec consume unit_proof selected_index clause proof =
        match clause, selected_index with
        | [], _ -> error (id ^ ": native core proof-term clause/unit resolution pivot index is out of bounds")
        | [literal], Some 0 when literal = selected ->
            native_core_branch_from_complement_proofs
              target_prop unit_literal unit_proof literal proof
        | [literal], Some _ ->
            error (id ^ ": native core proof-term clause/unit resolution pivot index is out of bounds")
        | [literal], None ->
            native_core_prove_literal_to_clause id result literal proof
        | literal :: rest, selected_index ->
            let literal_prop = native_core_literal_prop literal in
            let rest_prop = native_core_clause_prop id rest in
            let head_branch =
              PLam
                (literal_prop,
                 match selected_index with
                 | Some 0 when literal = selected ->
                     native_core_branch_from_complement
                       target_prop unit_proof unit_literal literal
                 | Some 0 ->
                     error (id ^ ": native core proof-term clause/unit resolution selected literal mismatch")
                 | _ ->
                     native_core_prove_literal_to_clause id result literal (Hyp 0))
            in
            let tail_selected =
              match selected_index with
              | Some 0 -> None
              | Some n -> Some (n - 1)
              | None -> None
            in
            let tail_branch =
              PLam
                (rest_prop,
                 consume (pfshift 0 1 unit_proof) tail_selected rest (Hyp 0))
            in
            PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
      in
      consume unit_proof (Some clause_index) clause clause_proof
  | [_], _ ->
      error (id ^ ": native core proof-term clause/unit resolution unit index is out of bounds")
  | _ ->
      error (id ^ ": native core proof-term clause/unit resolution expected a unit side clause")

let native_core_false_from_two_pivots main_pivot side_pivot =
  match main_pivot, side_pivot with
  | Pos main_atom, Neg side_atom when native_core_same_atom main_atom side_atom ->
      PPfAp (Hyp 0, Hyp 1)
  | Neg main_atom, Pos side_atom when native_core_same_atom main_atom side_atom ->
      PPfAp (Hyp 1, Hyp 0)
  | _ -> error "native core proof-term checker expected complementary binary pivots"

let native_core_resolve_binary_binary id main_clause main_proof main_index side_clause side_proof side_index result =
  match main_clause, side_clause, result with
  | [main_left; main_right], [side_left; side_right], [_; _] ->
      let target_prop = native_core_clause_prop id result in
      let main_pivot, main_remaining =
        match main_index with
        | 0 -> (main_left, main_right)
        | 1 -> (main_right, main_left)
        | _ -> error (id ^ ": native core proof-term checker got bad binary pivot index")
      in
      let side_pivot, side_remaining =
        match side_index with
        | 0 -> (side_left, side_right)
        | 1 -> (side_right, side_left)
        | _ -> error (id ^ ": native core proof-term checker got bad binary pivot index")
      in
      if not (native_core_complement main_pivot side_pivot) then
        error (id ^ ": native core proof-term checker expected complementary binary pivots");
      let side_pivot_prop = native_core_literal_prop side_pivot in
      let side_remaining_prop = native_core_literal_prop side_remaining in
      let main_pivot_branch =
        let side_pivot_branch =
          PLam
            (side_pivot_prop,
             PTmAp (native_core_false_from_two_pivots main_pivot side_pivot, target_prop))
        in
        let side_remaining_branch =
          PLam
            (side_remaining_prop,
             native_core_prove_literal_to_clause id result side_remaining (Hyp 0))
        in
        let side_left_branch, side_right_branch =
          if side_index = 0 then
            (side_pivot_branch, side_remaining_branch)
          else
            (side_remaining_branch, side_pivot_branch)
        in
        PLam
          (native_core_literal_prop main_pivot,
           PPfAp
             (PPfAp (PTmAp (pfshift 0 1 side_proof, target_prop), side_left_branch),
              side_right_branch))
      in
      let main_remaining_branch =
        PLam
          (native_core_literal_prop main_remaining,
           native_core_prove_literal_to_clause id result main_remaining (Hyp 0))
      in
      let main_left_branch, main_right_branch =
        if main_index = 0 then
          (main_pivot_branch, main_remaining_branch)
        else
          (main_remaining_branch, main_pivot_branch)
      in
      PPfAp
        (PPfAp (PTmAp (main_proof, target_prop), main_left_branch),
         main_right_branch)
  | _ -> error (id ^ ": native core proof-term checker expected binary/binary resolution")

let native_core_resolve_clause_clause id left_clause left_proof left_index right_clause right_proof right_index result =
  let left_pivot =
    nth left_index left_clause (id ^ " native clause/clause resolution left pivot")
  in
  let right_pivot =
    nth right_index right_clause (id ^ " native clause/clause resolution right pivot")
  in
  if not (native_core_complement left_pivot right_pivot) then
    error (id ^ ": native core proof-term checker expected complementary clause/clause pivots");
  let expected =
    remove_at left_index left_clause (id ^ " native clause/clause resolution left pivot")
    @ remove_at right_index right_clause (id ^ " native clause/clause resolution right pivot")
  in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native core proof-term clause/clause resolution result does not remove exactly the selected pivots");
  let target_prop = native_core_clause_prop id result in
  let rec consume_right left_pivot_proof selected_index clause proof =
    match clause, selected_index with
    | [], _ ->
        error (id ^ ": native core proof-term clause/clause right pivot index is out of bounds")
    | [literal], Some 0 when literal = right_pivot ->
        native_core_branch_from_complement_proofs
          target_prop left_pivot left_pivot_proof literal proof
    | [literal], Some _ ->
        error (id ^ ": native core proof-term clause/clause right pivot index is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = right_pivot ->
                 native_core_branch_from_complement_proofs
                   target_prop left_pivot (pfshift 0 1 left_pivot_proof) literal (Hyp 0)
             | Some 0 ->
                 error (id ^ ": native core proof-term clause/clause right selected literal mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume_right
               (pfshift 0 1 left_pivot_proof)
               tail_selected
               rest
               (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  let rec consume_left right_proof selected_index clause proof =
    match clause, selected_index with
    | [], _ ->
        error (id ^ ": native core proof-term clause/clause left pivot index is out of bounds")
    | [literal], Some 0 when literal = left_pivot ->
        consume_right (Hyp 0) (Some right_index) right_clause right_proof
    | [literal], Some _ ->
        error (id ^ ": native core proof-term clause/clause left pivot index is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = left_pivot ->
                 consume_right (Hyp 0) (Some right_index) right_clause (pfshift 0 1 right_proof)
             | Some 0 ->
                 error (id ^ ": native core proof-term clause/clause left selected literal mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume_left (pfshift 0 1 right_proof) tail_selected rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume_left right_proof (Some left_index) left_clause left_proof

let native_core_validate_resolve_step id left_clause right_clause left_index right_index result =
  let left_pivot =
    nth left_index left_clause (id ^ " native resolve left pivot")
  in
  let right_pivot =
    nth right_index right_clause (id ^ " native resolve right pivot")
  in
  if not (native_core_complement left_pivot right_pivot) then
    error (id ^ ": native preprocess proof-term resolve expected complementary pivots");
  let expected =
    remove_at left_index left_clause (id ^ " native resolve left pivot")
    @ remove_at right_index right_clause (id ^ " native resolve right pivot")
  in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native preprocess proof-term resolve result does not remove exactly the selected pivots")

let native_core_factor id parent_clause parent_proof left_index right_index result =
  if left_index = right_index then
    error (id ^ ": native core proof-term factor literal indices must be distinct");
  let left = nth left_index parent_clause (id ^ " native factor left literal") in
  let right = nth right_index parent_clause (id ^ " native factor right literal") in
  if left <> right then
    error (id ^ ": native core proof-term factor literals are not identical");
  let remove_index = if left_index > right_index then left_index else right_index in
  let expected =
    remove_at remove_index parent_clause (id ^ " native factor removed literal")
  in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native core proof-term factor result does not remove one duplicate literal");
  let target_prop = native_core_clause_prop id result in
  let rec consume clause proof =
    match clause with
    | [] -> error (id ^ ": native core proof-term factor parent clause is empty")
    | [literal] ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume parent_clause parent_proof

let native_core_validate_factor_step id parent_clause left_index right_index result =
  if left_index = right_index then
    error (id ^ ": native preprocess proof-term factor literal indices must be distinct");
  let left = nth left_index parent_clause (id ^ " native factor left literal") in
  let right = nth right_index parent_clause (id ^ " native factor right literal") in
  if left <> right then
    error (id ^ ": native preprocess proof-term factor literals are not identical");
  let remove_index = if left_index > right_index then left_index else right_index in
  let expected =
    remove_at remove_index parent_clause (id ^ " native factor removed literal")
  in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native preprocess proof-term factor result does not remove one duplicate literal")

let native_core_reflexive_eq_proof = function
  | Ap (Ap (TpAp (TmH h, tp), left), right)
      when h = megalodon_eq_poly_hash && left = right ->
      Some
        (TLam
           (Ar (tp, Ar (tp, Prop)),
            PLam
              (Ap (Ap (DB 0, tmshift 0 1 left), tmshift 0 1 left),
           Hyp 0)))
  | Ap (Ap (TmH h, left), right)
      when (h = "=" || h = "eq") && left = right ->
      Some
        (TLam
           (Ar (Set, Ar (Set, Prop)),
            PLam
              (Ap (Ap (DB 0, tmshift 0 1 left), tmshift 0 1 left),
           Hyp 0)))
  | _ -> None

let native_core_definition_input_proof sgdelta id variables result_step_variables clause =
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  match clause with
  | [Pos atom] ->
      let atom = close_tm atom in
      begin match megalodon_eq_poly_sides atom with
      | Some (tp, left, right) ->
          begin match conv left right sgdelta [] with
          | Some _ ->
              begin match
                native_core_reflexive_eq_proof
                  (Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), left), left))
              with
              | Some proof ->
                  let proof =
                    native_core_close_pf (variables @ result_step_variables) proof
                  in
                  List.fold_right
                    (fun (_, tp) proof -> TLam (tp, proof))
                    result_step_variables
                    proof
              | None ->
                  error
                    (id ^ ": native preprocess proof-term definition_input cannot build reflexivity proof")
              end
          | None ->
              error
                (id ^ ": native preprocess proof-term definition_input equality is not convertible under generated definitions")
          end
      | None ->
          error
            (id ^ ": native preprocess proof-term definition_input supports only Megalodon polymorphic equality")
      end
  | _ ->
      error
        (id ^ ": native preprocess proof-term definition_input expects a singleton positive equality")

let native_core_prop_ext_hash =
  "23ea4ad0d25e31cb704cd6f5752b77c544628e235c5c99d36647ab24d0d261c9"

let native_core_dneg_hash =
  "e4b03c310442ae760be9945e176494db51515dfb952ee60fbd42e05527752af0"

let native_core_not_forall_exists_hash = function
  | Set -> "vampire_not_forall_exists_set"
  | Prop -> "vampire_not_forall_exists_prop"
  | Ar (Set, Prop) -> "vampire_not_forall_exists_set_prop"
  | Ar (Set, Set) -> "vampire_not_forall_exists_set_set"
  | Ar (Set, Ar (Set, Prop)) -> "vampire_not_forall_exists_set_set_prop"
  | _ -> "vampire_not_forall_exists_unsupported"

let native_core_eps_symbol = function
  | Set -> "Eps_i"
  | Prop -> "Eps_prop"
  | Ar (Set, Prop) -> "Eps_set_prop"
  | Ar (Set, Set) -> "Eps_set_set"
  | Ar (Set, Ar (Set, Prop)) -> "Eps_set_set_prop"
  | _ -> "Eps_unsupported"

let native_core_exists_choice_hash = function
  | Set -> "vampire_exists_set_choice"
  | Prop -> "vampire_exists_prop_choice"
  | Ar (Set, Prop) -> "vampire_exists_set_prop_choice"
  | Ar (Set, Set) -> "vampire_exists_set_set_choice"
  | Ar (Set, Ar (Set, Prop)) -> "vampire_exists_set_set_prop_choice"
  | _ -> "vampire_exists_unsupported_choice"

let native_core_eq_prop left right =
  Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, Prop), left), right)

let native_core_eq_atom tp left right =
  Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), left), right)

let native_core_prop_ext_prop =
  All
    (Prop,
     All
       (Prop,
        Imp
          (Imp (DB 1, DB 0),
           Imp
             (Imp (DB 0, DB 1),
              native_core_expand_eq_atom (native_core_eq_prop (DB 1) (DB 0))))))

let native_core_dneg_prop =
  All
    (Prop,
     Imp
       (Imp (Imp (DB 0, native_core_false), native_core_false),
        DB 0))

let native_core_not_forall_exists_prop tp =
  All
    (Ar (tp, Prop),
     All
       (Ar (tp, Prop),
        Imp
          (All
             (tp,
              Imp
                (Imp (Ap (DB 2, DB 0), native_core_false),
                 Ap (DB 1, DB 0))),
           Imp
             (Imp (All (tp, Ap (DB 2, DB 0)), native_core_false),
              native_core_exists tp (Ap (DB 1, DB 0))))))

let native_core_exists_choice_prop tp =
  let eps = native_core_eps_symbol tp in
  All
    (Ar (tp, Prop),
     Imp
       (native_core_exists tp (Ap (DB 1, DB 0)),
        Ap (DB 0, Ap (TmH eps, DB 0))))

let native_core_skolem_dependency_names cert id =
  let count =
    match native_core_metadata_step_extra_field
            cert id "kernel_v1" "introduced_0_dependency_count"
    with
    | Some value ->
        begin try int_of_string value
        with Failure _ ->
          error (id ^ ": native core proof-term skolemization has non-numeric dependency count")
        end
    | None ->
        error (id ^ ": native core proof-term skolemization is missing dependency count metadata")
  in
  let rec collect index =
    if index = count then []
    else
      let key = "introduced_0_dependency_" ^ string_of_int index ^ "_var" in
      match native_core_metadata_step_extra_field cert id "kernel_v1" key with
      | Some name -> native_core_ident name :: collect (index + 1)
      | None ->
          error
            (id ^ ": native core proof-term skolemization is missing dependency variable metadata")
  in
  collect 0

let native_core_skolem_context_for_source cert id source =
  let step_variables = native_core_step_variables cert id in
  let variable_name index tp =
    match List.nth_opt step_variables index with
    | Some (name, declared_tp) when declared_tp = tp -> name
    | _ ->
        begin match List.find_opt (fun (_, declared_tp) -> declared_tp = tp) step_variables with
        | Some (name, _) -> name
        | None -> "__skolem_context_" ^ string_of_int index
        end
  in
  let rec find all_index context = function
    | Ap (TmH "vampire_exists_prop", Lam (tp, body)) ->
        Some (List.rev context, tp, body)
    | All (tp, body) ->
        let name = variable_name all_index tp in
        find (all_index + 1) ((name, tp) :: context) body
    | Ap (Ap (TmH "vampire_or", left), right) ->
        begin match find all_index context left with
        | Some _ as found -> found
        | None -> find all_index context right
        end
    | _ -> None
  in
  match find 0 [] source with
  | Some found -> found
  | None ->
      error
        (id ^ ": native core proof-term skolemization could not find existential source")

let native_core_skolem_definition_body cert id source =
  let context, witness_tp, body = native_core_skolem_context_for_source cert id source in
  let dependency_names = native_core_skolem_dependency_names cert id in
  let dependency_tps =
    List.map
      (fun name ->
         match List.assoc_opt name context with
         | Some tp -> tp
         | None ->
             error
               (id ^ ": native core proof-term skolemization dependency is not in source context"))
      dependency_names
  in
  let context_count = List.length context in
  let dependency_count = List.length dependency_names in
  let dependency_index name =
    let rec find index = function
      | [] -> None
      | candidate :: rest ->
          if candidate = name then Some index else find (index + 1) rest
    in
    find 0 dependency_names
  in
  let rec translate depth = function
    | DB index when index >= depth ->
        let external_index = index - depth in
        if external_index = 0 then DB (depth + 0)
        else
          let context_index = context_count - external_index in
          begin match List.nth_opt context context_index with
          | Some (name, _) ->
              begin match dependency_index name with
              | Some dep_index -> DB (depth + dependency_count - dep_index)
              | None ->
                  error
                    (id ^ ": native core proof-term skolemization body mentions a non-dependency context variable")
              end
          | None ->
              error
                (id ^ ": native core proof-term skolemization body has an out-of-scope de Bruijn index")
          end
    | TpAp (tm, tp) -> TpAp (translate depth tm, tp)
    | Ap (left, right) -> Ap (translate depth left, translate depth right)
    | Lam (tp, body) -> Lam (tp, translate (depth + 1) body)
    | Imp (left, right) -> Imp (translate depth left, translate depth right)
    | All (tp, body) -> All (tp, translate (depth + 1) body)
    | tm -> tm
  in
  let eps = native_core_eps_symbol witness_tp in
  if eps = "Eps_unsupported" then
    error
      (id ^ ": native core proof-term skolemization has no epsilon operator for witness sort");
  let predicate =
    Lam (witness_tp, native_core_formula_prop body |> translate 0)
  in
  let definition = Ap (TmH eps, predicate) |> tm_beta_eta_norm in
  List.fold_right (fun tp tm -> Lam (tp, tm)) dependency_tps definition

let native_core_approved_sgdelta () =
  let sgdelta = Hashtbl.create 2 in
  Hashtbl.add sgdelta native_core_prop_ext_hash (0, native_core_prop_ext_prop);
  Hashtbl.add sgdelta native_core_dneg_hash (0, native_core_dneg_prop);
  List.iter
    (fun tp ->
       Hashtbl.add
         sgdelta
         (native_core_not_forall_exists_hash tp)
         (0, native_core_not_forall_exists_prop tp))
    [Set; Prop; Ar (Set, Prop); Ar (Set, Set); Ar (Set, Ar (Set, Prop))];
  List.iter
    (fun tp ->
       Hashtbl.add
         sgdelta
         (native_core_exists_choice_hash tp)
         (0, native_core_exists_choice_prop tp))
    [Set; Prop; Ar (Set, Prop); Ar (Set, Set); Ar (Set, Ar (Set, Prop))];
  sgdelta

let native_core_certificate_sgdelta cert symbol_table =
  let sgdelta = native_core_approved_sgdelta () in
  let definitions = native_core_definition_delta_table cert symbol_table in
  let avatar_definitions = native_core_avatar_delta_table cert in
  let add_sequential_skolem_definitions id source subst =
    let step_variables = native_core_step_variables cert id in
    let variable_name index tp =
      match List.nth_opt step_variables index with
      | Some (name, declared_tp) when declared_tp = tp -> name
      | _ ->
          begin match List.find_opt (fun (_, declared_tp) -> declared_tp = tp) step_variables with
          | Some (name, _) -> name
          | None -> "__skolem_context_" ^ string_of_int index
          end
    in
    let dependency_arg_name = function
      | TmH raw_name -> native_core_ident_opt raw_name
      | _ -> None
    in
    let witness_dependency_names witness =
      match native_core_flatten_value_application witness with
      | TmH _, args ->
          let dependency_names = List.filter_map dependency_arg_name args in
          if List.length dependency_names = List.length args then
            Some dependency_names
          else
            None
      | _ -> None
    in
    let context_names_in_body context body =
      let context_count = List.length context in
      let add_name name names =
        if List.mem name names then names else name :: names
      in
      let rec collect depth names = function
        | DB index when index >= depth ->
            let external_index = index - depth in
            if external_index = 0 then names
            else
              let context_index = context_count - external_index in
              begin match List.nth_opt context context_index with
              | Some (name, _) -> add_name name names
              | None -> names
              end
        | TpAp (tm, _) -> collect depth names tm
        | Ap (left, right) | Imp (left, right) ->
            collect depth (collect depth names left) right
        | Lam (_, body) | All (_, body) -> collect (depth + 1) names body
        | TmH _ | DB _ | Prim _ -> names
      in
      collect 0 [] body
    in
    let witness_dependencies_cover context required witness =
      match witness_dependency_names witness with
      | Some dependency_names ->
          List.for_all
            (fun name -> List.mem_assoc name context)
            dependency_names
          && List.for_all
               (fun name -> List.mem name dependency_names)
               required
      | None -> false
    in
    let choose_witness context body subst =
      let required = context_names_in_body context body in
      let rec choose skipped = function
        | [] -> None
        | ((_, witness) as binding) :: rest ->
            if witness_dependencies_cover context required witness then
              Some (witness, List.rev_append skipped rest)
            else
              choose (binding :: skipped) rest
      in
      choose [] subst
    in
    let dependency_type context name =
      match List.assoc_opt name context with
      | Some tp -> Some tp
      | None -> List.assoc_opt name step_variables
    in
    let add_definition context witness_tp body witness =
      match native_core_flatten_value_application witness with
      | TmH symbol, args ->
          let dependency_names =
            List.filter_map dependency_arg_name args
          in
          if List.length dependency_names <> List.length args then ()
          else
            let dependency_tps =
              List.filter_map (dependency_type context) dependency_names
            in
            if List.length dependency_tps <> List.length dependency_names then ()
            else
              let context_count = List.length context in
              let dependency_count = List.length dependency_names in
              let dependency_index name =
                let rec find index = function
                  | [] -> None
                  | candidate :: rest ->
                      if candidate = name then Some index
                      else find (index + 1) rest
                in
                find 0 dependency_names
              in
              let rec translate depth = function
                | DB index when index >= depth ->
                    let external_index = index - depth in
                    if external_index = 0 then DB (depth + 0)
                    else
                      let context_index = context_count - external_index in
                      begin match List.nth_opt context context_index with
                      | Some (name, _) ->
                          begin match dependency_index name with
                          | Some dep_index ->
                              DB (depth + dependency_count - dep_index)
                          | None ->
                              error
                                (id ^ ": native core proof-term skolemization body mentions a non-dependency context variable")
                          end
                      | None ->
                          error
                            (id ^ ": native core proof-term skolemization body has an out-of-scope de Bruijn index")
                      end
                | TpAp (tm, tp) -> TpAp (translate depth tm, tp)
                | Ap (left, right) ->
                    Ap (translate depth left, translate depth right)
                | Lam (tp, body) -> Lam (tp, translate (depth + 1) body)
                | Imp (left, right) ->
                    Imp (translate depth left, translate depth right)
                | All (tp, body) -> All (tp, translate (depth + 1) body)
                | tm -> tm
              in
              let eps = native_core_eps_symbol witness_tp in
              if eps = "Eps_unsupported" then
                error
                  (id ^ ": native core proof-term skolemization has no epsilon operator for witness sort");
              let predicate =
                Lam (witness_tp, native_core_formula_prop body |> translate 0)
              in
              let definition =
                Ap (TmH eps, predicate) |> tm_beta_eta_norm
              in
              Hashtbl.replace
                definitions
                symbol
                (0, List.fold_right (fun tp tm -> Lam (tp, tm)) dependency_tps definition)
      | _ -> ()
    in
    let rec add all_index context source subst =
      match source, subst with
      | Ap (TmH "vampire_exists_prop", Lam (tp, body)), _ ->
          begin match choose_witness context body subst with
          | Some (witness, rest) ->
              add_definition context tp body witness;
              add all_index context (tmsubst body 0 witness) rest
          | None -> subst
          end
      | All (tp, body), _ ->
          let name = variable_name all_index tp in
          add (all_index + 1) (context @ [(name, tp)]) body subst
      | Ap (Ap (TmH ("vampire_or" | "vampire_and"), left), right), _ ->
          let rest = add all_index context left subst in
          add all_index context right rest
      | Imp (left, right), _ ->
          let rest = add all_index context left subst in
          add all_index context right rest
      | _ -> subst
    in
    let add_skolem_definitions_from_parent_formulas () =
      let parse_tm_field key =
        match native_core_metadata_step_extra_field cert id "kernel_v1" key with
        | Some value -> Some (parse_tm (parse_sexpr value))
        | None -> None
      in
      let introduced_count =
        match native_core_metadata_step_extra_field
                cert id "kernel_v1" "introduced_count"
        with
        | Some value ->
            begin try int_of_string value
            with Failure _ -> 0
            end
        | None -> 0
      in
      let rec peel_foralls all_index context = function
        | All (tp, body) ->
            let name = variable_name all_index tp in
            peel_foralls (all_index + 1) (context @ [(name, tp)]) body
        | body -> context, body
      in
      let rec contains_tm needle tm =
        tm = needle ||
        match tm with
        | TpAp (body, _) -> contains_tm needle body
        | Ap (left, right) | Imp (left, right) ->
            contains_tm needle left || contains_tm needle right
        | Lam (_, body) | All (_, body) -> contains_tm (tmshift 0 1 needle) body
        | TmH _ | DB _ | Prim _ -> false
      in
      let parent_definition_source formula =
        let context, body = peel_foralls 0 [] formula in
        match body with
        | Imp (Ap (TmH "vampire_exists_prop", Lam (witness_tp, exists_body)), target_body) ->
            Some (context, witness_tp, exists_body, target_body)
        | _ -> None
      in
      let witnesses =
        List.init introduced_count (fun index ->
          parse_tm_field ("introduced_" ^ string_of_int index ^ "_witness_term"))
        |> List.filter_map (fun x -> x)
      in
      for index = 0 to introduced_count - 1 do
        match
          parse_tm_field ("parent_" ^ string_of_int (index + 1) ^ "_formula")
        with
        | Some parent_formula ->
            begin match parent_definition_source parent_formula with
            | Some (context, witness_tp, body, target_body) ->
                begin match
                  witnesses
                  |> List.find_opt
                       (fun witness ->
                          let closed_witness = native_core_close_tm context witness in
                          contains_tm closed_witness target_body)
                with
                | Some witness -> add_definition context witness_tp body witness
                | None -> ()
                end
            | None -> ()
            end
        | _ -> ()
      done
    in
    ignore (add 0 [] source subst);
    add_skolem_definitions_from_parent_formulas ()
  in
  let add_skolem_definition id symbol source =
    Hashtbl.replace
      definitions
      symbol
      (0, native_core_skolem_definition_body cert id source)
  in
  let skolem_witness_matches_metadata id symbol witness =
    match native_core_metadata_step_extra_field
            cert id "kernel_v1" "introduced_0_dependency_count"
    with
    | None -> false
    | Some count ->
        begin try
          let dependency_count = int_of_string count in
          let head, args = native_core_flatten_value_application witness in
          head = TmH symbol && List.length args = dependency_count
        with Failure _ -> false
        end
  in
  List.iter
    (function
      | SkolemFormula (id, _, Some source, introductions, subst, _) ->
          add_sequential_skolem_definitions id source subst;
          begin match introductions, subst with
          | [{ skolem_intro_symbol = symbol; _ }], [(_, witness)]
              when skolem_witness_matches_metadata id symbol witness ->
              begin match
                native_core_metadata_step_extra_field
                  cert id "kernel_v1" "introduced_0_dependency_count"
              with
              | Some _ -> add_skolem_definition id symbol source
              | _ -> ()
              end
          | _ -> ()
          end
      | _ -> ())
    cert.steps;
  List.iter
    (function
      | PredicateDefinition (id, symbol, formula) ->
          let defined, _, _ = predicate_definition_parts id formula in
          let body =
            native_core_predicate_definition_body symbol_table id symbol formula
          in
          Hashtbl.replace definitions (native_core_ident defined) (0, body)
      | _ -> ())
    cert.steps;
  Hashtbl.iter
    (fun h v -> Hashtbl.replace sgdelta h v)
    definitions;
  Hashtbl.iter
    (fun h v -> Hashtbl.replace sgdelta h v)
    avatar_definitions;
  Hashtbl.iter
    (fun h v -> Hashtbl.replace definitions h v)
    avatar_definitions;
  sgdelta, definitions

let native_core_expand_generated_skolems_tm ?(ambient_shift=0) cert definitions input =
  let generated = native_core_generated_skolem_symbols cert in
  let is_generated h = List.mem h generated in
  let rec leading_lam_count count = function
    | Lam (_, body) -> leading_lam_count (count + 1) body
    | _ -> count
  in
  let rec apply_definition body = function
    | [] -> tm_beta_eta_norm body
    | arg :: rest ->
        begin match tm_beta_eta_norm body with
        | Lam (_, body) -> apply_definition (tmsubst body 0 arg) rest
        | body -> apply_definition (Ap (body, arg)) rest
        end
  in
  let rec tm depth input =
    let mapped =
      match input with
      | TpAp (m, a) -> TpAp (tm depth m, a)
      | Ap (m, n) -> Ap (tm depth m, tm depth n)
      | Lam (a, body) -> Lam (a, tm (depth + 1) body)
      | Imp (m, n) -> Imp (tm depth m, tm depth n)
      | All (a, body) -> All (a, tm (depth + 1) body)
      | DB _ | TmH _ | Prim _ -> input
    in
    let head, args = native_core_flatten_value_application mapped in
    match head with
    | TmH h when is_generated h ->
        begin match Hashtbl.find_opt definitions h with
        | Some (0, body) ->
            if List.length args < leading_lam_count 0 body then mapped
            else tm depth (apply_definition (tmshift 0 (ambient_shift + depth) body) args)
        | _ ->
            mapped
        end
    | _ -> mapped
  in
  tm 0 input

let native_core_expand_generated_skolems_step cert definitions step =
  let tm = native_core_expand_generated_skolems_tm cert definitions in
  let literal = function
    | Pos atom -> Pos (tm atom)
    | Neg atom -> Neg (tm atom)
  in
  let clause literals = List.map literal literals in
  let subst substitution =
    List.map (fun (name, value) -> (name, tm value)) substitution
  in
  let ennf_pair pair =
    {
      pair with
      ennf_pair_source = tm pair.ennf_pair_source;
      ennf_pair_target = tm pair.ennf_pair_target;
    }
  in
  match step with
  | Input (id, source, result) -> Input (id, source, clause result)
  | FormulaInput (id, source, result) -> FormulaInput (id, source, literal result)
  | FormulaTermInput (id, source, result) -> FormulaTermInput (id, source, tm result)
  | FormulaTermCopy (id, parent_id, result) -> FormulaTermCopy (id, parent_id, tm result)
  | RectifyFormula (id, parent_id, renamings, result) ->
      RectifyFormula (id, parent_id, renamings, tm result)
  | FoolAtomLift (id, source, target, path) ->
      FoolAtomLift (id, tm source, tm target, path)
  | FoolFormula (id, parent_id, result) -> FoolFormula (id, parent_id, tm result)
  | EnnfFormula (id, parent_id, source, pairs, result) ->
      EnnfFormula
        (id, parent_id, Option.map tm source, List.map ennf_pair pairs, tm result)
  | SkolemFormula (id, parent_id, source, introductions, substitution, result) ->
      SkolemFormula
        (id, parent_id, source, introductions, substitution, result)
  | SkolemFormulaComputed (id, parent_id, substitution) ->
      SkolemFormulaComputed (id, parent_id, subst substitution)
  | CnfFormulaClause (id, parent_id, index, count, result) ->
      CnfFormulaClause (id, parent_id, index, count, clause result)
  | FormulaCopy (id, parent_id, result) -> FormulaCopy (id, parent_id, literal result)
  | FoolBool (id, parent_id, result) -> FoolBool (id, parent_id, literal result)
  | CnfLiteral (id, parent_id, result) -> CnfLiteral (id, parent_id, clause result)
  | PredicateDefinition (id, symbol, result) -> PredicateDefinition (id, symbol, tm result)
  | PredicateDefinitionFold (id, source, definition, result) ->
      PredicateDefinitionFold (id, source, definition, tm result)
  | PredicateDefinitionFoldChain (id, source, definitions, result) ->
      PredicateDefinitionFoldChain (id, source, definitions, tm result)
  | DefinitionInput (id, result) -> DefinitionInput (id, clause result)
  | DefinitionRewriteChain (id, parent_id, rewrites, result) ->
      DefinitionRewriteChain (id, parent_id, rewrites, clause result)
  | AvatarComponent (id, result) -> AvatarComponent (id, clause result)
  | AvatarDefinition (id, split_var, split_positive, result) ->
      AvatarDefinition (id, split_var, split_positive, clause result)
  | SplitDependency (id, owner_id, dependencies, result) ->
      SplitDependency (id, owner_id, dependencies, clause result)
  | AvatarSplit (id, parent_ids, result) -> AvatarSplit (id, parent_ids, clause result)
  | AvatarContradiction (id, parent_ids, result) ->
      AvatarContradiction (id, parent_ids, clause result)
  | AvatarRefutation (id, parent_ids, sat_clauses, sat_proof, result) ->
      AvatarRefutation (id, parent_ids, sat_clauses, sat_proof, clause result)
  | FoolExhaustiveness (id, result) -> FoolExhaustiveness (id, clause result)
  | FoolDistinctness (id, result) -> FoolDistinctness (id, clause result)
  | InequalityNameIntro (id, result) -> InequalityNameIntro (id, clause result)
  | InequalitySplit (id, parent_id, splits, result) ->
      InequalitySplit (id, parent_id, splits, clause result)
  | Substitute (id, parent_id, substitution, result) ->
      Substitute (id, parent_id, subst substitution, clause result)
  | Condensation (id, parent_id, substitution, result) ->
      Condensation (id, parent_id, subst substitution, clause result)
  | UnitResultingResolution (id, parent_id, trace, result) ->
      UnitResultingResolution (id, parent_id, trace, clause result)
  | Resolve (id, left_id, right_id, left_index, right_index, result) ->
      Resolve (id, left_id, right_id, left_index, right_index, clause result)
  | SubsumptionResolution (id, main_parent_id, side_parent_id, selected, side_pivot, side_subst, result) ->
      SubsumptionResolution
        (id, main_parent_id, side_parent_id, literal selected,
         literal side_pivot, subst side_subst, clause result)
  | Factor (id, parent_id, left_index, right_index, result) ->
      Factor (id, parent_id, left_index, right_index, clause result)
  | EqualityResolution (id, parent_id, literal_index, result) ->
      EqualityResolution (id, parent_id, literal_index, clause result)
  | EqualityResolutionConstraints (id, parent_id, literal_index, selected, constraints, result) ->
      EqualityResolutionConstraints
        (id, parent_id, literal_index, literal selected,
         clause constraints, clause result)
  | EqualityFactoring (id, parent_id, selected_index, other_index, explicit_sides, substitution, result) ->
      EqualityFactoring
        (id, parent_id, selected_index, other_index,
         Option.map (fun (selected_lhs, other_rhs) -> (tm selected_lhs, tm other_rhs)) explicit_sides,
         subst substitution,
         clause result)
  | EqualityFactoringConstraints (id, parent_id, selected_index, other_index, explicit_sides, substitution, constraints, result) ->
      EqualityFactoringConstraints
        (id, parent_id, selected_index, other_index,
         Option.map (fun (selected_lhs, other_rhs) -> (tm selected_lhs, tm other_rhs)) explicit_sides,
         subst substitution,
         clause constraints, clause result)
  | TruthConflict (id, parent_id, literal_index, result) ->
      TruthConflict (id, parent_id, literal_index, clause result)
  | EqualitySymmetry (id, parent_id, literal_index, result) ->
      EqualitySymmetry (id, parent_id, literal_index, clause result)
  | BoolSimplify (id, parent_id, literal_index, positions, source, target, result) ->
      BoolSimplify
        (id, parent_id, literal_index, positions, tm source, tm target,
         clause result)
  | Paramodulate (id, equality_parent_id, target_parent_id, equality_index, target_index, position, from_tm, to_tm, result) ->
      Paramodulate
        (id, equality_parent_id, target_parent_id, equality_index, target_index,
         position, tm from_tm, tm to_tm, clause result)
  | Superposition (id, left_id, right_id, left_index, right_index, left_subst, right_subst, position, from_tm, to_tm, result) ->
      Superposition
        (id, left_id, right_id, left_index, right_index, subst left_subst,
         subst right_subst, position, tm from_tm, tm to_tm, clause result)
  | Contradiction _ as step -> step

let approved_native_sgdelta () =
  native_core_approved_sgdelta ()

let native_core_true_proof =
  TLam (Prop, PLam (DB 0, Hyp 0))

let native_core_xm_proof prop =
  let shifted_prop = tmshift 0 1 prop in
  let q = DB 0 in
  let not_prop = Imp (shifted_prop, native_core_false) in
  let hleft_prop = Imp (shifted_prop, q) in
  let hright_prop = Imp (not_prop, q) in
  let not_prop_proof =
    PLam
      (shifted_prop,
       PPfAp (Hyp 1, PPfAp (Hyp 3, Hyp 0)))
  in
  let q_proof = PPfAp (Hyp 1, not_prop_proof) in
  let false_proof = PPfAp (Hyp 0, q_proof) in
  TLam
    (Prop,
     PLam
       (hleft_prop,
        PLam
          (hright_prop,
           PPfAp
             (PTmAp (Known native_core_dneg_hash, q),
              PLam (Imp (q, native_core_false), false_proof)))))

let native_core_avatar_definition_proof_from_components cert variables id split_name component_literals =
  let split_prop = native_core_literal_prop (Pos (TmH split_name)) in
  let component_prop =
    native_core_step_clause_prop cert variables id component_literals
  in
  let rec instantiate_foralls proof target =
    match target with
    | All (tp, body) ->
        TLam
          (tp,
           instantiate_foralls
             (PTmAp (pftmshift 0 1 proof, DB 0))
             body)
    | _ -> proof
  in
  let prove_by_conversion target proof =
    PPfAp
      (PTmAp (Known native_core_dneg_hash, target),
       PLam
         (Imp (target, native_core_false),
          PPfAp (Hyp 0, pfshift 0 1 proof)))
  in
  let split_to_component =
    PLam
      (split_prop,
       instantiate_foralls (Hyp 0) component_prop)
  in
  let component_to_split =
    PLam
      (component_prop,
       prove_by_conversion split_prop (Hyp 0))
  in
  let left_prop = Imp (split_prop, component_prop) in
  let right_prop = Imp (component_prop, split_prop) in
  native_core_and_intro
    left_prop
    right_prop
    split_to_component
    component_to_split

let native_core_avatar_definition_proof cert variables id split_var split_positive clause =
  if not split_positive then
    error
      (id ^ ": native preprocess proof-term avatar_definition supports only positive split metadata");
  match native_core_avatar_definition_clause cert id split_var split_positive clause with
  | None ->
      error
        (id ^ ": native preprocess proof-term avatar_definition needs exactly one split literal and no local variables")
  | Some (split_name, component_literals) ->
      native_core_avatar_definition_proof_from_components
        cert variables id split_name component_literals

let native_core_avatar_split_proof cert id parent_ids result clause_table avatar_definitions =
  let split_literal =
    match result with
    | [literal] -> native_core_split_literal_name literal
    | _ -> None
  in
  let quantified_two_component_split source_id definition_ids =
    if definition_ids <> [] && native_core_is_split_clause result then begin
        let source_clause, source_proof = Hashtbl.find clause_table source_id in
        let target_prop = native_core_clause_prop id result in
        let result_literal_to_target literal =
          let literal_prop = native_core_literal_prop literal in
          PLam
            (literal_prop,
             native_core_prove_literal_to_clause
               id result literal (Hyp 0))
        in
        let result_split_literal_for split_name =
          let positive = Pos (TmH split_name) in
          let negative = Neg (TmH split_name) in
          if List.exists ((=) positive) result then Some positive
          else if List.exists ((=) negative) result then Some negative
          else
            None
        in
        let definition_info definition_id =
          let split_name, component_literals, definition_component_prop, definition_proof =
            try Hashtbl.find avatar_definitions definition_id
            with Not_found ->
              error
                (id ^ ": native preprocess proof-term avatar_split references unknown avatar definition")
          in
          match component_literals, native_core_step_variables cert definition_id with
          | _ :: _, ([] | [_]) ->
              let split_prop = native_core_literal_prop (Pos (TmH split_name)) in
              let component_to_split =
                native_core_and_elim_right
                  (Imp (split_prop, definition_component_prop))
                  (Imp (definition_component_prop, split_prop))
                  definition_proof
              in
              let split_to_component =
                native_core_and_elim_left
                  (Imp (split_prop, definition_component_prop))
                  (Imp (definition_component_prop, split_prop))
                  definition_proof
              in
              let component_witness =
                match native_core_step_variables cert definition_id with
                | [] -> None
                | [component_var, component_tp] ->
                    let open_component_prop =
                      native_core_clause_prop id component_literals
                    in
                    let component_body =
                      subst_named_tm component_var open_component_prop
                    in
                    let component_predicate =
                      Lam (component_tp, component_body)
                    in
                    let neg_component_predicate =
                      Lam (component_tp, Imp (component_body, native_core_false))
                    in
                    let witness =
                      Ap (TmH (native_core_eps_symbol component_tp), neg_component_predicate)
                    in
                    Some
                      (component_var, component_tp, component_body,
                       component_predicate, neg_component_predicate, witness)
                | _ -> assert false
              in
              (definition_id, split_name, component_literals, component_witness,
               definition_component_prop, component_to_split, split_to_component,
               split_prop, result_split_literal_for split_name)
          | _ ->
              error
                (id ^ ": native preprocess proof-term avatar_split quantified component needs at least one component literal and at most one component variable")
        in
        let infos = List.map definition_info definition_ids in
        let default_substitution =
          infos
          |> List.filter_map
               (fun (_, _, _, component_witness, _, _, _, _, _) ->
                  match component_witness with
                  | Some (component_var, _, _, _, _, witness) ->
                      Some (component_var, witness)
                  | None -> None)
        in
        let metadata_substitution =
          let field key =
            native_core_metadata_step_extra_field cert id "kernel_v1" key
          in
          let binding_count =
            match field "parent_var_binding_count" with
            | Some text -> (try int_of_string text with Failure _ -> 0)
            | None -> 0
          in
          let witness_for_split split_name =
            infos
            |> List.find_map
                 (fun (_, candidate_split, _, component_witness, _, _, _, _, _) ->
                    if candidate_split = split_name then
                      match component_witness with
                      | Some (_, _, _, _, _, witness) -> Some witness
                      | None -> None
                    else None)
          in
          let rec loop index acc =
            if index >= binding_count then List.rev acc
            else
              let prefix = "parent_var_binding_" ^ string_of_int index in
              let acc =
                match
                  field (prefix ^ "_parent_var"),
                  field (prefix ^ "_split_var")
                with
                | Some parent_var, Some split_var ->
                    begin match witness_for_split ("split_" ^ split_var) with
                    | Some witness -> (native_core_ident parent_var, witness) :: acc
                    | None -> acc
                    end
                | _ -> acc
              in
              loop (index + 1) acc
          in
          loop 0 []
        in
        let substitution =
          if metadata_substitution = [] then default_substitution
          else metadata_substitution @ default_substitution
        in
        let choice_free_quantified_split () =
          let quantified_positive_infos =
            infos
            |> List.filter_map
                 (fun (definition_id, split_name, component_literals, component_witness,
                       definition_component_prop, component_to_split,
                       split_to_component, split_prop, result_split_literal) ->
                    match component_witness, result_split_literal with
                    | Some (component_var, component_tp, component_body,
                            component_predicate, neg_component_predicate, _),
                      Some (Pos (TmH _)) ->
                        Some
                          (definition_id, split_name, component_literals,
                           component_var, component_tp, component_body,
                           component_predicate, neg_component_predicate,
                           definition_component_prop, component_to_split,
                           split_to_component, split_prop)
                    | _ -> None)
          in
          match quantified_positive_infos with
          | [(_definition_id, _split_name, quantified_component_literals,
              component_var, component_tp, component_body, component_predicate,
              neg_component_predicate, definition_component_prop,
              component_to_split, _split_to_component, _split_prop)] ->
              let source_step_variables = native_core_step_variables cert source_id in
              let bound_substitution =
                source_step_variables
                |> List.filter_map
                     (fun (name, tp) ->
                        if tp = component_tp then Some (name, DB 0) else None)
              in
              if bound_substitution = [] then None
              else
                let instantiated_source_clause =
                  subst_clause bound_substitution source_clause
                in
                let source_proof_instantiated =
                  List.fold_left
                    (fun proof (name, _) ->
                       let witness =
                         match List.assoc_opt name bound_substitution with
                         | Some witness -> witness
                         | None ->
                             error
                               (id ^ ": native preprocess proof-term avatar_split has no bound witness for source variable " ^ name)
                       in
                       PTmAp (proof, witness))
                    (pftmshift 0 1 (pfshift 0 2 source_proof))
                    source_step_variables
                in
                let quantified_component_literals =
                  subst_clause [(component_var, DB 0)] quantified_component_literals
                in
                let non_quantified_positive_infos =
                  infos
                  |> List.filter_map
                       (fun (_, split_name, component_literals, component_witness,
                             definition_component_prop, component_to_split,
                             _split_to_component, _split_prop, result_split_literal) ->
                          match component_witness, result_split_literal with
                          | None, Some (Pos (TmH _)) ->
                              Some
                                (split_name, component_literals,
                                 definition_component_prop, component_to_split)
                          | _ -> None)
                in
                let non_quantified_negative_infos =
                  infos
                  |> List.filter_map
                       (fun (_, split_name, component_literals, component_witness,
                             _definition_component_prop, _component_to_split,
                             split_to_component, split_prop, result_split_literal) ->
                          match component_witness, component_literals, result_split_literal with
                          | None, [component_literal], Some (Neg (TmH _)) ->
                              Some
                                (split_name, component_literal,
                                 split_to_component, split_prop)
                          | _ -> None)
                in
                let result_literal_to_target_under_literal literal =
                  pfshift 0 1 (result_literal_to_target literal)
                in
                let not_proof_for literal =
                  let literal_prop = native_core_literal_prop literal in
                  if List.exists ((=) literal) quantified_component_literals then
                    PLam
                      (literal_prop,
                       let literal_to_component =
                         native_core_prove_literal_to_clause
                           id quantified_component_literals literal (Hyp 0)
                       in
                       PPfAp (Hyp 1, literal_to_component))
                  else
                    let rec find_non_quantified = function
                      | [] ->
                          if List.exists ((=) literal) result then
                            let literal_to_target =
                              result_literal_to_target_under_literal literal
                            in
                            PLam
                              (literal_prop,
                               PPfAp (Hyp 2, PPfAp (literal_to_target, Hyp 0)))
                          else
                            error
                              (id ^ ": native preprocess proof-term avatar_split cannot refute choice-free source literal")
                      | (split_name, component_literals, _definition_component_prop,
                         component_to_split) :: rest ->
                          if List.exists ((=) literal) component_literals then
                            let split_literal = Pos (TmH split_name) in
                            let split_to_target =
                              result_literal_to_target_under_literal split_literal
                            in
                            PLam
                              (literal_prop,
                               let component_clause_proof =
                                 native_core_prove_literal_to_clause
                                   id component_literals literal (Hyp 0)
                               in
                               let split_proof =
                                 PPfAp
                                   (pftmshift 0 1 (pfshift 0 3 component_to_split),
                                    component_clause_proof)
                               in
                                 PPfAp
                                   (Hyp 2,
                                    PPfAp (split_to_target, split_proof)))
                          else
                            find_non_quantified rest
                    in
                    let rec find_non_quantified_negative = function
                      | [] ->
                          error
                            (id ^ ": native preprocess proof-term avatar_split cannot refute choice-free source literal")
                      | (split_name, component_literal, split_to_component, split_prop) :: rest ->
                          let complement_literal =
                            native_core_complement_literal component_literal
                          in
                          if literal = complement_literal then
                            let negative_split_literal = Neg (TmH split_name) in
                            let negative_split_prop =
                              native_core_literal_prop negative_split_literal
                            in
                            let negative_split_to_target =
                              result_literal_to_target_under_literal negative_split_literal
                            in
                            PLam
                              (literal_prop,
                               let not_negative_split =
                                 PLam
                                   (negative_split_prop,
                                    PPfAp
                                      (Hyp 3,
                                       PPfAp
                                         (pfshift 0 1 negative_split_to_target,
                                          Hyp 0)))
                               in
                               let split_proof =
                                 PPfAp
                                   (PTmAp (Known native_core_dneg_hash, split_prop),
                                    not_negative_split)
                               in
                               let component_proof =
                                 PPfAp
                                   (pfshift 0 1 split_to_component,
                                    split_proof)
                               in
                               native_core_false_from_complement_proofs
                                 component_literal
                                 component_proof
                                 complement_literal
                                 (Hyp 0))
                          else
                            find_non_quantified_negative rest
                    in
                    try find_non_quantified non_quantified_positive_infos
                    with Error _ ->
                      find_non_quantified_negative non_quantified_negative_infos
                in
                let rec contradiction depth clause proof =
                  match clause with
                  | [] -> proof
                  | [literal] ->
                      PPfAp (pfshift 0 depth (not_proof_for literal), proof)
                  | literal :: rest ->
                      let literal_prop = native_core_literal_prop literal in
                      let rest_prop = native_core_clause_prop id rest in
                      let left_branch =
                        PLam
                          (literal_prop,
                           PPfAp
                             (pfshift 0 (depth + 1) (not_proof_for literal),
                              Hyp 0))
                      in
                      let right_branch =
                        PLam
                          (rest_prop,
                           contradiction (depth + 1) rest (Hyp 0))
                      in
                      PPfAp
                        (PPfAp (PTmAp (proof, native_core_false), left_branch),
                         right_branch)
                in
                let proof =
                  PPfAp
                    (PTmAp (Known native_core_dneg_hash, target_prop),
                     PLam
                       (Imp (target_prop, native_core_false),
                        let split_to_target =
                          result_literal_to_target
                            (Pos
                               (TmH
                                  (match quantified_positive_infos with
                                   | [(_, split_name, _, _, _, _, _, _, _, _, _, _)] -> split_name
                                   | _ -> assert false)))
                        in
                        let not_split =
                          PLam
                            (native_core_literal_prop
                               (Pos
                                  (TmH
                                     (match quantified_positive_infos with
                                      | [(_, split_name, _, _, _, _, _, _, _, _, _, _)] -> split_name
                                      | _ -> assert false))),
                             PPfAp
                               (Hyp 1,
                                PPfAp (pfshift 0 1 split_to_target, Hyp 0)))
                        in
                        let not_closed_component =
                          PLam
                            (definition_component_prop,
                             PPfAp
                               (pfshift 0 1 not_split,
                                PPfAp
                                  (pfshift 0 1 component_to_split,
                                   Hyp 0)))
                        in
                        let pointwise =
                          TLam
                            (component_tp,
                             PLam (Imp (component_body, native_core_false), Hyp 0))
                        in
                        let exists_neg_component =
                          PPfAp
                            (PPfAp
                               (PTmAp
                                  (PTmAp
                                     (Known (native_core_not_forall_exists_hash component_tp),
                                      component_predicate),
                                   neg_component_predicate),
                                pointwise),
                             not_closed_component)
                        in
                        PPfAp
                          (PTmAp (exists_neg_component, native_core_false),
                           TLam
                             (component_tp,
                              PLam
                                (Imp (component_body, native_core_false),
                                 contradiction 0 instantiated_source_clause
                                   source_proof_instantiated)))))
                in
                Some proof
          | _ -> None
        in
        match choice_free_quantified_split () with
        | Some _ as proof -> proof
        | None ->
        let instantiated_source_clause = subst_clause substitution source_clause in
        let source_step_variables = native_core_step_variables cert source_id in
        let source_proof_instantiated =
          List.fold_left
            (fun proof (name, _) ->
               let witness =
                 match List.assoc_opt name substitution with
                 | Some witness -> witness
                 | None ->
                     error
                       (id ^ ": native preprocess proof-term avatar_split has no witness for source variable " ^ name)
               in
               PTmAp (proof, witness))
            (pfshift 0 1 source_proof)
            source_step_variables
        in
        let direct_result_literal_not_proofs =
          List.map
            (fun literal ->
               let literal_prop = native_core_literal_prop literal in
               let literal_to_target = result_literal_to_target literal in
               (literal,
                PLam
                  (literal_prop,
                   PPfAp
                     (Hyp 1,
                      PPfAp (pfshift 0 1 literal_to_target, Hyp 0)))))
            result
        in
        let source_literal_not_proofs =
          direct_result_literal_not_proofs @
          List.concat_map
            (fun (_, split_name, component_literals, component_witness,
                  definition_component_prop, component_to_split,
                  split_to_component, split_prop, result_split_literal) ->
               match result_split_literal with
               | Some (Pos (TmH _)) ->
                   let split_to_target =
                     result_literal_to_target (Pos (TmH split_name))
                   in
                   let not_split =
                     PLam
                       (split_prop,
                        PPfAp
                          (Hyp 1,
                           PPfAp (pfshift 0 1 split_to_target, Hyp 0)))
                   in
                   let not_closed_component =
                     PLam
                       (definition_component_prop,
                        PPfAp
                          (pfshift 0 1 not_split,
                           PPfAp (pfshift 0 1 component_to_split, Hyp 0)))
                   in
                   let instantiated_component_literals, not_instantiated_component =
                     match component_witness with
                     | None -> component_literals, not_closed_component
                     | Some (component_var, component_tp, component_body,
                             component_predicate, neg_component_predicate, witness) ->
                         let pointwise =
                           TLam
                             (component_tp,
                              PLam (Imp (component_body, native_core_false), Hyp 0))
                         in
                         let exists_neg_component =
                           PPfAp
                             (PPfAp
                                (PTmAp
                                   (PTmAp
                                      (Known (native_core_not_forall_exists_hash component_tp),
                                       component_predicate),
                                    neg_component_predicate),
                                 pointwise),
                              not_closed_component)
                         in
                         let not_instantiated_component =
                           PPfAp
                             (PTmAp
                                (Known (native_core_exists_choice_hash component_tp),
                                 neg_component_predicate),
                              exists_neg_component)
                         in
                         subst_clause [(component_var, witness)] component_literals,
                         not_instantiated_component
                   in
                   List.map
                     (fun instantiated_literal ->
                        let literal_prop = native_core_literal_prop instantiated_literal in
                        let literal_to_component =
                          native_core_prove_literal_to_clause
                            id
                            instantiated_component_literals
                            instantiated_literal
                            (Hyp 0)
                        in
                        (instantiated_literal,
                         PLam
                           (literal_prop,
                            PPfAp
                              (pfshift 0 1 not_instantiated_component,
                               literal_to_component))))
                     instantiated_component_literals
               | Some (Neg (TmH _)) ->
                   begin match component_witness, component_literals with
                   | None, [component_literal] ->
                       let complement_literal =
                         native_core_complement_literal component_literal
                       in
                       let complement_prop =
                         native_core_literal_prop complement_literal
                       in
                       let negative_split_literal = Neg (TmH split_name) in
                       let negative_split_prop =
                         native_core_literal_prop negative_split_literal
                       in
                       let negative_split_to_target =
                         result_literal_to_target negative_split_literal
                       in
                       let not_negative_split =
                         PLam
                           (negative_split_prop,
                            PPfAp
                              (Hyp 1,
                               PPfAp
                                 (pfshift 0 1 negative_split_to_target, Hyp 0)))
                       in
                       let proof =
                         PLam
                           (complement_prop,
                            let split_proof =
                              PPfAp
                                (PTmAp (Known native_core_dneg_hash, split_prop),
                                 pfshift 0 1 not_negative_split)
                            in
                            let component_proof =
                              PPfAp (pfshift 0 1 split_to_component, split_proof)
                            in
                            native_core_false_from_complement_proofs
                              component_literal
                              component_proof
                              complement_literal
                              (Hyp 0))
                       in
                       [(complement_literal, proof)]
                   | _ -> []
                   end
               | _ -> [])
            infos
        in
        let not_proof_for literal =
          match List.assoc_opt literal source_literal_not_proofs with
          | Some proof -> proof
          | None ->
              error
                (id ^ ": native preprocess proof-term avatar_split cannot refute instantiated source literal")
        in
        let rec contradiction depth clause proof =
          match clause with
          | [] -> proof
          | [literal] ->
              PPfAp (pfshift 0 depth (not_proof_for literal), proof)
          | literal :: rest ->
              let literal_prop = native_core_literal_prop literal in
              let rest_prop = native_core_clause_prop id rest in
              let left_branch =
                PLam
                  (literal_prop,
                   PPfAp (pfshift 0 (depth + 1) (not_proof_for literal), Hyp 0))
              in
              let right_branch =
                PLam
                  (rest_prop,
                   contradiction (depth + 1) rest (Hyp 0))
              in
              PPfAp
                (PPfAp (PTmAp (proof, native_core_false), left_branch),
                 right_branch)
        in
        Some
          (PPfAp
             (PTmAp (Known native_core_dneg_hash, target_prop),
              PLam
                (Imp (target_prop, native_core_false),
                 contradiction 0 instantiated_source_clause source_proof_instantiated)))
    end else None
  in
  let split_clause_by_component_definitions source_clause source_proof definitions =
    let replace_first source_literal target_literal clause =
      let rec replace = function
        | [] -> []
        | literal :: rest when literal = source_literal ->
            target_literal :: rest
        | literal :: rest -> literal :: replace rest
      in
      replace clause
    in
    let apply_definition (clause, proof) (split_name, component_literals, definition_component_prop, definition_proof) =
      match component_literals with
      | [component_literal] ->
          let split_literal = Pos (TmH split_name) in
          let negative_split_literal = Neg (TmH split_name) in
          if List.exists ((=) component_literal) clause
             && List.exists ((=) split_literal) result then
            let split_prop = native_core_literal_prop split_literal in
            let component_to_split =
              native_core_and_elim_right
                (Imp (split_prop, definition_component_prop))
                (Imp (definition_component_prop, split_prop))
                definition_proof
            in
            let next_clause =
              replace_first component_literal split_literal clause
            in
            let next_proof =
              native_core_prove_replace_literal_in_clause
                id clause proof component_literal split_literal next_clause
                component_to_split
            in
            (next_clause, next_proof)
          else
            let complement_literal =
              native_core_complement_literal component_literal
            in
            if List.exists ((=) complement_literal) clause
               && List.exists ((=) negative_split_literal) result then
              let split_prop = native_core_literal_prop split_literal in
              let split_to_component =
                native_core_and_elim_left
                  (Imp (split_prop, definition_component_prop))
                  (Imp (definition_component_prop, split_prop))
                  definition_proof
              in
              let not_component_to_not_split =
                match component_literal with
                | Pos _ ->
                    PLam
                      (native_core_literal_prop complement_literal,
                       PLam
                         (split_prop,
                          PPfAp
                            (Hyp 1,
                             PPfAp (split_to_component, Hyp 0))))
                | Neg atom ->
                    let atom_prop = native_core_literal_prop (Pos atom) in
                    PLam
                      (atom_prop,
                       PLam
                         (split_prop,
                          PPfAp
                            (PPfAp (split_to_component, Hyp 0),
                             Hyp 1)))
              in
              let next_clause =
                replace_first complement_literal negative_split_literal clause
              in
              let next_proof =
                native_core_prove_replace_literal_in_clause
                  id clause proof complement_literal negative_split_literal
                  next_clause not_component_to_not_split
              in
              (next_clause, next_proof)
            else
              (clause, proof)
      | _ ->
          (clause, proof)
    in
    let final_clause, final_proof =
      List.fold_left apply_definition (source_clause, source_proof) definitions
    in
    if same_clause_multiset final_clause result then
      Some (native_core_prove_clause_to_clause id final_clause result final_proof)
    else
      None
  in
  match parent_ids, split_literal with
  | [parent_id], _ when native_core_is_split_clause result ->
      let parent_clause, parent_proof = Hashtbl.find clause_table parent_id in
      if same_clause_multiset parent_clause result then
        parent_proof
      else
        let definitions =
          avatar_definitions
          |> Hashtbl.to_seq_values
          |> List.of_seq
        in
        begin match split_clause_by_component_definitions parent_clause parent_proof definitions with
        | Some proof -> proof
        | None ->
            error
              (id ^ ": native preprocess proof-term avatar_split single-parent result is not explained by split definitions")
        end
  | [source_id; definition_id], Some split_name ->
      let source_clause, source_proof = Hashtbl.find clause_table source_id in
      let def_split_name, component_literals, definition_component_prop, definition_proof =
        try Hashtbl.find avatar_definitions definition_id
        with Not_found ->
          error (id ^ ": native preprocess proof-term avatar_split references unknown avatar definition")
      in
      if split_name <> def_split_name then
        error (id ^ ": native preprocess proof-term avatar_split result split does not match definition parent");
      begin match
        split_clause_by_component_definitions
          source_clause
          source_proof
          [(def_split_name, component_literals, definition_component_prop,
            definition_proof)]
      with
      | Some proof -> proof
      | None ->
          if not (same_clause_multiset source_clause component_literals) then
            error (id ^ ": native preprocess proof-term avatar_split source clause does not match component definition");
          let split_prop = native_core_literal_prop (Pos (TmH split_name)) in
          let component_to_split =
            native_core_and_elim_right
              (Imp (split_prop, definition_component_prop))
              (Imp (definition_component_prop, split_prop))
              definition_proof
          in
          let component_proof =
            native_core_prove_clause_to_clause id source_clause component_literals source_proof
          in
          let split_proof = PPfAp (component_to_split, component_proof) in
          native_core_prove_literal_to_clause id result (Pos (TmH split_name)) split_proof
      end
  | source_id :: definition_ids, _ when native_core_is_split_clause result ->
      let source_clause, source_proof = Hashtbl.find clause_table source_id in
      begin match quantified_two_component_split source_id definition_ids with
      | Some proof -> proof
      | None ->
          let definitions =
            List.map
              (fun definition_id ->
                 try Hashtbl.find avatar_definitions definition_id
                 with Not_found ->
                   error (id ^ ": native preprocess proof-term avatar_split references unknown avatar definition"))
              definition_ids
          in
          begin match split_clause_by_component_definitions source_clause source_proof definitions with
          | Some proof -> proof
          | None ->
              error
                (id ^ ": native preprocess proof-term avatar_split component definitions do not produce result split clause")
          end
      end
  | _ ->
      error
        (id ^ ": native preprocess proof-term avatar_split supports only identity or source-plus-definition split clauses")

type native_core_avatar_component_direction =
  | AvatarComponentSplitToComponent
  | AvatarComponentComponentToSplit of literal

let native_core_avatar_component_proof cert variables id result avatar_definitions =
  let matches (split_name, component_literals, definition_component_prop, definition_proof) =
    let negative_split = Neg (TmH split_name) in
    let positive_split = Pos (TmH split_name) in
    if same_clause_multiset result (component_literals @ [negative_split]) then
      Some
        (split_name, component_literals, definition_component_prop, definition_proof,
         AvatarComponentSplitToComponent)
    else match component_literals with
    | [component_literal] ->
        let complement_literal =
          native_core_complement_literal component_literal
        in
        if same_clause_multiset result [complement_literal; positive_split] then
          Some
            (split_name, component_literals, definition_component_prop, definition_proof,
             AvatarComponentComponentToSplit component_literal)
        else
          None
    | _ ->
        None
  in
  let rec find_definition = function
    | [] -> None
    | item :: rest ->
        begin match matches item with
        | Some _ as found -> found
        | None -> find_definition rest
        end
  in
  let definitions =
    avatar_definitions
    |> Hashtbl.to_seq_values
    |> List.of_seq
  in
  match find_definition definitions with
  | None ->
      error (id ^ ": native preprocess proof-term avatar_component has no matching split definition")
  | Some (split_name, component_literals, definition_component_prop, definition_proof, direction) ->
      let result_step_variables = native_core_step_variables cert id in
      let instantiate_result_variables proof =
        List.fold_left
          (fun proof (name, _) -> PTmAp (proof, TmH name))
          proof
          result_step_variables
      in
      let split_prop = native_core_literal_prop (Pos (TmH split_name)) in
      let open_component_prop = native_core_clause_prop id component_literals in
      let target_prop = native_core_clause_prop id result in
      let split_to_component =
        native_core_and_elim_left
          (Imp (split_prop, definition_component_prop))
          (Imp (definition_component_prop, split_prop))
          definition_proof
      in
      let component_to_split =
        native_core_and_elim_right
          (Imp (split_prop, definition_component_prop))
          (Imp (definition_component_prop, split_prop))
          definition_proof
      in
      let body_proof =
        match direction with
        | AvatarComponentSplitToComponent ->
          let positive_branch =
            PLam
              (split_prop,
               let component_proof =
                 PPfAp (split_to_component, Hyp 0)
                 |> instantiate_result_variables
               in
               native_core_prove_clause_to_clause
                 id component_literals result component_proof)
          in
          let negative_branch =
            PLam
              (Imp (split_prop, native_core_false),
               native_core_prove_literal_to_clause
                 id result (Neg (TmH split_name)) (Hyp 0))
          in
          PPfAp
            (PPfAp
               (PTmAp (native_core_xm_proof split_prop, target_prop),
                positive_branch),
             negative_branch)
        | AvatarComponentComponentToSplit component_literal ->
          begin match component_literal with
          | Pos atom ->
              let positive_branch =
                PLam
                  (open_component_prop,
                   let split_proof = PPfAp (component_to_split, Hyp 0) in
                   native_core_prove_literal_to_clause
                     id result (Pos (TmH split_name)) split_proof)
              in
              let negative_branch =
                PLam
                  (Imp (open_component_prop, native_core_false),
                   native_core_prove_literal_to_clause
                     id result (Neg atom) (Hyp 0))
              in
              PPfAp
                (PPfAp
                   (PTmAp (native_core_xm_proof open_component_prop, target_prop),
                    positive_branch),
                 negative_branch)
          | Neg atom ->
              let atom_prop = native_core_literal_prop (Pos atom) in
              let positive_branch =
                PLam
                  (atom_prop,
                   native_core_prove_literal_to_clause
                     id result (Pos atom) (Hyp 0))
              in
              let negative_branch =
                PLam
                  (Imp (atom_prop, native_core_false),
                   let split_proof = PPfAp (component_to_split, Hyp 0) in
                   native_core_prove_literal_to_clause
                     id result (Pos (TmH split_name)) split_proof)
              in
              PPfAp
                (PPfAp
                   (PTmAp (native_core_xm_proof atom_prop, target_prop),
                    positive_branch),
                 negative_branch)
          end
      in
      let body_proof =
        native_core_close_pf (variables @ result_step_variables) body_proof
      in
      List.fold_right
        (fun (_, tp) proof -> TLam (tp, proof))
        result_step_variables
        body_proof

let native_core_split_literal_of_sat_lit id (var, positive) =
  if var <= 0 then
    error (id ^ ": native preprocess proof-term avatar_refutation SAT split variable must be positive");
  let atom = TmH ("split_" ^ string_of_int var) in
  if positive then Pos atom else Neg atom

let native_core_split_clause_of_sat_clause id clause =
  List.map (native_core_split_literal_of_sat_lit id) clause

let native_core_avatar_refutation_direct_proof id parent_ids clause_table =
  match parent_ids with
  | [left_id; right_id] ->
      let left_clause, left_proof = Hashtbl.find clause_table left_id in
      let right_clause, right_proof = Hashtbl.find clause_table right_id in
      begin match left_clause, right_clause with
      | [Neg left_atom], [Pos right_atom] when left_atom = right_atom ->
          PPfAp (left_proof, right_proof)
      | [Pos left_atom], [Neg right_atom] when left_atom = right_atom ->
          PPfAp (right_proof, left_proof)
      | _ ->
          error
            (id ^ ": native preprocess proof-term avatar_refutation supports only complementary split unit parents")
      end
  | _ ->
      error
        (id ^ ": native preprocess proof-term avatar_refutation supports only two SAT unit parents")

let native_core_avatar_refutation_sat_resolution_proof
    id parent_ids sat_clauses sat_proof clause_table =
  let source_pairs =
    try List.combine sat_clauses parent_ids
    with Invalid_argument _ ->
      error (id ^ ": native preprocess proof-term avatar_refutation SAT input count does not match parent count")
  in
  let used_parent_ids = ref [] in
  let consume_sat_input sid sat_clause =
    let rec find = function
      | [] ->
          error
            (id ^ ": native preprocess proof-term avatar_refutation SAT input has no matching certificate parent")
      | (candidate_sat_clause, parent_id) :: rest ->
          if normalize_sat_clause candidate_sat_clause = normalize_sat_clause sat_clause
             && not (List.mem parent_id !used_parent_ids) then begin
            let parent_clause, parent_proof = Hashtbl.find clause_table parent_id in
            let split_clause = native_core_split_clause_of_sat_clause id sat_clause in
            if not (same_clause_multiset parent_clause split_clause) then
              error
                (id ^ ": native preprocess proof-term avatar_refutation SAT input parent is not the matching split clause");
            used_parent_ids := parent_id :: !used_parent_ids;
            (sid, (split_clause, parent_proof))
          end else find rest
    in
    find source_pairs
  in
  let resolve_checked_step rup_id checked parent_ids result_clause =
    let parents =
      List.map
        (fun parent_id ->
          match List.assoc_opt parent_id checked with
          | Some parent -> parent
          | None ->
              error
                (id ^ ": native preprocess proof-term avatar_refutation SAT RUP parent is not an earlier proof step"))
        parent_ids
    in
    let rec factor_duplicates clause proof =
      let rec find_duplicate left_index = function
        | [] -> None
        | literal :: rest ->
            let rec find_right right_index = function
              | [] -> None
              | other :: others ->
                  if literal = other then Some (left_index, right_index)
                  else find_right (right_index + 1) others
            in
            begin match find_right (left_index + 1) rest with
            | Some _ as found -> found
            | None -> find_duplicate (left_index + 1) rest
            end
      in
      match find_duplicate 0 clause with
      | None -> (clause, proof)
      | Some (left_index, right_index) ->
          let next_clause =
            remove_at right_index clause
              (id ^ " avatar_refutation SAT duplicate literal")
          in
          let next_proof =
            native_core_factor
              (id ^ "_sat_" ^ string_of_int rup_id ^ "_factor")
              clause proof left_index right_index next_clause
          in
          factor_duplicates next_clause next_proof
    in
    let resolve_pair left_clause left_proof left_index right_clause right_proof right_index =
      let expected =
        remove_at left_index left_clause (id ^ " avatar_refutation SAT left pivot")
        @ remove_at right_index right_clause (id ^ " avatar_refutation SAT right pivot")
      in
      let proof =
        match left_clause, right_clause, expected, left_index, right_index with
        | [Pos left_atom], [Neg right_atom], [], 0, 0
          when native_core_same_atom left_atom right_atom ->
            PPfAp (right_proof, left_proof)
        | [Neg left_atom], [Pos right_atom], [], 0, 0
          when native_core_same_atom left_atom right_atom ->
            PPfAp (left_proof, right_proof)
        | _, [_], _, _, 0
            when List.length left_clause >= 1 ->
            native_core_resolve_clause_unit
              (id ^ "_sat_" ^ string_of_int rup_id)
              left_clause left_proof left_index right_clause right_proof right_index expected
        | [_], _, _, 0, _
            when List.length right_clause >= 1 ->
            native_core_resolve_clause_unit
              (id ^ "_sat_" ^ string_of_int rup_id)
              right_clause right_proof right_index left_clause left_proof left_index expected
        | _ ->
            native_core_resolve_clause_clause
              (id ^ "_sat_" ^ string_of_int rup_id)
              left_clause
              left_proof
              left_index
              right_clause
              right_proof
              right_index
              expected
      in
      factor_duplicates expected proof
    in
    let rec resolution_candidates left_clause left_proof left_index left_literal right_clause right_proof right_index = function
      | [] -> []
      | right_literal :: rest ->
          let rest_candidates =
            resolution_candidates
              left_clause left_proof left_index left_literal right_clause right_proof
              (right_index + 1)
              rest
          in
          if native_core_complement left_literal right_literal then
            resolve_pair
              left_clause left_proof left_index right_clause right_proof right_index
            :: rest_candidates
          else
            rest_candidates
    in
    let rec candidates_from_left left_clause left_proof right_clause right_proof left_index = function
      | [] -> []
      | left_literal :: rest ->
          resolution_candidates
            left_clause left_proof left_index left_literal right_clause right_proof
            0
            right_clause
          @ candidates_from_left
              left_clause left_proof right_clause right_proof (left_index + 1) rest
    in
    let resolve_candidates left right =
      let left_clause, left_proof = left in
      let right_clause, right_proof = right in
      candidates_from_left left_clause left_proof right_clause right_proof 0 left_clause
    in
    let rec derive_sequence current = function
      | [] ->
          if same_clause_multiset (fst current) result_clause then
            Some (snd current)
          else
            None
      | parent :: rest ->
          let rec try_candidates = function
            | [] -> None
            | candidate :: candidates ->
                begin match derive_sequence candidate rest with
                | Some _ as found -> found
                | None -> try_candidates candidates
                end
          in
          try_candidates (resolve_candidates current parent)
    in
    match parents with
    | [] ->
        error
          (id ^ ": native preprocess proof-term avatar_refutation SAT RUP step has no parents")
    | first :: rest ->
        begin match derive_sequence first rest with
        | Some proof -> proof
        | None ->
            let rec try_right_literal left_clause left_proof left_index left_literal right_clause right_proof right_index = function
      | [] -> None
      | right_literal :: rest ->
          if native_core_complement left_literal right_literal then begin
            let expected =
              remove_at left_index left_clause (id ^ " avatar_refutation SAT left pivot")
              @ remove_at right_index right_clause (id ^ " avatar_refutation SAT right pivot")
            in
            if same_clause_multiset expected result_clause then
              let proof =
                match left_clause, right_clause, result_clause, left_index, right_index with
                | [Pos left_atom], [Neg right_atom], [], 0, 0
                  when native_core_same_atom left_atom right_atom ->
                    PPfAp (right_proof, left_proof)
                | [Neg left_atom], [Pos right_atom], [], 0, 0
                  when native_core_same_atom left_atom right_atom ->
                    PPfAp (left_proof, right_proof)
                | _, [_], _, _, 0
                    when List.length left_clause >= 1
                         && List.length result_clause + 1 = List.length left_clause ->
                    native_core_resolve_clause_unit
                      (id ^ "_sat_" ^ string_of_int rup_id)
                      left_clause left_proof left_index right_clause right_proof right_index result_clause
                | [_], _, _, 0, _
                    when List.length right_clause >= 1
                         && List.length result_clause + 1 = List.length right_clause ->
                    native_core_resolve_clause_unit
                      (id ^ "_sat_" ^ string_of_int rup_id)
                      right_clause right_proof right_index left_clause left_proof left_index result_clause
                | _ ->
                    native_core_resolve_clause_clause
                      (id ^ "_sat_" ^ string_of_int rup_id)
                      left_clause
                      left_proof
                      left_index
                      right_clause
                      right_proof
                      right_index
                      result_clause
              in
              Some
                proof
            else None
          end else
            try_right_literal
              left_clause left_proof left_index left_literal right_clause right_proof
              (right_index + 1)
              rest
    in
    let try_left left_clause left_proof left_index left_literal right_clause right_proof =
      try_right_literal left_clause left_proof left_index left_literal right_clause right_proof 0 right_clause
    in
    let rec try_clause left_clause left_proof right_clause right_proof left_index = function
      | [] -> None
      | left_literal :: rest ->
          begin match
            try_left left_clause left_proof left_index left_literal right_clause right_proof
          with
          | Some proof -> Some proof
          | None -> try_clause left_clause left_proof right_clause right_proof (left_index + 1) rest
          end
    in
    let rec try_pairs = function
      | [] -> None
      | (left_clause, left_proof) :: rest ->
          let rec try_rights = function
            | [] -> try_pairs rest
            | (right_clause, right_proof) :: rights ->
                begin match
                  try_clause left_clause left_proof right_clause right_proof 0 left_clause
                with
                | Some proof -> Some proof
                | None -> try_rights rights
                end
          in
          try_rights rest
    in
    match try_pairs parents with
    | Some proof -> proof
    | None ->
        error
          (id ^ ": native preprocess proof-term avatar_refutation SAT RUP step is not a binary split-clause resolution")
        end
  in
  let rec build checked = function
    | [] -> checked
    | SatInput (sid, sat_clause) :: rest ->
        if List.mem_assoc sid checked then
          error (id ^ ": native preprocess proof-term avatar_refutation duplicate SAT proof step id");
        build (consume_sat_input sid sat_clause :: checked) rest
    | SatRup (sid, parent_step_ids, sat_clause) :: rest ->
        if List.mem_assoc sid checked then
          error (id ^ ": native preprocess proof-term avatar_refutation duplicate SAT proof step id");
        let result_clause = native_core_split_clause_of_sat_clause id sat_clause in
        let proof =
          resolve_checked_step sid checked parent_step_ids result_clause
        in
        build ((sid, (result_clause, proof)) :: checked) rest
  in
  match build [] sat_proof with
  | (_, ([], proof)) :: _ -> proof
  | _ ->
      error
        (id ^ ": native preprocess proof-term avatar_refutation SAT proof final step is not the empty clause")

let native_core_avatar_refutation_proof id parent_ids sat_clauses sat_proof result clause_table =
  if result <> [] then
    error (id ^ ": native preprocess proof-term avatar_refutation result is not empty");
  match sat_proof with
  | Some proof ->
      begin try
        native_core_avatar_refutation_sat_resolution_proof
          id parent_ids sat_clauses proof clause_table
      with Error _ ->
        native_core_avatar_refutation_direct_proof id parent_ids clause_table
      end
  | None ->
      native_core_avatar_refutation_direct_proof id parent_ids clause_table

let native_core_ennf_not_imp_to_and left_prop right_prop proof =
  let not_left_prop = Imp (left_prop, native_core_false) in
  let not_right_prop = Imp (right_prop, native_core_false) in
  let left_proof =
    PPfAp
      (PTmAp (Known native_core_dneg_hash, left_prop),
       PLam
         (not_left_prop,
          let imp_proof =
            PLam
              (left_prop,
               PTmAp (PPfAp (Hyp 1, Hyp 0), right_prop))
          in
          PPfAp (pfshift 0 1 proof, imp_proof)))
  in
  let not_right_proof =
    PLam
      (right_prop,
       let imp_proof = PLam (left_prop, Hyp 1) in
       PPfAp (pfshift 0 1 proof, imp_proof))
  in
  native_core_and_intro left_prop not_right_prop left_proof not_right_proof

let native_core_prop_ext_eq left right left_to_right right_to_left =
  PPfAp
    (PPfAp
       (PTmAp (PTmAp (Known native_core_prop_ext_hash, left), right),
        left_to_right),
     right_to_left)

let native_core_true_eq_from_proof source target proof =
  match native_core_equality_sides target with
  | Some (Prop, left, right) when left = source && right = native_core_true ->
      let atom = left in
      let atom_to_true = PLam (atom, native_core_true_proof) in
      let true_to_atom = PLam (native_core_true, pfshift 0 1 proof) in
      Some (native_core_prop_ext_eq atom native_core_true atom_to_true true_to_atom)
  | Some (Prop, left, right) when left = native_core_true && right = source ->
      let atom = right in
      let atom_to_true = PLam (atom, native_core_true_proof) in
      let true_to_atom = PLam (native_core_true, pfshift 0 1 proof) in
      Some (native_core_prop_ext_eq native_core_true atom true_to_atom atom_to_true)
  | _ -> None

let native_core_false_eq_from_proof source target proof =
  match native_core_equality_sides target with
  | Some (Prop, left, right) when left = source && right = native_core_false ->
      let atom = left in
      let atom_to_false = proof in
      let false_to_atom = PLam (native_core_false, PTmAp (Hyp 0, atom)) in
      Some (native_core_prop_ext_eq atom native_core_false atom_to_false false_to_atom)
  | Some (Prop, left, right) when left = native_core_false && right = source ->
      let atom = right in
      let atom_to_false = proof in
      let false_to_atom = PLam (native_core_false, PTmAp (Hyp 0, atom)) in
      Some (native_core_prop_ext_eq native_core_false atom false_to_atom atom_to_false)
  | _ -> None

let native_core_proof_from_true_eq source target proof =
  match native_core_equality_sides target with
  | Some (Prop, left, right) when left = source && right = native_core_true ->
      let atom = left in
      let atom_to_true = PLam (atom, native_core_true_proof) in
      let motive = Lam (Prop, Lam (Prop, Imp (DB 1, DB 0))) in
      Some (PPfAp (PPfAp (PTmAp (proof, motive), atom_to_true), native_core_true_proof))
  | Some (Prop, left, right) when left = native_core_true && right = source ->
      let atom = right in
      let atom_to_true = PLam (atom, native_core_true_proof) in
      let motive = Lam (Prop, Lam (Prop, Imp (DB 0, DB 1))) in
      Some (PPfAp (PPfAp (PTmAp (proof, motive), atom_to_true), native_core_true_proof))
  | _ -> None

let native_core_proof_from_false_eq source target proof =
  match native_core_equality_sides target with
  | Some (Prop, left, right) when left = source && right = native_core_false ->
      let atom = left in
      let motive = Lam (Prop, Lam (Prop, DB 1)) in
      Some
        (PLam
           (atom,
            PPfAp (PTmAp (pfshift 0 1 proof, motive), Hyp 0)))
  | Some (Prop, left, right) when left = native_core_false && right = source ->
      let atom = right in
      let motive = Lam (Prop, Lam (Prop, DB 0)) in
      Some
        (PLam
           (atom,
            PPfAp (PTmAp (pfshift 0 1 proof, motive), Hyp 0)))
  | _ -> None

let native_core_predicate_definition_proof id formula =
  let rec prove = function
    | All (tp, body) -> TLam (tp, prove body)
    | Ap (Ap (TmH "vampire_or", left), right) as disjunction ->
        let _, atom, body = predicate_definition_parts id disjunction in
        let is_negated_definiendum = function
          | Imp (candidate_atom, false_tm)
              when candidate_atom = atom && is_vampire_false false_tm -> true
          | _ -> false
        in
        let body_side, neg_side, body_is_left =
          if is_negated_definiendum left && right = body then
            (right, left, false)
          else if is_negated_definiendum right && left = body then
            (left, right, true)
          else
            error
              (id ^ ": native core predicate_definition proof expected a definitional disjunction")
        in
        let left_prop = native_core_formula_prop left in
        let right_prop = native_core_formula_prop right in
        let body_prop = native_core_formula_prop body_side in
        let neg_prop = native_core_formula_prop neg_side in
        let target_prop = native_core_formula_prop disjunction in
        let positive_branch =
          PLam
            (body_prop,
             if body_is_left then
               native_core_or_intro_left left_prop right_prop (Hyp 0)
             else
               native_core_or_intro_right left_prop right_prop (Hyp 0))
        in
        let atom_prop = native_core_formula_prop atom in
        let definiendum_prop =
          predicate_definition_definiendum_term atom
          |> native_core_formula_prop
        in
        let atom_to_body atom_proof =
          match native_core_proof_from_true_eq definiendum_prop atom atom_proof with
          | Some proof -> proof
          | None -> atom_proof
        in
        let neg_side_proof =
          PLam
            (atom_prop,
             PPfAp (Hyp 1, atom_to_body (Hyp 0)))
        in
        let negative_branch =
          PLam
            (Imp (body_prop, native_core_false),
             if body_is_left then
               native_core_or_intro_right left_prop right_prop neg_side_proof
             else
               native_core_or_intro_left left_prop right_prop neg_side_proof)
        in
        if native_core_normalize_bool_constants neg_prop
           <> Imp (atom_prop, native_core_false) then
          error
            (id ^ ": native core predicate_definition negative side is not atom -> false");
        PPfAp
          (PPfAp
             (PTmAp (native_core_xm_proof body_prop, target_prop),
              positive_branch),
           negative_branch)
    | _ ->
        error
          (id ^ ": native core predicate_definition proof supports only universal definitional disjunctions")
  in
  prove formula

let native_core_bind_result_step_variables variables result_step_variables body_proof =
  let body_proof =
    native_core_close_pf (variables @ result_step_variables) body_proof
  in
  List.fold_right
    (fun (_, tp) proof -> TLam (tp, proof))
    result_step_variables
    body_proof

let native_core_fool_formula_proof
    id symbol_table variables parent_step_variables result_step_variables source target proof =
  let source = native_core_close_tm (variables @ result_step_variables) source in
  let target = native_core_close_tm (variables @ result_step_variables) target in
  let result_variable_count = List.length result_step_variables in
  let db_for_result_variable name tp =
    let rec find index = function
      | [] -> None
      | (candidate_name, candidate_tp) :: rest ->
          if candidate_name = name && candidate_tp = tp then
            Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_result_variable tp =
    let rec find index = function
      | [] -> None
      | (_, candidate_tp) :: rest ->
          if candidate_tp = tp then Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_declared_variable tp =
    variables
    |> List.find_opt (fun (_, candidate_tp) -> candidate_tp = tp)
    |> Option.map (fun (name, _) -> TmH name)
  in
  let fallback_formula_witness tp =
    let env = variables @ result_step_variables in
    let rec first_some = function
      | [] -> None
      | candidate :: rest ->
          begin match candidate () with
          | Some _ as result -> result
          | None -> first_some rest
          end
    in
    let rec search tm =
      let self =
        match native_core_tm_type symbol_table env tm with
        | Some candidate_tp when candidate_tp = tp -> Some tm
        | _ -> None
      in
      match self with
      | Some _ -> self
      | None ->
          begin match tm with
          | TpAp (m, _) -> search m
          | Ap (m, n) -> first_some [ (fun () -> search m); (fun () -> search n) ]
          | Lam (_, body) -> search body
          | Imp (m, n) -> first_some [ (fun () -> search m); (fun () -> search n) ]
          | All (_, body) -> search body
          | DB _ | TmH _ | Prim _ -> None
          end
    in
    first_some [ (fun () -> search source); (fun () -> search target) ]
  in
  let fallback_variable tp =
    match fallback_result_variable tp with
    | Some tm -> Some tm
    | None ->
        begin match fallback_declared_variable tp with
        | Some _ as result -> result
        | None -> fallback_formula_witness tp
        end
  in
  let parent_proof =
    List.fold_left
      (fun proof (name, tp) ->
         let arg =
           match db_for_result_variable name tp with
           | Some tm -> tm
           | None ->
               begin match fallback_variable tp with
               | Some tm -> tm
               | None ->
                   error
                     (id ^ ": native preprocess proof-term fool_formula cannot instantiate dropped parent variable " ^ name)
               end
         in
         PTmAp (proof, arg))
      (pftmshift 0 result_variable_count proof)
      parent_step_variables
  in
  let initial_context = List.rev (List.map snd result_step_variables) in
  let witness context tp =
    let rec find index = function
      | [] -> None
      | candidate_tp :: rest ->
          if candidate_tp = tp then Some (DB index)
          else find (index + 1) rest
    in
    match find 0 context with
    | Some tm -> tm
    | None ->
        begin match fallback_declared_variable tp with
        | Some tm -> tm
        | None ->
            begin match fallback_formula_witness tp with
            | Some tm -> tm
            | None ->
                error
                  (id ^ ": native preprocess proof-term fool_formula cannot instantiate redundant universal binder")
            end
        end
  in
  let rec convert context direction source target proof =
    if source = target then proof
    else
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body)
          when source_tp = target_tp ->
          TLam
            (source_tp,
             convert
               (source_tp :: context)
               direction
               source_body
               target_body
               (PTmAp (pftmshift 0 1 proof, DB 0)))
      | All (source_tp, source_body), _ ->
          begin match direction with
          | `Forward ->
              let arg = witness context source_tp in
              convert
                context
                direction
                (tmsubst source_body 0 arg)
                target
                (PTmAp (proof, arg))
          | `Backward ->
              error
                (id ^ ": native preprocess proof-term fool_formula cannot synthesize a dropped source universal binder")
          end
      | _, All (target_tp, target_body) ->
          begin match direction with
          | `Forward ->
              TLam
                (target_tp,
                 convert
                   (target_tp :: context)
                   direction
                   (tmshift 0 1 source)
                   target_body
                   (pftmshift 0 1 proof))
          | `Backward ->
              let arg = witness context target_tp in
              convert
                context
                direction
                source
                (tmsubst target_body 0 arg)
                (PTmAp (proof, arg))
          end
      | Imp (source_left, source_right), Imp (target_left, target_right) ->
          begin match direction with
          | `Forward ->
              let source_left_proof =
                convert context `Backward source_left target_left (Hyp 0)
              in
              let source_right_proof =
                PPfAp (pfshift 0 1 proof, source_left_proof)
              in
              PLam
                (native_core_formula_prop target_left,
                 convert context `Forward source_right target_right source_right_proof)
          | `Backward ->
              let target_left_proof =
                convert context `Forward source_left target_left (Hyp 0)
              in
              let target_right_proof =
                PPfAp (pfshift 0 1 proof, target_left_proof)
              in
              PLam
                (native_core_formula_prop source_left,
                 convert context `Backward source_right target_right target_right_proof)
          end
      | _ ->
          begin match direction with
          | `Forward ->
              begin match native_core_true_eq_from_proof source target proof with
              | Some proof -> proof
              | None ->
                  begin match native_core_false_eq_from_proof source target proof with
                  | Some proof -> proof
                  | None ->
                      error
                        (id ^ ": native preprocess proof-term fool_formula cannot lift atom")
                  end
              end
          | `Backward ->
              begin match native_core_proof_from_true_eq source target proof with
              | Some proof -> proof
              | None ->
                  begin match native_core_proof_from_false_eq source target proof with
                  | Some proof -> proof
                  | None ->
                      error
                        (id ^ ": native preprocess proof-term fool_formula cannot lower atom")
                  end
              end
          end
  in
  let body_proof =
    convert initial_context `Forward source target parent_proof
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_ennf_formula_proof id variables step_variables source target proof =
  let source = native_core_close_tm (variables @ step_variables) source in
  let target = native_core_close_tm (variables @ step_variables) target in
  let native_core_exists_body source_tp = function
    | Ap (TmH "vampire_exists_prop", Lam (target_tp, target_body))
        when source_tp = target_tp ->
        Some target_body
    | Ap (TmH "vampire_exists_prop", Ap (TmH "vLAM", target_body)) ->
        Some (vampire_db_index_tm target_body)
    | _ -> None
  in
  let rec convert source target proof =
    if native_core_formula_prop source = native_core_formula_prop target then proof
    else
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body)
          when source_tp = target_tp ->
          TLam
            (source_tp,
             convert
               source_body
               target_body
               (PTmAp (pftmshift 0 1 proof, DB 0)))
      | Imp (Imp (source_left, source_right), source_false),
        Ap (Ap (TmH "vampire_and", target_left), target_right)
          when source_false = native_core_false ->
          let source_left_prop =
            native_core_formula_prop source_left
            |> native_core_normalize_bool_constants
          in
          let source_right_prop =
            native_core_formula_prop source_right
            |> native_core_normalize_bool_constants
          in
          let target_left_prop =
            native_core_formula_prop target_left
            |> native_core_normalize_bool_constants
          in
          let target_right_prop =
            native_core_formula_prop target_right
            |> native_core_normalize_bool_constants
          in
          let source_left_proof =
            PPfAp
              (PTmAp (Known native_core_dneg_hash, source_left_prop),
               PLam
                 (Imp (source_left_prop, native_core_false),
                  let imp_proof =
                    PLam
                      (source_left_prop,
                       PTmAp (PPfAp (Hyp 1, Hyp 0), source_right_prop))
                  in
                  PPfAp (pfshift 0 1 proof, imp_proof)))
          in
          let left_proof =
            if target_left_prop = source_left_prop then source_left_proof
            else convert source_left target_left source_left_proof
          in
          let not_right_proof =
            PLam
              (source_right_prop,
               let imp_proof = PLam (source_left_prop, Hyp 1) in
               PPfAp (pfshift 0 1 proof, imp_proof))
          in
          let right_proof =
            if target_right_prop = Imp (source_right_prop, native_core_false) then
              not_right_proof
            else
              convert
                (Imp (source_right, native_core_false))
                target_right
                not_right_proof
          in
          native_core_and_intro
            target_left_prop target_right_prop left_proof right_proof
      | Imp (All (source_tp, source_body), source_false), target
          when source_false = native_core_false ->
          begin match native_core_exists_body source_tp target with
          | None ->
              error
                (id ^ ": native preprocess proof-term ennf_formula expected negated universal to existential")
          | Some target_body ->
          let source_body_prop =
            native_core_formula_prop source_body
            |> native_core_normalize_bool_constants
          in
          let target_body_prop =
            native_core_formula_prop target_body
            |> native_core_normalize_bool_constants
          in
          let source_predicate = Lam (source_tp, source_body_prop) in
          let target_predicate = Lam (source_tp, target_body_prop) in
          let pointwise_proof =
            TLam
              (source_tp,
               PLam
                 (Imp (source_body_prop, native_core_false),
                  convert
                    (Imp (source_body, native_core_false))
                    target_body
                    (Hyp 0)))
          in
          PPfAp
            (PPfAp
               (PTmAp
                  (PTmAp
                     (Known (native_core_not_forall_exists_hash source_tp),
                      source_predicate),
                   target_predicate),
                pointwise_proof),
             proof)
          end
      | Imp (source_left, source_right),
        Ap (Ap (TmH "vampire_or", target_left), target_right) ->
          let source_left_prop = native_core_formula_prop source_left in
          let target_left_prop = native_core_formula_prop target_left in
          let target_right_prop = native_core_formula_prop target_right in
          let source_left_neg_prop = Imp (source_left_prop, native_core_false) in
          let target_prop = native_core_or target_left_prop target_right_prop in
          let right_case =
            let source_right_proof =
              PPfAp (pfshift 0 1 proof, Hyp 0)
            in
            let target_right_proof =
              convert source_right target_right source_right_proof
            in
            PLam
              (source_left_prop,
               native_core_or_intro_right
                 target_left_prop
                 target_right_prop
                 target_right_proof)
          in
          let left_case =
            PLam
              (source_left_neg_prop,
               let target_left_proof =
                 if target_left_prop = source_left_neg_prop then Hyp 0
                 else
                   convert
                     (Imp (source_left, native_core_false))
                     target_left
                     (Hyp 0)
               in
               native_core_or_intro_left
                 target_left_prop
                 target_right_prop
                 target_left_proof)
          in
          PPfAp
            (PPfAp
               (PTmAp (native_core_xm_proof source_left_prop, target_prop),
                right_case),
             left_case)
      | _ ->
          error
            (id ^ ": native preprocess proof-term ennf_formula supports only universal implication-to-or transformations")
  in
  let rec introduce variables proof =
    match variables with
    | [] -> convert source target proof
    | (_, tp) :: rest ->
        TLam
          (tp,
           introduce rest (PTmAp (pftmshift 0 1 proof, DB 0)))
  in
  introduce step_variables proof

let native_core_rectify_formula_proof
    id parent_step_variables result_step_variables proof =
  let rec introduce pending_parent_variables result_variables proof =
    match pending_parent_variables, result_variables with
    | [], [] -> proof
    | [], (_, result_tp) :: result_rest ->
        TLam
          (result_tp,
           introduce [] result_rest (pftmshift 0 1 proof))
    | (parent_name, parent_tp) :: parent_rest,
      (result_name, result_tp) :: result_rest
        when parent_name = result_name && parent_tp = result_tp ->
        TLam
          (result_tp,
           introduce
             parent_rest
             result_rest
             (PTmAp (pftmshift 0 1 proof, DB 0)))
    | _, (_, result_tp) :: result_rest ->
        TLam
          (result_tp,
           introduce pending_parent_variables result_rest (pftmshift 0 1 proof))
    | _ :: _, [] ->
        error
          (id ^ ": native preprocess proof-term rectify_formula could not match every parent variable in the result variables")
  in
  introduce parent_step_variables result_step_variables proof

let native_core_cnf_formula_clause_proof
    ?(shift_parent_proof=true)
    id variables parent_step_variables result_step_variables parent_formula result proof =
  let close_literal = function
    | Pos atom -> Pos (native_core_close_tm (variables @ result_step_variables) atom)
    | Neg atom -> Neg (native_core_close_tm (variables @ result_step_variables) atom)
  in
  let result = List.map close_literal result in
  let result_prop = native_core_clause_prop id result in
  let result_variable_count = List.length result_step_variables in
  let db_for_result_variable name tp =
    let rec find index = function
      | [] -> None
      | (candidate_name, candidate_tp) :: rest ->
          if candidate_name = name && candidate_tp = tp then
            Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_result_variable tp =
    let rec find index = function
      | [] -> None
      | (_, candidate_tp) :: rest ->
          if candidate_tp = tp then Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_declared_variable tp =
    variables
    |> List.find_opt (fun (_, candidate_tp) -> candidate_tp = tp)
    |> Option.map (fun (name, _) -> TmH name)
  in
  let fallback_variable tp =
    match fallback_result_variable tp with
    | Some tm -> Some tm
    | None ->
        begin match fallback_declared_variable tp with
        | Some tm -> Some tm
        | None -> native_core_default_witness tp
        end
  in
  let parent_variable_arg name tp =
    match db_for_result_variable name tp with
    | Some tm -> tm
    | None ->
        begin match fallback_variable tp with
        | Some tm -> tm
        | None ->
            error
              (id ^ ": native preprocess proof-term cnf_formula_clause cannot instantiate parent variable " ^ name)
        end
  in
  let parent_variable_args =
    List.map
      (fun (name, tp) -> (name, parent_variable_arg name tp))
      parent_step_variables
  in
  let parent_formula =
    native_core_close_tm (variables @ result_step_variables) parent_formula
    |> subst_tm parent_variable_args
  in
  let parent_proof =
    List.fold_left
      (fun proof (name, tp) ->
         let arg = List.assoc name parent_variable_args in
         PTmAp (proof, arg))
      (if shift_parent_proof then pftmshift 0 result_variable_count proof else proof)
      parent_step_variables
  in
  let quantifier_candidates pending tp =
    let rec collect acc prefix = function
      | [] -> List.rev acc
      | ((name, candidate_tp) as item) :: rest ->
          let acc =
            if candidate_tp = tp then
              match db_for_result_variable name tp with
              | Some tm -> (tm, List.rev_append prefix rest) :: acc
              | None -> acc
            else acc
          in
          collect acc (item :: prefix) rest
    in
    let candidates = collect [] [] pending in
    if candidates <> [] then candidates
    else
      match fallback_variable tp with
      | Some tm -> [tm, pending]
      | None ->
          error
            (id ^ ": native preprocess proof-term cnf_formula_clause cannot instantiate formula universal binder")
  in
  let rec eliminate pending formula proof =
    let formula_prop = native_core_formula_prop formula in
    if formula_prop = result_prop then proof
    else
      match formula with
      | All (_, body) ->
          let tp =
            match formula with
            | All (tp, _) -> tp
            | _ -> assert false
          in
          let rec try_candidates = function
            | [] ->
                error
                  (id ^ ": native preprocess proof-term cnf_formula_clause cannot instantiate formula universal binder to project target clause")
            | (arg, pending) :: rest ->
                try
                  eliminate
                    pending
                    (tmsubst body 0 arg)
                    (PTmAp (proof, arg))
                with Error _ -> try_candidates rest
          in
          try_candidates (quantifier_candidates pending tp)
      | Ap (Ap (TmH "vampire_or", left), right) ->
          let left_prop = native_core_formula_prop left in
          let right_prop = native_core_formula_prop right in
          let left_branch =
            PLam (left_prop, eliminate pending left (Hyp 0))
          in
          let right_branch =
            PLam (right_prop, eliminate pending right (Hyp 0))
          in
          PPfAp (PPfAp (PTmAp (proof, result_prop), left_branch), right_branch)
      | Ap (Ap (TmH "vampire_and", left), right) ->
          let left_prop = native_core_formula_prop left in
          let right_prop = native_core_formula_prop right in
          let left_proof =
            PPfAp
              (PTmAp (proof, left_prop),
               PLam (left_prop, PLam (right_prop, Hyp 1)))
          in
          let right_proof =
            PPfAp
              (PTmAp (proof, right_prop),
               PLam (left_prop, PLam (right_prop, Hyp 0)))
          in
          begin
            try eliminate pending left left_proof
            with Error _ -> eliminate pending right right_proof
          end
      | _ ->
          let literal = literal_of_formula_tm formula in
          if List.exists ((=) literal) result then
            native_core_prove_literal_to_clause id result literal proof
          else begin
            if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
              prerr_endline
                (id ^ ": cnf_formula_clause branch formula: " ^ tm_to_str formula);
              prerr_endline
                (id ^ ": cnf_formula_clause branch literal formula: "
                 ^ tm_to_str (formula_tm_of_literal literal));
              List.iteri
                (fun index target ->
                   prerr_endline
                     (id ^ ": cnf_formula_clause target literal " ^ string_of_int index
                      ^ ": " ^ tm_to_str (formula_tm_of_literal target)))
                result
            end;
            error
              (id ^ ": native preprocess proof-term cnf_formula_clause cannot project parent formula branch to result clause")
          end
  in
  let body_proof =
    eliminate parent_step_variables parent_formula parent_proof
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_fool_exhaustiveness_proof cert id result =
  let step_variables = native_core_step_variables cert id in
  let close_literal = function
    | Pos atom -> Pos (native_core_close_tm step_variables atom)
    | Neg atom -> Neg (native_core_close_tm step_variables atom)
  in
  let result = List.map close_literal result in
  let eq_atom = function
    | Pos atom -> native_core_equality_sides atom
    | Neg _ -> None
  in
  let equality_case lit =
    match eq_atom lit with
    | Some (Prop, left, right)
        when native_core_normalize_bool_constants left = native_core_true ->
        Some (`TrueEq, `ConstLeft, right)
    | Some (Prop, left, right)
        when native_core_normalize_bool_constants right = native_core_true ->
        Some (`TrueEq, `ConstRight, left)
    | Some (Prop, left, right)
        when native_core_normalize_bool_constants left = native_core_false ->
        Some (`FalseEq, `ConstLeft, right)
    | Some (Prop, left, right)
        when native_core_normalize_bool_constants right = native_core_false ->
        Some (`FalseEq, `ConstRight, left)
    | _ -> None
  in
  let true_equality_proof side p =
    match side with
    | `ConstLeft ->
        native_core_prop_ext_eq
          native_core_true
          p
          (PLam (native_core_true, Hyp 1))
          (PLam (p, native_core_true_proof))
    | `ConstRight ->
        native_core_prop_ext_eq
          p
          native_core_true
          (PLam (p, native_core_true_proof))
          (PLam (native_core_true, Hyp 1))
  in
  let false_equality_proof side p =
    match side with
    | `ConstLeft ->
        native_core_prop_ext_eq
          native_core_false
          p
          (PLam (native_core_false, PTmAp (Hyp 0, p)))
          (PLam (p, PPfAp (Hyp 1, Hyp 0)))
    | `ConstRight ->
        native_core_prop_ext_eq
          p
          native_core_false
          (PLam (p, PPfAp (Hyp 1, Hyp 0)))
          (PLam (native_core_false, PTmAp (Hyp 0, p)))
  in
  match result with
  | [left_literal; right_literal] ->
      let left_prop = native_core_literal_prop left_literal in
      let right_prop = native_core_literal_prop right_literal in
      let target_prop = native_core_or left_prop right_prop in
      begin match equality_case left_literal, equality_case right_literal with
      | Some (`TrueEq, true_side, true_tm), Some (`FalseEq, false_side, false_tm)
      | Some (`FalseEq, false_side, false_tm), Some (`TrueEq, true_side, true_tm)
          when true_tm = false_tm ->
          let p = DB 0 in
          let positive_case =
            PLam
              (p,
               let true_eq = true_equality_proof true_side p in
               match equality_case left_literal with
               | Some (`TrueEq, _, _) ->
                   native_core_or_intro_left left_prop right_prop true_eq
               | _ ->
                   native_core_or_intro_right left_prop right_prop true_eq)
          in
          let negative_case =
            PLam
              (Imp (p, native_core_false),
               let false_eq = false_equality_proof false_side p in
               match equality_case left_literal with
               | Some (`FalseEq, _, _) ->
                   native_core_or_intro_left left_prop right_prop false_eq
               | _ ->
                   native_core_or_intro_right left_prop right_prop false_eq)
          in
          List.fold_right
            (fun (_, tp) proof -> TLam (tp, proof))
            step_variables
            (PPfAp
               (PPfAp
                  (PTmAp (native_core_xm_proof p, target_prop),
                   positive_case),
                negative_case))
      | _ ->
          error
            (id ^ ": native preprocess proof-term fool_exhaustiveness expected true/false equality literals")
      end
  | _ ->
      error
        (id ^ ": native preprocess proof-term fool_exhaustiveness expected two literals")

let native_core_fool_bool_proof id variables parent_formula parent_proof result =
  let close = native_core_close_tm variables in
  match parent_formula, result with
  | atom, Pos target_atom ->
      let atom = close atom in
      let target_atom = close target_atom in
      begin match native_core_true_eq_from_proof atom target_atom parent_proof with
      | Some proof -> proof
      | None -> error (id ^ ": native preprocess proof-term fool_bool cannot lift positive atom")
      end
  | Imp (atom, false_tm), Neg target_atom
      when native_core_normalize_bool_constants false_tm = native_core_false ->
      let atom = close atom in
      let target_atom = close target_atom in
      begin match native_core_proof_from_true_eq atom target_atom (Hyp 0) with
      | Some atom_proof ->
          PLam
            (native_core_expand_eq_atom target_atom,
             PPfAp (pfshift 0 1 parent_proof, atom_proof))
      | None -> error (id ^ ": native preprocess proof-term fool_bool cannot lower negative atom")
      end
  | _ ->
      error (id ^ ": native preprocess proof-term fool_bool parent/result shape is unsupported")

let native_core_inequality_name_intro_proof cert symbol_table id variables result =
  check_inequality_name_intro id result;
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let closed_literal =
    match result with
    | [Pos atom] -> Pos (close_tm atom)
    | [_] ->
        error (id ^ ": native preprocess proof-term inequality_name_intro literal is not positive")
    | _ ->
        error (id ^ ": native preprocess proof-term inequality_name_intro expects a singleton clause")
  in
  let atom, named =
    match closed_literal with
    | Pos atom ->
        begin match native_core_equality_sides atom with
        | Some (Prop, left, right)
            when left = native_core_false ->
            atom, right
        | Some (Prop, left, right)
            when right = native_core_false ->
            atom, left
        | Some _ ->
            error
              (id ^ ": native preprocess proof-term inequality_name_intro literal is not an equality to false")
        | None ->
            error
              (id ^ ": native preprocess proof-term inequality_name_intro literal is not typed Megalodon equality")
        end
    | Neg _ -> assert false
  in
  let split_argument_type_and_term =
    match native_core_flatten_value_application named with
    | TmH head, (_ :: _ as args) ->
        let introduced = native_core_ident head in
        let symbol_tp = native_core_symbol_type symbol_table introduced in
        let arg_tps, result_tp = native_core_arrow_parts symbol_tp in
        if result_tp <> Prop then
          error (id ^ ": native preprocess proof-term inequality_name_intro split name does not return prop");
        if List.length args > List.length arg_tps then
          error (id ^ ": native preprocess proof-term inequality_name_intro split name has too many arguments");
        begin match List.rev args, List.rev (native_core_take_prefix (List.length args) arg_tps) with
        | split_arg :: _, split_tp :: _ -> split_tp, split_arg
        | _ -> assert false
        end
    | _ ->
        error (id ^ ": native preprocess proof-term inequality_name_intro literal is not a split-name application")
  in
  let split_tp, split_arg = split_argument_type_and_term in
  let split_refl =
    match
      native_core_reflexive_eq_proof
        (native_core_eq_atom split_tp split_arg split_arg)
    with
    | Some proof -> proof
    | None ->
        error (id ^ ": native preprocess proof-term inequality_name_intro cannot build split reflexivity proof")
  in
  let not_named =
    PLam
      (named,
       PPfAp (Hyp 0, split_refl))
  in
  let proof =
    match native_core_equality_sides atom with
    | Some (Prop, left, right) when left = native_core_false && right = named ->
        native_core_prop_ext_eq
          native_core_false
          named
          (PLam (native_core_false, PTmAp (Hyp 0, named)))
          not_named
    | Some (Prop, left, right) when left = named && right = native_core_false ->
        native_core_prop_ext_eq
          named
          native_core_false
          not_named
          (PLam (native_core_false, PTmAp (Hyp 0, named)))
    | _ -> assert false
  in
  let result_clause = [closed_literal] in
  let body_proof =
    native_core_prove_literal_to_clause id result_clause closed_literal proof
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_bool_name_literal value = function
  | Pos atom ->
      begin match native_core_equality_sides atom with
      | Some (Prop, left, named)
          when (value && left = native_core_true)
               || ((not value) && left = native_core_false) ->
          Some named
      | Some (Prop, named, right)
          when (value && right = native_core_true)
               || ((not value) && right = native_core_false) ->
          Some named
      | _ -> None
      end
  | Neg _ -> None

let native_core_swapped_eq_literal = function
  | Pos atom ->
      begin match megalodon_eq_poly_sides atom with
      | Some (tp, left, right) ->
          Some (Pos (Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), right), left)))
      | None -> None
      end
  | Neg atom ->
      begin match megalodon_eq_poly_sides atom with
      | Some (tp, left, right) ->
          Some (Neg (Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), right), left)))
      | None -> None
      end

let native_core_positive_eq_symmetry tp left right proof =
  let predicate_sort = Ar (tp, Ar (tp, Prop)) in
  let premise =
    Ap (Ap (DB 0, tmshift 0 1 right), tmshift 0 1 left)
  in
  let motive =
    Lam (tp, Lam (tp, Ap (Ap (DB 2, DB 0), DB 1)))
  in
  TLam
    (predicate_sort,
     PLam
       (premise,
        PPfAp
          (PTmAp (pfshift 0 1 (pftmshift 0 1 proof), motive),
           Hyp 0)))

let native_core_eq_symmetry_proof id literal proof =
  match literal with
  | Pos atom ->
      begin match megalodon_eq_poly_sides atom with
      | Some (tp, left, right) ->
          native_core_positive_eq_symmetry tp left right proof
      | None ->
          error (id ^ ": native core proof-term equality-symmetry requires typed Megalodon equality")
      end
  | Neg atom ->
      begin match megalodon_eq_poly_sides atom with
      | Some (tp, left, right) ->
          let swapped_atom =
            Ap (Ap (TpAp (TmH megalodon_eq_poly_hash, tp), right), left)
          in
          let source_eq =
            native_core_positive_eq_symmetry tp right left (Hyp 0)
          in
          PLam
            (native_core_expand_eq_atom swapped_atom,
             PPfAp (pfshift 0 1 proof, source_eq))
      | None ->
          error (id ^ ": native core proof-term equality-symmetry requires typed Megalodon equality")
      end

let native_core_formula_orientation_proof
    ?(normalize_formula_for_match=(fun _ tm -> tm))
    ?(definition_symbols=[])
    ?(parent_variable_map=[])
    id variables parent_step_variables result_step_variables source target proof =
  let is_definition_term tm =
    match head_symbol tm with
    | Some symbol -> List.mem (native_core_ident symbol) definition_symbols
    | None -> false
  in
  let result_variable_count = List.length result_step_variables in
  let db_for_result_variable name tp =
    let rec find index = function
      | [] -> None
      | (candidate_name, candidate_tp) :: rest ->
          if candidate_name = name && candidate_tp = tp then
            Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_result_variable tp =
    let rec find index = function
      | [] -> None
      | (_, candidate_tp) :: rest ->
          if candidate_tp = tp then Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_declared_variable tp =
    variables
    |> List.find_opt (fun (_, candidate_tp) -> candidate_tp = tp)
    |> Option.map (fun (name, _) -> TmH name)
  in
  let fallback_variable tp =
    match fallback_result_variable tp with
    | Some tm -> Some tm
    | None ->
        begin match fallback_declared_variable tp with
        | Some tm -> Some tm
        | None -> native_core_default_witness tp
        end
  in
  let mapped_parent_variable name tp =
    match List.assoc_opt name parent_variable_map with
    | None -> None
    | Some (TmH target_name) -> db_for_result_variable target_name tp
    | Some tm -> Some (native_core_close_tm (variables @ result_step_variables) tm)
  in
  let parent_proof =
    List.fold_left
      (fun proof (name, tp) ->
         let arg =
           match mapped_parent_variable name tp with
           | Some tm -> tm
           | None ->
           match db_for_result_variable name tp with
           | Some tm -> tm
           | None ->
               begin match fallback_variable tp with
               | Some tm -> tm
               | None ->
                   error
                     (id ^ ": native preprocess proof-term formula orientation cannot instantiate dropped parent variable " ^ name)
               end
         in
         PTmAp (proof, arg))
      (pftmshift 0 result_variable_count proof)
      parent_step_variables
  in
  let source = native_core_close_tm (variables @ result_step_variables) source in
  let target = native_core_close_tm (variables @ result_step_variables) target in
  let short_tm tm =
    let text = tm_to_str tm in
    if String.length text <= 300 then text
    else String.sub text 0 300 ^ "..."
  in
  let rec first_tm_difference path left right =
    if left = right then None
    else
      match left, right with
      | TpAp (left_body, left_tp), TpAp (right_body, right_tp) ->
          if left_tp <> right_tp then
            Some (path ^ ".type", left, right)
          else
            first_tm_difference (path ^ ".tpap") left_body right_body
      | Ap (left_fun, left_arg), Ap (right_fun, right_arg) ->
          begin match first_tm_difference (path ^ ".fun") left_fun right_fun with
          | Some _ as found -> found
          | None -> first_tm_difference (path ^ ".arg") left_arg right_arg
          end
      | Lam (left_tp, left_body), Lam (right_tp, right_body)
      | All (left_tp, left_body), All (right_tp, right_body) ->
          if left_tp <> right_tp then
            Some (path ^ ".binder-type", left, right)
          else
            first_tm_difference (path ^ ".body") left_body right_body
      | Imp (left_a, left_b), Imp (right_a, right_b) ->
          begin match first_tm_difference (path ^ ".left") left_a right_a with
          | Some _ as found -> found
          | None -> first_tm_difference (path ^ ".right") left_b right_b
          end
      | _ -> Some (path, left, right)
  in
  let debug_formula_orientation_difference source_for_match target_for_match =
    match first_tm_difference "root" source_for_match target_for_match with
    | Some (path, left, right) ->
        prerr_endline ("native core formula orientation first diff path: " ^ path);
        prerr_endline ("native core formula orientation first diff source: " ^ short_tm left);
        prerr_endline ("native core formula orientation first diff target: " ^ short_tm right)
    | None -> ()
  in
  let rec convert local_depth direction source target proof =
    let normalize_for_match tm =
      normalize_formula_for_match (result_variable_count + local_depth) tm
    in
    let source_prop =
      normalize_for_match source
      |> native_core_formula_prop
      |> native_core_normalize_bool_constants
    in
    let target_prop =
      normalize_for_match target
      |> native_core_formula_prop
      |> native_core_normalize_bool_constants
    in
    if source_prop = target_prop then proof
    else begin
      let prop_eq_true_atom tm =
        match native_core_equality_sides tm with
        | Some (Prop, left, right) when left = native_core_true -> Some right
        | Some (Prop, left, right) when right = native_core_true -> Some left
        | _ -> None
      in
      let same_formula_prop left right =
        let prop tm =
          native_core_formula_prop tm
          |> native_core_normalize_bool_constants
        in
        prop left = prop right
      in
      let source_for_match =
        normalize_for_match source
        |> native_core_normalize_bool_constants
      in
      let target_for_match =
        normalize_for_match target
        |> native_core_normalize_bool_constants
      in
      match direction, prop_eq_true_atom source_for_match, prop_eq_true_atom target_for_match with
      | `Forward, Some source_atom, Some target_atom ->
          begin match native_core_proof_from_true_eq source_atom source_for_match proof with
          | Some source_atom_proof ->
              let target_atom_proof =
                convert local_depth `Forward source_atom target_atom source_atom_proof
              in
              begin match native_core_true_eq_from_proof target_atom target_for_match target_atom_proof with
              | Some proof -> proof
              | None -> assert false
              end
          | None -> assert false
          end
      | `Backward, Some source_atom, Some target_atom ->
          begin match native_core_proof_from_true_eq target_atom target_for_match proof with
          | Some target_atom_proof ->
              let source_atom_proof =
                convert local_depth `Backward source_atom target_atom target_atom_proof
              in
              begin match native_core_true_eq_from_proof source_atom source_for_match source_atom_proof with
              | Some proof -> proof
              | None -> assert false
              end
          | None -> assert false
          end
      | `Forward, _, Some atom when same_formula_prop source atom ->
          begin match native_core_true_eq_from_proof atom target_for_match proof with
          | Some proof -> proof
          | None -> assert false
          end
      | `Forward, Some atom, _ when same_formula_prop target atom ->
          begin match native_core_proof_from_true_eq atom source_for_match proof with
          | Some proof -> proof
          | None -> assert false
          end
      | `Backward, _, Some atom when same_formula_prop source atom ->
          begin match native_core_proof_from_true_eq atom target_for_match proof with
          | Some proof -> proof
          | None -> assert false
          end
      | `Backward, Some atom, _ when same_formula_prop target atom ->
          begin match native_core_true_eq_from_proof atom source_for_match proof with
          | Some proof -> proof
          | None -> assert false
          end
      | _ ->
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body)
          when source_tp = target_tp ->
          TLam
            (source_tp,
             convert
               (local_depth + 1)
               direction
               source_body
               target_body
               (PTmAp (pftmshift 0 1 proof, DB 0)))
      | Imp (source_left, source_right), Imp (target_left, target_right) ->
          begin match direction with
          | `Forward ->
              let source_left_proof =
                convert local_depth `Backward source_left target_left (Hyp 0)
              in
              let source_right_proof =
                PPfAp (pfshift 0 1 proof, source_left_proof)
              in
              PLam
                (native_core_formula_prop target_left,
                 convert local_depth `Forward source_right target_right source_right_proof)
          | `Backward ->
              let target_left_proof =
                convert local_depth `Forward source_left target_left (Hyp 0)
              in
              let target_right_proof =
                PPfAp (pfshift 0 1 proof, target_left_proof)
              in
              PLam
                (native_core_formula_prop source_left,
                 convert local_depth `Backward source_right target_right target_right_proof)
          end
      | Ap (Ap (TmH "vampire_or", source_left), source_right),
        Ap (Ap (TmH "vampire_or", target_left), target_right) ->
          begin match direction with
          | `Forward ->
              let source_left_prop = native_core_formula_prop source_left in
              let source_right_prop = native_core_formula_prop source_right in
              let target_left_prop = native_core_formula_prop target_left in
              let target_right_prop = native_core_formula_prop target_right in
              let target_prop = native_core_or target_left_prop target_right_prop in
              let left_branch =
                PLam
                  (source_left_prop,
                   native_core_or_intro_left
                     target_left_prop
                     target_right_prop
                     (convert local_depth `Forward source_left target_left (Hyp 0)))
              in
              let right_branch =
                PLam
                  (source_right_prop,
                   native_core_or_intro_right
                     target_left_prop
                     target_right_prop
                     (convert local_depth `Forward source_right target_right (Hyp 0)))
              in
              PPfAp (PPfAp (PTmAp (proof, target_prop), left_branch), right_branch)
          | `Backward ->
              let source_left_prop = native_core_formula_prop source_left in
              let source_right_prop = native_core_formula_prop source_right in
              let target_left_prop = native_core_formula_prop target_left in
              let target_right_prop = native_core_formula_prop target_right in
              let source_prop = native_core_or source_left_prop source_right_prop in
              let left_branch =
                PLam
                  (target_left_prop,
                   native_core_or_intro_left
                     source_left_prop
                     source_right_prop
                     (convert local_depth `Backward source_left target_left (Hyp 0)))
              in
              let right_branch =
                PLam
                  (target_right_prop,
                   native_core_or_intro_right
                     source_left_prop
                     source_right_prop
                     (convert local_depth `Backward source_right target_right (Hyp 0)))
              in
              PPfAp (PPfAp (PTmAp (proof, source_prop), left_branch), right_branch)
          end
      | Ap (Ap (TmH "vampire_and", source_left), source_right),
        Ap (Ap (TmH "vampire_and", target_left), target_right) ->
          begin match direction with
          | `Forward ->
              let source_left_prop = native_core_formula_prop source_left in
              let source_right_prop = native_core_formula_prop source_right in
              let target_left_prop = native_core_formula_prop target_left in
              let target_right_prop = native_core_formula_prop target_right in
              let source_left_proof =
                native_core_and_elim_left source_left_prop source_right_prop proof
              in
              let source_right_proof =
                native_core_and_elim_right source_left_prop source_right_prop proof
              in
              native_core_and_intro
                target_left_prop
                target_right_prop
                (convert local_depth `Forward source_left target_left source_left_proof)
                (convert local_depth `Forward source_right target_right source_right_proof)
          | `Backward ->
              let source_left_prop = native_core_formula_prop source_left in
              let source_right_prop = native_core_formula_prop source_right in
              let target_left_prop = native_core_formula_prop target_left in
              let target_right_prop = native_core_formula_prop target_right in
              let target_left_proof =
                native_core_and_elim_left target_left_prop target_right_prop proof
              in
              let target_right_proof =
                native_core_and_elim_right target_left_prop target_right_prop proof
              in
              native_core_and_intro
                source_left_prop
                source_right_prop
                (convert local_depth `Backward source_left target_left target_left_proof)
                (convert local_depth `Backward source_right target_right target_right_proof)
          end
      | Ap (TmH "vampire_exists_prop", Lam (source_tp, source_body)),
        Ap (TmH "vampire_exists_prop", Lam (target_tp, target_body))
          when source_tp = target_tp ->
          begin match direction with
          | `Forward ->
              TLam
                (Prop,
                 PLam
                   (All (target_tp, Imp (tmshift 1 1 (native_core_formula_prop target_body), DB 1)),
                    let continuation =
                      TLam
                        (source_tp,
                         PLam
                           (native_core_formula_prop (tmshift 1 1 source_body),
                            let target_body_proof =
                              convert
                                (local_depth + 1)
                                `Forward
                                (tmshift 1 1 source_body)
                                (tmshift 1 1 target_body)
                                (Hyp 0)
                            in
                            PPfAp
                              (PTmAp (pftmshift 0 1 (Hyp 1), DB 0),
                               target_body_proof)))
                    in
                    PPfAp
                      (PTmAp (pfshift 0 1 (pftmshift 0 1 proof), DB 0),
                       continuation)))
          | `Backward ->
              TLam
                (Prop,
                 PLam
                   (All (source_tp, Imp (tmshift 1 1 (native_core_formula_prop source_body), DB 1)),
                    let continuation =
                      TLam
                        (target_tp,
                         PLam
                           (native_core_formula_prop (tmshift 1 1 target_body),
                            let source_body_proof =
                              convert
                                (local_depth + 1)
                                `Backward
                                (tmshift 1 1 source_body)
                                (tmshift 1 1 target_body)
                                (Hyp 0)
                            in
                            PPfAp
                              (PTmAp (pftmshift 0 1 (Hyp 1), DB 0),
                               source_body_proof)))
                    in
                    PPfAp
                      (PTmAp (pfshift 0 1 (pftmshift 0 1 proof), DB 0),
                       continuation)))
          end
      | Ap (TmH "vampire_exists_prop", Lam (tp, body)), _ ->
          begin match direction with
          | `Forward ->
              let choice = native_core_exists_choice_hash tp in
              if choice = "vampire_exists_unsupported_choice" then
                error
                  (id ^ ": native preprocess proof-term formula orientation has no choice theorem for nested existential");
              let predicate = Lam (tp, native_core_formula_prop body) in
              let epsilon_witness = Ap (TmH (native_core_eps_symbol tp), predicate) in
              let choice_proof = PPfAp (PTmAp (Known choice, predicate), proof) in
              convert
                local_depth
                `Forward
                (tmsubst body 0 epsilon_witness)
                target
                choice_proof
          | `Backward ->
              if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
                prerr_endline ("native core formula orientation debug source: " ^ tm_to_str source);
                prerr_endline ("native core formula orientation debug target: " ^ tm_to_str target)
              end;
              error
                (id ^ ": native preprocess proof-term formula orientation does not synthesize existential introductions")
          end
      | _ ->
          begin match direction with
          | `Forward ->
              let source_for_match =
                normalize_for_match source
                |> native_core_normalize_bool_constants
              in
              let target_for_match =
                normalize_for_match target
                |> native_core_normalize_bool_constants
              in
              begin match native_core_swapped_eq_literal (Pos source_for_match) with
              | Some (Pos swapped) when swapped = target_for_match ->
                  native_core_eq_symmetry_proof id (Pos source) proof
              | _ ->
                  begin match native_core_equality_sides target_for_match with
                  | Some (Prop, left, right)
                      when left = native_core_true && is_definition_term right ->
                      begin match native_core_true_eq_from_proof right target_for_match proof with
                      | Some proof -> proof
                      | None -> assert false
                      end
                  | Some (Prop, left, right)
                      when right = native_core_true && is_definition_term left ->
                      begin match native_core_true_eq_from_proof left target_for_match proof with
                      | Some proof -> proof
                      | None -> assert false
                      end
                  | _ ->
                      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
                        prerr_endline ("native core formula orientation debug source: " ^ tm_to_str source);
                        prerr_endline ("native core formula orientation debug target: " ^ tm_to_str target);
                        prerr_endline ("native core formula orientation debug normalized source: " ^ tm_to_str source_for_match);
                        prerr_endline ("native core formula orientation debug normalized target: " ^ tm_to_str target_for_match);
                        debug_formula_orientation_difference source_for_match target_for_match
                      end;
                      error
                        (id ^ ": native preprocess proof-term formula orientation supports only equality symmetry, true equality introduction, and matching logical structure")
                  end
              end
          | `Backward ->
              let source_for_match =
                normalize_for_match source
                |> native_core_normalize_bool_constants
              in
              let target_for_match =
                normalize_for_match target
                |> native_core_normalize_bool_constants
              in
              begin match native_core_swapped_eq_literal (Pos target_for_match) with
              | Some (Pos swapped) when swapped = source_for_match ->
                  native_core_eq_symmetry_proof id (Pos target) proof
              | _ ->
                  begin match native_core_equality_sides target_for_match with
                  | Some (Prop, left, right)
                      when left = native_core_true && is_definition_term right ->
                      begin match native_core_proof_from_true_eq right target_for_match proof with
                      | Some proof -> proof
                      | None -> assert false
                      end
                  | Some (Prop, left, right)
                      when right = native_core_true && is_definition_term left ->
                      begin match native_core_proof_from_true_eq left target_for_match proof with
                      | Some proof -> proof
                      | None -> assert false
                      end
                  | _ ->
                      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
                        prerr_endline ("native core formula orientation debug source: " ^ tm_to_str source);
                        prerr_endline ("native core formula orientation debug target: " ^ tm_to_str target);
                        prerr_endline ("native core formula orientation debug normalized source: " ^ tm_to_str source_for_match);
                        prerr_endline ("native core formula orientation debug normalized target: " ^ tm_to_str target_for_match);
                        debug_formula_orientation_difference source_for_match target_for_match
                      end;
                      error
                        (id ^ ": native preprocess proof-term formula orientation supports only equality symmetry, true equality elimination, and matching logical structure")
                  end
              end
          end
    end
  in
  let body_proof = convert 0 `Forward source target parent_proof in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_predicate_definition_fold_step_proof
    id variables parent_step_variables result_step_variables definition source target proof =
  let _, definiendum, body = predicate_definition_parts id definition in
  let base_depth = universal_binder_count definition in
  let patterns = predicate_definition_fold_patterns base_depth body definiendum in
  let result_variable_count = List.length result_step_variables in
  let db_for_result_variable name tp =
    let rec find index = function
      | [] -> None
      | (candidate_name, candidate_tp) :: rest ->
          if candidate_name = name && candidate_tp = tp then
            Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_result_variable tp =
    let rec find index = function
      | [] -> None
      | (_, candidate_tp) :: rest ->
          if candidate_tp = tp then Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_declared_variable tp =
    variables
    |> List.find_opt (fun (_, candidate_tp) -> candidate_tp = tp)
    |> Option.map (fun (name, _) -> TmH name)
  in
  let fallback_variable tp =
    match fallback_result_variable tp with
    | Some tm -> Some tm
    | None ->
        begin match fallback_declared_variable tp with
        | Some tm -> Some tm
        | None -> native_core_default_witness tp
        end
  in
  let parent_proof =
    List.fold_left
      (fun proof (name, tp) ->
         let arg =
           match db_for_result_variable name tp with
           | Some tm -> tm
           | None ->
               begin match fallback_variable tp with
               | Some tm -> tm
               | None ->
                   error
                     (id ^ ": native preprocess proof-term predicate fold cannot instantiate dropped parent variable " ^ name)
               end
         in
         PTmAp (proof, arg))
      (pftmshift 0 result_variable_count proof)
      parent_step_variables
  in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let source = close_tm source in
  let target = close_tm target in
  let patterns = List.map (fun (needle, replacement) -> (close_tm needle, close_tm replacement)) patterns in
  let root_replacement depth source target =
    let shift = max 0 (depth - base_depth) in
    List.exists
      (fun (needle, replacement) ->
         let shifted_needle = tmshift 0 shift needle in
         let shifted_replacement = tmshift 0 shift replacement in
         match tm_pattern_replacement_result base_depth source needle replacement with
         | Some instantiated when target = instantiated -> true
         | _ -> source = shifted_needle && target = shifted_replacement)
      patterns
  in
  let proof_for_replacement target_atom proof =
    let target_prop =
      native_core_formula_prop target_atom
      |> native_core_normalize_bool_constants
    in
    let underlying_prop =
      match native_core_equality_sides target_atom with
      | Some (Prop, left, right) when left = native_core_true ->
          native_core_formula_prop right |> native_core_normalize_bool_constants
      | Some (Prop, left, right) when right = native_core_true ->
          native_core_formula_prop left |> native_core_normalize_bool_constants
      | _ -> target_prop
    in
    if target_prop = underlying_prop then proof
    else
      match native_core_true_eq_from_proof underlying_prop target_atom proof with
      | Some proof -> proof
      | None ->
          error
            (id ^ ": native preprocess proof-term predicate fold cannot introduce target equality")
  in
  let rec convert depth source target proof =
    let source_prop =
      native_core_formula_prop source
      |> native_core_normalize_bool_constants
    in
    let target_prop =
      native_core_formula_prop target
      |> native_core_normalize_bool_constants
    in
    if source_prop = target_prop then proof
    else if root_replacement depth source target then
      proof_for_replacement target proof
    else
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body)
          when source_tp = target_tp ->
          TLam
            (source_tp,
             convert
               (depth + 1)
               source_body
               target_body
               (PTmAp (pftmshift 0 1 proof, DB 0)))
      | Imp (source_left, source_right), Imp (target_left, target_right)
          when native_core_formula_prop source_left = native_core_formula_prop target_left ->
          PLam
            (native_core_formula_prop target_left,
             convert
               depth
               source_right
               target_right
               (PPfAp (pfshift 0 1 proof, Hyp 0)))
      | Ap (Ap (TmH "vampire_or", source_left), source_right),
        Ap (Ap (TmH "vampire_or", target_left), target_right) ->
          let source_left_prop = native_core_formula_prop source_left in
          let source_right_prop = native_core_formula_prop source_right in
          let target_left_prop = native_core_formula_prop target_left in
          let target_right_prop = native_core_formula_prop target_right in
          let target_prop = native_core_or target_left_prop target_right_prop in
          let left_branch =
            PLam
              (source_left_prop,
               native_core_or_intro_left
                 target_left_prop
                 target_right_prop
                 (convert depth source_left target_left (Hyp 0)))
          in
          let right_branch =
            PLam
              (source_right_prop,
               native_core_or_intro_right
                 target_left_prop
                 target_right_prop
                 (convert depth source_right target_right (Hyp 0)))
          in
          PPfAp (PPfAp (PTmAp (proof, target_prop), left_branch), right_branch)
      | Ap (Ap (TmH "vampire_and", source_left), source_right),
        Ap (Ap (TmH "vampire_and", target_left), target_right) ->
          let source_left_prop = native_core_formula_prop source_left in
          let source_right_prop = native_core_formula_prop source_right in
          let target_left_prop = native_core_formula_prop target_left in
          let target_right_prop = native_core_formula_prop target_right in
          let source_left_proof =
            native_core_and_elim_left source_left_prop source_right_prop proof
          in
          let source_right_proof =
            native_core_and_elim_right source_left_prop source_right_prop proof
          in
          native_core_and_intro
            target_left_prop
            target_right_prop
            (convert depth source_left target_left source_left_proof)
            (convert depth source_right target_right source_right_proof)
      | Ap (TmH "vampire_exists_prop", Lam (source_tp, source_body)),
        Ap (TmH "vampire_exists_prop", Lam (target_tp, target_body))
          when source_tp = target_tp ->
          TLam
            (Prop,
             PLam
               (All (target_tp, Imp (tmshift 1 1 (native_core_formula_prop target_body), DB 1)),
                let continuation =
                  TLam
                    (source_tp,
                     PLam
                       (native_core_formula_prop (tmshift 1 1 source_body),
                        let target_body_proof =
                          convert
                            (depth + 1)
                            (tmshift 1 1 source_body)
                            (tmshift 1 1 target_body)
                            (Hyp 0)
                        in
                        PPfAp
                          (PTmAp (pftmshift 0 1 (Hyp 1), DB 0),
                           target_body_proof)))
                in
                PPfAp
                  (PTmAp (pfshift 0 1 (pftmshift 0 1 proof), DB 0),
                   continuation)))
      | _ ->
          if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
            prerr_endline ("native predicate fold debug source: " ^ tm_to_str source);
            prerr_endline ("native predicate fold debug target: " ^ tm_to_str target)
          end;
          error
            (id ^ ": native preprocess proof-term predicate fold does not support this formula context")
  in
  let body_proof = convert 0 source target parent_proof in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_skolem_target_witness id source target =
  let merge left right =
    match left, right with
    | None, found | found, None -> found
    | Some left_tm, Some right_tm when left_tm = right_tm -> Some left_tm
    | Some _, Some _ ->
        error
          (id ^ ": native core proof-term skolemization found inconsistent target witnesses")
  in
  let rec match_tm depth source target =
    match source with
    | DB index ->
        if index = depth then Some (tmshift 0 (-depth) target)
        else if index > depth then
          let expected = DB (index - 1) in
          if expected = target then None else raise Not_found
        else if source = target then None
        else raise Not_found
    | TmH _ | Prim _ ->
        if source = target then None else raise Not_found
    | TpAp (source_tm, source_tp) ->
        begin match target with
        | TpAp (target_tm, target_tp) when source_tp = target_tp ->
            match_tm depth source_tm target_tm
        | _ -> raise Not_found
        end
    | Ap (source_left, source_right) ->
        begin match source, target with
        | Ap (Ap (source_eq, source_l), source_r),
          Ap (Ap (target_eq, target_l), target_r)
            when source_eq = target_eq
                 && megalodon_eq_poly_sides source <> None
                 && megalodon_eq_poly_sides target <> None ->
            begin try
              merge (match_tm depth source_l target_l) (match_tm depth source_r target_r)
            with Not_found ->
              merge (match_tm depth source_l target_r) (match_tm depth source_r target_l)
            end
        | _, Ap (target_left, target_right) ->
            merge
              (match_tm depth source_left target_left)
              (match_tm depth source_right target_right)
        | _ -> raise Not_found
        end
    | Lam (source_tp, source_body) ->
        begin match target with
        | Lam (target_tp, target_body) when source_tp = target_tp ->
            match_tm (depth + 1) source_body target_body
        | _ -> raise Not_found
        end
    | Imp (source_left, source_right) ->
        begin match target with
        | Imp (target_left, target_right) ->
            merge
              (match_tm depth source_left target_left)
              (match_tm depth source_right target_right)
        | _ -> raise Not_found
        end
    | All (source_tp, source_body) ->
        begin match target with
        | All (target_tp, target_body) when source_tp = target_tp ->
            match_tm (depth + 1) source_body target_body
        | _ -> raise Not_found
        end
  in
  match match_tm 0 source target with
  | Some witness -> witness
  | None ->
      error
        (id ^ ": native core proof-term skolemization result does not expose a target witness")
  | exception Not_found ->
      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
        prerr_endline ("native core skolem witness debug source: " ^ tm_to_str source);
        prerr_endline ("native core skolem witness debug target: " ^ tm_to_str target)
      end;
      error
        (id ^ ": native core proof-term skolemization result does not match source body")

let native_core_skolem_parent_helper_formulas cert id =
  let rec quantified_implication_prefix tps = function
    | All (tp, body) -> quantified_implication_prefix (tps @ [tp]) body
    | Imp _ -> Some tps
    | _ -> None
  in
  let wrap_quantifiers tps body =
    List.fold_right (fun tp acc -> All (tp, acc)) tps body
  in
	  let explicit_macro_edges =
	    native_core_skolem_macro_edges cert id
	    |> List.filter_map
	         (fun edge ->
	            let edge_source =
	              match edge.native_skolem_macro_edge_branch_contract with
	              | Some contract ->
	                  begin match
	                    contract.Vampire_kernel_syntax.skolem_branch_source_formula
	                  with
	                  | Some source -> Some source
	                  | None -> edge.native_skolem_macro_edge_source
	                  end
	              | None -> edge.native_skolem_macro_edge_source
	            in
	            let edge_target =
	              match edge.native_skolem_macro_edge_branch_contract with
	              | Some contract ->
	                  begin match
	                    contract.Vampire_kernel_syntax.skolem_branch_target_formula
	                  with
	                  | Some target -> Some target
	                  | None -> edge.native_skolem_macro_edge_target
	                  end
	              | None -> edge.native_skolem_macro_edge_target
	            in
	            match
	              edge.native_skolem_macro_edge_formula,
	              edge_source,
	              edge_target
	            with
            | Some formula, Some source, Some target ->
                let tps =
                  match edge.native_skolem_macro_edge_binders with
                  | [] ->
                      begin match quantified_implication_prefix [] formula with
                      | Some tps -> tps
                      | None -> []
                      end
                  | binders ->
                      List.map
                        (fun binder -> binder.native_kernel_variable_type)
                        binders
                in
                Some (wrap_quantifiers tps (Imp (source, target)))
            | _, Some source, Some target -> Some (Imp (source, target))
            | _ -> None)
  in
  if explicit_macro_edges <> [] then explicit_macro_edges
  else
  let proof_parent_count =
    match native_core_metadata_step_extra_field cert id "kernel_v1" "proof_parent_count" with
    | Some value ->
        begin try int_of_string value
        with Failure _ -> 0
        end
    | None -> 0
  in
  let parse_parent_formula index =
    match
      native_core_metadata_step_extra_field
        cert id "kernel_v1" ("parent_" ^ string_of_int index ^ "_formula")
    with
    | Some value -> Some (parse_tm (parse_sexpr value))
    | None -> None
  in
  let rec collect index acc =
    if index >= proof_parent_count then List.rev acc
    else
      let acc =
        match parse_parent_formula index with
        | Some formula -> formula :: acc
        | None -> acc
      in
      collect (index + 1) acc
  in
  collect 1 []

let native_core_skolem_source_existential_names cert id =
  let metadata_names () =
    match native_core_kernel_v1_field cert id "source_formula_quantifier_count" with
    | None -> None
    | Some _ ->
        Some
          (native_core_kernel_v1_quantifier_fields cert id "source_formula"
           |> List.filter_map
                (fun quantifier ->
                   if quantifier.native_kernel_quantifier_kind = "exists" then
                     let variable =
                       quantifier.native_kernel_quantifier_variable
                     in
                     Some variable.native_kernel_variable_name
                   else
                     None))
  in
  let rec collect = function
    | List [Atom "AP"; List [Atom "TMH"; exists_head];
            List [Atom binder; name; _tp; body]]
        when atom exists_head = "vampire_exists_prop"
             && (binder = "LAMV" || binder = "VLAMV") ->
        atom name :: collect body
    | List items ->
        List.concat_map collect items
    | Atom _ | Str _ -> []
  in
  match metadata_names () with
  | Some names -> names
  | None ->
      match native_core_metadata_step_extra_field cert id "kernel_v1" "source_formula" with
      | Some value ->
          collect (parse_sexpr value)
      | None -> []

let native_core_reorder_skolem_substitution_by_source cert id subst =
  let names = native_core_skolem_source_existential_names cert id in
  if names = [] then subst
  else
    let selected =
      names
      |> List.filter_map
           (fun name ->
              match List.assoc_opt name subst with
              | Some witness -> Some (name, witness)
              | None -> None)
    in
    let selected_names = List.map fst selected in
    let rest =
      subst
      |> List.filter (fun (name, _) -> not (List.mem name selected_names))
    in
    let reordered = selected @ rest in
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1"
       && reordered <> subst then
      prerr_endline
        (id
         ^ ": native core skolem reordered substitution by source binders "
         ^ String.concat "," (List.map fst subst)
         ^ " -> "
         ^ String.concat "," (List.map fst reordered));
    reordered

let rec native_core_direct_skolem_formula_proof
    ?(helper_formulas=[])
    ?(normalize_formula_for_match=(fun _ tm -> tm))
    ?(register_witness_replacement=(fun _ _ -> ()))
    ?(ambient_shift=0)
    id substitution source target proof =
  let rec contains_named name = function
    | TmH candidate -> candidate = name
    | TpAp (m, _) -> contains_named name m
    | Ap (m, n) | Imp (m, n) -> contains_named name m || contains_named name n
    | Lam (_, body) | All (_, body) -> contains_named name body
    | DB _ | Prim _ -> false
  in
  let rec rewrite_witnesses replacements depth tm =
    match
      List.find_opt
        (fun (target_witness, _) -> tm = tmshift 0 depth target_witness)
        replacements
    with
    | Some (_, epsilon_witness) -> tmshift 0 depth epsilon_witness
    | None ->
        match tm with
        | TpAp (m, a) -> TpAp (rewrite_witnesses replacements depth m, a)
        | Ap (m, n) ->
            Ap
              (rewrite_witnesses replacements depth m,
               rewrite_witnesses replacements depth n)
        | Lam (a, body) ->
            Lam (a, rewrite_witnesses replacements (depth + 1) body)
        | Imp (left, right) ->
            Imp
              (rewrite_witnesses replacements depth left,
               rewrite_witnesses replacements depth right)
        | All (a, body) ->
            All (a, rewrite_witnesses replacements (depth + 1) body)
        | DB _ | TmH _ | Prim _ -> tm
  in
  let pick_substitution_for_target body target remaining =
    let inferred_witness =
      try Some (native_core_skolem_target_witness id body target)
      with Error _ | Not_found -> None
    in
    match inferred_witness with
    | Some inferred_witness ->
        let rec pick prefix = function
          | [] -> None
          | (name, witness) :: rest ->
              if witness = inferred_witness then
                Some (name, witness, List.rev_append prefix rest)
              else
                pick ((name, witness) :: prefix) rest
        in
        begin match pick [] remaining with
        | Some selected -> selected
        | None ->
            begin match remaining with
            | (name, witness) :: rest -> name, witness, rest
            | [] -> "", inferred_witness, []
            end
        end
    | None ->
        begin match remaining with
        | (name, witness) :: rest -> name, witness, rest
        | [] -> "", native_core_skolem_target_witness id body target, []
        end
  in
  let checked_formula_prop local_depth tm =
    normalize_formula_for_match (ambient_shift + local_depth) tm
    |> native_core_formula_prop
    |> native_core_normalize_bool_constants
  in
  let normalized_formula_for_helper local_depth tm =
    normalize_formula_for_match (ambient_shift + local_depth) tm
    |> native_core_normalize_bool_constants
    |> tm_beta_eta_norm
  in
  let raw_formula_for_helper tm =
    native_core_normalize_bool_constants tm
    |> tm_beta_eta_norm
  in
  let rec formula_contains_exists = function
    | Ap (TmH "vampire_exists_prop", Lam _) -> true
    | TpAp (tm, _) -> formula_contains_exists tm
    | Ap (left, right) | Imp (left, right) ->
        formula_contains_exists left || formula_contains_exists right
    | Lam (_, body) | All (_, body) -> formula_contains_exists body
    | DB _ | TmH _ | Prim _ -> false
  in
  let helper_records =
    if helper_formulas = [] then []
    else
      let rec peel_foralls tps = function
        | All (tp, body) -> peel_foralls (tps @ [tp]) body
        | Imp (source, target) -> Some (tps, source, target)
        | _ -> None
      in
      helper_formulas
      |> List.mapi (fun index formula -> index, peel_foralls [] formula)
      |> List.filter_map
           (fun (index, helper) ->
              match helper with
              | Some (tps, source, target) -> Some (index, tps, source, target)
              | None -> None)
  in
  let shape_tag tm =
    match tm with
    | TmH name -> "TmH:" ^ name
    | DB index -> "DB:" ^ string_of_int index
    | Prim index -> "Prim:" ^ string_of_int index
    | TpAp _ -> "TpAp"
    | Ap (TmH name, _) -> "Ap:" ^ name
    | Ap (Ap (TmH name, _), _) -> "Ap2:" ^ name
    | Ap _ -> "Ap"
    | Lam _ -> "Lam"
    | Imp _ -> "Imp"
    | All _ -> "All"
  in
  if helper_records <> [] && Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
    prerr_endline
      (id
       ^ ": native core skolem helper records="
       ^ string_of_int (List.length helper_records)
       ^ " source_shape="
       ^ shape_tag source
       ^ " target_shape="
       ^ shape_tag target);
  let rec helper_target_compatible local_depth helper_target target =
    normalized_formula_for_helper local_depth helper_target
    = normalized_formula_for_helper local_depth target
    ||
    match helper_target, target with
    | All (helper_tp, helper_body), All (target_tp, target_body)
        when helper_tp = target_tp ->
        helper_target_compatible (local_depth + 1) helper_body target_body
    | Imp (helper_left, helper_right), Imp (target_left, target_right) ->
        helper_target_compatible local_depth helper_left target_left
        && helper_target_compatible local_depth helper_right target_right
    | Ap (Ap (TmH "vampire_and", helper_left), helper_right),
      Ap (Ap (TmH "vampire_and", target_left), target_right)
    | Ap (Ap (TmH "vampire_or", helper_left), helper_right),
      Ap (Ap (TmH "vampire_or", target_left), target_right) ->
        helper_target_compatible local_depth helper_left target_left
        && helper_target_compatible local_depth helper_right target_right
    | Ap (TmH "vampire_exists_prop", Lam _), _ ->
        true
    | _ -> false
  in
  let normalized_formula_with_replacements local_depth replacements tm =
    rewrite_witnesses replacements local_depth tm
    |> normalized_formula_for_helper local_depth
  in
  let helper_target_matches_current local_depth replacements helper_target target =
    let helper_target = rewrite_witnesses replacements local_depth helper_target in
    let target = rewrite_witnesses replacements local_depth target in
    if formula_contains_exists helper_target then
      helper_target_compatible local_depth helper_target target
    else
      raw_formula_for_helper helper_target = raw_formula_for_helper target
  in
  let rec matching_helper local_depth replacements source target helpers =
    match helpers with
    | [] -> None
    | ((_, _, helper_source, helper_target) as helper) :: rest ->
        if normalized_formula_for_helper local_depth source
           = normalized_formula_with_replacements local_depth replacements helper_source
           && helper_target_matches_current local_depth replacements helper_target target
           && normalized_formula_with_replacements local_depth replacements helper_source
              <> normalized_formula_with_replacements local_depth replacements helper_target then
          Some (helper, rest)
        else
          begin match matching_helper local_depth replacements source target rest with
          | Some (found, remaining) -> Some (found, helper :: remaining)
          | None -> None
          end
  in
  let rec choose_basic local_depth current_target remaining_substitution source proof replacements used_choice =
    match source with
    | Ap (TmH "vampire_exists_prop", Lam (tp, body)) ->
        let choice = native_core_exists_choice_hash tp in
        if choice = "vampire_exists_unsupported_choice" then
          error
            (id ^ ": native core proof-term skolemization has no choice theorem for witness sort");
        let predicate_for_body body =
          Lam (tp, checked_formula_prop (local_depth + 1) body)
        in
        let substitution_name, target_witness, remaining_substitution =
          let name, witness, rest =
            pick_substitution_for_target body current_target remaining_substitution
          in
          (if name = "" then None else Some name), witness, rest
        in
        let compact_named_body =
          match substitution_name with
          | Some name -> contains_named name body
          | None -> false
        in
        let body, replacements =
          match substitution_name with
          | Some name when compact_named_body ->
              subst_tm [(name, target_witness)] body, replacements
          | Some name ->
              let body = subst_named_tm name body in
              let epsilon_witness =
                Ap (TmH (native_core_eps_symbol tp), predicate_for_body body)
              in
              register_witness_replacement target_witness epsilon_witness;
              body,
              (target_witness, epsilon_witness) :: replacements
          | None ->
              let epsilon_witness =
                Ap (TmH (native_core_eps_symbol tp), predicate_for_body body)
              in
              register_witness_replacement target_witness epsilon_witness;
              body,
              (target_witness, epsilon_witness) :: replacements
        in
        let predicate = predicate_for_body body in
        let epsilon_witness = Ap (TmH (native_core_eps_symbol tp), predicate) in
        let choice_proof = PPfAp (PTmAp (Known choice, predicate), proof) in
        let instantiated_body = tmsubst body 0 epsilon_witness in
        choose_basic
          local_depth
          current_target
          remaining_substitution
          instantiated_body
          choice_proof
          replacements
          true
    | _ -> source, proof, replacements, used_choice, remaining_substitution
  in
  let helper_implication_proof_with_replacements replacements remaining_substitution tps helper_source helper_target =
    let active_source = rewrite_witnesses replacements 0 helper_source in
    let active_target = rewrite_witnesses replacements 0 helper_target in
    let orientation_source, body_proof, helper_replacements, helper_used_choice, remaining_substitution =
      choose_basic (List.length tps) active_target remaining_substitution active_source (Hyp 0) [] false
    in
    if not helper_used_choice then
      error (id ^ ": native core skolem helper implication did not eliminate an existential");
    let proved_target = rewrite_witnesses helper_replacements 0 active_target in
    let body_proof =
      native_core_formula_orientation_proof
        ~normalize_formula_for_match:(fun count tm ->
          normalize_formula_for_match (ambient_shift + List.length tps + count) tm)
        id [] [] [] orientation_source proved_target body_proof
    in
    let implication =
      PLam (native_core_formula_prop active_source, body_proof)
    in
    let proof = List.fold_right (fun tp proof -> TLam (tp, proof)) tps implication in
    proved_target, proof, helper_replacements @ replacements, remaining_substitution
  in
  let instantiate_helper_with_replacements replacements remaining_substitution tps helper_source helper_target current_proof =
    let proved_target, proof, replacements, remaining_substitution =
      helper_implication_proof_with_replacements
        replacements remaining_substitution tps helper_source helper_target
    in
    let args =
      List.mapi
        (fun index _ -> DB (List.length tps - index - 1))
        tps
    in
    let proof = List.fold_left (fun proof arg -> PTmAp (proof, arg)) proof args in
    proved_target, PPfAp (proof, current_proof), replacements, remaining_substitution
  in
  let rec choose_with_helpers
      local_depth helpers remaining_substitution source target proof replacements used_choice =
    let rec try_helpers helpers =
      match matching_helper local_depth replacements source target helpers with
      | None -> None
      | Some ((helper_index, tps, helper_source, helper_target), remaining_helpers) ->
          if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
            prerr_endline
              (id
               ^ ": native core skolem helper parent_"
               ^ string_of_int (helper_index + 1)
               ^ " at depth "
               ^ string_of_int local_depth);
          try
            let proved_target, proof, replacements, remaining_substitution =
              instantiate_helper_with_replacements
                replacements remaining_substitution tps helper_source helper_target proof
            in
            Some
              (choose_with_helpers
                 local_depth
                 remaining_helpers
                 remaining_substitution
                 proved_target
                 target
                 proof
                 replacements
                 true)
          with (Error _ | Failure _) as exn ->
            if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
              prerr_endline
                (id
                 ^ ": native core skolem helper parent_"
                 ^ string_of_int (helper_index + 1)
                 ^ " failed: "
                 ^ Printexc.to_string exn);
            try_helpers remaining_helpers
    in
    match try_helpers helpers with
    | Some result -> result
    | None ->
        match source with
        | Ap (TmH "vampire_exists_prop", Lam (tp, body)) ->
            begin match target with
            | Ap (TmH "vampire_exists_prop", Lam (target_tp, _))
                when target_tp = tp ->
                source, proof, replacements, used_choice, remaining_substitution
            | _ ->
                let choice = native_core_exists_choice_hash tp in
                if choice = "vampire_exists_unsupported_choice" then
                  error
                    (id ^ ": native core proof-term skolemization has no choice theorem for witness sort");
                let substitution_name, target_witness, remaining_substitution =
                  let name, witness, rest =
                    pick_substitution_for_target body target remaining_substitution
                  in
                  (if name = "" then None else Some name), witness, rest
                in
                if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                  prerr_endline
                    (id
                     ^ ": native core skolem choose "
                     ^ (match substitution_name with Some name -> name | None -> "<inferred>")
                     ^ " := "
                     ^ tm_to_str target_witness);
                let compact_named_body =
                  match substitution_name with
                  | Some name -> contains_named name body
                  | None -> false
                in
                let body, replacements =
                  match substitution_name with
                  | Some name when compact_named_body ->
                      subst_tm [(name, target_witness)] body, replacements
                  | Some name ->
                      let body = subst_named_tm name body in
                      let epsilon_witness =
                        Ap
                          (TmH (native_core_eps_symbol tp),
                           Lam (tp, checked_formula_prop (local_depth + 1) body))
                      in
                      register_witness_replacement target_witness epsilon_witness;
                      body,
                      (target_witness, epsilon_witness) :: replacements
                  | None ->
                      let epsilon_witness =
                        Ap
                          (TmH (native_core_eps_symbol tp),
                           Lam (tp, checked_formula_prop (local_depth + 1) body))
                      in
                      register_witness_replacement target_witness epsilon_witness;
                      body,
                      (target_witness, epsilon_witness) :: replacements
                in
                let predicate = Lam (tp, checked_formula_prop (local_depth + 1) body) in
                let choice_proof = PPfAp (PTmAp (Known choice, predicate), proof) in
                let target_body = tmsubst body 0 target_witness in
                let choice_proof =
                  PPfAp (PLam (checked_formula_prop local_depth target_body, Hyp 0), choice_proof)
                in
                choose_with_helpers
                  local_depth
                  helpers
                  remaining_substitution
                  target_body
                  target
                  choice_proof
                  replacements
                  true
            end
        | All (source_tp, source_body) ->
            begin match target with
            | All (target_tp, target_body) when source_tp = target_tp ->
                let transformed_body, body_proof, replacements, used_choice, remaining_substitution =
                  choose_with_helpers
                    (local_depth + 1)
                    helpers
                    remaining_substitution
                    source_body
                    target_body
                    (PTmAp (pftmshift 0 1 proof, DB 0))
                    replacements
                    used_choice
                in
                All (source_tp, transformed_body),
                TLam (source_tp, body_proof),
                replacements,
                used_choice,
                remaining_substitution
            | _ -> source, proof, replacements, used_choice, remaining_substitution
            end
        | Ap (Ap (TmH "vampire_and", source_left), source_right) ->
            begin match target with
            | Ap (Ap (TmH "vampire_and", target_left), target_right) ->
                let source_left_prop = checked_formula_prop local_depth source_left in
                let source_right_prop = checked_formula_prop local_depth source_right in
                let source_left_proof =
                  native_core_and_elim_left source_left_prop source_right_prop proof
                in
                let source_right_proof =
                  native_core_and_elim_right source_left_prop source_right_prop proof
                in
                let transformed_left, left_proof, replacements, used_choice, remaining_substitution =
                  choose_with_helpers
                    local_depth
                    helpers
                    remaining_substitution
                    source_left
                    target_left
                    source_left_proof
                    replacements
                    used_choice
                in
                let transformed_right, right_proof, replacements, used_choice, remaining_substitution =
                  choose_with_helpers
                    local_depth
                    helpers
                    remaining_substitution
                    source_right
                    target_right
                    source_right_proof
                    replacements
                    used_choice
                in
                let transformed_source =
                  Ap (Ap (TmH "vampire_and", transformed_left), transformed_right)
                in
                transformed_source,
                native_core_and_intro
                  (checked_formula_prop local_depth transformed_left)
                  (checked_formula_prop local_depth transformed_right)
                  left_proof
                  right_proof,
                replacements,
                used_choice,
                remaining_substitution
            | _ -> source, proof, replacements, used_choice, remaining_substitution
            end
        | Ap (Ap (TmH "vampire_or", source_left), source_right) ->
            begin match target with
            | Ap (Ap (TmH "vampire_or", target_left), target_right) ->
                let source_left_prop = checked_formula_prop local_depth source_left in
                let source_right_prop = checked_formula_prop local_depth source_right in
                let transformed_left, left_proof, replacements, used_choice, remaining_substitution =
                  choose_with_helpers
                    local_depth
                    helpers
                    remaining_substitution
                    source_left
                    target_left
                    (Hyp 0)
                    replacements
                    used_choice
                in
                let transformed_right, right_proof, replacements, used_choice, remaining_substitution =
                  choose_with_helpers
                    local_depth
                    helpers
                    remaining_substitution
                    source_right
                    target_right
                    (Hyp 0)
                    replacements
                    used_choice
                in
                let transformed_source =
                  Ap (Ap (TmH "vampire_or", transformed_left), transformed_right)
                in
                let transformed_prop =
                  native_core_or
                    (checked_formula_prop local_depth transformed_left)
                    (checked_formula_prop local_depth transformed_right)
                in
                let left_branch =
                  PLam
                    (source_left_prop,
                     native_core_or_intro_left
                       (checked_formula_prop local_depth transformed_left)
                       (checked_formula_prop local_depth transformed_right)
                       left_proof)
                in
                let right_branch =
                  PLam
                    (source_right_prop,
                     native_core_or_intro_right
                       (checked_formula_prop local_depth transformed_left)
                       (checked_formula_prop local_depth transformed_right)
                       right_proof)
                in
                transformed_source,
                PPfAp (PPfAp (PTmAp (proof, transformed_prop), left_branch), right_branch),
                replacements,
                used_choice,
                remaining_substitution
            | _ -> source, proof, replacements, used_choice, remaining_substitution
            end
        | _ -> source, proof, replacements, used_choice, remaining_substitution
  in
  let orientation_source, choice_proof, replacements, used_choice, _remaining_substitution =
    if helper_records = [] then
      choose_basic 0 target substitution source proof [] false
    else
      choose_with_helpers 0 helper_records substitution source target proof [] false
  in
  if not used_choice then
    error
      (id ^ ": native core proof-term skolemization supports only existential sources");
  let orientation_target =
    if helper_records = [] then rewrite_witnesses replacements 0 target
    else target
  in
  native_core_formula_orientation_proof
    ~normalize_formula_for_match:(fun count tm ->
      normalize_formula_for_match (ambient_shift + count) tm)
    id [] [] [] orientation_source orientation_target choice_proof

let native_core_skolem_formula_proof
    ?(helper_formulas=[])
    ?(normalize_formula_for_match=(fun _ tm -> tm))
    ?(register_witness_replacement=(fun _ _ -> ()))
    id variables parent_step_variables result_step_variables substitution source target proof =
  let source = native_core_close_tm (variables @ result_step_variables) source in
  let target = native_core_close_tm (variables @ result_step_variables) target in
  let result_variable_count = List.length result_step_variables in
  let db_for_result_variable name tp =
    let rec find index = function
      | [] -> None
      | (candidate_name, candidate_tp) :: rest ->
          if candidate_name = name && candidate_tp = tp then
            Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let substitution_for_parent_variable name _tp =
    substitution
    |> List.find_opt (fun (candidate_name, _) -> candidate_name = name)
    |> Option.map
         (fun (_, witness) ->
            native_core_close_tm (variables @ result_step_variables) witness)
  in
  let fallback_result_variable tp =
    let rec find index = function
      | [] -> None
      | (_, candidate_tp) :: rest ->
          if candidate_tp = tp then Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let fallback_declared_variable tp =
    variables
    |> List.find_opt (fun (_, candidate_tp) -> candidate_tp = tp)
    |> Option.map (fun (name, _) -> TmH name)
  in
  let fallback_variable tp =
    match fallback_result_variable tp with
    | Some tm -> Some tm
    | None -> fallback_declared_variable tp
  in
  let parent_proof =
    List.fold_left
      (fun proof (name, tp) ->
         let arg =
           match db_for_result_variable name tp with
           | Some tm -> tm
           | None ->
               begin match substitution_for_parent_variable name tp with
               | Some tm -> tm
               | None ->
                   begin match fallback_variable tp with
                   | Some tm -> tm
                   | None ->
                       error
                         (id ^ ": native core proof-term skolemization cannot instantiate dropped parent variable " ^ name)
                   end
               end
         in
         PTmAp (proof, arg))
      (pftmshift 0 result_variable_count proof)
      parent_step_variables
  in
  let rec convert source target proof =
    if native_core_formula_prop source = native_core_formula_prop target then proof
    else
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body)
          when source_tp = target_tp ->
          TLam
            (source_tp,
             convert
               source_body
               target_body
               (PTmAp (pftmshift 0 1 proof, DB 0)))
      | Ap (Ap (TmH "vampire_or", source_left), source_right),
        Ap (Ap (TmH "vampire_or", target_left), target_right) ->
          let source_left_prop = native_core_formula_prop source_left in
          let source_right_prop = native_core_formula_prop source_right in
          let target_left_prop = native_core_formula_prop target_left in
          let target_right_prop = native_core_formula_prop target_right in
          let target_prop = native_core_or target_left_prop target_right_prop in
          let left_branch =
            PLam
              (source_left_prop,
               let target_left_proof =
                 convert source_left target_left (Hyp 0)
               in
               native_core_or_intro_left
                 target_left_prop
                 target_right_prop
                 target_left_proof)
          in
          let right_branch =
            PLam
              (source_right_prop,
               let target_right_proof =
                 convert source_right target_right (Hyp 0)
               in
               native_core_or_intro_right
                 target_left_prop
                 target_right_prop
                 target_right_proof)
          in
          PPfAp
            (PPfAp (PTmAp (proof, target_prop), left_branch),
             right_branch)
      | Ap (Ap (TmH "vampire_and", source_left), source_right),
        Ap (Ap (TmH "vampire_and", target_left), target_right) ->
          let source_left_prop = native_core_formula_prop source_left in
          let source_right_prop = native_core_formula_prop source_right in
          let target_left_prop = native_core_formula_prop target_left in
          let target_right_prop = native_core_formula_prop target_right in
          let source_left_proof =
            native_core_and_elim_left source_left_prop source_right_prop proof
          in
          let source_right_proof =
            native_core_and_elim_right source_left_prop source_right_prop proof
          in
          native_core_and_intro
            target_left_prop
            target_right_prop
            (convert source_left target_left source_left_proof)
            (convert source_right target_right source_right_proof)
      | Ap (TmH "vampire_exists_prop", Lam _), _ ->
          let closed_substitution =
            List.map
              (fun (name, witness) ->
                 (name, native_core_close_tm (variables @ result_step_variables) witness))
              substitution
          in
          native_core_direct_skolem_formula_proof
            ~helper_formulas
            ~normalize_formula_for_match
            ~register_witness_replacement
            ~ambient_shift:result_variable_count
            id closed_substitution source target proof
      | _ ->
          error
            (id ^ ": native core proof-term skolemization supports only existential, forall, and disjunction contexts")
  in
  let body_proof = convert source target parent_proof in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_replace_witness_symbols_in_tm replacements tm =
  let rec replace depth tm =
    match tm with
    | TmH name ->
        begin match List.assoc_opt name replacements with
        | Some witness -> tmshift 0 depth (replace 0 witness)
        | None -> tm
        end
    | TpAp (body, tp) -> TpAp (replace depth body, tp)
    | Ap (left, right) -> Ap (replace depth left, replace depth right)
    | Lam (tp, body) -> Lam (tp, replace (depth + 1) body)
    | Imp (left, right) -> Imp (replace depth left, replace depth right)
    | All (tp, body) -> All (tp, replace (depth + 1) body)
    | DB _ | Prim _ -> tm
  in
  replace 0 tm
  |> native_core_normalize_bool_constants
  |> tm_beta_eta_norm

let native_core_replace_witness_symbols_in_pf replacements proof =
  let normalize tm =
    tm
    |> native_core_normalize_bool_constants
    |> tm_beta_eta_norm
  in
  let rec replace_tm depth tm =
    match tm with
    | TmH name ->
        begin match List.assoc_opt name replacements with
        | Some witness -> tmshift 0 depth (replace_tm 0 witness)
        | None -> tm
        end
    | TpAp (body, tp) -> TpAp (replace_tm depth body, tp)
    | Ap (left, right) -> Ap (replace_tm depth left, replace_tm depth right)
    | Lam (tp, body) -> Lam (tp, replace_tm (depth + 1) body)
    | Imp (left, right) -> Imp (replace_tm depth left, replace_tm depth right)
    | All (tp, body) -> All (tp, replace_tm (depth + 1) body)
    | DB _ | Prim _ -> tm
  in
  let rec replace_pf depth proof =
    match proof with
    | PTpAp (body, tp) -> PTpAp (replace_pf depth body, tp)
    | PTmAp (body, tm) ->
        PTmAp (replace_pf depth body, replace_tm depth tm |> normalize)
    | PPfAp (left, right) -> PPfAp (replace_pf depth left, replace_pf depth right)
    | PLam (prop, body) ->
        PLam (replace_tm depth prop |> normalize, replace_pf depth body)
    | TLam (tp, body) -> TLam (tp, replace_pf (depth + 1) body)
    | Hyp _ | Known _ -> proof
  in
  replace_pf 0 proof

let native_core_replace_terms_in_tm replacements tm =
  let normalize tm =
    tm
    |> native_core_normalize_bool_constants
    |> tm_beta_eta_norm
  in
  let rec replace_tm depth tm =
    match
      List.find_opt
        (fun (needle, _) -> tm = tmshift 0 depth needle)
        replacements
    with
    | Some (_, replacement) -> tmshift 0 depth replacement |> normalize
    | None ->
        match tm with
        | TpAp (body, tp) -> TpAp (replace_tm depth body, tp)
        | Ap (left, right) -> Ap (replace_tm depth left, replace_tm depth right)
        | Lam (tp, body) -> Lam (tp, replace_tm (depth + 1) body)
        | Imp (left, right) -> Imp (replace_tm depth left, replace_tm depth right)
        | All (tp, body) -> All (tp, replace_tm (depth + 1) body)
        | DB _ | TmH _ | Prim _ -> tm
  in
  replace_tm 0 tm |> normalize

let native_core_replace_terms_in_pf replacements proof =
  let normalize tm =
    tm
    |> native_core_normalize_bool_constants
    |> tm_beta_eta_norm
  in
  let rec replace_tm depth tm =
    match
      List.find_opt
        (fun (needle, _) -> tm = tmshift 0 depth needle)
        replacements
    with
    | Some (_, replacement) -> tmshift 0 depth replacement |> normalize
    | None ->
        match tm with
        | TpAp (body, tp) -> TpAp (replace_tm depth body, tp)
        | Ap (left, right) -> Ap (replace_tm depth left, replace_tm depth right)
        | Lam (tp, body) -> Lam (tp, replace_tm (depth + 1) body)
        | Imp (left, right) -> Imp (replace_tm depth left, replace_tm depth right)
        | All (tp, body) -> All (tp, replace_tm (depth + 1) body)
        | DB _ | TmH _ | Prim _ -> tm
  in
  let rec replace_pf depth proof =
    match proof with
    | PTpAp (body, tp) -> PTpAp (replace_pf depth body, tp)
    | PTmAp (body, tm) ->
        PTmAp (replace_pf depth body, replace_tm depth tm |> normalize)
    | PPfAp (left, right) -> PPfAp (replace_pf depth left, replace_pf depth right)
    | PLam (prop, body) ->
        PLam (replace_tm depth prop |> normalize, replace_pf depth body)
    | TLam (tp, body) -> TLam (tp, replace_pf (depth + 1) body)
    | Hyp _ | Known _ -> proof
  in
  replace_pf 0 proof

let native_core_pf_contains_term_symbol names proof =
  let rec tm_contains = function
    | TmH name -> List.mem name names
    | TpAp (body, _) -> tm_contains body
    | Ap (left, right) | Imp (left, right) ->
        tm_contains left || tm_contains right
    | Lam (_, body) | All (_, body) -> tm_contains body
    | DB _ | Prim _ -> false
  in
  let rec pf_contains = function
    | PTpAp (body, _) -> pf_contains body
    | PTmAp (body, tm) -> pf_contains body || tm_contains tm
    | PPfAp (left, right) -> pf_contains left || pf_contains right
    | PLam (prop, body) -> tm_contains prop || pf_contains body
    | TLam (_, body) -> pf_contains body
    | Hyp _ | Known _ -> false
  in
  pf_contains proof

let native_core_tm_term_symbol_detail names tm =
  let rec tm_detail path enclosing = function
    | TmH name when List.mem name names ->
        Some
          (path
           ^ ": introduced term symbol "
           ^ name
           ^ " in term "
           ^ tm_to_str (TmH name)
           ^ "; enclosing term "
           ^ tm_to_str enclosing)
    | TpAp (body, _) -> tm_detail (path ^ ".tp") enclosing body
    | Ap (left, right) ->
        begin match tm_detail (path ^ ".left") enclosing left with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".right") enclosing right
        end
    | Lam (_, body) -> tm_detail (path ^ ".body") body body
    | Imp (left, right) ->
        begin match tm_detail (path ^ ".left") enclosing left with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".right") enclosing right
        end
    | All (_, body) -> tm_detail (path ^ ".body") body body
    | DB _ | TmH _ | Prim _ -> None
  in
  tm_detail "root" tm tm

let native_core_pf_term_symbol_detail names proof =
  let rec tm_detail path enclosing = function
    | TmH name when List.mem name names ->
        Some
          (path
           ^ ": introduced term symbol "
           ^ name
           ^ " in term "
           ^ tm_to_str (TmH name)
           ^ "; enclosing term "
           ^ tm_to_str enclosing)
    | TpAp (body, _) -> tm_detail (path ^ ".tp") enclosing body
    | Ap (left, right) ->
        begin match tm_detail (path ^ ".left") enclosing left with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".right") enclosing right
        end
    | Lam (_, body) -> tm_detail (path ^ ".body") body body
    | Imp (left, right) ->
        begin match tm_detail (path ^ ".left") enclosing left with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".right") enclosing right
        end
    | All (_, body) -> tm_detail (path ^ ".body") body body
    | DB _ | TmH _ | Prim _ -> None
  in
  let rec pf_detail path = function
    | PTpAp (body, _) -> pf_detail (path ^ ".tp") body
    | PTmAp (body, tm) ->
        begin match pf_detail (path ^ ".proof") body with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".term") tm tm
        end
    | PPfAp (left, right) ->
        begin match pf_detail (path ^ ".left") left with
        | Some _ as found -> found
        | None -> pf_detail (path ^ ".right") right
        end
    | PLam (prop, body) ->
        begin match tm_detail (path ^ ".prop") prop prop with
        | Some _ as found -> found
        | None -> pf_detail (path ^ ".body") body
        end
    | TLam (_, body) -> pf_detail (path ^ ".body") body
    | Hyp _ | Known _ -> None
  in
  pf_detail "root" proof

let native_core_pf_contains_choice_witness proof =
  native_core_pf_contains_term_symbol
    [
      "Eps_i";
      "Eps_prop";
      "Eps_set_prop";
      "Eps_set_set";
      "Eps_set_set_prop";
    ]
    proof

let native_core_pf_choice_witness_detail proof =
  let choice_symbols =
    [
      "Eps_i";
      "Eps_prop";
      "Eps_set_prop";
      "Eps_set_set";
      "Eps_set_set_prop";
    ]
  in
  let rec tm_detail path enclosing = function
    | TmH name when List.mem name choice_symbols ->
        Some
          (path
           ^ ": certificate-local choice witness "
           ^ name
           ^ " in term "
           ^ tm_to_str enclosing)
    | TmH _ | DB _ | Prim _ -> None
    | TpAp (body, _) -> tm_detail (path ^ ".tp") enclosing body
    | Ap (left, right) ->
        begin match tm_detail (path ^ ".left") enclosing left with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".right") enclosing right
        end
    | Lam (_, body) | All (_, body) ->
        tm_detail (path ^ ".body") enclosing body
    | Imp (left, right) ->
        begin match tm_detail (path ^ ".left") enclosing left with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".right") enclosing right
        end
  in
  let tm_detail path tm = tm_detail path tm tm in
  let rec pf_detail path = function
    | PTpAp (body, _) -> pf_detail (path ^ ".tp") body
    | PTmAp (body, tm) ->
        begin match pf_detail (path ^ ".proof") body with
        | Some _ as found -> found
        | None -> tm_detail (path ^ ".term") tm
        end
    | PPfAp (left, right) ->
        begin match pf_detail (path ^ ".left") left with
        | Some _ as found -> found
        | None -> pf_detail (path ^ ".right") right
        end
    | PLam (prop, body) ->
        begin match tm_detail (path ^ ".prop") prop with
        | Some _ as found -> found
        | None -> pf_detail (path ^ ".body") body
        end
    | TLam (_, body) -> pf_detail (path ^ ".body") body
    | Hyp _ | Known _ -> None
  in
  pf_detail "root" proof

let native_core_pf_choice_known_detail proof =
  let choice_knowns =
    [
      "Eps_i_ax";
      "vampire_exists_prop_choice";
      "vampire_exists_set_prop_choice";
      "vampire_exists_set_set_choice";
      "vampire_exists_set_set_prop_choice";
    ]
  in
  let rec pf_detail path = function
    | Known name when List.mem name choice_knowns ->
        Some (path ^ ": certificate-local choice theorem " ^ name)
    | PTpAp (body, _) -> pf_detail (path ^ ".tp") body
    | PTmAp (body, _) -> pf_detail (path ^ ".proof") body
    | PPfAp (left, right) ->
        begin match pf_detail (path ^ ".left") left with
        | Some _ as found -> found
        | None -> pf_detail (path ^ ".right") right
        end
    | PLam (_, body) -> pf_detail (path ^ ".body") body
    | TLam (_, body) -> pf_detail (path ^ ".body") body
    | Hyp _ | Known _ -> None
  in
  pf_detail "root" proof

let native_core_abstract_shifted_subproof needle proof =
  let replaced = ref false in
  let rec replace term_depth proof_depth proof =
    let expected =
      needle
      |> pftmshift 0 term_depth
      |> pfshift proof_depth 1
    in
    if proof = expected then begin
      replaced := true;
      Hyp proof_depth
    end else
      match proof with
      | PTpAp (body, tp) -> PTpAp (replace term_depth proof_depth body, tp)
      | PTmAp (body, tm) -> PTmAp (replace term_depth proof_depth body, tm)
      | PPfAp (left, right) ->
          PPfAp
            (replace term_depth proof_depth left,
             replace term_depth proof_depth right)
      | PLam (prop, body) ->
          PLam (prop, replace term_depth (proof_depth + 1) body)
      | TLam (tp, body) ->
          TLam (tp, replace (term_depth + 1) proof_depth body)
      | Hyp _ | Known _ -> proof
  in
  let proof = replace 0 0 proof in
  if !replaced then Some proof else None

let native_core_skolem_refutation_cps_proof
    ?abstract_result_proof
    ?result_to_target_body
    ?result_assumption_prop
    ?result_assumption_step_variables
    ?skolem_proof_object
    ?(split_replacements=[])
    id variables parent_step_variables result_step_variables source subst result
    result_checked_prop parent_proof result_proof final_proof target_prop =
  let result_assumption_prop =
    match result_assumption_prop with
    | Some prop -> prop
    | None -> result_checked_prop
  in
  let result_assumption_step_variables =
    match result_assumption_step_variables with
    | Some step_variables -> step_variables
    | None -> result_step_variables
  in
  let witness_symbols =
    subst
    |> List.map
         (function
           | _, TmH symbol -> symbol
           | _ ->
               error
                 (id ^ ": native preprocess Skolem CPS currently supports only nullary introduced witnesses"))
  in
  let rec source_exists_types = function
    | Ap (TmH "vampire_exists_prop", Lam (tp, body)) ->
        tp :: source_exists_types body
    | Ap (Ap (TmH "vampire_and", left), right)
    | Ap (Ap (TmH "vampire_or", left), right)
    | Imp (left, right) ->
        source_exists_types left @ source_exists_types right
    | All (_, body)
    | Lam (_, body)
    | TpAp (body, _)
    | Ap (TmH "vampire_exists_prop", body)
    | Ap (TmH "vLAM", body) ->
        source_exists_types body
    | Ap (left, right) ->
        source_exists_types left @ source_exists_types right
    | _ -> []
  in
  let witness_infos =
    try List.map2 (fun symbol tp -> (symbol, tp)) witness_symbols (source_exists_types source)
    with Invalid_argument _ ->
      error
        (id ^ ": native preprocess Skolem CPS witness type count does not match substitution count")
  in
  let parent_proof = native_core_close_pf variables parent_proof in
  let result_proof = native_core_close_pf variables result_proof in
  let final_proof = native_core_close_pf variables final_proof in
  let rec source_exists_count = function
    | Ap (TmH "vampire_exists_prop", Lam (_, body)) ->
        1 + source_exists_count body
    | Ap (Ap (TmH "vampire_and", left), right)
    | Ap (Ap (TmH "vampire_or", left), right) ->
        source_exists_count left + source_exists_count right
    | Imp (left, right) ->
        source_exists_count left + source_exists_count right
    | All (_, body)
    | Lam (_, body) ->
        source_exists_count body
    | TpAp (body, _)
    | Ap (TmH "vampire_exists_prop", body)
    | Ap (TmH "vLAM", body) ->
        source_exists_count body
    | Ap (left, right) ->
        source_exists_count left + source_exists_count right
    | _ -> 0
  in
  if source_exists_count source <> List.length witness_symbols then
    error
      (id ^ ": native preprocess Skolem CPS source existential count does not match substitution count");
  let skolem_branch_contracts =
    match skolem_proof_object with
    | Some proof_object -> proof_object.Vampire_kernel_syntax.skolem_proof_branches
    | None -> []
  in
  let branch_witness_symbols branch =
    branch.Vampire_kernel_syntax.skolem_branch_introduced_witnesses
    |> List.map
         (fun witness ->
            witness.Vampire_kernel_syntax.skolem_witness_symbol)
  in
  let witness_set symbols =
    List.sort_uniq String.compare symbols
  in
  let witness_set_text symbols =
    match witness_set symbols with
    | [] -> "-"
    | symbols -> String.concat "," symbols
  in
  let formula_witness_symbols formula =
    witness_symbols
    |> List.filter (fun symbol -> tm_contains_symbol symbol formula)
    |> witness_set
  in
  let debug_skolem_branch_contracts () =
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1"
       && skolem_branch_contracts <> [] then
      List.iter
        (fun branch ->
           let source_exists =
             match branch.Vampire_kernel_syntax.skolem_branch_source_formula with
             | Some formula -> source_exists_count formula
             | None -> -1
           in
           let target_exists =
             match branch.Vampire_kernel_syntax.skolem_branch_target_formula with
             | Some formula -> source_exists_count formula
             | None -> -1
           in
           let source_symbols =
             match branch.Vampire_kernel_syntax.skolem_branch_source_formula with
             | Some formula -> formula_witness_symbols formula
             | None -> []
           in
           let target_symbols =
             match branch.Vampire_kernel_syntax.skolem_branch_target_formula with
             | Some formula -> formula_witness_symbols formula
             | None -> []
           in
           prerr_endline
             (Printf.sprintf
                "%s: native preprocess Skolem CPS branch contract #%d unit=%s parent=%s binders=%s parent_instantiations=%d witnesses=%s source_exists=%d target_exists=%d source_symbols=%s target_symbols=%s"
                id
                branch.Vampire_kernel_syntax.skolem_branch_index
                (match branch.Vampire_kernel_syntax.skolem_branch_unit with
                 | Some unit -> unit
                 | None -> "?")
                (match branch.Vampire_kernel_syntax.skolem_branch_parent_index with
                 | Some index -> string_of_int index
                 | None -> "?")
                (match branch.Vampire_kernel_syntax.skolem_branch_binder_count with
                 | Some count -> string_of_int count
                 | None -> "?")
                (List.length
                   branch.Vampire_kernel_syntax.skolem_branch_parent_instantiations)
                (witness_set_text (branch_witness_symbols branch))
                source_exists
                target_exists
                (witness_set_text source_symbols)
                (witness_set_text target_symbols)))
        skolem_branch_contracts
  in
  begin match skolem_proof_object with
  | Some proof_object ->
      let contract =
        proof_object.Vampire_kernel_syntax.skolem_proof_contract
      in
      let contract_witnesses =
        contract.Vampire_kernel_syntax.skolem_introduced_witnesses
        |> List.map
             (fun witness ->
                witness.Vampire_kernel_syntax.skolem_witness_symbol)
        |> witness_set
      in
      let substitution_witnesses = witness_set witness_symbols in
      if contract_witnesses <> substitution_witnesses then
        error
          (Printf.sprintf
             "%s: native preprocess Skolem CPS proof-object witnesses %s do not match substitution witnesses %s"
             id
             (witness_set_text contract_witnesses)
             (witness_set_text substitution_witnesses))
  | None -> ()
  end;
  let branch_matches_formula formula = function
    | Some branch_formula ->
        native_core_normalize_bool_constants branch_formula |> tm_beta_eta_norm
        =
        (native_core_normalize_bool_constants formula |> tm_beta_eta_norm)
    | None -> false
  in
  let debug_skolem_branch_candidates label term_depth proof_depth source result witnesses =
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1"
       && skolem_branch_contracts <> [] then
      let active_witness_set = witness_set witnesses in
      let source_exists = source_exists_count source in
      let result_symbols = formula_witness_symbols result in
      let candidate_labels =
        skolem_branch_contracts
        |> List.filter_map
             (fun branch ->
                let branch_witnesses =
                  branch_witness_symbols branch |> witness_set
                in
                let source_match =
                  branch_matches_formula
                    source
                    branch.Vampire_kernel_syntax.skolem_branch_source_formula
                in
                let target_match =
                  branch_matches_formula
                    result
                    branch.Vampire_kernel_syntax.skolem_branch_target_formula
                in
                let witness_match = branch_witnesses = active_witness_set in
                let target_symbols_match =
                  branch_witnesses = [] || branch_witnesses = result_symbols
                in
                if source_match || target_match || witness_match || target_symbols_match then
                  Some
                    (Printf.sprintf
                       "#%d%s%s%s%s[w=%s]"
                       branch.Vampire_kernel_syntax.skolem_branch_index
                       (if source_match then ":source" else "")
                       (if target_match then ":target" else "")
                       (if witness_match then ":witness" else "")
                       (if target_symbols_match then ":target-symbols" else "")
                       (witness_set_text branch_witnesses))
                else
                  None)
      in
      prerr_endline
        (Printf.sprintf
           "%s: native preprocess Skolem CPS %s branch candidates at term_depth=%d proof_depth=%d source_exists=%d active_witnesses=%s result_symbols=%s -> %s"
           id label term_depth proof_depth source_exists
           (witness_set_text active_witness_set)
           (witness_set_text result_symbols)
           (match candidate_labels with
            | [] -> "none"
            | labels -> String.concat " " labels))
  in
  debug_skolem_branch_contracts ();
  let parent_instantiations =
    match skolem_proof_object with
    | Some proof_object ->
        let contract =
          proof_object.Vampire_kernel_syntax.skolem_proof_contract
        in
        contract.Vampire_kernel_syntax.skolem_parent_instantiations
    | None -> []
  in
  let parent_proof =
    let certificate_step_argument (name, tp) instantiation =
      if instantiation.Vampire_kernel_syntax.skolem_parent_inst_variable <> name
         || instantiation.Vampire_kernel_syntax.skolem_parent_inst_type <> tp then
        error
          (Printf.sprintf
             "%s: native preprocess Skolem CPS parent instantiation %d does not match parent step variable %s"
             id
             instantiation.Vampire_kernel_syntax.skolem_parent_inst_index
             name);
      match tp with
      | Prop -> native_core_false
      | _ ->
          native_core_close_tm variables
            instantiation.Vampire_kernel_syntax.skolem_parent_inst_term
          |> tm_beta_eta_norm
    in
    let legacy_dummy_step_argument tp =
      match tp with
      | Prop -> native_core_false
      | _ ->
          error
            (id
             ^ ": native preprocess Skolem CPS cannot open non-prop parent step variable")
    in
    match parent_step_variables, parent_instantiations with
    | [], [] -> parent_proof
    | _, [] ->
        List.fold_left
          (fun proof (_, tp) -> PTmAp (proof, legacy_dummy_step_argument tp))
          parent_proof
          parent_step_variables
    | _ ->
        if List.length parent_step_variables <> List.length parent_instantiations then
          error
            (Printf.sprintf
               "%s: native preprocess Skolem CPS has %d parent step variables but %d parent instantiations"
               id
               (List.length parent_step_variables)
               (List.length parent_instantiations));
        List.fold_left2
          (fun proof variable instantiation ->
             PTmAp (proof, certificate_step_argument variable instantiation))
          parent_proof
          parent_step_variables
          parent_instantiations
  in
  let result_to_target_source_prop, base_result_to_target =
    match result_to_target_body with
    | Some body -> result_assumption_prop, PLam (result_assumption_prop, body)
    | None ->
        let shifted_final = pfshift 0 1 final_proof in
        let abstracted =
          match abstract_result_proof with
          | Some abstract_result_proof ->
              abstract_result_proof result_checked_prop result_proof shifted_final
          | None ->
              native_core_abstract_shifted_subproof result_proof shifted_final
        in
        match abstracted with
        | Some body -> result_checked_prop, PLam (result_checked_prop, body)
        | None ->
            error
              (id ^ ": native preprocess Skolem CPS could not isolate the Skolem result proof in the refutation")
  in
  let result_to_target =
    if result_assumption_prop = result_to_target_source_prop then
      base_result_to_target
    else
      let legacy_result_proof =
        native_core_bind_result_step_variables
          variables
          result_step_variables
          (Hyp 0)
      in
      PLam
        (result_assumption_prop,
         PPfAp (pfshift 0 1 base_result_to_target, legacy_result_proof))
  in
  let result_to_target =
    native_core_close_pf variables result_to_target
  in
  let target_prop = tm_beta_eta_norm target_prop in
  let formula_prop_with_ordered_replacements close_depth ordered_replacements formula =
    native_core_formula_prop formula
    |> native_core_replace_witness_symbols_in_tm ordered_replacements
    |> native_core_close_tm ~depth:close_depth variables
    |> tm_beta_eta_norm
  in
  let formula_prop_with_replacements ?close_depth ?(fallback_replacements=[]) replacements formula =
    let close_depth =
      match close_depth with
      | Some close_depth -> close_depth
      | None -> List.length replacements
    in
    formula_prop_with_ordered_replacements
      close_depth
      (replacements @ fallback_replacements)
      formula
  in
  let raw_formula_with_replacements close_depth replacements fallback_replacements formula =
    formula
    |> native_core_normalize_bool_constants
    |> tm_beta_eta_norm
    |> native_core_replace_witness_symbols_in_tm (replacements @ fallback_replacements)
    |> native_core_close_tm ~depth:close_depth variables
    |> tm_beta_eta_norm
  in
  let select_replacements_to_match label close_depth replacements fallback_replacements source result =
    let source_prop =
      formula_prop_with_replacements ~close_depth ~fallback_replacements replacements source
    in
    let result_prop =
      formula_prop_with_replacements ~close_depth ~fallback_replacements replacements result
    in
    if source_prop = result_prop then
      Some (replacements, source_prop, result_prop)
    else
      let candidate_symbols =
        witness_symbols
        |> List.filter (fun symbol -> tm_contains_symbol symbol result)
      in
      let rec try_overrides = function
        | [] -> None
        | symbol :: rest ->
            let replacements_with_override =
              (symbol, DB 0) :: replacements
            in
            let candidate_prop =
              formula_prop_with_ordered_replacements
                close_depth
                (replacements_with_override @ fallback_replacements)
                result
            in
            if source_prop = candidate_prop then begin
              if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                prerr_endline
                  (id
                   ^ ": native preprocess Skolem CPS refreshed active witness "
                   ^ symbol
                   ^ " for "
                   ^ label);
              Some (replacements_with_override, source_prop, candidate_prop)
            end else
              try_overrides rest
      in
      try_overrides candidate_symbols
  in
  let proof_with_replacements term_replacements replacements fallback_replacements proof =
    let all_replacements = replacements @ fallback_replacements in
    let covered_witness_symbols = List.map fst all_replacements in
    let active_split_replacements =
      split_replacements
      |> List.filter
           (fun (_name, replacement) ->
              let replacement =
                native_core_replace_witness_symbols_in_tm all_replacements replacement
              in
              not
                (List.exists
                   (fun symbol ->
                      not (List.mem symbol covered_witness_symbols)
                      && tm_contains_symbol symbol replacement)
                   witness_symbols))
    in
    native_core_replace_witness_symbols_in_pf
      (active_split_replacements @ replacements @ fallback_replacements)
      proof
    |> native_core_replace_terms_in_pf term_replacements
  in
  let debug_witness_tm label tm =
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
      witness_symbols
      |> List.find_opt (fun symbol -> tm_contains_symbol symbol tm)
      |> Option.iter
           (fun symbol ->
              prerr_endline
                (id
                 ^ ": native preprocess Skolem CPS "
                 ^ label
                 ^ " still contains introduced symbol "
                 ^ symbol
                 ^ ": "
                 ^ tm_to_str tm))
  in
	  let debug_witness_pf label proof =
	    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
	      match native_core_pf_term_symbol_detail witness_symbols proof with
      | Some detail ->
          prerr_endline
            (id
             ^ ": native preprocess Skolem CPS "
             ^ label
             ^ " still contains introduced symbol: "
	             ^ detail)
	      | None -> ()
	  in
		  let shift_captured_pf captured_term_depth captured_proof_depth term_depth proof_depth proof =
		    if term_depth < captured_term_depth || proof_depth < captured_proof_depth then
		      error (id ^ ": native preprocess Skolem CPS internal continuation depth moved outward");
		    proof
		    |> pftmshift 0 (term_depth - captured_term_depth)
		    |> pfshift 0 (proof_depth - captured_proof_depth)
		  in
		  let shift_captured_tm captured_term_depth term_depth tm =
		    if term_depth < captured_term_depth then
		      error (id ^ ": native preprocess Skolem CPS internal proposition depth moved outward");
		    tmshift 0 (term_depth - captured_term_depth) tm
		  in
	  let short_tm_debug tm =
	    let text = tm_to_str tm in
	    if String.length text <= 220 then text
	    else String.sub text 0 220 ^ "..."
	  in
	  let rec first_tm_difference path left right =
	    if left = right then None
	    else
	      match left, right with
	      | TpAp (left_body, left_tp), TpAp (right_body, right_tp) ->
	          if left_tp <> right_tp then Some (path ^ ".type", left, right)
	          else first_tm_difference (path ^ ".tpap") left_body right_body
	      | Ap (left_fun, left_arg), Ap (right_fun, right_arg) ->
	          begin match first_tm_difference (path ^ ".fun") left_fun right_fun with
	          | Some _ as found -> found
	          | None -> first_tm_difference (path ^ ".arg") left_arg right_arg
	          end
	      | Lam (left_tp, left_body), Lam (right_tp, right_body)
	      | All (left_tp, left_body), All (right_tp, right_body) ->
	          if left_tp <> right_tp then Some (path ^ ".binder-type", left, right)
	          else first_tm_difference (path ^ ".body") left_body right_body
	      | Imp (left_a, left_b), Imp (right_a, right_b) ->
	          begin match first_tm_difference (path ^ ".left") left_a right_a with
	          | Some _ as found -> found
	          | None -> first_tm_difference (path ^ ".right") left_b right_b
	          end
	      | _ -> Some (path, left, right)
	  in
	  let debug_prop_pair label term_depth proof_depth left right =
	    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" && left <> right then begin
	      prerr_endline
	        (id
	         ^ ": native preprocess Skolem CPS "
	         ^ label
	         ^ " proposition mismatch at term_depth="
	         ^ string_of_int term_depth
	         ^ " proof_depth="
	         ^ string_of_int proof_depth
	         ^ (if tmshift 0 1 left = right then
	              " (right is tmshift +1 of left)"
	            else if left = tmshift 0 1 right then
	              " (left is tmshift +1 of right)"
	            else
	              ""));
	      begin match first_tm_difference "root" left right with
	      | Some (path, diff_left, diff_right) ->
	          prerr_endline
	            (id ^ ": native preprocess Skolem CPS " ^ label ^ " first diff path: " ^ path);
	          prerr_endline
	            (id ^ ": native preprocess Skolem CPS " ^ label ^ " left: " ^ short_tm_debug diff_left);
	          prerr_endline
	            (id ^ ": native preprocess Skolem CPS " ^ label ^ " right: " ^ short_tm_debug diff_right)
	      | None -> ()
	      end
	    end
	  in
	  let debug_replacement_set label term_depth replacements fallback_replacements =
	    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
	      let short_tm tm =
	        let text = tm_to_str tm in
	        if String.length text <= 180 then text
	        else String.sub text 0 180 ^ "..."
	      in
	      prerr_endline
	        (id
	         ^ ": native preprocess Skolem CPS "
	         ^ label
	         ^ " replacements at term_depth="
	         ^ string_of_int term_depth
	         ^ " active=["
	         ^ String.concat ", "
	             (List.map
	                (fun (name, tm) -> name ^ ":=" ^ short_tm tm)
	                replacements)
	         ^ "] fallback=["
	         ^ String.concat ", "
	             (List.map
	                (fun (name, tm) -> name ^ ":=" ^ short_tm tm)
	                fallback_replacements)
	         ^ "]")
	  in
	  let unshift_and_component tm =
	    try Some (tmshift 0 (-1) tm |> tm_beta_eta_norm)
	    with _ -> None
	  in
	  let native_core_and_components_of_prop prop =
	    match tm_beta_eta_norm prop with
	    | All (Prop, Imp (Imp (left, Imp (right, DB 0)), DB 0)) ->
	        begin match unshift_and_component left, unshift_and_component right with
	        | Some left, Some right -> Some (left, right)
	        | _ -> None
	        end
	    | _ -> None
	  in
		  let debug_conjunction_contract label term_depth proof_depth expected rebuilt =
		    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
	      if expected = rebuilt then
	        prerr_endline
	          (id
	           ^ ": native preprocess Skolem CPS "
	           ^ label
	           ^ " conjunction contract OK at term_depth="
	           ^ string_of_int term_depth
	           ^ " proof_depth="
	           ^ string_of_int proof_depth)
	      else begin
	        debug_prop_pair
	          (label ^ " conjunction contract")
	          term_depth
	          proof_depth
	          expected
	          rebuilt;
	        begin match
	          native_core_and_components_of_prop expected,
	          native_core_and_components_of_prop rebuilt
	        with
	        | Some (expected_left, expected_right), Some (rebuilt_left, rebuilt_right) ->
	            debug_prop_pair
	              (label ^ " expected-left/rebuilt-left")
	              term_depth proof_depth expected_left rebuilt_left;
	            debug_prop_pair
	              (label ^ " expected-right/rebuilt-right")
	              term_depth proof_depth expected_right rebuilt_right
	        | _ ->
	            prerr_endline
	              (id
	               ^ ": native preprocess Skolem CPS "
	               ^ label
	               ^ " could not decompose conjunction contract")
	        end
		      end
		    end
		  in
			  let result_to_target_builder term_depth proof_depth term_replacements replacements fallback_replacements =
	    let result_prop =
	      formula_prop_with_replacements
	        ~close_depth:term_depth
	        ~fallback_replacements
	        replacements
	        result
	    in
	    let checked_result_prop =
	      tmshift 0 term_depth result_assumption_prop
	      |> native_core_replace_witness_symbols_in_tm
	           (replacements @ fallback_replacements)
	      |> native_core_replace_terms_in_tm term_replacements
	    in
	    let result_prop_after_term_replacements =
	      native_core_replace_terms_in_tm term_replacements result_prop
	    in
	    debug_prop_pair
	      "result-to-target replaced-checked/current"
	      term_depth
	      proof_depth
	      checked_result_prop
	      result_prop_after_term_replacements;
	    if checked_result_prop <> result_prop_after_term_replacements
	       && Sys.getenv_opt "MEGALODON_CERT_FAIL_FAST_SKOLEM_CONTRACT" = Some "1" then
	      error
	        (id
	         ^ ": native preprocess Skolem CPS result-to-target continuation contract mismatch");
	    let shifted_result_to_target =
	      result_to_target
	      |> pftmshift 0 term_depth
	      |> pfshift 0 (proof_depth + 1)
	    in
	    let bound_result_proof =
	      native_core_bind_result_step_variables
	        variables
	        result_assumption_step_variables
	        (Hyp 0)
	      |> proof_with_replacements
	           term_replacements
	           replacements
	           fallback_replacements
	    in
	    PLam
	      (result_prop,
	       PPfAp (shifted_result_to_target, bound_result_proof))
	  in
  let rec eliminate term_depth proof_depth term_replacements replacements fallback_replacements witnesses source result proof result_to_target_builder =
    debug_skolem_branch_candidates
      "enter"
      term_depth
      proof_depth
      source
      result
      witnesses;
    match source, result, witnesses with
    | Ap (TmH "vampire_exists_prop", Lam (tp, body)), _, witness :: rest ->
        debug_skolem_branch_candidates
          ("exists " ^ witness)
          term_depth
          proof_depth
          source
          result
          witnesses;
        let replacements_under_binder =
          (witness, DB 0)
          :: List.map (fun (name, tm) -> (name, tmshift 0 1 tm)) replacements
        in
        let fallback_replacements_under_binder =
          let shifted =
            List.map
              (fun (name, tm) -> (name, tmshift 0 1 tm))
              fallback_replacements
          in
          let covered =
            List.map fst replacements_under_binder
          in
          let sibling_fallbacks =
            witness_infos
            |> List.filter_map
                 (fun (symbol, symbol_tp) ->
                    if symbol_tp = tp && not (List.mem symbol covered) then
                      Some (symbol, DB 0)
                    else
                      None)
          in
          let rec keep_first seen = function
            | [] -> []
            | (name, tm) :: rest when List.mem name seen ->
                keep_first seen rest
            | (name, tm) :: rest ->
                (name, tm) :: keep_first (name :: seen) rest
          in
          keep_first [] (shifted @ sibling_fallbacks)
        in
        let term_replacements_under_binder =
          List.map
            (fun (needle, replacement) ->
               (tmshift 0 1 needle, tmshift 0 1 replacement))
            term_replacements
        in
        let body_prop =
          native_core_formula_prop body
          |> native_core_replace_witness_symbols_in_tm replacements_under_binder
          |> native_core_close_tm ~depth:(List.length replacements_under_binder) variables
          |> native_core_normalize_bool_constants
          |> tm_beta_eta_norm
        in
        let epsilon_witness =
          Ap (TmH (native_core_eps_symbol tp), Lam (tp, body_prop))
          |> native_core_normalize_bool_constants
          |> tm_beta_eta_norm
        in
        let term_replacements_under_binder =
          (epsilon_witness, DB 0) :: term_replacements_under_binder
        in
        let continuation =
          TLam
            (tp,
	             PLam
	               (body_prop,
	                eliminate
	                  (term_depth + 1)
	                  (proof_depth + 1)
	                  term_replacements_under_binder
	                  replacements_under_binder
	                  fallback_replacements_under_binder
                  rest
	                  body
	                  result
	                  (Hyp 0)
	                  result_to_target_builder))
	        in
	        let candidate = PPfAp (PTmAp (proof, target_prop), continuation) in
	        debug_witness_pf ("exists-continuation " ^ witness) candidate;
	        candidate
    | Ap (Ap (TmH "vampire_and", source_left), source_right),
      Ap (Ap (TmH "vampire_and", result_left), result_right),
      _ ->
        debug_skolem_branch_candidates
          "and"
          term_depth
          proof_depth
          source
          result
          witnesses;
        let left_count = source_exists_count source_left in
        let right_count = source_exists_count source_right in
        let rec split_witnesses n acc rest =
          if n = 0 then (List.rev acc, rest)
          else
            match rest with
            | witness :: rest -> split_witnesses (n - 1) (witness :: acc) rest
            | [] ->
                error
                  (id ^ ": native preprocess Skolem CPS source has fewer existential binders than substitutions")
        in
        if left_count > 0 && right_count > 0 then
          let left_witnesses, right_witnesses =
            split_witnesses left_count [] witnesses
          in
          let captured_term_depth = term_depth in
          let captured_proof_depth = proof_depth in
          let source_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_left in
          let source_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_right in
          let source_left_proof =
            native_core_and_elim_left source_left_prop source_right_prop proof
          in
          let source_right_proof =
            native_core_and_elim_right source_left_prop source_right_prop proof
          in
          let left_result_to_target_builder term_depth proof_depth term_replacements replacements fallback_replacements =
            let captured_result_left_term_depth = term_depth in
            let captured_result_left_proof_depth = proof_depth + 1 in
            let captured_result_left_prop =
              formula_prop_with_replacements
                ~close_depth:term_depth
                ~fallback_replacements
                replacements
                result_left
            in
            let result_left_proof = Hyp 0 in
            let right_source_proof =
              shift_captured_pf
                captured_term_depth captured_proof_depth
                term_depth (proof_depth + 1) source_right_proof
            in
            let right_result_to_target_builder term_depth proof_depth term_replacements replacements fallback_replacements =
              let result_left_prop =
                shift_captured_tm
                  captured_result_left_term_depth
                  term_depth
                  captured_result_left_prop
              in
              let result_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_right in
              PLam
                (result_right_prop,
                 let rebuilt =
                   native_core_and_intro
                     result_left_prop
                     result_right_prop
                     (shift_captured_pf
                        captured_result_left_term_depth
                        captured_result_left_proof_depth
                        term_depth (proof_depth + 1) result_left_proof)
                     (Hyp 0)
                 in
                 PPfAp
                   (result_to_target_builder
                      term_depth (proof_depth + 1)
                      term_replacements replacements fallback_replacements,
                    rebuilt))
            in
            PLam
              (formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_left,
               let delayed_shift = term_depth - captured_term_depth in
               let delayed_source_right =
                 if delayed_shift = 0 then source_right
                 else tmshift 0 delayed_shift source_right
               in
               let delayed_result_right =
                 if delayed_shift = 0 then result_right
                 else tmshift 0 delayed_shift result_right
               in
               eliminate
                 term_depth
                 (proof_depth + 1)
                 term_replacements
                 replacements
                 fallback_replacements
                 right_witnesses
                 delayed_source_right
                 delayed_result_right
                 right_source_proof
                 right_result_to_target_builder)
          in
          eliminate
            term_depth
            proof_depth
            term_replacements
            replacements
            fallback_replacements
            left_witnesses
            source_left
            result_left
            source_left_proof
            left_result_to_target_builder
	        else if left_count > 0 then
	          let captured_term_depth = term_depth in
	          let captured_proof_depth = proof_depth in
	          let source_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_left in
	          let source_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_right in
	          let source_left_proof =
	            native_core_and_elim_left source_left_prop source_right_prop proof
	          in
	          let source_right_proof =
	            native_core_and_elim_right source_left_prop source_right_prop proof
	          in
            let captured_result_right_prop =
              formula_prop_with_replacements
                ~close_depth:term_depth
                ~fallback_replacements
                replacements
                result_right
            in
	            debug_prop_pair
	              "and-left-count unchanged-right"
	              term_depth
	              proof_depth
	              source_right_prop
	              captured_result_right_prop;
	            if source_right_prop <> captured_result_right_prop then
	              debug_replacement_set
	                "and-left-count unchanged-right"
	                term_depth replacements fallback_replacements;
			          let left_result_to_target_builder term_depth proof_depth term_replacements replacements fallback_replacements =
		            let result_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_left in
		            let result_right_prop =
                  shift_captured_tm
                    captured_term_depth
                    term_depth
                    captured_result_right_prop
                in
		            PLam
		              (result_left_prop,
		               let rebuilt =
	                 debug_conjunction_contract
	                   "and-left-count"
	                   term_depth
	                   (proof_depth + 1)
	                   (formula_prop_with_replacements
	                      ~close_depth:term_depth
	                      ~fallback_replacements
	                      replacements
	                      result)
	                   (native_core_and result_left_prop result_right_prop |> tm_beta_eta_norm);
	                 native_core_and_intro
	                   result_left_prop
		                   result_right_prop
		                   (Hyp 0)
		                   (shift_captured_pf
		                      captured_term_depth captured_proof_depth
		                      term_depth (proof_depth + 1) source_right_proof)
		               in
		               PPfAp
		                 (result_to_target_builder
		                    term_depth (proof_depth + 1)
		                    term_replacements replacements fallback_replacements,
		                  rebuilt))
		          in
		          eliminate
		            term_depth
		            proof_depth
	            term_replacements
	            replacements
	            fallback_replacements
            witnesses
            source_left
	            result_left
	            source_left_proof
	            left_result_to_target_builder
	        else if right_count > 0 then
	          let captured_term_depth = term_depth in
	          let captured_proof_depth = proof_depth in
	          let source_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_left in
	          let source_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_right in
	          let source_left_proof =
	            native_core_and_elim_left source_left_prop source_right_prop proof
	          in
	          let source_right_proof =
	            native_core_and_elim_right source_left_prop source_right_prop proof
	          in
            let captured_result_left_prop =
              formula_prop_with_replacements
                ~close_depth:term_depth
                ~fallback_replacements
                replacements
                result_left
            in
	            debug_prop_pair
	              "and-right-count unchanged-left"
	              term_depth
	              proof_depth
	              source_left_prop
	              captured_result_left_prop;
	            if source_left_prop <> captured_result_left_prop then
	              debug_replacement_set
	                "and-right-count unchanged-left"
	                term_depth replacements fallback_replacements;
			          let right_result_to_target_builder term_depth proof_depth term_replacements replacements fallback_replacements =
		            let result_left_prop =
                  shift_captured_tm
                    captured_term_depth
                    term_depth
                    captured_result_left_prop
                in
		            let result_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_right in
		            PLam
		              (result_right_prop,
	               let rebuilt =
	                 debug_conjunction_contract
	                   "and-right-count"
	                   term_depth
	                   (proof_depth + 1)
	                   (formula_prop_with_replacements
	                      ~close_depth:term_depth
	                      ~fallback_replacements
	                      replacements
	                      result)
	                   (native_core_and result_left_prop result_right_prop |> tm_beta_eta_norm);
		                 native_core_and_intro
		                   result_left_prop
		                   result_right_prop
		                   (shift_captured_pf
		                      captured_term_depth captured_proof_depth
		                      term_depth (proof_depth + 1) source_left_proof)
		                   (Hyp 0)
	               in
		               PPfAp
		                 (result_to_target_builder
		                    term_depth (proof_depth + 1)
		                    term_replacements replacements fallback_replacements,
		                  rebuilt))
		          in
		          eliminate
		            term_depth
		            proof_depth
	            term_replacements
	            replacements
	            fallback_replacements
            witnesses
            source_right
	            result_right
	            source_right_proof
	            right_result_to_target_builder
	        else
	          eliminate_base term_depth proof_depth term_replacements replacements fallback_replacements source result proof result_to_target_builder
    | Ap (Ap (TmH "vampire_or", source_left), source_right),
      Ap (Ap (TmH "vampire_or", result_left), result_right),
      _ ->
        debug_skolem_branch_candidates
          "or"
          term_depth
          proof_depth
          source
          result
          witnesses;
        let left_count = source_exists_count source_left in
        let right_count = source_exists_count source_right in
        let rec split_witnesses n acc rest =
          if n = 0 then (List.rev acc, rest)
          else
            match rest with
            | witness :: rest -> split_witnesses (n - 1) (witness :: acc) rest
            | [] ->
                error
                  (id ^ ": native preprocess Skolem CPS source has fewer existential binders than substitutions")
        in
        let left_witnesses, right_witnesses =
          split_witnesses left_count [] witnesses
        in
		        let source_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_left in
		        let source_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source_right in
		        debug_witness_tm "or source_left_prop" source_left_prop;
		        debug_witness_tm "or source_right_prop" source_right_prop;
			        let result_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_left in
			        let result_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_right in
		        let branch_target = target_prop in
	        let rebuild_left_to_target_builder term_depth proof_depth term_replacements replacements fallback_replacements =
	          let result_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_left in
	          let result_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_right in
	          debug_witness_tm "or result_left_prop" result_left_prop;
	          debug_witness_tm "or result_right_prop" result_right_prop;
	          PLam
	            (result_left_prop,
	             let rebuilt =
               native_core_or_intro_left
                 result_left_prop
                 result_right_prop
                 (Hyp 0)
	             in
	             PPfAp
	               (result_to_target_builder
	                  term_depth (proof_depth + 1)
	                  term_replacements replacements fallback_replacements,
	                rebuilt))
	        in
	        let rebuild_right_to_target_builder term_depth proof_depth term_replacements replacements fallback_replacements =
	          let result_left_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_left in
	          let result_right_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result_right in
	          PLam
	            (result_right_prop,
	             let rebuilt =
               native_core_or_intro_right
                 result_left_prop
                 result_right_prop
                 (Hyp 0)
	             in
	             PPfAp
	               (result_to_target_builder
	                  term_depth (proof_depth + 1)
	                  term_replacements replacements fallback_replacements,
	                rebuilt))
	        in
	        let left_branch =
	          PLam
            (source_left_prop,
	             if left_count > 0 then
	               eliminate
	                 term_depth
	                 (proof_depth + 1)
	                 term_replacements
	                 replacements
	                 fallback_replacements
                 left_witnesses
                 source_left
	                 result_left
	                 (Hyp 0)
	                 rebuild_left_to_target_builder
	             else if source_left_prop = result_left_prop then
	               PPfAp
	                 (rebuild_left_to_target_builder
	                    term_depth (proof_depth + 1)
	                    term_replacements replacements fallback_replacements,
	                  Hyp 0)
             else
               begin match
                 select_replacements_to_match
                   "unchanged left disjunction branch"
                   term_depth
                   replacements fallback_replacements source_left result_left
               with
               | Some (selected_replacements, _, _) ->
                   PPfAp
                     (rebuild_left_to_target_builder
                        term_depth (proof_depth + 1)
                        term_replacements selected_replacements fallback_replacements,
                      Hyp 0)
               | None ->
                   error
                     (id ^ ": native preprocess Skolem CPS unchanged disjunction branch does not match result")
               end)
        in
	        let right_branch =
	          PLam
            (source_right_prop,
	             if right_count > 0 then
	               eliminate
	                 term_depth
	                 (proof_depth + 1)
	                 term_replacements
	                 replacements
	                 fallback_replacements
                 right_witnesses
                 source_right
	                 result_right
	                 (Hyp 0)
	                 rebuild_right_to_target_builder
	             else if source_right_prop = result_right_prop then
	               PPfAp
	                 (rebuild_right_to_target_builder
	                    term_depth (proof_depth + 1)
	                    term_replacements replacements fallback_replacements,
	                  Hyp 0)
             else
               begin match
                 select_replacements_to_match
                   "unchanged right disjunction branch"
                   term_depth
                   replacements fallback_replacements source_right result_right
               with
               | Some (selected_replacements, _, _) ->
                   PPfAp
                     (rebuild_right_to_target_builder
                        term_depth (proof_depth + 1)
                        term_replacements selected_replacements fallback_replacements,
                      Hyp 0)
               | None ->
                   error
                     (id ^ ": native preprocess Skolem CPS unchanged disjunction branch does not match result")
               end)
        in
	        let candidate =
	          PPfAp
	          (PPfAp (PTmAp (proof, branch_target), left_branch),
	           right_branch)
	        in
	        (* Close Skolem witnesses that only survive through an unused
	           disjunction side in the replay continuation.  The caller still
	           rejects any remaining witness or choice leak and rechecks the
	           whole proof against False. *)
	        let candidate =
	          proof_with_replacements
	            term_replacements replacements fallback_replacements candidate
	        in
	        debug_witness_pf "or-elimination candidate" candidate;
	        candidate
	    | _, _, [] ->
	        eliminate_base term_depth proof_depth term_replacements replacements fallback_replacements source result proof result_to_target_builder
    | _ ->
        error
          (id ^ ": native preprocess Skolem CPS source has fewer existential binders than substitutions")
	  and eliminate_base term_depth proof_depth term_replacements replacements fallback_replacements source result proof result_to_target_builder =
        let source_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements source in
        let expected_result_prop = formula_prop_with_replacements ~close_depth:term_depth ~fallback_replacements replacements result in
        let selected_replacements, expected_result_prop =
          if source_prop = expected_result_prop then
            replacements, expected_result_prop
          else
            let candidate_symbols =
              witness_symbols
              |> List.filter (fun symbol -> tm_contains_symbol symbol result)
            in
            let rec try_overrides = function
              | [] -> None
              | symbol :: rest ->
                  let replacements_with_override =
                    (symbol, DB 0) :: replacements
                  in
                  let candidate_prop =
                    formula_prop_with_ordered_replacements
                      term_depth
                      (replacements_with_override @ fallback_replacements)
                      result
                  in
                  if source_prop = candidate_prop then
                    Some (symbol, replacements_with_override, candidate_prop)
                  else
                    try_overrides rest
            in
            begin match try_overrides candidate_symbols with
            | Some (symbol, replacements_with_override, candidate_prop) ->
                if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                  prerr_endline
                    (id
                     ^ ": native preprocess Skolem CPS refreshed active witness "
                     ^ symbol
                     ^ " at base binder");
                replacements_with_override, candidate_prop
            | None -> replacements, expected_result_prop
            end
        in
        if source_prop <> expected_result_prop then begin
          if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
            prerr_endline ("native preprocess Skolem CPS source base: " ^ tm_to_str source_prop);
            prerr_endline ("native preprocess Skolem CPS result base: " ^ tm_to_str expected_result_prop);
            prerr_endline
              ("native preprocess Skolem CPS replacements: "
               ^ String.concat ", " (List.map fst replacements));
            prerr_endline
              ("native preprocess Skolem CPS fallback replacements: "
               ^ String.concat ", " (List.map fst fallback_replacements));
            begin match native_core_tm_term_symbol_detail witness_symbols expected_result_prop with
            | Some detail ->
                prerr_endline
                  ("native preprocess Skolem CPS result base first witness: " ^ detail)
            | None -> ()
            end;
            let short_tm tm =
              let text = tm_to_str tm in
              if String.length text <= 300 then text
              else String.sub text 0 300 ^ "..."
            in
            prerr_endline
              ("native preprocess Skolem CPS fallback replacement values: "
               ^ String.concat ", "
                   (List.map
                      (fun (name, tm) -> name ^ ":=" ^ short_tm tm)
                      fallback_replacements));
            prerr_endline
              ("native preprocess Skolem CPS active replacement values: "
               ^ String.concat ", "
                   (List.map
                      (fun (name, tm) -> name ^ ":=" ^ short_tm tm)
                      replacements));
            prerr_endline
              ("native preprocess Skolem CPS raw result before replacements: "
               ^ short_tm result);
            begin match native_core_tm_term_symbol_detail witness_symbols result with
            | Some detail ->
                prerr_endline
                  ("native preprocess Skolem CPS raw result first witness: " ^ detail)
            | None -> ()
            end;
            prerr_endline
              ("native preprocess Skolem CPS raw result after replacements: "
               ^ short_tm
                   (raw_formula_with_replacements
                      term_depth replacements fallback_replacements result));
            prerr_endline
              ("native preprocess Skolem CPS raw source after replacements: "
               ^ short_tm
                   (raw_formula_with_replacements
                      term_depth replacements fallback_replacements source));
            let rec first_tm_difference path left right =
              if left = right then None
              else
                match left, right with
                | TpAp (left_body, left_tp), TpAp (right_body, right_tp) ->
                    if left_tp <> right_tp then Some (path ^ ".type", left, right)
                    else first_tm_difference (path ^ ".tpap") left_body right_body
                | Ap (left_fun, left_arg), Ap (right_fun, right_arg) ->
                    begin match first_tm_difference (path ^ ".fun") left_fun right_fun with
                    | Some _ as found -> found
                    | None -> first_tm_difference (path ^ ".arg") left_arg right_arg
                    end
                | Lam (left_tp, left_body), Lam (right_tp, right_body)
                | All (left_tp, left_body), All (right_tp, right_body) ->
                    if left_tp <> right_tp then Some (path ^ ".binder-type", left, right)
                    else first_tm_difference (path ^ ".body") left_body right_body
                | Imp (left_a, left_b), Imp (right_a, right_b) ->
                    begin match first_tm_difference (path ^ ".left") left_a right_a with
                    | Some _ as found -> found
                    | None -> first_tm_difference (path ^ ".right") left_b right_b
                    end
                | _ -> Some (path, left, right)
            in
            begin match first_tm_difference "root" source_prop expected_result_prop with
            | Some (path, left, right) ->
                prerr_endline ("native preprocess Skolem CPS first diff path: " ^ path);
                prerr_endline ("native preprocess Skolem CPS first diff source: " ^ short_tm left);
                prerr_endline ("native preprocess Skolem CPS first diff target: " ^ short_tm right)
            | None -> ()
            end
          end;
          error
            (id ^ ": native preprocess Skolem CPS source body does not match the Skolem result")
        end;
        let result_checked_proof =
          proof_with_replacements
            term_replacements
            selected_replacements
            fallback_replacements
            proof
        in
	        let result_to_target_proof =
	          result_to_target_builder
	            term_depth proof_depth term_replacements selected_replacements fallback_replacements
	          |> proof_with_replacements term_replacements selected_replacements fallback_replacements
        in
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
          begin match native_core_pf_term_symbol_detail witness_symbols result_to_target_proof with
          | Some detail ->
              prerr_endline
                (id ^ ": native preprocess Skolem CPS base result_to_target still contains introduced symbol: " ^ detail)
          | None -> ()
          end;
          begin match native_core_pf_term_symbol_detail witness_symbols result_checked_proof with
          | Some detail ->
              prerr_endline
                (id ^ ": native preprocess Skolem CPS base result proof still contains introduced symbol: " ^ detail)
          | None -> ()
          end
        end;
        PPfAp
          (result_to_target_proof, result_checked_proof)
  in
	  eliminate 0 0 [] [] [] witness_symbols source result parent_proof result_to_target_builder

let native_core_truth_conflict_false_proof id literal proof =
  let is_true = function
    | TmH "f__true" | TmH "vampire_true" -> true
    | tm when tm = native_core_true -> true
    | _ -> false
  in
  let is_false = function
    | TmH "f__false" | TmH "vampire_false" -> true
    | tm when tm = native_core_false -> true
    | _ -> false
  in
  let motive_left = Lam (Prop, Lam (Prop, DB 1)) in
  let motive_right = Lam (Prop, Lam (Prop, DB 0)) in
  match literal with
  | Pos atom ->
      begin match megalodon_eq_poly_sides atom with
      | Some (_, left, right) when is_true left && is_false right ->
          PPfAp (PTmAp (proof, motive_left), native_core_true_proof)
      | Some (_, left, right) when is_false left && is_true right ->
          PPfAp (PTmAp (proof, motive_right), native_core_true_proof)
      | Some _ ->
          error (id ^ ": native core proof-term truth-conflict equality is not true = false")
      | None ->
          error (id ^ ": native core proof-term truth-conflict literal is not typed Megalodon equality")
      end
  | Neg _ ->
      error (id ^ ": native core proof-term truth-conflict literal must be positive")

let native_core_truth_conflict id parent_clause parent_proof literal_index result =
  let selected = nth literal_index parent_clause (id ^ " native truth-conflict literal") in
  let expected = remove_at literal_index parent_clause (id ^ " native truth-conflict literal") in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native core proof-term truth-conflict result does not remove selected literal");
  let target_prop = native_core_clause_prop id result in
  let selected_branch proof =
    PTmAp (native_core_truth_conflict_false_proof id selected proof, target_prop)
  in
  let rec consume selected_index clause proof =
    match clause, selected_index with
    | [], _ -> error (id ^ ": native core proof-term truth-conflict index is out of bounds")
    | [literal], Some 0 when literal = selected -> selected_branch proof
    | [literal], Some _ ->
        error (id ^ ": native core proof-term truth-conflict index is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = selected -> selected_branch (Hyp 0)
             | Some 0 ->
                 error (id ^ ": native core proof-term truth-conflict selected literal mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam (rest_prop, consume tail_selected rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume (Some literal_index) parent_clause parent_proof

let native_core_open_step_theorem_body_in_result_context
    ?(shift_parent_proof=true)
    cert id variables parent_id subst proof =
  (* Open a stored parent theorem under the result step binders. Parent
     variables must either be retained in the result step or explicitly
     substituted by Vampire metadata. *)
  let parent_step_variables = native_core_step_variables cert parent_id in
  let result_step_variables = native_core_step_variables cert id in
  let result_variable_count = List.length result_step_variables in
  let db_for_result_variable name tp =
    let rec find index = function
      | [] -> None
      | (candidate_name, candidate_tp) :: rest ->
          if candidate_name = name && candidate_tp = tp then
            Some (DB (result_variable_count - index - 1))
          else find (index + 1) rest
    in
    find 0 result_step_variables
  in
  let close_witness tm =
    native_core_close_tm (variables @ result_step_variables) tm
  in
  List.fold_left
    (fun proof (name, tp) ->
       let witness =
         match List.assoc_opt name subst with
         | Some tm -> close_witness tm
         | None ->
             begin match db_for_result_variable name tp with
             | Some tm -> tm
             | None ->
                 error
                   (id ^ ": native core open_step_theorem cannot instantiate dropped parent variable "
                    ^ name ^ " without an explicit substitution")
             end
       in
       PTmAp (proof, witness))
    (if shift_parent_proof then pftmshift 0 result_variable_count proof else proof)
    parent_step_variables

let native_core_truth_conflict_in_result_context
    cert id variables parent_id parent_clause parent_proof literal_index result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let parent_clause = List.map close_literal parent_clause in
  let result = List.map close_literal result in
  let parent_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables parent_id [] parent_proof
  in
  let body_proof =
    native_core_truth_conflict id parent_clause parent_proof literal_index result
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_instantiate_step_proof_in_result_context
    cert id variables parent_id subst proof =
  let result_step_variables = native_core_step_variables cert id in
  let body_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables parent_id subst proof
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_inequality_split_proof
    cert id variables source_id source_clause source_proof splits result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let close_split split =
    {
      split_name_parent = split.split_name_parent;
      split_source = close_literal split.split_source;
      split_name_literal = close_literal split.split_name_literal;
      split_replacement = close_literal split.split_replacement;
    }
  in
  let source_clause = List.map close_literal source_clause in
  let result = List.map close_literal result in
  let splits = List.map close_split splits in
  let source_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables source_id [] source_proof
  in
  let rec split_for_source lit = function
    | [] -> None
    | split :: rest ->
        if split.split_source = lit then Some split else split_for_source lit rest
  in
  let replacement_for_split split =
    let split_named =
      match native_core_bool_name_literal false split.split_name_literal with
      | Some named -> named
      | None ->
          error (id ^ ": native preprocess proof-term inequality_split name literal is not false equality")
    in
    let replacement_named =
      match native_core_bool_name_literal true split.split_replacement with
      | Some named -> named
      | None ->
          error (id ^ ": native preprocess proof-term inequality_split replacement is not true equality")
    in
    let split_name, split_args =
      match native_core_flatten_value_application split_named with
      | TmH name, (_ :: _ as args) -> (name, args)
      | _ ->
          error (id ^ ": native preprocess proof-term inequality_split name literal is not a split-name application")
    in
    let replacement_name, replacement_args =
      match native_core_flatten_value_application replacement_named with
      | TmH name, (_ :: _ as args) -> (name, args)
      | _ ->
          error (id ^ ": native preprocess proof-term inequality_split replacement is not a split-name application")
    in
    if native_core_ident split_name <> native_core_ident replacement_name then
      error (id ^ ": native preprocess proof-term inequality_split replacement uses a different split name");
    let split_arg =
      match List.rev split_args with
      | arg :: _ -> arg
      | [] -> assert false
    in
    let target_arg =
      match List.rev replacement_args with
      | arg :: _ -> arg
      | [] -> assert false
    in
    (replacement_named, split_arg, target_arg)
  in
  let replacement_proof split source_literal_proof =
    let replacement_named, split_arg, target_arg = replacement_for_split split in
    let source_atom =
      match split.split_source with
      | Neg atom -> atom
      | Pos _ ->
          error (id ^ ": native preprocess proof-term inequality_split source literal is not negative")
    in
    let source_to_named =
      match native_core_equality_sides source_atom with
      | Some (_, left, right) when left = target_arg && right = split_arg ->
          source_literal_proof
      | Some (tp, left, right) when left = split_arg && right = target_arg ->
          let target_atom = native_core_eq_atom tp target_arg split_arg in
          PLam
            (native_core_expand_eq_atom target_atom,
             let symmetry =
               native_core_eq_symmetry_proof id (Pos target_atom) (Hyp 0)
             in
             PPfAp (pfshift 0 1 source_literal_proof, symmetry))
      | Some _ ->
          error (id ^ ": native preprocess proof-term inequality_split source equality does not match split arguments")
      | None ->
          error (id ^ ": native preprocess proof-term inequality_split source literal is not equality")
    in
    let replacement_atom =
      match split.split_replacement with
      | Pos atom -> atom
      | Neg _ ->
          error (id ^ ": native preprocess proof-term inequality_split replacement is not positive")
    in
    match native_core_true_eq_from_proof replacement_named replacement_atom source_to_named with
    | Some proof -> proof
    | None ->
        error (id ^ ": native preprocess proof-term inequality_split cannot prove true equality replacement")
  in
  let introduce lit proof =
    match split_for_source lit splits with
    | Some split ->
        native_core_prove_literal_to_clause
          id result split.split_replacement (replacement_proof split proof)
    | None ->
        native_core_prove_literal_to_clause id result lit proof
  in
  let transformed =
    List.map
      (fun lit ->
         match split_for_source lit splits with
         | Some split -> split.split_replacement
         | None -> lit)
      source_clause
  in
  if not (same_clause_multiset transformed result) then
    error (id ^ ": native preprocess proof-term inequality_split result does not match source replacements");
  let rec consume clause proof =
    match clause with
    | [] -> error (id ^ ": native preprocess proof-term inequality_split source clause is empty")
    | [literal] -> introduce literal proof
    | literal :: rest ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let target_prop = native_core_clause_prop id result in
        let head_branch =
          PLam (literal_prop, introduce literal (Hyp 0))
        in
        let tail_branch =
          PLam (rest_prop, consume rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  let body_proof = consume source_clause source_proof in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_substitute_in_result_context
    ?(shift_parent_proof=true)
    cert id variables parent_id parent_clause subst parent_proof result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm = native_core_close_tm (variables @ result_step_variables) in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let source_clause =
    subst_clause subst parent_clause
    |> List.map close_literal
  in
  let result =
    List.map close_literal result
  in
  if not (same_clause_multiset source_clause result) then
    error
      (id ^ ": native proof-term checker instantiation substitution does not produce result clause");
  let body_proof =
    native_core_open_step_theorem_body_in_result_context
      ~shift_parent_proof
      cert id variables parent_id subst parent_proof
  in
  let body_proof =
    if source_clause = result then body_proof
    else native_core_prove_clause_to_clause id source_clause result body_proof
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_factor_in_result_context
    cert id variables parent_id parent_clause parent_proof left_index right_index result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let parent_clause = List.map close_literal parent_clause in
  let result = List.map close_literal result in
  let parent_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables parent_id [] parent_proof
  in
  let body_proof =
    native_core_factor id parent_clause parent_proof left_index right_index result
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_resolve_in_result_context
    cert id variables left_id left_clause left_proof right_id right_clause right_proof
    left_index right_index result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let left_clause = List.map close_literal left_clause in
  let right_clause = List.map close_literal right_clause in
  let result = List.map close_literal result in
  let left_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables left_id [] left_proof
  in
  let right_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables right_id [] right_proof
  in
  let body_proof =
    match left_clause, right_clause, result, left_index, right_index with
    | [Pos left_atom], [Neg right_atom], [], 0, 0
      when native_core_same_atom left_atom right_atom ->
        PPfAp (right_proof, left_proof)
    | [Neg left_atom], [Pos right_atom], [], 0, 0
      when native_core_same_atom left_atom right_atom ->
        PPfAp (left_proof, right_proof)
    | _, [_], _, _, 0
        when List.length left_clause >= 1
             && List.length result + 1 = List.length left_clause ->
        native_core_resolve_clause_unit
          id left_clause left_proof left_index right_clause right_proof right_index result
    | [_], _, _, 0, _
        when List.length right_clause >= 1
             && List.length result + 1 = List.length right_clause ->
        native_core_resolve_clause_unit
          id right_clause right_proof right_index left_clause left_proof left_index result
    | [_; _], [_; _], [_; _], _, _ ->
        native_core_resolve_binary_binary
          id left_clause left_proof left_index right_clause right_proof right_index result
    | _, _, _, _, _ ->
        native_core_resolve_clause_clause
          id left_clause left_proof left_index right_clause right_proof right_index result
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_equality_resolution id parent_clause parent_proof literal_index result =
  let selected = nth literal_index parent_clause (id ^ " native equality-resolution literal") in
  let expected = remove_at literal_index parent_clause (id ^ " native equality-resolution literal") in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native core proof-term equality-resolution result does not remove the selected literal");
  let atom =
    match selected with
    | Neg atom -> atom
    | Pos _ ->
        error (id ^ ": native core proof-term equality-resolution selected literal is positive")
  in
  let refl =
    match native_core_reflexive_eq_proof atom with
    | Some refl -> refl
    | None ->
        error
          (id ^ ": native core proof-term equality-resolution requires a reflexive Megalodon equality literal")
  in
  let target_prop = native_core_clause_prop id result in
  let rec consume selected_index clause proof =
    match clause, selected_index with
    | [], _ -> error (id ^ ": native core proof-term equality-resolution literal index is out of bounds")
    | [literal], Some 0 when literal = selected ->
        PTmAp (PPfAp (proof, refl), target_prop)
    | [literal], Some _ ->
        error (id ^ ": native core proof-term equality-resolution literal index is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = selected ->
                 PTmAp (PPfAp (Hyp 0, refl), target_prop)
             | Some 0 ->
                 error (id ^ ": native core proof-term equality-resolution selected literal mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume tail_selected rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume (Some literal_index) parent_clause parent_proof

let native_core_equality_resolution_in_result_context
    cert id variables parent_id parent_clause parent_proof literal_index result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let parent_clause = List.map close_literal parent_clause in
  let result = List.map close_literal result in
  let parent_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables parent_id [] parent_proof
  in
  let body_proof =
    native_core_equality_resolution id parent_clause parent_proof literal_index result
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_equality_symmetry id parent_clause parent_proof literal_index result =
  let selected = nth literal_index parent_clause (id ^ " native equality-symmetry literal") in
  let swapped =
    match native_core_swapped_eq_literal selected with
    | Some literal -> literal
    | None -> error (id ^ ": native core proof-term equality-symmetry requires typed Megalodon equality")
  in
  let expected =
    remove_at literal_index parent_clause (id ^ " native equality-symmetry literal") @ [swapped]
  in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native core proof-term equality-symmetry result does not match the swapped selected literal");
  let target_prop = native_core_clause_prop id result in
  let rec consume selected_index clause proof =
    match clause, selected_index with
    | [], _ -> error (id ^ ": native core proof-term equality-symmetry selected index is out of bounds")
    | [literal], Some 0 when literal = selected ->
        let transported = native_core_eq_symmetry_proof id selected proof in
        native_core_prove_literal_to_clause id result swapped transported
    | [literal], Some _ ->
        error (id ^ ": native core proof-term equality-symmetry selected index is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = selected ->
                 let transported = native_core_eq_symmetry_proof id selected (Hyp 0) in
                 native_core_prove_literal_to_clause id result swapped transported
             | Some 0 ->
                 error (id ^ ": native core proof-term equality-symmetry selected literal mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume tail_selected rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume (Some literal_index) parent_clause parent_proof

let native_core_validate_equality_symmetry_step id parent_clause literal_index result =
  let selected = nth literal_index parent_clause (id ^ " native equality-symmetry literal") in
  let swapped =
    match native_core_swapped_eq_literal selected with
    | Some literal -> literal
    | None -> error (id ^ ": native preprocess proof-term equality_symmetry requires typed Megalodon equality")
  in
  let expected =
    remove_at literal_index parent_clause (id ^ " native equality-symmetry literal") @ [swapped]
  in
  if not (same_clause_multiset expected result) then
    error (id ^ ": native preprocess proof-term equality_symmetry result does not match the swapped selected literal")

let native_core_equality_symmetry_in_result_context
    cert id variables parent_id parent_clause parent_proof literal_index result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let parent_clause = List.map close_literal parent_clause in
  let result = List.map close_literal result in
  let parent_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables parent_id [] parent_proof
  in
  let body_proof =
    native_core_equality_symmetry id parent_clause parent_proof literal_index result
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_equality_factoring_other_proof
    id selected_atom selected_proof other_atom introduced_atom introduced_proof =
  match
    megalodon_eq_poly_sides selected_atom,
    megalodon_eq_poly_sides other_atom,
    megalodon_eq_poly_sides introduced_atom
  with
  | Some (selected_tp, selected_left, selected_right),
    Some (other_tp, other_left, other_right),
    Some (introduced_tp, introduced_left, introduced_right)
      when selected_tp = other_tp
           && selected_tp = introduced_tp
           && selected_left = other_left
           && selected_right = introduced_left
           && other_right = introduced_right ->
      let motive =
        Lam
          (selected_tp,
           Lam
             (selected_tp,
              native_core_expand_eq_atom
                (native_core_eq_atom selected_tp (DB 0) (tmshift 0 2 other_right))))
      in
      PPfAp (PTmAp (selected_proof, motive), introduced_proof)
  | _ ->
      error
        (id ^ ": native core proof-term equality-factoring supports only shared-left equality factoring")

let native_core_equality_factoring id parent_clause parent_proof selected_index other_index result =
  if selected_index = other_index then
    error (id ^ ": native core proof-term equality-factoring literal indices must be distinct");
  let selected = nth selected_index parent_clause (id ^ " native equality-factoring selected literal") in
  let other = nth other_index parent_clause (id ^ " native equality-factoring other literal") in
  let selected_atom =
    match selected with
    | Pos atom -> atom
    | Neg _ ->
        error (id ^ ": native core proof-term equality-factoring selected literal is negative")
  in
  let other_atom =
    match other with
    | Pos atom -> atom
    | Neg _ ->
        error (id ^ ": native core proof-term equality-factoring other literal is negative")
  in
  let introduced_atom =
    match megalodon_eq_poly_sides selected_atom, megalodon_eq_poly_sides other_atom with
    | Some (selected_tp, selected_left, selected_right),
      Some (other_tp, other_left, other_right)
        when selected_tp = other_tp && selected_left = other_left ->
        native_core_eq_atom selected_tp selected_right other_right
    | Some _, Some _ ->
        error
          (id ^ ": native core proof-term equality-factoring supports only shared-left equality literals")
    | _ ->
        error
          (id ^ ": native core proof-term equality-factoring requires typed Megalodon equality literals")
  in
  let introduced_negative = Neg introduced_atom in
  let expected =
    remove_at selected_index parent_clause (id ^ " native equality-factoring selected literal")
    @ [introduced_negative]
  in
  if not (same_clause_multiset expected result) then
    error
      (id ^ ": native core proof-term equality-factoring result does not match the shared-left factoring clause");
  let target_prop = native_core_clause_prop id result in
  let introduced_prop = native_core_literal_prop (Pos introduced_atom) in
  let selected_branch selected_proof =
    let left_branch =
      PLam
        (introduced_prop,
         let other_proof =
           native_core_equality_factoring_other_proof
             id selected_atom (pfshift 0 1 selected_proof) other_atom introduced_atom (Hyp 0)
         in
         native_core_prove_literal_to_clause id result other other_proof)
    in
    let right_branch =
      PLam
        (Imp (introduced_prop, native_core_false),
         native_core_prove_literal_to_clause id result introduced_negative (Hyp 0))
    in
    PPfAp
      (PPfAp (PTmAp (native_core_xm_proof introduced_prop, target_prop), left_branch),
       right_branch)
  in
  let rec consume selected_index clause proof =
    match clause, selected_index with
    | [], _ ->
        error (id ^ ": native core proof-term equality-factoring selected index is out of bounds")
    | [literal], Some 0 when literal = selected ->
        selected_branch proof
    | [literal], Some _ ->
        error (id ^ ": native core proof-term equality-factoring selected index is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = selected -> selected_branch (Hyp 0)
             | Some 0 ->
                 error (id ^ ": native core proof-term equality-factoring selected literal mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume tail_selected rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume (Some selected_index) parent_clause parent_proof

let native_core_equality_factoring_in_result_context
    cert id variables parent_id parent_clause parent_proof selected_index other_index subst result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let parent_clause =
    subst_clause subst parent_clause
    |> List.map close_literal
  in
  let result = List.map close_literal result in
  let parent_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables parent_id subst parent_proof
  in
  let body_proof =
    native_core_equality_factoring
      id parent_clause parent_proof selected_index other_index result
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_literal_index id rule selected clause =
  let rec find index = function
    | [] -> error (id ^ ": native core proof-term " ^ rule ^ " selected literal is not in the main parent")
    | literal :: rest ->
        if literal = selected then index else find (index + 1) rest
  in
  find 0 clause

let native_core_instantiate_step_proof cert parent_id subst proof =
  native_core_step_variables cert parent_id
  |> List.fold_left
       (fun proof (name, _) ->
          let witness =
            match List.assoc_opt name subst with
            | Some tm -> tm
            | None -> TmH name
          in
          PTmAp (proof, witness))
       proof

let native_core_subsumption_resolution_unit id main_clause main_proof side_clause side_proof selected side_pivot result =
  let selected_index =
    native_core_literal_index id "subsumption-resolution" selected main_clause
  in
  let side_pivot_index =
    native_core_literal_index id "subsumption-resolution side" side_pivot side_clause
  in
  if not (native_core_complement selected side_pivot) then
    error (id ^ ": native core proof-term subsumption-resolution side pivot does not complement the selected literal");
  let expected =
    remove_at selected_index main_clause (id ^ " native subsumption-resolution selected literal")
  in
  if expected <> result then
    error (id ^ ": native core proof-term subsumption-resolution result does not remove the selected literal");
  let side_remaining =
    remove_at side_pivot_index side_clause (id ^ " native subsumption-resolution side pivot")
  in
  List.iter
    (fun literal ->
       if not (List.exists ((=) literal) result) then
         error (id ^ ": native core proof-term subsumption-resolution side remainder is not in the result"))
    side_remaining;
  let target_prop = native_core_clause_prop id result in
  let rec consume_side selected_proof side_index clause proof =
    match clause, side_index with
    | [], _ -> error (id ^ ": native core proof-term subsumption-resolution side pivot is out of bounds")
    | [literal], Some 0 when literal = side_pivot ->
        let false_proof =
          native_core_false_from_complement_proofs selected selected_proof literal proof
        in
        PTmAp (false_proof, target_prop)
    | [literal], Some _ ->
        error (id ^ ": native core proof-term subsumption-resolution side pivot is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, side_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match side_index with
             | Some 0 when literal = side_pivot ->
                 let false_proof =
                   native_core_false_from_complement_proofs
                     selected (pfshift 0 1 selected_proof) literal (Hyp 0)
                 in
                 PTmAp (false_proof, target_prop)
             | Some 0 ->
                 error (id ^ ": native core proof-term subsumption-resolution side pivot mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_index =
          match side_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume_side (pfshift 0 1 selected_proof) tail_index rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  let prove_selected selected_proof side_proof =
    consume_side selected_proof (Some side_pivot_index) side_clause side_proof
  in
  let rec consume_main selected_index clause proof side_proof =
    match clause, selected_index with
    | [], _ -> error (id ^ ": native core proof-term subsumption-resolution selected index is out of bounds")
    | [literal], Some 0 when literal = selected -> prove_selected proof side_proof
    | [literal], Some _ ->
        error (id ^ ": native core proof-term subsumption-resolution selected index is out of bounds")
    | [literal], None ->
        native_core_prove_literal_to_clause id result literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = selected ->
                 prove_selected (Hyp 0) (pfshift 0 1 side_proof)
             | Some 0 ->
                 error (id ^ ": native core proof-term subsumption-resolution selected literal mismatch")
             | _ ->
                 native_core_prove_literal_to_clause id result literal (Hyp 0))
        in
        let tail_index =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume_main tail_index rest (Hyp 0) (pfshift 0 1 side_proof))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume_main (Some selected_index) main_clause main_proof side_proof

let native_core_paramodulate_literal_transport
    id equality_atom equality_proof target_literal position from_tm to_tm result_literal literal_proof =
  let tp, eq_left, eq_right =
    match megalodon_eq_poly_sides equality_atom with
    | Some sides -> sides
    | None ->
        error (id ^ ": native core proof-term paramodulation equality literal is not typed Megalodon equality")
  in
  let target_atom, result_atom, context_replacement, source_atom =
    match target_literal, result_literal with
    | Pos target_atom, Pos result_atom ->
        let context_replacement, source_atom =
          if eq_left = from_tm && eq_right = to_tm then
            (DB 1, from_tm)
          else if eq_right = from_tm && eq_left = to_tm then
            (DB 0, from_tm)
          else
            error (id ^ ": native core proof-term paramodulation from/to terms do not match equality literal")
        in
        (target_atom, result_atom, context_replacement, source_atom)
    | Neg target_atom, Neg result_atom ->
        let context_replacement, source_atom =
          if eq_left = from_tm && eq_right = to_tm then
            (DB 0, from_tm)
          else if eq_right = from_tm && eq_left = to_tm then
            (DB 1, from_tm)
          else
            error (id ^ ": native core proof-term paramodulation from/to terms do not match equality literal")
        in
        (target_atom, result_atom, context_replacement, source_atom)
    | _ ->
        error (id ^ ": native core proof-term paramodulation cannot change literal polarity")
  in
  let rewrite_position =
    let rec select = function
      | [] -> error (id ^ ": native core proof-term paramodulation position does not contain from term")
      | candidate :: rest ->
          begin match try_tm_at_position target_atom candidate with
          | Some found when found = source_atom -> candidate
          | _ -> select rest
          end
    in
    select (paramodulation_position_candidates target_atom position)
  in
  let rewritten_atom =
    replace_tm_at_position target_atom rewrite_position to_tm (id ^ " native paramodulation target")
  in
  if rewritten_atom <> result_atom then
    error (id ^ ": native core proof-term paramodulation result literal is not the direct rewrite");
  let context_atom =
    replace_tm_at_position
      (tmshift 0 2 target_atom)
      rewrite_position
      context_replacement
      (id ^ " native paramodulation context")
  in
  let motive = Lam (tp, Lam (tp, native_core_expand_eq_atom context_atom)) in
  match target_literal, result_literal with
  | Pos _, Pos _ -> PPfAp (PTmAp (equality_proof, motive), literal_proof)
  | Neg _, Neg result_atom ->
      let result_prop = native_core_expand_eq_atom result_atom in
      PLam
        (result_prop,
         PPfAp
           (pfshift 0 1 literal_proof,
            PPfAp (PTmAp (pfshift 0 1 equality_proof, motive), Hyp 0)))
  | _ -> assert false

let native_core_paramodulate_unit id equality_clause equality_proof target_clause target_proof equality_index target_index position from_tm to_tm result =
  let equality_atom =
    match nth equality_index equality_clause (id ^ " native paramodulation equality literal") with
    | Pos equality_atom -> equality_atom
    | Neg _ -> error (id ^ ": native core proof-term paramodulation equality literal must be positive")
  in
  let selected =
    nth target_index target_clause (id ^ " native paramodulation target literal")
  in
	  let _target_rest =
	    remove_at target_index target_clause (id ^ " native paramodulation target literal")
	  in
	  let _equality_rest =
	    remove_at equality_index equality_clause (id ^ " native paramodulation equality literal")
	  in
	  let transport_to_result_literal result_literal proof =
	    try
	      native_core_paramodulate_literal_transport
	        id equality_atom equality_proof selected position from_tm to_tm result_literal proof
	    with Error _ ->
	      begin match native_core_swapped_eq_literal result_literal with
	      | Some direct_literal ->
	          let direct_proof =
	            native_core_paramodulate_literal_transport
	              id equality_atom equality_proof selected position from_tm to_tm direct_literal proof
	          in
	          native_core_eq_symmetry_proof id direct_literal direct_proof
	      | None ->
	          error
	            (id ^ ": native core proof-term paramodulation result does not contain the rewritten target literal")
	      end
	  in
	  let result_literal =
	    let candidates =
	      List.filter
	        (fun literal ->
	           try
	            ignore (transport_to_result_literal literal (Hyp 0));
	            true
	           with Error _ -> false)
	        result
	    in
    match candidates with
    | literal :: _ -> literal
    | [] ->
        error (id ^ ": native core proof-term paramodulation result does not contain the rewritten target literal")
  in
	  let target_prop = native_core_clause_prop id result in
	  let prove_side_literal literal proof =
	    try native_core_prove_literal_to_clause id result literal proof
	    with Error _ ->
	      begin match native_core_swapped_eq_literal literal with
	      | Some swapped ->
	          native_core_prove_literal_to_clause
	            id result swapped (native_core_eq_symmetry_proof id literal proof)
	      | None ->
	          error
	            (id ^ ": native core proof-term paramodulation side literal is not present in result")
	      end
	  in
	  let selected_transport equality_proof proof =
	    try
	      native_core_paramodulate_literal_transport
	        id equality_atom equality_proof selected position from_tm to_tm result_literal proof
	    with Error _ ->
	      begin match native_core_swapped_eq_literal result_literal with
	      | Some direct_literal ->
	          let direct_proof =
	            native_core_paramodulate_literal_transport
	              id equality_atom equality_proof selected position from_tm to_tm direct_literal proof
	          in
	          native_core_eq_symmetry_proof id direct_literal direct_proof
	      | None ->
	          error
	            (id ^ ": native core proof-term paramodulation result does not contain the rewritten target literal")
	      end
	  in
  let rec consume_target equality_proof selected_index clause proof =
    match clause, selected_index with
    | [], _ -> error (id ^ ": native core proof-term paramodulation target index is out of bounds")
    | [literal], Some 0 when literal = selected ->
        let transported = selected_transport equality_proof proof in
        native_core_prove_literal_to_clause id result result_literal transported
	    | [literal], Some _ ->
	        error (id ^ ": native core proof-term paramodulation target index is out of bounds")
	    | [literal], None ->
	        prove_side_literal literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = selected ->
                 let transported = selected_transport (pfshift 0 1 equality_proof) (Hyp 0) in
                 native_core_prove_literal_to_clause id result result_literal transported
	             | Some 0 ->
	                 error (id ^ ": native core proof-term paramodulation selected literal mismatch")
	             | _ ->
	                 prove_side_literal literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume_target (pfshift 0 1 equality_proof) tail_selected rest (Hyp 0))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  let rec consume_equality selected_index clause proof target_proof =
    match clause, selected_index with
    | [], _ -> error (id ^ ": native core proof-term paramodulation equality index is out of bounds")
    | [literal], Some 0 when literal = Pos equality_atom ->
        consume_target proof (Some target_index) target_clause target_proof
	    | [literal], Some _ ->
	        error (id ^ ": native core proof-term paramodulation equality index is out of bounds")
	    | [literal], None ->
	        prove_side_literal literal proof
    | literal :: rest, selected_index ->
        let literal_prop = native_core_literal_prop literal in
        let rest_prop = native_core_clause_prop id rest in
        let head_branch =
          PLam
            (literal_prop,
             match selected_index with
             | Some 0 when literal = Pos equality_atom ->
                 consume_target (Hyp 0) (Some target_index) target_clause (pfshift 0 1 target_proof)
	             | Some 0 ->
	                 error (id ^ ": native core proof-term paramodulation selected equality mismatch")
	             | _ ->
	                 prove_side_literal literal (Hyp 0))
        in
        let tail_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          PLam
            (rest_prop,
             consume_equality
               tail_selected
               rest
               (Hyp 0)
               (pfshift 0 1 target_proof))
        in
        PPfAp (PPfAp (PTmAp (proof, target_prop), head_branch), tail_branch)
  in
  consume_equality (Some equality_index) equality_clause equality_proof target_proof

let native_core_paramodulate_unit_in_result_context
    cert id variables equality_parent_id equality_clause equality_proof
    target_parent_id target_clause target_proof equality_index target_index
    position from_tm to_tm result =
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let equality_clause = List.map close_literal equality_clause in
  let target_clause = List.map close_literal target_clause in
  let result = List.map close_literal result in
  let from_tm = close_tm from_tm in
  let to_tm = close_tm to_tm in
  let equality_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables equality_parent_id [] equality_proof
  in
  let target_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables target_parent_id [] target_proof
  in
  let body_proof =
    native_core_paramodulate_unit
      id equality_clause equality_proof target_clause target_proof
      equality_index target_index position from_tm to_tm result
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_definition_rewrite_chain_proof
    cert id variables source_id source_clause source_proof rewrites result lookup_clause =
  if rewrites = [] then
    error (id ^ ": native core proof-term definition_rewrite_chain needs at least one rewrite");
  let result_step_variables = native_core_step_variables cert id in
  let close_tm tm = native_core_close_tm (variables @ result_step_variables) tm in
  let close_literal = function
    | Pos atom -> Pos (close_tm atom)
    | Neg atom -> Neg (close_tm atom)
  in
  let close_rewrite rewrite =
    {
      rewrite with
      rewrite_from = close_tm rewrite.rewrite_from;
      rewrite_to = close_tm rewrite.rewrite_to;
    }
  in
  let source_clause = List.map close_literal source_clause in
  let result = List.map close_literal result in
  let rewrites = List.map close_rewrite rewrites in
  let source_proof =
    native_core_open_step_theorem_body_in_result_context
      cert id variables source_id [] source_proof
  in
  let open_definition_parent rewrite =
    let definition_clause, definition_proof = lookup_clause rewrite.definition_parent in
    let definition_clause = List.map close_literal definition_clause in
    let definition_proof =
      native_core_open_step_theorem_body_in_result_context
        cert id variables rewrite.definition_parent [] definition_proof
    in
    definition_clause, definition_proof
  in
  let replay_one (current_clause, current_proof) rewrite =
    let definition_clause, definition_proof = open_definition_parent rewrite in
    let definition_literal =
      nth rewrite.definition_literal definition_clause
        (id ^ " native definition_rewrite_chain definition literal")
    in
    let equality_atom =
      match definition_literal with
      | Pos atom -> atom
      | Neg _ ->
          error
            (id ^ ": native core proof-term definition_rewrite_chain definition literal must be positive")
    in
    begin match megalodon_eq_poly_sides equality_atom with
    | Some (_, left, right)
        when (left = rewrite.rewrite_from && right = rewrite.rewrite_to)
             || (right = rewrite.rewrite_from && left = rewrite.rewrite_to) -> ()
    | Some _ ->
        error
          (id ^ ": native core proof-term definition_rewrite_chain rewrite terms do not match definition equality")
    | None ->
        error
          (id ^ ": native core proof-term definition_rewrite_chain definition parent is not typed Megalodon equality")
    end;
    let target_literal =
      nth rewrite.target_literal current_clause
        (id ^ " native definition_rewrite_chain target literal")
    in
    let target_atom = literal_atom target_literal in
    begin match try_tm_at_position target_atom rewrite.rewrite_position with
    | Some found when found = rewrite.rewrite_from -> ()
    | Some _ ->
        error
          (id ^ ": native core proof-term definition_rewrite_chain position does not contain from term")
    | None ->
        error
          (id ^ ": native core proof-term definition_rewrite_chain position is invalid")
    end;
    let rewritten_atom =
      replace_tm_at_position
        target_atom
        rewrite.rewrite_position
        rewrite.rewrite_to
        (id ^ " native definition_rewrite_chain target")
    in
    let rewritten_literal = replace_literal_atom target_literal rewritten_atom in
    let next_clause =
      replace_at rewrite.target_literal rewritten_literal current_clause
        (id ^ " native definition_rewrite_chain target literal")
    in
    let next_proof =
      native_core_paramodulate_unit
        id definition_clause definition_proof current_clause current_proof
        rewrite.definition_literal rewrite.target_literal rewrite.rewrite_position
        rewrite.rewrite_from rewrite.rewrite_to next_clause
    in
    next_clause, next_proof
  in
  let final_clause, final_proof =
    List.fold_left replay_one (source_clause, source_proof) rewrites
  in
  let body_proof =
    if final_clause = result then final_proof
    else if same_clause_multiset final_clause result then
      native_core_prove_clause_to_clause id final_clause result final_proof
    else
      error
        (id ^ ": native core proof-term definition_rewrite_chain final result does not match replayed chain")
  in
  native_core_bind_result_step_variables variables result_step_variables body_proof

let native_core_source_kind_and_tptp_name = function
  | SourceAxiom name -> ("axiom", name)
  | SourceConjecture name -> ("conjecture", name)
  | SourceNegatedConjecture name -> ("negated_conjecture", name)
  | SourceDefinition name -> ("definition", name)
  | SourceSetReflexivity name -> ("set_reflexivity", name)

let native_core_source_map_entry source_map source =
  let _, tptp_name = native_core_source_kind_and_tptp_name source in
  match
    List.find_opt
      (fun entry -> entry.source_map_tptp_name = tptp_name)
      source_map
  with
  | Some entry -> Some entry
  | None ->
      begin match source with
      | SourceConjecture alias ->
          List.find_opt
            (fun entry ->
               entry.source_map_kind = "conjecture"
               && ("conj_" ^ entry.source_map_tptp_name = alias
                   || "conj_" ^ entry.source_map_source_name = alias))
            source_map
      | _ -> None
      end

let native_core_source_is_set_reflexivity source_map source =
  match source with
  | SourceSetReflexivity _ -> true
  | _ ->
      begin match native_core_source_map_entry source_map source with
      | Some entry ->
          entry.source_map_kind = "set_reflexivity"
          || entry.source_map_kind = "local_set_reflexivity"
      | None -> false
      end

let native_core_source_is_conjecture = function
  | SourceConjecture _ | SourceNegatedConjecture _ -> true
  | _ -> false

let native_core_source_binding source_map id source proposition =
  let source_kind, tptp_name = native_core_source_kind_and_tptp_name source in
  let entry = native_core_source_map_entry source_map source in
  {
    core_native_source_step = id;
    core_native_certificate_source_kind = source_kind;
    core_native_tptp_name = tptp_name;
    core_native_source_name =
      begin match entry with
      | Some entry when entry.source_map_source_name <> "" -> entry.source_map_source_name
      | _ -> tptp_name
      end;
    core_native_source_map_kind =
      begin match entry with
      | Some entry -> entry.source_map_kind
      | None -> ""
      end;
    core_native_source_hash =
      begin match entry with
      | Some entry -> entry.source_map_hash
      | None -> ""
      end;
    core_native_source_proposition = proposition;
  }

let native_core_set_reflexivity_atom_proof id atom =
  match native_core_reflexive_eq_proof atom with
  | Some proof -> proof
  | None ->
      error
        (id ^ ": native proof-term source set_reflexivity is not a reflexive Megalodon equality")

let native_core_set_reflexivity_literal_proof id = function
  | Pos atom -> native_core_set_reflexivity_atom_proof id atom
  | Neg _ ->
      error
        (id ^ ": native proof-term source set_reflexivity cannot prove a negative literal")

let native_core_set_reflexivity_clause_proof id = function
  | [literal] -> native_core_set_reflexivity_literal_proof id literal
  | _ ->
      error
        (id ^ ": native proof-term source set_reflexivity expects a unit equality clause")

let native_core_source_proof source_proofs id =
  List.assoc_opt id source_proofs

let native_core_merge_external_delta proof_delta external_delta_table =
  let merged = Hashtbl.copy proof_delta in
  Hashtbl.iter
    (fun h v ->
       if not (Hashtbl.mem merged h) then
         Hashtbl.add merged h v
       else if not (valid_id_p h) then
         Hashtbl.replace merged h v)
    external_delta_table;
  merged

let native_core_allow_transitional_known () =
  Sys.getenv_opt "MEGALODON_CERT_ALLOW_TRANSITIONAL_PREPROCESS_KNOWN" = Some "1"

let native_core_has_prefix prefix text =
  let prefix_len = String.length prefix in
  String.length text >= prefix_len
  && String.sub text 0 prefix_len = prefix

let native_core_fixed_logical_known h =
  match h with
  | "vampire_exists_set_choice"
  | "vampire_exists_prop_choice"
  | "vampire_exists_set_prop_choice"
  | "vampire_exists_set_set_choice"
  | "vampire_exists_set_set_prop_choice"
  | "vampire_not_forall_exists_set"
  | "vampire_not_forall_exists_prop"
  | "vampire_not_forall_exists_set_prop"
  | "vampire_not_forall_exists_set_set"
  | "vampire_not_forall_exists_set_set_prop" -> true
  | _ -> false

let native_core_reject_certificate_knowns mode step_id proof =
  if not (native_core_allow_transitional_known ()) then begin
    let rec scan = function
      | Known h
          when native_core_has_prefix "vampire_" h
               && not (native_core_fixed_logical_known h) ->
          error
            (step_id ^ ": native " ^ mode
             ^ " proof-term checker refuses certificate-derived Known primitive "
             ^ h
             ^ "; implement a real proof term or run a structural diagnostic with MEGALODON_CERT_ALLOW_TRANSITIONAL_PREPROCESS_KNOWN=1")
      | PTpAp (proof, _) -> scan proof
      | PTmAp (proof, _) -> scan proof
      | PPfAp (left, right) -> scan left; scan right
      | PLam (_, proof) -> scan proof
      | TLam (_, proof) -> scan proof
      | Hyp _ | Known _ -> ()
    in
    scan proof
  end

let native_certificate_source_bindings
    ?(source_map=[])
    ?(external_definition_names=[])
    cert =
  ignore (check_certificate_strict cert);
  let variables = native_core_proof_variables ~exclude_names:external_definition_names cert in
  let type_from_thf_decl_formula formula =
    try
      let colon = String.index formula ':' in
      let close =
        try String.rindex formula ')'
        with Not_found -> String.length formula
      in
      let start = colon + 1 in
      let type_text = String.sub formula start (max 0 (close - start)) in
      let len = String.length type_text in
      let rec skip i =
        if i < len && (type_text.[i] = ' ' || type_text.[i] = '\t' || type_text.[i] = '\n') then
          skip (i + 1)
        else
          i
      in
      let rec parse_arrow i =
        let left, i = parse_atom i in
        let i = skip i in
        if i < len && type_text.[i] = '>' then
          let right, j = parse_arrow (skip (i + 1)) in
          (Ar (left, right), j)
        else
          (left, i)
      and parse_atom i =
        let i = skip i in
        if i + 1 < len && type_text.[i] = '$' && type_text.[i + 1] = 'i' then
          (Set, i + 2)
        else if i + 1 < len && type_text.[i] = '$' && type_text.[i + 1] = 'o' then
          (Prop, i + 2)
        else if i < len && type_text.[i] = '(' then
          let tp, j = parse_arrow (i + 1) in
          let j = skip j in
          if j < len && type_text.[j] = ')' then (tp, j + 1)
          else raise Not_found
        else
          raise Not_found
      in
      let tp, i = parse_arrow 0 in
      if skip i = len then Some tp else None
    with Not_found | Invalid_argument _ -> None
  in
  let local_source_variables =
    let declared_type name =
      variables
      |> List.find_opt (fun (variable_name, _) -> variable_name = native_core_ident name)
      |> Option.map (fun (variable_name, tp) -> (variable_name, tp))
    in
    let local_type_entry entry =
      let source_name = native_core_ident entry.source_map_source_name in
      match declared_type source_name with
      | Some variable -> Some variable
      | None ->
          begin match entry.source_map_decl_formula with
          | Some formula ->
              Option.map (fun tp -> (source_name, tp)) (type_from_thf_decl_formula formula)
          | None -> None
          end
    in
    let ordered =
      source_map
      |> List.filter_map
           (fun entry ->
              if entry.source_map_kind = "local_type" then
                local_type_entry entry
              else
                None)
    in
    if ordered = [] then variables else ordered
  in
  let symbol_table = native_core_symbol_table cert in
  let typed_steps =
    List.map
      (native_core_type_raw_equalities_step cert variables symbol_table)
      cert.steps
  in
  let tm_mentions_variable name tm =
    let rec mentions = function
      | TmH raw_name ->
          begin match native_core_ident_opt raw_name with
          | Some ident -> ident = name
          | None -> false
          end
      | TpAp (body, _) -> mentions body
      | Ap (left, right) -> mentions left || mentions right
      | Lam (_, body) | All (_, body) -> mentions body
      | Imp (left, right) -> mentions left || mentions right
      | DB _ | Prim _ -> false
    in
    mentions tm
  in
  let literal_terms = function
    | Pos tm | Neg tm -> [tm]
  in
  let source_variables terms =
    variables
    |> List.filter
         (fun (name, _) ->
            List.exists (tm_mentions_variable name) terms)
  in
  let source_variables_for_clause clause =
    clause |> List.concat_map literal_terms |> source_variables
  in
  let close_global_source_variables variables prop =
    List.fold_right (fun (_, tp) prop -> All (tp, prop)) variables prop
  in
  let source_keeps_local_variables source =
    match source with
    | SourceConjecture _ | SourceNegatedConjecture _ -> true
    | _ ->
        begin match native_core_source_map_entry source_map source with
        | Some entry ->
            begin match entry.source_map_kind with
            | "local_fact"
            | "local_definition"
            | "set_reflexivity"
            | "local_set_reflexivity"
            | "conjecture" -> true
            | _ -> false
            end
        | None -> false
        end
  in
  let source_local_variables source =
    match native_core_source_map_entry source_map source with
    | Some entry when entry.source_map_kind = "local_definition" -> variables
    | _ -> local_source_variables
  in
  let close_source_variables source variables prop =
    if source_keeps_local_variables source then prop
    else close_global_source_variables variables prop
  in
  List.fold_left
    (fun bindings step ->
       match step with
       | Input (id, source, clause) ->
           let source_variables =
             if source_keeps_local_variables source then source_local_variables source
             else source_variables_for_clause clause
           in
           let proposition =
             native_core_step_clause_prop cert source_variables id clause
             |> close_source_variables source source_variables
           in
           bindings @ [native_core_source_binding source_map id source proposition]
       | FormulaInput (id, source, literal) ->
           let source_variables =
             if source_keeps_local_variables source then source_local_variables source
             else source_variables (literal_terms literal)
           in
           let proposition =
             native_core_step_clause_prop cert source_variables id [literal]
             |> close_source_variables source source_variables
           in
           bindings @ [native_core_source_binding source_map id source proposition]
       | FormulaTermInput (id, source, formula) ->
           let step_variables =
             if native_core_source_is_conjecture source then
               native_core_step_variables_for_terms cert id [formula]
             else
               native_core_step_variables cert id
           in
           let source_variables =
             if source_keeps_local_variables source then source_local_variables source
             else source_variables [formula]
           in
           let proposition =
             native_core_close_tm
               (source_variables @ step_variables)
               (native_core_formula_prop formula)
           in
           let proposition =
             List.fold_right (fun (_, tp) prop -> All (tp, prop)) step_variables proposition
             |> close_source_variables source source_variables
           in
           bindings @ [native_core_source_binding source_map id source proposition]
       | _ -> bindings)
    []
    typed_steps

let native_preprocess_step_formula_prop_with_step_variables variables step_variables formula =
  let prop =
    native_core_close_tm
      (variables @ step_variables)
      (native_core_formula_prop formula)
  in
  List.fold_right (fun (_, tp) prop -> All (tp, prop)) step_variables prop

let native_preprocess_step_formula_prop cert variables id formula =
  native_preprocess_step_formula_prop_with_step_variables
    variables
    (native_core_step_variables cert id)
    formula

let native_core_skolem_result_formula_step_variables cert id result_step_variables =
  match native_core_kernel_v1_field cert id "result_formula_free_variable_count" with
  | None -> result_step_variables
  | Some _ ->
      let free_variables =
        native_core_kernel_v1_typed_variable_fields
          cert id "result_formula" "free_variable"
      in
      result_step_variables
      |> List.filter
           (fun (name, tp) ->
              List.exists
                (fun variable ->
                   variable.native_kernel_variable_name = name
                   && variable.native_kernel_variable_type = tp)
                free_variables)

let elaborate_core_resolution_refutation_native
    ?(source_map=[])
    ?(source_proofs=[])
    ?(external_hypotheses=[])
    ?(external_delta_table=Hashtbl.create 0)
    ?(external_definition_names=[])
    cert =
  let core_steps = validate_certificate_core_fragment cert in
  ignore (check_certificate_strict cert);
  let variables = native_core_proof_variables ~exclude_names:external_definition_names cert in
  let symbol_table = native_core_symbol_table cert in
  let proof_delta, raw_definition_delta = native_core_certificate_sgdelta cert symbol_table in
  let typed_steps =
    List.map
      (native_core_type_raw_equalities_step cert variables symbol_table)
      cert.steps
  in
  let used_steps = proof_dependency_closure typed_steps in
  let step_is_used id = Hashtbl.mem used_steps id in
  let source_inputs = ref [] in
  let source_bindings = ref [] in
  let add_source_input id source proposition =
    let binding = native_core_source_binding source_map id source proposition in
    if step_is_used id then
      source_bindings := !source_bindings @ [binding];
    if step_is_used id
       && not (native_core_source_is_set_reflexivity source_map source)
       && native_core_source_proof source_proofs id = None then
      source_inputs := !source_inputs @ [(id, proposition, binding)]
  in
  List.iter
    (function
      | Input (id, source, clause) ->
          let proposition = native_core_step_clause_prop cert variables id clause in
          add_source_input id source proposition
      | FormulaInput (id, source, literal) ->
          let proposition = native_core_step_clause_prop cert variables id [literal] in
          add_source_input id source proposition
      | FormulaTermInput (id, source, formula) ->
          let step_variables =
            if native_core_source_is_conjecture source then
              native_core_step_variables_for_terms cert id [formula]
            else
              native_core_step_variables cert id
          in
          let proposition =
            native_core_close_tm
              (variables @ step_variables)
              (native_core_formula_prop formula)
          in
          let proposition =
            List.fold_right (fun (_, tp) prop -> All (tp, prop)) step_variables proposition
          in
          add_source_input id source proposition
      | _ -> ())
    typed_steps;
  let source_count = List.length !source_inputs in
  let shifted_source_proofs =
    if source_count = 0 then source_proofs
    else
      List.map
        (fun (id, proof) -> (id, pfshift 0 source_count proof))
        source_proofs
  in
  let source_hyp_index id =
    let rec find index = function
      | [] -> None
    | (input_id, _, _) :: rest ->
          if input_id = id then Some (source_count - index - 1)
          else find (index + 1) rest
    in
    match find 0 !source_inputs with
    | Some index -> index
    | None -> error (id ^ ": native core proof-term checker lost source hypothesis")
  in
  let source_input_proposition id =
    let rec find = function
      | [] -> None
      | (input_id, proposition, _) :: rest ->
          if input_id = id then Some proposition else find rest
    in
    find !source_inputs
  in
  let lift_source_input_to_formula_step source_prop target_prop proof =
    let rec lift source_prop target_prop proof =
      match source_prop, target_prop with
      | All (source_tp, source_body), All (target_tp, target_body)
          when source_tp = target_tp ->
          TLam
            (target_tp,
             lift
               source_body
               target_body
               (PTmAp (pftmshift 0 1 proof, DB 0)))
      | _, All (tp, body) ->
          TLam
            (tp,
             lift
               (tmshift 0 1 source_prop)
               body
               (pftmshift 0 1 proof))
      | _ -> proof
    in
    lift source_prop target_prop proof
  in
  let variable_types = List.rev (List.map snd variables) in
  let closed_source_context =
    (!source_inputs
    |> List.map (fun (_, prop, _) -> prop)
    |> List.rev)
    @ external_hypotheses
  in
  let proof_delta = native_core_close_delta_table variables proof_delta in
  let definition_delta = native_core_close_delta_table variables raw_definition_delta in
  let normalize_generated_skolems ambient_shift =
    native_core_expand_generated_skolems_tm ~ambient_shift cert definition_delta
  in
  let proof_delta = native_core_merge_external_delta proof_delta external_delta_table in
  let check_step_proof id clause proof =
    let step_variables = native_core_step_variables cert id in
    let prop = native_core_step_clause_prop cert variables id clause in
    let proof = native_core_close_pf (variables @ step_variables) proof in
    native_core_reject_certificate_knowns "core" id proof;
    let debug_failure msg =
      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
        prerr_endline ("native core proof-term debug step " ^ id ^ ": " ^ msg);
        prerr_endline ("native core proposition: " ^ tm_to_str prop);
        prerr_endline ("native core proof: " ^ pf_to_str proof)
      end
    in
    try
      match check_propofpf proof_delta symbol_table variable_types closed_source_context proof prop [] with
      | Some _ -> ()
      | None ->
          debug_failure "wrong proposition";
          error
            (id ^ ": native core proof-term checker built a proof of the wrong proposition")
    with Failure msg ->
      debug_failure msg;
      error
        (id ^ ": native core proof-term checker built an ill-formed proof term: " ^ msg)
    | Error _ as exn -> raise exn
    | exn ->
        let msg = Printexc.to_string exn in
        debug_failure msg;
        error
          (id ^ ": native core proof-term checker built an ill-formed proof term: " ^ msg)
  in
  let table = Hashtbl.create 101 in
  let formula_table = Hashtbl.create 101 in
  let final_proof = ref None in
  let store id clause proof =
    check_step_proof id clause proof;
    Hashtbl.replace table id (clause, proof);
    if clause = [] then final_proof := Some proof
  in
  let check_formula_step_proof id formula proof =
    let step_variables = native_core_step_variables cert id in
    let prop = native_preprocess_step_formula_prop cert variables id formula in
    let proof = native_core_close_pf (variables @ step_variables) proof in
    let debug_failure msg =
      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
        prerr_endline ("native core proof-term debug formula step " ^ id ^ ": " ^ msg);
        prerr_endline ("native core formula proposition: " ^ tm_to_str prop);
        prerr_endline ("native core formula proof: " ^ pf_to_str proof)
      end
    in
    try
      match check_propofpf proof_delta symbol_table variable_types closed_source_context proof prop [] with
      | Some _ -> ()
      | None ->
          debug_failure "wrong proposition";
          error
            (id ^ ": native core proof-term checker built a formula proof of the wrong proposition")
    with Failure msg ->
      debug_failure msg;
      error
        (id ^ ": native core proof-term checker built an ill-formed formula proof term: " ^ msg)
    | Error _ as exn -> raise exn
    | exn ->
        let msg = Printexc.to_string exn in
        debug_failure msg;
        error
          (id ^ ": native core proof-term checker built an ill-formed formula proof term: " ^ msg)
  in
  let store_formula id formula proof =
    check_formula_step_proof id formula proof;
    Hashtbl.replace formula_table id (formula, proof)
  in
  let lookup id =
    try Hashtbl.find table id
    with Not_found ->
      error (id ^ ": native core proof-term checker references unknown parent")
  in
  let lookup_formula id =
    try Hashtbl.find formula_table id
    with Not_found ->
      error (id ^ ": native core proof-term checker references unknown formula parent")
  in
  List.iter
    (function
      | Input (id, source, clause)
          when native_core_source_is_set_reflexivity source_map source ->
          if step_is_used id then
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> native_core_set_reflexivity_clause_proof id clause
            in
            store id clause proof
      | Input (id, _, clause) ->
          if step_is_used id then begin
            let _ = native_core_clause_prop id clause in
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> Hyp (source_hyp_index id)
            in
            store id clause proof
          end
      | FormulaInput (id, source, literal)
          when native_core_source_is_set_reflexivity source_map source ->
          if step_is_used id then begin
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> native_core_set_reflexivity_literal_proof id literal
            in
            store id [literal] proof;
            store_formula id (native_core_literal_prop literal) proof
          end
      | FormulaInput (id, _, literal) ->
          if step_is_used id then begin
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> Hyp (source_hyp_index id)
            in
            store id [literal] proof;
            store_formula id (native_core_literal_prop literal) proof
          end
      | FormulaTermInput (id, source, formula)
          when native_core_source_is_set_reflexivity source_map source ->
          if step_is_used id then begin
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> native_core_set_reflexivity_atom_proof id formula
            in
            store_formula id formula proof
          end
      | FormulaTermInput (id, _, formula) ->
          if step_is_used id then begin
            let target_prop =
              native_preprocess_step_formula_prop cert variables id formula
            in
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None ->
                  let source_proof = Hyp (source_hyp_index id) in
                  begin match source_input_proposition id with
                  | Some source_prop ->
                      lift_source_input_to_formula_step
                        source_prop target_prop source_proof
                  | None -> source_proof
                  end
            in
            store_formula id formula proof
          end
      | FormulaTermCopy (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          if parent_formula <> result then
            error (id ^ ": native core proof-term formula_term_copy is not an identity copy");
          store_formula id result parent_proof
      | RectifyFormula (id, parent_id, renamings, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          check_native_rectify_formula id parent_id renamings parent_formula result;
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          let parent_variable_map =
            kernel_v1_substitution_field cert id "rectify_variable_map"
          in
          store_formula id result
            (native_core_formula_orientation_proof
               ~parent_variable_map
               id variables parent_step_variables result_step_variables
               parent_formula result parent_proof)
      | FoolAtomLift (id, source, target, path) ->
          check_fool_atom_lift id source target path
      | FoolFormula (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          check_fool_formula [(parent_id, CheckedFormula parent_formula)] id parent_id result;
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          store_formula id result
            (native_core_fool_formula_proof
               id symbol_table variables parent_step_variables result_step_variables
               parent_formula result parent_proof)
      | FoolBool (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          check_fool_bool [(parent_id, CheckedFormula parent_formula)] id parent_id result;
          store_formula id (formula_tm_of_literal result)
            (native_core_fool_bool_proof id variables parent_formula parent_proof result)
      | EnnfFormula (id, parent_id, source, pairs, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          check_ennf_formula [(parent_id, CheckedFormula parent_formula)] id parent_id source pairs result;
          let result_step_variables = native_core_step_variables cert id in
          store_formula id result
            (native_core_ennf_formula_proof
               id variables result_step_variables parent_formula result parent_proof)
      | SkolemFormula (id, parent_id, source, introductions, subst, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          let check_parent_formula =
            match source with
            | Some source -> source
            | None -> parent_formula
          in
          check_skolem_formula
            [(parent_id, CheckedFormula check_parent_formula)]
            id parent_id source introductions subst result;
          let source_formula =
            match source with
            | Some source -> source
            | None -> parent_formula
          in
          let subst =
            native_core_reorder_skolem_substitution_by_source cert id subst
          in
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          let helper_formulas =
            native_core_skolem_parent_helper_formulas cert id
          in
          let skolem_proof_object =
            native_core_skolem_proof_object cert id
          in
          native_core_debug_skolem_proof_object id skolem_proof_object;
          let skolem_contract =
            Option.map
              (fun proof_object ->
                 proof_object.Vampire_kernel_syntax.skolem_proof_contract)
              skolem_proof_object
          in
          let introduced_names_from_step =
            introductions
            |> List.filter_map
                 (fun introduction ->
                    native_core_ident_opt introduction.skolem_intro_symbol)
          in
          let introduced_names_from_contract =
            native_core_skolem_contract_introduced_names skolem_contract
          in
          let introduced_names =
            List.sort_uniq
              String.compare
              (introduced_names_from_step @ introduced_names_from_contract)
          in
          let register_witness_replacement target_witness epsilon_witness =
            match native_core_flatten_value_application target_witness with
            | TmH raw_name, [] ->
                begin match native_core_ident_opt raw_name with
                | Some name when List.mem name introduced_names ->
                    let closed_witness =
                      native_core_close_tm variables epsilon_witness
                      |> tm_beta_eta_norm
                    in
                    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                      prerr_endline
                        (id
                         ^ ": native core skolem registered witness definition "
                         ^ name
                         ^ " := "
                         ^ tm_to_str closed_witness);
                    if native_core_tm_scoped_under (List.length variables) closed_witness then begin
                      if not (Hashtbl.mem proof_delta name) then
                        Hashtbl.replace proof_delta name (0, closed_witness);
                      if not (Hashtbl.mem definition_delta name) then
                        Hashtbl.replace definition_delta name (0, closed_witness)
                    end else if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                      prerr_endline
                        (id
                         ^ ": native core skolem kept context-dependent witness "
                         ^ name
                         ^ " out of arity-zero delta tables")
                | _ -> ()
                end
            | TmH raw_name, _ :: _ ->
                begin match native_core_ident_opt raw_name with
                | Some name when List.mem name introduced_names
                                 && Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" ->
                    prerr_endline
                      (id
                       ^ ": native core skolem deferred dependent witness definition for "
                       ^ name)
                | _ -> ()
                end
            | _ -> ()
          in
          let proof =
            try
              native_core_skolem_formula_proof
                ~normalize_formula_for_match:normalize_generated_skolems
                ~register_witness_replacement
                id variables parent_step_variables result_step_variables
                subst source_formula result parent_proof
            with (Error _ | Failure _) as exn ->
              if helper_formulas = [] then raise exn
              else
                native_core_skolem_formula_proof
                  ~helper_formulas
                  ~normalize_formula_for_match:normalize_generated_skolems
                  ~register_witness_replacement
                  id variables parent_step_variables result_step_variables
                  subst source_formula result parent_proof
          in
          store_formula id result
            proof
      | FormulaCopy (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          if native_core_normalize_bool_constants (native_core_literal_prop result)
             <> native_core_normalize_bool_constants (native_core_formula_prop parent_formula) then
            error (id ^ ": native core proof-term formula_copy result is not the parent formula");
          store_formula id (formula_tm_of_literal result) parent_proof;
          store id [result] parent_proof
      | CnfLiteral (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          let parent_prop =
            native_core_normalize_bool_constants
              (native_core_formula_prop parent_formula)
          in
          let result_prop =
            native_core_normalize_bool_constants
              (native_core_clause_prop id result)
          in
          if parent_prop <> result_prop then
            error
              (id ^ ": native core proof-term cnf_literal result is not propositionally identical to the parent formula");
          store id result parent_proof
      | CnfFormulaClause (id, parent_id, _index, _count, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          store id result
            (native_core_cnf_formula_clause_proof
               id variables parent_step_variables result_step_variables
               parent_formula result parent_proof)
      | DefinitionInput (id, result) ->
          check_definition_input id result;
          let result_step_variables = native_core_step_variables cert id in
          store id result
            (native_core_definition_input_proof
               proof_delta id variables result_step_variables result)
      | DefinitionRewriteChain (id, parent_id, rewrites, result) ->
          let parent_clause, parent_proof = lookup parent_id in
          store id result
            (native_core_definition_rewrite_chain_proof
               cert id variables parent_id parent_clause parent_proof
               rewrites result lookup)
      | FoolExhaustiveness (id, result) ->
          check_fool_exhaustiveness id result;
          store id result
            (native_core_fool_exhaustiveness_proof cert id result)
      | InequalityNameIntro (id, result) ->
          check_inequality_name_intro id result;
          store id result
            (native_core_inequality_name_intro_proof cert symbol_table id variables result)
      | InequalitySplit (id, source_id, splits, result) ->
          List.iter
            (fun split -> ignore (lookup split.split_name_parent))
            splits;
          let source_clause, source_proof = lookup source_id in
          store id result
            (native_core_inequality_split_proof
               cert id variables source_id source_clause source_proof splits result)
      | Substitute (id, parent_id, [], result) ->
          let parent_clause, parent_proof = lookup parent_id in
          let proof =
            native_core_substitute_in_result_context
              cert id variables parent_id parent_clause [] parent_proof result
          in
          store id result proof
      | Substitute (id, parent_id, subst, result) ->
          let parent_clause, parent_proof = lookup parent_id in
          let proof =
            native_core_substitute_in_result_context
              cert id variables parent_id parent_clause subst parent_proof result
          in
          store id result proof
      | Resolve (id, left_id, right_id, left_index, right_index, result) ->
          let left_clause, left_proof = lookup left_id in
          let right_clause, right_proof = lookup right_id in
          let proof =
            native_core_resolve_in_result_context
              cert id variables left_id left_clause left_proof right_id right_clause right_proof
              left_index right_index result
          in
          store id result proof
      | Factor (id, parent_id, left_index, right_index, result) ->
          let parent_clause, parent_proof = lookup parent_id in
          let proof =
            native_core_factor_in_result_context
              cert id variables parent_id parent_clause parent_proof
              left_index right_index result
          in
          store id result proof
      | EqualityResolution (id, parent_id, literal_index, result) ->
          let parent_clause, parent_proof = lookup parent_id in
          let proof =
            native_core_equality_resolution_in_result_context
              cert id variables parent_id parent_clause parent_proof literal_index result
          in
          store id result proof
      | EqualitySymmetry (id, parent_id, literal_index, result) ->
          let parent_clause, parent_proof = lookup parent_id in
          let proof =
            native_core_equality_symmetry_in_result_context
              cert id variables parent_id parent_clause parent_proof literal_index result
          in
          store id result proof
      | EqualityFactoring (id, parent_id, selected_index, other_index, _, subst, result) ->
          let parent_clause, parent_proof = lookup parent_id in
          let proof =
            native_core_equality_factoring_in_result_context
              cert id variables parent_id parent_clause parent_proof
              selected_index other_index subst result
          in
          store id result proof
	      | TruthConflict (id, parent_id, literal_index, result) ->
	          let parent_clause, parent_proof = lookup parent_id in
	          let proof =
	            native_core_truth_conflict_in_result_context
                cert id variables parent_id parent_clause parent_proof literal_index result
	          in
	          store id result proof
	      | SubsumptionResolution (id, main_parent_id, side_parent_id, selected, side_pivot, side_subst, result) ->
	          let main_clause, main_proof = lookup main_parent_id in
	          let side_clause, side_proof = lookup side_parent_id in
          let side_clause = subst_clause side_subst side_clause in
          let side_pivot = subst_literal side_subst side_pivot in
          let side_proof =
            native_core_instantiate_step_proof cert side_parent_id side_subst side_proof
          in
          let proof =
            native_core_subsumption_resolution_unit
              id main_clause main_proof side_clause side_proof selected side_pivot result
          in
          store id result proof
      | Paramodulate (id, equality_parent_id, target_parent_id, equality_index, target_index, position, from_tm, to_tm, result) ->
          let equality_clause, equality_proof = lookup equality_parent_id in
          let target_clause, target_proof = lookup target_parent_id in
          let proof =
            native_core_paramodulate_unit_in_result_context
              cert id variables equality_parent_id equality_clause equality_proof
              target_parent_id target_clause target_proof
              equality_index target_index position from_tm to_tm result
          in
          store id result proof
      | Contradiction (id, parent_id) ->
          let parent_clause, parent_proof = lookup parent_id in
          if parent_clause <> [] then
            error (id ^ ": native core proof-term contradiction parent is not empty");
          store id [] parent_proof
      | UnitResultingResolution (id, _, _, _) ->
          error
            (id
             ^ ": native core proof-term checker requires unit_resulting_resolution to be lowered to primitive certificate steps")
      | step ->
          error
            (step_id step ^ ": native core proof-term checker has no proof-term rule for "
             ^ step_rule_name step))
    typed_steps;
  let proof =
    match !final_proof with
    | Some proof -> proof
    | None -> error "native core proof-term checker found no empty-clause proof"
  in
  let body_prop =
    List.fold_right
      (fun (_, assumption, _) target -> Imp (assumption, target))
      !source_inputs
      native_core_false
  in
  let body_proof =
    List.fold_right
      (fun (_, assumption, _) proof -> PLam (assumption, proof))
      !source_inputs
      proof
  in
  let closed_prop = native_core_close_tm variables body_prop in
  let closed_proof = native_core_close_pf variables body_proof in
  {
    core_native_proposition =
      List.fold_right (fun (_, tp) prop -> All (tp, prop)) variables closed_prop;
    core_native_proof =
      List.fold_right (fun (_, tp) proof -> TLam (tp, proof)) variables closed_proof;
    core_native_delta_table = definition_delta;
    core_native_symbol_table = symbol_table;
    core_native_steps = core_steps;
    core_native_source_bindings = !source_bindings;
    core_native_source_assumption_bindings =
      List.map (fun (_, _, binding) -> binding) !source_inputs;
    core_native_source_assumptions = source_count;
  }

let elaborate_preprocess_refutation_native
    ?(source_map=[])
    ?(source_proofs=[])
    ?(external_hypotheses=[])
    ?(external_delta_table=Hashtbl.create 0)
    ?(external_definition_names=[])
    cert =
  ignore (check_certificate_strict cert);
  let variables = native_core_proof_variables ~exclude_names:external_definition_names cert in
  let symbol_table = native_core_symbol_table cert in
  let proof_delta, raw_definition_delta = native_core_certificate_sgdelta cert symbol_table in
  let typed_steps =
    List.map
      (native_core_type_raw_equalities_step cert variables symbol_table)
      cert.steps
  in
  let used_steps = proof_dependency_closure typed_steps in
  let step_is_used id = Hashtbl.mem used_steps id in
  let source_inputs = ref [] in
  let source_bindings = ref [] in
  let add_source_input id source proposition =
    let binding = native_core_source_binding source_map id source proposition in
    source_bindings := !source_bindings @ [binding];
    if step_is_used id
       && not (native_core_source_is_set_reflexivity source_map source)
       && native_core_source_proof source_proofs id = None then
      source_inputs := !source_inputs @ [(id, proposition, binding)]
  in
  List.iter
    (function
      | Input (id, source, clause) ->
          let proposition = native_core_step_clause_prop cert variables id clause in
          add_source_input id source proposition
      | FormulaInput (id, source, literal) ->
          let proposition =
            native_core_step_clause_prop cert variables id [literal]
          in
          add_source_input id source proposition
      | FormulaTermInput (id, source, formula) ->
          let step_variables =
            if native_core_source_is_conjecture source then
              native_core_step_variables_for_terms cert id [formula]
            else
              native_core_step_variables cert id
          in
          let proposition =
            native_core_close_tm
              (variables @ step_variables)
              (native_core_formula_prop formula)
          in
          let proposition =
            List.fold_right (fun (_, tp) prop -> All (tp, prop)) step_variables proposition
          in
          add_source_input id source proposition
      | _ -> ())
    typed_steps;
  let source_count = List.length !source_inputs in
  let shifted_source_proofs =
    if source_count = 0 then source_proofs
    else
      List.map
        (fun (id, proof) -> (id, pfshift 0 source_count proof))
        source_proofs
  in
  let source_hyp_index id =
    let rec find index = function
      | [] -> None
      | (input_id, _, _) :: rest ->
          if input_id = id then Some (source_count - index - 1)
          else find (index + 1) rest
    in
    match find 0 !source_inputs with
    | Some index -> index
    | None -> error (id ^ ": native preprocess proof-term checker lost source hypothesis")
  in
  let source_input_proposition id =
    let rec find = function
      | [] -> None
      | (input_id, proposition, _) :: rest ->
          if input_id = id then Some proposition else find rest
    in
    find !source_inputs
  in
  let lift_source_input_to_formula_step source_prop target_prop proof =
    let rec lift source_prop target_prop proof =
      match source_prop, target_prop with
      | All (source_tp, source_body), All (target_tp, target_body)
          when source_tp = target_tp ->
          TLam
            (target_tp,
             lift
               source_body
               target_body
               (PTmAp (pftmshift 0 1 proof, DB 0)))
      | _, All (tp, body) ->
          TLam
            (tp,
             lift
               (tmshift 0 1 source_prop)
               body
               (pftmshift 0 1 proof))
      | _ -> proof
    in
    lift source_prop target_prop proof
  in
  let variable_types = List.rev (List.map snd variables) in
  let closed_source_context =
    (!source_inputs
    |> List.map (fun (_, prop, _) -> prop)
    |> List.rev)
    @ external_hypotheses
  in
  let proof_delta = native_core_close_delta_table variables proof_delta in
  let definition_delta = native_core_close_delta_table variables raw_definition_delta in
  let normalize_generated_skolems ambient_shift =
    native_core_expand_generated_skolems_tm ~ambient_shift cert definition_delta
  in
  let proof_delta = native_core_merge_external_delta proof_delta external_delta_table in
  let short_tm tm =
    let text = tm_to_str tm in
    if String.length text <= 700 then text
    else String.sub text 0 700 ^ "..."
  in
  let short_pf pf =
    let text = pf_to_str pf in
    if String.length text <= 700 then text
    else String.sub text 0 700 ^ "..."
  in
  let check_step_proof id prop proof =
    let step_variables = native_core_step_variables cert id in
    let proof = native_core_close_pf (variables @ step_variables) proof in
    native_core_reject_certificate_knowns "preprocess" id proof;
    let debug_failure msg =
      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
        prerr_endline ("native preprocess proof-term debug step " ^ id ^ ": " ^ msg);
        prerr_endline ("native preprocess expected proposition: " ^ short_tm prop);
        begin
          try
            let actual, _ =
              extr_propofpf proof_delta symbol_table variable_types closed_source_context proof []
            in
            prerr_endline ("native preprocess actual proposition: " ^ short_tm actual)
          with exn ->
            prerr_endline
              ("native preprocess actual proposition unavailable: "
               ^ Printexc.to_string exn)
        end;
        prerr_endline ("native preprocess proof: " ^ short_pf proof)
      end
    in
    try
      match check_propofpf proof_delta symbol_table variable_types closed_source_context proof prop [] with
      | Some _ -> ()
      | None ->
          debug_failure "wrong proposition";
          error
            (id ^ ": native preprocess proof-term checker built a proof of the wrong proposition")
    with Failure msg ->
      debug_failure msg;
      error
        (id ^ ": native preprocess proof-term checker built an ill-formed proof term: " ^ msg)
    | Error _ as exn -> raise exn
    | exn ->
        let msg = Printexc.to_string exn in
        debug_failure msg;
        error
          (id ^ ": native preprocess proof-term checker built an ill-formed proof term: " ^ msg)
  in
  let clause_table = Hashtbl.create 101 in
  let formula_table = Hashtbl.create 101 in
  let avatar_definition_table = Hashtbl.create 17 in
  let transitional_primitive_formula_steps = Hashtbl.create 17 in
  let transitional_primitive_clause_steps = Hashtbl.create 17 in
  let skolem_cps_entries = ref [] in
  let skolem_witness_replacements = ref [] in
  let skolem_witness_raw_replacements = ref [] in
  let final_proof = ref None in
  let first_stored_choice_witness = ref None in
  let debug_stored_choice_witness kind id proof =
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
      match !first_stored_choice_witness with
      | Some _ -> ()
      | None ->
          begin match native_core_pf_choice_witness_detail proof with
          | None -> ()
          | Some detail ->
              first_stored_choice_witness := Some (kind, id, detail);
              prerr_endline
                (id ^ ": native preprocess first stored "
                 ^ kind
                 ^ " proof containing certificate-local choice witness: "
                 ^ detail)
          end
  in
  let store_clause id clause proof =
    let prop = native_core_step_clause_prop cert variables id clause in
    check_step_proof id prop proof;
    debug_stored_choice_witness "clause" id proof;
    Hashtbl.replace clause_table id (clause, proof);
    if clause = [] then final_proof := Some proof
  in
  let store_formula id formula proof =
    let prop = native_preprocess_step_formula_prop cert variables id formula in
    check_step_proof id prop proof;
    debug_stored_choice_witness "formula" id proof;
    Hashtbl.replace formula_table id (formula, proof)
  in
  let final_refutation_proof_checks proof =
    let rec proof_node_count = function
      | Hyp _ | Known _ -> 1
      | PTpAp (body, _) -> 1 + proof_node_count body
      | PTmAp (body, _) -> 1 + proof_node_count body
      | PPfAp (left, right) -> 1 + proof_node_count left + proof_node_count right
      | PLam (_, body) -> 1 + proof_node_count body
      | TLam (_, body) -> 1 + proof_node_count body
    in
    let short_tm tm =
      let text = tm_to_str tm in
      if String.length text <= 500 then text
      else String.sub text 0 500 ^ "..."
    in
    let short_pf pf =
      let text = pf_to_str pf in
      if String.length text <= 500 then text
      else String.sub text 0 500 ^ "..."
    in
    let first_tm_difference left right =
      let rec find path left right =
        if left = right then None
        else
          match left, right with
          | TpAp (left_body, left_tp), TpAp (right_body, right_tp) ->
              if left_tp <> right_tp then Some (path ^ ".type", left, right)
              else find (path ^ ".tpap") left_body right_body
          | Ap (left_fun, left_arg), Ap (right_fun, right_arg) ->
              begin match find (path ^ ".fun") left_fun right_fun with
              | Some _ as found -> found
              | None -> find (path ^ ".arg") left_arg right_arg
              end
          | Lam (left_tp, left_body), Lam (right_tp, right_body)
          | All (left_tp, left_body), All (right_tp, right_body) ->
              if left_tp <> right_tp then Some (path ^ ".binder-type", left, right)
              else find (path ^ ".body") left_body right_body
          | Imp (left_a, left_b), Imp (right_a, right_b) ->
              begin match find (path ^ ".left") left_a right_a with
              | Some _ as found -> found
              | None -> find (path ^ ".right") left_b right_b
              end
          | _ -> Some (path, left, right)
      in
      find "root" left right
    in
    let find_bad_application proof =
      let rec find path cxtm cxpf proof =
        match proof with
        | PPfAp (left, right) ->
            begin match find (path ^ ".left") cxtm cxpf left with
            | Some _ as found -> found
            | None ->
                begin match find (path ^ ".right") cxtm cxpf right with
                | Some _ as found -> found
                | None ->
            begin
              try
                let left_prop, _ =
                  extr_propofpf proof_delta symbol_table cxtm cxpf left []
                in
                match tm_beta_eta_norm left_prop with
                | Imp (expected, _) ->
                    begin
                      try
                        let right_prop, _ =
                          extr_propofpf proof_delta symbol_table cxtm cxpf right []
                        in
                        if tm_beta_eta_norm expected <> tm_beta_eta_norm right_prop then
                          let expected = tm_beta_eta_norm expected in
                          let right_prop = tm_beta_eta_norm right_prop in
                          let diff =
                            match first_tm_difference expected right_prop with
                            | None -> ""
                            | Some (diff_path, diff_expected, diff_actual) ->
                                "; first diff "
                                ^ diff_path
                                ^ "; diff expected "
                                ^ short_tm diff_expected
                                ^ "; diff actual "
                                ^ short_tm diff_actual
                          in
                          let context_sample =
                            cxpf
                            |> List.mapi (fun index prop -> "__" ^ string_of_int index ^ ":" ^ short_tm prop)
                            |> fun props ->
                                let rec take n = function
                                  | _ when n = 0 -> []
                                  | [] -> []
                                  | x :: xs -> x :: take (n - 1) xs
                                in
                                String.concat " | " (take 6 props)
                          in
                          Some
                            (path
                             ^ ": implication argument mismatch; expected "
                             ^ short_tm expected
                             ^ "; actual "
                             ^ short_tm right_prop
                             ^ diff
                             ^ "; term ctx depth "
                             ^ string_of_int (List.length cxtm)
                             ^ "; proof ctx depth "
                             ^ string_of_int (List.length cxpf)
                             ^ "; proof ctx top "
                             ^ context_sample
                             ^ "; left proof "
                             ^ short_pf left
                             ^ "; right proof "
                             ^ short_pf right)
                        else None
                      with exn ->
                        Some
                          (path
                           ^ ": could not extract right proposition: "
                           ^ Printexc.to_string exn)
                    end
                | prop ->
                    Some (path ^ ": left proposition is not implication: " ^ short_tm prop)
              with exn ->
                Some (path ^ ": could not extract left proposition: " ^ Printexc.to_string exn)
            end
                end
            end
        | PTpAp (body, _) -> find (path ^ ".tp") cxtm cxpf body
        | PTmAp (body, _) -> find (path ^ ".tm") cxtm cxpf body
        | PLam (prop, body) -> find (path ^ ".plam") cxtm (prop :: cxpf) body
        | TLam (tp, body) ->
            let cxtm = tp :: cxtm in
            let cxpf = List.map (fun prop -> tmshift 0 1 prop) cxpf in
            find (path ^ ".tlam") cxtm cxpf body
        | Hyp _ | Known _ -> None
      in
      find "root" variable_types closed_source_context proof
    in
    let debug_failure msg =
      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
        prerr_endline ("native preprocess final refutation proof debug: " ^ msg);
        prerr_endline
          ("native preprocess final refutation proof nodes: "
           ^ string_of_int (proof_node_count proof));
        begin match find_bad_application proof with
        | Some detail ->
            prerr_endline
              ("native preprocess final refutation first bad application: " ^ detail)
        | None -> ()
        end
      end
    in
    try
      match check_propofpf proof_delta symbol_table variable_types closed_source_context proof native_core_false [] with
      | Some _ -> true
      | None ->
          debug_failure "wrong proposition";
          false
    with Failure msg ->
      debug_failure msg;
      false
    | Error _ as exn -> raise exn
    | exn ->
        debug_failure (Printexc.to_string exn);
        false
  in
  let abstract_skolem_result_by_prop result_prop result_proof shifted_final =
    let replaced = ref 0 in
    let rec tm_app_spine args = function
      | PTmAp (body, tm) -> tm_app_spine (tm :: args) body
      | head -> head, args
    in
    let rebuild_tm_app_spine head args =
      List.fold_left (fun proof tm -> PTmAp (proof, tm)) head args
    in
    let rec replace term_depth proof_depth cxtm cxpf proof =
      let proof =
        let expected_head =
          result_proof
          |> pftmshift 0 term_depth
          |> pfshift proof_depth 1
        in
        let head, args = tm_app_spine [] proof in
        if args <> [] && head = expected_head then begin
          incr replaced;
          rebuild_tm_app_spine (Hyp proof_depth) args
        end else
          let expected = tmshift 0 term_depth result_prop in
          try
            match check_propofpf proof_delta symbol_table cxtm cxpf proof expected [] with
            | Some _ ->
                incr replaced;
                Hyp proof_depth
            | None -> proof
          with _ -> proof
      in
      match proof with
      | PTpAp (body, tp) ->
          PTpAp (replace term_depth proof_depth cxtm cxpf body, tp)
      | PTmAp (body, tm) ->
          PTmAp (replace term_depth proof_depth cxtm cxpf body, tm)
      | PPfAp (left, right) ->
          PPfAp
            (replace term_depth proof_depth cxtm cxpf left,
             replace term_depth proof_depth cxtm cxpf right)
      | PLam (prop, body) ->
          PLam (prop, replace term_depth (proof_depth + 1) cxtm (prop :: cxpf) body)
      | TLam (tp, body) ->
          let cxtm = tp :: cxtm in
          let cxpf = List.map (fun prop -> tmshift 0 1 prop) cxpf in
          TLam (tp, replace (term_depth + 1) proof_depth cxtm cxpf body)
      | Hyp _ | Known _ -> proof
    in
    let body =
      replace
        0
        0
        variable_types
        (result_prop :: closed_source_context)
        shifted_final
    in
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" && !replaced > 0 then
      prerr_endline
        ("native preprocess Skolem CPS abstracted "
         ^ string_of_int !replaced
         ^ " result subproof(s)");
    if !replaced > 0 then Some body else None
  in
  let store_avatar_definition_with_key key id split_name component_literals proof =
    let split_prop = native_core_literal_prop (Pos (TmH split_name)) in
    let component_prop =
      native_core_step_clause_prop cert [] id component_literals
    in
    let prop =
      native_core_and
        (Imp (split_prop, component_prop))
        (Imp (component_prop, split_prop))
      |> native_core_normalize_bool_constants
      |> native_core_close_tm variables
    in
    check_step_proof id prop proof;
    let table_proof =
      native_core_avatar_definition_proof_from_components
        cert [] id split_name component_literals
    in
    Hashtbl.replace
      avatar_definition_table
      key
      (split_name, component_literals, component_prop, table_proof)
  in
  let store_avatar_definition id split_name component_literals proof =
    store_avatar_definition_with_key id id split_name component_literals proof
  in
  let seed_avatar_metadata_definitions () =
    native_core_avatar_metadata_definitions cert
    |> List.iter
         (fun (id, split_name, component_literals) ->
            let proof =
              native_core_avatar_definition_proof_from_components
                cert variables id split_name component_literals
            in
            store_avatar_definition_with_key
              (id ^ "__" ^ split_name)
              id
              split_name
              component_literals
              proof)
  in
  let lookup_clause id =
    try Hashtbl.find clause_table id
    with Not_found ->
      error (id ^ ": native preprocess proof-term checker references unknown clause parent")
  in
  let lookup_formula id =
    try Hashtbl.find formula_table id
    with Not_found ->
      error (id ^ ": native preprocess proof-term checker references unknown formula parent")
  in
  let checked_formulas () =
    Hashtbl.fold
      (fun formula_id (formula, _) checked ->
         (formula_id, CheckedFormula formula) :: checked)
      formula_table
      []
  in
  let install_transitional_known id primitive prop =
    match Sys.getenv_opt "MEGALODON_CERT_ALLOW_TRANSITIONAL_PREPROCESS_KNOWN" with
    | Some "1" ->
        Hashtbl.replace proof_delta primitive (0, prop);
        Hashtbl.replace definition_delta primitive (0, prop)
    | _ ->
        error
          (id ^ ": native preprocess proof-term checker refuses certificate-derived Known primitive "
           ^ primitive
           ^ "; implement a real proof term or run a structural diagnostic with MEGALODON_CERT_ALLOW_TRANSITIONAL_PREPROCESS_KNOWN=1")
  in
  let step_by_id id =
    List.find_opt (fun step -> step_id step = id) typed_steps
  in
  let formula_step_uses_closed_primitive id =
    Hashtbl.mem transitional_primitive_formula_steps id
  in
  let cnf_step_uses_closed_parent_primitive id =
    match step_by_id id with
    | Some (CnfFormulaClause (_, parent_id, _, _, _)) ->
        formula_step_uses_closed_primitive parent_id
    | _ -> false
  in
  let substitute_proof id parent_id parent_clause subst parent_proof result =
    let use_primitive =
      cnf_step_uses_closed_parent_primitive parent_id
      || Hashtbl.mem transitional_primitive_clause_steps parent_id
    in
    if use_primitive then begin
      let source_clause =
        subst_clause subst parent_clause
      in
      if not (same_clause_multiset source_clause result) then
        error
          (id ^ ": native proof-term checker instantiation substitution does not produce result clause");
      let parent_prop =
        native_core_step_clause_prop cert variables parent_id parent_clause
      in
      let result_prop =
        native_core_step_clause_prop cert variables id result
      in
      let primitive = "vampire_substitute_" ^ id in
      let primitive_prop = Imp (parent_prop, result_prop) in
      install_transitional_known id primitive primitive_prop;
      Hashtbl.replace transitional_primitive_clause_steps id true;
      PPfAp (Known primitive, parent_proof)
    end else
      native_core_substitute_in_result_context
        cert id variables parent_id parent_clause subst parent_proof result
  in
  let substitute_step_uses_closed_parent_primitive id =
    match step_by_id id with
    | Some (Substitute (_, parent_id, _, _)) ->
        cnf_step_uses_closed_parent_primitive parent_id
    | _ -> false
  in
  let shadow_skolem_final_refutation
      ?skolem_assumption_prop
      ?skolem_assumption_step_variables
      skolem_id result_checked_prop result_formula =
    let skolem_assumption_prop =
      match skolem_assumption_prop with
      | Some prop -> prop
      | None -> result_checked_prop
    in
    let skolem_assumption_step_variables =
      match skolem_assumption_step_variables with
      | Some step_variables -> step_variables
      | None -> native_core_step_variables cert skolem_id
    in
    let shadow_clause_table = Hashtbl.create 101 in
    let shadow_formula_table = Hashtbl.create 101 in
    let shadow_final_proof = ref None in
    let first_shadow_choice = ref None in
    let shadow_context = skolem_assumption_prop :: closed_source_context in
    let debug_shadow_choice kind id proof =
      if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
        match !first_shadow_choice with
        | Some _ -> ()
        | None ->
            let witness = native_core_pf_choice_witness_detail proof in
            let theorem = native_core_pf_choice_known_detail proof in
            begin match witness, theorem with
            | None, None -> ()
            | _ ->
                first_shadow_choice := Some id;
                begin match witness with
                | Some detail ->
                    prerr_endline
                      (id ^ ": native preprocess Skolem shadow first stored "
                       ^ kind ^ " choice witness: " ^ detail)
                | None -> ()
                end;
                begin match theorem with
                | Some detail ->
                    prerr_endline
                      (id ^ ": native preprocess Skolem shadow first stored "
                       ^ kind ^ " choice theorem: " ^ detail)
                | None -> ()
                end
            end
    in
    let shadow_step_variables id =
      if id = skolem_id then skolem_assumption_step_variables
      else native_core_step_variables cert id
    in
    let check_shadow_step_proof id prop proof =
      let step_variables = shadow_step_variables id in
      let proof = native_core_close_pf (variables @ step_variables) proof in
      native_core_reject_certificate_knowns "preprocess-shadow" id proof;
      let debug_failure msg =
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
          prerr_endline ("native preprocess Skolem shadow debug step " ^ id ^ ": " ^ msg);
          prerr_endline ("native preprocess Skolem shadow proposition: " ^ tm_to_str prop);
          prerr_endline ("native preprocess Skolem shadow proof: " ^ pf_to_str proof)
        end
      in
      try
        match check_propofpf proof_delta symbol_table variable_types shadow_context proof prop [] with
        | Some _ -> ()
        | None ->
            debug_failure "wrong proposition";
            error
              (id ^ ": native preprocess Skolem shadow built a proof of the wrong proposition")
      with Failure msg ->
        debug_failure msg;
        error
          (id ^ ": native preprocess Skolem shadow built an ill-formed proof term: " ^ msg)
      | Error _ as exn -> raise exn
      | exn ->
          let msg = Printexc.to_string exn in
          debug_failure msg;
          error
            (id ^ ": native preprocess Skolem shadow built an ill-formed proof term: " ^ msg)
    in
    let store_shadow_clause id clause proof =
      let prop = native_core_step_clause_prop cert variables id clause in
      check_shadow_step_proof id prop proof;
      debug_shadow_choice "clause" id proof;
      Hashtbl.replace shadow_clause_table id (clause, proof);
      if clause = [] then shadow_final_proof := Some proof
    in
    let store_shadow_formula id formula proof =
      let prop = native_preprocess_step_formula_prop cert variables id formula in
      check_shadow_step_proof id prop proof;
      debug_shadow_choice "formula" id proof;
      Hashtbl.replace shadow_formula_table id (formula, proof)
    in
    let store_shadow_formula_with_prop id formula prop proof =
      check_shadow_step_proof id prop proof;
      debug_shadow_choice "formula" id proof;
      Hashtbl.replace shadow_formula_table id (formula, proof)
    in
    let shifted_normal_formula id =
      let formula, proof = lookup_formula id in
      (formula, pfshift 0 1 proof)
    in
    let shifted_normal_clause id =
      let clause, proof = lookup_clause id in
      (clause, pfshift 0 1 proof)
    in
    let shadow_formula_parent id =
      match Hashtbl.find_opt shadow_formula_table id with
      | Some parent -> parent
      | None -> shifted_normal_formula id
    in
    let shadow_clause_parent id =
      match Hashtbl.find_opt shadow_clause_table id with
      | Some parent -> parent
      | None -> shifted_normal_clause id
    in
    let has_shadow_formula id = Hashtbl.mem shadow_formula_table id in
    let has_shadow_clause id = Hashtbl.mem shadow_clause_table id in
    let combined_shadow_clause_table () =
      let table = Hashtbl.create 101 in
      Hashtbl.iter
        (fun id (clause, proof) ->
           Hashtbl.replace table id (clause, pfshift 0 1 proof))
        clause_table;
      Hashtbl.iter
        (fun id value -> Hashtbl.replace table id value)
        shadow_clause_table;
      table
    in
    let shadow_avatar_definition_table =
      let table = Hashtbl.create 17 in
      Hashtbl.iter
        (fun key (split_name, component_literals, component_prop, definition_proof) ->
           Hashtbl.replace
             table
             key
             (split_name, component_literals, component_prop, pfshift 0 1 definition_proof))
        avatar_definition_table;
      table
    in
    let replay_step = function
      | SkolemFormula (id, _, _, _, _, _) when id = skolem_id ->
          store_shadow_formula_with_prop
            id result_formula skolem_assumption_prop (Hyp 0)
      | FormulaTermCopy (id, parent_id, result) when has_shadow_formula parent_id ->
          let parent_formula, parent_proof = shadow_formula_parent parent_id in
          if parent_formula <> result then
            error (id ^ ": native preprocess Skolem shadow formula_term_copy is not an identity copy");
          store_shadow_formula id result parent_proof
      | FormulaCopy (id, parent_id, result) when has_shadow_formula parent_id ->
          let parent_formula, parent_proof = shadow_formula_parent parent_id in
          if native_core_normalize_bool_constants (native_core_literal_prop result)
             <> native_core_normalize_bool_constants (native_core_formula_prop parent_formula) then
            error (id ^ ": native preprocess Skolem shadow formula_copy result is not the parent formula");
          store_shadow_formula id (formula_tm_of_literal result) parent_proof;
          store_shadow_clause id [result] parent_proof
      | CnfLiteral (id, parent_id, result) when has_shadow_formula parent_id ->
          let parent_formula, parent_proof = shadow_formula_parent parent_id in
          let parent_prop =
            native_core_normalize_bool_constants
              (native_core_formula_prop parent_formula)
          in
          let result_prop =
            native_core_normalize_bool_constants
              (native_core_clause_prop id result)
          in
          if parent_prop <> result_prop then
            error
              (id ^ ": native preprocess Skolem shadow cnf_literal result is not propositionally identical to the parent formula");
          store_shadow_clause id result parent_proof
      | CnfFormulaClause (id, parent_id, _index, _count, result)
          when has_shadow_formula parent_id ->
          let parent_formula, parent_proof = shadow_formula_parent parent_id in
          if Hashtbl.mem transitional_primitive_formula_steps parent_id then
            error
              (id ^ ": native preprocess Skolem shadow refuses transitional cnf_formula_clause parent")
          else
            let parent_step_variables =
              if parent_id = skolem_id then skolem_assumption_step_variables
              else native_core_step_variables cert parent_id
            in
            store_shadow_clause id result
              (native_core_cnf_formula_clause_proof
                 id variables
                 parent_step_variables
                 (native_core_step_variables cert id)
                 parent_formula result parent_proof)
      | SplitDependency (id, owner_id, _dependencies, result)
          when has_shadow_clause owner_id ->
          let owner_clause, owner_proof = shadow_clause_parent owner_id in
          if owner_clause <> result then
            error (id ^ ": native preprocess Skolem shadow split_dependency result does not match owner clause");
          store_shadow_clause id result owner_proof
      | Substitute (id, parent_id, subst, result) when has_shadow_clause parent_id ->
          let parent_clause, parent_proof = shadow_clause_parent parent_id in
          store_shadow_clause id result
            (native_core_substitute_in_result_context
               cert id variables parent_id parent_clause subst parent_proof result)
      | Resolve (id, left_id, right_id, left_index, right_index, result)
          when has_shadow_clause left_id || has_shadow_clause right_id ->
          let left_clause, left_proof = shadow_clause_parent left_id in
          let right_clause, right_proof = shadow_clause_parent right_id in
          store_shadow_clause id result
            (native_core_resolve_in_result_context
               cert id variables left_id left_clause left_proof
               right_id right_clause right_proof left_index right_index result)
      | Factor (id, parent_id, left_index, right_index, result)
          when has_shadow_clause parent_id ->
          let parent_clause, parent_proof = shadow_clause_parent parent_id in
          store_shadow_clause id result
            (native_core_factor_in_result_context
               cert id variables parent_id parent_clause parent_proof
               left_index right_index result)
      | EqualityResolution (id, parent_id, literal_index, result)
          when has_shadow_clause parent_id ->
          let parent_clause, parent_proof = shadow_clause_parent parent_id in
          store_shadow_clause id result
            (native_core_equality_resolution_in_result_context
               cert id variables parent_id parent_clause parent_proof literal_index result)
      | EqualitySymmetry (id, parent_id, literal_index, result)
          when has_shadow_clause parent_id ->
          let parent_clause, parent_proof = shadow_clause_parent parent_id in
          store_shadow_clause id result
            (native_core_equality_symmetry_in_result_context
               cert id variables parent_id parent_clause parent_proof literal_index result)
      | TruthConflict (id, parent_id, literal_index, result)
          when has_shadow_clause parent_id ->
          let parent_clause, parent_proof = shadow_clause_parent parent_id in
          store_shadow_clause id result
            (native_core_truth_conflict_in_result_context
               cert id variables parent_id parent_clause parent_proof literal_index result)
      | SubsumptionResolution
          (id, main_parent_id, side_parent_id, selected, side_pivot, side_subst, result)
          when has_shadow_clause main_parent_id || has_shadow_clause side_parent_id ->
          let main_clause, main_proof = shadow_clause_parent main_parent_id in
          let side_clause, side_proof = shadow_clause_parent side_parent_id in
          let side_clause = subst_clause side_subst side_clause in
          let side_pivot = subst_literal side_subst side_pivot in
          let side_proof =
            native_core_instantiate_step_proof cert side_parent_id side_subst side_proof
          in
          store_shadow_clause id result
            (native_core_subsumption_resolution_unit
               id main_clause main_proof side_clause side_proof selected side_pivot result)
      | Paramodulate
          (id, equality_parent_id, target_parent_id, equality_index, target_index,
           position, from_tm, to_tm, result)
          when has_shadow_clause equality_parent_id || has_shadow_clause target_parent_id ->
          let equality_clause, equality_proof = shadow_clause_parent equality_parent_id in
          let target_clause, target_proof = shadow_clause_parent target_parent_id in
          store_shadow_clause id result
            (native_core_paramodulate_unit_in_result_context
               cert id variables equality_parent_id equality_clause equality_proof
               target_parent_id target_clause target_proof
               equality_index target_index position from_tm to_tm result)
      | AvatarSplit (id, parent_ids, result)
          when List.exists has_shadow_clause parent_ids ->
          store_shadow_clause id result
            (native_core_avatar_split_proof
               cert id parent_ids result
               (combined_shadow_clause_table ())
               shadow_avatar_definition_table)
      | AvatarRefutation (id, parent_ids, sat_clauses, sat_proof, result)
          when List.exists has_shadow_clause parent_ids ->
          store_shadow_clause id result
            (native_core_avatar_refutation_proof
               id parent_ids sat_clauses sat_proof result
               (combined_shadow_clause_table ()))
      | Contradiction (id, parent_id) when has_shadow_clause parent_id ->
          let parent_clause, parent_proof = shadow_clause_parent parent_id in
          if parent_clause <> [] then
            error (id ^ ": native preprocess Skolem shadow contradiction parent is not empty");
          store_shadow_clause id [] parent_proof
      | _ -> ()
    in
    List.iter
      (fun step ->
         try replay_step step
         with Error _ as exn ->
           if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
             prerr_endline
               (skolem_id
                ^ ": native preprocess Skolem shadow replay stopped at "
                ^ step_id step
                ^ ": "
                ^ Printexc.to_string exn);
           raise exn)
      typed_steps;
    match !shadow_final_proof with
    | Some proof ->
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
          prerr_endline
            (skolem_id ^ ": native preprocess Skolem shadow replay reached empty clause");
          begin match native_core_pf_choice_witness_detail proof with
          | Some detail ->
              prerr_endline
                (skolem_id ^ ": native preprocess Skolem shadow first choice witness: " ^ detail)
          | None -> ()
          end;
          begin match native_core_pf_choice_known_detail proof with
          | Some detail ->
              prerr_endline
                (skolem_id ^ ": native preprocess Skolem shadow first choice theorem: " ^ detail)
          | None -> ()
          end
        end;
        Some (native_core_close_pf variables proof)
    | None ->
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
          prerr_endline
            (skolem_id ^ ": native preprocess Skolem shadow replay did not reach empty clause");
        None
  in
  seed_avatar_metadata_definitions ();
  List.iter
    (function
      | Input (id, source, clause)
          when native_core_source_is_set_reflexivity source_map source ->
          if step_is_used id then
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> native_core_set_reflexivity_clause_proof id clause
            in
            store_clause id clause proof
      | Input (id, _, clause) ->
          if step_is_used id then begin
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> Hyp (source_hyp_index id)
            in
            store_clause id clause proof
          end
      | FormulaInput (id, source, literal)
          when native_core_source_is_set_reflexivity source_map source ->
          if step_is_used id then begin
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> native_core_set_reflexivity_literal_proof id literal
            in
            store_clause id [literal] proof;
            store_formula id (native_core_literal_prop literal) proof
          end
      | FormulaInput (id, _, literal) ->
          if step_is_used id then begin
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> Hyp (source_hyp_index id)
            in
            store_clause id [literal] proof;
            store_formula id (native_core_literal_prop literal) proof
          end
      | FormulaTermInput (id, source, formula)
          when native_core_source_is_set_reflexivity source_map source ->
          if step_is_used id then begin
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None -> native_core_set_reflexivity_atom_proof id formula
            in
            store_formula id formula proof
          end
      | FormulaTermInput (id, _, formula) ->
          if step_is_used id then begin
            let target_prop =
              native_preprocess_step_formula_prop cert variables id formula
            in
            let proof =
              match native_core_source_proof shifted_source_proofs id with
              | Some proof -> proof
              | None ->
                  let source_proof = Hyp (source_hyp_index id) in
                  begin match source_input_proposition id with
                  | Some source_prop ->
                      lift_source_input_to_formula_step
                        source_prop target_prop source_proof
                  | None -> source_proof
                  end
            in
            store_formula id formula proof
          end
      | PredicateDefinition (id, symbol, result) ->
          check_predicate_definition id symbol result;
          let result_step_variables = native_core_step_variables cert id in
          store_formula id result
            (native_core_bind_result_step_variables
               variables result_step_variables
               (native_core_predicate_definition_proof id result))
      | PredicateDefinitionFold (id, source_id, definition_id, result) ->
          let source_formula, source_proof = lookup_formula source_id in
          let definition_formula, _ = lookup_formula definition_id in
          check_predicate_definition_fold (checked_formulas ()) id source_id definition_id result;
          let parent_step_variables = native_core_step_variables cert source_id in
          let result_step_variables = native_core_step_variables cert id in
          store_formula id result
            (native_core_predicate_definition_fold_step_proof
               id variables parent_step_variables result_step_variables
               definition_formula source_formula result source_proof)
      | PredicateDefinitionFoldChain (id, source_id, definition_ids, result) ->
          let source_formula, source_proof = lookup_formula source_id in
          let path =
            predicate_definition_fold_chain_path
              (checked_formulas ()) id source_id definition_ids result
          in
          let result_step_variables = native_core_step_variables cert id in
          let proof =
            let rec replay current_formula current_proof parent_step_variables = function
              | [] -> current_proof
              | (_definition_id, definition_formula, path_source, path_target) :: rest ->
                  if current_formula <> path_source then
                    error
                      (id ^ ": native preprocess proof-term predicate fold-chain replay lost its source formula");
                  let step_proof =
                    native_core_predicate_definition_fold_step_proof
                      id variables parent_step_variables result_step_variables
                      definition_formula path_source path_target current_proof
                  in
                  replay path_target step_proof result_step_variables rest
            in
            replay
              source_formula
              source_proof
              (native_core_step_variables cert source_id)
              path
          in
          store_formula id result proof
      | FormulaTermCopy (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          if parent_formula <> result then
            error (id ^ ": native preprocess proof-term formula_term_copy is not an identity copy");
          if Hashtbl.mem transitional_primitive_formula_steps parent_id then
            Hashtbl.replace transitional_primitive_formula_steps id true;
          store_formula id result parent_proof
      | RectifyFormula (id, parent_id, renamings, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          check_native_rectify_formula id parent_id renamings parent_formula result;
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          let parent_variable_map =
            kernel_v1_substitution_field cert id "rectify_variable_map"
          in
          if Hashtbl.mem transitional_primitive_formula_steps parent_id then
            Hashtbl.replace transitional_primitive_formula_steps id true;
          store_formula id result
            (native_core_formula_orientation_proof
               ~parent_variable_map
               id variables parent_step_variables result_step_variables
               parent_formula result parent_proof)
      | FoolBool (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          store_formula id (formula_tm_of_literal result)
            (native_core_fool_bool_proof id variables parent_formula parent_proof result)
      | FoolAtomLift (id, source, target, path) ->
          check_fool_atom_lift id source target path
      | FoolFormula (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          check_fool_formula
            [(parent_id, CheckedFormula parent_formula)]
            id parent_id result;
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          if Hashtbl.mem transitional_primitive_formula_steps parent_id then
            Hashtbl.replace transitional_primitive_formula_steps id true;
          store_formula id result
            (native_core_fool_formula_proof
               id symbol_table variables parent_step_variables result_step_variables
               parent_formula result parent_proof)
      | EnnfFormula (id, parent_id, source, pairs, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          check_ennf_formula
            [(parent_id, CheckedFormula parent_formula)]
            id parent_id source pairs result;
          let result_step_variables = native_core_step_variables cert id in
          if Hashtbl.mem transitional_primitive_formula_steps parent_id then
            Hashtbl.replace transitional_primitive_formula_steps id true;
          store_formula id result
            (native_core_ennf_formula_proof
               id variables result_step_variables parent_formula result parent_proof)
      | SkolemFormula (id, parent_id, source, introductions, subst, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          let check_parent_formula =
            match source with
            | Some source -> source
            | None -> parent_formula
          in
          check_skolem_formula
            [(parent_id, CheckedFormula check_parent_formula)]
            id parent_id source introductions subst result;
          let source_formula =
            match source with
            | Some source -> source
            | None -> parent_formula
          in
          let subst =
            native_core_reorder_skolem_substitution_by_source cert id subst
          in
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          let helper_formulas =
            native_core_skolem_parent_helper_formulas cert id
          in
          let skolem_proof_object =
            native_core_skolem_proof_object cert id
          in
          native_core_debug_skolem_proof_object id skolem_proof_object;
          let skolem_contract =
            Option.map
              (fun proof_object ->
                 proof_object.Vampire_kernel_syntax.skolem_proof_contract)
              skolem_proof_object
          in
          let introduced_names_from_step =
            introductions
            |> List.filter_map
                 (fun introduction ->
                    native_core_ident_opt introduction.skolem_intro_symbol)
          in
          let introduced_names_from_contract =
            native_core_skolem_contract_introduced_names skolem_contract
          in
          let introduced_names =
            List.sort_uniq
              String.compare
              (introduced_names_from_step @ introduced_names_from_contract)
          in
          let register_witness_replacement target_witness epsilon_witness =
            match native_core_flatten_value_application target_witness with
            | TmH raw_name, [] ->
                begin match native_core_ident_opt raw_name with
                | Some name when List.mem name introduced_names ->
                    let closed_witness =
                      native_core_close_tm variables epsilon_witness
                      |> tm_beta_eta_norm
                    in
                    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                      prerr_endline
                        (id
                         ^ ": native preprocess skolem registered witness definition "
                         ^ name
                         ^ " := "
                         ^ tm_to_str closed_witness);
                    if native_core_tm_scoped_under (List.length variables) closed_witness then begin
                      if not (Hashtbl.mem proof_delta name) then
                        Hashtbl.replace proof_delta name (0, closed_witness);
                      if not (Hashtbl.mem definition_delta name) then
                        Hashtbl.replace definition_delta name (0, closed_witness)
                    end else if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                      prerr_endline
                        (id
                         ^ ": native preprocess skolem kept context-dependent witness "
                         ^ name
                         ^ " out of arity-zero delta tables");
                    skolem_witness_replacements :=
                      (name, closed_witness)
                      :: List.remove_assoc name !skolem_witness_replacements;
                    skolem_witness_raw_replacements :=
                      (name, tm_beta_eta_norm epsilon_witness)
                      :: List.remove_assoc name !skolem_witness_raw_replacements
                | _ -> ()
                end
            | TmH raw_name, _ :: _ ->
                begin match native_core_ident_opt raw_name with
                | Some name when List.mem name introduced_names
                                 && Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" ->
                    prerr_endline
                      (id
                       ^ ": native preprocess skolem deferred dependent witness definition for "
                       ^ name)
                | _ -> ()
                end
            | _ -> ()
          in
          let build_skolem_formula_proof result_step_variables =
            let proof =
              try
                native_core_skolem_formula_proof
                  ~normalize_formula_for_match:normalize_generated_skolems
                  ~register_witness_replacement
                  id variables parent_step_variables result_step_variables
                  subst source_formula result parent_proof
              with (Error _ | Failure _) as exn ->
                if helper_formulas = [] then raise exn
                else
                  native_core_skolem_formula_proof
                    ~helper_formulas
                    ~normalize_formula_for_match:normalize_generated_skolems
                    ~register_witness_replacement
                    id variables parent_step_variables result_step_variables
                    subst source_formula result parent_proof
            in
            let inverse_witness_replacements =
              (!skolem_witness_raw_replacements @ !skolem_witness_replacements)
              |> List.filter
                   (fun (name, _) -> List.mem name introduced_names)
              |> List.map
                   (fun (name, witness) -> (witness, TmH name))
            in
            native_core_replace_terms_in_pf inverse_witness_replacements proof
          in
          let proof =
            build_skolem_formula_proof result_step_variables
          in
          store_formula id result proof;
          let result_checked_prop =
            native_preprocess_step_formula_prop cert variables id result
          in
          let base_result_assumption_step_variables =
            native_core_skolem_result_formula_step_variables
              cert id result_step_variables
          in
          let preserved_contract_step_variables =
            match skolem_contract with
            | None -> []
            | Some contract ->
                contract.Vampire_kernel_syntax.skolem_parent_instantiations
                |> List.filter_map
                     (fun instantiation ->
                        if instantiation.Vampire_kernel_syntax.skolem_parent_inst_role
                           <> "preserved_variable" then
                          None
                        else
                          List.find_opt
                            (fun (name, tp) ->
                               name
                               = instantiation.Vampire_kernel_syntax.skolem_parent_inst_variable
                               && tp
                                  = instantiation.Vampire_kernel_syntax.skolem_parent_inst_type)
                            result_step_variables)
          in
          let result_assumption_step_variables =
            result_step_variables
            |> List.filter
                 (fun variable ->
                    List.mem variable base_result_assumption_step_variables
                    || List.mem variable preserved_contract_step_variables)
          in
          let result_assumption_prop =
            native_preprocess_step_formula_prop_with_step_variables
              variables result_assumption_step_variables result
          in
          let result_assumption_proof =
            if result_assumption_step_variables = result_step_variables then
              proof
            else begin
              if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                prerr_endline
                  (id
                   ^ ": native preprocess Skolem CPS rebuilt result proof with "
                   ^ string_of_int (List.length result_assumption_step_variables)
                   ^ " result free variables instead of "
                   ^ string_of_int (List.length result_step_variables)
                   ^ " step variables");
              build_skolem_formula_proof result_assumption_step_variables
            end
          in
          skolem_cps_entries :=
            (id, source_formula, subst, result, parent_step_variables,
             result_step_variables,
             result_checked_prop, result_assumption_step_variables,
             result_assumption_prop, parent_proof,
             result_assumption_proof, skolem_proof_object)
            :: !skolem_cps_entries
      | FormulaCopy (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          if native_core_normalize_bool_constants (native_core_literal_prop result)
             <> native_core_normalize_bool_constants (native_core_formula_prop parent_formula) then
            error (id ^ ": native preprocess proof-term formula_copy result is not the parent formula");
          store_formula id (formula_tm_of_literal result) parent_proof;
          store_clause id [result] parent_proof
      | CnfLiteral (id, parent_id, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          let parent_prop =
            native_core_normalize_bool_constants
              (native_core_formula_prop parent_formula)
          in
          let result_prop =
            native_core_normalize_bool_constants
              (native_core_clause_prop id result)
          in
          if parent_prop <> result_prop then
            error
              (id ^ ": native preprocess proof-term cnf_literal result is not propositionally identical to the parent formula");
          store_clause id result parent_proof
      | CnfFormulaClause (id, parent_id, _index, _count, result) ->
          let parent_formula, parent_proof = lookup_formula parent_id in
          let parent_step_variables = native_core_step_variables cert parent_id in
          let result_step_variables = native_core_step_variables cert id in
          if Hashtbl.mem transitional_primitive_formula_steps parent_id then begin
            let parent_prop =
              native_preprocess_step_formula_prop cert variables parent_id parent_formula
            in
            let result_prop =
              native_core_step_clause_prop cert variables id result
            in
            let primitive = "vampire_cnf_formula_clause_" ^ id in
            let primitive_prop = Imp (parent_prop, result_prop) in
            install_transitional_known id primitive primitive_prop;
            Hashtbl.replace transitional_primitive_clause_steps id true;
            store_clause id result (PPfAp (Known primitive, parent_proof))
          end else
            store_clause id result
              (native_core_cnf_formula_clause_proof
                 id variables parent_step_variables result_step_variables
                 parent_formula result parent_proof)
      | DefinitionInput (id, result) ->
          let result_step_variables = native_core_step_variables cert id in
          store_clause id result
            (native_core_definition_input_proof
               proof_delta id variables result_step_variables result)
      | DefinitionRewriteChain (id, parent_id, rewrites, result) ->
          let parent_clause, parent_proof = lookup_clause parent_id in
          store_clause id result
            (native_core_definition_rewrite_chain_proof
               cert id variables parent_id parent_clause parent_proof
               rewrites result lookup_clause)
      | AvatarDefinition (id, split_var, split_positive, result) ->
          begin match native_core_avatar_definition_clause cert id split_var split_positive result with
          | Some (split_name, component_literals) ->
              let proof =
                native_core_avatar_definition_proof
                  cert variables id split_var split_positive result
              in
              store_avatar_definition
                id
                split_name
                component_literals
                proof
          | None ->
              error
                (id ^ ": native preprocess proof-term avatar_definition needs a supported split definition")
          end
      | AvatarComponent (id, result) ->
          check_avatar_component_strict id result;
          store_clause id result
            (native_core_avatar_component_proof
               cert variables id result avatar_definition_table)
      | SplitDependency (id, owner_id, _dependencies, result) ->
          let owner_clause, owner_proof = lookup_clause owner_id in
          if owner_clause <> result then
            error (id ^ ": native preprocess proof-term split_dependency result does not match owner clause");
          store_clause id result owner_proof
      | AvatarSplit (id, parent_ids, result) ->
          if parent_ids = [] then
            error (id ^ ": native preprocess proof-term avatar_split requires at least one parent");
          store_clause id result
            (native_core_avatar_split_proof
               cert id parent_ids result clause_table avatar_definition_table)
      | AvatarRefutation (id, parent_ids, sat_clauses, sat_proof, result) ->
          store_clause id result
            (native_core_avatar_refutation_proof
               id parent_ids sat_clauses sat_proof result clause_table)
      | FoolExhaustiveness (id, result) ->
          store_clause id result
            (native_core_fool_exhaustiveness_proof cert id result)
      | InequalityNameIntro (id, result) ->
          store_clause id result
            (native_core_inequality_name_intro_proof cert symbol_table id variables result)
      | InequalitySplit (id, source_id, splits, result) ->
          List.iter
            (fun split -> ignore (lookup_clause split.split_name_parent))
            splits;
          let source_clause, source_proof = lookup_clause source_id in
          store_clause id result
            (native_core_inequality_split_proof
               cert id variables source_id source_clause source_proof splits result)
      | Substitute (id, parent_id, [], result) ->
          let parent_clause, parent_proof = lookup_clause parent_id in
          store_clause id result
            (substitute_proof id parent_id parent_clause [] parent_proof result)
      | Substitute (id, parent_id, subst, result) ->
          let parent_clause, parent_proof = lookup_clause parent_id in
          store_clause id result
            (substitute_proof id parent_id parent_clause subst parent_proof result)
      | Resolve (id, left_id, right_id, left_index, right_index, result) ->
          let left_clause, left_proof = lookup_clause left_id in
          let right_clause, right_proof = lookup_clause right_id in
          if Hashtbl.mem transitional_primitive_clause_steps left_id
             || Hashtbl.mem transitional_primitive_clause_steps right_id then begin
            native_core_validate_resolve_step
              id left_clause right_clause left_index right_index result;
            let left_prop =
              native_core_step_clause_prop cert variables left_id left_clause
            in
            let right_prop =
              native_core_step_clause_prop cert variables right_id right_clause
            in
            let result_prop =
              native_core_step_clause_prop cert variables id result
            in
            let primitive = "vampire_resolve_" ^ id in
            let primitive_prop = Imp (left_prop, Imp (right_prop, result_prop)) in
            install_transitional_known id primitive primitive_prop;
            Hashtbl.replace transitional_primitive_clause_steps id true;
            store_clause id result
              (PPfAp (PPfAp (Known primitive, left_proof), right_proof))
          end else begin
            let proof =
              native_core_resolve_in_result_context
                cert id variables left_id left_clause left_proof right_id right_clause right_proof
                left_index right_index result
            in
            store_clause id result proof
          end
      | Factor (id, parent_id, left_index, right_index, result) ->
          let parent_clause, parent_proof = lookup_clause parent_id in
          if Hashtbl.mem transitional_primitive_clause_steps parent_id then begin
            native_core_validate_factor_step
              id parent_clause left_index right_index result;
            let parent_prop =
              native_core_step_clause_prop cert variables parent_id parent_clause
            in
            let result_prop =
              native_core_step_clause_prop cert variables id result
            in
            let primitive = "vampire_factor_" ^ id in
            let primitive_prop = Imp (parent_prop, result_prop) in
            install_transitional_known id primitive primitive_prop;
            Hashtbl.replace transitional_primitive_clause_steps id true;
            store_clause id result (PPfAp (Known primitive, parent_proof))
          end else
            store_clause id result
              (native_core_factor_in_result_context
                 cert id variables parent_id parent_clause parent_proof
                 left_index right_index result)
      | EqualityResolution (id, parent_id, literal_index, result) ->
          let parent_clause, parent_proof = lookup_clause parent_id in
          if Hashtbl.mem transitional_primitive_clause_steps parent_id then begin
            let expected = remove_at literal_index parent_clause (id ^ " equality-resolution literal") in
            if not (same_clause_multiset expected result) then
              error (id ^ ": native preprocess proof-term equality_resolution transitional primitive result mismatch");
            let parent_prop =
              native_core_step_clause_prop cert variables parent_id parent_clause
            in
            let result_prop =
              native_core_step_clause_prop cert variables id result
            in
            let primitive = "vampire_equality_resolution_" ^ id in
            let primitive_prop = Imp (parent_prop, result_prop) in
            install_transitional_known id primitive primitive_prop;
            Hashtbl.replace transitional_primitive_clause_steps id true;
            store_clause id result (PPfAp (Known primitive, parent_proof))
          end else
            store_clause id result
              (native_core_equality_resolution_in_result_context
                 cert id variables parent_id parent_clause parent_proof literal_index result)
      | EqualitySymmetry (id, parent_id, literal_index, result) ->
          let parent_clause, parent_proof = lookup_clause parent_id in
          if Hashtbl.mem transitional_primitive_clause_steps parent_id then begin
            native_core_validate_equality_symmetry_step
              id parent_clause literal_index result;
            let parent_prop =
              native_core_step_clause_prop cert variables parent_id parent_clause
            in
            let result_prop =
              native_core_step_clause_prop cert variables id result
            in
            let primitive = "vampire_equality_symmetry_" ^ id in
            let primitive_prop = Imp (parent_prop, result_prop) in
            install_transitional_known id primitive primitive_prop;
            Hashtbl.replace transitional_primitive_clause_steps id true;
            store_clause id result (PPfAp (Known primitive, parent_proof))
          end else
            store_clause id result
              (native_core_equality_symmetry_in_result_context
                 cert id variables parent_id parent_clause parent_proof literal_index result)
	      | TruthConflict (id, parent_id, literal_index, result) ->
	          let parent_clause, parent_proof = lookup_clause parent_id in
	          store_clause id result
	            (native_core_truth_conflict_in_result_context
               cert id variables parent_id parent_clause parent_proof literal_index result)
	      | SubsumptionResolution (id, main_parent_id, side_parent_id, selected, side_pivot, side_subst, result) ->
	          let main_clause, main_proof = lookup_clause main_parent_id in
	          let side_clause, side_proof = lookup_clause side_parent_id in
          let side_clause = subst_clause side_subst side_clause in
          let side_pivot = subst_literal side_subst side_pivot in
          let side_proof =
            native_core_instantiate_step_proof cert side_parent_id side_subst side_proof
          in
          store_clause id result
            (native_core_subsumption_resolution_unit
               id main_clause main_proof side_clause side_proof selected side_pivot result)
      | Paramodulate (id, equality_parent_id, target_parent_id, equality_index, target_index, position, from_tm, to_tm, result) ->
          let equality_clause, equality_proof = lookup_clause equality_parent_id in
          let target_clause, target_proof = lookup_clause target_parent_id in
          if substitute_step_uses_closed_parent_primitive target_parent_id
             || Hashtbl.mem transitional_primitive_clause_steps equality_parent_id
             || Hashtbl.mem transitional_primitive_clause_steps target_parent_id then begin
            let equality_prop =
              native_core_step_clause_prop cert variables equality_parent_id equality_clause
            in
            let target_prop =
              native_core_step_clause_prop cert variables target_parent_id target_clause
            in
            let result_prop =
              native_core_step_clause_prop cert variables id result
            in
            let primitive = "vampire_paramodulate_" ^ id in
            let primitive_prop = Imp (equality_prop, Imp (target_prop, result_prop)) in
            install_transitional_known id primitive primitive_prop;
            Hashtbl.replace transitional_primitive_clause_steps id true;
            store_clause id result
              (PPfAp (PPfAp (Known primitive, equality_proof), target_proof))
          end else
            store_clause id result
              (native_core_paramodulate_unit_in_result_context
                 cert id variables equality_parent_id equality_clause equality_proof
                 target_parent_id target_clause target_proof
                 equality_index target_index position from_tm to_tm result)
      | Contradiction (id, parent_id) ->
          let parent_clause, parent_proof = lookup_clause parent_id in
          if parent_clause <> [] then
            error (id ^ ": native preprocess proof-term contradiction parent is not empty");
          store_clause id [] parent_proof
      | UnitResultingResolution (id, _, _, _) ->
          error
            (id
             ^ ": native preprocess proof-term checker requires unit_resulting_resolution to be lowered to primitive certificate steps")
      | step ->
          error
            (step_id step ^ ": native preprocess proof-term checker has no proof-term rule for "
             ^ step_rule_name step))
    typed_steps;
  let proof =
    match !final_proof with
    | Some proof -> proof
    | None -> error "native preprocess proof-term checker found no empty-clause proof"
  in
  let proof =
    List.fold_left
      (fun current
           (id, source_formula, subst, result, parent_step_variables,
            result_step_variables, result_checked_prop,
            result_assumption_step_variables, result_assumption_prop,
            parent_proof, result_proof, skolem_proof_object) ->
         try
           let introduced_witness_symbols =
             subst
             |> List.map
                  (function
                    | _, TmH symbol -> symbol
                    | _ -> "")
             |> List.filter (fun symbol -> symbol <> "")
           in
           let split_replacements =
             avatar_definition_table
             |> Hashtbl.to_seq_values
             |> List.of_seq
             |> List.map
                  (fun (split_name, _component_literals, component_prop, _definition_proof) ->
                     (split_name,
                      component_prop
                      |> native_core_normalize_bool_constants
                      |> tm_beta_eta_norm))
             |> List.sort_uniq compare
           in
           if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1"
              && split_replacements <> [] then
             prerr_endline
               (id
                ^ ": native preprocess Skolem CPS inlining AVATAR splits "
                ^ String.concat ", " (List.map fst split_replacements));
           let shadow_result_to_target =
             if Sys.getenv_opt "MEGALODON_CERT_DISABLE_SKOLEM_SHADOW" = Some "1" then begin
               if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
                 prerr_endline
                   (id ^ ": native preprocess Skolem CPS shadow replay disabled by environment");
               None
             end else
               try
                 shadow_skolem_final_refutation
                   ~skolem_assumption_prop:result_assumption_prop
                   ~skolem_assumption_step_variables:result_assumption_step_variables
                   id result_checked_prop result
               with (Error _ | Failure _) -> None
           in
           begin match shadow_result_to_target with
           | Some _ when Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" ->
               prerr_endline
                 (id ^ ": native preprocess Skolem CPS using shadow replay continuation")
           | _ -> ()
           end;
           let candidate =
	             native_core_skolem_refutation_cps_proof
	               ~abstract_result_proof:abstract_skolem_result_by_prop
	               ?result_to_target_body:shadow_result_to_target
               ~result_assumption_prop
               ~result_assumption_step_variables
               ?skolem_proof_object
               ~split_replacements
               id variables parent_step_variables result_step_variables
               source_formula subst result result_checked_prop parent_proof
               result_proof current native_core_false
           in
           let fail_fast_skolem_cps () =
             Sys.getenv_opt "MEGALODON_CERT_FAIL_FAST_SKOLEM_CPS" = Some "1"
           in
           if native_core_pf_contains_choice_witness candidate then begin
             if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
               prerr_endline
                 (id ^ ": native preprocess Skolem CPS candidate still contains certificate-local choice witnesses; keeping original refutation");
               begin match native_core_pf_choice_witness_detail candidate with
               | Some detail ->
                   prerr_endline
                     (id ^ ": native preprocess Skolem CPS first choice witness: " ^ detail)
               | None -> ()
               end;
               begin match native_core_pf_choice_known_detail candidate with
               | Some detail ->
                   prerr_endline
                     (id ^ ": native preprocess Skolem CPS first choice theorem: " ^ detail)
               | None -> ()
               end
             end;
             if fail_fast_skolem_cps () then
               error
                 (id
                  ^ ": native preprocess Skolem CPS candidate still contains certificate-local choice witnesses");
             current
           end else if native_core_pf_contains_term_symbol introduced_witness_symbols candidate then begin
             if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then begin
               prerr_endline
                 (id ^ ": native preprocess Skolem CPS candidate still contains introduced Skolem symbols; keeping original refutation");
               begin match native_core_pf_term_symbol_detail introduced_witness_symbols candidate with
               | Some detail ->
                   prerr_endline
                     (id ^ ": native preprocess Skolem CPS first introduced symbol: " ^ detail)
               | None -> ()
               end
             end;
             if fail_fast_skolem_cps () then
               error
                 (id
                  ^ ": native preprocess Skolem CPS candidate still contains introduced Skolem symbols");
             current
           end else if final_refutation_proof_checks candidate then begin
             if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
               prerr_endline
                 (id ^ ": native preprocess Skolem CPS discharged certificate-local witnesses");
             candidate
           end else begin
             if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
               prerr_endline
                 (id
                  ^ ": native preprocess Skolem CPS candidate did not check"
                  ^ (if fail_fast_skolem_cps () then "; failing fast" else "; keeping original refutation"));
             if fail_fast_skolem_cps () then
               error
                 (id ^ ": native preprocess Skolem CPS candidate did not check");
             current
           end
         with (Error _ | Failure _) as exn ->
           if Sys.getenv_opt "MEGALODON_CERT_FAIL_FAST_SKOLEM_CPS" = Some "1" then
             raise exn;
           if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
             prerr_endline
               (id ^ ": native preprocess Skolem CPS skipped: " ^ Printexc.to_string exn);
           current)
      proof
      !skolem_cps_entries
  in
  let proof =
    let split_replacements =
      avatar_definition_table
      |> Hashtbl.to_seq_values
      |> List.of_seq
      |> List.map
           (fun (split_name, _component_literals, component_prop, _definition_proof) ->
              (split_name,
               component_prop
               |> native_core_normalize_bool_constants
               |> tm_beta_eta_norm))
      |> List.sort_uniq compare
    in
    let split_names = List.map fst split_replacements in
    if split_replacements = []
       || not (native_core_pf_contains_term_symbol split_names proof) then
      proof
    else
      let candidate =
        native_core_replace_witness_symbols_in_pf split_replacements proof
      in
      if final_refutation_proof_checks candidate then begin
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
          prerr_endline
            ("native preprocess refutation discharged AVATAR split symbols "
             ^ String.concat ", " split_names);
        candidate
      end else begin
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
          prerr_endline
            "native preprocess refutation AVATAR split replacement candidate did not check";
        proof
      end
  in
  let proof =
    let replacements =
      !skolem_witness_replacements
      |> List.sort_uniq compare
    in
    let witness_names = List.map fst replacements in
    if replacements = []
       || not (native_core_pf_contains_term_symbol witness_names proof) then
      proof
    else
      let candidate =
        native_core_replace_witness_symbols_in_pf replacements proof
      in
      if final_refutation_proof_checks candidate then begin
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
          prerr_endline
            ("native preprocess refutation discharged Skolem witness symbols "
             ^ String.concat ", " witness_names);
        candidate
      end else begin
        if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
          prerr_endline
            "native preprocess refutation Skolem witness replacement candidate did not check";
        proof
      end
  in
  let body_prop =
    List.fold_right
      (fun (_, assumption, _) target -> Imp (assumption, target))
      !source_inputs
      native_core_false
  in
  let body_proof =
    List.fold_right
      (fun (_, assumption, _) proof -> PLam (assumption, proof))
      !source_inputs
      proof
  in
  let closed_prop = native_core_close_tm variables body_prop in
  let closed_proof = native_core_close_pf variables body_proof in
  {
    core_native_proposition =
      List.fold_right (fun (_, tp) prop -> All (tp, prop)) variables closed_prop;
    core_native_proof =
      List.fold_right (fun (_, tp) proof -> TLam (tp, proof)) variables closed_proof;
    core_native_delta_table = definition_delta;
    core_native_symbol_table = symbol_table;
    core_native_steps = List.length cert.steps;
    core_native_source_bindings = !source_bindings;
    core_native_source_assumption_bindings =
      List.map (fun (_, _, binding) -> binding) !source_inputs;
    core_native_source_assumptions = source_count;
  }

let emit_error msg =
  let msg =
    if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
      msg ^ "\n" ^ Printexc.raw_backtrace_to_string (Printexc.get_callstack 20)
    else msg
  in
  error ("simple Megalodon emitter: " ^ msg)

let debug_emit_error context msg =
  if Sys.getenv_opt "MEGALODON_CERT_DEBUG" = Some "1" then
    prerr_endline ("simple Megalodon emitter debug: " ^ context ^ ": " ^ msg)

let closed_approved_axioms =
  [
    ("dneg", "forall P:prop, ~~P -> P");
    ("Eps_i_ax", "forall P:set->prop, forall x:set, P x -> P (Eps_i P)");
    ("vampire_exists_prop_choice",
     "forall P:prop->prop, vampire_exists_prop P -> P (Eps_prop P)");
    ("vampire_exists_set_prop_choice",
     "forall P:(set->prop)->prop, vampire_exists_set_prop P -> P (Eps_set_prop P)");
    ("vampire_exists_set_set_choice",
     "forall P:(set->set)->prop, vampire_exists_set_set P -> P (Eps_set_set P)");
    ("vampire_exists_set_set_prop_choice",
     "forall P:(set->set->prop)->prop, vampire_exists_set_set_prop P -> P (Eps_set_set_prop P)");
    ("prop_ext", "forall p q:prop, iff p q -> p = q");
  ]

let closed_axiom_line line =
  if not (string_starts_with "Axiom " line) then None
  else
    let rest = String.sub line 6 (String.length line - 6) in
    match string_find_substring " : " rest with
    | None -> emit_error ("closed axiom policy cannot parse axiom line: " ^ line)
    | Some colon ->
        let name = String.sub rest 0 colon |> String.trim in
        let prop =
          String.sub rest (colon + 3) (String.length rest - colon - 3)
          |> String.trim
        in
        let prop =
          if String.length prop > 0 && prop.[String.length prop - 1] = '.' then
            String.sub prop 0 (String.length prop - 1) |> String.trim
          else prop
        in
        Some (name, prop)

let validate_closed_axiom_policy lines =
  List.iteri
    (fun index line ->
       match closed_axiom_line line with
       | None -> ()
       | Some (name, prop) ->
           begin match List.assoc_opt name closed_approved_axioms with
           | Some expected when prop = expected -> ()
           | Some expected ->
               emit_error
                 (Printf.sprintf
                    "closed axiom policy rejects changed axiom %s at generated line %d; expected %s but got %s"
                    name (index + 1) expected prop)
           | None ->
               emit_error
                 (Printf.sprintf
                    "closed axiom policy rejects unapproved axiom %s at generated line %d"
                    name (index + 1))
           end)
    lines

let simple_normalize_vlam_text ?(lambda_binder_sort = fun _ -> None) text =
  let is_name_char = function
    | 'A'..'Z' | 'a'..'z' | '0'..'9' | '_' | '\'' -> true
    | _ -> false
  in
  let is_token_at source token i =
    let len = String.length source in
    let token_len = String.length token in
    i + token_len <= len
    && String.sub source i token_len = token
    && (i = 0 || not (is_name_char source.[i - 1]))
    && (i + token_len = len || not (is_name_char source.[i + token_len]))
  in
  let rec skip_spaces source i =
    if i < String.length source && is_space source.[i] then skip_spaces source (i + 1) else i
  in
  let rec parse_paren source depth i =
    let len = String.length source in
    if i >= len then emit_error "unterminated parenthesized vLAM argument";
    match source.[i] with
    | '(' -> parse_paren source (depth + 1) (i + 1)
    | ')' when depth = 1 -> i + 1
    | ')' -> parse_paren source (depth - 1) (i + 1)
    | _ -> parse_paren source depth (i + 1)
  in
  let parse_arg source i =
    let len = String.length source in
    let start = skip_spaces source i in
    if start >= len then emit_error "vLAM has no argument";
    if source.[start] = '(' then
      let stop = parse_paren source 1 (start + 1) in
      (String.sub source (start + 1) (stop - start - 2), stop)
    else
      let rec atom_end j =
        if j >= len || is_space source.[j] || source.[j] = ')' then j else atom_end (j + 1)
      in
      let stop = atom_end start in
      (String.sub source start (stop - start), stop)
  in
  let fresh_index = ref 0 in
  let fresh_binder () =
    let name = "vdb" ^ string_of_int !fresh_index in
    incr fresh_index;
    name
  in
  let rec parse_db_token source i =
    let len = String.length source in
    if i + 2 <= len
       && String.sub source i 2 = "db"
       && (i = 0 || not (is_name_char source.[i - 1])) then begin
      let rec digits j =
        if j < len then
          match source.[j] with
          | '0'..'9' -> digits (j + 1)
          | _ -> j
        else j
      in
      let stop = digits (i + 2) in
      if stop > i + 2
         && (stop = len || not (is_name_char source.[stop])) then
        Some
          (int_of_string (String.sub source (i + 2) (stop - i - 2)), stop)
      else None
    end else None
  in
  let rec normalize env source =
    let source_len = String.length source in
    let rec loop i =
      if i >= source_len then ""
      else if is_token_at source "vLAM" i then
        let body, stop = parse_arg source (i + 4) in
        render_lambda env body ^ loop stop
      else begin
        match parse_db_token source i with
        | Some (index, stop) ->
            let replacement =
              match List.nth_opt env index with
              | Some (name, _) -> name
              | None -> "db" ^ string_of_int index
            in
            replacement ^ loop stop
        | None -> String.make 1 source.[i] ^ loop (i + 1)
      end
    in
    loop 0
  and binder_sort body =
    let vlam_text_candidates body =
      let body = String.trim body in
      ["vLAM " ^ body; "vLAM (" ^ body ^ ")"]
    in
    match vlam_text_candidates body |> List.find_map lambda_binder_sort with
    | Some sort -> sort
    | None -> "set"
  and render_lambda env body =
    let sort = binder_sort body in
    let name = fresh_binder () in
    let normalized_body = normalize ((name, sort) :: env) (String.trim body) in
    "(fun " ^ name ^ ":" ^ sort ^ " => " ^ normalized_body ^ ")"
  in
  normalize [] text

let metadata_step_proposition cert id =
  let parse_lambda_sorts fields =
    fields
    |> List.fold_left
         (fun acc field ->
            match String.index_opt field '=' with
            | None -> acc
            | Some eq ->
                let key = String.sub field 0 eq in
                let value = String.sub field (eq + 1) (String.length field - eq - 1) in
                (key, value) :: acc)
         []
  in
  let current_lambda_sorts =
    cert.metadata.step_extras
    |> List.filter (fun (step_id, _, _) -> step_id = id)
    |> List.concat_map (fun (_, _, fields) -> fields)
    |> parse_lambda_sorts
  in
  let global_lambda_sorts =
    cert.metadata.step_extras
    |> List.concat_map (fun (_, _, fields) -> fields)
    |> parse_lambda_sorts
  in
  let lambda_binder_sort_from fields text =
    let is_step_lambda_key key =
      let prefix = "step_lambda_" in
      let prefix_len = String.length prefix in
      let len = String.length key in
      len > prefix_len
      && String.sub key 0 prefix_len = prefix
      &&
      let rec digits i =
        i >= len || (match key.[i] with '0'..'9' -> digits (i + 1) | _ -> false)
      in
      digits prefix_len
    in
    let matching_prefix =
      fields
      |> List.find_map
           (fun (key, value) ->
              if value = text && is_step_lambda_key key then
                Some key
              else None)
    in
    match matching_prefix with
    | None -> None
    | Some key -> List.assoc_opt (key ^ "_binder_sort") fields
  in
  let lambda_binder_sort text =
    match lambda_binder_sort_from current_lambda_sorts text with
    | Some sort -> Some sort
    | None -> lambda_binder_sort_from global_lambda_sorts text
  in
  Option.map
    (simple_normalize_vlam_text ~lambda_binder_sort)
    (List.assoc_opt id cert.metadata.step_propositions)

let metadata_step_variable_sorts cert id =
  match List.assoc_opt id cert.metadata.step_variable_sorts with
  | Some sorts -> sorts
  | None -> []

let variable_sort_pair sort =
  match String.index_opt sort ':' with
  | Some colon when colon > 0 ->
      Some
        (String.sub sort 0 colon,
         String.sub sort (colon + 1) (String.length sort - colon - 1))
  | _ -> None

let metadata_step_variable_sort_pairs cert id =
  metadata_step_variable_sorts cert id
  |> List.filter_map variable_sort_pair

let metadata_step_extra_fields cert id kind =
  cert.metadata.step_extras
  |> List.filter_map
       (fun (step_id, step_kind, fields) ->
          if step_id = id && step_kind = kind then Some fields else None)

let metadata_step_extra_field cert id kind key =
  let prefix = key ^ "=" in
  let prefix_len = String.length prefix in
  metadata_step_extra_fields cert id kind
  |> List.find_map
       (fun fields ->
          List.find_map
            (fun field ->
               if String.length field >= prefix_len
                  && String.sub field 0 prefix_len = prefix then
                 Some (String.sub field prefix_len (String.length field - prefix_len))
	               else None)
	            fields)

let metadata_avatar_split_parent_var_bindings cert id =
  let field key = metadata_step_extra_field cert id "avatar_split" key in
  match field "parent_var_binding_count" with
  | None -> []
  | Some count_text ->
      let count =
        try int_of_string count_text with Failure _ -> 0
      in
      let rec loop index acc =
        if index >= count then List.rev acc
        else
          let prefix = "parent_var_binding_" ^ string_of_int index in
          let acc =
            match field (prefix ^ "_parent_var"), field (prefix ^ "_split_var") with
            | Some parent_var, Some split_var ->
                (parent_var, "split_" ^ split_var) :: acc
            | _ -> acc
          in
          loop (index + 1) acc
      in
      loop 0 []

let metadata_avatar_split_literal_class_bindings cert id =
  let field key = metadata_step_extra_field cert id "avatar_split" key in
  let int_field key =
    match field key with
    | Some text -> (try Some (int_of_string text) with Failure _ -> None)
    | None -> None
  in
  let component_levels =
    match int_field "component_parent_count" with
    | None -> []
    | Some count ->
        let rec loop index acc =
          if index > count then acc
          else
            let prefix = "component_parent_" ^ string_of_int index in
            let acc =
              match field (prefix ^ "_split_level"), field (prefix ^ "_split_var") with
              | Some level, Some split_var -> (level, "split_" ^ split_var) :: acc
              | _ -> acc
            in
            loop (index + 1) acc
        in
        loop 1 []
  in
  match int_field "literal_class_count" with
  | None -> []
  | Some class_count ->
      let rec classes index acc =
        if index >= class_count then List.rev acc
        else
          let prefix = "literal_class_" ^ string_of_int index in
          let acc =
            match field (prefix ^ "_matched_split_level"), int_field (prefix ^ "_literal_count") with
            | Some level, Some literal_count ->
                begin match List.assoc_opt level component_levels with
                | None -> acc
                | Some split_name ->
                    let rec literals literal_index acc =
                      if literal_index >= literal_count then acc
                      else
                        let key = prefix ^ "_literal_" ^ string_of_int literal_index in
                        let acc =
                          match field key with
                          | Some literal_text -> (literal_text, split_name) :: acc
                          | None -> acc
                        in
                        literals (literal_index + 1) acc
                    in
                    literals 0 acc
                end
            | _ -> acc
          in
          classes (index + 1) acc
      in
      classes 0 []

let metadata_avatar_definition_bodies cert =
  let field fields key =
    let prefix = key ^ "=" in
    let prefix_len = String.length prefix in
    fields
    |> List.find_map
         (fun field ->
            if String.length field >= prefix_len
               && String.sub field 0 prefix_len = prefix then
              Some (String.sub field prefix_len (String.length field - prefix_len))
            else None)
  in
  let strip_avatar_component_body split_name clause =
    let prefix = "vampire_or " in
    let suffix = " ((" ^ split_name ^ ") -> vampire_false)" in
    let prefix_len = String.length prefix in
    let suffix_len = String.length suffix in
    let len = String.length clause in
    if len >= prefix_len + suffix_len
       && String.sub clause 0 prefix_len = prefix
       && String.sub clause (len - suffix_len) suffix_len = suffix then
      Some (String.sub clause prefix_len (len - prefix_len - suffix_len))
    else None
  in
  cert.metadata.step_extras
  |> List.filter_map
       (fun (_, kind, fields) ->
          if kind <> "avatar_definition" then None
          else
            match field fields "component_split_var", field fields "component_clause" with
            | Some split_var, Some clause ->
                let split_name = "split_" ^ split_var in
                begin match strip_avatar_component_body split_name clause with
                | Some body -> Some (split_name, body)
                | None -> None
                end
            | _ -> None)

let metadata_definition_lhs_sort_pairs cert id =
  let is_db_name name =
    let len = String.length name in
    let rec digits i =
      i >= len || (match name.[i] with '0'..'9' -> digits (i + 1) | _ -> false)
    in
    len > 2 && String.sub name 0 2 = "db" && digits 2
  in
  let field_value fields key =
    let prefix = key ^ "=" in
    let prefix_len = String.length prefix in
    fields
    |> List.find_map
         (fun field ->
            if String.length field >= prefix_len
               && String.sub field 0 prefix_len = prefix then
              Some (String.sub field prefix_len (String.length field - prefix_len))
            else None)
  in
  metadata_step_extra_fields cert id "function_definition"
  |> List.filter_map
       (fun fields ->
          match field_value fields "lhs", field_value fields "equality_sort" with
          | Some lhs, Some sort when is_db_name lhs -> Some (lhs, sort)
          | _ -> None)

let metadata_higher_order_definition_db_names cert =
  cert.metadata.step_extras
  |> List.concat_map
       (fun (id, kind, _) ->
          if kind <> "function_definition" then []
          else
            metadata_definition_lhs_sort_pairs cert id
            |> List.filter_map
                 (fun (name, sort) ->
                    if sort <> "set" && sort <> "prop" then Some name else None))
  |> List.sort_uniq String.compare

let metadata_lambda_sort_env cert =
  let parse_fields fields =
    let kvs =
      fields
      |> List.filter_map
           (fun field ->
              match String.index_opt field '=' with
              | None -> None
              | Some eq ->
                  Some
                    (String.sub field 0 eq,
                     String.sub field (eq + 1) (String.length field - eq - 1)))
    in
    let is_lambda_key key =
      let prefixes = ["step_lambda_"; "target_lambda_"] in
      List.exists
        (fun prefix ->
           let prefix_len = String.length prefix in
           let len = String.length key in
           len > prefix_len
           && String.sub key 0 prefix_len = prefix
           &&
           let rec digits i =
             i >= len || (match key.[i] with '0'..'9' -> digits (i + 1) | _ -> false)
           in
           digits prefix_len)
        prefixes
    in
    kvs
    |> List.filter_map
         (fun (key, term) ->
            if is_lambda_key key then
              match List.assoc_opt (key ^ "_sort") kvs with
              | Some sort -> Some (term, sort)
              | None -> None
            else None)
  in
  cert.metadata.step_extras
  |> List.concat_map (fun (_, _, fields) -> parse_fields fields)
  |> List.sort_uniq compare

let simple_unsupported_step cert step =
  let id = step_id step in
  let base = "unsupported rule " ^ step_rule_name step ^ " at step " ^ id in
  let with_prop =
    match metadata_step_proposition cert id with
    | Some proposition -> base ^ "; proposition: " ^ proposition
    | None -> base
  in
  match metadata_step_variable_sorts cert id with
  | [] -> with_prop
  | sorts -> with_prop ^ "; variable_sorts: " ^ String.concat ", " sorts

let simple_formula_prop cert id =
  match metadata_step_proposition cert id with
  | Some proposition -> proposition
  | None ->
      emit_error
        ("formula step " ^ id ^ " has no step_proposition metadata; rebuild Vampire proof output with native metadata")

let simple_parent_prop cert parent_id =
  match metadata_step_proposition cert parent_id with
  | Some proposition -> proposition
  | None -> emit_error ("parent step " ^ parent_id ^ " has no step_proposition metadata")

let simple_declared_name line =
  let variable_prefix = "Variable " in
  let prefix_len = String.length variable_prefix in
  if String.length line > prefix_len
     && String.sub line 0 prefix_len = variable_prefix then
    match String.index_opt line ':' with
    | Some colon when colon > prefix_len ->
        Some (String.sub line prefix_len (colon - prefix_len))
    | _ -> None
  else None

let metadata_declared_names cert =
  cert.metadata.symbol_declarations
  |> List.filter_map simple_declared_name

let metadata_variable_sorts cert =
  cert.metadata.step_variable_sorts
  |> List.concat_map snd
  |> List.filter_map variable_sort_pair
  |> List.sort_uniq compare

let megalodon_ident s =
  let n = String.length s in
  if n = 0 then emit_error "empty identifier";
  let is_alpha c =
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c = '_'
  in
  let is_ident c = is_alpha c || ('0' <= c && c <= '9') || c = '\'' in
  if not (is_alpha s.[0]) then emit_error ("unsupported identifier " ^ s);
  String.iter
    (fun c ->
       if not (is_ident c) then emit_error ("unsupported identifier " ^ s))
    s;
  s

let megalodon_safe_ident prefix s =
  let is_alpha c =
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c = '_'
  in
  let is_ident c = is_alpha c || ('0' <= c && c <= '9') || c = '\'' in
  let buf = Buffer.create (String.length prefix + String.length s + 8) in
  Buffer.add_string buf prefix;
  String.iter
    (fun c ->
       if is_ident c then Buffer.add_char buf c
       else Buffer.add_string buf (Printf.sprintf "_x%02X" (Char.code c)))
    s;
  let result = Buffer.contents buf in
  if result = "" then "x"
  else if is_alpha result.[0] then result
  else "x_" ^ result

let is_hex_char = function
  | '0' .. '9' | 'a' .. 'f' | 'A' .. 'F' -> true
  | _ -> false

let hex_value = function
  | '0' .. '9' as c -> Char.code c - Char.code '0'
  | 'a' .. 'f' as c -> 10 + Char.code c - Char.code 'a'
  | 'A' .. 'F' as c -> 10 + Char.code c - Char.code 'A'
  | _ -> 0

let decode_megalodon_tptp_name name =
  let encoded =
    if name = "emptyname" then name
    else if String.length name > 2
            && String.sub name 0 2 = "c_"
            && (name.[2] = '_'
                || ('A' <= name.[2] && name.[2] <= 'Z')
                || ('0' <= name.[2] && name.[2] <= '9')) then
      String.sub name 2 (String.length name - 2)
    else name
  in
  let buf = Buffer.create (String.length encoded) in
  let rec loop i =
    if i >= String.length encoded then ()
    else if encoded.[i] = '_'
            && i + 2 < String.length encoded
            && is_hex_char encoded.[i + 1]
            && is_hex_char encoded.[i + 2] then
      begin
        Buffer.add_char buf
          (Char.chr ((hex_value encoded.[i + 1] * 16) + hex_value encoded.[i + 2]));
        loop (i + 3)
      end
    else
      begin
        Buffer.add_char buf encoded.[i];
        loop (i + 1)
      end
  in
  loop 0;
  Buffer.contents buf

let simple_source_kind_and_tptp_name = function
  | SourceAxiom name -> ("axiom", name)
  | SourceConjecture name -> ("conjecture", name)
  | SourceNegatedConjecture name -> ("negated_conjecture", name)
  | SourceDefinition name -> ("definition", name)
  | SourceSetReflexivity name -> ("set_reflexivity", name)

let simple_path_basename value =
  let rec loop i last =
    if i >= String.length value then last
    else
      let last =
        match value.[i] with
        | '/' | '\\' -> i + 1
        | _ -> last
      in
      loop (i + 1) last
  in
  let start = loop 0 0 in
  String.sub value start (String.length value - start)

let simple_copied_conjecture_alias tptp_name =
  let decoded = decode_megalodon_tptp_name tptp_name in
  let base = simple_path_basename decoded in
  if base = "" || base = decoded then None
  else Some ("conj_" ^ base)

let simple_source_map_entry source_map source =
  let _, tptp_name = simple_source_kind_and_tptp_name source in
  match List.find_opt (fun entry -> entry.source_map_tptp_name = tptp_name) source_map with
  | Some _ as entry -> entry
  | None ->
      begin match source, simple_copied_conjecture_alias tptp_name with
      | (SourceConjecture _ | SourceNegatedConjecture _), Some alias ->
          begin match
            List.filter
              (fun entry ->
                 entry.source_map_kind = "conjecture"
                 && entry.source_map_tptp_name = alias)
              source_map
          with
          | [entry] -> Some entry
          | _ -> None
          end
      | _ -> None
      end

let simple_source_label source_map source =
  let kind, tptp_name = simple_source_kind_and_tptp_name source in
  let displayed_name =
    match simple_source_map_entry source_map source with
    | Some entry when entry.source_map_source_name <> "" -> entry.source_map_source_name
    | _ -> decode_megalodon_tptp_name tptp_name
  in
  kind ^ "_" ^ displayed_name

let simple_fresh_name used base =
  let base = megalodon_safe_ident "" base in
  let rec choose n =
    let candidate =
      if n = 0 then base else base ^ "_" ^ string_of_int n
    in
    if List.mem candidate !used then choose (n + 1)
    else begin
      used := candidate :: !used;
      candidate
    end
  in
  choose 0

let simple_term_name = function
  | TmH name -> megalodon_ident name
  | _ -> emit_error "only named set terms are supported in simple native emission"

let is_vampire_bool_const = function
  | TmH "f__true" | TmH "vampire_true" | TmH "f__false" | TmH "vampire_false" -> true
  | _ -> false

let is_db_ident name =
  let len = String.length name in
  let rec digits i =
    i >= len || (match name.[i] with '0'..'9' -> digits (i + 1) | _ -> false)
  in
  len > 2 && String.sub name 0 2 = "db" && digits 2

let simple_db_alias_env : string list ref = ref []

let simple_vlam_name_counter = ref 0

let simple_fresh_vlam_name () =
  let name = "vdb" ^ string_of_int !simple_vlam_name_counter in
  incr simple_vlam_name_counter;
  name

let simple_with_stable_vlam_names f =
  let previous = !simple_vlam_name_counter in
  simple_vlam_name_counter := 0;
  match f () with
  | result ->
      simple_vlam_name_counter := previous;
      result
  | exception exn ->
      simple_vlam_name_counter := previous;
      raise exn

let simple_db_index name =
  if is_db_ident name then
    Some (int_of_string (String.sub name 2 (String.length name - 2)))
  else None

let simple_db_alias_by_index index =
  List.nth_opt !simple_db_alias_env index

let simple_name_expr name =
  match Option.bind (simple_db_index name) simple_db_alias_by_index with
  | Some alias -> alias
  | None -> megalodon_ident name

let simple_with_db_aliases aliases f =
  let previous = !simple_db_alias_env in
  simple_db_alias_env := aliases @ previous;
  match f () with
  | result ->
      simple_db_alias_env := previous;
      result
  | exception exn ->
      simple_db_alias_env := previous;
      raise exn

let simple_bool_const_prop = function
  | TmH "f__true" | TmH "vampire_true" -> Some "vampire_true"
  | TmH "f__false" | TmH "vampire_false" -> Some "vampire_false"
  | _ -> None

let rec flatten_application = function
  | Ap (fn, arg) ->
      let head, args = flatten_application fn in
      (head, args @ [arg])
  | tm -> (tm, [])

let rec flatten_value_application = function
  | Ap (TmH "vLAM", _) as tm -> (tm, [])
  | Ap (fn, arg) ->
      let head, args = flatten_value_application fn in
      (head, args @ [arg])
  | tm -> (tm, [])

let simple_lambda_sort_env : (string * string) list ref = ref []

let simple_function_alias_env : (string * ((string * string) list * tm)) list ref = ref []

let simple_alias_binder_sort_expr sort =
  if String.contains sort '-' then "(" ^ sort ^ ")" else sort

let rec simple_source_tp_expr = function
  | Prop -> "prop"
  | Set -> "set"
  | TpVar _ -> emit_error "type variables are not supported in source-term rendering"
  | Ar (left, right) ->
      let left_text =
        match left with
        | Ar _ -> "(" ^ simple_source_tp_expr left ^ ")"
        | _ -> simple_source_tp_expr left
      in
      left_text ^ "->" ^ simple_source_tp_expr right

let rec simple_tm_contains_function_alias = function
  | TmH name -> List.mem_assoc name !simple_function_alias_env
  | DB _ | Prim _ -> false
  | TpAp (tm, _) -> simple_tm_contains_function_alias tm
  | Ap (left, right)
  | Imp (left, right) ->
      simple_tm_contains_function_alias left || simple_tm_contains_function_alias right
  | Lam (_, body)
  | All (_, body) -> simple_tm_contains_function_alias body

let simple_literal_contains_function_alias = function
  | Pos atom | Neg atom -> simple_tm_contains_function_alias atom

let simple_clause_contains_function_alias clause =
  List.exists simple_literal_contains_function_alias clause

let rec simple_source_tm_expr tm =
  let render_arg arg =
    match arg with
    | TmH _ | DB _ | Prim _ -> simple_source_tm_expr arg
    | _ -> "(" ^ simple_source_tm_expr arg ^ ")"
  in
  match tm with
  | TmH name -> megalodon_ident name
  | DB i -> "db" ^ string_of_int i
  | Prim i -> "prim_" ^ string_of_int i
  | TpAp (tm, _) -> simple_source_tm_expr tm
  | Ap (TmH "vLAM", body) ->
      let body_text = simple_source_tm_expr body in
      begin match body with
      | TmH _ | DB _ | Prim _ -> "vLAM " ^ body_text
      | _ -> "vLAM (" ^ body_text ^ ")"
      end
  | Ap _ ->
      let head, args = flatten_value_application tm in
      String.concat " " (simple_source_tm_expr head :: List.map render_arg args)
  | Imp (left, right) ->
      simple_source_tm_expr left ^ " -> " ^ simple_source_tm_expr right
  | All (tp, body) ->
      let binder = "db0" in
      "forall " ^ binder ^ ":" ^ simple_source_tp_expr tp ^ ", "
      ^ simple_with_db_aliases [binder] (fun () -> simple_source_tm_expr body)
  | Lam (tp, body) ->
      let binder = "db0" in
      "(fun " ^ binder ^ ":" ^ simple_source_tp_expr tp ^ " => "
      ^ simple_with_db_aliases [binder] (fun () -> simple_source_tm_expr body)
      ^ ")"

let simple_lambda_sort tm =
  match tm with
  | Ap (TmH "vLAM", _) ->
      begin match
        try Some (simple_source_tm_expr tm)
        with Error _ -> None
      with
      | Some key -> List.assoc_opt key !simple_lambda_sort_env
      | None -> None
      end
  | _ -> None

let rec simple_tp_expr = function
  | Prop -> "prop"
  | Set -> "set"
  | TpVar _ -> emit_error "type variables are not supported in simple native emission"
  | Ar (left, right) ->
      let left_text =
        match left with
        | Ar _ -> "(" ^ simple_tp_expr left ^ ")"
        | _ -> simple_tp_expr left
      in
      left_text ^ "->" ^ simple_tp_expr right

let rec simple_vlam_expr body =
  let logical_head = function
    | "vLAM" | "vPI" | "vOR" | "vAND" | "vNOT" | "vIMP"
    | "vampire_or" | "vampire_and" | "vampire_true" | "vampire_false"
    | "f__true" | "f__false" -> true
    | _ -> false
  in
  let rec contains_db = function
    | TmH name -> is_db_ident name
    | DB _ -> true
    | Prim _ -> false
    | TpAp (tm, _) -> contains_db tm
    | Ap (fn, arg) -> contains_db fn || contains_db arg
    | Lam (_, body) | All (_, body) -> contains_db body
    | Imp (left, right) -> contains_db left || contains_db right
  in
  let rec db_in_nonlogical_application tm =
    let head, args = flatten_application tm in
    let here =
      match head with
      | TmH name when not (logical_head name) ->
          List.exists contains_db args
      | _ -> false
    in
    here ||
    match tm with
    | TmH _ | DB _ | Prim _ -> false
    | TpAp (tm, _) -> db_in_nonlogical_application tm
    | Ap (fn, arg) -> db_in_nonlogical_application fn || db_in_nonlogical_application arg
    | Lam (_, body) | All (_, body) -> db_in_nonlogical_application body
    | Imp (left, right) -> db_in_nonlogical_application left || db_in_nonlogical_application right
  in
  let rec has_prop_logical_head tm =
    let head, args = flatten_application tm in
    let here =
      match head with
      | TmH ("vOR" | "vAND" | "vNOT" | "vIMP" | "vampire_or" | "vampire_and") -> true
      | _ -> false
    in
    here || List.exists has_prop_logical_head args
  in
  let binder_sort body =
    if db_in_nonlogical_application body then "set"
    else if has_prop_logical_head body then "prop"
    else "set"
  in
  let rec collect arity = function
    | Ap (TmH "vLAM", body) ->
        let sorts, final_body = collect (arity + 1) body in
        (binder_sort body :: sorts, final_body)
    | body -> ([binder_sort body], body)
  in
  let sorts, body = collect 1 body in
  let arity = List.length sorts in
  let rec binders n acc =
    if n <= 0 then acc else binders (n - 1) (acc @ [simple_fresh_vlam_name ()])
  in
  let binders = binders arity [] in
  let body_text =
    simple_with_db_aliases (List.rev binders)
      (fun () -> simple_tm_expr body)
  in
  "("
	  ^ String.concat " => "
	      ((List.combine sorts binders
	        |> List.map (fun (sort, name) -> "fun " ^ name ^ ":" ^ sort))
	       @ [body_text])
	  ^ ")"

and simple_lam_expr tp body =
  let rec collect acc = function
    | Lam (tp, body) -> collect (acc @ [tp]) body
    | body -> (acc, body)
  in
  let sorts, body = collect [tp] body in
  let arity = List.length sorts in
  let rec binders i acc =
    if i < 0 then acc else binders (i - 1) (acc @ ["db" ^ string_of_int i])
  in
  let binders = binders (arity - 1) [] in
  "("
  ^ String.concat " => "
      ((List.combine sorts binders
        |> List.map (fun (sort, name) -> "fun " ^ name ^ ":" ^ simple_tp_expr sort))
       @ [simple_tm_expr body])
  ^ ")"

and simple_tm_expr tm =
  match simple_bool_const_prop tm with
  | Some name -> name
  | None ->
      begin match equality_sides tm with
      | Some (left, right) when is_vampire_bool_const left || is_vampire_bool_const right ->
          "vampire_eq_prop (" ^ simple_tm_expr left ^ ") (" ^ simple_tm_expr right ^ ")"
      | Some (left, right) ->
          simple_tm_expr left ^ " = " ^ simple_tm_expr right
      | None ->
      begin match tm with
      | Lam (tp, body) -> simple_lam_expr tp body
      | _ ->
      let head, args = flatten_application tm in
      let arg_text arg =
        match arg with
        | TmH raw when List.mem_assoc raw !simple_function_alias_env ->
            "(" ^ simple_tm_expr arg ^ ")"
        | TmH _ | DB _ -> simple_tm_expr arg
        | _ -> "(" ^ simple_tm_expr arg ^ ")"
      in
      begin match head, args with
      | TmH "vLAM", body :: rest ->
          let head_text = simple_vlam_expr body in
          begin match rest with
          | [] -> head_text
          | _ -> String.concat " " (head_text :: List.map arg_text rest)
          end
      | TmH raw_name, _ ->
          let name = megalodon_ident raw_name in
          begin match List.assoc_opt name !simple_function_alias_env with
          | Some (binders, body) ->
              let arity = List.length binders in
              let provided = take_prefix arity args in
              let extra = drop_prefix arity args in
              let remaining = drop_prefix (List.length provided) binders in
              let substitution =
                List.map2
                  (fun (binder, _) arg -> (binder, arg))
                  (take_prefix (List.length provided) binders)
                  provided
              in
              let expanded = subst_tm substitution body in
              let expanded =
                List.fold_left (fun acc arg -> Ap (acc, arg)) expanded extra
              in
              let text = simple_tm_expr expanded in
              List.fold_right
                (fun (binder, sort) acc ->
                   "(fun " ^ binder ^ ":" ^ simple_alias_binder_sort_expr sort ^ " => " ^ acc ^ ")")
                remaining
                text
          | None ->
              let head_text = simple_name_expr raw_name in
              begin match args with
              | [] -> head_text
              | _ -> String.concat " " (head_text :: List.map arg_text args)
              end
          end
      | _ ->
          let head_text =
            match head with
            | TmH name -> simple_name_expr name
            | DB i ->
                begin match simple_db_alias_by_index i with
                | Some alias -> alias
                | None -> "db" ^ string_of_int i
                end
            | Imp _ | All _ | Lam _ | TpAp _ | Prim _ ->
                emit_error "only named/application terms are supported in simple native emission"
            | _ -> "(" ^ simple_tm_expr head ^ ")"
          in
          match args with
          | [] -> head_text
          | _ -> String.concat " " (head_text :: List.map arg_text args)
	      end
      end
      end

let rec simple_prop_equality_arg tm =
  if is_vampire_bool_const tm then
    if is_vampire_false tm then "vampire_false" else "vampire_true"
  else
    match equality_sides tm with
    | Some _ -> simple_atom_prop tm
    | None -> simple_tm_expr tm

and simple_prop_equality left right =
  "vampire_eq_prop (" ^ simple_prop_equality_arg left ^ ") ("
  ^ simple_prop_equality_arg right ^ ")"

and simple_atom_prop = function
  | TmH name -> simple_name_expr name
  | atom ->
      begin match equality_sides atom with
      | Some (left, right) when is_vampire_bool_const left || is_vampire_bool_const right ->
          simple_prop_equality left right
      | Some (left, right) ->
          simple_tm_expr left ^ " = " ^ simple_tm_expr right
      | None ->
          simple_tm_expr atom
      end

let simple_literal_prop = function
  | Pos atom -> simple_atom_prop atom
  | Neg atom -> "(" ^ simple_atom_prop atom ^ " -> False)"

let rec simple_clause_prop = function
  | [] -> "False"
  | [lit] -> simple_literal_prop lit
  | lit :: rest -> "(" ^ simple_literal_prop lit ^ " \\/ " ^ simple_clause_prop rest ^ ")"

let simple_prop_arg prop = "(" ^ prop ^ ")"

let simple_true_proof = "(fun p:prop => fun H:p => H)"

let simple_prop_equal_mod_app_parens left right =
  let has_reserved_syntax text =
    let contains needle =
      let len = String.length text in
      let needle_len = String.length needle in
      let rec loop i =
        i + needle_len <= len
        && (String.sub text i needle_len = needle || loop (i + 1))
      in
      needle_len = 0 || loop 0
    in
    contains "forall "
    || contains " -> "
    || contains "\\/"
    || contains "="
    || contains "=>"
    || contains ":"
  in
  let ident_start = function
    | 'A'..'Z' | 'a'..'z' | '_' -> true
    | _ -> false
  in
  let removable_inner text =
    let text = String.trim text in
    text <> "" && ident_start text.[0] && not (has_reserved_syntax text)
  in
  let normalize_once text =
    let len = String.length text in
    let buffer = Buffer.create len in
    let rec find_close depth i =
      if i >= len then None
      else
        match text.[i] with
        | '(' -> find_close (depth + 1) (i + 1)
        | ')' ->
            if depth = 0 then Some i else find_close (depth - 1) (i + 1)
        | _ -> find_close depth (i + 1)
    in
    let rec loop changed i =
      if i >= len then changed
      else if text.[i] = '(' then
        match find_close 0 (i + 1) with
        | Some close ->
            let inner = String.sub text (i + 1) (close - i - 1) in
            if removable_inner inner then begin
              Buffer.add_string buffer inner;
              loop true (close + 1)
            end else begin
              Buffer.add_char buffer text.[i];
              loop changed (i + 1)
            end
        | None ->
            Buffer.add_char buffer text.[i];
            loop changed (i + 1)
      else begin
        Buffer.add_char buffer text.[i];
        loop changed (i + 1)
      end
    in
    let changed = loop false 0 in
    (changed, Buffer.contents buffer)
  in
  let rec normalize text =
    let changed, text = normalize_once text in
    if changed then normalize text else text
  in
  normalize left = normalize right

let simple_prop_equal_mod_cnf_defs left right =
  let replace_all needle replacement text =
    let needle_len = String.length needle in
    let text_len = String.length text in
    let buffer = Buffer.create text_len in
    let rec loop i =
      if i >= text_len then ()
      else if i + needle_len <= text_len && String.sub text i needle_len = needle then begin
        Buffer.add_string buffer replacement;
        loop (i + needle_len)
      end else begin
        Buffer.add_char buffer text.[i];
        loop (i + 1)
      end
    in
    loop 0;
    Buffer.contents buffer
  in
  let normalize text =
    text
    |> replace_all "vampire_false" "False"
    |> replace_all "vampire_true" "True"
    |> replace_all "vampire_or" ""
    |> replace_all "\\/" ""
    |> String.to_seq
    |> Seq.filter
         (function
           | ' ' | '\n' | '\t' | '\r' | '(' | ')' -> false
           | _ -> true)
    |> String.of_seq
  in
  normalize left = normalize right

let simple_prop_equal_mod_fool_exhaustiveness_or_alias left right =
  let replace_all needle replacement text =
    let needle_len = String.length needle in
    let text_len = String.length text in
    let buffer = Buffer.create text_len in
    let rec loop i =
      if i >= text_len then ()
      else if i + needle_len <= text_len && String.sub text i needle_len = needle then begin
        Buffer.add_string buffer replacement;
        loop (i + needle_len)
      end else begin
        Buffer.add_char buffer text.[i];
        loop (i + 1)
      end
    in
    loop 0;
    Buffer.contents buffer
  in
  let normalize text =
    text
    |> replace_all "vampire_false" "False"
    |> replace_all "vampire_true" "True"
    |> replace_all "vampire_or" ""
    |> replace_all "\\/" ""
    |> String.to_seq
    |> Seq.filter
         (function
           | ' ' | '\n' | '\t' | '\r' | '(' | ')' -> false
           | _ -> true)
    |> String.of_seq
  in
  normalize left = normalize right

let simple_fool_exhaustiveness_clause = function
  | [left; right] ->
      begin match true_false_equality_var left, true_false_equality_var right with
      | Some ("f__true", x), Some ("f__false", y)
      | Some ("f__false", x), Some ("f__true", y) -> x = y
      | _ -> false
      end
  | _ -> false

let collect_simple_names cert =
  let declared_names = metadata_declared_names cert in
  let variable_sorts = metadata_variable_sorts cert in
  let typed_variable_names = List.map fst variable_sorts in
  let is_known name =
    List.mem name declared_names
    || List.mem name typed_variable_names
    || List.mem name
         [
           "False"; "True"; "or"; "vampire_or"; "vampire_and"; "vampire_exists_set";
           "vampire_exists_prop"; "vampire_false"; "vampire_true"; "vampire_eq_prop";
           "vampire_exists_set_set_prop";
           "vampire_eq_prop_to_prop_to_prop";
           "vampire_eq_set_to_set"; "vampire_eq_set_to_prop";
           "vampire_eq_set_to_set_to_prop"; "vampire_eq_set_to_set_to_set";
           "vampire_eq_lp_set_to_set_rp_to_set";
           "vampire_eq_lp_set_to_prop_rp_to_set";
           "vampire_eq_set_to_lp_set_to_set_rp_to_set";
           "vampire_eq_lp_set_to_set_rp_to_set_to_set";
           "vampire_eq_lp_set_to_set_to_set_rp_to_set_to_set";
           "vampire_eq_set_to_lp_set_to_set_to_set_rp_to_set_to_set";
           "f__true"; "f__false"; "vLAM"; "vPI"
         ]
  in
  let add_prop acc name =
    let name = megalodon_ident name in
    let props, terms = acc in
    if is_known name || List.mem name props then acc else (name :: props, terms)
  in
  let add_term acc term =
    let name = simple_term_name term in
    let props, terms = acc in
    if is_known name || List.mem name terms then acc else (props, name :: terms)
  in
  let rec add_term_expr acc = function
    | TmH name when is_vampire_bool_const (TmH name) || is_known name -> acc
    | TmH _ as term -> add_term acc term
    | DB _ -> acc
    | Ap (fn, arg) -> add_term_expr (add_term_expr acc fn) arg
    | TpAp (fn, _) -> add_term_expr acc fn
    | Lam (_, body) -> add_term_expr acc body
    | Imp (left, right) -> add_prop_expr (add_prop_expr acc left) right
    | All (_, body) -> add_prop_expr acc body
    | Prim _ -> acc
  and add_prop_expr acc = function
    | TmH name when is_vampire_bool_const (TmH name) || is_known name -> acc
    | TmH name -> add_prop acc name
    | Ap _ as atom ->
        begin match equality_sides atom with
        | Some (left, right) when is_vampire_bool_const left || is_vampire_bool_const right ->
            add_prop_expr (add_prop_expr acc left) right
        | Some (left, right) -> add_term_expr (add_term_expr acc left) right
        | None ->
            let head, args = flatten_application atom in
            let acc =
              match head with
              | TmH name when is_known name -> acc
              | TmH _ -> add_prop_expr acc head
              | _ -> add_prop_expr acc head
            in
            List.fold_left add_term_expr acc args
        end
    | TpAp (fn, _) -> add_prop_expr acc fn
    | Lam (_, body) -> add_prop_expr acc body
    | Imp (left, right) -> add_prop_expr (add_prop_expr acc left) right
    | All (_, body) -> add_prop_expr acc body
    | DB _ | Prim _ -> acc
  in
  let add_atom acc atom =
    match equality_sides atom with
    | Some (left, right) when is_vampire_bool_const left || is_vampire_bool_const right ->
        add_prop_expr (add_prop_expr acc left) right
    | Some (left, right) -> add_term_expr (add_term_expr acc left) right
    | None -> add_prop_expr acc atom
  in
  let add_literal acc = function
    | Pos atom | Neg atom -> add_atom acc atom
  in
  let add_clause acc clause = List.fold_left add_literal acc clause in
  let add_step acc = function
    | Input (_, _, clause) -> add_clause acc clause
    | FormulaInput (id, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | FormulaTermInput (id, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | FormulaTermCopy (id, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | RectifyFormula (id, _, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | FoolAtomLift (id, _, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | FormulaCopy (id, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | FoolFormula (id, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | FoolBool (id, _, lit) ->
        ignore (simple_formula_prop cert id);
        add_literal acc lit
    | EnnfFormula (id, _, _, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | SkolemFormula (id, _, _, _, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | SkolemFormulaComputed (id, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | CnfLiteral (id, _, clause) ->
        ignore (simple_formula_prop cert id);
        add_clause acc clause
    | CnfFormulaClause (id, _, _, _, clause) ->
        ignore (simple_formula_prop cert id);
        add_clause acc clause
    | FoolExhaustiveness (_, clause) -> add_clause acc clause
    | FoolDistinctness (_, clause) -> add_clause acc clause
    | PredicateDefinition (id, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | PredicateDefinitionFold (id, _, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | PredicateDefinitionFoldChain (id, _, _, _) ->
        ignore (simple_formula_prop cert id);
        acc
    | DefinitionInput (_, clause) -> add_clause acc clause
    | Substitute (_, _, _, clause) -> add_clause acc clause
    | Condensation (_, _, _, clause) -> add_clause acc clause
    | UnitResultingResolution (_, _, _, clause) -> add_clause acc clause
    | SubsumptionResolution (_, _, _, _, _, _, clause) -> add_clause acc clause
    | Resolve (_, _, _, _, _, clause) -> add_clause acc clause
    | Factor (_, _, _, _, clause) -> add_clause acc clause
    | EqualitySymmetry (_, _, _, clause) -> add_clause acc clause
    | EqualityResolution (_, _, _, clause) -> add_clause acc clause
    | EqualityResolutionConstraints (_, _, _, _, _, clause) -> add_clause acc clause
    | EqualityFactoring (_, _, _, _, _, _, clause) -> add_clause acc clause
    | EqualityFactoringConstraints (_, _, _, _, _, _, _, clause) -> add_clause acc clause
    | TruthConflict (_, _, _, clause) -> add_clause acc clause
    | BoolSimplify (_, _, _, _, _, _, clause) -> add_clause acc clause
    | Paramodulate (_, _, _, _, _, _, _, _, clause) -> add_clause acc clause
    | Superposition (_, _, _, _, _, _, _, _, _, _, clause) -> add_clause acc clause
    | DefinitionRewriteChain (_, _, _, clause) -> add_clause acc clause
    | AvatarComponent (_, clause) -> add_clause acc clause
    | AvatarDefinition (_, _, _, clause) -> add_clause acc clause
    | SplitDependency (_, _, dependencies, clause) ->
        dependencies
        |> List.fold_left
             (fun acc dependency -> add_clause acc dependency.dependency_component)
             (add_clause acc clause)
    | AvatarSplit (_, _, clause) -> add_clause acc clause
    | AvatarContradiction (_, _, clause) -> add_clause acc clause
    | AvatarRefutation (_, _, _, _, clause) -> add_clause acc clause
    | InequalityNameIntro (_, clause) -> add_clause acc clause
    | InequalitySplit (_, _, _, clause) -> add_clause acc clause
    | Contradiction _ -> acc
  in
  let props, terms = List.fold_left add_step ([], []) cert.steps in
  let terms =
    terms
    |> List.filter (fun name -> not (is_db_ident name && List.mem name props))
  in
  let collisions = List.filter (fun name -> List.mem name terms) props in
  begin match collisions with
  | [] -> ()
  | name :: _ ->
      emit_error ("identifier " ^ name ^ " is used both as a proposition and a set term")
  end;
  (List.sort String.compare props, List.sort String.compare terms)

let lookup_simple_clause checked id =
  match List.assoc_opt id checked with
  | Some clause -> clause
  | None -> emit_error ("missing parent " ^ id)

let lookup_simple_name names id =
  match List.assoc_opt id names with
  | Some name -> name
  | None -> emit_error ("missing emitted parent name " ^ id)

let simple_clause_nth id label index clause =
  if index < 0 || index >= List.length clause then
    emit_error (id ^ ": " ^ label ^ " index is out of bounds");
  List.nth clause index

let simple_literal_index id label selected clause =
  let rec find index = function
    | [] -> emit_error (id ^ ": " ^ label ^ " literal is not present")
    | literal :: rest -> if literal = selected then index else find (index + 1) rest
  in
  find 0 clause

let simple_remove_index id label index clause =
  if index < 0 || index >= List.length clause then
    emit_error (id ^ ": " ^ label ^ " index is out of bounds");
  List.mapi (fun i lit -> (i, lit)) clause
  |> List.filter (fun (i, _) -> i <> index)
  |> List.map snd

let simple_sorts_subset smaller larger =
  List.for_all
    (fun (name, sort) -> List.exists (fun (name', sort') -> name = name' && sort = sort') larger)
    smaller

let simple_wrap_forall_intro sorts proof =
  List.fold_right
    (fun (name, sort) body ->
       "(fun " ^ megalodon_ident name ^ ":" ^ sort ^ " => " ^ body ^ ")")
    sorts
    proof

let simple_forall_prefix_sorts prop =
  let len = String.length prop in
  let is_space = function ' ' | '\n' | '\r' | '\t' -> true | _ -> false in
  let is_ident = function
    | 'a' .. 'z' | 'A' .. 'Z' | '0' .. '9' | '_' | '\'' -> true
    | _ -> false
  in
  let rec skip i =
    if i < len && is_space prop.[i] then skip (i + 1) else i
  in
  let starts_with i prefix =
    let prefix_len = String.length prefix in
    i + prefix_len <= len && String.sub prop i prefix_len = prefix
  in
  let rec parse acc i =
    let i = skip i in
    if not (starts_with i "forall") then acc
    else
      let j = i + 6 in
      if j < len && is_ident prop.[j] then acc
      else
        let j = skip j in
        let name_start = j in
        let rec scan_name k =
          if k < len && is_ident prop.[k] then scan_name (k + 1) else k
        in
        let name_end = scan_name name_start in
        if name_end = name_start then acc
        else
          let name = String.sub prop name_start (name_end - name_start) in
          let k = skip name_end in
          if k >= len || prop.[k] <> ':' then acc
          else
            let sort_start = skip (k + 1) in
            let rec scan_sort depth k =
              if k >= len then k
              else
                match prop.[k] with
                | '(' -> scan_sort (depth + 1) (k + 1)
                | ')' -> scan_sort (max 0 (depth - 1)) (k + 1)
                | ',' when depth = 0 -> k
                | _ -> scan_sort depth (k + 1)
            in
            let sort_end = scan_sort 0 sort_start in
            if sort_end >= len || prop.[sort_end] <> ',' then acc
            else
              let sort =
                String.sub prop sort_start (sort_end - sort_start)
                |> String.trim
              in
              parse (acc @ [(megalodon_ident name, sort)]) (sort_end + 1)
  in
  parse [] 0

let simple_wrap_forall_intro_in_order sorts proof =
  List.fold_right
    (fun (name, sort) body ->
       "(fun " ^ megalodon_ident name ^ ":" ^ sort ^ " => " ^ body ^ ")")
    sorts
    proof

let simple_apply_forall_vars proof sorts =
  List.fold_left
    (fun acc (name, _) -> "(" ^ acc ^ " " ^ megalodon_ident name ^ ")")
    proof
    sorts

let simple_witness_for_sort sort =
  match String.trim sort with
  | "set" -> "(Eps_i (fun Xeps:set => vampire_true))"
  | "prop" -> "vampire_true"
  | other -> emit_error ("no canonical witness for quantified sort " ^ other)

let simple_sort_has_canonical_witness sort =
  try
    ignore (simple_witness_for_sort sort);
    true
  with Error _ -> false

let simple_sorts_instantiable_from_result parent_sorts result_sorts =
  let result_name_sorts =
    List.map (fun (name, sort) -> (megalodon_ident name, sort)) result_sorts
  in
  List.for_all
    (fun (name, sort) ->
       let ident = megalodon_ident name in
       match List.assoc_opt ident result_name_sorts with
       | Some result_sort when result_sort = sort -> true
       | _ -> simple_sort_has_canonical_witness sort)
    parent_sorts

let simple_apply_forall_witnesses proof sorts =
  List.fold_left
    (fun acc (_, sort) -> "(" ^ acc ^ " " ^ simple_witness_for_sort sort ^ ")")
    proof
    sorts

let simple_named_witness_ok name sort =
  let sort = String.trim sort in
  sort <> "prop"
  && not (String.contains sort '-')
  && name <> ""
  && name <> "Eps_i"
  && name <> "vampire_true"
  && name <> "vampire_false"
  && name <> "f__true"
  && name <> "f__false"
  && not (string_starts_with "vampire_" name)
  && not (string_starts_with "vdb" name)
  && not (is_db_ident name)
  && not (is_vampire_var_name name)

let simple_witness_from_env type_env sort =
  let sort = String.trim sort in
  match
    type_env
    |> List.find_opt
         (fun (name, known_sort) ->
            String.trim known_sort = sort && simple_named_witness_ok name sort)
  with
  | Some (name, _) -> name
  | None -> simple_witness_for_sort sort

let simple_apply_forall_witnesses_from_env type_env proof sorts =
  List.fold_left
    (fun acc (_, sort) -> "(" ^ acc ^ " " ^ simple_witness_from_env type_env sort ^ ")")
    proof
    sorts

let simple_apply_forall_result_vars_or_witnesses proof result_sorts parent_sorts =
  let result_name_sorts =
    List.map (fun (name, sort) -> (megalodon_ident name, sort)) result_sorts
  in
  List.fold_left
    (fun acc (name, sort) ->
       let ident = megalodon_ident name in
       let arg =
         match List.assoc_opt ident result_name_sorts with
         | Some result_sort when result_sort = sort -> ident
         | _ -> simple_witness_for_sort sort
       in
       "(" ^ acc ^ " " ^ arg ^ ")")
    proof
    parent_sorts

let simple_parent_proof_with_emitted_prefix parent_prop parent_formula parent_name =
  let emitted_prefix = simple_forall_prefix_sorts parent_prop in
  let formula_prefix_count = prefix_forall_count parent_formula in
  let extra_prefix_count = List.length emitted_prefix - formula_prefix_count in
  if extra_prefix_count <= 0 then parent_name
  else
    simple_apply_forall_witnesses
      parent_name
      (take_prefix extra_prefix_count emitted_prefix)

let simple_rectify_extra_prefix_binders_proof
    parent_prop target_prop parent_formula target_formula parent_name =
  let parent_binders = simple_forall_prefix_sorts parent_prop in
  let target_binders = simple_forall_prefix_sorts target_prop in
  if List.length target_binders <= List.length parent_binders then
    emit_error "rectification prefix replay expects extra target binders";
  if not
       (same_mod_scoped_vampire_var_renaming parent_formula target_formula
        || same_mod_scoped_vampire_var_renaming_and_equality parent_formula target_formula
        || same_mod_scoped_vampire_var_renaming
             (strip_forall parent_formula)
             (strip_forall target_formula)
        || same_mod_scoped_vampire_var_renaming_and_equality
             (strip_forall parent_formula)
             (strip_forall target_formula)) then
    emit_error "rectification prefix replay body is not a scoped renaming";
  let target_sort name =
    List.assoc_opt name target_binders
  in
  let parent_application =
    List.fold_left
      (fun acc (name, sort) ->
         let arg =
           match target_sort name with
           | Some target_sort when target_sort = sort -> name
           | _ -> simple_witness_for_sort sort
         in
         "(" ^ acc ^ " " ^ arg ^ ")")
      parent_name
      parent_binders
  in
  simple_wrap_forall_intro_in_order target_binders parent_application

let simple_resolution_proof
    literal_prop parent_sorts_of result_sorts id left_id right_id left_index right_index result checked names =
  let left_clause = lookup_simple_clause checked left_id in
  let right_clause = lookup_simple_clause checked right_id in
  let left_pivot = simple_clause_nth id "left" left_index left_clause in
  let right_pivot = simple_clause_nth id "right" right_index right_clause in
  if not (complementary left_pivot right_pivot) then
    emit_error (id ^ ": pivots are not complementary");
  let left_rest = simple_remove_index id "left" left_index left_clause in
  let right_rest = simple_remove_index id "right" right_index right_clause in
  let positive_parent, negative_parent, positive_index, negative_index, positive_rest, negative_rest =
    match left_pivot, right_pivot with
    | Pos _, Neg _ -> left_id, right_id, left_index, right_index, left_rest, right_rest
    | Neg _, Pos _ -> right_id, left_id, right_index, left_index, right_rest, left_rest
    | _ -> emit_error (id ^ ": pivots are not complementary")
  in
  let positive_parent_name =
    simple_apply_forall_result_vars_or_witnesses
      (lookup_simple_name names positive_parent)
      result_sorts
      (parent_sorts_of positive_parent)
  in
  let negative_parent_name =
    simple_apply_forall_result_vars_or_witnesses
      (lookup_simple_name names negative_parent)
      result_sorts
      (parent_sorts_of negative_parent)
  in
  let wrap proof = simple_wrap_forall_intro result_sorts proof in
  match positive_rest, negative_rest, result with
  | [tail], [], [res] when tail = res ->
      if positive_index <> 0 then
        emit_error (id ^ ": simple binary-tail resolution expects the positive pivot at the clause head");
      let target = literal_prop res in
      let target_arg = simple_prop_arg target in
      wrap
        (Printf.sprintf
           "(%s %s (fun Hlit_0 => ((%s Hlit_0) %s)) (fun Htail_1 => Htail_1))"
           positive_parent_name target_arg negative_parent_name target_arg)
  | [], [tail], [res] when tail = res ->
      if negative_index <> 0 then
        emit_error (id ^ ": simple binary-tail resolution expects the negative pivot at the clause head");
      let target = literal_prop res in
      let target_arg = simple_prop_arg target in
      wrap
        (Printf.sprintf
           "(%s %s (fun Hlit_0 => ((Hlit_0 %s) %s)) (fun Htail_1 => Htail_1))"
           negative_parent_name target_arg positive_parent_name target_arg)
  | [positive_tail], [negative_tail], [res]
      when positive_tail = res && negative_tail = res ->
      if positive_index <> 0 || negative_index <> 0 then
        emit_error (id ^ ": simple binary-tail resolution expects pivots at clause heads");
      let target = literal_prop res in
      let target_arg = simple_prop_arg target in
      wrap
        (Printf.sprintf
           "(%s %s (fun Hlit_0 => (%s %s (fun Hnot_1 => ((Hnot_1 Hlit_0) %s)) (fun Htail_2 => Htail_2))) (fun Htail_3 => Htail_3))"
           positive_parent_name target_arg negative_parent_name target_arg target_arg)
  | [], [], [] ->
      if positive_index <> 0 || negative_index <> 0 then
        emit_error (id ^ ": simple unit resolution expects pivots at the clause head");
      wrap (Printf.sprintf "((%s %s) False)" negative_parent_name positive_parent_name)
  | _ ->
      emit_error (id ^ ": simple emitter supports only unit resolution and binary-tail unit resolution")

let simple_subsumption_resolution_proof
    literal_prop parent_sorts_of result_sorts id main_parent_id side_parent_id selected side_pivot side_subst result checked names =
  let main_clause = lookup_simple_clause checked main_parent_id in
  let raw_side_clause = lookup_simple_clause checked side_parent_id in
  let side_clause = subst_clause side_subst raw_side_clause in
  let side_pivot = subst_literal side_subst side_pivot in
  let selected_index =
    simple_literal_index id "subsumption-resolution selected" selected main_clause
  in
  let side_index =
    simple_literal_index id "subsumption-resolution side" side_pivot side_clause
  in
  let checked, names, parent_sorts_of =
    match side_subst with
    | [] -> checked, names, parent_sorts_of
    | _ ->
        let side_parent_sorts = parent_sorts_of side_parent_id in
        let side_parent_name = lookup_simple_name names side_parent_id in
        let instantiated_side_name =
          List.fold_left
            (fun acc (name, sort) ->
               let arg =
                 match List.assoc_opt name side_subst with
                 | Some tm -> simple_tm_expr tm
                 | None ->
                     let ident = megalodon_ident name in
                     if ident <> "" then ident else simple_witness_for_sort sort
               in
               "(" ^ acc ^ " " ^ arg ^ ")")
            side_parent_name
            side_parent_sorts
        in
        let checked =
          (side_parent_id, side_clause)
          :: List.remove_assoc side_parent_id checked
        in
        let names =
          (side_parent_id, instantiated_side_name)
          :: List.remove_assoc side_parent_id names
        in
        let parent_sorts_of parent_id =
          if parent_id = side_parent_id then [] else parent_sorts_of parent_id
        in
        checked, names, parent_sorts_of
  in
  simple_resolution_proof
    literal_prop parent_sorts_of result_sorts id
    main_parent_id side_parent_id selected_index side_index result checked names

let rec simple_resolution_clause_proof
    clause_body_prop parent_sorts_of result_sorts id left_id right_id left_index right_index result checked names =
  let left_clause = lookup_simple_clause checked left_id in
  let right_clause = lookup_simple_clause checked right_id in
  let left_pivot = simple_clause_nth id "left" left_index left_clause in
  let right_pivot = simple_clause_nth id "right" right_index right_clause in
  if not (complementary left_pivot right_pivot) then
    emit_error (id ^ ": pivots are not complementary");
  let left_rest = simple_remove_index id "left" left_index left_clause in
  let right_rest = simple_remove_index id "right" right_index right_clause in
  let expected = left_rest @ right_rest in
  if not (same_clause_multiset expected result) then
    emit_error (id ^ ": simple resolution proof expects parent rests as result");
  let positive_parent, negative_parent, positive_index, negative_index =
    match left_pivot, right_pivot with
    | Pos _, Neg _ -> left_id, right_id, left_index, right_index
    | Neg _, Pos _ -> right_id, left_id, right_index, left_index
    | _ -> emit_error (id ^ ": pivots are not complementary")
  in
  let positive_clause = lookup_simple_clause checked positive_parent in
  let negative_clause = lookup_simple_clause checked negative_parent in
  let positive_parent_name =
    simple_apply_forall_result_vars_or_witnesses
      (lookup_simple_name names positive_parent)
      result_sorts
      (parent_sorts_of positive_parent)
  in
  let negative_parent_name =
    simple_apply_forall_result_vars_or_witnesses
      (lookup_simple_name names negative_parent)
      result_sorts
      (parent_sorts_of negative_parent)
  in
  let target_prop = clause_body_prop result in
  let target_arg = simple_prop_arg target_prop in
  let negative_pivot_branch neg_proof pos_proof =
    Printf.sprintf "((%s %s) %s)" neg_proof pos_proof target_arg
  in
  let rec consume_negative selected_index source_clause source_proof pos_proof depth =
    match source_clause with
    | [] -> emit_error "cannot resolve against the empty negative clause"
    | [lit] ->
        begin match selected_index with
        | Some 0 -> negative_pivot_branch source_proof pos_proof
        | Some _ -> emit_error "resolution negative pivot index is out of bounds"
        | None -> simple_clause_intro_proof result lit source_proof
        end
    | lit :: rest ->
        let head_name = "Hres_neg_lit_" ^ string_of_int depth in
        let tail_name = "Hres_neg_tail_" ^ string_of_int depth in
        let head_branch =
          match selected_index with
          | Some 0 -> negative_pivot_branch head_name pos_proof
          | _ -> simple_clause_intro_proof result lit head_name
        in
        let rest_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch = consume_negative rest_selected rest tail_name pos_proof (depth + 1) in
        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
          source_proof target_arg
          head_name head_branch
          tail_name tail_branch
  in
  let rec consume_positive selected_index source_clause source_proof depth =
    match source_clause with
    | [] -> emit_error "cannot resolve from the empty positive clause"
    | [lit] ->
        begin match selected_index with
        | Some 0 -> consume_negative (Some negative_index) negative_clause negative_parent_name source_proof 0
        | Some _ -> emit_error "resolution positive pivot index is out of bounds"
        | None -> simple_clause_intro_proof result lit source_proof
        end
    | lit :: rest ->
        let head_name = "Hres_pos_lit_" ^ string_of_int depth in
        let tail_name = "Hres_pos_tail_" ^ string_of_int depth in
        let head_branch =
          match selected_index with
          | Some 0 -> consume_negative (Some negative_index) negative_clause negative_parent_name head_name 0
          | _ -> simple_clause_intro_proof result lit head_name
        in
        let rest_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch = consume_positive rest_selected rest tail_name (depth + 1) in
        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
          source_proof target_arg
          head_name head_branch
          tail_name tail_branch
  in
  simple_wrap_forall_intro result_sorts
    (consume_positive (Some positive_index) positive_clause positive_parent_name 0)

and simple_clause_intro_proof clause lit proof =
  match clause with
  | [] -> emit_error "cannot introduce a literal into the empty clause"
  | [single] when single = lit -> proof
  | head :: tail when head = lit ->
      Printf.sprintf "(fun vclause_goal Hhead Htail => Hhead %s)" proof
  | _ :: tail ->
      let tail_proof = simple_clause_intro_proof tail lit proof in
      Printf.sprintf "(fun vclause_goal Hhead Htail => Htail %s)" tail_proof

and simple_clause_suffix_intro_proof clause suffix proof =
  if clause = suffix then proof
  else
    match clause with
    | [] -> emit_error "cannot introduce a suffix into the empty clause"
    | _ :: tail ->
        let tail_proof = simple_clause_suffix_intro_proof tail suffix proof in
        Printf.sprintf "(fun vclause_goal Hhead Htail => Htail %s)" tail_proof

let rec simple_clause_projection_proof target_prop target_clause source_clause source_proof depth =
  let literal_prop = simple_literal_prop in
  let fast_projection () =
    match source_clause, target_clause with
    | [a; b; c; d; e; f; g], [g'; b'; c'; d'; e'; f'; a']
        when a = a' && b = b' && c = c' && d = d' && e = e' && f = f' && g = g' ->
        Some
          (Printf.sprintf
             "(vampire_or_rotate_last_first7 (%s) (%s) (%s) (%s) (%s) (%s) (%s) %s)"
             (literal_prop a) (literal_prop b) (literal_prop c) (literal_prop d)
             (literal_prop e) (literal_prop f) (literal_prop g) source_proof)
    | _ -> None
  in
  match fast_projection () with
  | Some proof -> proof
  | None ->
  match source_clause with
  | [] -> emit_error "cannot project from the empty clause"
  | [lit] -> simple_clause_intro_proof target_clause lit source_proof
  | lit :: rest ->
      let head_name = "Hproj_lit_" ^ string_of_int depth in
      let tail_name = "Hproj_tail_" ^ string_of_int depth in
      let head_branch = simple_clause_intro_proof target_clause lit head_name in
      let tail_branch =
        simple_clause_projection_proof target_prop target_clause rest tail_name (depth + 1)
      in
      Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
        source_proof (simple_prop_arg target_prop)
        head_name head_branch
        tail_name tail_branch

let simple_clause_projection_script target_prop target_clause source_clause source_proof result_sorts =
  match source_clause, target_clause with
  | [a; b; c; d; e; f; g], [g'; b'; c'; d'; e'; f'; a']
      when a = a' && b = b' && c = c' && d = d' && e = e' && f = f' && g = g' ->
      let binders =
        result_sorts
        |> List.map (fun (name, _) -> megalodon_ident name)
        |> String.concat " "
      in
      let let_prefix =
        if binders = "" then "" else "let " ^ binders ^ ". "
      in
      let intro_rights =
        List.init (List.length target_clause - 1) (fun _ -> "apply vampire_or_intro_right.")
        |> String.concat " "
      in
      Some
        ("__SCRIPT__"
         ^ let_prefix
         ^ "apply (" ^ source_proof ^ " " ^ simple_prop_arg target_prop ^ ").\n"
         ^ "- assume Hproj_head. "
         ^ intro_rights
         ^ " exact Hproj_head.\n"
         ^ "- assume Hproj_tail. apply vampire_or_rotate_last_first6_extend. exact Hproj_tail.")
  | _ -> None

let rec simple_clause_remove_reflexive_disequality_proof
    target_prop target_clause selected_index source_clause source_proof depth =
  let literal_prop = simple_literal_prop in
  let selected_branch lit proof =
    match lit with
    | Neg atom ->
        begin match equality_sides atom with
        | Some (left, right) when left = right ->
            Printf.sprintf "((%s (fun Q H => H)) %s)" proof (simple_prop_arg target_prop)
        | Some _ ->
            emit_error "equality-resolution selected literal is not reflexive"
        | None ->
            emit_error "equality-resolution selected literal is not an equality"
        end
    | Pos _ ->
        emit_error "equality-resolution selected literal is not negative"
  in
  let fast_drop_head () =
    match selected_index, source_clause, target_clause with
    | Some 0, [a; b; c; d; e; f; g], [b'; c'; d'; e'; f'; g']
        when b = b' && c = c' && d = d' && e = e' && f = f' && g = g' ->
        begin match a with
        | Neg atom ->
            begin match equality_sides atom with
            | Some (left, right) when left = right ->
                let selected_prop = literal_prop a in
                Some
                  (Printf.sprintf
                     "(vampire_or_drop_head7 (%s) (%s) (%s) (%s) (%s) (%s) (%s) (fun Hdrop_head:%s => ((Hdrop_head (fun Q H => H)) %s)) %s)"
                     selected_prop
                     (literal_prop b) (literal_prop c) (literal_prop d)
                     (literal_prop e) (literal_prop f) (literal_prop g)
                     selected_prop (simple_prop_arg target_prop) source_proof)
            | Some _ -> emit_error "equality-resolution equality is not reflexive"
            | None -> emit_error "equality-resolution literal is not an equality"
            end
        | Pos _ -> emit_error "equality-resolution selected literal is not negative"
        end
    | _ -> None
  in
  match fast_drop_head () with
  | Some proof -> proof
  | None ->
  match source_clause with
  | [] -> emit_error "cannot remove a literal from the empty clause"
  | [lit] ->
      begin match selected_index with
      | Some 0 -> selected_branch lit source_proof
      | Some _ -> emit_error "equality-resolution selected index is out of bounds"
      | None -> simple_clause_intro_proof target_clause lit source_proof
      end
  | lit :: rest ->
      let head_name = "Heqres_lit_" ^ string_of_int depth in
      let tail_name = "Heqres_tail_" ^ string_of_int depth in
      let head_branch =
        match selected_index with
        | Some 0 -> selected_branch lit head_name
        | _ -> simple_clause_intro_proof target_clause lit head_name
      in
      let rest_selected =
        match selected_index with
        | Some 0 -> None
        | Some n -> Some (n - 1)
        | None -> None
      in
      let tail_branch =
        simple_clause_remove_reflexive_disequality_proof
          target_prop target_clause rest_selected rest tail_name (depth + 1)
      in
      Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
        source_proof (simple_prop_arg target_prop)
        head_name head_branch
        tail_name tail_branch

let rec simple_clause_remove_truth_conflict_proof
    target_prop target_clause selected_index source_clause source_proof depth =
  let true_proof = "(fun p:prop => fun H:p => H)" in
  let is_true = function
    | TmH "f__true" | TmH "vampire_true" -> true
    | _ -> false
  in
  let is_false = function
    | TmH "f__false" | TmH "vampire_false" -> true
    | _ -> false
  in
  let selected_branch lit proof =
    match lit with
    | Pos atom ->
        begin match equality_sides atom with
        | Some (left, right) when is_true left && is_false right ->
            Printf.sprintf "((%s (fun X Y:prop => X) %s) %s)"
              proof true_proof (simple_prop_arg target_prop)
        | Some (left, right) when is_false left && is_true right ->
            Printf.sprintf "((%s (fun X Y:prop => Y) %s) %s)"
              proof true_proof (simple_prop_arg target_prop)
        | Some _ ->
            emit_error "truth-conflict selected equality is not true = false"
        | None ->
            emit_error "truth-conflict selected literal is not an equality"
        end
    | Neg _ ->
        emit_error "truth-conflict selected literal is not positive"
  in
  match source_clause with
  | [] -> emit_error "cannot remove a literal from the empty clause"
  | [lit] ->
      begin match selected_index with
      | Some 0 -> selected_branch lit source_proof
      | Some _ -> emit_error "truth-conflict selected index is out of bounds"
      | None -> simple_clause_intro_proof target_clause lit source_proof
      end
  | lit :: rest ->
      let head_name = "Htruth_lit_" ^ string_of_int depth in
      let tail_name = "Htruth_tail_" ^ string_of_int depth in
      let head_branch =
        match selected_index with
        | Some 0 -> selected_branch lit head_name
        | _ -> simple_clause_intro_proof target_clause lit head_name
      in
      let rest_selected =
        match selected_index with
        | Some 0 -> None
        | Some n -> Some (n - 1)
        | None -> None
      in
      let tail_branch =
        simple_clause_remove_truth_conflict_proof
          target_prop target_clause rest_selected rest tail_name (depth + 1)
      in
      Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
        source_proof (simple_prop_arg target_prop)
        head_name head_branch
        tail_name tail_branch

let simple_factor_proof clause_body_prop parent_sorts result_sorts id parent_id left_index right_index result checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  let left = simple_clause_nth id "left" left_index parent_clause in
  let right = simple_clause_nth id "right" right_index parent_clause in
  if left <> right then emit_error (id ^ ": factor literals are not identical");
  let remove_index = if left_index > right_index then left_index else right_index in
  let expected = simple_remove_index id "removed factor" remove_index parent_clause in
  if not (same_clause_multiset expected result) then
    emit_error (id ^ ": simple factor proof expects the result to remove the later duplicate");
  let target = clause_body_prop result in
  let parent_name =
    simple_apply_forall_vars (lookup_simple_name names parent_id) parent_sorts
  in
  simple_wrap_forall_intro result_sorts
    (simple_clause_projection_proof target result parent_clause parent_name 0)

let simple_equality_resolution_proof id parent_id literal_index result parent_sorts result_sorts checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  ignore (simple_clause_nth id "equality-resolution" literal_index parent_clause);
  let target = simple_clause_prop result in
  let parent_name =
    simple_apply_forall_vars (lookup_simple_name names parent_id) parent_sorts
  in
  simple_wrap_forall_intro result_sorts
    (simple_clause_remove_reflexive_disequality_proof
       target result (Some literal_index) parent_clause parent_name 0)

let simple_equality_resolution_clause_proof
    clause_body_prop id parent_id literal_index result parent_sorts result_sorts checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  ignore (simple_clause_nth id "equality-resolution" literal_index parent_clause);
  let target = clause_body_prop result in
  let parent_name =
    simple_apply_forall_vars (lookup_simple_name names parent_id) parent_sorts
  in
  simple_wrap_forall_intro result_sorts
    (simple_clause_remove_reflexive_disequality_proof
       target result (Some literal_index) parent_clause parent_name 0)

let simple_truth_conflict_clause_proof
    clause_body_prop id parent_id literal_index result parent_sorts result_sorts checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  ignore (simple_clause_nth id "truth-conflict" literal_index parent_clause);
  let target = clause_body_prop result in
  let parent_name =
    simple_apply_forall_vars (lookup_simple_name names parent_id) parent_sorts
  in
  simple_wrap_forall_intro result_sorts
    (simple_clause_remove_truth_conflict_proof
       target result (Some literal_index) parent_clause parent_name 0)

let simple_copy_proof id parent_id result checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  if parent_clause <> result then
    emit_error (id ^ ": simple emitter supports only exact clause copies for substitution");
  lookup_simple_name names parent_id

let simple_tm_names tm =
  let rec collect acc = function
    | TmH name -> if List.mem name acc then acc else name :: acc
    | DB _ | Prim _ -> acc
    | TpAp (m, _) -> collect acc m
    | Ap (m, n) -> collect (collect acc m) n
    | Lam (_, body) -> collect acc body
    | Imp (left, right) -> collect (collect acc left) right
    | All (_, body) -> collect acc body
  in
  collect [] tm

let simple_tm_has_db_name tm =
  simple_tm_names tm |> List.exists is_db_ident

let simple_tm_has_unscoped_db_name tm =
  let rec contains under_vlam = function
    | TmH name -> is_db_ident name && not under_vlam
    | DB _ | Prim _ -> false
    | TpAp (body, _) -> contains under_vlam body
    | Ap (TmH "vLAM", body) -> contains true body
    | Ap (left, right) -> contains under_vlam left || contains under_vlam right
    | Lam (_, body) | All (_, body) -> contains under_vlam body
    | Imp (left, right) -> contains under_vlam left || contains under_vlam right
  in
  contains false tm

let simple_clause_has_unscoped_db_name clause =
  List.exists (fun literal -> simple_tm_has_unscoped_db_name (literal_atom literal)) clause

let simple_clause_names clause =
  clause
  |> List.fold_left
       (fun acc literal ->
          List.fold_left
            (fun acc name -> if List.mem name acc then acc else name :: acc)
            acc
            (simple_tm_names (literal_atom literal)))
       []

let simple_clause_vlam_bound_names clause =
  let rec add_name acc name =
    if is_db_ident name && not (List.mem name acc) then name :: acc else acc
  in
  let rec names_under_vlam acc = function
    | TmH name -> add_name acc name
    | DB _ | Prim _ -> acc
    | TpAp (tm, _) -> names_under_vlam acc tm
    | Ap (fn, arg) -> names_under_vlam (names_under_vlam acc fn) arg
    | Lam (_, body) | All (_, body) -> names_under_vlam acc body
    | Imp (left, right) -> names_under_vlam (names_under_vlam acc left) right
  in
  let rec scan acc = function
    | Ap (TmH "vLAM", body) -> names_under_vlam acc body
    | TmH _ | DB _ | Prim _ -> acc
    | TpAp (tm, _) -> scan acc tm
    | Ap (fn, arg) -> scan (scan acc fn) arg
    | Lam (_, body) | All (_, body) -> scan acc body
    | Imp (left, right) -> scan (scan acc left) right
  in
  clause
  |> List.fold_left (fun acc literal -> scan acc (literal_atom literal)) []
  |> List.sort_uniq compare

let simple_tm_vlam_bound_names tm =
  simple_clause_vlam_bound_names [Pos tm]

let simple_clause_contains_vlam clause =
  let rec contains = function
    | TmH "vLAM" -> true
    | TmH _ | DB _ | Prim _ -> false
    | TpAp (tm, _) -> contains tm
    | Ap (fn, arg) -> contains fn || contains arg
    | Lam (_, body) | All (_, body) -> contains body
    | Imp (left, right) -> contains left || contains right
  in
  List.exists (fun literal -> contains (literal_atom literal)) clause

let simple_literal_contains_vlam literal =
  simple_clause_contains_vlam [literal]

let simple_tm_contains_vlam tm =
  simple_clause_contains_vlam [Pos tm]

let simple_quantify_prop variable_sorts prop =
  List.fold_right
    (fun (name, sort) body -> "forall " ^ megalodon_ident name ^ ":" ^ sort ^ ", " ^ body)
    variable_sorts
    prop

let simple_variable_sorts_for_names names available_sorts =
  available_sorts
  |> List.filter (fun (name, _) -> List.mem name names)
  |> List.fold_left
       (fun acc (name, sort) ->
          if List.exists (fun (existing, _) -> existing = name) acc then acc
          else acc @ [(name, sort)])
       []

let simple_unique_variable_sorts sorts =
  List.fold_left
    (fun acc (name, sort) ->
       if List.exists (fun (existing, _) -> existing = name) acc then acc
       else acc @ [(name, sort)])
    []
    sorts

let simple_type_env_with_variables variable_sorts type_env =
  let variable_sorts =
    variable_sorts
    |> List.filter (fun (name, _) -> not (List.mem_assoc name type_env))
  in
  variable_sorts @ type_env

let simple_type_env_with_variable_overrides variable_sorts type_env =
  let variable_names = List.map fst variable_sorts in
  variable_sorts
  @ List.filter (fun (name, _) -> not (List.mem name variable_names)) type_env

let simple_clause_prop_and_sorts_for_step ?(available_sorts=[]) cert id clause =
  match metadata_step_proposition cert id with
  | Some proposition when not (simple_clause_contains_function_alias clause) ->
      (proposition, metadata_step_variable_sort_pairs cert id)
  | None ->
      let prop = simple_with_stable_vlam_names (fun () -> simple_clause_prop clause) in
      let names = simple_clause_names clause in
      let names =
        names
        |> List.filter
             (fun name ->
                not (List.mem_assoc name !simple_function_alias_env))
      in
      let variable_sorts = simple_variable_sorts_for_names names available_sorts in
      (simple_quantify_prop variable_sorts prop, variable_sorts)
  | Some _ ->
      let prop = simple_with_stable_vlam_names (fun () -> simple_clause_prop clause) in
      let names = simple_clause_names clause in
      let names =
        names
        |> List.filter
             (fun name ->
                not (List.mem_assoc name !simple_function_alias_env))
      in
      let variable_sorts = simple_variable_sorts_for_names names available_sorts in
      (simple_quantify_prop variable_sorts prop, variable_sorts)

let simple_clause_prop_for_step ?(available_sorts=[]) cert id clause =
  fst (simple_clause_prop_and_sorts_for_step ~available_sorts cert id clause)

let simple_strip_outer_parens typ =
  let rec loop typ =
    let typ = String.trim typ in
    let len = String.length typ in
    if len >= 2 && typ.[0] = '(' && typ.[len - 1] = ')' then begin
      let depth = ref 0 in
      let balanced_outer = ref true in
      for i = 0 to len - 1 do
        begin match typ.[i] with
        | '(' -> incr depth
        | ')' ->
            decr depth;
            if !depth = 0 && i < len - 1 then balanced_outer := false
        | _ -> ()
        end
      done;
      if !balanced_outer && !depth = 0 then
        loop (String.sub typ 1 (len - 2))
      else typ
    end else typ
  in
  loop typ

let simple_replace_all ~pattern ~replacement text =
  let pattern_len = String.length pattern in
  if pattern_len = 0 then text
  else
    let text_len = String.length text in
    let buf = Buffer.create text_len in
    let rec loop i =
      if i >= text_len then ()
      else if i + pattern_len <= text_len
              && String.sub text i pattern_len = pattern then begin
        Buffer.add_string buf replacement;
        loop (i + pattern_len)
      end else begin
        Buffer.add_char buf text.[i];
        loop (i + 1)
      end
    in
    loop 0;
    Buffer.contents buf

let simple_fix_known_higher_order_binders text =
  text
  |> simple_replace_all
       ~pattern:"In_rec_i ((fun db1:set => fun db0:set => If_i"
       ~replacement:"In_rec_i ((fun db1:set => fun db0:set->set => If_i"
  |> simple_replace_all
       ~pattern:"In_rec_i (fun db1:set => fun db0:set => If_i"
       ~replacement:"In_rec_i (fun db1:set => fun db0:set->set => If_i"

let simple_split_arrow_type typ =
  let typ = simple_strip_outer_parens typ in
  let len = String.length typ in
  let depth = ref 0 in
  let found = ref None in
  let i = ref 0 in
  while !i + 1 < len && !found = None do
    begin match typ.[!i] with
    | '(' -> incr depth
    | ')' -> decr depth
    | '-' when !depth = 0 && typ.[!i + 1] = '>' -> found := Some !i
    | _ -> ()
    end;
    incr i
  done;
  match !found with
  | None -> None
  | Some pos ->
      let left = String.sub typ 0 pos |> simple_strip_outer_parens in
      let right =
        String.sub typ (pos + 2) (len - pos - 2)
        |> simple_strip_outer_parens
      in
      Some (left, right)

let rec simple_arrow_sort_parts typ =
  match simple_split_arrow_type typ with
  | Some (domain, codomain) -> domain :: simple_arrow_sort_parts codomain
  | None -> [simple_strip_outer_parens typ]

let simple_arrow_sort domain codomain =
  let domain =
    match simple_split_arrow_type domain with
    | Some _ -> "(" ^ domain ^ ")"
    | None -> domain
  in
  domain ^ "->" ^ codomain

let simple_binder_sort_expr sort =
  match simple_split_arrow_type sort with
  | Some _ -> "(" ^ sort ^ ")"
  | None -> sort

let simple_symbol_type_env cert =
  let builtins =
    [
      ("False", "prop"); ("True", "prop"); ("or", "prop->prop->prop");
      ("vampire_or", "prop->prop->prop"); ("vampire_and", "prop->prop->prop");
      ("vampire_exists_set", "(set->prop)->prop");
      ("vampire_exists_prop", "(prop->prop)->prop");
      ("vampire_exists_set_prop", "((set->prop)->prop)->prop");
      ("vampire_exists_set_set", "((set->set)->prop)->prop");
      ("vampire_exists_set_set_prop", "((set->set->prop)->prop)->prop");
      ("vampire_false", "prop"); ("vampire_true", "prop");
      ("vampire_eq_prop", "prop->prop->prop");
      ("vampire_eq_prop_to_set", "(prop->set)->(prop->set)->prop");
      ("vampire_eq_prop_to_prop_to_prop", "(prop->prop->prop)->(prop->prop->prop)->prop");
      ("vampire_eq_set_to_set", "(set->set)->(set->set)->prop");
      ("vampire_eq_set_to_prop", "(set->prop)->(set->prop)->prop");
      ("vampire_eq_set_to_set_to_prop", "(set->set->prop)->(set->set->prop)->prop");
      ("vampire_eq_set_to_set_to_set", "(set->set->set)->(set->set->set)->prop");
      ("vampire_eq_lp_set_to_set_rp_to_set", "((set->set)->set)->((set->set)->set)->prop");
      ("vampire_eq_lp_set_to_prop_rp_to_set", "((set->prop)->set)->((set->prop)->set)->prop");
      ("vampire_eq_set_to_lp_set_to_set_rp_to_set", "(set->((set->set)->set))->(set->((set->set)->set))->prop");
      ("vampire_eq_lp_set_to_set_rp_to_set_to_set", "((set->set)->set->set)->((set->set)->set->set)->prop");
      ("vampire_eq_lp_set_to_set_to_set_rp_to_set_to_set", "((set->set->set)->set->set)->((set->set->set)->set->set)->prop");
      ("vampire_eq_set_to_lp_set_to_set_to_set_rp_to_set_to_set", "(set->((set->set->set)->set->set))->(set->((set->set->set)->set->set))->prop");
      ("vPI", "(set->prop)->prop");
      ("f__true", "prop"); ("f__false", "prop")
    ]
  in
  let parse_decl decl =
    let line = String.trim decl in
    if not (string_starts_with "Variable " line) then None
    else
      let body =
        String.sub line 9 (String.length line - 9)
        |> String.trim
      in
      match String.index_opt body ':' with
      | None -> None
      | Some colon ->
          let name = String.sub body 0 colon |> String.trim |> megalodon_ident in
          let typ =
            String.sub body (colon + 1) (String.length body - colon - 1)
            |> String.trim
          in
          let typ =
            if String.length typ > 0 && typ.[String.length typ - 1] = '.' then
              String.sub typ 0 (String.length typ - 1)
            else typ
          in
          Some (name, simple_strip_outer_parens typ)
  in
  cert.metadata.symbol_declarations
  |> List.filter_map parse_decl
  |> List.rev_append builtins
  |> List.sort_uniq compare

let simple_add_inferred_sort type_env acc name sort =
  let name = megalodon_ident name in
  if List.mem_assoc name type_env then acc
  else if List.exists (fun (existing, existing_sort) -> existing = name && existing_sort = sort) acc then acc
  else acc @ [(name, sort)]

let simple_infer_tm_variable_sorts ?expected type_env tm =
  let rec known_sort local_env = function
    | TmH name -> List.assoc_opt (megalodon_ident name) local_env
    | DB _ | Prim _ -> None
    | TpAp (fn, _) -> known_sort local_env fn
    | Ap (TmH "vLAM", _) as tm -> simple_lambda_sort tm
    | Ap (fn, _) ->
        begin match Option.bind (known_sort local_env fn) simple_split_arrow_type with
        | Some (_, codomain) -> Some codomain
        | None -> None
        end
    | Lam _ | Imp _ | All _ -> None
  in
  let rec infer local_env expected acc tm =
    match equality_sides tm with
    | Some (left, right) ->
        let left_sort = known_sort local_env left in
        let right_sort = known_sort local_env right in
        let _, acc = infer local_env right_sort acc left in
        let _, acc = infer local_env left_sort acc right in
        (Some "prop", acc)
    | None ->
    match tm with
    | TmH name ->
        let name = megalodon_ident name in
        let known = List.assoc_opt name local_env in
        let sort = match known with Some sort -> Some sort | None -> expected in
        let acc =
          match expected, known with
          | Some sort, None -> simple_add_inferred_sort local_env acc name sort
          | _ -> acc
        in
        (sort, acc)
    | DB _ | Prim _ -> (expected, acc)
    | TpAp (fn, _) -> infer local_env expected acc fn
    | Ap (fn, arg) ->
        let fn_sort, acc = infer local_env None acc fn in
        let domain, codomain =
          match Option.bind fn_sort simple_split_arrow_type with
          | Some (domain, codomain) -> (Some domain, Some codomain)
          | None -> (None, None)
        in
        let arg_sort, acc = infer local_env domain acc arg in
        let acc =
          match fn, fn_sort, domain, arg_sort, expected with
          | TmH name, None, None, Some domain, Some codomain ->
              simple_add_inferred_sort local_env acc name (domain ^ "->" ^ codomain)
          | _ -> acc
        in
        let result_sort = match codomain with Some _ -> codomain | None -> expected in
        (result_sort, acc)
    | Lam (_, body) ->
        let _, acc = infer local_env None acc body in
        (expected, acc)
    | Imp (left, right) ->
        let _, acc = infer local_env (Some "prop") acc left in
        let _, acc = infer local_env (Some "prop") acc right in
        (Some "prop", acc)
    | All (tp, body) ->
        let sort = simple_tp_expr tp in
        let local_env =
          match preferred_formula_binder_name sort body with
          | Some name when List.assoc_opt (megalodon_ident name) local_env = Some sort ->
              (megalodon_ident name, sort) :: local_env
          | _ ->
              let candidates =
                local_env
                |> List.filter
                     (fun (name, known_sort) ->
                        known_sort = sort
                        && is_vampire_var_name name
                        && tm_contains_symbol name body)
              in
              begin match candidates with
              | (name, _) :: _ -> (name, sort) :: local_env
              | [] ->
              begin match max_vampire_var_name body with
              | Some name -> (megalodon_ident name, sort) :: local_env
              | None -> local_env
              end
              end
        in
        let _, acc = infer local_env (Some "prop") acc body in
        (Some "prop", acc)
  in
  snd (infer type_env expected [] tm)

let rec simple_tm_sort type_env = function
  | TmH name -> List.assoc_opt (megalodon_ident name) type_env
  | DB _ | Prim _ -> None
  | TpAp (fn, _) -> simple_tm_sort type_env fn
  | Ap (TmH "vLAM", _) as tm -> simple_lambda_sort tm
  | Ap (fn, _) ->
      begin match Option.bind (simple_tm_sort type_env fn) simple_split_arrow_type with
      | Some (_, codomain) -> Some codomain
      | None -> None
      end
  | Lam _ | Imp _ | All _ -> None

let simple_infer_literal_variable_sorts type_env = function
  | Pos atom | Neg atom ->
      begin match equality_sides atom with
      | Some (left, right) ->
          let left_sort = simple_tm_sort type_env left in
          let right_sort = simple_tm_sort type_env right in
          simple_infer_tm_variable_sorts ?expected:right_sort type_env left
          @ simple_infer_tm_variable_sorts ?expected:left_sort type_env right
          |> simple_unique_variable_sorts
      | None -> simple_infer_tm_variable_sorts ~expected:"prop" type_env atom
      end

let simple_infer_clause_variable_sorts type_env clause =
  clause
  |> List.concat_map (simple_infer_literal_variable_sorts type_env)
  |> simple_unique_variable_sorts

let rec simple_tm_expr_with_expected type_env expected tm =
  match simple_bool_const_prop tm with
  | Some name -> name
  | None ->
      begin match expected, equality_sides tm with
      | Some "prop", Some (left, right) ->
          if is_vampire_bool_const left || is_vampire_bool_const right then
            simple_prop_equality left right
          else
            let left_expected = simple_tm_sort type_env right in
            let right_expected = simple_tm_sort type_env left in
            let left_text = simple_tm_expr_with_expected type_env left_expected left in
            let right_text = simple_tm_expr_with_expected type_env right_expected right in
            left_text ^ " = " ^ right_text
      | _ ->
      begin match tm with
      | Ap (TmH "vLAM", body) ->
          simple_vlam_expr_with_expected type_env expected body
      | Ap (fn, arg) ->
          let head, args = flatten_value_application tm in
          let arg_sorts = List.map (simple_tm_sort type_env) args in
          let all_arg_sorts =
            List.fold_right
              (fun sort acc ->
                 match sort, acc with
                 | Some sort, Some sorts -> Some (sort :: sorts)
                 | _ -> None)
              arg_sorts
              (Some [])
          in
          begin match head, expected, all_arg_sorts with
          | Ap (TmH "vLAM", _), Some result_sort, Some arg_sorts ->
              let head_expected =
                List.fold_right simple_arrow_sort arg_sorts result_sort
              in
              let head_text =
                "(" ^ simple_tm_expr_with_expected type_env (Some head_expected) head ^ ")"
              in
              let arg_texts =
                List.map2
                  (fun arg sort ->
                     match arg with
                     | TmH raw when List.mem_assoc raw !simple_function_alias_env ->
                         "(" ^ simple_tm_expr_with_expected type_env (Some sort) arg ^ ")"
                     | TmH _ | DB _ -> simple_tm_expr_with_expected type_env (Some sort) arg
                     | _ -> "(" ^ simple_tm_expr_with_expected type_env (Some sort) arg ^ ")")
                  args
                  arg_sorts
              in
              String.concat " " (head_text :: arg_texts)
          | _ ->
              let fn_sort = simple_tm_sort type_env fn in
              let domain, codomain =
                match Option.bind fn_sort simple_split_arrow_type with
                | Some (domain, codomain) -> (Some domain, Some codomain)
                | None -> (simple_tm_sort type_env arg, None)
              in
              let fn_expected =
                match fn_sort, domain with
                | None, Some domain ->
                    Some (simple_arrow_sort domain (match expected with Some sort -> sort | None -> "set"))
                | _ -> None
              in
              let fn_text =
                match fn with
                | TmH _ | DB _ -> simple_tm_expr_with_expected type_env fn_expected fn
                | _ -> "(" ^ simple_tm_expr_with_expected type_env fn_expected fn ^ ")"
              in
              let arg_text =
                match arg with
                | TmH raw when List.mem_assoc raw !simple_function_alias_env ->
                    "(" ^ simple_tm_expr_with_expected type_env domain arg ^ ")"
                | TmH _ | DB _ -> simple_tm_expr_with_expected type_env domain arg
                | _ -> "(" ^ simple_tm_expr_with_expected type_env domain arg ^ ")"
              in
              ignore codomain;
              fn_text ^ " " ^ arg_text
          end
      | _ -> simple_tm_expr tm
      end
      end

and simple_vlam_expr_with_expected type_env expected body =
  let expected =
    match expected with
    | Some _ -> expected
    | None -> simple_lambda_sort (Ap (TmH "vLAM", body))
  in
  let rec collect sorts expected body =
    match Option.bind expected simple_split_arrow_type with
    | Some (domain, codomain) ->
        begin match body with
        | Ap (TmH "vLAM", nested) -> collect (sorts @ [domain]) (Some codomain) nested
        | _ -> (sorts @ [domain], Some codomain, body)
        end
    | None -> emit_error "typed vLAM rendering requires an arrow expected type"
  in
  match expected with
  | None -> simple_vlam_expr body
  | Some _ ->
	      begin match
	        try Some (collect [] expected body)
	        with Error _ -> None
      with
      | None -> simple_vlam_expr body
      | Some (sorts, final_expected, body) ->
          let arity = List.length sorts in
          let rec binders n acc =
            if n <= 0 then acc else binders (n - 1) (acc @ [simple_fresh_vlam_name ()])
          in
          let binders = binders arity [] in
          let body_type_env = List.combine binders sorts @ type_env in
          let body_text =
            simple_with_db_aliases (List.rev binders)
              (fun () -> simple_tm_expr_with_expected body_type_env final_expected body)
          in
          "("
          ^ String.concat " => "
              ((List.combine sorts binders
                |> List.map (fun (sort, name) -> "fun " ^ name ^ ":" ^ simple_binder_sort_expr sort))
               @ [body_text])
          ^ ")"
      end

let simple_equality_symbol_for_sort sort =
  match simple_strip_outer_parens sort with
  | "prop" -> Some "vampire_eq_prop"
  | "set->set" -> Some "vampire_eq_set_to_set"
  | "set->prop" -> Some "vampire_eq_set_to_prop"
  | "set->set->prop" -> Some "vampire_eq_set_to_set_to_prop"
  | "set->set->set" -> Some "vampire_eq_set_to_set_to_set"
  | "(set->set)->set" -> Some "vampire_eq_lp_set_to_set_rp_to_set"
  | "(set->prop)->set" -> Some "vampire_eq_lp_set_to_prop_rp_to_set"
  | "set->((set->set)->set)"
  | "set->(set->set)->set" -> Some "vampire_eq_set_to_lp_set_to_set_rp_to_set"
  | "(set->set)->set->set" -> Some "vampire_eq_lp_set_to_set_rp_to_set_to_set"
  | "(set->set->set)->set->set" -> Some "vampire_eq_lp_set_to_set_to_set_rp_to_set_to_set"
  | "set->((set->set->set)->set->set)"
  | "set->(set->set->set)->set->set" ->
      Some "vampire_eq_set_to_lp_set_to_set_to_set_rp_to_set_to_set"
  | _ -> None

let simple_equality_prop_with_type_env type_env left right =
  let left_expected = simple_tm_sort type_env right in
  let right_expected = simple_tm_sort type_env left in
  let left_text = simple_tm_expr_with_expected type_env left_expected left in
  let right_text = simple_tm_expr_with_expected type_env right_expected right in
  match left_expected, right_expected with
  | Some "set", _ | _, Some "set" -> left_text ^ " = " ^ right_text
  | Some sort, _ | _, Some sort ->
      begin match simple_equality_symbol_for_sort sort with
      | Some equality -> equality ^ " (" ^ left_text ^ ") (" ^ right_text ^ ")"
      | None -> left_text ^ " = " ^ right_text
      end
  | None, None -> left_text ^ " = " ^ right_text

let rec simple_formula_like_prop_with_type_env type_env tm =
  let rec render used type_env tm =
    match tm with
    | All (tp, body) ->
      let sort = simple_tp_expr tp in
      let binder =
        let candidates =
          type_env
          |> List.filter
               (fun (name, known_sort) ->
                  known_sort = sort
                  && is_vampire_var_name name
                  && not (List.mem name used)
                  && tm_contains_symbol name body)
        in
        match candidates with
        | (name, _) :: _ -> megalodon_ident name
        | [] ->
            match preferred_formula_binder_name sort body with
            | Some name
                when not (List.mem name used)
                     && List.assoc_opt name type_env = Some sort ->
                megalodon_ident name
            | _ ->
            begin match max_vampire_var_name body with
            | Some name when not (List.mem (megalodon_ident name) used) ->
                megalodon_ident name
            | None -> "Xformula"
            | Some _ -> "Xformula"
            end
      in
      "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
      ^ render (binder :: used) ((binder, sort) :: type_env) body
    | Imp (left, right) ->
      "(" ^ render used type_env left ^ " -> " ^ render used type_env right ^ ")"
    | Ap (Ap (TmH "vampire_and", left), right) ->
      "vampire_and (" ^ render used type_env left ^ ") ("
      ^ render used type_env right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
      "vampire_or (" ^ render used type_env left ^ ") ("
      ^ render used type_env right ^ ")"
    | Ap (exists_head, Lam (tp, body))
      when exists_head = TmH "vampire_exists_prop"
           || exists_head = TmH "vampire_exists_set" ->
      let sort = simple_tp_expr tp in
      let exists_name =
        match sort with
        | "set" -> "vampire_exists_set"
        | "prop" -> "vampire_exists_prop"
        | "set->prop" -> "vampire_exists_set_prop"
        | "set->set" -> "vampire_exists_set_set"
        | "set->set->prop" -> "vampire_exists_set_set_prop"
        | _ -> "vampire_exists_set"
      in
      let binder =
        let candidates =
          type_env
          |> List.filter
               (fun (name, known_sort) ->
                  known_sort = sort
                  && is_vampire_var_name name
                  && not (List.mem name used)
                  && tm_contains_symbol name body)
        in
        match candidates with
        | (name, _) :: _ -> megalodon_ident name
        | [] ->
            match preferred_formula_binder_name sort body with
            | Some name
                when not (List.mem name used)
                     && List.assoc_opt name type_env = Some sort ->
                megalodon_ident name
            | _ ->
            begin match max_vampire_var_name body with
            | Some name when not (List.mem (megalodon_ident name) used) ->
                megalodon_ident name
            | None -> "Xformula"
            | Some _ -> "Xformula"
            end
      in
      exists_name ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
      ^ render (binder :: used) ((binder, sort) :: type_env) body ^ ")"
    | atom -> simple_atom_prop_with_type_env type_env atom
  in
  render [] type_env tm

and simple_atom_prop_with_type_env type_env atom =
  match equality_sides atom with
  | Some (left, right) when is_vampire_bool_const left || is_vampire_bool_const right ->
      simple_prop_equality left right
  | Some (left, right) -> simple_equality_prop_with_type_env type_env left right
  | None -> simple_tm_expr_with_expected type_env (Some "prop") atom

let simple_literal_prop_with_type_env type_env = function
  | Pos atom -> simple_formula_like_prop_with_type_env type_env atom
  | Neg atom -> "(" ^ simple_formula_like_prop_with_type_env type_env atom ^ " -> False)"

let rec simple_clause_prop_with_type_env type_env = function
  | [] -> "False"
  | [lit] -> simple_literal_prop_with_type_env type_env lit
  | lit :: rest ->
      "(" ^ simple_literal_prop_with_type_env type_env lit
      ^ " \\/ "
      ^ simple_clause_prop_with_type_env type_env rest
      ^ ")"

let simple_clause_map_selected_literal_proof
    type_env selected_index source_clause target_clause source_proof map_selected =
  let prop lit = simple_literal_prop_with_type_env type_env lit in
  match source_clause, target_clause, selected_index with
  | [a; b; c; d; e; f; g], [a'; b'; c'; d'; e2; f'; g'], 4
      when a = a' && b = b' && c = c' && d = d' && f = f' && g = g' ->
      begin match e, e2 with
      | Pos source_atom, Pos target_atom ->
          begin match equality_sides source_atom, equality_sides target_atom with
          | Some (left, right), Some (target_left, target_right)
              when target_left = right && target_right = left
                   && not (is_vampire_bool_const left)
                   && not (is_vampire_bool_const right)
                   &&
                   (match simple_tm_sort type_env left, simple_tm_sort type_env right with
                    | Some sort, _ | _, Some sort -> simple_strip_outer_parens sort = "set"
                    | None, None -> true) ->
              let left_text = simple_tm_expr_with_expected type_env (Some "set") left in
              let right_text = simple_tm_expr_with_expected type_env (Some "set") right in
              Printf.sprintf
                "(vampire_or_eqsym5_7_set (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) %s)"
                (prop a) (prop b) (prop c) (prop d) (prop f) (prop g)
                left_text right_text source_proof
          | _ ->
              let selected_name = "Hmap_selected_4" in
              Printf.sprintf
                "(vampire_or_map5_7 (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) (fun %s:%s => %s) %s)"
                (prop a) (prop b) (prop c) (prop d) (prop e) (prop f) (prop g) (prop e2)
                selected_name (prop e)
                (map_selected e e2 selected_name)
                source_proof
          end
      | _ ->
          let selected_name = "Hmap_selected_4" in
          Printf.sprintf
            "(vampire_or_map5_7 (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) (fun %s:%s => %s) %s)"
            (prop a) (prop b) (prop c) (prop d) (prop e) (prop f) (prop g) (prop e2)
            selected_name (prop e)
            (map_selected e e2 selected_name)
            source_proof
      end
  | [a; b; c; d; e; f; g; h], [a'; b'; c'; d'; e2; f'; g'; h'], 4
      when a = a' && b = b' && c = c' && d = d' && f = f' && g = g' && h = h' ->
      let selected_name = "Hmap_selected_4" in
      Printf.sprintf
        "(vampire_or_map5_8 (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) (fun %s:%s => %s) %s)"
        (prop a) (prop b) (prop c) (prop d) (prop e) (prop f) (prop g) (prop h) (prop e2)
        selected_name (prop e)
        (map_selected e e2 selected_name)
        source_proof
  | [a; b; c; d; e; f; g; h], [a'; b'; c'; d'; e'; f2; g'; h'], 5
      when a = a' && b = b' && c = c' && d = d' && e = e' && g = g' && h = h' ->
      let selected_name = "Hmap_selected_5" in
      Printf.sprintf
        "(vampire_or_map6_8 (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) (fun %s:%s => %s) %s)"
        (prop a) (prop b) (prop c) (prop d) (prop e) (prop f) (prop g) (prop h) (prop f2)
        selected_name (prop f)
        (map_selected f f2 selected_name)
        source_proof
  | _ ->
  let rec go index source target proof =
    match source, target with
    | [], [] -> emit_error "cannot map a selected literal in an empty clause"
    | [src], [tgt] ->
        if index = selected_index then map_selected src tgt proof
        else if src = tgt then proof
        else emit_error "clause literal map found a non-selected mismatch"
    | src :: source_rest, tgt :: target_rest ->
        let src_text = simple_literal_prop_with_type_env type_env src in
        let source_rest_text = simple_clause_prop_with_type_env type_env source_rest in
        let tgt_text = simple_literal_prop_with_type_env type_env tgt in
        let target_rest_text = simple_clause_prop_with_type_env type_env target_rest in
        let head_name = "Hmap_lit_" ^ string_of_int index in
        let tail_name = "Hmap_tail_" ^ string_of_int index in
        let head_map =
          if index = selected_index then
            Printf.sprintf "(fun %s:%s => %s)"
              head_name src_text (map_selected src tgt head_name)
          else if src = tgt then
            Printf.sprintf "(fun %s:%s => %s)" head_name src_text head_name
          else
            emit_error "clause literal map found a non-selected head mismatch"
        in
        let tail_map =
          if selected_index > index then
            Printf.sprintf "(fun %s:%s => %s)"
              tail_name source_rest_text
              (go (index + 1) source_rest target_rest tail_name)
          else if source_rest = target_rest then
            Printf.sprintf "(fun %s:%s => %s)"
              tail_name source_rest_text tail_name
          else
            emit_error "clause literal map found a non-selected tail mismatch"
        in
        Printf.sprintf "(vampire_or_map (%s) (%s) (%s) (%s) %s %s %s)"
          src_text source_rest_text tgt_text target_rest_text
          head_map tail_map proof
    | _ ->
        emit_error "clause literal map source and target lengths differ"
  in
  go 0 source_clause target_clause source_proof

let rec simple_clause_formula_tm = function
  | [] -> vampire_false
  | [lit] -> formula_tm_of_literal lit
  | lit :: rest -> vampire_or (formula_tm_of_literal lit) (simple_clause_formula_tm rest)

let simple_clause_formula_prop_with_type_env type_env clause =
  simple_formula_like_prop_with_type_env type_env (simple_clause_formula_tm clause)

let rec simple_formula_clause_projection_proof type_env target_prop target_clause source_formula source_proof depth =
  match source_formula with
  | Ap (Ap (TmH "vampire_or", left), right) ->
      let left_name = "Hformula_lit_" ^ string_of_int depth in
      let right_name = "Hformula_tail_" ^ string_of_int depth in
      let left_branch =
        simple_formula_clause_projection_proof
          type_env target_prop target_clause left left_name (depth + 1)
      in
      let right_branch =
        simple_formula_clause_projection_proof
          type_env target_prop target_clause right right_name (depth + 1)
      in
      Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
        source_proof (simple_prop_arg target_prop)
        left_name left_branch
        right_name right_branch
  | atom ->
      simple_clause_intro_proof target_clause (literal_of_formula_tm atom) source_proof

let simple_literal_equality_symmetry_proof type_env source_literal proof =
  let sym_helper left right source_proof =
    if is_vampire_bool_const left || is_vampire_bool_const right then
      let left_text = simple_tm_expr_with_expected type_env (Some "prop") left in
      let right_text = simple_tm_expr_with_expected type_env (Some "prop") right in
      "vampire_eq_prop_sym (" ^ left_text ^ ") (" ^ right_text ^ ") " ^ source_proof
    else
      let sort =
        match simple_tm_sort type_env left, simple_tm_sort type_env right with
        | Some sort, _ | _, Some sort -> simple_strip_outer_parens sort
        | None, None -> "set"
      in
      match sort with
      | "set" ->
          let left_text = simple_tm_expr_with_expected type_env (Some "set") left in
          let right_text = simple_tm_expr_with_expected type_env (Some "set") right in
          "vampire_eq_set_sym (" ^ left_text ^ ") (" ^ right_text ^ ") " ^ source_proof
      | "prop" ->
          let left_text = simple_tm_expr_with_expected type_env (Some "prop") left in
          let right_text = simple_tm_expr_with_expected type_env (Some "prop") right in
          "vampire_eq_prop_sym (" ^ left_text ^ ") (" ^ right_text ^ ") " ^ source_proof
      | _ ->
          emit_error ("simple equality-symmetry does not support equality at sort " ^ sort)
  in
  match source_literal with
  | Pos atom ->
      begin match equality_sides atom with
      | Some (left, right) -> sym_helper left right proof
      | None -> emit_error "simple equality-symmetry literal is not an equality"
      end
  | Neg atom ->
      begin match equality_sides atom with
      | Some (left, right) ->
          "(fun Hswapped_eq => " ^ proof ^ " ("
          ^ sym_helper right left "Hswapped_eq"
          ^ "))"
      | None -> emit_error "simple equality-symmetry literal is not an equality"
      end

let simple_paramodulate_unit_proof
    clause_body_prop type_env id equality_parent_id target_parent_id equality_index target_index position
    from_tm to_tm result equality_sorts target_sorts result_sorts checked names =
  let equality_clause = lookup_simple_clause checked equality_parent_id in
  let target_clause = lookup_simple_clause checked target_parent_id in
  let equality_literal = simple_clause_nth id "paramodulation equality" equality_index equality_clause in
  let target_literal = simple_clause_nth id "paramodulation target" target_index target_clause in
  let equality_rest = simple_remove_index id "paramodulation equality" equality_index equality_clause in
  let target_rest = simple_remove_index id "paramodulation target" target_index target_clause in
  let equality_atom =
    match equality_literal with
    | Pos atom -> atom
    | Neg _ -> emit_error (id ^ ": paramodulation equality literal is not positive")
  in
  let left, right =
    match equality_sides equality_atom with
    | Some sides -> sides
    | None -> emit_error (id ^ ": paramodulation equality literal is not an equality")
  in
  let target_atom = literal_atom target_literal in
  let rewrite_position =
    let rec select = function
      | [] -> emit_error (id ^ ": paramodulation position does not contain from term")
      | candidate :: rest ->
          begin match try_tm_at_position target_atom candidate with
          | Some found when found = from_tm -> candidate
          | _ -> select rest
          end
    in
    select (paramodulation_position_candidates target_atom position)
  in
  let rewritten_atom = replace_tm_at_position target_atom rewrite_position to_tm (id ^ " target") in
  let rewritten_literal = replace_literal_atom target_literal rewritten_atom in
  let expected = equality_rest @ target_rest @ [rewritten_literal] in
  let result_literal, result_literal_needs_symmetry =
    if same_clause_multiset expected result then
      rewritten_literal, false
    else
      match swap_literal_equality rewritten_literal with
      | Some swapped_literal
          when same_clause_multiset (equality_rest @ target_rest @ [swapped_literal]) result ->
          swapped_literal, true
      | _ ->
          emit_error
            (id ^ ": simple paramodulation proof expects target rest plus the rewritten literal")
  in
  let sort =
    match simple_tm_sort type_env from_tm, simple_tm_sort type_env to_tm with
    | Some sort, _ | _, Some sort -> simple_strip_outer_parens sort
    | None, None -> emit_error (id ^ ": cannot infer paramodulation rewrite sort")
  in
  let equality_expr =
    simple_apply_forall_result_vars_or_witnesses
      (lookup_simple_name names equality_parent_id)
      result_sorts
      equality_sorts
  in
  let target_expr =
    simple_apply_forall_result_vars_or_witnesses
      (lookup_simple_name names target_parent_id)
      result_sorts
      target_sorts
  in
  let rewrite_selected_proof equality_lit_proof target_lit_proof =
    if sort = "prop" then begin
      let left_is_from = left = from_tm && right = to_tm in
      let right_is_from = right = from_tm && left = to_tm in
      if not (left_is_from || right_is_from) then
        emit_error (id ^ ": paramodulation from/to terms do not match equality literal");
      let left_var = "vpm_left" in
      let right_var = "vpm_right" in
      let replacement = TmH (if left_is_from then left_var else right_var) in
      let ctx_atom = replace_tm_at_position target_atom rewrite_position replacement (id ^ " context") in
      let ctx_literal = replace_literal_atom target_literal ctx_atom in
      let ctx_type_env = (left_var, "prop") :: (right_var, "prop") :: type_env in
      let ctx_prop = simple_literal_prop_with_type_env ctx_type_env ctx_literal in
      let ctx =
        "(fun " ^ left_var ^ ":prop"
        ^ " => fun " ^ right_var ^ ":prop"
        ^ " => " ^ ctx_prop ^ ")"
      in
      Printf.sprintf "(%s %s %s)" equality_lit_proof ctx target_lit_proof
    end else begin
      let left_is_from = left = from_tm && right = to_tm in
      let right_is_from = right = from_tm && left = to_tm in
      if not (left_is_from || right_is_from) then
        emit_error (id ^ ": paramodulation from/to terms do not match equality literal");
      let left_var = "vpm_left" in
      let right_var = "vpm_right" in
      let replacement = TmH (if left_is_from then left_var else right_var) in
      let ctx_atom = replace_tm_at_position target_atom rewrite_position replacement (id ^ " context") in
      let ctx_literal = replace_literal_atom target_literal ctx_atom in
      let ctx_type_env = (left_var, sort) :: (right_var, sort) :: type_env in
      let ctx_prop = simple_literal_prop_with_type_env ctx_type_env ctx_literal in
      let binder_sort = simple_binder_sort_expr sort in
      let ctx =
        "(fun " ^ left_var ^ ":" ^ binder_sort
        ^ " => fun " ^ right_var ^ ":" ^ binder_sort
        ^ " => " ^ ctx_prop ^ ")"
      in
      Printf.sprintf "(%s %s %s)" equality_lit_proof ctx target_lit_proof
    end
  in
  let result_literal_proof equality_lit_proof target_lit_proof =
    let direct_proof = rewrite_selected_proof equality_lit_proof target_lit_proof in
    if result_literal_needs_symmetry then
      "(" ^ simple_literal_equality_symmetry_proof type_env rewritten_literal direct_proof ^ ")"
    else
      direct_proof
  in
	  let target_prop = clause_body_prop result in
	  let rec consume_target equality_lit_proof selected_index source_clause source_proof depth =
	    match source_clause with
	    | [] -> emit_error "cannot paramodulate from the empty clause"
    | [lit] ->
        begin match selected_index with
        | Some 0 ->
            simple_clause_intro_proof result result_literal
              (result_literal_proof equality_lit_proof source_proof)
        | Some _ -> emit_error "paramodulation selected target index is out of bounds"
        | None -> simple_clause_intro_proof result lit source_proof
        end
    | lit :: rest ->
        let head_name = "Hparamod_lit_" ^ string_of_int depth in
        let tail_name = "Hparamod_tail_" ^ string_of_int depth in
        let head_branch =
          match selected_index with
          | Some 0 ->
              simple_clause_intro_proof result result_literal
                (result_literal_proof equality_lit_proof head_name)
          | _ -> simple_clause_intro_proof result lit head_name
        in
	        let rest_selected =
	          match selected_index with
	          | Some 0 -> None
	          | Some n -> Some (n - 1)
	          | None -> None
	        in
	        let tail_branch =
	          consume_target equality_lit_proof rest_selected rest tail_name (depth + 1)
	        in
	        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
	          source_proof (simple_prop_arg target_prop)
	          head_name head_branch
	          tail_name tail_branch
	  in
	  let rec consume_equality selected_index source_clause source_proof depth =
	    match source_clause with
	    | [] -> emit_error "cannot paramodulate from an empty equality clause"
	    | [lit] ->
	        begin match selected_index with
	        | Some 0 -> consume_target source_proof (Some target_index) target_clause target_expr 0
	        | Some _ -> emit_error "paramodulation equality index is out of bounds"
	        | None -> simple_clause_intro_proof result lit source_proof
	        end
    | lit :: rest ->
        let head_name = "Hparamod_eq_lit_" ^ string_of_int depth in
        let tail_name = "Hparamod_eq_tail_" ^ string_of_int depth in
	        let head_branch =
	          match selected_index with
	          | Some 0 -> consume_target head_name (Some target_index) target_clause target_expr 0
	          | _ -> simple_clause_intro_proof result lit head_name
	        in
        let rest_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
	        in
	        let tail_branch = consume_equality rest_selected rest tail_name (depth + 1) in
	        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
	          source_proof (simple_prop_arg target_prop)
	          head_name head_branch
	          tail_name tail_branch
	  in
	  simple_wrap_forall_intro result_sorts
	    (consume_equality (Some equality_index) equality_clause equality_expr 0)

let simple_paramodulate_unit_split_proof
    clause_body_prop type_env id helper_name equality_parent_id target_parent_id equality_index target_index position
    from_tm to_tm result equality_sorts target_sorts result_sorts checked names =
  let equality_clause = lookup_simple_clause checked equality_parent_id in
  let target_clause = lookup_simple_clause checked target_parent_id in
  let equality_literal = simple_clause_nth id "paramodulation equality" equality_index equality_clause in
  let target_literal = simple_clause_nth id "paramodulation target" target_index target_clause in
  let equality_rest = simple_remove_index id "paramodulation equality" equality_index equality_clause in
  let target_rest = simple_remove_index id "paramodulation target" target_index target_clause in
  let equality_atom =
    match equality_literal with
    | Pos atom -> atom
    | Neg _ -> emit_error (id ^ ": paramodulation equality literal is not positive")
  in
  let left, right =
    match equality_sides equality_atom with
    | Some sides -> sides
    | None -> emit_error (id ^ ": paramodulation equality literal is not an equality")
  in
  let target_atom = literal_atom target_literal in
  let rewrite_position =
    let rec select = function
      | [] -> emit_error (id ^ ": paramodulation position does not contain from term")
      | candidate :: rest ->
          begin match try_tm_at_position target_atom candidate with
          | Some found when found = from_tm -> candidate
          | _ -> select rest
          end
    in
    select (paramodulation_position_candidates target_atom position)
  in
  let rewritten_atom = replace_tm_at_position target_atom rewrite_position to_tm (id ^ " target") in
  let rewritten_literal = replace_literal_atom target_literal rewritten_atom in
  let orient_literal source actual =
    if source = actual then
      Some (actual, fun proof -> proof)
    else
      match swap_literal_equality source with
      | Some swapped when swapped = actual ->
          Some
            (actual,
             fun proof -> "(" ^ simple_literal_equality_symmetry_proof type_env source proof ^ ")")
      | _ -> None
  in
  let rec orient_literals sources actuals =
    match sources, actuals with
    | [], [] -> Some ([], [])
    | source :: sources, actual :: actuals ->
        begin match orient_literal source actual, orient_literals sources actuals with
        | Some (oriented, orient_proof), Some (oriented_rest, orient_proofs) ->
            Some (oriented :: oriented_rest, orient_proof :: orient_proofs)
        | _ -> None
        end
    | _ -> None
  in
  let split_prefix n items =
    let rec loop n prefix rest =
      if n = 0 then Some (List.rev prefix, rest)
      else
        match rest with
        | head :: tail -> loop (n - 1) (head :: prefix) tail
        | [] -> None
    in
    loop n [] items
  in
  let result_literal, result_literal_needs_symmetry, result_layout,
      target_rest, equality_rest, _orient_target_rest_proofs, _orient_equality_rest_proofs =
    let try_suffix lit needs_symmetry =
      match split_prefix (List.length equality_rest) result with
      | Some (actual_equality_rest, rest) ->
          begin match split_prefix (List.length target_rest) rest with
          | Some (actual_target_rest, [actual_lit]) when actual_lit = lit ->
              begin match
                orient_literals equality_rest actual_equality_rest,
                orient_literals target_rest actual_target_rest
              with
              | Some (oriented_equality_rest, orient_equality_rest_proofs),
                Some (oriented_target_rest, orient_target_rest_proofs) ->
                  Some
                    (lit, needs_symmetry, `Suffix,
                     oriented_target_rest, oriented_equality_rest,
                     orient_target_rest_proofs, orient_equality_rest_proofs)
              | _ -> None
              end
          | _ -> None
          end
      | None -> None
    in
    let try_head lit needs_symmetry =
      match result with
      | actual_lit :: rest when actual_lit = lit ->
          begin match split_prefix (List.length target_rest) rest with
          | Some (actual_target_rest, actual_equality_rest)
              when List.length actual_equality_rest = List.length equality_rest ->
              begin match
                orient_literals target_rest actual_target_rest,
                orient_literals equality_rest actual_equality_rest
              with
              | Some (oriented_target_rest, orient_target_rest_proofs),
                Some (oriented_equality_rest, orient_equality_rest_proofs) ->
                  Some
                    (lit, needs_symmetry, `Head,
                     oriented_target_rest, oriented_equality_rest,
                     orient_target_rest_proofs, orient_equality_rest_proofs)
              | _ -> None
              end
          | _ -> None
          end
      | _ -> None
    in
    match try_suffix rewritten_literal false with
    | Some result -> result
    | None ->
    match try_head rewritten_literal false with
    | Some result -> result
    | None ->
    match swap_literal_equality rewritten_literal with
    | Some swapped_literal ->
        begin match try_suffix swapped_literal true with
        | Some result -> result
        | None ->
        match try_head swapped_literal true with
        | Some result -> result
        | None -> emit_error (id ^ ": split paramodulation requires a supported result order")
        end
    | None -> emit_error (id ^ ": split paramodulation requires a supported result order")
  in
  let target_result_clause = target_rest @ [result_literal] in
  let simple_clause_intro_oriented target_clause lit proof =
    if List.exists ((=) lit) target_clause then
      simple_clause_intro_proof target_clause lit proof
    else
      match swap_literal_equality lit with
      | Some swapped when List.exists ((=) swapped) target_clause ->
          simple_clause_intro_proof target_clause swapped
            ("(" ^ simple_literal_equality_symmetry_proof type_env lit proof ^ ")")
      | _ -> simple_clause_intro_proof target_clause lit proof
  in
  begin match result_layout with
  | `Suffix ->
      if result <> equality_rest @ target_result_clause then
        emit_error (id ^ ": split paramodulation target result is not a suffix")
  | `Head -> ()
  end;
  let sort =
    match simple_tm_sort type_env from_tm, simple_tm_sort type_env to_tm with
    | Some sort, _ | _, Some sort -> simple_strip_outer_parens sort
    | None, None -> emit_error (id ^ ": cannot infer paramodulation rewrite sort")
  in
  let target_expr =
    simple_apply_forall_result_vars_or_witnesses
      (lookup_simple_name names target_parent_id)
      result_sorts
      target_sorts
  in
  let rewrite_selected_proof equality_lit_proof target_lit_proof =
    if sort = "prop" then begin
      let left_is_from = left = from_tm && right = to_tm in
      let right_is_from = right = from_tm && left = to_tm in
      if not (left_is_from || right_is_from) then
        emit_error (id ^ ": paramodulation from/to terms do not match equality literal");
      let left_var = "vpm_left" in
      let right_var = "vpm_right" in
      let replacement = TmH (if left_is_from then left_var else right_var) in
      let ctx_atom = replace_tm_at_position target_atom rewrite_position replacement (id ^ " context") in
      let ctx_literal = replace_literal_atom target_literal ctx_atom in
      let ctx_type_env = (left_var, "prop") :: (right_var, "prop") :: type_env in
      let ctx_prop = simple_literal_prop_with_type_env ctx_type_env ctx_literal in
      let ctx =
        "(fun " ^ left_var ^ ":prop"
        ^ " => fun " ^ right_var ^ ":prop"
        ^ " => " ^ ctx_prop ^ ")"
      in
      Printf.sprintf "(%s %s %s)" equality_lit_proof ctx target_lit_proof
    end else begin
      let left_is_from = left = from_tm && right = to_tm in
      let right_is_from = right = from_tm && left = to_tm in
      if not (left_is_from || right_is_from) then
        emit_error (id ^ ": paramodulation from/to terms do not match equality literal");
      let left_var = "vpm_left" in
      let right_var = "vpm_right" in
      let replacement = TmH (if left_is_from then left_var else right_var) in
      let ctx_atom = replace_tm_at_position target_atom rewrite_position replacement (id ^ " context") in
      let ctx_literal = replace_literal_atom target_literal ctx_atom in
      let ctx_type_env = (left_var, sort) :: (right_var, sort) :: type_env in
      let ctx_prop = simple_literal_prop_with_type_env ctx_type_env ctx_literal in
      let binder_sort = simple_binder_sort_expr sort in
      let ctx =
        "(fun " ^ left_var ^ ":" ^ binder_sort
        ^ " => fun " ^ right_var ^ ":" ^ binder_sort
        ^ " => " ^ ctx_prop ^ ")"
      in
      Printf.sprintf "(%s %s %s)" equality_lit_proof ctx target_lit_proof
    end
  in
  let result_literal_proof equality_lit_proof target_lit_proof =
    let direct_proof = rewrite_selected_proof equality_lit_proof target_lit_proof in
    if result_literal_needs_symmetry then
      "(" ^ simple_literal_equality_symmetry_proof type_env rewritten_literal direct_proof ^ ")"
    else
      direct_proof
  in
  let target_result_prop = clause_body_prop target_result_clause in
  let equality_literal_prop = simple_literal_prop_with_type_env type_env equality_literal in
  let rotate6_target_proof equality_lit_proof source_proof =
    match target_clause, target_result_clause, target_index with
    | [selected; b; c; d; e; f], [b'; c'; d'; e'; f'; g], 0
        when selected = target_literal
             && b = b' && c = c' && d = d' && e = e' && f = f'
             && g = result_literal ->
        let selected_name = "Hparamod_selected" in
        let prop lit = simple_literal_prop_with_type_env type_env lit in
        Some
          (Printf.sprintf
             "(vampire_or_rotate6 (%s) (%s) (%s) (%s) (%s) (%s) (%s) (fun %s:%s => %s) %s)"
             (prop selected) (prop b) (prop c) (prop d) (prop e) (prop f) (prop g)
             selected_name (prop selected)
             (result_literal_proof equality_lit_proof selected_name)
             source_proof)
    | _ -> None
  in
  let rec consume_target equality_lit_proof selected_index source_clause source_proof depth =
    match source_clause with
    | [] -> emit_error "cannot paramodulate from the empty clause"
    | [lit] ->
        begin match selected_index with
        | Some 0 ->
            simple_clause_intro_proof target_result_clause result_literal
              (result_literal_proof equality_lit_proof source_proof)
        | Some _ -> emit_error "paramodulation selected target index is out of bounds"
        | None -> simple_clause_intro_oriented target_result_clause lit source_proof
        end
    | lit :: rest ->
        let head_name = "Hparamod_lit_" ^ string_of_int depth in
        let tail_name = "Hparamod_tail_" ^ string_of_int depth in
        let head_branch =
          match selected_index with
          | Some 0 ->
              simple_clause_intro_proof target_result_clause result_literal
                (result_literal_proof equality_lit_proof head_name)
          | _ -> simple_clause_intro_oriented target_result_clause lit head_name
        in
        let rest_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch =
          consume_target equality_lit_proof rest_selected rest tail_name (depth + 1)
        in
        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
          source_proof (simple_prop_arg target_result_prop)
          head_name head_branch
          tail_name tail_branch
  in
  let helper_prop =
    simple_quantify_prop result_sorts
      ("(" ^ equality_literal_prop ^ " -> " ^ target_result_prop ^ ")")
  in
  let script_binder_prefix () =
    let binders =
      result_sorts
      |> List.map (fun (name, _) -> megalodon_ident name)
      |> String.concat " "
    in
    if binders = "" then "" else "let " ^ binders ^ ". "
  in
  let target_result_injection_script index proof =
    if index < 0 || index >= List.length target_result_clause then
      emit_error (id ^ ": target result injection index is out of bounds");
    let rights =
      List.init index (fun _ -> "apply vampire_or_intro_right.")
      |> String.concat " "
    in
    let left =
      if index < List.length target_result_clause - 1 then
        " apply vampire_or_intro_left."
      else
        ""
    in
    String.trim (rights ^ left ^ " exact " ^ proof ^ ".")
  in
  let target_result_oriented_proof index lit proof =
    match List.nth_opt target_result_clause index with
    | None -> emit_error (id ^ ": target result literal index is out of bounds")
    | Some actual ->
        begin match orient_literal lit actual with
        | Some (_, orient_proof) -> orient_proof proof
        | None -> emit_error (id ^ ": target result literal orientation mismatch")
        end
  in
  let target_result_index source_index =
    if source_index = target_index then
      List.length target_rest
    else if source_index < target_index then
      source_index
    else
      source_index - 1
  in
  let target_clause_script () =
    if List.length target_clause < 5 then
      None
    else
      let bullet depth =
        match depth mod 3 with
        | 0 -> "-"
        | 1 -> "+"
        | _ -> "*"
      in
      let branch_proof index lit assumption =
        if index = target_index then
          target_result_injection_script
            (target_result_index index)
            (result_literal_proof "Hparamod_eq" assumption)
        else
          let result_index = target_result_index index in
          target_result_injection_script
            result_index
            (target_result_oriented_proof result_index lit assumption)
      in
      let rec cases depth index clause proof_name =
        match clause with
        | [] -> emit_error (id ^ ": cannot script paramodulation over an empty target clause")
        | [lit] -> branch_proof index lit proof_name
        | lit :: rest ->
            let head_name = "Hparamod_lit_" ^ string_of_int index in
            let tail_name = "Hparamod_tail_" ^ string_of_int index in
            let marker = bullet depth in
            let head_line =
              marker ^ " assume " ^ head_name ^ ". "
              ^ branch_proof index lit head_name
            in
            let tail_body =
              match rest with
              | [tail_lit] -> branch_proof (index + 1) tail_lit tail_name
              | _ ->
                  "apply " ^ tail_name ^ ".\n"
                  ^ cases (depth + 1) (index + 1) rest tail_name
            in
            head_line ^ "\n"
            ^ marker ^ " assume " ^ tail_name ^ ". " ^ tail_body
      in
      Some
        ("__SCRIPT__"
         ^ script_binder_prefix ()
         ^ "assume Hparamod_eq. "
         ^ "apply (" ^ target_expr ^ " " ^ simple_prop_arg target_result_prop ^ ").\n"
         ^ cases 0 0 target_clause target_expr)
  in
  let helper_proof =
    match target_clause_script () with
    | Some script -> script
    | None ->
        let target_body =
          match rotate6_target_proof "Hparamod_eq" target_expr with
          | Some proof -> proof
          | None ->
              consume_target "Hparamod_eq" (Some target_index) target_clause target_expr 0
        in
        simple_wrap_forall_intro result_sorts
          ("(fun Hparamod_eq:" ^ simple_prop_arg equality_literal_prop ^ " => "
           ^ target_body
           ^ ")")
  in
  let helper_expr =
    simple_apply_forall_vars helper_name result_sorts
  in
  let target_prop = clause_body_prop result in
  let introduce_target_result proof =
    match result_layout with
    | `Suffix -> simple_clause_suffix_intro_proof result target_result_clause proof
    | `Head ->
        begin match target_rest, equality_rest with
        | [a; b; c; d; e], [g] ->
            let prop lit = simple_literal_prop_with_type_env type_env lit in
            Printf.sprintf
              "(vampire_or_rotate_last_first6_extend (%s) (%s) (%s) (%s) (%s) (%s) (%s) %s)"
              (prop a) (prop b) (prop c) (prop d) (prop e)
              (prop result_literal) (prop g) proof
        | _ ->
            simple_clause_projection_proof target_prop result target_result_clause proof 0
        end
  in
  let fast_suffix_equality source_clause source_proof =
    match result_layout, source_clause, target_result_clause with
    | `Suffix, [eq_lit; suffix_lit], [a; b; c; d; e; f]
        when eq_lit = equality_literal && [suffix_lit] = equality_rest ->
        let prop lit = simple_literal_prop_with_type_env type_env lit in
        let equality_lit_name = "Hparamod_eq_lit_fast" in
        Some
          (Printf.sprintf
             "(vampire_or_paramod_suffix7 (%s) (%s) (%s) (%s) (%s) (%s) (%s) (%s) (fun %s:%s => (%s %s)) %s)"
             equality_literal_prop (prop suffix_lit)
             (prop a) (prop b) (prop c) (prop d) (prop e) (prop f)
             equality_lit_name equality_literal_prop helper_expr equality_lit_name
             source_proof)
    | _ -> None
  in
  let rec consume_equality selected_index source_clause source_proof depth =
    match selected_index, fast_suffix_equality source_clause source_proof with
    | Some 0, Some proof -> proof
    | _ ->
    match source_clause with
    | [] -> emit_error "cannot paramodulate from an empty equality clause"
	    | [lit] ->
	        begin match selected_index with
        | Some 0 ->
            introduce_target_result ("(" ^ helper_expr ^ " " ^ source_proof ^ ")")
        | Some _ -> emit_error "paramodulation equality index is out of bounds"
        | None -> simple_clause_intro_oriented result lit source_proof
        end
    | lit :: rest ->
        let head_name = "Hparamod_eq_lit_" ^ string_of_int depth in
        let tail_name = "Hparamod_eq_tail_" ^ string_of_int depth in
        let head_branch =
          match selected_index with
          | Some 0 ->
              introduce_target_result ("(" ^ helper_expr ^ " " ^ head_name ^ ")")
          | _ -> simple_clause_intro_oriented result lit head_name
        in
        let rest_selected =
          match selected_index with
          | Some 0 -> None
          | Some n -> Some (n - 1)
          | None -> None
        in
        let tail_branch = consume_equality rest_selected rest tail_name (depth + 1) in
        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
          source_proof (simple_prop_arg target_prop)
          head_name head_branch
          tail_name tail_branch
  in
  let final_proof =
    simple_wrap_forall_intro result_sorts
      (consume_equality (Some equality_index) equality_clause
         (simple_apply_forall_result_vars_or_witnesses
            (lookup_simple_name names equality_parent_id)
            result_sorts
            equality_sorts)
         0)
  in
  let helper_claim_proof =
    if string_starts_with "__SCRIPT__" helper_proof then
      String.sub helper_proof 10 (String.length helper_proof - 10)
    else
      "exact " ^ helper_proof ^ "."
  in
  ([(helper_name, helper_prop, helper_claim_proof)], final_proof)

let simple_substitute_proof
    ?(formula_parent=false)
    clause_body_prop type_env id parent_id subst result parent_sorts result_sorts checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  let substituted_parent = subst_clause subst parent_clause in
  if not (same_clause_multiset substituted_parent result) then
    emit_error (id ^ ": simple substitution proof expects the explicit substituted parent clause");
  let subst_sources = List.map fst subst in
  if not
       (List.for_all
          (fun source_name ->
             List.exists (fun (name, _) -> name = source_name) parent_sorts)
          subst_sources) then
    emit_error (id ^ ": simple substitution proof only instantiates quantified parent variables");
  let arg_for_parent_var (name, sort) =
    let tm =
      match List.assoc_opt name subst with
      | Some tm -> tm
      | None -> TmH name
    in
    let text = simple_tm_expr_with_expected type_env (Some sort) tm in
    match tm with
    | TmH _ | DB _ -> text
    | _ -> "(" ^ text ^ ")"
  in
  let parent_expr =
    List.fold_left
      (fun acc parent_sort -> "(" ^ acc ^ " " ^ arg_for_parent_var parent_sort ^ ")")
      (lookup_simple_name names parent_id)
      parent_sorts
  in
  let simple_formula_parent_projection_script source_formula target_prop =
    let source_items = collect_binary "vampire_or" source_formula in
    let target_items = List.map formula_tm_of_literal result in
    let source_is_left_assoc5 =
      match source_formula with
      | Ap (Ap (TmH "vampire_or",
                Ap (Ap (TmH "vampire_or",
                        Ap (Ap (TmH "vampire_or",
                                Ap (Ap (TmH "vampire_or", _), _)), _)), _)), _) ->
          true
      | _ -> false
    in
    if source_is_left_assoc5
       && List.length source_items = 5
       && source_items = target_items then
      let binders =
        result_sorts
        |> List.map (fun (name, _) -> megalodon_ident name)
        |> String.concat " "
      in
      let let_prefix =
        if binders = "" then "" else "let " ^ binders ^ ". "
      in
      Some
        ("__SCRIPT__"
         ^ let_prefix
         ^ "apply vampire_or_left5_to_right5. exact "
         ^ parent_expr
         ^ ".")
    else
      None
  in
  let target = clause_body_prop result in
  let proof =
    if formula_parent then
      let source_formula =
        substituted_parent
        |> simple_clause_formula_tm
        |> left_assoc_vampire_or_formula
      in
      begin match simple_formula_parent_projection_script source_formula target with
      | Some script -> script
      | None ->
          simple_formula_clause_projection_proof
            type_env target result source_formula parent_expr 0
      end
    else if substituted_parent = result then
      parent_expr
    else
      match simple_clause_projection_script target result substituted_parent parent_expr result_sorts with
      | Some script -> script
      | None -> simple_clause_projection_proof target result substituted_parent parent_expr 0
  in
  if string_starts_with "__SCRIPT__" proof then proof
  else simple_wrap_forall_intro result_sorts proof

let simple_substituted_parent_expr type_env subst parent_sorts parent_name =
  let subst_sources = List.map fst subst in
  if not
       (List.for_all
          (fun source_name ->
             List.exists (fun (name, _) -> name = source_name) parent_sorts)
          subst_sources) then
    emit_error "substitution proof only instantiates quantified parent variables";
  let arg_for_parent_var (name, sort) =
    let tm =
      match List.assoc_opt name subst with
      | Some tm -> tm
      | None -> TmH name
    in
    let text = simple_tm_expr_with_expected type_env (Some sort) tm in
    match tm with
    | TmH _ | DB _ -> text
    | _ -> "(" ^ text ^ ")"
  in
  List.fold_left
    (fun acc parent_sort -> "(" ^ acc ^ " " ^ arg_for_parent_var parent_sort ^ ")")
    parent_name
    parent_sorts

let simple_condensation_clause_proof
    clause_body_prop type_env id parent_id subst result parent_sorts result_sorts checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  let substituted_parent = subst_clause subst parent_clause in
  let expected = unique_clause substituted_parent in
  if expected <> result then
    emit_error (id ^ ": simple condensation proof expects the duplicate-collapsed substituted parent clause");
  if List.length expected >= List.length parent_clause then
    emit_error (id ^ ": simple condensation proof expects at least one duplicate literal removal");
  let parent_expr =
    simple_substituted_parent_expr
      type_env subst parent_sorts (lookup_simple_name names parent_id)
  in
  let target = clause_body_prop result in
  simple_wrap_forall_intro result_sorts
    (simple_clause_projection_proof target result substituted_parent parent_expr 0)

let simple_condensation_proof id parent_id subst result checked names =
  if subst <> [] then
    emit_error (id ^ ": simple emitter does not support term-changing condensation");
  let parent_clause = lookup_simple_clause checked parent_id in
  match parent_clause, result with
  | [a; b], [res] when a = b && a = res ->
      let target = simple_literal_prop res in
      let target_arg = simple_prop_arg target in
      let parent_name = lookup_simple_name names parent_id in
      Printf.sprintf "(%s %s (fun Hlit_0 => Hlit_0) (fun Htail_1 => Htail_1))"
        parent_name target_arg
  | _ ->
      emit_error (id ^ ": simple emitter supports only two-literal propositional condensation")

let simple_equality_symmetry_body id parent_id literal_index result checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  let literal = simple_clause_nth id "equality-symmetry" literal_index parent_clause in
  let swapped =
    match swap_literal_equality literal with
    | Some swapped -> swapped
    | None -> emit_error (id ^ ": equality-symmetry literal is not an equality")
  in
  begin match parent_clause, literal, result with
  | [Pos atom], Pos _, [res] when res = swapped ->
      begin match equality_sides atom with
      | Some _ ->
          "symmetry. exact " ^ lookup_simple_name names parent_id ^ "."
      | None -> emit_error (id ^ ": equality-symmetry literal is not an equality")
      end
  | _ ->
      emit_error (id ^ ": simple emitter supports only unit positive equality symmetry")
  end

let simple_equality_symmetry_proof type_env source_literal proof =
  let sym_helper left right source_proof =
    if is_vampire_bool_const left || is_vampire_bool_const right then
      let left_text = simple_tm_expr_with_expected type_env (Some "prop") left in
      let right_text = simple_tm_expr_with_expected type_env (Some "prop") right in
      "vampire_eq_prop_sym (" ^ left_text ^ ") (" ^ right_text ^ ") " ^ source_proof
    else
      let sort =
        match simple_tm_sort type_env left, simple_tm_sort type_env right with
        | Some sort, _ | _, Some sort -> simple_strip_outer_parens sort
        | None, None -> "set"
      in
      match sort with
      | "set" ->
          let left_text = simple_tm_expr_with_expected type_env (Some "set") left in
          let right_text = simple_tm_expr_with_expected type_env (Some "set") right in
          "vampire_eq_set_sym (" ^ left_text ^ ") (" ^ right_text ^ ") " ^ source_proof
      | "prop" ->
          let left_text = simple_tm_expr_with_expected type_env (Some "prop") left in
          let right_text = simple_tm_expr_with_expected type_env (Some "prop") right in
          "vampire_eq_prop_sym (" ^ left_text ^ ") (" ^ right_text ^ ") " ^ source_proof
      | _ ->
          emit_error ("simple equality-symmetry does not support equality at sort " ^ sort)
  in
  match source_literal with
  | Pos atom ->
      begin match equality_sides atom with
      | Some (left, right) -> sym_helper left right proof
      | None -> emit_error "simple equality-symmetry literal is not an equality"
      end
  | Neg atom ->
      begin match equality_sides atom with
      | Some (left, right) ->
          "(fun Hswapped_eq => " ^ proof ^ " ("
          ^ sym_helper right left "Hswapped_eq"
          ^ "))"
      | None -> emit_error "simple equality-symmetry literal is not an equality"
      end

let rec simple_clause_equality_symmetry_proof
    type_env target_prop target_clause selected_index source_clause source_proof depth =
  match source_clause with
  | [] -> emit_error "simple equality-symmetry cannot map an empty source clause"
  | [lit] ->
      begin match selected_index with
      | Some 0 ->
          let swapped =
            match swap_literal_equality lit with
            | Some swapped -> swapped
            | None -> emit_error "simple equality-symmetry literal is not an equality"
          in
          simple_clause_intro_proof
            target_clause swapped
            ("(" ^ simple_equality_symmetry_proof type_env lit source_proof ^ ")")
      | Some _ -> emit_error "simple equality-symmetry selected index is out of bounds"
      | None -> simple_clause_intro_proof target_clause lit source_proof
      end
  | lit :: rest ->
      let head_name = "Hsym_lit_" ^ string_of_int depth in
      let tail_name = "Hsym_tail_" ^ string_of_int depth in
      let head_branch =
        match selected_index with
        | Some 0 ->
            let swapped =
              match swap_literal_equality lit with
              | Some swapped -> swapped
              | None -> emit_error "simple equality-symmetry literal is not an equality"
            in
            simple_clause_intro_proof
              target_clause swapped
              ("(" ^ simple_equality_symmetry_proof type_env lit head_name ^ ")")
        | _ -> simple_clause_intro_proof target_clause lit head_name
      in
      let rest_selected =
        match selected_index with
        | Some 0 -> None
        | Some n -> Some (n - 1)
        | None -> None
      in
      let tail_branch =
        simple_clause_equality_symmetry_proof
          type_env target_prop target_clause rest_selected rest tail_name (depth + 1)
      in
      Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
        source_proof (simple_prop_arg target_prop)
        head_name head_branch
        tail_name tail_branch

let simple_equality_symmetry_clause_proof
    type_env id parent_id literal_index result target_prop parent_sorts result_sorts checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  let literal = simple_clause_nth id "equality-symmetry" literal_index parent_clause in
  let swapped =
    match swap_literal_equality literal with
    | Some swapped -> swapped
    | None -> emit_error (id ^ ": equality-symmetry literal is not an equality")
  in
  let parent_name = lookup_simple_name names parent_id in
  let parent_expr = simple_apply_forall_vars parent_name parent_sorts in
  let script_binder_prefix () =
    let binders =
      result_sorts
      |> List.map (fun (name, _) -> megalodon_ident name)
      |> String.concat " "
    in
    if binders = "" then "" else "let " ^ binders ^ ". "
  in
  let goal_directed_set_eqsym_script () =
    match parent_clause, result, literal_index, literal, swapped with
    | [a; b; c; d; e; f; g], [a'; b'; c'; d'; e2; f'; g'], 4, Pos source_atom, Pos target_atom
        when a = a' && b = b' && c = c' && d = d' && f = f' && g = g' ->
        begin match equality_sides source_atom, equality_sides target_atom with
        | Some (left, right), Some (target_left, target_right)
            when target_left = right && target_right = left
                 && not (is_vampire_bool_const left)
                 && not (is_vampire_bool_const right)
                 &&
                 (match simple_tm_sort type_env left, simple_tm_sort type_env right with
                  | Some sort, _ | _, Some sort -> simple_strip_outer_parens sort = "set"
                  | None, None -> true) ->
            Some
              ("__SCRIPT__" ^ script_binder_prefix ()
               ^ "apply vampire_or_eqsym5_7_set. exact "
               ^ parent_expr
               ^ ".")
        | _ -> None
        end
    | _ -> None
  in
  let goal_directed_map8_eqsym_script () =
    let selected_proof source_lit target_lit assumption =
      if target_lit <> swapped then
        emit_error (id ^ ": equality-symmetry target literal is not the swapped selected literal");
      "(" ^ simple_literal_equality_symmetry_proof type_env source_lit assumption ^ ")"
    in
    let bullet depth =
      match depth mod 3 with
      | 0 -> "-"
      | 1 -> "+"
      | _ -> "*"
    in
    let inject index proof =
      let rights =
        List.init index (fun _ -> "apply vampire_or_intro_right.")
        |> String.concat " "
      in
      let left =
        if index < List.length result - 1 then " apply vampire_or_intro_left." else ""
      in
      String.trim (rights ^ left ^ " exact " ^ proof ^ ".")
    in
    let branch_proof index source_lit target_lit assumption =
      if index = literal_index then
        let converted = selected_proof source_lit target_lit assumption in
        inject index converted
      else begin
        if source_lit <> target_lit then
          emit_error (id ^ ": equality-symmetry map found a non-selected mismatch");
        inject index assumption
      end
    in
    let rec cases depth index source_lits target_lits proof_name =
      match source_lits, target_lits with
      | [], [] -> emit_error (id ^ ": equality-symmetry map cannot project an empty clause")
      | [source_lit], [target_lit] ->
          branch_proof index source_lit target_lit proof_name
      | source_lit :: source_rest, target_lit :: target_rest ->
          let head_name = "Hmap_lit_" ^ string_of_int index in
          let tail_name = "Hmap_tail_" ^ string_of_int index in
          let marker = bullet depth in
          let head_line =
            marker ^ " assume " ^ head_name ^ ". "
            ^ branch_proof index source_lit target_lit head_name
          in
          let tail_body =
            match source_rest, target_rest with
            | [tail_source], [tail_target] ->
                branch_proof (index + 1) tail_source tail_target tail_name
            | _ ->
                "apply " ^ tail_name ^ ".\n"
                ^ cases (depth + 1) (index + 1) source_rest target_rest tail_name
          in
          head_line ^ "\n"
          ^ marker ^ " assume " ^ tail_name ^ ". " ^ tail_body
      | _ -> emit_error (id ^ ": equality-symmetry map source and target lengths differ")
    in
    let script source_lits target_lits =
      "__SCRIPT__" ^ script_binder_prefix ()
      ^ "apply (" ^ parent_expr ^ " " ^ simple_prop_arg target_prop ^ ").\n"
      ^ cases 0 0 source_lits target_lits parent_expr
    in
    match parent_clause, result, literal_index with
    | [a; b; c; d; e; f; g; h], [a'; b'; c'; d'; e2; f'; g'; h'], 4
        when a = a' && b = b' && c = c' && d = d' && f = f' && g = g' && h = h' ->
        Some (script [a; b; c; d; e; f; g; h] [a'; b'; c'; d'; e2; f'; g'; h'])
    | [a; b; c; d; e; f; g; h], [a'; b'; c'; d'; e'; f2; g'; h'], 5
        when a = a' && b = b' && c = c' && d = d' && e = e' && g = g' && h = h' ->
        Some (script [a; b; c; d; e; f; g; h] [a'; b'; c'; d'; e'; f2; g'; h'])
    | _ -> None
  in
  let proof =
    match goal_directed_set_eqsym_script () with
    | Some script -> script
    | None ->
        match goal_directed_map8_eqsym_script () with
        | Some script -> script
        | None ->
            try
              simple_clause_map_selected_literal_proof
                type_env literal_index parent_clause result parent_expr
                (fun source_lit target_lit source_proof ->
                   if target_lit <> swapped then
                     emit_error (id ^ ": equality-symmetry target literal is not the swapped selected literal");
                   "(" ^ simple_literal_equality_symmetry_proof type_env source_lit source_proof ^ ")")
            with Error _ ->
              simple_clause_equality_symmetry_proof
                type_env target_prop result (Some literal_index) parent_clause parent_expr 0
  in
  if string_starts_with "__SCRIPT__" proof then proof
  else simple_wrap_forall_intro result_sorts proof

let simple_prop_term_expr type_env source_atom tm =
  if tm = source_atom then simple_atom_prop_with_type_env type_env source_atom
  else simple_tm_expr_with_expected type_env (Some "prop") tm

let simple_bool_true_tm = function
  | TmH "f__true" | TmH "vampire_true" -> true
  | _ -> false

let simple_fool_eq_to_true source target =
  let source_variants =
    let normalized = vampire_vlam_body_tm source in
    if normalized = source then [source] else [source; normalized]
  in
  let is_source tm = List.exists ((=) tm) source_variants in
  match equality_sides target with
  | Some (left, right) when is_source left && simple_bool_true_tm right ->
      Some (`SourceLeft, left, right)
  | Some (left, right) when is_source right && simple_bool_true_tm left ->
      Some (`SourceRight, left, right)
  | _ -> None

let simple_fool_atom_forward_proof type_env source target proof =
  match simple_fool_eq_to_true source target with
  | Some (`SourceLeft, left, right) ->
      let left_text = simple_prop_term_expr type_env source left in
      ignore (simple_tm_expr_with_expected type_env (Some "prop") right);
      Printf.sprintf "(vampire_fool_prop_to_eq_true (%s) %s)" left_text proof
  | Some (`SourceRight, left, right) ->
      let right_text = simple_prop_term_expr type_env source right in
      ignore (simple_tm_expr_with_expected type_env (Some "prop") left);
      Printf.sprintf "(vampire_fool_prop_to_true_eq (%s) %s)" right_text proof
  | None ->
      if source = target then proof
      else emit_error "FOOL formula atom is not an equality-to-true lifting"

let simple_fool_atom_backward_proof type_env source target proof =
  match simple_fool_eq_to_true source target with
  | Some (`SourceLeft, left, right) ->
      let left_text = simple_prop_term_expr type_env source left in
      ignore (simple_tm_expr_with_expected type_env (Some "prop") right);
      Printf.sprintf "(vampire_fool_eq_true_to_prop (%s) %s)" left_text proof
  | Some (`SourceRight, _, right) ->
      let right_text = simple_prop_term_expr type_env source right in
      Printf.sprintf "(vampire_fool_true_eq_to_prop (%s) %s)" right_text proof
  | None ->
      if source = target then proof
      else emit_error "FOOL formula atom is not an equality-to-true lifting"

let rec simple_tm_contains_all = function
  | All _ -> true
  | TpAp (tm, _) -> simple_tm_contains_all tm
  | Ap (left, right)
  | Imp (left, right) ->
      simple_tm_contains_all left || simple_tm_contains_all right
  | Lam (_, body) -> simple_tm_contains_all body
  | DB _ | TmH _ | Prim _ -> false

let rec simple_fool_prefix_imp_shape source target =
  match source, target with
  | All (source_tp, source_body), All (target_tp, target_body) when source_tp = target_tp ->
      simple_fool_prefix_imp_shape source_body target_body
  | All _, _
  | _, All _ ->
      false
  | Imp (source_left, source_right), Imp (target_left, target_right) ->
      simple_fool_prefix_imp_shape source_left target_left
      && simple_fool_prefix_imp_shape source_right target_right
  | Imp _, _
  | _, Imp _ ->
      false
  | _ ->
      not (simple_tm_contains_all source || simple_tm_contains_all target)
      && (source = target || Option.is_some (simple_fool_eq_to_true source target))

let simple_cnf_and_projection_proof
    type_env parent_sorts target_sorts source target_clause parent_name =
  let source = strip_forall source in
  let target_prop =
    try simple_clause_prop_with_type_env type_env target_clause
    with Error _ -> simple_clause_prop target_clause
  in
  let rec conjuncts = function
    | Ap (Ap (TmH "vampire_and", left), right) ->
        conjuncts left @ conjuncts right
    | tm -> [tm]
  in
  let rec projection tm proof_var target_lit =
    match tm with
    | Ap (Ap (TmH "vampire_and", left), right) ->
        begin match projection left "Hcnf_left" target_lit with
        | Some branch ->
            let left_name = "Hcnf_left" in
            let right_name = "Hcnf_right" in
            Some
              (Printf.sprintf
                 "%s %s (fun %s %s => %s)"
                 proof_var
                 (simple_prop_arg target_prop)
                 left_name right_name branch)
        | None ->
            begin match projection right "Hcnf_right" target_lit with
            | Some branch ->
                let left_name = "Hcnf_left" in
                let right_name = "Hcnf_right" in
                Some
                  (Printf.sprintf
                     "%s %s (fun %s %s => %s)"
                     proof_var
                     (simple_prop_arg target_prop)
                     left_name right_name branch)
            | None -> None
            end
        end
    | atom ->
        let lit = literal_of_formula_tm atom in
        if lit = target_lit then
          Some (simple_clause_intro_proof target_clause lit proof_var)
        else None
  in
  match source with
  | Ap (Ap (TmH "vampire_and", _), _) ->
      let source_proof = simple_apply_forall_vars parent_name parent_sorts in
      let source_conjuncts = conjuncts source in
      let target_lit =
        match target_clause with
        | [lit] when List.exists (fun tm -> literal_of_formula_tm tm = lit) source_conjuncts -> lit
        | _ -> emit_error "CNF conjunction projection target is not a conjunct"
      in
      let branch =
        match projection source source_proof target_lit with
        | Some branch -> branch
        | None -> emit_error "CNF conjunction projection target is not a conjunct"
      in
      simple_wrap_forall_intro target_sorts branch
  | _ ->
      emit_error "CNF conjunction projection supports only vampire_and parents"

let simple_cnf_clause_projection_proof
    type_env parent_sorts target_sorts source target_clause parent_name =
  let source_clauses = cnf_clauses source in
  if not (List.exists (fun source_clause -> same_clause_multiset source_clause target_clause) source_clauses) then
    emit_error "CNF clause projection target is not the source clause multiset";
  let clause_is_subset_of_target source_clause =
    List.for_all
      (fun lit -> List.exists ((=) lit) target_clause)
      source_clause
  in
  let source_prefix_sorts = take_prefix (prefix_forall_count source) parent_sorts in
  let source_proof = simple_apply_forall_vars parent_name source_prefix_sorts in
  let target_prop =
    try simple_clause_prop_with_type_env type_env target_clause
    with Error _ -> simple_clause_prop target_clause
  in
  let cnf_binder_sorts =
    parent_sorts @ target_sorts |> simple_unique_variable_sorts
  in
  let formula_text_binder used env sort body =
    let metadata_candidate () =
      cnf_binder_sorts
      |> List.find_opt
           (fun (name, known_sort) ->
              let binder = megalodon_ident name in
              known_sort = sort
              && is_vampire_var_name binder
              && not (List.mem binder used)
              && tm_contains_symbol binder body)
      |> Option.map (fun (name, _) -> megalodon_ident name)
    in
    match preferred_formula_binder_name sort body with
    | Some name ->
        let binder = megalodon_ident name in
        if is_vampire_var_name binder
           && not (List.mem binder used)
           && tm_contains_symbol binder body
           &&
           (match List.assoc_opt binder (env @ cnf_binder_sorts) with
            | Some known_sort -> known_sort = sort
            | None -> true)
        then binder
        else
          begin match first_unused_vampire_var_name_with_sort env used sort body with
          | Some name -> megalodon_ident name
          | None ->
              begin match metadata_candidate () with
              | Some binder -> binder
              | None ->
                  begin match first_unused_vampire_var_name used body with
                  | Some name -> megalodon_ident name
                  | None -> "Xcnf_text_" ^ string_of_int (List.length used)
                  end
              end
          end
    | None ->
        begin match first_unused_vampire_var_name_with_sort env used sort body with
        | Some name -> megalodon_ident name
        | None ->
            begin match metadata_candidate () with
            | Some binder -> binder
            | None ->
                begin match first_unused_vampire_var_name used body with
                | Some name -> megalodon_ident name
                | None -> "Xcnf_text_" ^ string_of_int (List.length used)
                end
            end
        end
  in
  let rec formula_prop_text used env = function
    | All (tp, body) ->
        let sort = simple_tp_expr tp in
        let binder = formula_text_binder used env sort body in
        "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_prop_text (binder :: used) ((binder, sort) :: env) body)
    | Imp (left, right) ->
        "(" ^ formula_prop_text used env left ^ " -> " ^ formula_prop_text used env right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
        "vampire_or (" ^ formula_prop_text used env left ^ ") (" ^ formula_prop_text used env right ^ ")"
    | Ap (Ap (TmH "vampire_and", left), right) ->
        "vampire_and (" ^ formula_prop_text used env left ^ ") (" ^ formula_prop_text used env right ^ ")"
    | Ap (exists_head, Lam (tp, body))
        when exists_head = TmH "vampire_exists_prop"
             || exists_head = TmH "vampire_exists_set" ->
        let sort = simple_tp_expr tp in
        let exists_name =
          match sort with
          | "set" -> "vampire_exists_set"
          | "prop" -> "vampire_exists_prop"
          | "set->prop" -> "vampire_exists_set_prop"
          | "set->set" -> "vampire_exists_set_set"
          | "set->set->prop" -> "vampire_exists_set_set_prop"
          | _ -> "vampire_exists_set"
        in
        let binder = formula_text_binder used env sort body in
        exists_name ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_prop_text (binder :: used) ((binder, sort) :: env) body)
        ^ ")"
    | atom ->
        begin match equality_sides atom with
        | Some _ -> simple_atom_prop_with_type_env env atom
        | None -> simple_tm_expr_with_expected env (Some "prop") atom
        end
  in
  let choose_binder used sort body =
    let rec contains_outside_nested_forall name = function
      | All _ -> false
      | TpAp (tm, _) -> contains_outside_nested_forall name tm
      | Ap (left, right)
      | Imp (left, right) ->
          contains_outside_nested_forall name left
          || contains_outside_nested_forall name right
      | Lam (_, body) -> contains_outside_nested_forall name body
      | TmH h -> h = name
      | DB _ | Prim _ -> false
    in
    let candidates =
      target_sorts
      |> List.filter
           (fun (name, known_sort) ->
              let binder = megalodon_ident name in
              known_sort = sort
              && not (List.mem binder used)
              && tm_contains_symbol binder body)
    in
    let outside_nested =
      candidates
      |> List.filter
           (fun (name, _) ->
              contains_outside_nested_forall (megalodon_ident name) body)
    in
    match outside_nested with
    | (name, _) :: _ -> megalodon_ident name
    | [] ->
    match candidates with
    | (name, _) :: _ -> megalodon_ident name
    | [] -> emit_error "CNF clause projection could not find a target binder for nested forall"
  in
  let rec project_formula depth used env formula proof =
    match formula with
    | All (tp, body) ->
        let binder = choose_binder used (simple_tp_expr tp) body in
        let sort = simple_tp_expr tp in
        project_formula (depth + 1) (binder :: used) ((binder, sort) :: env)
          body ("(" ^ proof ^ " " ^ binder ^ ")")
    | Ap (Ap (TmH "vampire_and", left), right) ->
        let left_name = "Hcnf_formula_and_left_" ^ string_of_int depth in
        let right_name = "Hcnf_formula_and_right_" ^ string_of_int depth in
        let left_text = formula_prop_text used env left in
        let right_text = formula_prop_text used env right in
        let use_left =
          cnf_clauses left
          |> List.exists clause_is_subset_of_target
        in
        let selected_branch =
          if use_left then project_formula (depth + 1) used env left left_name
          else if
            cnf_clauses right
            |> List.exists clause_is_subset_of_target
          then project_formula (depth + 1) used env right right_name
          else emit_error "CNF conjunction source does not contain target clause"
        in
        Printf.sprintf
          "(%s %s (fun %s:%s => fun %s:%s => %s))"
          proof (simple_prop_arg target_prop)
          left_name left_text right_name right_text selected_branch
    | Ap (Ap (TmH "vampire_or", left), right) ->
        let left_name = "Hcnf_formula_left_" ^ string_of_int depth in
        let right_name = "Hcnf_formula_right_" ^ string_of_int depth in
        let left_branch = project_formula (depth + 1) used env left left_name in
        let right_branch = project_formula (depth + 1) used env right right_name in
        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
          proof (simple_prop_arg target_prop)
          left_name left_branch
          right_name right_branch
    | atom ->
        simple_clause_intro_proof target_clause (literal_of_formula_tm atom) proof
  in
  let used_prefix_binders =
    List.map (fun (name, _) -> megalodon_ident name) source_prefix_sorts
  in
  simple_wrap_forall_intro target_sorts
    (project_formula 0 used_prefix_binders type_env (strip_forall source) source_proof)

let simple_cnf_imp_false_singleton_proof
    parent_sorts target_sorts source target_clause parent_name =
  match strip_forall source, target_clause with
  | Imp (left, right), [Neg atom]
      when is_vampire_false right
           && (left = atom || same_mod_scoped_vampire_var_renaming_and_equality left atom) ->
      simple_wrap_forall_intro target_sorts
        (simple_apply_forall_vars parent_name parent_sorts)
  | _ ->
      emit_error "CNF implication-to-false projection does not match singleton negative clause"

let simple_cnf_literal_proof
    parent_sorts target_sorts source target_clause parent_name =
  let source_clause = [literal_of_formula_tm source] in
  if not (same_clause_multiset source_clause target_clause) then
    emit_error "CNF literal target does not match parent literal";
  simple_wrap_forall_intro target_sorts
    (simple_apply_forall_vars parent_name parent_sorts)

let simple_cnf_literal_clause_parent_proof
    target_prop parent_sorts target_sorts source_clause target_clause parent_name =
  if not (same_clause_multiset source_clause target_clause) then
    emit_error "CNF literal target does not match singleton parent clause";
  let parent_expr = simple_apply_forall_vars parent_name parent_sorts in
  simple_wrap_forall_intro target_sorts
    (simple_clause_projection_proof target_prop target_clause source_clause parent_expr 0)

let simple_fool_formula_proof type_env id parent_sorts result_sorts source target parent_name =
  let binder_sorts =
    parent_sorts @ result_sorts |> simple_unique_variable_sorts
  in
  let binder_index = ref 0 in
  let proof_var_index = ref 0 in
  let fallback_binder sort =
    let name =
      match List.nth_opt binder_sorts !binder_index with
      | Some (name, known_sort) when known_sort = sort ->
          incr binder_index;
        megalodon_ident name
      | Some (name, _) ->
          incr binder_index;
          megalodon_ident name
      | None ->
          let name = "Xfool_" ^ string_of_int !binder_index in
          incr binder_index;
          name
    in
    name
  in
  let fresh_proof_var () =
    let name = "Hfool_arg_" ^ string_of_int !proof_var_index in
    incr proof_var_index;
    name
  in
  let rec convert direction env source target proof =
    match source, target with
    | All (source_tp, source_body), All (target_tp, target_body) when source_tp = target_tp ->
        let sort = simple_tp_expr source_tp in
        ignore target_body;
        let binder = fallback_binder sort in
        let env = (binder, sort) :: env in
        let body_proof = convert direction env source_body target_body ("(" ^ proof ^ " " ^ binder ^ ")") in
          "(fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => " ^ body_proof ^ ")"
    | Imp (source_left, source_right), Imp (target_left, target_right) ->
        begin match direction with
        | `Forward ->
            let arg = fresh_proof_var () in
            let left_source =
              convert `Backward env source_left target_left arg
            in
            let source_right_proof = "(" ^ proof ^ " " ^ left_source ^ ")" in
            let target_right =
              convert `Forward env source_right target_right source_right_proof
            in
            "(fun " ^ arg ^ " => " ^ target_right ^ ")"
        | `Backward ->
            let arg = fresh_proof_var () in
            let left_target =
              convert `Forward env source_left target_left arg
            in
            let target_right_proof = "(" ^ proof ^ " " ^ left_target ^ ")" in
            let source_right =
              convert `Backward env source_right target_right target_right_proof
            in
            "(fun " ^ arg ^ " => " ^ source_right ^ ")"
        end
    | _ ->
        ignore env;
        begin match direction with
        | `Forward -> simple_fool_atom_forward_proof type_env source target proof
        | `Backward -> simple_fool_atom_backward_proof type_env source target proof
        end
  in
  if not (simple_fool_prefix_imp_shape source target) then
    emit_error (id ^ ": FOOL formula proof supports only prefix-universal atomic lifting");
  if not
       (List.exists
          (fun expected -> same_fool_formula_lift expected target)
          (fool_formula_tm_candidates source))
  then
    emit_error (id ^ ": FOOL formula proof target does not match recursive lifting");
  convert `Forward [] source target parent_name

let simple_fool_bool_proof
    type_env parent_sorts result_sorts id parent_literal result_literal names parent_id =
  let parent_name =
    simple_apply_forall_vars (lookup_simple_name names parent_id) parent_sorts
  in
  let source_atom, source_negative =
    match parent_literal with
    | Pos atom -> atom, false
    | Neg atom -> atom, true
  in
  let target_atom, target_negative =
    match result_literal with
    | Pos atom -> atom, false
    | Neg atom -> atom, true
  in
  if source_negative <> target_negative then
    emit_error (id ^ ": FOOL bool replay expected matching literal polarity");
  let left, right =
    match equality_sides target_atom with
    | Some (left, right) -> left, right
    | None -> emit_error (id ^ ": FOOL bool target is not equality-to-true")
  in
  let left_is_source = left = source_atom in
  let right_is_source = right = source_atom in
  let left_is_true = is_vampire_bool_const left && not (is_vampire_false left) in
  let right_is_true = is_vampire_bool_const right && not (is_vampire_false right) in
  if not ((left_is_source && right_is_true) || (left_is_true && right_is_source)) then
    emit_error (id ^ ": FOOL bool target does not wrap the parent atom with true");
  let left_text = simple_prop_term_expr type_env source_atom left in
  let right_text = simple_prop_term_expr type_env source_atom right in
  let source_text = simple_atom_prop_with_type_env type_env source_atom in
  let eq_text = simple_atom_prop_with_type_env type_env target_atom in
  let proof =
    if not source_negative then
      let left_to_right, right_to_left =
        if left_is_source then
          (Printf.sprintf "(fun H:%s => %s)" source_text simple_true_proof,
           Printf.sprintf "(fun H:%s => %s)" right_text parent_name)
        else
          (Printf.sprintf "(fun H:%s => %s)" left_text parent_name,
           Printf.sprintf "(fun H:%s => %s)" source_text simple_true_proof)
      in
      Printf.sprintf "(vampire_eq_prop_ext (%s) (%s) %s %s)"
        left_text right_text left_to_right right_to_left
    else
      let source_from_eq =
        if left_is_source then
          Printf.sprintf "(Heq_fool (fun X Y:prop => Y) %s)"
            simple_true_proof
        else
          Printf.sprintf "(Heq_fool (fun X Y:prop => X) %s)"
            simple_true_proof
      in
      Printf.sprintf "(fun Heq_fool:%s => %s %s)" eq_text parent_name source_from_eq
  in
  simple_wrap_forall_intro result_sorts proof

let simple_fool_exhaustiveness_proof type_env result_sorts id clause =
  let literal_prop lit =
    try simple_literal_prop_with_type_env type_env lit
    with Error _ -> simple_literal_prop lit
  in
  let equality_case lit =
    match lit with
    | Pos atom ->
        begin match equality_sides atom with
        | Some (left, right) when is_vampire_bool_const left && not (is_vampire_false left) ->
            Some (`TrueEq, true, right)
        | Some (left, right) when is_vampire_bool_const right && not (is_vampire_false right) ->
            Some (`TrueEq, false, left)
        | Some (left, right) when is_vampire_false left ->
            Some (`FalseEq, true, right)
        | Some (left, right) when is_vampire_false right ->
            Some (`FalseEq, false, left)
        | _ -> None
        end
    | Neg _ -> None
  in
  let left_lit, right_lit =
    match clause with
    | [left_lit; right_lit] -> left_lit, right_lit
    | _ -> emit_error (id ^ ": FOOL exhaustiveness proof expects exactly two literals")
  in
  let left_prop = literal_prop left_lit in
  let right_prop = literal_prop right_lit in
  let target_prop = "(" ^ left_prop ^ " \\/ " ^ right_prop ^ ")" in
  let left_intro proof =
    Printf.sprintf
      "(fun vfool_goal:prop => fun Hleft:%s -> vfool_goal => fun Hright:%s -> vfool_goal => Hleft %s)"
      left_prop right_prop proof
  in
  let right_intro proof =
    Printf.sprintf
      "(fun vfool_goal:prop => fun Hleft:%s -> vfool_goal => fun Hright:%s -> vfool_goal => Hright %s)"
      left_prop right_prop proof
  in
  let eq_proof lit positive_case_name negative_case_name =
    match equality_case lit with
    | Some (`TrueEq, true, tm) ->
        let tm_text = simple_tm_expr_with_expected type_env (Some "prop") tm in
        Some (tm, Printf.sprintf "(vampire_fool_prop_to_true_eq (%s) %s)" tm_text positive_case_name)
    | Some (`TrueEq, false, tm) ->
        let tm_text = simple_tm_expr_with_expected type_env (Some "prop") tm in
        Some (tm, Printf.sprintf "(vampire_fool_prop_to_eq_true (%s) %s)" tm_text positive_case_name)
    | Some (`FalseEq, true, tm) ->
        let tm_text = simple_tm_expr_with_expected type_env (Some "prop") tm in
        Some (tm, Printf.sprintf "(vampire_fool_not_prop_to_false_eq (%s) %s)" tm_text negative_case_name)
    | Some (`FalseEq, false, tm) ->
        let tm_text = simple_tm_expr_with_expected type_env (Some "prop") tm in
        Some (tm, Printf.sprintf "(vampire_fool_not_prop_to_eq_false (%s) %s)" tm_text negative_case_name)
    | None -> None
  in
  let left_eq = eq_proof left_lit "Hfool_true" "Hfool_false" in
  let right_eq = eq_proof right_lit "Hfool_true" "Hfool_false" in
  let is_true_eq lit =
    match equality_case lit with
    | Some (`TrueEq, _, _) -> true
    | _ -> false
  in
  let is_false_eq lit =
    match equality_case lit with
    | Some (`FalseEq, _, _) -> true
    | _ -> false
  in
  let exhaustiveness_tm =
    match left_eq, right_eq with
    | Some (tm_left, _), Some (tm_right, _) when tm_left = tm_right -> tm_left
    | _ ->
        emit_error
          (id ^ ": FOOL exhaustiveness proof expects true/false equalities for one Boolean term")
  in
  let left_branch =
    match left_eq, right_eq with
    | Some (_, proof), _ when is_true_eq left_lit ->
        left_intro proof
    | _, Some (_, proof) when is_true_eq right_lit ->
        right_intro proof
    | _ -> emit_error (id ^ ": FOOL exhaustiveness proof did not find true branch")
  in
  let right_branch =
    match left_eq, right_eq with
    | Some (_, proof), _ when is_false_eq left_lit ->
        left_intro proof
    | _, Some (_, proof) when is_false_eq right_lit ->
        right_intro proof
    | _ -> emit_error (id ^ ": FOOL exhaustiveness proof did not find false branch")
  in
  let tm_text = simple_tm_expr_with_expected type_env (Some "prop") exhaustiveness_tm in
  let proof =
    Printf.sprintf
      "((vampire_xm (%s)) %s (fun Hfool_true:%s => %s) (fun Hfool_false:%s -> False => %s))"
      tm_text target_prop tm_text left_branch tm_text right_branch
  in
  simple_wrap_forall_intro result_sorts proof

let simple_fool_distinctness_proof type_env result_sorts id clause =
  let literal =
    match clause with
    | [Neg atom] -> atom
    | [_] -> emit_error (id ^ ": FOOL distinctness literal must be negative")
    | _ -> emit_error (id ^ ": FOOL distinctness proof expects a singleton clause")
  in
  let contradiction =
    match equality_sides literal with
    | Some (left, right)
        when (is_vampire_bool_const left && not (is_vampire_false left)
              && is_vampire_false right) ->
        Printf.sprintf
          "(fun Hfool_distinct:%s => Hfool_distinct (fun X Y:prop => X) %s)"
          (simple_atom_prop_with_type_env type_env literal)
          simple_true_proof
    | Some (left, right)
        when (is_vampire_false left
              && is_vampire_bool_const right && not (is_vampire_false right)) ->
        Printf.sprintf
          "(fun Hfool_distinct:%s => Hfool_distinct (fun X Y:prop => Y) %s)"
          (simple_atom_prop_with_type_env type_env literal)
          simple_true_proof
    | Some _ ->
        emit_error (id ^ ": FOOL distinctness proof expected true != false")
    | None ->
        emit_error (id ^ ": FOOL distinctness proof literal is not an equality")
  in
  simple_wrap_forall_intro result_sorts
    (simple_clause_intro_proof clause (Neg literal) contradiction)

let simple_avatar_component_proof type_env split_definitions id result_sorts result =
  let split_literals, component_literals =
    List.partition is_split_literal result
  in
  let split_literal =
    match split_literals with
    | [literal] -> literal
    | [] -> emit_error (id ^ ": avatar component proof expected a split literal")
    | _ -> emit_error (id ^ ": avatar component proof expected exactly one split literal")
  in
  let split_name =
    match split_literal with
    | Pos (TmH name) | Neg (TmH name) -> megalodon_ident name
    | _ -> emit_error (id ^ ": avatar component split literal is not a split atom")
  in
  let raw_target_formula = simple_clause_formula_tm result in
  let target_formula = left_assoc_vampire_or_formula raw_target_formula in
  let rec prop_text = function
    | TmH name when string_starts_with "split_" name -> megalodon_ident name
    | Imp (left, right) ->
        "(" ^ prop_text left ^ " -> " ^ prop_text right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
        "(" ^ prop_text left ^ " \\/ " ^ prop_text right ^ ")"
    | Ap (Ap (TmH "vampire_and", left), right) ->
        "vampire_and (" ^ prop_text left ^ ") (" ^ prop_text right ^ ")"
    | atom ->
        begin match equality_sides atom with
        | Some _ -> simple_atom_prop_with_type_env type_env atom
        | None -> simple_tm_expr_with_expected type_env (Some "prop") atom
        end
  in
  let target_prop = prop_text target_formula in
  let rec formula_contains_literal formula literal =
    formula = formula_tm_of_literal literal
    ||
    match formula with
    | Ap (Ap (TmH "vampire_or", left), right) ->
        formula_contains_literal left literal
        || formula_contains_literal right literal
    | _ -> false
  in
	  let rec formula_intro_proof formula literal proof =
	    if formula = formula_tm_of_literal literal then proof
	    else
      match formula with
      | Ap (Ap (TmH "vampire_or", left), right) ->
          let left_prop = prop_text left in
          let right_prop = prop_text right in
          if formula_contains_literal left literal then
            let left_proof = formula_intro_proof left literal proof in
            Printf.sprintf
              "(fun vavatar_goal:prop => fun Hleft:(%s) -> vavatar_goal => fun Hright:(%s) -> vavatar_goal => Hleft %s)"
              left_prop right_prop left_proof
          else if formula_contains_literal right literal then
            let right_proof = formula_intro_proof right literal proof in
            Printf.sprintf
              "(fun vavatar_goal:prop => fun Hleft:(%s) -> vavatar_goal => fun Hright:(%s) -> vavatar_goal => Hright %s)"
              left_prop right_prop right_proof
          else
            emit_error (id ^ ": avatar component target does not contain literal")
	      | _ -> emit_error (id ^ ": avatar component target is not an or-formula")
	  in
	  let rec formula_intro_script formula literal proof =
	    if formula = formula_tm_of_literal literal then "exact " ^ proof ^ "."
	    else
	      match formula with
	      | Ap (Ap (TmH "vampire_or", left), right) ->
	          if formula_contains_literal left literal then
	            "apply vampire_or_intro_left. "
	            ^ formula_intro_script left literal proof
	          else if formula_contains_literal right literal then
	            "apply vampire_or_intro_right. "
	            ^ formula_intro_script right literal proof
	          else
	            emit_error (id ^ ": avatar component target does not contain literal")
	      | _ -> emit_error (id ^ ": avatar component target is not an or-formula")
	  in
  let rec formula_projection_from_clause source_clause source_proof depth =
    match source_clause with
    | [] -> emit_error (id ^ ": avatar component cannot project from empty body")
    | [lit] -> formula_intro_proof target_formula lit source_proof
    | lit :: rest ->
        let head_name = "Havatar_component_lit_" ^ string_of_int depth in
        let tail_name = "Havatar_component_tail_" ^ string_of_int depth in
        let head_type = prop_text (formula_tm_of_literal lit) in
        let tail_type = prop_text (simple_clause_formula_tm rest) in
        let head_branch = formula_intro_proof target_formula lit head_name in
        let tail_branch =
          formula_projection_from_clause rest tail_name (depth + 1)
        in
        Printf.sprintf
          "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
          source_proof (simple_prop_arg target_prop)
          head_name head_type head_branch
          tail_name tail_type tail_branch
  in
  let orient_target proof =
    if raw_target_formula = target_formula then proof
    else
      match raw_target_formula, target_formula with
      | Ap (Ap (TmH "vampire_or", source_a),
            Ap (Ap (TmH "vampire_or", source_b), source_c)),
        Ap (Ap (TmH "vampire_or",
                Ap (Ap (TmH "vampire_or", target_a), target_b)),
            target_c)
          when source_a = target_a && source_b = target_b && source_c = target_c ->
          let a_text = prop_text target_a in
          let b_text = prop_text target_b in
          let c_text = prop_text target_c in
          let target_left_text = prop_text (vampire_or target_a target_b) in
          let source_tail_text = prop_text (vampire_or source_b source_c) in
          let target_left_from_a =
            Printf.sprintf
              "(fun vavatar_assoc_left_goal:prop => fun Hleft:(%s) -> vavatar_assoc_left_goal => fun Hright:(%s) -> vavatar_assoc_left_goal => Hleft Havatar_assoc_a)"
              a_text b_text
          in
          let target_left_from_b =
            Printf.sprintf
              "(fun vavatar_assoc_left_goal:prop => fun Hleft:(%s) -> vavatar_assoc_left_goal => fun Hright:(%s) -> vavatar_assoc_left_goal => Hright Havatar_assoc_b)"
              a_text b_text
          in
          let target_from_left left_proof =
            Printf.sprintf
              "(fun vavatar_assoc_goal:prop => fun Hleft:(%s) -> vavatar_assoc_goal => fun Hright:(%s) -> vavatar_assoc_goal => Hleft %s)"
              target_left_text c_text left_proof
          in
          let target_from_c =
            Printf.sprintf
              "(fun vavatar_assoc_goal:prop => fun Hleft:(%s) -> vavatar_assoc_goal => fun Hright:(%s) -> vavatar_assoc_goal => Hright Havatar_assoc_c)"
              target_left_text c_text
          in
          Printf.sprintf
            "(%s %s (fun Havatar_assoc_a:%s => %s) (fun Havatar_assoc_tail:(%s) => Havatar_assoc_tail %s (fun Havatar_assoc_b:%s => %s) (fun Havatar_assoc_c:%s => %s)))"
            proof (simple_prop_arg target_prop)
            a_text (target_from_left target_left_from_a)
            source_tail_text (simple_prop_arg target_prop)
            b_text (target_from_left target_left_from_b)
            c_text target_from_c
      | _ -> emit_error (id ^ ": avatar component target association is unsupported")
  in
  let body_clause, body_prop =
    match List.assoc_opt split_name split_definitions with
    | Some (_, body_clause, body_prop) -> body_clause, body_prop
    | None ->
        emit_error (id ^ ": avatar component has no local split definition")
  in
  let prove_from_body proof_name =
    let body_proof =
      List.fold_left
        (fun acc (name, _) -> "(" ^ acc ^ " " ^ megalodon_ident name ^ ")")
        proof_name
        result_sorts
    in
    formula_projection_from_clause body_clause body_proof 0
  in
  let split_prop = prop_text (formula_tm_of_literal split_literal) in
  let target_from_body proof_name =
    prove_from_body proof_name
  in
  let target_from_not_body proof_name =
    formula_intro_proof target_formula split_literal proof_name
  in
	  let proof =
	    match split_literal with
	    | Neg (TmH _) ->
	        begin match body_clause with
	        | [lit0; lit1; lit2; lit3] ->
	            let binders =
	              result_sorts
	              |> List.map (fun (name, _) -> megalodon_ident name)
	              |> String.concat " "
	            in
	            let let_prefix =
	              if binders = "" then "" else "let " ^ binders ^ ". "
	            in
	            let body_instance =
	              List.fold_left
	                (fun acc (name, _) -> "(" ^ acc ^ " " ^ megalodon_ident name ^ ")")
	                "Havatar_body"
	                result_sorts
	            in
	            "__SCRIPT__"
	            ^ let_prefix
	            ^ "apply (vampire_xm "
	            ^ simple_prop_arg body_prop
	            ^ " "
	            ^ simple_prop_arg target_prop
	            ^ ").\n"
	            ^ "- assume Havatar_body. apply ("
	            ^ body_instance
	            ^ " "
	            ^ simple_prop_arg target_prop
	            ^ ").\n"
	            ^ "  + assume Havatar_lit_0. "
	            ^ formula_intro_script target_formula lit0 "Havatar_lit_0"
	            ^ "\n"
	            ^ "  + assume Havatar_tail_0. apply Havatar_tail_0.\n"
	            ^ "    * assume Havatar_lit_1. "
	            ^ formula_intro_script target_formula lit1 "Havatar_lit_1"
	            ^ "\n"
	            ^ "    * assume Havatar_tail_1. apply Havatar_tail_1.\n"
	            ^ "      + assume Havatar_lit_2. "
	            ^ formula_intro_script target_formula lit2 "Havatar_lit_2"
	            ^ "\n"
	            ^ "      + assume Havatar_lit_3. "
	            ^ formula_intro_script target_formula lit3 "Havatar_lit_3"
	            ^ "\n"
	            ^ "- assume Havatar_not_body. "
	            ^ formula_intro_script target_formula split_literal "Havatar_not_body"
	        | _ ->
	            let positive_branch = target_from_body "Havatar_body" in
	            let negative_branch = target_from_not_body "Havatar_not_body" in
	            Printf.sprintf
	              "((vampire_xm (%s)) %s (fun Havatar_body:%s => %s) (fun Havatar_not_body:(%s) -> False => %s))"
	              body_prop target_prop body_prop positive_branch body_prop negative_branch
	        end
    | Pos (TmH _) ->
        begin match component_literals, body_clause with
        | [Neg atom], [Pos body_atom] when atom = body_atom ->
            let component_prop = prop_text (formula_tm_of_literal (Neg atom)) in
            let positive_branch =
              if result = component_literals @ [split_literal] then
                Printf.sprintf
                  "(fun vavatar_goal:prop => fun Hleft:(%s) -> vavatar_goal => fun Hright:(%s) -> vavatar_goal => Hright Havatar_body)"
                  component_prop split_prop
              else
                simple_clause_intro_proof result split_literal "Havatar_body"
                |> orient_target
            in
            let negative_branch =
              if result = component_literals @ [split_literal] then
                Printf.sprintf
                  "(fun vavatar_goal:prop => fun Hleft:(%s) -> vavatar_goal => fun Hright:(%s) -> vavatar_goal => Hleft Havatar_not_body)"
                  component_prop split_prop
              else
                simple_clause_intro_proof result (Neg atom) "Havatar_not_body"
                |> orient_target
            in
            Printf.sprintf
              "((vampire_xm (%s)) %s (fun Havatar_body:%s => %s) (fun Havatar_not_body:(%s) -> False => %s))"
              body_prop target_prop body_prop positive_branch body_prop negative_branch
        | _ ->
            emit_error
              (id ^ ": avatar component positive split proof supports only singleton complements")
        end
    | _ -> emit_error (id ^ ": avatar component split literal is not a split atom")
  in
	  if string_starts_with "__SCRIPT__" proof then proof
	  else simple_wrap_forall_intro result_sorts proof

let simple_clause_projection_with_eliminators target_prop target_clause source_clause source_proof eliminator =
  let false_elim proof =
    Printf.sprintf "(%s %s)" proof (simple_prop_arg target_prop)
  in
  let rec project depth clause proof =
    match clause with
    | [] -> emit_error "cannot project from the empty clause"
    | [lit] ->
        if List.exists ((=) lit) target_clause then
          simple_clause_intro_proof target_clause lit proof
        else
          begin match eliminator lit proof with
          | Some contradiction -> false_elim contradiction
          | None -> emit_error "avatar split projection has an unhandled literal"
          end
    | lit :: rest ->
        let head_name = "Havatar_split_lit_" ^ string_of_int depth in
        let tail_name = "Havatar_split_tail_" ^ string_of_int depth in
        let head_type = simple_literal_prop lit in
        let tail_type = simple_clause_prop rest in
        let head_branch =
          if List.exists ((=) lit) target_clause then
            simple_clause_intro_proof target_clause lit head_name
          else
            begin match eliminator lit head_name with
            | Some contradiction -> false_elim contradiction
            | None ->
                emit_error
                  ("avatar split projection has an unhandled literal "
                   ^ simple_literal_prop lit)
            end
        in
        let tail_branch = project (depth + 1) rest tail_name in
        Printf.sprintf "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
          proof (simple_prop_arg target_prop)
          head_name head_type head_branch
          tail_name tail_type tail_branch
  in
  project 0 source_clause source_proof

let simple_formula_projection_with_eliminators target_prop target_clause source_formula source_proof eliminator =
  let false_elim proof =
    Printf.sprintf "(%s %s)" proof (simple_prop_arg target_prop)
  in
  let rec formula_prop = function
    | TmH name -> simple_name_expr name
    | Imp (left, right) -> "(" ^ formula_prop left ^ " -> " ^ formula_prop right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
        "(" ^ formula_prop left ^ " \\/ " ^ formula_prop right ^ ")"
    | atom -> simple_atom_prop atom
  in
  let rec project depth formula proof =
    match formula with
    | Ap (Ap (TmH "vampire_or", left), right) ->
        let left_name = "Havatar_formula_lit_" ^ string_of_int depth in
        let right_name = "Havatar_formula_tail_" ^ string_of_int depth in
        let left_branch = project (depth + 1) left left_name in
        let right_branch = project (depth + 1) right right_name in
        Printf.sprintf "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
          proof (simple_prop_arg target_prop)
          left_name (formula_prop left) left_branch
          right_name (formula_prop right) right_branch
    | atom ->
        let lit = literal_of_formula_tm atom in
        if List.exists ((=) lit) target_clause then
          simple_clause_intro_proof target_clause lit proof
        else
          begin match eliminator lit proof with
          | Some contradiction -> false_elim contradiction
          | None -> emit_error "avatar formula projection has an unhandled literal"
          end
  in
  project 0 source_formula source_proof

let simple_avatar_split_proof
    type_env split_definitions parent_var_bindings literal_class_bindings id result_sorts parent_id parent_sorts parent_clause result parent_name =
  let raw_target_formula = simple_clause_formula_tm result in
  let target_formula = left_assoc_vampire_or_formula raw_target_formula in
  let rec prop_text = function
    | TmH name when string_starts_with "split_" name -> megalodon_ident name
    | Imp (left, right) ->
        "(" ^ prop_text left ^ " -> " ^ prop_text right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
        "(" ^ prop_text left ^ " \\/ " ^ prop_text right ^ ")"
    | atom -> simple_tm_expr_with_expected type_env (Some "prop") atom
  in
  let target_prop = prop_text target_formula in
  let rec formula_contains_literal formula literal =
    formula = formula_tm_of_literal literal
    ||
    match formula with
    | Ap (Ap (TmH "vampire_or", left), right) ->
        formula_contains_literal left literal
        || formula_contains_literal right literal
    | _ -> false
  in
  let rec formula_intro_proof formula literal proof =
    if formula = formula_tm_of_literal literal then proof
    else
      match formula with
      | Ap (Ap (TmH "vampire_or", left), right) ->
          let left_prop = prop_text left in
          let right_prop = prop_text right in
          if formula_contains_literal left literal then
            let left_proof = formula_intro_proof left literal proof in
            Printf.sprintf
              "(fun vavatar_split_goal:prop => fun Hleft:(%s) -> vavatar_split_goal => fun Hright:(%s) -> vavatar_split_goal => Hleft %s)"
              left_prop right_prop left_proof
          else if formula_contains_literal right literal then
            let right_proof = formula_intro_proof right literal proof in
            Printf.sprintf
              "(fun vavatar_split_goal:prop => fun Hleft:(%s) -> vavatar_split_goal => fun Hright:(%s) -> vavatar_split_goal => Hright %s)"
              left_prop right_prop right_proof
          else
            emit_error (id ^ ": avatar split target does not contain literal")
      | _ -> emit_error (id ^ ": avatar split target is not an or-formula")
  in
  let formula_projection_with_eliminators source_clause source_proof eliminator =
    let false_elim proof =
      Printf.sprintf "(%s %s)" proof (simple_prop_arg target_prop)
    in
    let split_literal_from_source lit =
      let source_prop = prop_text (formula_tm_of_literal lit) in
      literal_class_bindings
      |> List.find_map
           (fun (literal_text, split_name) ->
              if simple_prop_equal_mod_cnf_defs source_prop literal_text then
                let split_lit =
                  match lit with
                  | Pos _ -> Pos (TmH split_name)
                  | Neg _ -> Neg (TmH split_name)
                in
                if formula_contains_literal target_formula split_lit
                   &&
                   match List.assoc_opt split_name split_definitions with
                   | Some (_, _, body_prop) ->
                       not (string_starts_with "forall " (String.trim body_prop))
                   | None -> false then
                  Some split_lit
                else None
              else None)
    in
    let project_source_literal lit proof =
      if formula_contains_literal target_formula lit then
        Some (formula_intro_proof target_formula lit proof)
      else
        match split_literal_from_source lit with
        | Some split_lit -> Some (formula_intro_proof target_formula split_lit proof)
        | None -> None
    in
    let rec project depth clause proof =
      match clause with
      | [] -> emit_error (id ^ ": avatar split cannot project from empty clause")
      | [lit] ->
          begin match project_source_literal lit proof with
          | Some proof -> proof
          | None ->
            begin match eliminator lit proof with
            | Some contradiction -> false_elim contradiction
            | None ->
                emit_error
                  ("avatar split projection has an unhandled literal "
                   ^ prop_text (formula_tm_of_literal lit))
            end
          end
      | lit :: rest ->
          let head_name = "Havatar_split_lit_" ^ string_of_int depth in
          let tail_name = "Havatar_split_tail_" ^ string_of_int depth in
          let head_type = prop_text (formula_tm_of_literal lit) in
          let tail_type = prop_text (simple_clause_formula_tm rest) in
          let head_branch =
            match project_source_literal lit head_name with
            | Some proof -> proof
            | None ->
              begin match eliminator lit head_name with
              | Some contradiction -> false_elim contradiction
              | None ->
                  emit_error
                    ("avatar split projection has an unhandled literal "
                     ^ prop_text (formula_tm_of_literal lit))
              end
          in
          let tail_branch = project (depth + 1) rest tail_name in
          Printf.sprintf "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
            proof (simple_prop_arg target_prop)
            head_name head_type head_branch
            tail_name tail_type tail_branch
    in
    project 0 source_clause source_proof
  in
  let split_name_of_literal = function
    | Pos (TmH name) | Neg (TmH name) when string_starts_with "split_" name ->
        Some (megalodon_ident name)
    | _ -> None
  in
  let split_atom_prop name = name in
  let branch_name prefix split_name =
    prefix ^ "_" ^ split_name
  in
  let lookup_assignment split_name assignments =
    List.find_opt (fun (name, _) -> name = split_name) assignments
  in
  let clause_contains_symbol symbol clause =
    List.exists (fun lit -> tm_contains_symbol symbol (literal_atom lit)) clause
  in
  let split_for_parent_variable name sort assignments =
    if sort <> "prop" then None
    else
      match
        parent_var_bindings
        |> List.find_map
             (fun (parent_var, split_name) ->
                if megalodon_ident parent_var = name
                   && List.exists (fun (assigned, _) -> assigned = split_name) assignments then
                  Some split_name
                else None)
      with
      | Some _ as split_name -> split_name
      | None ->
          split_definitions
          |> List.find_opt
               (fun (split_name, (_, body_clause, _)) ->
                  List.exists (fun (assigned, _) -> assigned = split_name) assignments
                  && clause_contains_symbol name body_clause)
          |> Option.map (fun (split_name, _) -> split_name)
  in
  let contradiction_from_assignment lit lit_proof assignments =
    match lit with
    | Pos (TmH raw_name) | Neg (TmH raw_name)
        when string_starts_with "split_" raw_name ->
        let split_name = megalodon_ident raw_name in
        begin match lit, lookup_assignment split_name assignments with
        | Pos _, Some (_, `False not_name) ->
            Some (Printf.sprintf "(%s %s)" not_name lit_proof)
        | Neg _, Some (_, `True true_name) ->
            Some (Printf.sprintf "(%s %s)" lit_proof true_name)
        | _ -> None
        end
    | Pos atom | Neg atom ->
        let is_true_tm = function
          | TmH "f__true" | TmH "vampire_true" -> true
          | _ -> false
        in
        let direct_prop_split_contradiction () =
          match lit, equality_sides atom with
          | Pos _, Some (left, TmH raw_name) when is_true_tm left && string_starts_with "split_" raw_name ->
              let split_name = megalodon_ident raw_name in
              begin match lookup_assignment split_name assignments with
              | Some (_, `False not_name) ->
                  Some
                    (Printf.sprintf "(%s (vampire_fool_true_eq_to_prop (%s) %s))"
                       not_name split_name lit_proof)
              | _ -> None
              end
          | Pos _, Some (TmH raw_name, right) when is_true_tm right && string_starts_with "split_" raw_name ->
              let split_name = megalodon_ident raw_name in
              begin match lookup_assignment split_name assignments with
              | Some (_, `False not_name) ->
                  Some
                    (Printf.sprintf "(%s (vampire_fool_eq_true_to_prop (%s) %s))"
                       not_name split_name lit_proof)
              | _ -> None
              end
          | _ -> None
        in
        let try_definition (split_name, (_, body_clause, body_prop)) =
          let source_prop = prop_text (formula_tm_of_literal lit) in
          match body_clause, lookup_assignment split_name assignments, lit with
          | [], Some (_, `False not_name), _
              when simple_prop_equal_mod_cnf_defs source_prop body_prop ->
              Some (Printf.sprintf "(%s %s)" not_name lit_proof)
          | [], Some (_, `True true_name), Neg source_atom
              when simple_prop_equal_mod_cnf_defs (prop_text source_atom) body_prop ->
              Some (Printf.sprintf "(%s %s)" lit_proof true_name)
          | [Pos body_atom], Some (_, `False not_name), Pos source_atom
              when source_atom = body_atom ->
              Some (Printf.sprintf "(%s %s)" not_name lit_proof)
          | [Pos body_atom], Some (_, `True true_name), Neg source_atom
              when source_atom = body_atom ->
              Some (Printf.sprintf "(%s %s)" lit_proof true_name)
          | _ -> None
        in
        let rec first = function
          | [] -> None
          | item :: rest ->
              begin match try_definition item with
              | Some proof -> Some proof
              | None -> first rest
              end
        in
        begin match direct_prop_split_contradiction () with
        | Some proof -> Some proof
        | None -> first split_definitions
        end
  in
  let prove_positive_split split_name assignments =
    match List.assoc_opt split_name split_definitions with
    | None -> emit_error (id ^ ": avatar split has no definition for " ^ split_name)
    | Some (_, body_clause, body_prop) ->
        let body_sorts = simple_forall_prefix_sorts body_prop in
        let body_type_env = simple_type_env_with_variables body_sorts type_env in
        let body_target_prop =
          if body_clause = [] then body_prop
          else simple_clause_prop_with_type_env body_type_env body_clause
        in
        let parent_proof, parent_subst =
          List.fold_left
            (fun (proof, subst) (name, sort) ->
               let ident = megalodon_ident name in
               let is_body_binder =
                 List.exists (fun (body_name, _) -> megalodon_ident body_name = ident) body_sorts
               in
               let witness, subst =
                 if is_body_binder then
                   (ident, subst)
                 else
                   match split_for_parent_variable ident sort assignments with
                   | Some split_name -> (split_name, (ident, TmH split_name) :: subst)
                   | None -> (simple_witness_for_sort sort, subst)
               in
               ("(" ^ proof ^ " " ^ witness ^ ")", subst))
            (parent_name, [])
            parent_sorts
        in
        let parent_clause = subst_clause parent_subst parent_clause in
        let eliminator lit proof = contradiction_from_assignment lit proof assignments in
        let body_proof =
          if body_clause = [] then
            let false_elim proof =
              Printf.sprintf "(%s %s)" proof (simple_prop_arg body_target_prop)
            in
            let rec project depth clause proof =
              match clause with
              | [] -> emit_error (id ^ ": avatar split cannot project from empty metadata body")
              | [lit] ->
                  let source_prop = prop_text (formula_tm_of_literal lit) in
                  if simple_prop_equal_mod_cnf_defs source_prop body_target_prop then
                    proof
                  else
                    begin match eliminator lit proof with
                    | Some contradiction -> false_elim contradiction
                    | None ->
                        emit_error
                          ("avatar split metadata-body projection has an unhandled literal "
                           ^ source_prop)
                    end
              | lit :: rest ->
                  let head_name = "Havatar_split_metadata_lit_" ^ string_of_int depth in
                  let tail_name = "Havatar_split_metadata_tail_" ^ string_of_int depth in
                  let source_prop = prop_text (formula_tm_of_literal lit) in
                  let head_branch =
                    if simple_prop_equal_mod_cnf_defs source_prop body_target_prop then
                      head_name
                    else
                      begin match eliminator lit head_name with
                      | Some contradiction -> false_elim contradiction
                      | None ->
                          emit_error
                            ("avatar split metadata-body projection has an unhandled literal "
                             ^ source_prop)
                      end
                  in
                  let tail_branch = project (depth + 1) rest tail_name in
                  Printf.sprintf "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
                    proof (simple_prop_arg body_target_prop)
                    head_name source_prop head_branch
                    tail_name (prop_text (simple_clause_formula_tm rest)) tail_branch
            in
            project 0 parent_clause parent_proof
          else
            simple_clause_projection_with_eliminators
              body_target_prop body_clause parent_clause parent_proof eliminator
        in
        simple_wrap_forall_intro body_sorts body_proof
  in
  let prove_from_contradiction assignments =
    let candidates =
      result
      |> List.filter_map
           (function
             | Pos (TmH raw_name) when string_starts_with "split_" raw_name ->
                 let split_name = megalodon_ident raw_name in
                 begin match lookup_assignment split_name assignments with
                 | Some (_, `False not_name) -> Some (split_name, not_name)
                 | _ -> None
                 end
             | _ -> None)
    in
    let rec try_candidates = function
      | [] -> None
      | (split_name, not_name) :: rest ->
          if not (List.mem_assoc split_name split_definitions) then try_candidates rest
          else
            match
              try Some (prove_positive_split split_name assignments)
              with Error msg ->
                debug_emit_error
                  ("avatar_split " ^ id ^ " candidate " ^ split_name)
                  msg;
                None
            with
            | Some split_proof ->
                Some
                  (Printf.sprintf "((%s %s) %s)"
                     not_name split_proof (simple_prop_arg target_prop))
            | None -> try_candidates rest
    in
    match try_candidates candidates with
    | Some proof -> proof
    | None ->
        let eliminator lit proof = contradiction_from_assignment lit proof assignments in
        formula_projection_with_eliminators parent_clause parent_name eliminator
  in
  let rec cases assignments = function
    | [] -> prove_from_contradiction assignments
    | lit :: rest ->
        begin match split_name_of_literal lit with
        | None -> emit_error (id ^ ": avatar split result contains a non-split literal")
        | Some split_name ->
            let split_prop = split_atom_prop split_name in
            begin match lit with
            | Pos _ ->
                let true_name = branch_name "Havatar_split" split_name in
                let false_name = branch_name "Havatar_not_split" split_name in
                let true_branch =
                  formula_intro_proof target_formula lit true_name
                in
                let false_branch =
                  cases ((split_name, `False false_name) :: assignments) rest
                in
                Printf.sprintf
                  "((vampire_xm (%s)) %s (fun %s:%s => %s) (fun %s:%s -> False => %s))"
                  split_prop target_prop true_name split_prop true_branch
                  false_name split_prop false_branch
            | Neg _ ->
                let true_name = branch_name "Havatar_split" split_name in
                let false_name = branch_name "Havatar_not_split" split_name in
                let true_branch =
                  cases ((split_name, `True true_name) :: assignments) rest
                in
                let false_branch =
                  formula_intro_proof target_formula lit false_name
                in
                Printf.sprintf
                  "((vampire_xm (%s)) %s (fun %s:%s => %s) (fun %s:%s -> False => %s))"
                  split_prop target_prop true_name split_prop true_branch
                  false_name split_prop false_branch
            end
        end
  in
  let direct =
    try
      Some
        (formula_projection_with_eliminators parent_clause parent_name (fun _ _ -> None))
	              with Error msg ->
	                debug_emit_error ("predicate_definition_fold " ^ id) msg;
	                None
  in
  let proof =
    match direct with
    | Some proof -> proof
    | None -> cases [] result
  in
  simple_wrap_forall_intro result_sorts proof

let simple_avatar_refutation_proof cert id parent_ids sat_clauses checked names =
  if parent_ids = [] || List.length parent_ids <> List.length sat_clauses then
    emit_error (id ^ ": avatar refutation proof expects one parent per SAT input");
  let inputs = List.combine parent_ids sat_clauses in
  let vars =
    sat_clauses
    |> List.concat
    |> List.map fst
    |> List.sort_uniq compare
  in
  let split_prop var = "split_" ^ string_of_int var in
  let true_name var = "Hsat_split_" ^ string_of_int var in
  let false_name var = "Hsat_not_split_" ^ string_of_int var in
  let assigned_value assignments var =
    match List.assoc_opt var assignments with
    | Some value -> value
    | None -> emit_error (id ^ ": incomplete SAT assignment in avatar refutation proof")
  in
  let sat_literal_false assignments (var, polarity) =
    assigned_value assignments var <> polarity
  in
  let split_var_of_literal lit = split_literal_number lit in
  let contradiction_from_assignment assignments lit lit_proof =
    match split_var_of_literal lit with
    | None -> None
    | Some var ->
        begin match lit, assigned_value assignments var with
        | Pos _, false ->
            Some (Printf.sprintf "(%s %s)" (false_name var) lit_proof)
        | Neg _, true ->
            Some (Printf.sprintf "(%s %s)" lit_proof (true_name var))
        | _ -> None
        end
  in
  let leaf assignments =
    let falsified =
      List.find_opt
        (fun (_, clause) -> List.for_all (sat_literal_false assignments) clause)
        inputs
    in
    match falsified with
    | None -> emit_error (id ^ ": SAT assignment did not falsify any input clause")
    | Some (parent_id, _) ->
        let parent_clause =
          let clause = lookup_simple_clause checked parent_id in
          match metadata_step_proposition cert parent_id with
          | None -> clause
          | Some parent_prop ->
              let indexed =
                clause
                |> List.mapi
                     (fun index lit ->
                        let position =
                          match split_literal_name lit with
                          | Some raw_name ->
                              string_find_identifier (megalodon_ident raw_name) parent_prop
                          | None -> None
                        in
                        (index, position, lit))
              in
              if List.for_all (fun (_, position, _) -> Option.is_some position) indexed then
                indexed
                |> List.sort
                     (fun (left_index, left_pos, _) (right_index, right_pos, _) ->
                        match left_pos, right_pos with
                        | Some left_pos, Some right_pos ->
                            let cmp = compare left_pos right_pos in
                            if cmp = 0 then compare left_index right_index else cmp
                        | _ -> compare left_index right_index)
                |> List.map (fun (_, _, lit) -> lit)
              else
                clause
        in
        let parent_name = lookup_simple_name names parent_id in
        let eliminator lit proof =
          contradiction_from_assignment assignments lit proof
        in
        let parent_formula =
          parent_clause
          |> simple_clause_formula_tm
          |> left_assoc_vampire_or_formula
        in
        simple_formula_projection_with_eliminators
          "False" [] parent_formula parent_name eliminator
  in
  let rec cases assignments = function
    | [] -> leaf assignments
    | var :: rest ->
        let prop = split_prop var in
        let positive =
          cases ((var, true) :: assignments) rest
        in
        let negative =
          cases ((var, false) :: assignments) rest
        in
        Printf.sprintf
          "((vampire_xm (%s)) False (fun %s:%s => %s) (fun %s:%s -> False => %s))"
          prop (true_name var) prop positive (false_name var) prop negative
  in
  cases [] vars

let simple_literal_of_sat_lit (var, polarity) =
  let atom = TmH ("split_" ^ string_of_int var) in
  if polarity then Pos atom else Neg atom

let simple_clause_of_sat_clause clause =
  List.map simple_literal_of_sat_lit clause

let simple_sat_clause_prop clause =
  simple_clause_prop (simple_clause_of_sat_clause clause)

let simple_sat_lit_prop lit =
  simple_literal_prop (simple_literal_of_sat_lit lit)

let simple_avatar_refutation_sat_proof
    cert id parent_ids sat_clauses proof checked names fresh_name =
  if parent_ids = [] || List.length parent_ids <> List.length sat_clauses then
    emit_error (id ^ ": avatar SAT proof expects one parent per SAT input");
  let input_parents = List.combine parent_ids sat_clauses in
  let normalized clause = normalize_sat_clause clause in
  let parent_for_input clause =
    let key = normalized clause in
    match
      input_parents
      |> List.find_opt (fun (_, parent_clause) -> normalized parent_clause = key)
    with
    | Some (parent_id, parent_clause) -> parent_id, parent_clause
    | None -> emit_error (id ^ ": SAT proof input clause has no AVATAR parent")
  in
  let parent_clause_in_emitted_order parent_id fallback_clause =
    let clause =
      try lookup_simple_clause checked parent_id
      with Error _ -> fallback_clause
    in
    match metadata_step_proposition cert parent_id with
    | None -> clause
    | Some parent_prop ->
        let indexed =
          clause
          |> List.mapi
               (fun index lit ->
                  let position =
                    match split_literal_name lit with
                    | Some raw_name ->
                        string_find_identifier (megalodon_ident raw_name) parent_prop
                    | None -> None
                  in
                  (index, position, lit))
        in
        if List.for_all (fun (_, position, _) -> Option.is_some position) indexed then
          indexed
          |> List.sort
               (fun (left_index, left_pos, _) (right_index, right_pos, _) ->
                  match left_pos, right_pos with
                  | Some left_pos, Some right_pos ->
                      let cmp = compare left_pos right_pos in
                      if cmp = 0 then compare left_index right_index else cmp
                  | _ -> compare left_index right_index)
          |> List.map (fun (_, _, lit) -> lit)
        else
          clause
  in
  let step_name sid =
    fresh_name ("avatar_sat__" ^ id ^ "_" ^ string_of_int sid)
  in
  let literal_contradiction assignments lit proof =
    let var, polarity = lit in
    match List.assoc_opt var assignments with
    | Some (assigned_polarity, assigned_proof) when assigned_polarity <> polarity ->
        if polarity then
          Some (Printf.sprintf "(%s %s)" assigned_proof proof)
        else
          Some (Printf.sprintf "(%s %s)" proof assigned_proof)
    | _ -> None
  in
  let add_assignment lit proof assignments =
    let var, polarity = lit in
    match List.assoc_opt var assignments with
    | Some (existing, _) when existing = polarity -> assignments
    | Some _ -> emit_error (id ^ ": inconsistent SAT unit replay assignment")
    | None -> (var, (polarity, proof)) :: assignments
  in
  let clause_eval assignments clause =
    let rec loop unassigned = function
      | [] ->
          let unique_unassigned =
            unassigned |> List.sort_uniq compare
          in
          begin match unique_unassigned with
          | [] -> `Conflict
          | [lit] -> `Unit lit
          | _ -> `Undetermined
          end
      | ((var, polarity) as lit) :: rest ->
          begin match List.assoc_opt var assignments with
          | Some (assigned_polarity, _) when assigned_polarity = polarity -> `Satisfied
          | Some _ -> loop unassigned rest
          | None -> loop (lit :: unassigned) rest
          end
    in
    loop [] clause
  in
  let prove_unit assignments clause proof lit =
    let target_clause = [simple_literal_of_sat_lit lit] in
    let target_prop = simple_sat_lit_prop lit in
    let source_clause = simple_clause_of_sat_clause clause in
    let eliminator source_lit source_proof =
      match split_literal_number source_lit with
      | Some var ->
          let polarity =
            match source_lit with
            | Pos _ -> true
            | Neg _ -> false
          in
          literal_contradiction assignments (var, polarity) source_proof
      | None -> None
    in
    simple_clause_projection_with_eliminators
      target_prop target_clause source_clause proof eliminator
  in
  let prove_conflict assignments clause proof =
    let source_clause = simple_clause_of_sat_clause clause in
    let eliminator source_lit source_proof =
      match split_literal_number source_lit with
      | Some var ->
          let polarity =
            match source_lit with
            | Pos _ -> true
            | Neg _ -> false
          in
          literal_contradiction assignments (var, polarity) source_proof
      | None -> None
    in
    simple_clause_projection_with_eliminators
      "False" [] source_clause proof eliminator
  in
  let prove_rup checked_steps parent_step_ids result_clause =
    let antecedents =
      List.map
        (fun parent ->
          match List.assoc_opt parent checked_steps with
          | Some item -> item
          | None -> emit_error (id ^ ": SAT proof parent is not available for replay"))
        parent_step_ids
    in
    let rec derive_false assignments =
      let rec find_conflict_or_unit = function
        | [] -> None
        | (clause, proof_name) :: rest ->
            begin match clause_eval assignments clause with
            | `Satisfied -> find_conflict_or_unit rest
            | `Undetermined -> find_conflict_or_unit rest
            | `Conflict -> Some (`Conflict (clause, proof_name))
            | `Unit lit -> Some (`Unit (clause, proof_name, lit))
            end
      in
      match find_conflict_or_unit antecedents with
      | Some (`Conflict (clause, proof_name)) ->
          prove_conflict assignments clause proof_name
      | Some (`Unit (clause, proof_name, lit)) ->
          let lit_proof = prove_unit assignments clause proof_name lit in
          derive_false (add_assignment lit lit_proof assignments)
      | None ->
          emit_error (id ^ ": SAT RUP replay did not reach a conflict")
    in
    let target_clause = simple_clause_of_sat_clause result_clause in
    let target_prop = simple_clause_prop target_clause in
    if result_clause = [] then
      derive_false []
    else
      let not_clause_name = "Hsat_rup_not_clause" in
      let assignments =
        result_clause
        |> List.mapi
             (fun index ((var, polarity) as lit) ->
                let split_prop = "split_" ^ string_of_int var in
                let lit_proof_name = "Hsat_rup_clause_lit_" ^ string_of_int index in
                let lit_intro =
                  simple_clause_intro_proof
                    target_clause (simple_literal_of_sat_lit lit) lit_proof_name
                in
                if polarity then
                  let proof =
                    Printf.sprintf
                      "(fun %s:%s => (%s %s))"
                      lit_proof_name split_prop not_clause_name lit_intro
                  in
                  (var, (false, proof))
                else
                  let proof =
                    Printf.sprintf
                      "(dneg %s (fun %s:%s -> False => (%s %s)))"
                      split_prop lit_proof_name split_prop not_clause_name lit_intro
                  in
                  (var, (true, proof)))
      in
      let contradiction = derive_false assignments in
      Printf.sprintf
        "(dneg %s (fun %s:%s -> False => %s))"
        target_prop not_clause_name target_prop contradiction
  in
  let claims_rev, checked_steps =
    List.fold_left
      (fun (claims_rev, checked_steps) step ->
         match step with
         | SatInput (sid, clause) ->
             let parent_id, parent_clause = parent_for_input clause in
             let parent_name = lookup_simple_name names parent_id in
             let source_clause =
               parent_clause_in_emitted_order parent_id (simple_clause_of_sat_clause parent_clause)
             in
             let name = step_name sid in
             let prop = simple_sat_clause_prop clause in
             let proof =
               let source_formula =
                 source_clause
                 |> simple_clause_formula_tm
                 |> left_assoc_vampire_or_formula
               in
               simple_formula_projection_with_eliminators
                 prop
                 (simple_clause_of_sat_clause clause)
                 source_formula
                 parent_name
                 (fun _ _ -> None)
             in
             ((name, prop, "exact " ^ proof ^ ".") :: claims_rev,
              (sid, (clause, name)) :: checked_steps)
         | SatRup (sid, parents, clause) ->
             let name = step_name sid in
             let prop = simple_sat_clause_prop clause in
             let proof = prove_rup checked_steps parents clause in
             ((name, prop, "exact " ^ proof ^ ".") :: claims_rev,
              (sid, (clause, name)) :: checked_steps))
      ([], [])
      proof
  in
  match checked_steps with
  | (_, ([], final_name)) :: _ -> (List.rev claims_rev, final_name)
  | _ -> emit_error (id ^ ": SAT proof final replay step is not empty")

let simple_inequality_name_intro_proof type_env result_sorts id result =
  let literal, named =
    match result with
    | [literal] ->
        begin match bool_name_literal false literal with
        | Some named -> literal, named
        | None -> emit_error (id ^ ": inequality_name_intro must be a positive equality to false")
        end
    | _ -> emit_error (id ^ ": inequality_name_intro proof expects a singleton clause")
  in
  let named_text = simple_tm_expr_with_expected type_env (Some "prop") named in
  let refutation =
    Printf.sprintf
      "(fun Hineq_name:%s => Hineq_name (fun Q H => H))"
      named_text
  in
  let atom =
    match literal with
    | Pos atom -> atom
    | Neg _ -> emit_error (id ^ ": inequality_name_intro literal is not positive")
  in
  let proof =
    match equality_sides atom with
    | Some (left, right) when is_vampire_false left && right = named ->
        Printf.sprintf
          "(vampire_fool_not_prop_to_false_eq (%s) %s)"
          named_text refutation
    | Some (left, right) when left = named && is_vampire_false right ->
        Printf.sprintf
          "(vampire_fool_not_prop_to_eq_false (%s) %s)"
          named_text refutation
    | Some _ ->
        emit_error (id ^ ": inequality_name_intro literal is not an equality between the split name and false")
    | None -> emit_error (id ^ ": inequality_name_intro literal is not an equality")
  in
  simple_wrap_forall_intro result_sorts
    (simple_clause_intro_proof result literal proof)

let simple_inequality_split_clause_proof
    type_env id parent_id splits result target_prop parent_sorts result_sorts checked names =
  let parent_clause = lookup_simple_clause checked parent_id in
  let parent_proof =
    simple_apply_forall_vars (lookup_simple_name names parent_id) parent_sorts
  in
  let last_arg args =
    match List.rev args with
    | arg :: _ -> arg
    | [] -> emit_error (id ^ ": inequality split name has no arguments")
  in
  let replacement_proof split source_proof =
    let split_name, split_args =
      match bool_name_literal false split.split_name_literal with
      | Some named -> split_name_application id named
      | None -> emit_error (id ^ ": inequality split name literal is not false equality")
    in
    let split_arg = last_arg split_args in
    let replacement_named =
      match bool_name_literal true split.split_replacement with
      | Some named -> named
      | None -> emit_error (id ^ ": inequality split replacement is not true equality")
    in
    let replacement_name, replacement_args =
      split_name_application id replacement_named
    in
    if replacement_name <> split_name then
      emit_error (id ^ ": inequality split replacement uses a different split name");
    let target_arg = last_arg replacement_args in
    let source_atom =
      match split.split_source with
      | Neg atom -> atom
      | Pos _ -> emit_error (id ^ ": inequality split source literal is not negative")
    in
    let source_to_named =
      match equality_sides source_atom with
      | Some (left, right) when left = target_arg && right = split_arg ->
          source_proof
      | Some (left, right) when left = split_arg && right = target_arg ->
          "(" ^ simple_literal_equality_symmetry_proof type_env split.split_source source_proof ^ ")"
      | Some _ ->
          emit_error (id ^ ": inequality split source equality does not match split arguments")
      | None -> emit_error (id ^ ": inequality split source literal is not an equality")
    in
    let named_text =
      simple_tm_expr_with_expected type_env (Some "prop") replacement_named
    in
    let replacement_atom =
      match split.split_replacement with
      | Pos atom -> atom
      | Neg _ -> emit_error (id ^ ": inequality split replacement is not positive")
    in
    match equality_sides replacement_atom with
    | Some (left, right) when is_vampire_bool_const left && not (is_vampire_false left)
                            && right = replacement_named ->
        Printf.sprintf
          "(vampire_fool_prop_to_true_eq (%s) %s)"
          named_text source_to_named
    | Some (left, right) when left = replacement_named
                            && is_vampire_bool_const right && not (is_vampire_false right) ->
        Printf.sprintf
          "(vampire_fool_prop_to_eq_true (%s) %s)"
          named_text source_to_named
    | Some _ ->
        emit_error (id ^ ": inequality split replacement is not an equality between true and the split name")
    | None -> emit_error (id ^ ": inequality split replacement is not an equality")
  in
  let rec split_for_source lit = function
    | [] -> None
    | split :: rest ->
        if split.split_source = lit then Some split else split_for_source lit rest
  in
  let introduce lit proof =
    match split_for_source lit splits with
    | Some split ->
        simple_clause_intro_proof result split.split_replacement
          (replacement_proof split proof)
    | None -> simple_clause_intro_proof result lit proof
  in
  let rec project depth source_clause proof =
    match source_clause with
    | [] -> emit_error "cannot project inequality split from the empty clause"
    | [lit] -> introduce lit proof
    | lit :: rest ->
        let head_name = "Hineq_lit_" ^ string_of_int depth in
        let tail_name = "Hineq_tail_" ^ string_of_int depth in
        let head_branch = introduce lit head_name in
        let tail_branch = project (depth + 1) rest tail_name in
        Printf.sprintf "(%s %s (fun %s => %s) (fun %s => %s))"
          proof (simple_prop_arg target_prop)
          head_name head_branch
          tail_name tail_branch
  in
  simple_wrap_forall_intro result_sorts (project 0 parent_clause parent_proof)

let rec simple_formula_prop_text_with_used used type_env tm =
  match tm with
  | All (tp, body) ->
      let sort = simple_tp_expr tp in
      let binder =
        match preferred_formula_binder_name sort body with
        | Some name
            when not (List.mem name used)
                 && List.assoc_opt name type_env = Some sort ->
            megalodon_ident name
        | _ ->
            let candidates =
              type_env
              |> List.filter
                   (fun (name, known_sort) ->
                      let binder = megalodon_ident name in
                      known_sort = sort
                      && is_vampire_var_name binder
                      && not (List.mem binder used)
                      && tm_contains_symbol binder body)
            in
            match candidates with
            | (name, _) :: _ -> megalodon_ident name
            | [] ->
                begin match max_vampire_var_name body with
                | Some name -> megalodon_ident name
                | None -> "Xformula"
                end
      in
      "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
      ^ simple_formula_prop_text_with_used
          (binder :: used) ((binder, sort) :: type_env) body
  | Imp (left, right) ->
      "(" ^ simple_formula_prop_text_with_used used type_env left ^ " -> "
      ^ simple_formula_prop_text_with_used used type_env right ^ ")"
  | Ap (Ap (TmH "vampire_and", left), right) ->
      "vampire_and (" ^ simple_formula_prop_text_with_used used type_env left ^ ") ("
      ^ simple_formula_prop_text_with_used used type_env right ^ ")"
  | Ap (Ap (TmH "vampire_or", left), right) ->
      "vampire_or (" ^ simple_formula_prop_text_with_used used type_env left ^ ") ("
      ^ simple_formula_prop_text_with_used used type_env right ^ ")"
  | Ap (exists_head, Lam (tp, body))
      when exists_head = TmH "vampire_exists_prop"
           || exists_head = TmH "vampire_exists_set" ->
      let sort = simple_tp_expr tp in
      let exists_name =
        match sort with
        | "set" -> "vampire_exists_set"
        | "prop" -> "vampire_exists_prop"
        | "set->prop" -> "vampire_exists_set_prop"
        | "set->set" -> "vampire_exists_set_set"
        | "set->set->prop" -> "vampire_exists_set_set_prop"
        | _ -> "vampire_exists_set"
      in
      let binder =
        match preferred_formula_binder_name sort body with
        | Some name
            when not (List.mem name used)
                 &&
                 (match List.assoc_opt name type_env with
                  | Some known_sort -> known_sort = sort
                  | None -> true) ->
            megalodon_ident name
        | _ ->
            let candidates =
              type_env
              |> List.filter
                   (fun (name, known_sort) ->
                      let binder = megalodon_ident name in
                      known_sort = sort
                      && is_vampire_var_name binder
                      && not (List.mem binder used)
                      && tm_contains_symbol binder body)
            in
            begin match candidates with
            | (name, _) :: _ -> megalodon_ident name
            | [] ->
            match first_unused_vampire_var_name_with_sort
                    type_env used sort body
            with
            | Some name -> megalodon_ident name
            | None ->
                begin match first_unused_vampire_var_name used body with
                | Some name -> megalodon_ident name
                | None -> "Xformula"
                end
            end
      in
      exists_name ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
      ^ simple_formula_prop_text_with_used
          (binder :: used) ((binder, sort) :: type_env) body ^ ")"
  | atom ->
      begin match equality_sides atom with
      | Some _ -> simple_atom_prop_with_type_env type_env atom
      | None -> simple_tm_expr_with_expected type_env (Some "prop") atom
      end

let rec simple_formula_prop_text_for_definition used type_env tm =
  match tm with
  | All (tp, body) ->
      let sort = simple_tp_expr tp in
      let binder =
        match preferred_formula_binder_name sort body with
        | Some name
            when not (List.mem name used)
                 && List.assoc_opt name type_env = Some sort ->
            megalodon_ident name
        | _ ->
            begin match first_unused_vampire_var_name_with_sort type_env used sort body with
            | Some name -> megalodon_ident name
            | None ->
                let candidates =
                  type_env
                  |> List.filter
                       (fun (name, known_sort) ->
                          let binder = megalodon_ident name in
                          known_sort = sort
                          && is_vampire_var_name binder
                          && not (List.mem binder used)
                          && tm_contains_symbol binder body)
                in
                match candidates with
                | (name, _) :: _ -> megalodon_ident name
                | [] ->
                    begin match max_vampire_var_name body with
                    | Some name -> megalodon_ident name
                    | None -> "Xformula"
                    end
            end
      in
      "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
      ^ simple_with_db_aliases [binder]
          (fun () ->
             simple_formula_prop_text_for_definition
               (binder :: used) ((binder, sort) :: type_env) body)
  | Imp (left, right) ->
      "(" ^ simple_formula_prop_text_for_definition used type_env left ^ " -> "
      ^ simple_formula_prop_text_for_definition used type_env right ^ ")"
  | Ap (Ap (TmH "vampire_and", left), right) ->
      "vampire_and (" ^ simple_formula_prop_text_for_definition used type_env left ^ ") ("
      ^ simple_formula_prop_text_for_definition used type_env right ^ ")"
  | Ap (Ap (TmH "vampire_or", left), right) ->
      "vampire_or (" ^ simple_formula_prop_text_for_definition used type_env left ^ ") ("
      ^ simple_formula_prop_text_for_definition used type_env right ^ ")"
  | Ap (exists_head, Lam (tp, body))
      when exists_head = TmH "vampire_exists_prop"
           || exists_head = TmH "vampire_exists_set" ->
      let sort = simple_tp_expr tp in
      let exists_name =
        match sort with
        | "set" -> "vampire_exists_set"
        | "prop" -> "vampire_exists_prop"
        | "set->prop" -> "vampire_exists_set_prop"
        | "set->set" -> "vampire_exists_set_set"
        | "set->set->prop" -> "vampire_exists_set_set_prop"
        | _ -> "vampire_exists_set"
      in
      let binder =
        match preferred_formula_binder_name sort body with
        | Some name
            when not (List.mem name used)
                 &&
                 (match List.assoc_opt name type_env with
                  | Some known_sort -> known_sort = sort
                  | None -> true) ->
            megalodon_ident name
        | _ ->
            begin match first_unused_vampire_var_name_with_sort type_env used sort body with
            | Some name -> megalodon_ident name
            | None ->
                let candidates =
                  type_env
                  |> List.filter
                       (fun (name, known_sort) ->
                          let binder = megalodon_ident name in
                          known_sort = sort
                          && is_vampire_var_name binder
                          && not (List.mem binder used)
                          && tm_contains_symbol binder body)
                in
                begin match candidates with
                | (name, _) :: _ -> megalodon_ident name
                | [] ->
                    begin match first_unused_vampire_var_name used body with
                    | Some name -> megalodon_ident name
                    | None -> "Xformula"
                    end
                end
            end
      in
      exists_name ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
      ^ simple_with_db_aliases [binder]
          (fun () ->
             simple_formula_prop_text_for_definition
               (binder :: used) ((binder, sort) :: type_env) body) ^ ")"
  | atom ->
      begin match equality_sides atom with
      | Some _ -> simple_atom_prop_with_type_env type_env atom
      | None -> simple_tm_expr_with_expected type_env (Some "prop") atom
      end

let rec simple_formula_prop_text type_env tm =
  match tm with
  | All (tp, body) ->
      let sort = simple_tp_expr tp in
      let binder =
        match preferred_formula_binder_name sort body with
        | Some name when List.assoc_opt name type_env = Some sort ->
            megalodon_ident name
        | _ ->
            let candidates =
              type_env
              |> List.filter
                   (fun (name, known_sort) ->
                      let binder = megalodon_ident name in
                      known_sort = sort
                      && is_vampire_var_name binder
                      && tm_contains_symbol binder body)
            in
            match candidates with
            | (name, _) :: _ -> megalodon_ident name
            | [] ->
                begin match max_vampire_var_name body with
                | Some name -> megalodon_ident name
                | None -> "Xformula"
                end
      in
      "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
      ^ simple_formula_prop_text ((binder, sort) :: type_env) body
  | Imp (left, right) ->
      "(" ^ simple_formula_prop_text type_env left ^ " -> "
      ^ simple_formula_prop_text type_env right ^ ")"
  | Ap (Ap (TmH "vampire_and", left), right) ->
      "vampire_and (" ^ simple_formula_prop_text type_env left ^ ") ("
      ^ simple_formula_prop_text type_env right ^ ")"
  | Ap (Ap (TmH "vampire_or", left), right) ->
      "vampire_or (" ^ simple_formula_prop_text type_env left ^ ") ("
      ^ simple_formula_prop_text type_env right ^ ")"
  | Ap (exists_head, Lam (tp, body))
      when exists_head = TmH "vampire_exists_prop"
           || exists_head = TmH "vampire_exists_set" ->
      let sort = simple_tp_expr tp in
      let exists_name =
        match sort with
        | "set" -> "vampire_exists_set"
        | "prop" -> "vampire_exists_prop"
        | "set->prop" -> "vampire_exists_set_prop"
        | "set->set" -> "vampire_exists_set_set"
        | "set->set->prop" -> "vampire_exists_set_set_prop"
        | _ -> "vampire_exists_set"
      in
      let binder =
        match preferred_formula_binder_name sort body with
        | Some name when List.assoc_opt name type_env = Some sort ->
            megalodon_ident name
        | None ->
            let candidates =
              type_env
              |> List.filter
                   (fun (name, known_sort) ->
                      let binder = megalodon_ident name in
                      known_sort = sort
                      && is_vampire_var_name binder
                      && tm_contains_symbol binder body)
            in
            begin match candidates with
            | (name, _) :: _ -> megalodon_ident name
            | [] ->
                begin match max_vampire_var_name body with
                | Some name -> megalodon_ident name
                | None -> "Xformula"
                end
            end
        | Some name -> megalodon_ident name
      in
      exists_name ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
      ^ simple_formula_prop_text ((binder, sort) :: type_env) body ^ ")"
  | atom ->
      begin match equality_sides atom with
      | Some _ -> simple_atom_prop_with_type_env type_env atom
      | None -> simple_tm_expr_with_expected type_env (Some "prop") atom
      end

let simple_rendered_prop_equiv left right =
  let replace_substring needle replacement text =
    let needle_len = String.length needle in
    let text_len = String.length text in
    let buffer = Buffer.create text_len in
    let rec loop i =
      if i >= text_len then ()
      else if i + needle_len <= text_len
              && String.sub text i needle_len = needle then
        (Buffer.add_string buffer replacement; loop (i + needle_len))
      else
        (Buffer.add_char buffer text.[i]; loop (i + 1))
    in
    loop 0;
    Buffer.contents buffer
  in
  let normalize text =
    text
    |> replace_substring "vampire_true" "True"
    |> replace_substring "vampire_false" "False"
    |> String.to_seq
    |> Seq.filter
         (function
           | ' ' | '\n' | '\t' | '\r' | '(' | ')' -> false
           | _ -> true)
    |> String.of_seq
  in
  normalize left = normalize right

let simple_formula_orientation_proof
    ?(prefer_last_binder=false)
    ?source_type_env
    ?target_type_env
    type_env source target proof =
  let source_type_env =
    match source_type_env with
    | Some env -> env
    | None -> type_env
  in
  let target_type_env =
    match target_type_env with
    | Some env -> env
    | None -> type_env
  in
  let proof_index = ref 0 in
  let fresh prefix =
    let name = prefix ^ string_of_int !proof_index in
    incr proof_index;
    name
  in
  let choose_binder binder_env used sort body =
    let candidates =
      binder_env
      |> List.filter
           (fun (name, known_sort) ->
              let binder = megalodon_ident name in
              known_sort = sort
              && is_vampire_var_name binder
              && not (List.mem binder used)
              && tm_contains_symbol binder body)
    in
    match (if prefer_last_binder then List.rev candidates else candidates) with
    | (name, _) :: _ ->
        let binder = megalodon_ident name in
        (binder, binder)
    | [] ->
        let binder = fresh "Xorient_" in
        (binder, binder)
  in
  let source_render_env env =
    simple_type_env_with_variable_overrides env source_type_env
  in
  let target_render_env env =
    simple_type_env_with_variable_overrides env target_type_env
  in
  let generic_render_env env =
    simple_type_env_with_variable_overrides env type_env
  in
  let render_source used env tm =
    simple_formula_prop_text_with_used used (source_render_env env) tm
  in
  let render_target used env tm =
    simple_formula_prop_text_with_used used (target_render_env env) tm
  in
  let rec convert env used source target proof =
    if source = target then proof
    else
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body) when source_tp = target_tp ->
          let sort = simple_tp_expr source_tp in
          let source_binder =
            choose_binder source_type_env used sort source_body
          in
          let target_binder =
            choose_binder target_type_env used sort target_body
          in
          let source_raw, _ = source_binder in
          let target_raw, _ = target_binder in
          let binder = fresh "Xorient_forall_" in
          let source_body =
            if source_raw = binder then source_body
            else subst_tm [(source_raw, TmH binder)] source_body
          in
          let target_body =
            if target_raw = binder then target_body
            else subst_tm [(target_raw, TmH binder)] target_body
          in
          let env = (binder, sort) :: env in
          "(fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
          ^ convert env (binder :: used) source_body target_body ("(" ^ proof ^ " " ^ binder ^ ")")
          ^ ")"
      | Imp (source_left, source_right), Imp (target_left, target_right) ->
          let arg = fresh "Horient_arg_" in
          let target_left_text = render_target used env target_left in
          let source_left_proof = convert env used target_left source_left arg in
          let source_right_proof = "(" ^ proof ^ " " ^ source_left_proof ^ ")" in
          let target_right_proof = convert env used source_right target_right source_right_proof in
          "(fun " ^ arg ^ ":" ^ target_left_text ^ " => " ^ target_right_proof ^ ")"
	      | Ap (Ap (TmH "vampire_and", source_left), source_right),
	        Ap (Ap (TmH "vampire_and", target_left), target_right) ->
	          let left_name = fresh "Horient_left_" in
	          let right_name = fresh "Horient_right_" in
	          let source_left_text = render_source used env source_left in
	          let source_right_text = render_source used env source_right in
	          let target_left_text = render_target used env target_left in
	          let target_right_text = render_target used env target_right in
	          let left_proof = convert env used source_left target_left left_name in
	          let right_proof = convert env used source_right target_right right_name in
	          Printf.sprintf
	            "(vampire_and_map (%s) (%s) (%s) (%s) (fun %s:%s => %s) (fun %s:%s => %s) %s)"
	            source_left_text source_right_text target_left_text target_right_text
	            left_name source_left_text left_proof
	            right_name source_right_text right_proof
	            proof
	      | Ap (Ap (TmH "vampire_or", source_a),
	            Ap (Ap (TmH "vampire_or", source_b), source_c)), _
	          when
	            let source_items = collect_binary "vampire_or" source in
	            let target_items = collect_binary "vampire_or" target in
	            List.length source_items = List.length target_items
	            && List.length source_items > 2 ->
	          let source_a_text = render_source used env source_a in
	          let source_b_text = render_source used env source_b in
	          let source_c_text = render_source used env source_c in
	          let associated_source =
	            Ap (Ap (TmH "vampire_or",
	                    Ap (Ap (TmH "vampire_or", source_a), source_b)),
	                source_c)
	          in
	          let associated_proof =
	            Printf.sprintf
	              "(vampire_or_assoc (%s) (%s) (%s) %s)"
	              source_a_text source_b_text source_c_text proof
	          in
	          convert env used associated_source target associated_proof
	      | _ when
	          let source_items = collect_binary "vampire_or" source in
	          let target_items = collect_binary "vampire_or" target in
	          List.length source_items = List.length target_items
		          && List.length source_items > 1
		          && (source_items <> [source] || target_items <> [target]) ->
		          let target_items = collect_binary "vampire_or" target in
		          let target_text = render_target used env target in
	          let target_item index =
	            match List.nth_opt target_items index with
	            | Some tm -> tm
	            | None ->
	                emit_error
	                  "formula orientation transport lost a disjunction target leaf"
	          in
	          let rec inject target index leaf_proof =
	            match target with
	            | Ap (Ap (TmH "vampire_or", left), right) ->
	                let left_count =
	                  List.length (collect_binary "vampire_or" left)
	                in
	                let left_text = render_target used env left in
	                let right_text = render_target used env right in
	                if index < left_count then
	                  let left_proof = inject left index leaf_proof in
	                  Printf.sprintf
	                    "(fun vorient_goal:prop => fun Horient_left:(%s) -> vorient_goal => fun Horient_right:(%s) -> vorient_goal => Horient_left %s)"
	                    left_text right_text left_proof
	                else
	                  let right_proof = inject right (index - left_count) leaf_proof in
	                  Printf.sprintf
	                    "(fun vorient_goal:prop => fun Horient_left:(%s) -> vorient_goal => fun Horient_right:(%s) -> vorient_goal => Horient_right %s)"
	                    left_text right_text right_proof
	            | _ -> leaf_proof
	          in
	          let rec eliminate source index proof_expr =
	            match source with
	            | Ap (Ap (TmH "vampire_or", left), right) ->
	                let left_count =
	                  List.length (collect_binary "vampire_or" left)
	                in
	                let left_name = fresh "Horient_or_left_" in
	                let right_name = fresh "Horient_or_right_" in
	                let left_text = render_source used env left in
	                let right_text = render_source used env right in
	                let left_proof = eliminate left index left_name in
	                let right_proof =
	                  eliminate right (index + left_count) right_name
	                in
	                Printf.sprintf
	                  "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
	                  proof_expr (simple_prop_arg target_text)
	                  left_name left_text left_proof
	                  right_name right_text right_proof
	            | leaf ->
	                let target_leaf = target_item index in
	                inject target index
	                  (convert env used leaf target_leaf proof_expr)
	          in
	          eliminate source 0 proof
	      | Ap (Ap (TmH "vampire_or", source_a),
	            Ap (Ap (TmH "vampire_or", source_b), source_c)),
	        Ap (Ap (TmH "vampire_or",
                Ap (Ap (TmH "vampire_or", target_a), target_b)),
            target_c) ->
          let a_name = fresh "Horient_assoc_a_" in
          let b_name = fresh "Horient_assoc_b_" in
          let c_name = fresh "Horient_assoc_c_" in
          let source_a_text = render_source used env source_a in
          let source_b_text = render_source used env source_b in
          let source_c_text = render_source used env source_c in
          let target_a_text = render_target used env target_a in
          let target_b_text = render_target used env target_b in
          let target_c_text = render_target used env target_c in
          let target_left_text =
            render_target used env (Ap (Ap (TmH "vampire_or", target_a), target_b))
          in
          let target_text = render_target used env target in
          let a_proof = convert env used source_a target_a a_name in
          let b_proof = convert env used source_b target_b b_name in
          let c_proof = convert env used source_c target_c c_name in
          let target_left_from_a =
            Printf.sprintf
              "(fun vorient_left_goal:prop => fun Horient_left:(%s) -> vorient_left_goal => fun Horient_right:(%s) -> vorient_left_goal => Horient_left %s)"
              target_a_text target_b_text a_proof
          in
          let target_left_from_b =
            Printf.sprintf
              "(fun vorient_left_goal:prop => fun Horient_left:(%s) -> vorient_left_goal => fun Horient_right:(%s) -> vorient_left_goal => Horient_right %s)"
              target_a_text target_b_text b_proof
          in
          let target_from_left left_proof =
            Printf.sprintf
              "(fun vorient_goal:prop => fun Horient_left:(%s) -> vorient_goal => fun Horient_right:(%s) -> vorient_goal => Horient_left %s)"
              target_left_text target_c_text left_proof
          in
          let target_from_c =
	            Printf.sprintf
	              "(fun vorient_goal:prop => fun Horient_left:(%s) -> vorient_goal => fun Horient_right:(%s) -> vorient_goal => Horient_right %s)"
	              target_left_text target_c_text c_proof
	          in
	          Printf.sprintf
	            "(%s %s (fun %s:%s => %s) (fun Horient_assoc_tail:(%s) => Horient_assoc_tail %s (fun %s:%s => %s) (fun %s:%s => %s)))"
	            proof (simple_prop_arg target_text)
	            a_name source_a_text (target_from_left target_left_from_a)
	            (render_source used env (Ap (Ap (TmH "vampire_or", source_b), source_c)))
	            (simple_prop_arg target_text)
	            b_name source_b_text (target_from_left target_left_from_b)
	            c_name source_c_text target_from_c
	      | Ap (Ap (TmH "vampire_or", source_left), source_right),
	        Ap (Ap (TmH "vampire_or", target_left), target_right) ->
	          let left_name = fresh "Horient_left_" in
          let right_name = fresh "Horient_right_" in
          let source_left_text = render_source used env source_left in
          let source_right_text = render_source used env source_right in
          let target_left_text = render_target used env target_left in
          let target_right_text = render_target used env target_right in
          let target_text = render_target used env target in
          let left_proof = convert env used source_left target_left left_name in
          let right_proof = convert env used source_right target_right right_name in
          let left_intro =
            Printf.sprintf
              "(fun vorient_goal:prop => fun Hleft:(%s) -> vorient_goal => fun Hright:(%s) -> vorient_goal => Hleft %s)"
              target_left_text target_right_text left_proof
          in
          let right_intro =
            Printf.sprintf
              "(fun vorient_goal:prop => fun Hleft:(%s) -> vorient_goal => fun Hright:(%s) -> vorient_goal => Hright %s)"
              target_left_text target_right_text right_proof
          in
          Printf.sprintf
            "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
            proof (simple_prop_arg target_text)
            left_name source_left_text left_intro
            right_name source_right_text right_intro
      | Ap (source_exists, Lam (source_tp, source_body)),
        Ap (target_exists, Lam (target_tp, target_body))
          when source_exists = target_exists && source_tp = target_tp
               && (source_exists = TmH "vampire_exists_prop"
                   || source_exists = TmH "vampire_exists_set") ->
          let sort = simple_tp_expr source_tp in
          let source_raw, _ =
            choose_binder source_type_env used sort source_body
          in
          let _, binder =
            choose_binder target_type_env used sort target_body
          in
          let source_body =
            if source_raw = binder then source_body
            else subst_tm [(source_raw, TmH binder)] source_body
          in
          let body_env = (binder, sort) :: env in
	          let source_body_text = render_source (binder :: used) body_env source_body in
	          let target_body_text = render_target (binder :: used) body_env target_body in
	          let witness_name = fresh "Horient_exists_" in
	          let body_proof =
	            convert body_env (binder :: used) source_body target_body witness_name
	          in
		          let map_name =
		            match sort with
		            | "set" -> "vampire_exists_set_map"
		            | "prop" -> "vampire_exists_prop_map"
                | "set->prop" -> "vampire_exists_set_prop_map"
		            | _ ->
		                emit_error
		                  "formula orientation transport has no existential map theorem for this sort"
		          in
	          Printf.sprintf
	            "(%s (fun %s:%s => %s) (fun %s:%s => %s) (fun %s:%s => fun %s:%s => %s) %s)"
	            map_name
	            binder (simple_binder_sort_expr sort) source_body_text
	            binder (simple_binder_sort_expr sort) target_body_text
	            binder (simple_binder_sort_expr sort)
	            witness_name source_body_text body_proof
	            proof
      | _ ->
          begin match equality_sides source, equality_sides target with
          | Some (source_left, source_right), Some (target_left, target_right)
              when source_left = target_right && source_right = target_left ->
              "(" ^ simple_literal_equality_symmetry_proof (generic_render_env env) (Pos source) proof ^ ")"
          | _ ->
              begin match source, target with
              | Ap (Ap (TmH "vampire_eq_prop", source_left), source_right),
                Ap (Ap (TmH "vampire_eq_prop", target_left), target_right)
                  when source_left = target_right && source_right = target_left ->
                  let left_text = simple_tm_expr_with_expected (generic_render_env env) (Some "prop") source_left in
                  let right_text = simple_tm_expr_with_expected (generic_render_env env) (Some "prop") source_right in
                  "(vampire_eq_prop_sym (" ^ left_text ^ ") (" ^ right_text ^ ") " ^ proof ^ ")"
              | _ ->
                  emit_error
                    ("formula orientation transport supports only equality symmetry and simple logical structure: "
                     ^ render_source used env source
                     ^ " ==> "
                     ^ render_target used env target)
              end
          end
  in
  convert [] [] source target proof

let simple_skolem_formula_proof ?opened_witness
    type_env id parent_id subst source target parent_sorts result_sorts names =
  let choice_for_sort = function
    | "set" ->
        Some "vampire_exists_set_choice"
    | "prop" ->
        Some "vampire_exists_prop_choice"
    | "set->prop" ->
        Some "vampire_exists_set_prop_choice"
    | "set->set" ->
        Some "vampire_exists_set_set_choice"
    | "set->set->prop" ->
        Some "vampire_exists_set_set_prop_choice"
    | _ -> None
  in
  let binder_sorts =
    parent_sorts @ result_sorts |> simple_unique_variable_sorts
  in
  let binder_index = ref 0 in
  let proof_index = ref 0 in
  let fresh prefix =
    let name = prefix ^ string_of_int !proof_index in
    incr proof_index;
    name
  in
  let is_exists_head = function
    | TmH ("vampire_exists_prop" | "vampire_exists_set"
          | "vampire_exists_set_prop" | "vampire_exists_set_set"
          | "vampire_exists_set_set_prop") -> true
    | _ -> false
  in
  let fallback_binder sort =
    let rec find_from i =
      match List.nth_opt binder_sorts i with
      | Some (name, known_sort) when known_sort = sort ->
          binder_index := i + 1;
          megalodon_ident name
      | Some _ -> find_from (i + 1)
      | None ->
          let name = "Xskolem_" ^ string_of_int !binder_index in
          incr binder_index;
          name
    in
    find_from !binder_index
  in
  let skolem_subst_for_var source_var =
    match List.assoc_opt source_var subst with
    | Some tm -> tm
    | None -> emit_error (id ^ ": skolem proof could not find substitution variable")
  in
  let inferred_formula_binder env sort body =
    let candidates =
      env
      |> List.filter
           (fun (name, known_sort) ->
              let binder = megalodon_ident name in
              known_sort = sort
              && is_vampire_var_name binder
              && tm_contains_symbol binder body)
    in
    match List.rev candidates with
    | (name, _) :: _ -> Some (megalodon_ident name)
    | [] ->
        begin match first_unused_vampire_var_name [] body with
        | Some name -> Some (megalodon_ident name)
        | None -> None
        end
  in
  let metadata_formula_binder bound sort body =
    binder_sorts
    |> List.find_opt
         (fun (name, known_sort) ->
            let binder = megalodon_ident name in
            known_sort = sort
            && not (List.mem binder bound)
            && tm_contains_symbol binder body)
    |> Option.map (fun (name, _) -> megalodon_ident name)
  in
  let known_binder_sort env binder =
    match List.assoc_opt binder env with
    | Some _ as found -> found
    | None -> List.assoc_opt binder binder_sorts
  in
  let preferred_skolem_formula_binder bound env sort body =
    match preferred_formula_binder_name sort body with
    | Some name ->
        let binder = megalodon_ident name in
        if is_vampire_var_name binder
           && not (List.mem binder bound)
           && tm_contains_symbol binder body
           &&
           (match known_binder_sort env binder with
            | Some known_sort -> known_sort = sort
            | None -> true)
        then Some binder
        else None
    | None -> None
  in
  let formula_binder bound env sort body =
    match preferred_skolem_formula_binder bound env sort body with
    | Some binder -> binder
    | None ->
        begin match metadata_formula_binder bound sort body with
        | Some binder -> binder
        | None ->
            begin match inferred_formula_binder env sort body with
            | Some binder -> binder
            | None -> fallback_binder sort
            end
        end
  in
  let rec formula_text bound env tm =
    match tm with
    | All (tp, body) ->
        let sort = simple_tp_expr tp in
        let binder = formula_binder bound env sort body in
        "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_text (binder :: bound) ((binder, sort) :: env) body)
    | Imp (left, right) ->
        "((" ^ formula_text bound env left ^ ") -> (" ^ formula_text bound env right ^ "))"
    | Ap (Ap (TmH "vampire_and", left), right) ->
        "vampire_and (" ^ formula_text bound env left ^ ") (" ^ formula_text bound env right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
        "vampire_or (" ^ formula_text bound env left ^ ") (" ^ formula_text bound env right ^ ")"
    | Ap (exists_head, Lam (tp, body)) when is_exists_head exists_head ->
        let sort = simple_tp_expr tp in
        let exists_name =
          match sort with
          | "set" -> "vampire_exists_set"
          | "prop" -> "vampire_exists_prop"
          | "set->prop" -> "vampire_exists_set_prop"
          | "set->set" -> "vampire_exists_set_set"
          | "set->set->prop" -> "vampire_exists_set_set_prop"
          | _ -> "vampire_exists_set"
        in
        let raw_source_var =
          match subst with
          | [(source_var, _)] -> Some source_var
          | _ ->
              subst
              |> List.find_opt (fun (source_var, _) -> tm_contains_symbol source_var body)
              |> Option.map fst
        in
        let binder =
          match preferred_skolem_formula_binder bound env sort body with
          | Some binder -> binder
          | None ->
          match raw_source_var with
          | Some source_var
              when not (List.mem (megalodon_ident source_var) bound)
                   &&
                   (match known_binder_sort env (megalodon_ident source_var) with
                    | Some known_sort -> known_sort = sort
                    | None -> true) ->
              megalodon_ident source_var
          | Some _ | None ->
              begin match
                first_unused_vampire_var_name_with_sort env bound sort body
              with
              | Some name -> megalodon_ident name
              | None ->
                  begin match first_unused_vampire_var_name bound body with
                  | Some name -> megalodon_ident name
                  | None -> fallback_binder sort
                  end
              end
        in
        exists_name ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_text (binder :: bound) ((binder, sort) :: env) body)
        ^ ")"
    | _ ->
        simple_formula_prop_text_with_used [] env tm
  in
  let rec transport bound env available_subst source target proof =
    if source = target then proof
    else
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body) when source_tp = target_tp ->
          let sort = simple_tp_expr source_tp in
          let source_raw =
            match metadata_formula_binder bound sort source_body with
            | Some _ as found -> found
            | None -> inferred_formula_binder env sort source_body
          in
          let target_raw =
            match metadata_formula_binder bound sort target_body with
            | Some _ as found -> found
            | None -> inferred_formula_binder env sort target_body
          in
          let binder =
            match target_raw, source_raw with
            | Some binder, _ | None, Some binder -> binder
            | None, None -> fallback_binder sort
          in
          let source_body =
            match source_raw with
            | Some raw when raw <> binder ->
                subst_tm [(raw, TmH binder)] source_body
            | _ -> source_body
          in
          let target_body =
            match target_raw with
            | Some raw when raw <> binder ->
                subst_tm [(raw, TmH binder)] target_body
            | _ -> target_body
          in
          let env = (binder, sort) :: env in
          Printf.sprintf
            "(fun %s:%s => %s)"
            binder (simple_binder_sort_expr sort)
            (transport (binder :: bound) env available_subst source_body target_body ("(" ^ proof ^ " " ^ binder ^ ")"))
      | Ap (Ap (TmH "vampire_and", source_left), source_right),
        Ap (Ap (TmH "vampire_and", target_left), target_right) ->
          let left_name = fresh "Hskolem_and_left_" in
          let right_name = fresh "Hskolem_and_right_" in
          let target_left_text = formula_text bound env target_left in
          let target_right_text = formula_text bound env target_right in
          let target_text = formula_text bound env target in
          let left_proof = transport bound env available_subst source_left target_left left_name in
          let right_proof = transport bound env available_subst source_right target_right right_name in
          let target_intro =
            Printf.sprintf
              "(fun vskolem_and_goal:prop => fun Hskolem_and:((%s) -> (%s) -> vskolem_and_goal) => Hskolem_and %s %s)"
              target_left_text target_right_text left_proof right_proof
          in
          Printf.sprintf
            "(%s %s (fun %s => fun %s => %s))"
            proof (simple_prop_arg target_text)
            left_name right_name target_intro
      | Ap (Ap (TmH "vampire_or", source_a),
            Ap (Ap (TmH "vampire_or", source_b), source_c)),
        Ap (Ap (TmH "vampire_or",
                Ap (Ap (TmH "vampire_or", target_a), target_b)),
            target_c) ->
          let a_name = fresh "Hskolem_assoc_a_" in
          let b_name = fresh "Hskolem_assoc_b_" in
          let c_name = fresh "Hskolem_assoc_c_" in
          let target_a_text = formula_text bound env target_a in
          let target_b_text = formula_text bound env target_b in
          let target_c_text = formula_text bound env target_c in
          let target_left_text =
            formula_text bound env (Ap (Ap (TmH "vampire_or", target_a), target_b))
          in
          let target_text = formula_text bound env target in
          let a_proof = transport bound env available_subst source_a target_a a_name in
          let b_proof = transport bound env available_subst source_b target_b b_name in
          let c_proof = transport bound env available_subst source_c target_c c_name in
          let target_left_from_a =
            Printf.sprintf
              "(fun vassoc_left_goal:prop => fun Hassoc_left:(%s) -> vassoc_left_goal => fun Hassoc_right:(%s) -> vassoc_left_goal => Hassoc_left %s)"
              target_a_text target_b_text a_proof
          in
          let target_left_from_b =
            Printf.sprintf
              "(fun vassoc_left_goal:prop => fun Hassoc_left:(%s) -> vassoc_left_goal => fun Hassoc_right:(%s) -> vassoc_left_goal => Hassoc_right %s)"
              target_a_text target_b_text b_proof
          in
          let target_from_left left_proof =
            Printf.sprintf
              "(fun vassoc_goal:prop => fun Hassoc_left:(%s) -> vassoc_goal => fun Hassoc_right:(%s) -> vassoc_goal => Hassoc_left %s)"
              target_left_text target_c_text left_proof
          in
          let target_from_c =
            Printf.sprintf
              "(fun vassoc_goal:prop => fun Hassoc_left:(%s) -> vassoc_goal => fun Hassoc_right:(%s) -> vassoc_goal => Hassoc_right %s)"
              target_left_text target_c_text c_proof
          in
          Printf.sprintf
            "(%s %s (fun %s => %s) (fun Hskolem_assoc_tail => Hskolem_assoc_tail %s (fun %s => %s) (fun %s => %s)))"
            proof (simple_prop_arg target_text)
            a_name (target_from_left target_left_from_a)
            (simple_prop_arg target_text)
            b_name (target_from_left target_left_from_b)
            c_name target_from_c
      | Ap (Ap (TmH "vampire_or", source_left), source_right),
        Ap (Ap (TmH "vampire_or", target_left), target_right) ->
          let left_name = fresh "Hskolem_left_" in
          let right_name = fresh "Hskolem_right_" in
          let target_left_text = formula_text bound env target_left in
          let target_right_text = formula_text bound env target_right in
          let target_text = formula_text bound env target in
          let left_proof = transport bound env available_subst source_left target_left left_name in
          let right_proof = transport bound env available_subst source_right target_right right_name in
          let left_intro =
            Printf.sprintf
              "(fun vskolem_goal:prop => fun Hleft:(%s) -> vskolem_goal => fun Hright:(%s) -> vskolem_goal => Hleft %s)"
              target_left_text target_right_text left_proof
          in
          let right_intro =
            Printf.sprintf
              "(fun vskolem_goal:prop => fun Hleft:(%s) -> vskolem_goal => fun Hright:(%s) -> vskolem_goal => Hright %s)"
              target_left_text target_right_text right_proof
          in
          Printf.sprintf
            "(%s %s (fun %s => %s) (fun %s => %s))"
            proof (simple_prop_arg target_text)
            left_name left_intro
            right_name right_intro
      | Ap (exists_head, Lam (source_tp, body)), _
          when is_exists_head exists_head || available_subst <> [] ->
          let source_sort = simple_tp_expr source_tp in
          let raw_source_var =
            match available_subst with
            | [(source_var, _)] -> source_var
            | _ ->
                begin match
                  List.find_opt
                    (fun (source_var, _) -> tm_contains_symbol source_var body)
                    available_subst
                with
                | Some (source_var, _) -> source_var
                | None ->
                    begin match available_subst with
                    | (source_var, _) :: _ -> source_var
                    | [] -> emit_error (id ^ ": skolem proof has no remaining substitution for existential")
                    end
                end
          in
          let source_var = megalodon_ident raw_source_var in
          let skolem_tm = skolem_subst_for_var raw_source_var in
          let remaining_subst =
            List.filter (fun (source_var, _) -> source_var <> raw_source_var) available_subst
          in
          let choice_body = subst_tm [(raw_source_var, skolem_tm)] body in
          begin match choice_for_sort source_sort, opened_witness with
          | Some choice_theorem, _ ->
              let predicate_env = (source_var, source_sort) :: env in
              let predicate_text =
                "fun " ^ source_var ^ ":" ^ simple_binder_sort_expr source_sort ^ " => "
                ^ formula_text (source_var :: bound) predicate_env body
              in
              let choice_proof =
                Printf.sprintf
                  "(%s (%s) %s)"
                  choice_theorem predicate_text proof
              in
              transport bound env remaining_subst choice_body target choice_proof
          | None, Some witness_name ->
              transport bound env remaining_subst choice_body target witness_name
          | None, _ ->
              emit_error
                (id ^ ": skolem proof has no choice theorem for witness sort " ^ source_sort)
          end
      | Ap (_, Ap (TmH "vLAM", body)), _ when available_subst <> [] ->
          let raw_source_var =
            match available_subst with
            | [(source_var, _)] -> source_var
            | (source_var, _) :: _ -> source_var
            | [] -> emit_error (id ^ ": skolem proof has no remaining substitution for vLAM existential")
          in
          let source_var = megalodon_ident raw_source_var in
          let skolem_tm = skolem_subst_for_var raw_source_var in
          let source_sort =
            match
              List.assoc_opt source_var binder_sorts,
              simple_tm_sort type_env skolem_tm
            with
            | Some sort, _ | None, Some sort -> sort
            | None, None -> "set"
          in
          let remaining_subst =
            List.filter (fun (source_var, _) -> source_var <> raw_source_var) available_subst
          in
          let named_body = subst_tm [("db0", TmH source_var)] body in
          let choice_body =
            subst_tm [("db0", skolem_tm); (raw_source_var, skolem_tm)] body
          in
          begin match choice_for_sort source_sort, opened_witness with
          | Some choice_theorem, _ ->
              let predicate_env = (source_var, source_sort) :: env in
              let predicate_text =
                "fun " ^ source_var ^ ":" ^ simple_binder_sort_expr source_sort
                ^ " => " ^ formula_text (source_var :: bound) predicate_env named_body
              in
              let choice_proof =
                Printf.sprintf
                  "(%s (%s) %s)"
                  choice_theorem predicate_text proof
              in
              transport bound env remaining_subst choice_body target choice_proof
          | None, Some witness_name ->
              transport bound env remaining_subst choice_body target witness_name
          | None, _ ->
              emit_error
                (id ^ ": skolem proof has no choice theorem for vLAM witness sort " ^ source_sort)
          end
      | _ ->
          simple_formula_orientation_proof ~prefer_last_binder:true env source target proof
  in
  let parent_expr =
    simple_apply_forall_vars (lookup_simple_name names parent_id) parent_sorts
  in
  transport [] type_env subst source target parent_expr

let simple_predicate_definition_proof type_env id formula =
  let _, atom, body = predicate_definition_parts id formula in
  let definition_parameter_binders =
    let _, args = flatten_value_application (predicate_definition_definiendum_term atom) in
    args
    |> List.filter_map
         (function
           | TmH name when is_vampire_var_name (megalodon_ident name) ->
               Some (megalodon_ident name)
           | _ -> None)
    |> List.rev
    |> ref
  in
  let rec collect_binders env used = function
    | All (tp, body) ->
        let sort = simple_tp_expr tp in
        let binder =
          match !definition_parameter_binders with
          | candidate :: rest
              when not (List.mem candidate used)
                   && tm_contains_symbol candidate body
                   && List.assoc_opt candidate type_env = Some sort ->
              definition_parameter_binders := rest;
              candidate
          | _ ->
              match preferred_formula_binder_name sort body with
              | Some name
                  when not (List.mem name used)
                       && List.assoc_opt name type_env = Some sort ->
                  megalodon_ident name
              | _ ->
                  begin match
                    type_env
                    |> List.filter
                         (fun (name, known_sort) ->
                            let binder = megalodon_ident name in
                            known_sort = sort
                            && is_vampire_var_name binder
                            && not (List.mem binder used)
                            && tm_contains_symbol binder body)
                  with
                  | (name, _) :: _ -> megalodon_ident name
                  | [] ->
                      begin match max_vampire_var_name body with
                      | Some name when not (List.mem (megalodon_ident name) used) ->
                          megalodon_ident name
                      | _ -> "Xpred_def_" ^ string_of_int (List.length used)
                      end
                  end
        in
        let env = (binder, sort) :: env in
        let body_proof = collect_binders env (binder :: used) body in
        Printf.sprintf
          "(fun %s:%s => %s)"
          binder (simple_binder_sort_expr sort) body_proof
    | Ap (Ap (TmH "vampire_or", left), right) ->
        let is_negated_definiendum = function
          | Imp (candidate_atom, false_tm) when is_vampire_false false_tm ->
              candidate_atom = atom
          | _ -> false
        in
        let body_side, neg_side, body_is_left =
          if is_negated_definiendum left && right = body then
            (right, left, false)
          else if is_negated_definiendum right && left = body then
            (left, right, true)
          else
            emit_error
              (id ^ ": predicate definition proof expected a definitional disjunction")
        in
        let target_text =
          simple_formula_prop_text_with_used used env (Ap (Ap (TmH "vampire_or", left), right))
        in
        let body_text = simple_formula_prop_text_with_used used env body_side in
        let atom_text = simple_formula_prop_text_with_used used env atom in
        let atom_to_body proof_name =
          match equality_sides atom with
          | Some (TmH h, _) when h = "f__true" ->
              Printf.sprintf "(vampire_fool_true_eq_to_prop (%s) %s)" body_text proof_name
          | Some (_, TmH h) when h = "f__true" ->
              Printf.sprintf "(vampire_fool_eq_true_to_prop (%s) %s)" body_text proof_name
          | Some (TmH h, _) when h = "vampire_true" ->
              Printf.sprintf "(vampire_fool_true_eq_to_prop (%s) %s)" body_text proof_name
          | Some (_, TmH h) when h = "vampire_true" ->
              Printf.sprintf "(vampire_fool_eq_true_to_prop (%s) %s)" body_text proof_name
          | _ -> proof_name
        in
        let body_name = "Hpredicate_definition_body" in
        let not_name = "Hpredicate_definition_not" in
        let eq_name = "Hpredicate_definition_eq" in
        let neg_proof =
          Printf.sprintf
            "(fun %s:(%s) => %s (%s))"
            eq_name atom_text not_name (atom_to_body eq_name)
        in
        let left_intro proof =
          Printf.sprintf
            "(fun vpred_def_goal:prop => fun Hleft:(%s) -> vpred_def_goal => fun Hright:(%s) -> vpred_def_goal => Hleft %s)"
            (simple_formula_prop_text_with_used used env left)
            (simple_formula_prop_text_with_used used env right)
            proof
        in
        let right_intro proof =
          Printf.sprintf
            "(fun vpred_def_goal:prop => fun Hleft:(%s) -> vpred_def_goal => fun Hright:(%s) -> vpred_def_goal => Hright %s)"
            (simple_formula_prop_text_with_used used env left)
            (simple_formula_prop_text_with_used used env right)
            proof
        in
        let positive_branch =
          if body_is_left then left_intro body_name else right_intro body_name
        in
        let negative_branch =
          if body_is_left then right_intro neg_proof else left_intro neg_proof
        in
        Printf.sprintf
          "((vampire_xm (%s)) %s (fun %s:(%s) => %s) (fun %s:(%s) -> False => %s))"
          body_text (simple_prop_arg target_text)
          body_name body_text positive_branch
          not_name body_text negative_branch
    | _ ->
        emit_error
          (id ^ ": predicate definition proof supports only universal definitional disjunctions")
  in
  collect_binders type_env [] formula

let simple_predicate_definition_fold_proof type_env id result_sorts source target body atom parent_name =
  let definiendum = predicate_definition_definiendum_term atom in
  let supported_exists_sort = function
    | "set" | "prop" | "set->prop" | "set->set" | "set->set->prop" -> true
    | _ -> false
  in
  let is_exists_head = function
    | TmH ("vampire_exists_prop" | "vampire_exists_set"
          | "vampire_exists_set_prop" | "vampire_exists_set_set"
          | "vampire_exists_set_set_prop") -> true
    | _ -> false
  in
  let rec contains_unsupported_exists = function
    | Ap (exists_head, Lam (tp, body)) when is_exists_head exists_head ->
        let sort = simple_tp_expr tp in
        not (supported_exists_sort sort) || contains_unsupported_exists body
    | Ap (exists_head, _) when is_exists_head exists_head -> true
    | TpAp (tm, _) -> contains_unsupported_exists tm
    | Ap (left, right)
    | Imp (left, right) -> contains_unsupported_exists left || contains_unsupported_exists right
    | Lam (_, body)
    | All (_, body) -> contains_unsupported_exists body
    | DB _ | TmH _ | Prim _ -> false
  in
  if contains_unsupported_exists source
     || contains_unsupported_exists target
     || contains_unsupported_exists body
     || contains_unsupported_exists atom then
    emit_error (id ^ ": predicate-definition fold proof does not yet support this existential context");
  let is_supported_true_left_formula tm =
    simple_tm_sort (result_sorts @ type_env) tm = Some "prop"
  in
  let rec contains_unsupported_formula_shape tm =
    if tm = definiendum then false
    else match tm with
    | All (tp, body)
    | Lam (tp, body) ->
        ignore tp;
        contains_unsupported_formula_shape body
    | Ap (Ap (TmH ("=" | "vampire_eq_prop"), TmH ("f__true" | "vampire_true")), other)
        when not (is_supported_true_left_formula other) ->
        true
    | TpAp (tm, _) -> contains_unsupported_formula_shape tm
    | Ap (left, right)
    | Imp (left, right) ->
        contains_unsupported_formula_shape left || contains_unsupported_formula_shape right
    | DB _ | TmH _ | Prim _ -> false
  in
  if contains_unsupported_formula_shape source
     || contains_unsupported_formula_shape target
     || contains_unsupported_formula_shape body
     || contains_unsupported_formula_shape atom then
    emit_error (id ^ ": predicate-definition fold proof does not yet support this formula shape");
  let binder_index = ref 0 in
  let proof_index = ref 0 in
  let exists_name_for_sort = function
    | "set" -> "vampire_exists_set"
    | "prop" -> "vampire_exists_prop"
    | "set->prop" -> "vampire_exists_set_prop"
    | "set->set" -> "vampire_exists_set_set"
    | "set->set->prop" -> "vampire_exists_set_set_prop"
    | sort -> emit_error (id ^ ": predicate-definition fold has unsupported existential sort " ^ sort)
  in
  let exists_intro_name_for_sort = function
    | "set" -> "vampire_exists_set_intro"
    | "prop" -> "vampire_exists_prop_intro"
    | "set->prop" -> "vampire_exists_set_prop_intro"
    | "set->set" -> "vampire_exists_set_set_intro"
    | "set->set->prop" -> "vampire_exists_set_set_prop_intro"
    | sort -> emit_error (id ^ ": predicate-definition fold has unsupported existential witness sort " ^ sort)
  in
  let fresh prefix =
    let name = prefix ^ string_of_int !proof_index in
    incr proof_index;
    name
  in
  let binder_for_body used sort body =
    let rec find_from index =
      match List.nth_opt result_sorts index with
      | Some (name, known_sort) ->
          let next = index + 1 in
          let binder = megalodon_ident name in
          if known_sort = sort
             && is_vampire_var_name binder
             && not (List.mem binder used)
             && tm_contains_symbol binder body then Some binder
          else find_from next
      | None -> None
    in
    match preferred_formula_binder_name sort body with
    | Some name
        when not (List.mem name used)
             && List.assoc_opt name (result_sorts @ type_env) = Some sort ->
        megalodon_ident name
    | _ ->
    match find_from !binder_index with
    | Some binder ->
        let rec binder_result_index index = function
          | [] -> None
          | (name, _) :: rest ->
              if megalodon_ident name = binder then Some index
              else binder_result_index (index + 1) rest
        in
        begin match binder_result_index 0 result_sorts with
        | Some index -> binder_index := max !binder_index (index + 1)
        | None -> ()
        end;
        binder
    | None ->
        begin match first_unused_vampire_var_name_with_sort (result_sorts @ type_env) used sort body with
        | Some name -> megalodon_ident name
        | None ->
        begin match first_unused_vampire_var_name used body with
        | Some name when
            let binder = megalodon_ident name in
            not (List.mem binder used)
            &&
            (match List.assoc_opt binder (result_sorts @ type_env) with
             | Some known_sort -> known_sort = sort
             | None -> true) ->
            megalodon_ident name
        | _ ->
            let name = "Xpredicate_fold_" ^ string_of_int !binder_index in
            incr binder_index;
            name
        end
        end
  in
  let rec formula_text env tm =
    let render_env = env @ type_env in
    match tm with
    | All (tp, body) ->
        let sort = simple_tp_expr tp in
        let binder = binder_for_body (List.map fst env) sort body in
        "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_text ((binder, sort) :: env) body)
    | Imp (left, right) ->
        "((" ^ formula_text env left ^ ") -> (" ^ formula_text env right ^ "))"
    | Ap (Ap (TmH "vampire_and", left), right) ->
        "vampire_and (" ^ formula_text env left ^ ") (" ^ formula_text env right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
        "vampire_or (" ^ formula_text env left ^ ") (" ^ formula_text env right ^ ")"
    | Ap (exists_head, Lam (tp, exists_body)) when is_exists_head exists_head ->
        let sort = simple_tp_expr tp in
        let binder = binder_for_body (List.map fst env) sort exists_body in
        exists_name_for_sort sort ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_text ((binder, sort) :: env) exists_body)
        ^ ")"
    | atom ->
        begin match equality_sides atom with
        | Some _ -> simple_atom_prop_with_type_env render_env atom
        | None -> simple_tm_expr_with_expected render_env (Some "prop") atom
        end
  in
  let atom_replacement_proof env proof target_atom =
    if target_atom = definiendum then proof
    else
      try
        match equality_sides target_atom with
        | Some (left, right) when simple_bool_true_tm left && right = definiendum ->
            let body_text = formula_text env body in
            Printf.sprintf "(vampire_fool_prop_to_true_eq (%s) %s)" body_text proof
        | Some (left, right) when left = definiendum && simple_bool_true_tm right ->
            let body_text = formula_text env body in
            Printf.sprintf "(vampire_fool_prop_to_eq_true (%s) %s)" body_text proof
        | _ ->
            simple_fool_atom_forward_proof (env @ type_env) definiendum target_atom proof
      with Error msg ->
        emit_error (id ^ ": predicate-definition fold replacement is unsupported: " ^ msg)
  in
  let rec convert env source target proof =
    if source = target then proof
    else if source = body then atom_replacement_proof env proof target
    else
      match source, target with
      | All (source_tp, source_body), All (target_tp, target_body) when source_tp = target_tp ->
          let sort = simple_tp_expr source_tp in
          let binder = binder_for_body (List.map fst env) sort target_body in
          let env = (binder, sort) :: env in
          let body_proof = convert env source_body target_body ("(" ^ proof ^ " " ^ binder ^ ")") in
          "(fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => " ^ body_proof ^ ")"
      | Imp (source_left, source_right), Imp (target_left, target_right)
          when source_left = target_left ->
          let arg = fresh "Hpredicate_fold_imp_" in
          let right_proof = convert env source_right target_right ("(" ^ proof ^ " " ^ arg ^ ")") in
          "(fun " ^ arg ^ ":(" ^ formula_text env target_left ^ ") => " ^ right_proof ^ ")"
      | Ap (Ap (TmH "vampire_or", source_left), source_right),
        Ap (Ap (TmH "vampire_or", target_left), target_right) ->
          let goal = fresh "Hpredicate_fold_or_goal_" in
          let left_name = fresh "Hpredicate_fold_or_left_" in
          let right_name = fresh "Hpredicate_fold_or_right_" in
          let source_left_text = formula_text env source_left in
          let source_right_text = formula_text env source_right in
          let target_left_text = formula_text env target_left in
          let target_right_text = formula_text env target_right in
          let target_text = formula_text env target in
          let left_proof = convert env source_left target_left left_name in
          let right_proof = convert env source_right target_right right_name in
          let left_intro =
            Printf.sprintf
              "(fun %s:prop => fun Hleft:(%s) -> %s => fun Hright:(%s) -> %s => Hleft %s)"
              goal target_left_text goal target_right_text goal left_proof
          in
          let right_intro =
            Printf.sprintf
              "(fun %s:prop => fun Hleft:(%s) -> %s => fun Hright:(%s) -> %s => Hright %s)"
              goal target_left_text goal target_right_text goal right_proof
          in
          Printf.sprintf
            "(%s %s (fun %s:%s => %s) (fun %s:%s => %s))"
            proof (simple_prop_arg target_text)
            left_name source_left_text left_intro
            right_name source_right_text right_intro
      | Ap (Ap (TmH "vampire_and", source_left), source_right),
        Ap (Ap (TmH "vampire_and", target_left), target_right) ->
          let goal = fresh "Hpredicate_fold_and_goal_" in
          let and_name = fresh "Hpredicate_fold_and_" in
          let left_name = fresh "Hpredicate_fold_and_left_" in
          let right_name = fresh "Hpredicate_fold_and_right_" in
          let source_left_text = formula_text env source_left in
          let source_right_text = formula_text env source_right in
          let target_left_text = formula_text env target_left in
          let target_right_text = formula_text env target_right in
          let left_proof = convert env source_left target_left left_name in
          let right_proof = convert env source_right target_right right_name in
          Printf.sprintf
            "(fun %s:prop => fun %s:(%s) -> (%s) -> %s => %s %s (fun %s:(%s) => fun %s:(%s) => %s %s %s))"
            goal and_name target_left_text target_right_text goal
            proof goal left_name source_left_text right_name source_right_text
            and_name left_proof right_proof
      | Ap (source_exists, Lam (source_tp, source_body)),
        Ap (target_exists, Lam (target_tp, target_body))
          when source_tp = target_tp && is_exists_head source_exists && is_exists_head target_exists ->
          let sort = simple_tp_expr source_tp in
          let binder = binder_for_body (List.map fst env) sort target_body in
          let env = (binder, sort) :: env in
          let source_body_text = formula_text env source_body in
          let target_body_text = formula_text env target_body in
          let body_name = fresh "Hpredicate_fold_exists_body_" in
          let body_proof = convert env source_body target_body body_name in
          let target_text = formula_text (List.tl env) target in
          Printf.sprintf
            "(%s %s (fun %s:%s => fun %s:(%s) => (%s (fun %s:%s => %s) %s %s)))"
            proof (simple_prop_arg target_text)
            binder (simple_binder_sort_expr sort)
            body_name source_body_text
            (exists_intro_name_for_sort sort)
            binder (simple_binder_sort_expr sort)
            target_body_text binder body_proof
      | _ ->
          emit_error (id ^ ": predicate-definition fold proof does not support this formula context")
  in
  convert [] source target parent_name

let simple_ennf_formula_proof type_env id parent_sorts result_sorts source target parent_name =
  let binder_sorts =
    parent_sorts @ result_sorts |> simple_unique_variable_sorts
  in
  let binder_index = ref 0 in
  let proof_var_index = ref 0 in
  let fresh_proof_var prefix =
    let name = prefix ^ string_of_int !proof_var_index in
    incr proof_var_index;
    name
  in
  let fallback_binder sort =
    let name =
      match List.nth_opt binder_sorts !binder_index with
      | Some (name, _) ->
          incr binder_index;
          megalodon_ident name
      | None ->
          let name = "Xennf_" ^ string_of_int !binder_index in
          incr binder_index;
          name
    in
    ignore sort;
    name
  in
  let binder_for_body env sort body =
    let used = List.map fst env in
    let preferred =
      match preferred_formula_binder_name sort body with
      | Some name ->
          let binder = megalodon_ident name in
          if is_vampire_var_name binder
             && not (List.mem binder used)
             && tm_contains_symbol binder body then
            Some binder
          else None
      | None -> None
    in
    let use_preferred preferred =
      let rec find_index i =
        match List.nth_opt binder_sorts i with
        | Some (name, known_sort) ->
            let binder = megalodon_ident name in
            if binder = preferred && known_sort = sort then Some i
            else find_index (i + 1)
        | None -> None
      in
      begin match find_index !binder_index with
      | Some i -> binder_index := i + 1
      | None -> ()
      end;
      preferred
    in
    let rec find_from i =
      match List.nth_opt binder_sorts i with
      | Some (name, known_sort) ->
          let binder = megalodon_ident name in
          if known_sort = sort
             && is_vampire_var_name binder
             && not (List.mem binder used)
             && tm_contains_symbol binder body then begin
            binder_index := i + 1;
            Some binder
          end else
            find_from (i + 1)
      | None -> None
    in
    match find_from !binder_index with
    | Some binder -> binder
    | None ->
    match preferred with
    | Some binder -> use_preferred binder
    | None ->
    match first_unused_vampire_var_name_with_sort
            (env @ binder_sorts @ type_env) used sort body with
    | Some name -> use_preferred (megalodon_ident name)
    | None ->
        let candidates =
          binder_sorts
          |> List.filter
               (fun (name, known_sort) ->
	                  let binder = megalodon_ident name in
	                  known_sort = sort
	                  && is_vampire_var_name binder
	                  && not (List.mem binder used)
	                  && tm_contains_symbol binder body)
        in
        match List.rev candidates with
        | (name, _) :: _ -> megalodon_ident name
        | [] -> fallback_binder sort
  in
  let is_exists_head = function
    | TmH ("vampire_exists_prop" | "vampire_exists_set"
          | "vampire_exists_set_prop" | "vampire_exists_set_set"
          | "vampire_exists_set_set_prop") -> true
    | _ -> false
  in
  let exists_name_for_sort = function
    | "set" -> "vampire_exists_set"
    | "prop" -> "vampire_exists_prop"
    | "set->prop" -> "vampire_exists_set_prop"
    | "set->set" -> "vampire_exists_set_set"
    | "set->set->prop" -> "vampire_exists_set_set_prop"
    | _ -> "vampire_exists_set"
  in
  let exists_intro_name_for_sort sort =
    match sort with
    | "set" -> "vampire_exists_set_intro"
    | "prop" -> "vampire_exists_prop_intro"
    | "set->prop" -> "vampire_exists_set_prop_intro"
    | "set->set" -> "vampire_exists_set_set_intro"
    | "set->set->prop" -> "vampire_exists_set_set_prop_intro"
    | _ -> emit_error (id ^ ": ENNF proof has unsupported existential witness sort " ^ sort)
  in
  let rec formula_text local_env tm =
    let used = List.map fst local_env in
    let render_env = local_env @ type_env in
    let choose_formula_binder sort body =
      let preferred =
        match preferred_formula_binder_name sort body with
        | Some name ->
            let binder = megalodon_ident name in
            if is_vampire_var_name binder
               && not (List.mem binder used)
               && tm_contains_symbol binder body
               &&
               (match List.assoc_opt binder (binder_sorts @ render_env) with
                | Some known_sort -> known_sort = sort
                | None -> true)
            then Some binder
            else None
        | None -> None
      in
      let candidates =
        binder_sorts
        |> List.filter
             (fun (name, known_sort) ->
                let binder = megalodon_ident name in
                known_sort = sort
                && is_vampire_var_name binder
                && not (List.mem binder used))
      in
      match preferred with
      | Some binder -> binder
      | None ->
          match
            List.find_opt
              (fun (name, _) -> tm_contains_symbol (megalodon_ident name) body)
              candidates
          with
          | Some (name, _) -> megalodon_ident name
          | None ->
              begin match candidates with
              | (name, _) :: _ -> megalodon_ident name
              | [] ->
                  begin match first_unused_vampire_var_name used body with
                  | Some name -> megalodon_ident name
                  | None ->
                      let rec fresh i =
                        let candidate = "Xformula_" ^ string_of_int i in
                        if List.mem candidate used then fresh (i + 1) else candidate
                      in
                      fresh (List.length used)
                  end
              end
    in
    match tm with
    | All (tp, body) ->
        let sort = simple_tp_expr tp in
        let binder = choose_formula_binder sort body in
        "forall " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ ", "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_text ((binder, sort) :: local_env) body)
    | Imp (left, right) ->
        "((" ^ formula_text local_env left ^ ") -> (" ^ formula_text local_env right ^ "))"
    | Ap (Ap (TmH "vampire_and", left), right) ->
        "vampire_and (" ^ formula_text local_env left ^ ") (" ^ formula_text local_env right ^ ")"
    | Ap (Ap (TmH "vampire_or", left), right) ->
        "vampire_or (" ^ formula_text local_env left ^ ") (" ^ formula_text local_env right ^ ")"
    | Ap (exists_head, Lam (tp, body)) when is_exists_head exists_head ->
        let sort = simple_tp_expr tp in
        let exists_name = exists_name_for_sort sort in
        let binder = choose_formula_binder sort body in
        exists_name ^ " (fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => "
        ^ simple_with_db_aliases [binder]
            (fun () -> formula_text ((binder, sort) :: local_env) body)
        ^ ")"
    | atom ->
        begin match equality_sides atom with
        | Some _ -> simple_atom_prop_with_type_env render_env atom
        | None -> simple_tm_expr_with_expected render_env (Some "prop") atom
        end
  in
  let rec convert env source target proof =
    match source, target with
    | All (source_tp, source_body), All (target_tp, target_body) when source_tp = target_tp ->
        let sort = simple_tp_expr source_tp in
        let binder = binder_for_body env sort target_body in
        let env = (binder, sort) :: env in
        let body_proof = convert env source_body target_body ("(" ^ proof ^ " " ^ binder ^ ")") in
        "(fun " ^ binder ^ ":" ^ simple_binder_sort_expr sort ^ " => " ^ body_proof ^ ")"
    | _ when source = target -> proof
    | Imp (Imp (left, right), false_tm),
      Ap (Ap (TmH "vampire_and", target_left), target_right)
        when is_vampire_false false_tm ->
        if target_left <> ennf_pos left || target_right <> ennf_neg right then
          emit_error (id ^ ": ENNF proof expected negated implication-to-and target");
        let not_left_name = fresh_proof_var "Hennf_not_left_" in
        let source_left_name = fresh_proof_var "Hennf_source_left_" in
        let target_left_name = fresh_proof_var "Hennf_target_left_" in
        let right_name = fresh_proof_var "Hennf_right_" in
        let left_text = formula_text env left in
        let target_left_text = formula_text env target_left in
        let right_text = formula_text env right in
        let target_right_text = formula_text env target_right in
        let target_left_from_source =
          convert env left target_left source_left_name
        in
        let left_proof =
          Printf.sprintf
            "(dneg (%s) (fun %s:(%s) -> False => %s (fun %s:%s => (%s %s) (%s))))"
            target_left_text not_left_name target_left_text proof source_left_name left_text
            not_left_name target_left_from_source right_text
        in
        let not_right_proof =
          Printf.sprintf
            "(fun %s:%s => %s (fun %s:%s => %s))"
            right_name right_text proof target_left_name left_text right_name
        in
        let right_proof =
          convert env (Imp (right, vampire_false)) target_right not_right_proof
        in
        Printf.sprintf
          "(fun Hennf_goal:prop => fun Hennf_and:((%s) -> (%s) -> Hennf_goal) => Hennf_and %s %s)"
          target_left_text target_right_text left_proof right_proof
    | Imp (source_quantified, false_tm), target_exists
        when is_vampire_false false_tm ->
        let rec source_chain acc = function
          | All (tp, body) -> source_chain (EnnfChainBinder tp :: acc) body
          | Imp (left, right) -> source_chain (EnnfChainPremise left :: acc) right
          | conclusion -> (List.rev acc, conclusion)
        in
        let rec match_target_chain env acc items target =
          match items, target with
          | EnnfChainBinder tp :: rest, Ap (exists_head, Lam (target_tp, body))
              when tp = target_tp && is_exists_head exists_head ->
              let sort = simple_tp_expr tp in
              let binder = binder_for_body env sort body in
              match_target_chain
                ((binder, sort) :: env)
                (MatchedEnnfBinder (binder, sort, tp) :: acc)
                rest body
          | EnnfChainPremise premise :: rest, Ap (Ap (TmH "vampire_and", left), right)
              when left = ennf_pos premise ->
              let premise_name = fresh_proof_var "Hennf_premise_" in
              match_target_chain
                env
                (MatchedEnnfPremise (premise, left, premise_name) :: acc)
                rest right
          | [], target_leaf -> (List.rev acc, target_leaf)
          | EnnfChainBinder _ :: _, _ ->
              emit_error (id ^ ": ENNF proof expected an existential for a negated universal binder")
          | EnnfChainPremise premise :: _, Ap (Ap (TmH "vampire_and", left), _) ->
              emit_error
                (id ^ ": ENNF proof target premise does not match positive-normalized source premise: "
                 ^ formula_text env premise ^ " vs " ^ formula_text env left)
          | EnnfChainPremise _ :: _, _ ->
              emit_error (id ^ ": ENNF proof expected a conjunction for a negated implication premise")
        in
        let source_items, source_conclusion = source_chain [] source_quantified in
        if source_items = [] then
          emit_error (id ^ ": ENNF proof expected a non-empty negated chain");
        let matched_items, target_leaf = match_target_chain env [] source_items target_exists in
        let neg_source_conclusion = Imp (source_conclusion, vampire_false) in
        if target_leaf <> ennf_neg source_conclusion then
          emit_error
            (id ^ ": ENNF proof target leaf does not match negative-normalized source conclusion");
        let not_conclusion_name = fresh_proof_var "Hennf_not_conclusion_" in
        let rec target_witness env matched target =
          match matched, target with
          | MatchedEnnfBinder (binder, sort, tp) :: rest,
            Ap (exists_head, Lam (target_tp, body))
              when tp = target_tp && is_exists_head exists_head ->
              let body_env = (binder, sort) :: env in
              let body_text = formula_text body_env body in
              let body_proof = target_witness body_env rest body in
              Printf.sprintf
                "(%s (fun %s:%s => %s) %s %s)"
                (exists_intro_name_for_sort sort)
                binder (simple_binder_sort_expr sort) body_text binder body_proof
          | MatchedEnnfPremise (premise, target_premise, premise_name) :: rest,
            Ap (Ap (TmH "vampire_and", left), right)
              when left = target_premise ->
              let goal_name = fresh_proof_var "Hennf_and_goal_" in
              let and_name = fresh_proof_var "Hennf_and_" in
              let left_text = formula_text env left in
              let right_text = formula_text env right in
              let left_proof = convert env premise target_premise premise_name in
              let right_proof = target_witness env rest right in
              Printf.sprintf
                "(fun %s:prop => fun %s:((%s) -> (%s) -> %s) => %s %s %s)"
                goal_name and_name left_text right_text goal_name
                and_name left_proof right_proof
          | [], _ ->
              convert env neg_source_conclusion target not_conclusion_name
          | _ ->
              emit_error (id ^ ": ENNF proof could not build target witness")
        in
        let witness_text = target_witness env matched_items target_exists in
        let rec source_argument env matched body =
          match matched with
          | [] -> body
          | MatchedEnnfBinder (binder, sort, _) :: rest ->
              Printf.sprintf
                "fun %s:%s => %s"
                binder (simple_binder_sort_expr sort)
                (source_argument ((binder, sort) :: env) rest body)
          | MatchedEnnfPremise (premise, _, premise_name) :: rest ->
              Printf.sprintf
                "fun %s:%s => %s"
                premise_name (formula_text env premise)
                (source_argument env rest body)
        in
        let conclusion_env =
          List.fold_left
            (fun env -> function
               | MatchedEnnfBinder (binder, sort, _) -> (binder, sort) :: env
               | MatchedEnnfPremise _ -> env)
            env matched_items
        in
        let conclusion_text = formula_text conclusion_env source_conclusion in
        let rec formula_text_with_binders local_env preferred tm =
          match preferred, tm with
          | (preferred_binder, preferred_sort) :: rest,
            Ap (exists_head, Lam (tp, body))
              when simple_tp_expr tp = preferred_sort && is_exists_head exists_head ->
              exists_name_for_sort preferred_sort
              ^ " (fun " ^ preferred_binder ^ ":" ^ simple_binder_sort_expr preferred_sort ^ " => "
              ^ simple_with_db_aliases [preferred_binder]
                  (fun () ->
                     formula_text_with_binders
                       ((preferred_binder, preferred_sort) :: local_env)
                       rest
                       body)
              ^ ")"
          | _ -> formula_text local_env tm
        in
        let matched_binders =
          matched_items
          |> List.filter_map
               (function
                 | MatchedEnnfBinder (binder, sort, _) -> Some (binder, sort)
                 | MatchedEnnfPremise _ -> None)
        in
        let contradiction_for target_contradiction =
          let body =
            Printf.sprintf
              "dneg (%s) (fun %s:(%s) -> False => %s)"
              conclusion_text not_conclusion_name conclusion_text target_contradiction
          in
          Printf.sprintf "%s (%s)" proof (source_argument env matched_items body)
        in
        begin match target_exists with
        | Ap (exists_head, Lam (_, body)) when is_exists_head exists_head ->
            begin match matched_binders with
            | (binder, sort) :: rest_binders ->
                let body_text =
                  simple_with_db_aliases [binder]
                    (fun () ->
                       formula_text_with_binders
                         ((binder, sort) :: env)
                         rest_binders
                         body)
                in
                let case_type =
                  Printf.sprintf
                    "(forall %s:%s, %s -> Hennf_exists_goal)"
                    binder (simple_binder_sort_expr sort) body_text
                in
                let target_contradiction =
                  Printf.sprintf
                    "Hennf_not_goal ((%s Hennf_exists_goal) Hennf_exists_case)"
                    witness_text
                in
                Printf.sprintf
                  "(fun Hennf_exists_goal:prop => fun Hennf_exists_case:%s => dneg Hennf_exists_goal (fun Hennf_not_goal:Hennf_exists_goal -> False => %s))"
                  case_type (contradiction_for target_contradiction)
            | [] ->
                emit_error (id ^ ": ENNF proof expected a matched existential binder")
            end
        | _ ->
            let target_text = formula_text env target_exists in
            let target_contradiction =
              Printf.sprintf "Hennf_not_goal %s" witness_text
            in
            Printf.sprintf
              "dneg (%s) (fun Hennf_not_goal:(%s) -> False => %s)"
              target_text target_text (contradiction_for target_contradiction)
        end
    | Imp (left, right), Ap (Ap (TmH "vampire_or", neg_left), target_right) ->
        if neg_left = ennf_neg left then
          let pos_name = fresh_proof_var "Hennf_pos_" in
          let neg_name = fresh_proof_var "Hennf_neg_" in
          let left_text = formula_text env left in
          let target_text = formula_text env target in
          let target_left_text = formula_text env neg_left in
          let target_right_text = formula_text env target_right in
          let left_proof =
            convert env (Imp (left, vampire_false)) neg_left neg_name
          in
          let right_proof =
            convert env right target_right ("(" ^ proof ^ " " ^ pos_name ^ ")")
          in
          let left_intro =
            Printf.sprintf
              "(fun vennf_goal:prop => fun Hleft:%s -> vennf_goal => fun Hright:(%s) -> vennf_goal => Hleft %s)"
              target_left_text target_right_text left_proof
          in
          let right_intro =
            Printf.sprintf
              "(fun vennf_goal:prop => fun Hleft:%s -> vennf_goal => fun Hright:(%s) -> vennf_goal => Hright %s)"
              target_left_text target_right_text right_proof
          in
          Printf.sprintf
            "((vampire_xm (%s)) %s (fun %s:(%s) => %s) (fun %s:(%s) -> False => %s))"
            left_text (simple_prop_arg target_text)
            pos_name left_text right_intro
            neg_name left_text left_intro
        else begin match neg_left with
        | Imp (neg_source, false_tm) when neg_source = left && is_vampire_false false_tm ->
            let pos_name = fresh_proof_var "Hennf_pos_" in
            let neg_name = fresh_proof_var "Hennf_neg_" in
            let left_text = formula_text env left in
            let target_text = formula_text env target in
            let neg_left_text = formula_text env neg_left in
            let target_right_text = formula_text env target_right in
            let right_proof = convert env right target_right ("(" ^ proof ^ " " ^ pos_name ^ ")") in
            let left_intro =
              Printf.sprintf
                "(fun vennf_goal:prop => fun Hleft:%s -> vennf_goal => fun Hright:(%s) -> vennf_goal => Hleft %s)"
                neg_left_text target_right_text neg_name
            in
            let right_intro =
              Printf.sprintf
                "(fun vennf_goal:prop => fun Hleft:%s -> vennf_goal => fun Hright:(%s) -> vennf_goal => Hright %s)"
                neg_left_text target_right_text right_proof
            in
            Printf.sprintf
              "((vampire_xm (%s)) %s (fun %s:(%s) => %s) (fun %s:(%s) -> False => %s))"
              left_text (simple_prop_arg target_text)
              pos_name left_text right_intro
              neg_name left_text left_intro
        | _ ->
            let pos_name = fresh_proof_var "Hennf_pos_" in
            let neg_name = fresh_proof_var "Hennf_neg_" in
            let left_text = formula_text env left in
            let right_text = formula_text env right in
            let target_text = formula_text env target in
            let target_left_text = formula_text env neg_left in
            let target_right_text = formula_text env target_right in
            let right_proof = convert env right target_right pos_name in
            let source_left_name = fresh_proof_var "Hennf_source_left_" in
            let neg_left_source_proof =
              Printf.sprintf
                "(fun %s:%s => %s (%s %s))"
                source_left_name left_text neg_name proof source_left_name
            in
            let left_proof =
              convert env (Imp (left, vampire_false)) neg_left neg_left_source_proof
            in
            let left_intro =
              Printf.sprintf
                "(fun vennf_goal:prop => fun Hleft:%s -> vennf_goal => fun Hright:(%s) -> vennf_goal => Hleft %s)"
                target_left_text target_right_text left_proof
            in
            let right_intro =
              Printf.sprintf
                "(fun vennf_goal:prop => fun Hleft:%s -> vennf_goal => fun Hright:(%s) -> vennf_goal => Hright %s)"
                target_left_text target_right_text right_proof
            in
            Printf.sprintf
              "((vampire_xm (%s)) %s (fun %s:(%s) => %s) (fun %s:(%s) -> False => %s))"
              right_text (simple_prop_arg target_text)
              pos_name right_text right_intro
              neg_name right_text left_intro
        end
    | _ ->
        emit_error (id ^ ": ENNF proof supports only universal implication-to-or transformations")
  in
  convert [] source target parent_name

